class TempleApp extends StatelessWidget {
  const TempleApp({super.key});

  @override
  Widget build(BuildContext context) {
    // Al cambiar de tema la app se vuelve a montar con otra llave (60).
    return ListenableBuilder(
      listenable: TemaTemplo.instancia,
      builder: (BuildContext context, _) => MaterialApp(
        key: ValueKey<int>(TemaTemplo.instancia.version),
        title: 'Temple of Strength',
        debugShowCheckedModeBanner: false,
        theme: TemaTemplo.instancia.temaMaterial(),
        scrollBehavior: const DesplazamientoTemplo(),
        // En la web, en pantallas anchas, la app va en una ventana grande (58.4).
        builder: (BuildContext context, Widget? child) => MarcoWeb(child: child ?? const SizedBox.shrink()),
        home: const PuertaTemplo(),
      ),
    );
  }
}

// ===========================================================================
// 3. GLIFOS VECTORIALES
//
// Todos se dibujan sobre una caja normalizada de 24×24 y luego se escalan, así
// comparten peso óptico a cualquier tamaño.
// ===========================================================================

enum TempleGlyph {
  // Navegación
  torii,
  casa,
  kitsune,
  clan,
  espadas,
  // Energía — redibujados como piezas propias, no iconos genéricos
  rayo,
  mancuerna,
  montana,
  luna,
  gota,
  // Accesorios
  llama,
  cuenco,
  loto,
  bandera,
  chispa,
  medalla,
  reloj,
  lista,
  campana,
}

class TempleIcon extends StatelessWidget {
  const TempleIcon(
    this.glifo, {
    super.key,
    this.size = 24,
    required this.color,
    this.trazo = 1.7,
  });

  final TempleGlyph glifo;
  final double size;
  final Color color;
  final double trazo;

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: size,
      height: size,
      child: CustomPaint(
        painter: _GlifoPainter(glifo: glifo, color: color, trazo: trazo),
      ),
    );
  }
}

class _GlifoPainter extends CustomPainter {
  const _GlifoPainter({
    required this.glifo,
    required this.color,
    required this.trazo,
  });

  final TempleGlyph glifo;
  final Color color;
  final double trazo;

  @override
  void paint(Canvas canvas, Size size) {
    canvas.save();
    canvas.scale(size.shortestSide / 24);

    final Paint t = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = trazo
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..isAntiAlias = true;

    final Paint f = Paint()
      ..color = color
      ..style = PaintingStyle.fill
      ..isAntiAlias = true;

    final TempleGlyph g = glifo;

    // -- Navegación ---------------------------------------------------------
    if (g == TempleGlyph.torii) {
      canvas.drawPath(
        Path()
          ..moveTo(2.4, 6.6)
          ..quadraticBezierTo(12, 3.6, 21.6, 6.6),
        t,
      );
      canvas.drawLine(const Offset(4.2, 8.4), const Offset(19.8, 8.4), t);
      canvas.drawLine(const Offset(5.9, 12.1), const Offset(18.1, 12.1), t);
      canvas.drawLine(const Offset(12, 8.4), const Offset(12, 12.1), t);
      canvas.drawLine(const Offset(7, 8.4), const Offset(8, 20.8), t);
      canvas.drawLine(const Offset(17, 8.4), const Offset(16, 20.8), t);
    } else if (g == TempleGlyph.casa) {
      canvas.drawPath(
        Path()
          ..moveTo(2.2, 10.6)
          ..cubicTo(5.4, 9.4, 8.6, 4.6, 12, 3.4)
          ..cubicTo(15.4, 4.6, 18.6, 9.4, 21.8, 10.6),
        t,
      );
      canvas.drawLine(const Offset(5.6, 11.4), const Offset(5.6, 20.6), t);
      canvas.drawLine(const Offset(18.4, 11.4), const Offset(18.4, 20.6), t);
      canvas.drawLine(const Offset(5.6, 20.6), const Offset(18.4, 20.6), t);
      canvas.drawPath(
        Path()
          ..moveTo(9.9, 20.6)
          ..lineTo(9.9, 14.9)
          ..lineTo(14.1, 14.9)
          ..lineTo(14.1, 20.6),
        t,
      );
    } else if (g == TempleGlyph.kitsune) {
      canvas.drawPath(
        Path()
          ..moveTo(3.5, 3.9)
          ..lineTo(7.4, 8.2)
          ..cubicTo(9.6, 7.3, 14.4, 7.3, 16.6, 8.2)
          ..lineTo(20.5, 3.9)
          ..lineTo(19.7, 10.6)
          ..cubicTo(20.3, 15.6, 16.2, 20.4, 12, 21.0)
          ..cubicTo(7.8, 20.4, 3.7, 15.6, 4.3, 10.6)
          ..close(),
        t,
      );
      canvas.drawLine(const Offset(8.2, 12.2), const Offset(10.6, 13.4), t);
      canvas.drawLine(const Offset(15.8, 12.2), const Offset(13.4, 13.4), t);
    } else if (g == TempleGlyph.clan) {
      canvas.drawCircle(const Offset(16.2, 8.4), 2.5, t);
      canvas.drawPath(
        Path()
          ..moveTo(13.6, 18.6)
          ..cubicTo(14.2, 14.6, 18.6, 14.0, 21.0, 17.0)
          ..lineTo(21.0, 18.6),
        t,
      );
      canvas.drawCircle(const Offset(9.2, 9.4), 3.2, t);
      canvas.drawPath(
        Path()
          ..moveTo(3.2, 20.4)
          ..cubicTo(3.6, 15.6, 14.8, 15.6, 15.2, 20.4),
        t,
      );
    } else if (g == TempleGlyph.espadas) {
      canvas.drawLine(const Offset(4.6, 20.2), const Offset(19.2, 4.6), t);
      canvas.drawLine(const Offset(19.4, 20.2), const Offset(4.8, 4.6), t);
      canvas.drawLine(const Offset(6.1, 15.4), const Offset(9.4, 18.6), t);
      canvas.drawLine(const Offset(17.9, 15.4), const Offset(14.6, 18.6), t);
    }
    // -- Energía ------------------------------------------------------------
    // Rayo: un solo polígono macizo. Sin contorno, para que a 17 px lea como
    // una forma y no como un garabato.
    else if (g == TempleGlyph.rayo) {
      canvas.drawPath(
        Path()
          ..moveTo(13.9, 2.0)
          ..lineTo(6.0, 13.6)
          ..lineTo(10.7, 13.6)
          ..lineTo(9.9, 22.0)
          ..lineTo(18.0, 10.3)
          ..lineTo(13.2, 10.3)
          ..close(),
        f,
      );
    }
    // Mancuerna: barra, discos y topes simétricos sobre el eje Y=12.
    else if (g == TempleGlyph.mancuerna) {
      canvas.drawLine(const Offset(9.0, 12), const Offset(15.0, 12), t);
      canvas.drawLine(const Offset(7.6, 8.2), const Offset(7.6, 15.8), t);
      canvas.drawLine(const Offset(16.4, 8.2), const Offset(16.4, 15.8), t);
      canvas.drawLine(const Offset(4.9, 9.8), const Offset(4.9, 14.2), t);
      canvas.drawLine(const Offset(19.1, 9.8), const Offset(19.1, 14.2), t);
      final Paint fino = Paint()
        ..color = color
        ..style = PaintingStyle.stroke
        ..strokeWidth = trazo * 0.85
        ..strokeCap = StrokeCap.round;
      canvas.drawLine(const Offset(2.6, 10.9), const Offset(2.6, 13.1), fino);
      canvas.drawLine(const Offset(21.4, 10.9), const Offset(21.4, 13.1), fino);
    }
    // Montaña: cono del Fuji con la nieve dentada en la cumbre.
    else if (g == TempleGlyph.montana) {
      canvas.drawPath(
        Path()
          ..moveTo(2.0, 19.6)
          ..cubicTo(5.2, 19.2, 6.6, 4.8, 12.0, 4.8)
          ..cubicTo(17.4, 4.8, 18.8, 19.2, 22.0, 19.6)
          ..close(),
        t,
      );
      final Paint nieve = Paint()
        ..color = color
        ..style = PaintingStyle.stroke
        ..strokeWidth = trazo * 0.85
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round;
      canvas.drawPath(
        Path()
          ..moveTo(8.6, 9.6)
          ..lineTo(10.1, 8.0)
          ..lineTo(11.4, 9.4)
          ..lineTo(12.8, 7.9)
          ..lineTo(14.1, 9.5)
          ..lineTo(15.5, 8.4),
        nieve,
      );
    }
    // Luna: la misma creciente de la marca, resuelta como diferencia de dos
    // círculos para que el filo interior quede limpio.
    else if (g == TempleGlyph.luna) {
      final Path exterior = Path()
        ..addOval(Rect.fromCircle(center: const Offset(12, 12.4), radius: 8.9));
      final Path recorte = Path()
        ..addOval(Rect.fromCircle(center: const Offset(16.8, 7.2), radius: 8.4));
      canvas.drawPath(
        Path.combine(PathOperation.difference, exterior, recorte),
        f,
      );
    }
    // Gota.
    else if (g == TempleGlyph.gota) {
      canvas.drawPath(
        Path()
          ..moveTo(12, 2.6)
          ..cubicTo(12, 2.6, 5.4, 9.8, 5.4, 14.4)
          ..cubicTo(5.4, 18.0, 8.4, 21.0, 12, 21.0)
          ..cubicTo(15.6, 21.0, 18.6, 18.0, 18.6, 14.4)
          ..cubicTo(18.6, 9.8, 12, 2.6, 12, 2.6)
          ..close(),
        t,
      );
      canvas.drawPath(
        Path()
          ..moveTo(9.0, 15.4)
          ..cubicTo(9.0, 17.1, 10.3, 18.4, 12.0, 18.4),
        Paint()
          ..color = color.withValues(alpha: 0.55)
          ..style = PaintingStyle.stroke
          ..strokeWidth = trazo * 0.8
          ..strokeCap = StrokeCap.round,
      );
    }
    // -- Accesorios ---------------------------------------------------------
    else if (g == TempleGlyph.llama) {
      canvas.drawPath(
        Path()
          ..moveTo(12, 2.4)
          ..cubicTo(16.6, 6.6, 18.4, 9.8, 18.4, 13.6)
          ..cubicTo(18.4, 17.8, 15.5, 21.2, 12, 21.2)
          ..cubicTo(8.5, 21.2, 5.6, 17.8, 5.6, 13.6)
          ..cubicTo(5.6, 10.6, 6.8, 8.6, 8.4, 7.0)
          ..cubicTo(8.6, 9.4, 9.4, 10.8, 10.6, 11.6)
          ..cubicTo(10.1, 7.6, 10.6, 5.0, 12, 2.4)
          ..close(),
        f,
      );
    } else if (g == TempleGlyph.cuenco) {
      canvas.drawPath(
        Path()
          ..moveTo(3.4, 11.6)
          ..cubicTo(3.4, 16.6, 7.2, 20.2, 12, 20.2)
          ..cubicTo(16.8, 20.2, 20.6, 16.6, 20.6, 11.6)
          ..close(),
        t,
      );
      canvas.drawLine(const Offset(2.2, 11.6), const Offset(21.8, 11.6), t);
      final Paint vapor = Paint()
        ..color = color.withValues(alpha: 0.6)
        ..style = PaintingStyle.stroke
        ..strokeWidth = trazo * 0.8
        ..strokeCap = StrokeCap.round;
      canvas.drawPath(
        Path()
          ..moveTo(9.4, 8.2)
          ..cubicTo(8.4, 6.8, 10.4, 5.6, 9.4, 4.0),
        vapor,
      );
      canvas.drawPath(
        Path()
          ..moveTo(14.6, 8.2)
          ..cubicTo(13.6, 6.8, 15.6, 5.6, 14.6, 4.0),
        vapor,
      );
    } else if (g == TempleGlyph.loto) {
      canvas.drawPath(
        Path()
          ..moveTo(12, 4.0)
          ..cubicTo(14.6, 7.0, 15.6, 10.0, 15.2, 13.4)
          ..cubicTo(13.9, 14.6, 10.1, 14.6, 8.8, 13.4)
          ..cubicTo(8.4, 10.0, 9.4, 7.0, 12, 4.0)
          ..close(),
        t,
      );
      canvas.drawPath(
        Path()
          ..moveTo(3.0, 12.4)
          ..cubicTo(6.6, 12.0, 9.6, 13.6, 12, 17.2)
          ..cubicTo(14.4, 13.6, 17.4, 12.0, 21.0, 12.4)
          ..cubicTo(20.4, 17.4, 16.6, 20.4, 12, 20.4)
          ..cubicTo(7.4, 20.4, 3.6, 17.4, 3.0, 12.4)
          ..close(),
        t,
      );
    } else if (g == TempleGlyph.bandera) {
      canvas.drawLine(const Offset(5.2, 21.4), const Offset(5.2, 3.2), t);
      canvas.drawPath(
        Path()
          ..moveTo(5.2, 4.4)
          ..lineTo(18.4, 4.4)
          ..lineTo(15.4, 8.8)
          ..lineTo(18.4, 13.2)
          ..lineTo(5.2, 13.2),
        t,
      );
    } else if (g == TempleGlyph.chispa) {
      canvas.drawPath(
        Path()
          ..moveTo(12, 2.6)
          ..cubicTo(12.9, 7.2, 14.6, 9.0, 19.2, 10.0)
          ..cubicTo(14.6, 11.0, 12.9, 12.8, 12, 17.4)
          ..cubicTo(11.1, 12.8, 9.4, 11.0, 4.8, 10.0)
          ..cubicTo(9.4, 9.0, 11.1, 7.2, 12, 2.6)
          ..close(),
        f,
      );
      canvas.drawPath(
        Path()
          ..moveTo(17.6, 15.4)
          ..cubicTo(17.9, 17.4, 18.6, 18.1, 20.6, 18.4)
          ..cubicTo(18.6, 18.7, 17.9, 19.4, 17.6, 21.4)
          ..cubicTo(17.3, 19.4, 16.6, 18.7, 14.6, 18.4)
          ..cubicTo(16.6, 18.1, 17.3, 17.4, 17.6, 15.4)
          ..close(),
        f,
      );
    } else if (g == TempleGlyph.medalla) {
      canvas.drawCircle(const Offset(12, 9.2), 5.4, t);
      canvas.drawPath(
        Path()
          ..moveTo(8.6, 13.6)
          ..lineTo(7.0, 21.4)
          ..lineTo(12.0, 18.6)
          ..lineTo(17.0, 21.4)
          ..lineTo(15.4, 13.6),
        t,
      );
    } else if (g == TempleGlyph.reloj) {
      canvas.drawCircle(const Offset(12, 12), 8.8, t);
      canvas.drawPath(
        Path()
          ..moveTo(12, 6.8)
          ..lineTo(12, 12.4)
          ..lineTo(15.6, 14.6),
        t,
      );
    } else if (g == TempleGlyph.lista) {
      for (int i = 0; i < 3; i++) {
        final double y = 6.6 + i * 5.4;
        canvas.drawLine(Offset(9.0, y), Offset(20.0, y), t);
        canvas.drawCircle(Offset(4.6, y), 1.0, f);
      }
    } else if (g == TempleGlyph.campana) {
      canvas.drawPath(
        Path()
          ..moveTo(18.2, 8.4)
          ..cubicTo(18.2, 4.9, 15.4, 2.4, 12.0, 2.4)
          ..cubicTo(8.6, 2.4, 5.8, 4.9, 5.8, 8.4)
          ..cubicTo(5.8, 15.0, 3.2, 16.8, 3.2, 16.8)
          ..lineTo(20.8, 16.8)
          ..cubicTo(20.8, 16.8, 18.2, 15.0, 18.2, 8.4)
          ..close(),
        t,
      );
      canvas.drawPath(
        Path()
          ..moveTo(10.2, 20.0)
          ..cubicTo(10.8, 21.2, 13.2, 21.2, 13.8, 20.0),
        t,
      );
    }

    canvas.restore();
  }

  @override
  bool shouldRepaint(_GlifoPainter old) =>
      old.glifo != glifo || old.color != color || old.trazo != trazo;
}

