class FondoTemplo extends StatelessWidget {
  const FondoTemplo({super.key, this.child});
  final Widget? child;

  @override
  Widget build(BuildContext context) {
    return DecoratedBox(
      decoration: const BoxDecoration(gradient: TempleColors.fondo),
      child: Stack(
        fit: StackFit.expand,
        children: <Widget>[
          const IgnorePointer(child: CustomPaint(painter: _HalosPainter())),
          if (child != null) child!,
        ],
      ),
    );
  }
}

class _HalosPainter extends CustomPainter {
  const _HalosPainter();

  @override
  void paint(Canvas canvas, Size size) {
    void halo(Offset c, double r, double a) {
      canvas.drawCircle(
        c,
        r,
        Paint()
          ..shader = RadialGradient(
            colors: <Color>[
              TempleColors.violeta.withValues(alpha: a),
              Colors.transparent,
            ],
          ).createShader(Rect.fromCircle(center: c, radius: r)),
      );
    }

    halo(Offset(size.width * 0.85, -size.height * 0.02), size.width * 0.7, 0.14);
    halo(Offset(size.width * 0.05, size.height * 0.55), size.width * 0.6, 0.07);
  }

  @override
  bool shouldRepaint(_HalosPainter oldDelegate) => false;
}

class TempleCard extends StatefulWidget {
  const TempleCard({
    super.key,
    required this.child,
    this.onTap,
    this.padding = const EdgeInsets.all(16),
    this.destacada = false,
  });

  final Widget child;
  final VoidCallback? onTap;
  final EdgeInsetsGeometry padding;
  final bool destacada;

  @override
  State<TempleCard> createState() => _TempleCardState();
}

class _TempleCardState extends State<TempleCard> {
  bool _p = false;

  @override
  Widget build(BuildContext context) {
    final Widget sup = AnimatedContainer(
      duration: TempleMotion.rapido,
      curve: TempleMotion.suave,
      padding: widget.padding,
      decoration: BoxDecoration(
        color: _p
            ? TempleColors.superficieAlta
            : TempleColors.superficie.withValues(alpha: 0.92),
        borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
        border: Border.all(
          color: widget.destacada
              ? TempleColors.violeta.withValues(alpha: 0.32)
              : TempleColors.borde,
        ),
        boxShadow: widget.destacada
            ? <BoxShadow>[
                BoxShadow(
                  color: TempleColors.violeta.withValues(alpha: 0.16),
                  blurRadius: 28,
                  spreadRadius: -6,
                  offset: const Offset(0, 8),
                ),
              ]
            : null,
      ),
      child: widget.child,
    );

    if (widget.onTap == null) return sup;

    return GestureDetector(
      onTap: widget.onTap,
      onTapDown: (_) => setState(() => _p = true),
      onTapUp: (_) => setState(() => _p = false),
      onTapCancel: () => setState(() => _p = false),
      child: AnimatedScale(
        duration: TempleMotion.rapido,
        curve: TempleMotion.suave,
        scale: _p ? 0.985 : 1,
        child: Semantics(button: true, child: sup),
      ),
    );
  }
}

