// 5. MARCA: LUNA + TORII
// ===========================================================================

class ToriiMoonLogo extends StatelessWidget {
  const ToriiMoonLogo({super.key, this.size = 138});
  final double size;

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: size,
      height: size,
      child: CustomPaint(painter: _LogoPainter()),
    );
  }
}

class _LogoPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final double s = size.shortestSide;
    final Offset c = size.center(Offset.zero);
    final double r = s * 0.42;

    // Halo.
    canvas.drawCircle(
      c,
      r * 1.9,
      Paint()
        ..shader = RadialGradient(
          colors: <Color>[
            TempleColors.violeta.withValues(alpha: 0.30),
            Colors.transparent,
          ],
        ).createShader(Rect.fromCircle(center: c, radius: r * 1.9)),
    );

    // Creciente fina: diferencia de dos círculos casi concéntricos.
    final Path exterior = Path()
      ..addOval(Rect.fromCircle(center: c, radius: r));
    final Path recorte = Path()
      ..addOval(
        Rect.fromCircle(center: c.translate(r * 0.30, -r * 0.10), radius: r * 0.90),
      );
    canvas.drawPath(
      Path.combine(PathOperation.difference, exterior, recorte),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: const <Color>[
            TempleColors.blancoLuna,
            TempleColors.violetaClaro,
          ],
        ).createShader(Rect.fromCircle(center: c, radius: r)),
    );

    // Torii centrado dentro de la luna.
    final double a = s * 0.30;
    final Paint tinta = Paint()
      ..color = TempleColors.violetaClaro
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeWidth = s * 0.026;

    final double cx = c.dx - s * 0.02;
    final double top = c.dy - a * 0.52;
    final double base = c.dy + a * 0.55;
    final double izq = cx - a * 0.50;
    final double der = cx + a * 0.50;

    canvas.drawPath(
      Path()
        ..moveTo(izq - a * 0.12, top + a * 0.06)
        ..quadraticBezierTo(cx, top - a * 0.10, der + a * 0.12, top + a * 0.06),
      Paint()
        ..color = TempleColors.violetaClaro
        ..style = PaintingStyle.stroke
        ..strokeCap = StrokeCap.round
        ..strokeWidth = s * 0.034,
    );
    canvas.drawLine(
      Offset(izq - a * 0.02, top + a * 0.20),
      Offset(der + a * 0.02, top + a * 0.20),
      tinta,
    );
    canvas.drawLine(
      Offset(izq + a * 0.08, top + a * 0.46),
      Offset(der - a * 0.08, top + a * 0.46),
      tinta,
    );
    canvas.drawLine(
      Offset(izq + a * 0.02, top + a * 0.20),
      Offset(izq + a * 0.10, base),
      tinta,
    );
    canvas.drawLine(
      Offset(der - a * 0.02, top + a * 0.20),
      Offset(der - a * 0.10, base),
      tinta,
    );
    canvas.drawLine(
      Offset(cx, top + a * 0.20),
      Offset(cx, top + a * 0.46),
      Paint()
        ..color = TempleColors.violetaClaro
        ..style = PaintingStyle.stroke
        ..strokeWidth = s * 0.018
        ..strokeCap = StrokeCap.round,
    );
  }

  @override
  bool shouldRepaint(_LogoPainter oldDelegate) => false;
}

