class DojoBackground extends StatefulWidget {
  const DojoBackground({super.key});

  @override
  State<DojoBackground> createState() => _DojoBackgroundState();
}

class _DojoBackgroundState extends State<DojoBackground>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;

  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 46),
  );

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (MediaQuery.maybeDisableAnimationsOf(context) ?? false) {
      _c.stop();
      _c.value = 0.25;
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return RepaintBoundary(
      child: AnimatedBuilder(
        animation: _c,
        builder: (BuildContext context, _) =>
            CustomPaint(painter: _PaisajePainter(_c.value), size: Size.infinite),
      ),
    );
  }
}

class _PaisajePainter extends CustomPainter {
  const _PaisajePainter(this.t);
  final double t;

  @override
  void paint(Canvas canvas, Size size) {
    final double w = size.width;
    final double h = size.height;
    final double horizonte = h * 0.76;
    // Colores del paisaje según el tema (60): de día en Claro.
    final PaisajePaleta pp = TemaTemplo.paleta.paisaje;

    // Cielo.
    canvas.drawRect(
      Offset.zero & size,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: pp.cielo,
          stops: const <double>[0, 0.38, 0.72, 1],
        ).createShader(Offset.zero & size),
    );

    // Estrellas.
    final math.Random rnd = math.Random(7);
    for (int i = 0; i < (pp.estrellas ? 34 : 0); i++) {
      final double x = rnd.nextDouble() * w;
      final double y = rnd.nextDouble() * h * 0.55;
      final double parpadeo =
          0.35 + 0.35 * math.sin(t * 2 * math.pi * 2 + i.toDouble());
      canvas.drawCircle(
        Offset(x, y),
        rnd.nextDouble() * 1.1 + 0.4,
        Paint()..color = Colors.white.withValues(alpha: parpadeo * 0.5),
      );
    }

    // Luna.
    final Offset luna = Offset(w * 0.78, h * 0.16);
    final double rl = w * 0.13;
    canvas.drawCircle(
      luna,
      rl * 3.6,
      Paint()
        ..shader = RadialGradient(
          colors: <Color>[
            TempleColors.violetaClaro.withValues(alpha: 0.26),
            Colors.transparent,
          ],
        ).createShader(Rect.fromCircle(center: luna, radius: rl * 3.6)),
    );
    canvas.drawCircle(
      luna,
      rl,
      Paint()..color = pp.luna.withValues(alpha: 0.9),
    );

    // Fuji.
    final Path fuji = Path()
      ..moveTo(-w * 0.05, horizonte)
      ..cubicTo(w * 0.10, h * 0.60, w * 0.24, h * 0.30, w * 0.40, h * 0.28)
      ..cubicTo(w * 0.56, h * 0.30, w * 0.70, h * 0.60, w * 0.86, horizonte)
      ..close();
    canvas.drawPath(fuji, Paint()..color = pp.fuji);
    // Nieve.
    canvas.drawPath(
      Path()
        ..moveTo(w * 0.325, h * 0.365)
        ..cubicTo(w * 0.35, h * 0.30, w * 0.37, h * 0.285, w * 0.40, h * 0.28)
        ..cubicTo(w * 0.43, h * 0.285, w * 0.45, h * 0.30, w * 0.475, h * 0.365)
        ..cubicTo(w * 0.44, h * 0.345, w * 0.42, h * 0.385, w * 0.40, h * 0.355)
        ..cubicTo(w * 0.38, h * 0.385, w * 0.36, h * 0.345, w * 0.325, h * 0.365)
        ..close(),
      Paint()..color = pp.nieve.withValues(alpha: 0.85),
    );

    // Colinas traseras.
    canvas.drawPath(
      Path()
        ..moveTo(w * 0.55, horizonte)
        ..cubicTo(w * 0.68, h * 0.60, w * 0.82, h * 0.54, w * 1.05, horizonte)
        ..close(),
      Paint()..color = pp.colinas,
    );

    // Bambú a la izquierda.
    for (int i = 0; i < 4; i++) {
      final double x = w * (0.03 + i * 0.045);
      final double alto = h * (0.52 + (i % 2) * 0.10);
      final Paint canya = Paint()
        ..color = pp.bambu
        ..style = PaintingStyle.stroke
        ..strokeWidth = w * 0.011
        ..strokeCap = StrokeCap.round;
      canvas.drawLine(Offset(x, horizonte), Offset(x + w * 0.012, horizonte - alto), canya);
      for (int n = 1; n < 5; n++) {
        final double y = horizonte - alto * n / 5;
        canvas.drawLine(
          Offset(x + w * 0.012 * (n / 5) - 4, y),
          Offset(x + w * 0.012 * (n / 5) + 4, y),
          canya..strokeWidth = w * 0.006,
        );
      }
    }

    // Casa tradicional a la derecha.
    _casaTradicional(canvas, Offset(w * 0.70, horizonte), w * 0.24);

    // Agua.
    canvas.drawRect(
      Rect.fromLTRB(0, horizonte, w, h),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[
            pp.aguaArriba.withValues(alpha: 0.96),
            pp.aguaAbajo,
          ],
        ).createShader(Rect.fromLTRB(0, horizonte, w, h)),
    );
    for (int i = 0; i < 5; i++) {
      final double y = horizonte + 10 + i * 13.0;
      final double d = math.sin(t * 2 * math.pi + i) * 7;
      canvas.drawLine(
        Offset(luna.dx - 22 + d, y),
        Offset(luna.dx + 22 + d, y),
        Paint()
          ..color = TempleColors.violetaClaro.withValues(alpha: 0.15 - i * 0.025)
          ..strokeWidth = 1.5
          ..strokeCap = StrokeCap.round,
      );
    }

    // Torii al frente, sobre el agua.
    _torii(canvas, Offset(w * 0.27, horizonte + h * 0.06), h * 0.22);

    // Niebla.
    for (int i = 0; i < 4; i++) {
      final double fase = (t + i * 0.25) % 1.0;
      final double x = -w * 0.5 + fase * w * 2.0;
      final double y = horizonte - h * 0.09 + i * 14.0;
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromLTWH(x, y, w * 0.7, 13),
          const Radius.circular(8),
        ),
        Paint()
          ..color = TempleColors.violetaClaro.withValues(alpha: 0.05)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 12),
      );
    }

    // Viñeta inferior para que el formulario siempre tenga contraste.
    canvas.drawRect(
      Offset.zero & size,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[
            Colors.transparent,
            TempleColors.negro.withValues(alpha: 0.55),
            TempleColors.negro.withValues(alpha: 0.92),
          ],
          stops: const <double>[0.30, 0.66, 1],
        ).createShader(Offset.zero & size),
    );
  }

  void _casaTradicional(Canvas canvas, Offset base, double ancho) {
    final Paint tinta = Paint()..color = TemaTemplo.paleta.paisaje.tinta;
    final double alto = ancho * 0.52;

    // Cuerpo.
    canvas.drawRect(
      Rect.fromLTWH(base.dx - ancho / 2, base.dy - alto * 0.62, ancho, alto * 0.62),
      tinta,
    );
    // Tejado con aleros curvos.
    canvas.drawPath(
      Path()
        ..moveTo(base.dx - ancho * 0.66, base.dy - alto * 0.58)
        ..quadraticBezierTo(
          base.dx - ancho * 0.30, base.dy - alto * 0.94, base.dx, base.dy - alto)
        ..quadraticBezierTo(base.dx + ancho * 0.30, base.dy - alto * 0.94,
            base.dx + ancho * 0.66, base.dy - alto * 0.58)
        ..quadraticBezierTo(base.dx, base.dy - alto * 0.72, base.dx - ancho * 0.66,
            base.dy - alto * 0.58)
        ..close(),
      tinta,
    );
    // Ventanas encendidas.
    for (int i = 0; i < 3; i++) {
      canvas.drawRect(
        Rect.fromLTWH(
          base.dx - ancho * 0.34 + i * ancho * 0.26,
          base.dy - alto * 0.44,
          ancho * 0.14,
          alto * 0.20,
        ),
        Paint()..color = const Color(0xFFE0A84E).withValues(alpha: 0.55),
      );
    }
  }

  void _torii(Canvas canvas, Offset base, double alto) {
    final double ancho = alto * 0.80;
    final Color c = TemaTemplo.paleta.paisaje.frente;
    final double izq = base.dx - ancho / 2;
    final double der = base.dx + ancho / 2;
    final double top = base.dy - alto;

    Paint p(double w) => Paint()
      ..color = c
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeWidth = w;

    canvas.drawPath(
      Path()
        ..moveTo(izq - ancho * 0.14, top + alto * 0.10)
        ..quadraticBezierTo(
            base.dx, top - alto * 0.04, der + ancho * 0.14, top + alto * 0.10),
      p(alto * 0.075),
    );
    canvas.drawLine(Offset(izq - ancho * 0.02, top + alto * 0.21),
        Offset(der + ancho * 0.02, top + alto * 0.21), p(alto * 0.052));
    canvas.drawLine(Offset(izq + ancho * 0.07, top + alto * 0.42),
        Offset(der - ancho * 0.07, top + alto * 0.42), p(alto * 0.046));
    canvas.drawLine(Offset(izq + ancho * 0.02, top + alto * 0.21),
        Offset(izq + ancho * 0.07, base.dy), p(alto * 0.062));
    canvas.drawLine(Offset(der - ancho * 0.02, top + alto * 0.21),
        Offset(der - ancho * 0.07, base.dy), p(alto * 0.062));
    canvas.drawLine(Offset(base.dx, top + alto * 0.21),
        Offset(base.dx, top + alto * 0.42), p(alto * 0.030));
  }

  @override
  bool shouldRepaint(_PaisajePainter old) => old.t != t;
}

/// Pétalos en deriva. Se usa en el login y en cualquier pantalla secundaria.
class PetalField extends StatefulWidget {
  const PetalField({super.key, this.cantidad = 14});
  final int cantidad;

  @override
  State<PetalField> createState() => _PetalFieldState();
}

class _PetalFieldState extends State<PetalField>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 18),
  );

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (MediaQuery.maybeDisableAnimationsOf(context) ?? false) {
      _c.stop();
      _c.value = 0.3;
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    // En la web no hay pétalos: la experiencia completa vive en la app (59).
    if (Rendimiento.ligero) return const SizedBox.shrink();
    return IgnorePointer(
      child: RepaintBoundary(
        child: AnimatedBuilder(
          animation: _c,
          builder: (BuildContext context, _) => CustomPaint(
            painter: _PetalPainter(_c.value, widget.cantidad),
            size: Size.infinite,
          ),
        ),
      ),
    );
  }
}

class _PetalPainter extends CustomPainter {
  const _PetalPainter(this.t, this.n);
  final double t;
  final int n;

  @override
  void paint(Canvas canvas, Size size) {
    final math.Random rnd = math.Random(21);
    for (int i = 0; i < n; i++) {
      final double semilla = rnd.nextDouble();
      final double vel = 0.5 + semilla * 0.7;
      final double fase = (t * vel + semilla) % 1.0;
      final double x = size.width * rnd.nextDouble() +
          math.sin(fase * 2 * math.pi + i) * 26;
      final double y = -14 + fase * (size.height + 28);
      final double tam = 4 + semilla * 4;

      canvas.save();
      canvas.translate(x, y);
      canvas.rotate(fase * 6 + i);
      canvas.drawOval(
        Rect.fromCenter(center: Offset.zero, width: tam * 1.7, height: tam),
        Paint()
          ..color = const Color(0xFFE7B9F5)
              .withValues(alpha: 0.20 + semilla * 0.28),
      );
      canvas.restore();
    }
  }

  @override
  bool shouldRepaint(_PetalPainter old) => old.t != t;
}

