class TempleTextField extends StatefulWidget {
  const TempleTextField({
    super.key,
    required this.controller,
    required this.etiqueta,
    required this.hint,
    required this.glifo,
    this.esContrasena = false,
    this.enabled = true,
    this.textInputAction = TextInputAction.next,
    this.inputFormatters,
    this.validator,
    this.focusNode,
    this.onSubmitted,
  });

  final TextEditingController controller;
  final String etiqueta;
  final String hint;
  final TempleGlyph glifo;
  final bool esContrasena;
  final bool enabled;
  final TextInputAction textInputAction;
  final List<TextInputFormatter>? inputFormatters;
  final String? Function(String?)? validator;
  final FocusNode? focusNode;
  final void Function(String)? onSubmitted;

  @override
  State<TempleTextField> createState() => _TempleTextFieldState();
}

class _TempleTextFieldState extends State<TempleTextField> {
  bool _oculto = true;
  late final FocusNode _foco = widget.focusNode ?? FocusNode();
  bool _enfocado = false;

  @override
  void initState() {
    super.initState();
    _foco.addListener(() {
      if (mounted) setState(() => _enfocado = _foco.hasFocus);
    });
  }

  @override
  void dispose() {
    if (widget.focusNode == null) _foco.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: <Widget>[
        Text(
          widget.etiqueta.toUpperCase(),
          style: TextStyle(
            fontSize: 10.5,
            fontWeight: FontWeight.w600,
            letterSpacing: 1.6,
            color: _enfocado
                ? TempleColors.violetaClaro
                : TempleColors.textoTenue,
          ),
        ),
        const SizedBox(height: 8),
        TextFormField(
          controller: widget.controller,
          focusNode: _foco,
          enabled: widget.enabled,
          obscureText: widget.esContrasena && _oculto,
          textInputAction: widget.textInputAction,
          inputFormatters: widget.inputFormatters,
          validator: widget.validator,
          onFieldSubmitted: widget.onSubmitted,
          style: const TextStyle(fontSize: 15, color: TempleColors.blancoLuna),
          cursorColor: TempleColors.violetaClaro,
          decoration: InputDecoration(
            hintText: widget.hint,
            hintStyle: const TextStyle(color: TempleColors.textoTenue),
            filled: true,
            fillColor: TempleColors.superficie.withValues(alpha: 0.75),
            prefixIcon: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 14),
              child: TempleIcon(
                widget.glifo,
                size: 19,
                color: _enfocado
                    ? TempleColors.violetaClaro
                    : TempleColors.textoTenue,
                trazo: 1.6,
              ),
            ),
            prefixIconConstraints:
                const BoxConstraints(minWidth: 0, minHeight: 0),
            suffixIcon: widget.esContrasena
                ? IconButton(
