class AuthValidators {
  const AuthValidators._();

  static String? usuario(String? v) {
    final String s = (v ?? '').trim();
    if (s.isEmpty) return 'Escribe tu nombre de usuario';
    if (s.length < 3) return 'Mínimo 3 caracteres';
    return null;
  }

  static String? contrasena(String? v) {
    final String s = v ?? '';
    if (s.isEmpty) return 'Escribe tu contraseña';
    if (s.length < 6) return 'Mínimo 6 caracteres';
    return null;
  }
}

class LoginScreen extends StatefulWidget {
  const LoginScreen({super.key});

  @override
  State<LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends State<LoginScreen>
    with SingleTickerProviderStateMixin {
  final GlobalKey<FormState> _formKey = GlobalKey<FormState>();
  final TextEditingController _usuario = TextEditingController();
  final TextEditingController _contrasena = TextEditingController();
  final FocusNode _focoContrasena = FocusNode();

  late final AnimationController _entrada = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1600),
  );

  bool _cargando = false;
  String? _errorGeneral;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _entrada.forward();
    });
  }

  @override
  void dispose() {
    _entrada.dispose();
    _usuario.dispose();
    _contrasena.dispose();
    _focoContrasena.dispose();
    super.dispose();
  }

  Future<void> _entrarAlDojo() async {
    FocusScope.of(context).unfocus();
    setState(() => _errorGeneral = null);

    if (!(_formKey.currentState?.validate() ?? false)) {
      HapticFeedback.lightImpact();
      return;
    }

    setState(() => _cargando = true);

    try {
      final PerfilServidor p = await SesionTemplo.instancia.iniciarSesion(
        usuario: _usuario.text.trim(),
        password: _contrasena.text,
      );
      if (!mounted) return;
      HapticFeedback.heavyImpact();
      if (p.espiritu == null) {
        // La cuenta existe pero no terminó El Ascenso.
        Navigator.of(context).pushAndRemoveUntil(
          MaterialPageRoute<void>(builder: (_) => AscensoScreen(usuario: p.usuario)),
          (Route<dynamic> r) => false,
        );
      } else {
        Navigator.of(context).pushAndRemoveUntil(
          rutaAlTemplo(SesionTemplo.instancia.perfilApp()),
          (Route<dynamic> r) => false,
        );
      }
    } on AuthFailure catch (e) {
      if (!mounted) return;
      HapticFeedback.vibrate();
      setState(() => _errorGeneral = e.mensaje);
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  void _aviso(String txt) {
    ScaffoldMessenger.of(context)
      ..hideCurrentSnackBar()
      ..showSnackBar(
        SnackBar(
          behavior: SnackBarBehavior.floating,
          backgroundColor: TempleColors.superficieAlta,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(TempleRadius.campo),
            side: const BorderSide(color: TempleColors.borde),
          ),
          content: Text(
            txt,
            style: const TextStyle(color: TempleColors.texto, fontSize: 13),
          ),
        ),
      );
  }

  @override
  Widget build(BuildContext context) {
    final double alturaTeclado = MediaQuery.viewInsetsOf(context).bottom;
    final bool tecladoAbierto = alturaTeclado > 0;

    return AnnotatedRegion<SystemUiOverlayStyle>(
      value: TemaTemplo.estiloBarras,
      child: Scaffold(
        backgroundColor: TempleColors.negro,
        resizeToAvoidBottomInset: false,
        body: Stack(
          fit: StackFit.expand,
          children: <Widget>[
            const DojoBackground(),
            const PetalField(),
            SafeArea(
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: () => FocusScope.of(context).unfocus(),
                child: LayoutBuilder(
                  builder: (BuildContext context, BoxConstraints c) {
                    return SingleChildScrollView(
                      physics: const ClampingScrollPhysics(),
                      padding: EdgeInsets.only(
                        left: 26,
                        right: 26,
                        top: 8,
                        bottom: 24 + alturaTeclado,
                      ),
                      child: ConstrainedBox(
                        constraints: BoxConstraints(
                          minHeight: c.maxHeight - 32,
                          maxWidth: 430,
                        ),
                        child: Center(
                          child: Column(
                            mainAxisSize: MainAxisSize.min,
                            crossAxisAlignment: CrossAxisAlignment.stretch,
                            children: <Widget>[
                              SizedBox(height: tecladoAbierto ? 12 : 34),
                              Aparece(
                                controlador: _entrada,
                                desde: 0.00,
                                hasta: 0.45,
                                desplazamiento: 26,
                                child: _Marca(compacta: tecladoAbierto),
                              ),
                              SizedBox(height: tecladoAbierto ? 26 : 44),
                              Aparece(
                                controlador: _entrada,
                                desde: 0.28,
                                hasta: 0.72,
                                child: Form(
                                  key: _formKey,
                                  child: AutofillGroup(
                                    child: Column(
                                      crossAxisAlignment:
                                          CrossAxisAlignment.stretch,
                                      children: <Widget>[
                                        TempleTextField(
                                          controller: _usuario,
                                          etiqueta: 'Nombre de usuario',
                                          hint: 'tu_nombre',
                                          glifo: TempleGlyph.kitsune,
                                          enabled: !_cargando,
                                          validator: AuthValidators.usuario,
                                          inputFormatters:
                                              <TextInputFormatter>[
                                            FilteringTextInputFormatter.deny(
                                                RegExp(r'\s')),
                                            LengthLimitingTextInputFormatter(20),
                                          ],
                                          onSubmitted: (_) =>
                                              _focoContrasena.requestFocus(),
                                        ),
                                        const SizedBox(height: 18),
                                        TempleTextField(
                                          controller: _contrasena,
                                          focusNode: _focoContrasena,
                                          etiqueta: 'Contraseña',
                                          hint: '••••••••',
                                          glifo: TempleGlyph.torii,
                                          esContrasena: true,
                                          enabled: !_cargando,
                                          textInputAction:
                                              TextInputAction.done,
                                          validator:
                                              AuthValidators.contrasena,
                                          onSubmitted: (_) => _entrarAlDojo(),
                                        ),
                                        const SizedBox(height: 4),
 Align(
                                          alignment: Alignment.centerRight,
                                          child: DojoTextLink(
                                            texto: '¿Olvidaste tu contraseña?',
                                            onTap: () =>
                                                Navigator.of(context).push(
                                              MaterialPageRoute<void>(
                                                builder: (_) =>
                                                    const RecuperarAccesoScreen(),
                                              ),
                                            ),
                                          ),
                                        ),
                                      ],
                                    ),
                                  ),
                                ),
                              ),
                              _MensajeError(mensaje: _errorGeneral),
                              const SizedBox(height: 26),
                              Aparece(
                                controlador: _entrada,
                                desde: 0.44,
                                hasta: 0.86,
