class PerfilUsuario {
  const PerfilUsuario({
    required this.nombre,
    required this.espiritu,
    required this.rango,
    required this.nivel,
    required this.xp,
    required this.xpSiguiente,
    this.titulo,
    this.rangoEspecial = false,
  });

  final String nombre;
  final String espiritu;
  final String rango;
  final int nivel;
  final int xp;
  final int xpSiguiente;
  final String? titulo;
  final bool rangoEspecial;

  double get progresoNivel =>
      xpSiguiente <= 0 ? 0 : (xp / xpSiguiente).clamp(0.0, 1.0);

  factory PerfilUsuario.nuevo({
    required String nombre,
    required String espiritu,
  }) =>
      PerfilUsuario(
        nombre: nombre,
        espiritu: espiritu,
        rango: 'Aprendiz',
        nivel: 1,
        xp: 0,
        xpSiguiente: 500,
      );

  PerfilUsuario copyWith({String? nombre}) => PerfilUsuario(
        nombre: nombre ?? this.nombre,
        espiritu: espiritu,
        rango: rango,
        nivel: nivel,
        xp: xp,
        xpSiguiente: xpSiguiente,
        titulo: titulo,
        rangoEspecial: rangoEspecial,
      );

  static const PerfilUsuario demo = PerfilUsuario(
    nombre: 'Guerrero',
    espiritu: 'Kuroi',
    rango: 'Samurái Élite',
    nivel: 17,
    xp: 2450,
    xpSiguiente: 3000,
    titulo: 'El que no falta',
    rangoEspecial: true,
  );
}

