const double kAlturaNavBar = 68;

class DestinoTemplo {
  const DestinoTemplo({required this.etiqueta, required this.glifo});
  final String etiqueta;
  final TempleGlyph glifo;
}

const List<DestinoTemplo> destinosTemplo = <DestinoTemplo>[
  DestinoTemplo(etiqueta: 'Dojo', glifo: TempleGlyph.torii),
  DestinoTemplo(etiqueta: 'Casa', glifo: TempleGlyph.casa),
  DestinoTemplo(etiqueta: 'Tenshi', glifo: TempleGlyph.kitsune),
  DestinoTemplo(etiqueta: 'Clan', glifo: TempleGlyph.clan),
  DestinoTemplo(etiqueta: 'Ranked', glifo: TempleGlyph.espadas),
];

class MainShell extends StatefulWidget {
  const MainShell({super.key, required this.perfil, this.indiceInicial = 0});
  final PerfilUsuario perfil;
  final int indiceInicial;

  @override
  State<MainShell> createState() => _MainShellState();
}

class _MainShellState extends State<MainShell> {
  late int _indice = TemaTemplo.instancia.tomarModulo() ?? widget.indiceInicial;

  @override
  void initState() {
    super.initState();
    if (TemaTemplo.instancia.tomarReapertura()) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) abrirApariencia(context, modulo: _indice);
      });
    }
    PaseTemplo.instancia.cargar();
    SonidosTemplo.instancia.cargar();
    Moderacion.instancia.comprobar();
    PreferenciasPase.instancia.cargar();
    // Recordatorios del teléfono, tu clan y las cifras para los retos.
    Recordatorios.instancia.cargar(widget.perfil.nombre);
    ActividadRepo.instancia.reiniciar();
    ClanesRepo.instancia.cargarMio();
    Future<void>.delayed(const Duration(seconds: 4), () => RetosRepo.instancia.aportar(widget.perfil.nombre));
    WidgetsBinding.instance.addPostFrameCallback((_) => _primeraVez());
  }

  /// La primera vez: el recorrido por el templo y, al terminarlo, la alerta
  /// del Pase (una sola vez). Después, la guía de cada módulo la primera vez
  /// que se abre.
  Future<void> _primeraVez() async {
    if (!mounted) return;
    final String u = widget.perfil.nombre;
    // Si los términos cambiaron desde que los aceptó, primero eso.
    if (!await pedirTerminosSiCambiaron(context) || !mounted) return;
    // Una pieza lucida 24 h que ya venció vuelve a su lugar; y los anuncios
    // se preparan, con el aviso de privacidad si hace falta.
    if (AlmacenAnuncios.instancia.revisarPrueba(u)) NubeTemplo.instancia.marcarCambio();
    unawaited(MotorAnuncios.instancia.iniciar());
    if (!GuiaTemplo.instancia.vista(u, 'recorrido')) {
      await Navigator.of(context).push(MaterialPageRoute<void>(
        fullscreenDialog: true,
        builder: (_) => RecorridoScreen(usuario: u),
      ));
      GuiaTemplo.instancia.marcar(u, 'recorrido');
      if (!mounted) return;
    }
    if (!GuiaTemplo.instancia.vista(u, 'pase_alerta')) {
      GuiaTemplo.instancia.marcar(u, 'pase_alerta');
      // A menores de edad no se les insiste con pagos.
      final bool menor = SesionTemplo.instancia.actual?.esMenor ?? false;
      if (!menor && !PaseTemplo.instancia.activo) {
        await mostrarAlertaPase(context);
        if (!mounted) return;
      }
    }
    _guiaDe(_indice);
  }

  void _guiaDe(int i) {
    if (!mounted || i < 0 || i >= clavesModulos.length) return;
    guiaSiEsNueva(context, widget.perfil.nombre, clavesModulos[i]);
  }

  void _irA(int i) {
    if (i == _indice) return;
    HapticFeedback.selectionClick();
    sonar(SonidoTemplo.toque);
    setState(() => _indice = i);
    WidgetsBinding.instance.addPostFrameCallback((_) => _guiaDe(i));
  }

  @override
  Widget build(BuildContext context) {
    return TempleShellScope(
      perfil: widget.perfil,
      irA: _irA,
      indice: _indice,
      child: Scaffold(
        backgroundColor: TempleColors.negro,
        extendBody: true,
        body: FondoTemplo(
          child: IndexedStack(
            index: _indice,
            children: const <Widget>[
              DojoScreen(),
              CasaScreen(),
              TenshiScreen(),
              ClanScreen(),
              RankedScreen(),
            ],
          ),
        ),
        bottomNavigationBar: TempleNavBar(
          indice: _indice,
          onDestino: _irA,
          puntos: <int>{
            if (AlmacenRanked.instancia.pendientes(widget.perfil.nombre).isNotEmpty) 4,
          },
        ),
      ),
    );
  }
}

class TempleShellScope extends InheritedWidget {
  const TempleShellScope({
    super.key,
    required this.perfil,
    required this.irA,
    required this.indice,
    required super.child,
  });

  final PerfilUsuario perfil;
  final void Function(int indice) irA;
  final int indice;

  static TempleShellScope of(BuildContext context) {
    final TempleShellScope? s =
        context.dependOnInheritedWidgetOfExactType<TempleShellScope>();
    assert(s != null, 'No hay MainShell por encima de este widget.');
    return s!;
  }

  @override
  bool updateShouldNotify(TempleShellScope old) =>
      old.perfil != perfil || old.indice != indice;
}

class TempleNavBar extends StatelessWidget {
  const TempleNavBar({
    super.key,
    required this.indice,
    required this.onDestino,
    this.puntos = const <int>{},
  });

  final int indice;
  final ValueChanged<int> onDestino;

  /// Pestañas con algo esperando (un punto dorado).
  final Set<int> puntos;

  @override
  Widget build(BuildContext context) {
    final double seguro = MediaQuery.paddingOf(context).bottom;

    // En la web el desenfoque del fondo se recalculaba en cada cuadro: ahí va
    // un color casi opaco, que se ve igual y cuesta casi nada (59).
    final Widget barra = Container(
          padding: EdgeInsets.only(bottom: seguro),
          decoration: BoxDecoration(
            color: TempleColors.negro.withValues(alpha: Rendimiento.ligero ? 0.96 : 0.82),
            border: Border(
              top: BorderSide(
                color: TempleColors.borde.withValues(alpha: 0.9),
              ),
            ),
          ),
          child: SizedBox(
            height: kAlturaNavBar,
            child: Row(
              children: List<Widget>.generate(destinosTemplo.length, (int i) {
                return Expanded(
                  child: _ItemNav(
                    destino: destinosTemplo[i],
                    activo: i == indice,
                    punto: puntos.contains(i),
                    onTap: () => onDestino(i),
                  ),
                );
              }),
            ),
          ),
        );
    if (Rendimiento.ligero) return barra;
    return ClipRect(
      child: BackdropFilter(
        filter: ImageFilter.blur(sigmaX: 18, sigmaY: 18),
        child: barra,
      ),
    );
  }
}

class _ItemNav extends StatelessWidget {
  const _ItemNav({
    required this.destino,
    required this.activo,
    required this.onTap,
    this.punto = false,
  });

  final DestinoTemplo destino;
  final bool activo;
  final VoidCallback onTap;
  final bool punto;

  @override
  Widget build(BuildContext context) {
    final Color tinte =
        activo ? TempleColors.violeta : TempleColors.textoTenue;

    return Semantics(
      button: true,
      selected: activo,
      label: destino.etiqueta,
      child: InkWell(
        onTap: onTap,
        splashColor: TempleColors.violeta.withValues(alpha: 0.08),
        highlightColor: Colors.transparent,
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: <Widget>[
            const SizedBox(height: 4),
            AnimatedScale(
              duration: TempleMotion.medio,
              curve: TempleMotion.suave,
              scale: activo ? 1.06 : 1,
              child: Badge(
                isLabelVisible: punto,
                smallSize: 8,
