class EntrenamientoDelDia {
  const EntrenamientoDelDia({
    required this.nombre,
    required this.grupos,
    required this.duracionMin,
    required this.ejercicios,
    this.completado = false,
  });

  final String nombre;
  final List<String> grupos;
  final int duracionMin;
  final int ejercicios;
  final bool completado;

  String get resumen => grupos.join(' · ');
}

class ObjetivoDiario {
  const ObjetivoDiario({
    required this.titulo,
    required this.actual,
    required this.meta,
    this.unidad = '',
  });

  final String titulo;
  final num actual;
  final num meta;
  final String unidad;

  bool get cumplido => actual >= meta;
  double get progreso => meta <= 0 ? 0 : (actual / meta).clamp(0.0, 1.0);
}

class MedidorEnergia {
  const MedidorEnergia({
    required this.etiqueta,
    required this.valor,
    required this.glifo,
  });

  final String etiqueta;
  final double valor;
  final TempleGlyph glifo;
}

class DiaSemana {
  const DiaSemana({
    required this.inicial,
    required this.valor,
    this.esHoy = false,
  });

  final String inicial;
  final double valor;
  final bool esHoy;
}

class EstadoDojo {
  const EstadoDojo({
    required this.entrenamiento,
    required this.objetivos,
    required this.medidores,
    required this.semana,
    required this.fraseKanji,
    required this.frase,
  });

  final EntrenamientoDelDia entrenamiento;
  final List<ObjetivoDiario> objetivos;
  final List<MedidorEnergia> medidores;
  final List<DiaSemana> semana;
  final String fraseKanji;
  final String frase;

  int get objetivosCumplidos =>
      objetivos.where((ObjetivoDiario o) => o.cumplido).length;

  double get progresoGeneral => objetivos.isEmpty
      ? 0
      : objetivos.fold<double>(
              0, (double a, ObjetivoDiario o) => a + o.progreso) /
          objetivos.length;

  static const EstadoDojo demo = EstadoDojo(
    fraseKanji: '継続は力なり',
    frase: 'La constancia es fuerza.',
    entrenamiento: EntrenamientoDelDia(
      nombre: 'Fuerza superior',
      grupos: <String>['Espalda', 'Bíceps', 'Abdomen'],
      duracionMin: 52,
      ejercicios: 6,
    ),
    objetivos: <ObjetivoDiario>[
      ObjetivoDiario(
          titulo: 'Volumen levantado', actual: 4200, meta: 6000, unidad: ' kg'),
      ObjetivoDiario(titulo: 'Series completadas', actual: 12, meta: 18),
      ObjetivoDiario(titulo: 'Agua', actual: 1.8, meta: 3, unidad: ' L'),
      ObjetivoDiario(titulo: 'Proteína', actual: 96, meta: 140, unidad: ' g'),
    ],
    medidores: <MedidorEnergia>[
      MedidorEnergia(
          etiqueta: 'Energía', valor: 0.78, glifo: TempleGlyph.rayo),
      MedidorEnergia(
          etiqueta: 'Fuerza', valor: 0.64, glifo: TempleGlyph.mancuerna),
      MedidorEnergia(
          etiqueta: 'Constancia', valor: 0.90, glifo: TempleGlyph.montana),
      MedidorEnergia(etiqueta: 'Sueño', valor: 0.52, glifo: TempleGlyph.luna),
      MedidorEnergia(etiqueta: 'Agua', valor: 0.60, glifo: TempleGlyph.gota),
    ],
    semana: <DiaSemana>[
      DiaSemana(inicial: 'L', valor: 0.62),
      DiaSemana(inicial: 'M', valor: 0.85),
      DiaSemana(inicial: 'X', valor: 0.30),
      DiaSemana(inicial: 'J', valor: 0.74),
      DiaSemana(inicial: 'V', valor: 0.95),
      DiaSemana(inicial: 'S', valor: 0.48, esHoy: true),
      DiaSemana(inicial: 'D', valor: 0.0),
    ],
  );
