/// Lo que el servidor sabe de la cuenta propia.
class PerfilServidor {
  const PerfilServidor({
    required this.id,
    required this.usuario,
    required this.genero,
    required this.edad,
    required this.esMenor,
    this.espiritu,
    this.ascenso = const <String, String>{},
    this.nombreVisible,
    this.biografia = '',
    this.etiquetas = const <String>[],
    this.sello = const <String, dynamic>{},
    this.vineta = const <String, String>{},
    this.redes = const <String, String>{},
    this.terminosVersion,
  });

  final String id;
  final String usuario;
  final String genero;

  /// Enlaces a redes sociales del perfil público (sección 47).
  final Map<String, String> redes;

  /// Versión de los términos que aceptó. Null si el servidor no la envía.
  final String? terminosVersion;
  final int edad;
  final bool esMenor;
  final String? espiritu;
  final Map<String, String> ascenso;

  // Lo que el perfil público ya tiene guardado. Sirve para restaurar la
  // identidad y la viñeta al volver a entrar.
  final String? nombreVisible;
  final String biografia;
  final List<String> etiquetas;
  final Map<String, dynamic> sello;
  final Map<String, String> vineta;

  String? get foto {
    final Object? f = sello['foto'];
    return f is String && f.isNotEmpty ? f : null;
  }

  factory PerfilServidor.desdeMapa(Map<String, dynamic> m) {
    final Map<String, String> asc = <String, String>{};
    final Object? a = m['ascenso'];
    if (a is Map) {
      a.forEach((Object? k, Object? v) {
        if (k != null && v != null) asc[k.toString()] = v.toString();
      });
    }
    final Map<String, String> vin = <String, String>{};
    final Object? v = m['vineta'];
    if (v is Map) {
      v.forEach((Object? k, Object? x) {
        if (k != null && x != null) vin[k.toString()] = x.toString();
      });
    }
    final Object? s = m['sello'];
    final Object? et = m['etiquetas'];
    return PerfilServidor(
      id: m['id'] as String,
      usuario: m['usuario'] as String,
      genero: (m['genero'] as String?) ?? 'hombre',
      edad: (m['edad'] as num?)?.toInt() ?? 0,
      esMenor: m['es_menor'] == true,
      espiritu: m['espiritu'] as String?,
      ascenso: asc,
      nombreVisible: m['nombre_visible'] as String?,
      biografia: (m['biografia'] as String?) ?? '',
      etiquetas: et is List ? et.map((Object? e) => e.toString()).toList() : const <String>[],
      sello: s is Map ? Map<String, dynamic>.from(s) : const <String, dynamic>{},
      vineta: vin,
      redes: RedesSociales.desde(m['redes']),
      terminosVersion: m['terminos_version'] as String?,
    );
  }
}

class SesionTemplo {
  SesionTemplo._();
  static final SesionTemplo instancia = SesionTemplo._();

  PerfilServidor? actual;

  /// Ya aceptó la versión vigente en esta ejecución (aunque el servidor aún
  /// no lo sepa por falta de conexión).
  bool terminosAceptadosAhora = false;

  /// Registra en el servidor que aceptó los términos vigentes.
  Future<bool> aceptarTerminos() async {
    try {
      await supa.rpc('aceptar_terminos', params: <String, dynamic>{'v': ConfigSupabase.versionTerminos});
      return true;
    } catch (_) {
      return false;
    }
  }

  String? get uid => supa.auth.currentUser?.id;

  String _correo(String usuario) =>
      '${usuario.trim().toLowerCase()}@${ConfigSupabase.dominioInterno}';

  /// Convierte cualquier error del servidor en un mensaje para la persona.
  static String mensajeDe(Object e) {
    if (e is AuthFailure) return e.mensaje;
    if (e is FunctionException) {
      final Object? d = e.details;
      if (d is Map && d['error'] != null) return d['error'].toString();
      return 'Algo falló en el templo. Intenta de nuevo.';
    }
    if (e is PostgrestException) {
      final String m = e.message;
      // Los mensajes que escribimos en la base de datos ya están en español.
      if (m.isNotEmpty && !m.contains('violates') && !m.contains('permission')) {
        return m;
      }
      return 'No tienes permiso para hacer eso.';
    }
    if (e is StorageException) {
      return 'No se pudo subir el archivo. Revisa que pese menos de 50 MB.';
    }
    if (e is AuthException) return e.message;
    return 'No hay conexión con el templo. Revisa tu internet.';
  }

  /// Datos de la cuenta propia. Si no hay sesión, null.
  ///
  /// Sin internet entra con la última copia del perfil guardada en el
  /// dispositivo, y abre el progreso guardado (en el teléfono y en la nube).
  Future<PerfilServidor?> cargarMiPerfil() async {
    final String? id = uid;
    if (id == null) return null;
    Map<String, dynamic>? datos;
    try {
      final Object? r = await supa.rpc('mi_perfil').timeout(const Duration(seconds: 10));
      if (r is! Map) return null;
      datos = Map<String, dynamic>.from(r);
      unawaited(NubeTemplo.guardarPerfilCache(id, datos));
    } catch (_) {
      datos = await NubeTemplo.perfilCache(id);
      if (datos == null) rethrow;
    }
    actual = PerfilServidor.desdeMapa(datos);
    final PerfilServidor p = actual!;
    if (p.ascenso.isNotEmpty) {
      AlmacenTemplo.instancia.guardarAscenso(p.usuario, p.ascenso);
    }
    _hidratar(p);
    await NubeTemplo.instancia.abrir(uid: id, usuario: p.usuario);
    return p;
  }

  /// Usuarios cuya identidad ya se trajo del servidor en esta ejecución.
  final Set<String> _hidratados = <String>{};

  /// Al entrar, devuelve a la app lo que el perfil público ya tenía: nombre,
  /// biografía, sello, foto y la viñeta del taller. Solo una vez por
  /// ejecución, para no pisar lo que la persona edite después.
  void _hidratar(PerfilServidor p) {
    if (!_hidratados.add(p.usuario)) return;
    final IdentidadUsuario id = AlmacenIdentidad.instancia.de(p.usuario);
    id.nombreVisible = p.nombreVisible;
    id.biografia = p.biografia;
    id.etiquetas
      ..clear()
      ..addAll(p.etiquetas);
    final Map<String, dynamic> s = p.sello;
    final Object? paleta = s['paleta'];
    if (paleta is num) id.paleta = paleta.toInt();
    for (final SimboloSello x in SimboloSello.values) {
      if (x.name == s['simbolo']) id.simbolo = x;
    }
    for (final MarcoSello x in MarcoSello.values) {
      if (x.name == s['marco']) id.marco = x;
    }
    final Object? estilo = s['estilo'];
    id.estiloNombre = estilo is String ? estilo : null;
    id.foto = p.foto;
    id.redes
      ..clear()
      ..addAll(p.redes);

    final EstadoProgreso prog = MotorProgresion.instancia.de(p.usuario);
    for (final MapEntry<String, String> e in p.vineta.entries) {
      for (final CapaVineta c in CapaVineta.values) {
        if (c.name == e.key) {
          prog.vineta[c] = e.value;
          // La pieza que está a la vista ya era suya: se conserva.
          prog.piezas.add(e.value);
        }
      }
    }
  }

  /// La viñeta como la guarda el servidor: {capa: pieza}.
  static Map<String, String> vinetaParaServidor(Map<CapaVineta, String> v) =>
      v.map((CapaVineta c, String p) => MapEntry<String, String>(c.name, p));

  PerfilUsuario _perfilApp(PerfilServidor p) => PerfilUsuario.nuevo(
        nombre: p.usuario,
        espiritu: p.espiritu ?? 'Sin espíritu',
      );

  /// Al abrir la app: si quedó una sesión guardada, entra directo.
  Future<PerfilServidor?> restaurar() async {
    if (supa.auth.currentSession == null) return null;
    try {
      return await cargarMiPerfil();
    } catch (_) {
      return null;
    }
  }

  PerfilUsuario perfilApp() => _perfilApp(actual!);

  /// Crea la cuenta en el servidor y deja la sesión iniciada.
  /// Devuelve el código de recuperación (se muestra una sola vez).
  Future<String?> registrar({
    required String usuario,
    required String password,
    required DateTime nacimiento,
    required String genero,
    required bool autorizacionTutor,
    Map<String, dynamic>? captcha,
  }) async {
    final String fecha = '${nacimiento.year.toString().padLeft(4, '0')}-'
        '${nacimiento.month.toString().padLeft(2, '0')}-'
        '${nacimiento.day.toString().padLeft(2, '0')}';
    try {
      final FunctionResponse r = await supa.functions.invoke(
        'cuenta',
        body: <String, dynamic>{
          'accion': 'registrar',
          'usuario': usuario.trim(),
          'password': password,
          'nacimiento': fecha,
          'genero': genero,
          'terminos_version': ConfigSupabase.versionTerminos,
          'tutor': autorizacionTutor,
          if (captcha != null) 'captcha': captcha,
        },
      );
      final Object? d = r.data;
      final String? codigo =
          d is Map && d['codigo'] != null ? d['codigo'].toString() : null;
      await supa.auth.signInWithPassword(
        email: _correo(usuario),
        password: password,
      );
      await cargarMiPerfil();
      return codigo;
    } catch (e) {
      throw AuthFailure(mensajeDe(e));
    }
  }

  Future<PerfilServidor> iniciarSesion({
    required String usuario,
    required String password,
  }) async {
    try {
      await supa.auth.signInWithPassword(
        email: _correo(usuario),
        password: password,
      );
    } on AuthException {
      bool existe = true;
      bool sinRed = false;
      try {
        existe = await supa.rpc('usuario_existe',
                params: <String, dynamic>{'u': usuario.trim()}) ==
            true;
      } catch (_) {
        sinRed = true;
      }
      if (sinRed) {
        throw const AuthFailure(
            'Sin internet no se puede entrar por primera vez en este teléfono. '
            'Si ya habías entrado aquí, abre la app sin cerrar sesión y funcionará sin conexión.');
      }
      throw AuthFailure(existe
          ? 'La contraseña no abre esta puerta'
          : 'No encontramos a nadie con ese nombre');
    } catch (e) {
      throw AuthFailure(mensajeDe(e));
    }
    final PerfilServidor? p = await cargarMiPerfil();
    if (p == null) {
      await supa.auth.signOut();
      throw const AuthFailure('Esta cuenta no tiene perfil. Escríbenos a soporte.');
    }
    return p;
  }

  /// Guarda el espíritu y las respuestas de El Ascenso en el servidor.
  Future<void> guardarAscenso(String espiritu, Map<String, String> respuestas) async {
    final String? id = uid;
    if (id == null) return;
    try {
      await supa.from('perfiles').update(<String, dynamic>{
        'espiritu': espiritu,
        'ascenso': respuestas,
      }).eq('id', id);
      await cargarMiPerfil();
    } catch (_) {
      // Si falla, la app sigue: se reintenta la próxima vez que se sincronice.
    }
  }

  /// Sube al perfil público lo que se editó en local: nombre, biografía,
  /// sello, foto y viñeta. El nivel, la racha y la llama solo se suben si en
  /// esta ejecución hay entrenamientos registrados, para no borrar lo que el
  /// servidor ya mostraba.
  Future<bool> sincronizarIdentidad(String usuario) async {
    final String? id = uid;
    if (id == null) return false;
    final IdentidadUsuario ident = AlmacenIdentidad.instancia.de(usuario);
    final DatosUsuario datos = AlmacenTemplo.instancia.de(usuario);
    final Map<String, dynamic> cambios = <String, dynamic>{
      'nombre_visible': (ident.nombreVisible ?? '').trim().isEmpty
          ? null
          : ident.nombreVisible!.trim(),
      'biografia': ident.biografia.length > 160
          ? ident.biografia.substring(0, 160)
          : ident.biografia,
      'etiquetas': ident.etiquetas,
      'sello': <String, dynamic>{
        'paleta': ident.paleta,
        'simbolo': ident.simbolo.name,
        'marco': ident.marco.name,
        if (ident.foto != null) 'foto': ident.foto,
        // El servidor lo borra si no hay Pase; el sello «pase_hasta» lo pone
        // solo el servidor.
        if (ident.estiloNombre != null) 'estilo': ident.estiloNombre,
      },
      'vineta': vinetaParaServidor(MotorProgresion.instancia.de(usuario).vineta),
      // El servidor recorta a 2 sin Pase y los vacía en cuentas de menores.
      'redes': (actual?.esMenor ?? false) ? <String, String>{} : RedesSociales.visibles(ident.redes, limite: 5),
    };
    if (datos.completadas.isNotEmpty) {
      final NivelTemplo nivel = NivelTemplo.desdeXp(datos.xpGeneral);
      final Llama llama = AlmacenTemplo.instancia.llama(usuario);
      cambios['nivel'] = nivel.nivel;
      cambios['rango'] = nivel.rango;
      cambios['racha'] =
          MotorProgresion.instancia.racha(usuario).diasSeguidos.clamp(0, 3650);
      cambios['llama'] = llama.valor.clamp(0, 100);
      cambios['ranked'] = AlmacenRanked.resumenParaServidor(usuario);
    }
    try {
      await supa.from('perfiles').update(cambios).eq('id', id);
      return true;
    } catch (_) {
      // Si el servidor aún no tiene las columnas nuevas, guarda al menos lo
      // de siempre.
      try {
        await supa.from('perfiles').update(<String, dynamic>{
          for (final MapEntry<String, dynamic> e in cambios.entries)
            if (e.key != 'vineta' && e.key != 'racha' && e.key != 'llama' && e.key != 'ranked' && e.key != 'redes')
              e.key: e.value,
        }).eq('id', id);
        return true;
      } catch (_) {
        return false;
      }
    }
  }

  /// Sube una foto de la galería como foto de perfil y borra la anterior.
  Future<void> cambiarFotoPerfil(String usuario, XFile archivo) async {
    final String? id = uid;
    if (id == null) throw const AuthFailure('Tu sesión se cerró. Vuelve a entrar.');
    final IdentidadUsuario ident = AlmacenIdentidad.instancia.de(usuario);
    final String? anterior = ident.foto;
    try {
      final Uint8List bytes = await archivo.readAsBytes();
      if (bytes.length > 8 * 1024 * 1024) {
        throw const AuthFailure('La foto pesa demasiado. Elige otra.');
      }
      final String n = archivo.name.toLowerCase();
      final String ext = n.endsWith('.png')
          ? 'png'
          : n.endsWith('.webp')
              ? 'webp'
              : 'jpg';
      final String ruta = '$id/perfil/${DateTime.now().millisecondsSinceEpoch}.$ext';
      await supa.storage.from(MediosClan.bucket).uploadBinary(
            ruta,
            bytes,
            fileOptions: FileOptions(
              contentType: ext == 'png'
                  ? 'image/png'
                  : ext == 'webp'
                      ? 'image/webp'
                      : 'image/jpeg',
              upsert: false,
            ),
          );
      ident.foto = ruta;
      if (!await sincronizarIdentidad(usuario)) {
        ident.foto = anterior;
        try {
          await supa.storage.from(MediosClan.bucket).remove(<String>[ruta]);
        } catch (_) {}
        throw const AuthFailure('No se pudo guardar la foto. Intenta de nuevo.');
      }
      if (anterior != null && anterior != ruta) {
        try {
          await supa.storage.from(MediosClan.bucket).remove(<String>[anterior]);
        } catch (_) {}
      }
    } catch (e) {
      throw AuthFailure(mensajeDe(e));
    }
  }

  /// Vuelve al sello sin foto.
  Future<void> quitarFotoPerfil(String usuario) async {
    final IdentidadUsuario ident = AlmacenIdentidad.instancia.de(usuario);
    final String? anterior = ident.foto;
    ident.foto = null;
    await sincronizarIdentidad(usuario);
    if (anterior != null) {
      try {
        await supa.storage.from(MediosClan.bucket).remove(<String>[anterior]);
      } catch (_) {}
    }
  }

  Future<String?> recuperar({
    required String usuario,
    required String codigo,
    required String nueva,
  }) async {
    try {
      final FunctionResponse r = await supa.functions.invoke(
        'cuenta',
        body: <String, dynamic>{
          'accion': 'recuperar',
          'usuario': usuario.trim(),
          'codigo': codigo,
          'nueva': nueva,
        },
      );
      final Object? d = r.data;
      return d is Map && d['codigo'] != null ? d['codigo'].toString() : null;
    } catch (e) {
      throw AuthFailure(mensajeDe(e));
    }
  }

  Future<String?> nuevoCodigo() async {
    try {
      final FunctionResponse r = await supa.functions.invoke(
        'cuenta',
        body: <String, dynamic>{'accion': 'nuevo_codigo'},
      );
      final Object? d = r.data;
      return d is Map && d['codigo'] != null ? d['codigo'].toString() : null;
    } catch (e) {
      throw AuthFailure(mensajeDe(e));
    }
  }

  Future<void> cerrarSesion() async {
    // Lo último que se entrenó se guarda y se sube antes de salir.
    try {
      await NubeTemplo.instancia.cerrar().timeout(const Duration(seconds: 12));
    } catch (_) {}
    actual = null;
    GymsRepo.instancia.limpiar();
    await supa.auth.signOut();
  }

  Future<void> eliminarCuenta() async {
    final String? id = uid;
    try {
      await supa.functions.invoke(
        'cuenta',
        body: <String, dynamic>{'accion': 'eliminar'},
      );
    } catch (e) {
      throw AuthFailure(mensajeDe(e));
    }
    if (id != null) await NubeTemplo.instancia.borrarTodo(id);
    actual = null;
    GymsRepo.instancia.limpiar();
    try {
      await supa.auth.signOut();
    } catch (_) {}
  }
}

/// Puerta de entrada: si hay sesión guardada, entra directo al templo (o a
/// El Ascenso si quedó sin terminar). Si no, al inicio de sesión.
class PuertaTemplo extends StatefulWidget {
  const PuertaTemplo({super.key});

  @override
  State<PuertaTemplo> createState() => _PuertaTemploState();
}

class _PuertaTemploState extends State<PuertaTemplo> {
  late final Future<PerfilServidor?> _carga =
      vistaPrueba ? Future<PerfilServidor?>.value() : SesionTemplo.instancia.restaurar();

  @override
  Widget build(BuildContext context) {
    if (vistaPrueba) {
      // Solo en compilaciones de prueba (60.5): módulos sin cuenta.
      if (parametroPrueba('pantalla') == 'login') return const LoginScreen();
      return MainShell(
        perfil: PerfilUsuario.nuevo(nombre: 'Kenji', espiritu: espiritusDelTemplo.values.first.nombre),
        indiceInicial: int.tryParse(parametroPrueba('modulo') ?? '') ?? 0,
      );
    }
    return FutureBuilder<PerfilServidor?>(
      future: _carga,
      builder: (BuildContext context, AsyncSnapshot<PerfilServidor?> s) {
        if (s.connectionState != ConnectionState.done) {
          return const Scaffold(
            backgroundColor: TempleColors.negro,
            body: Center(child: ToriiMoonLogo(size: 110)),
          );
        }
        final PerfilServidor? p = s.data;
        if (p == null) return const LoginScreen();
        if (p.espiritu == null) return AscensoScreen(usuario: p.usuario);
        return MainShell(perfil: SesionTemplo.instancia.perfilApp());
      },
    );
  }
}

/// Transición compartida hacia el shell: fundido con una escala mínima, como
/// si el templo se acercara.
Route<void> rutaAlTemplo(PerfilUsuario perfil) {
  return PageRouteBuilder<void>(
    transitionDuration: const Duration(milliseconds: 620),
    pageBuilder: (_, __, ___) => MainShell(perfil: perfil),
    transitionsBuilder: (_, Animation<double> a, __, Widget hijo) {
      final Animation<double> c =
          CurvedAnimation(parent: a, curve: TempleMotion.entrada);
      return FadeTransition(
        opacity: c,
        child: ScaleTransition(
          scale: Tween<double>(begin: 1.06, end: 1).animate(c),
          child: hijo,
        ),
      );
    },
  );
}

