// ===========================================================================
// 18. CREAR CUENTA
//
// Además del nombre y la contraseña, se pide fecha de nacimiento y género:
// la edad decide en qué parte del Clan vive cada persona (menores con
// menores, adultos con adultos) y ambos datos aparecen como una burbuja junto
// al nombre en el perfil. La fecha exacta nunca se muestra a nadie.
// ===========================================================================

const List<String> kMesesTemplo = <String>[
  'enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
  'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre',
];

int edadEnAnios(DateTime nacimiento, [DateTime? hoy]) {
  final DateTime h = hoy ?? DateTime.now();
  int e = h.year - nacimiento.year;
  if (h.month < nacimiento.month ||
      (h.month == nacimiento.month && h.day < nacimiento.day)) {
    e--;
  }
  return e;
}

class RegistroScreen extends StatefulWidget {
  const RegistroScreen({super.key});

  @override
  State<RegistroScreen> createState() => _RegistroScreenState();
}

class _RegistroScreenState extends State<RegistroScreen> {
  final GlobalKey<FormState> _formKey = GlobalKey<FormState>();
  final TextEditingController _usuario = TextEditingController();
  final TextEditingController _password = TextEditingController();
  final TextEditingController _confirmar = TextEditingController();
  final FocusNode _focoPassword = FocusNode();
  final FocusNode _focoConfirmar = FocusNode();

  DateTime? _nacimiento;
  String? _genero;
  bool _tutor = false;
  bool _terminos = false;

  /// Si los términos se aceptaron con las reglas para menores incluidas.
  bool _terminosComoMenor = false;

  bool _cargando = false;
  String? _error;

  int? get _edad => _nacimiento == null ? null : edadEnAnios(_nacimiento!);
  bool get _esMenor => (_edad ?? 99) < 18;

  @override
  void initState() {
    super.initState();
    // El medidor vive fuera del campo, así que hay que avisarle al teclear.
    _password.addListener(() {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _usuario.dispose();
    _password.dispose();
    _confirmar.dispose();
    _focoPassword.dispose();
    _focoConfirmar.dispose();
    super.dispose();
  }

  /// Fuerza de la contraseña, 0–3. No bloquea: solo informa.
  int get _fuerza {
    final String p = _password.text;
    if (p.length < 6) return 0;
    int f = 1;
    if (p.length >= 10) f++;
    if (RegExp(r'[0-9]').hasMatch(p) && RegExp(r'[a-zA-Z]').hasMatch(p)) f++;
    return f.clamp(0, 3);
  }

  static String? _validarUsuario(String? v) {
    final String s = (v ?? '').trim();
    if (s.isEmpty) return 'Escribe tu nombre de usuario';
    if (s.length < 3) return 'Mínimo 3 caracteres';
    if (!RegExp(r'^[A-Za-z0-9_.]+$').hasMatch(s)) {
      return 'Solo letras, números, punto y guion bajo';
    }
    return null;
  }

  Future<void> _elegirNacimiento() async {
    FocusScope.of(context).unfocus();
    final DateTime? f = await mostrarSelectorNacimiento(context, _nacimiento);
    if (f != null && mounted) {
      setState(() {
        _nacimiento = f;
        if (!_esMenor) _tutor = false;
        // Si ahora es menor y aceptó sin las reglas para menores, debe leerlas.
        if (_esMenor && _terminos && !_terminosComoMenor) _terminos = false;
        _error = null;
      });
    }
  }

  Future<void> _leerTerminos() async {
    FocusScope.of(context).unfocus();
    final bool menor = _esMenor && _nacimiento != null;
    final bool? ok = await Navigator.of(context).push<bool>(
      MaterialPageRoute<bool>(builder: (_) => TerminosScreen(paraAceptar: true, menor: menor)),
    );
    if (ok == true && mounted) {
      setState(() {
        _terminos = true;
        _terminosComoMenor = menor;
        _error = null;
      });
    }
  }

  Future<void> _crear() async {
    FocusScope.of(context).unfocus();
    setState(() => _error = null);

    final bool formOk = _formKey.currentState?.validate() ?? false;
    String? falta;
    if (_nacimiento == null) {
      falta = 'Elige tu fecha de nacimiento';
    } else if ((_edad ?? 0) < 13) {
      falta = 'Necesitas tener al menos 13 años para entrar al templo';
    } else if (_genero == null) {
      falta = 'Elige tu género';
    } else if (_esMenor && !_tutor) {
      falta = 'Confirma que tu madre, padre o tutor lo autoriza';
    } else if (!_terminos) {
      falta = 'Lee y acepta los términos para cruzar el umbral';
    }
    if (!formOk || falta != null) {
      HapticFeedback.lightImpact();
      setState(() => _error = falta);
      return;
    }

    // El reto del templo (captcha): lo comprueba el servidor al crear la cuenta.
    final Map<String, dynamic>? captcha = await resolverRetoTemplo(context);
    if (captcha == null || !mounted) return;

    setState(() => _cargando = true);
    try {
      final String usuario = _usuario.text.trim();
      final String? codigo = await SesionTemplo.instancia.registrar(
        usuario: usuario,
        password: _password.text,
        nacimiento: _nacimiento!,
        genero: _genero!,
        autorizacionTutor: _tutor,
        captcha: captcha,
      );
      if (!mounted) return;
      HapticFeedback.heavyImpact();
      if (codigo != null) await mostrarCodigoRecuperacion(context, codigo);
      if (!mounted) return;
      // La cuenta existe pero aún no tiene espíritu: toca El Ascenso.
      Navigator.of(context).pushAndRemoveUntil(
        MaterialPageRoute<void>(builder: (_) => AscensoScreen(usuario: usuario)),
        (Route<dynamic> r) => false,
      );
    } on AuthFailure catch (e) {
      if (!mounted) return;
      HapticFeedback.vibrate();
      setState(() => _error = e.mensaje);
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final int? edad = _edad;
    return PantallaAcceso(
      titulo: 'Cruza el umbral',
      subtitulo:
          'Elige el nombre con el que el templo te reconocerá. No pedimos correo '
          'ni teléfono: aquí solo importa quién entrena.',
      child: Form(
        key: _formKey,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: <Widget>[
            TempleTextField(
              controller: _usuario,
              etiqueta: 'Nombre de usuario',
              hint: 'tu_nombre',
              glifo: TempleGlyph.kitsune,
              enabled: !_cargando,
              validator: _validarUsuario,
              inputFormatters: <TextInputFormatter>[
                FilteringTextInputFormatter.allow(RegExp(r'[A-Za-z0-9_.]')),
                LengthLimitingTextInputFormatter(20),
              ],
              onSubmitted: (_) => _focoPassword.requestFocus(),
            ),
            const SizedBox(height: 8),
            const Text(
              'Entre 3 y 20 caracteres: letras, números, punto o guion bajo. '
              'No podrás cambiarlo.',
              style: TextStyle(fontSize: 11.5, color: TempleColors.textoTenue),
            ),
            const SizedBox(height: 18),
            TempleTextField(
              controller: _password,
              focusNode: _focoPassword,
              etiqueta: 'Contraseña',
              hint: '••••••••',
              glifo: TempleGlyph.torii,
              esContrasena: true,
              enabled: !_cargando,
              validator: AuthValidators.contrasena,
              onSubmitted: (_) => _focoConfirmar.requestFocus(),
            ),
            const SizedBox(height: 10),
            _MedidorFuerza(nivel: _fuerza),
            const SizedBox(height: 18),
            TempleTextField(
              controller: _confirmar,
              focusNode: _focoConfirmar,
              etiqueta: 'Repite la contraseña',
              hint: '••••••••',
              glifo: TempleGlyph.torii,
              esContrasena: true,
              enabled: !_cargando,
              textInputAction: TextInputAction.done,
              validator: (String? v) {
                if ((v ?? '').isEmpty) return 'Repite la contraseña';
                if (v != _password.text) return 'Las dos no coinciden';
                return null;
              },
              onSubmitted: (_) => _elegirNacimiento(),
            ),
            const SizedBox(height: 26),
            const _RotuloRegistro('Fecha de nacimiento'),
            const SizedBox(height: 8),
            _CampoTocable(
              icono: Icons.cake_outlined,
              texto: _nacimiento == null
                  ? 'Elige el día, el mes y el año'
                  : '${_nacimiento!.day} de ${kMesesTemplo[_nacimiento!.month - 1]} '
                      'de ${_nacimiento!.year}',
              detalle: edad == null ? null : '$edad años',
              vacio: _nacimiento == null,
              onTap: _cargando ? null : _elegirNacimiento,
            ),
            const SizedBox(height: 8),
            const Text(
              'Solo se muestra tu edad, nunca la fecha. Si tienes menos de 18 años, los '
              'adultos no ven tu edad y tendrás que leer unas reglas para menores.',
              style: TextStyle(fontSize: 11.5, height: 1.45, color: TempleColors.textoTenue),
            ),
            const SizedBox(height: 22),
            const _RotuloRegistro('Género'),
            const SizedBox(height: 8),
            Row(
              children: <Widget>[
                Expanded(
                  child: _OpcionGenero(
                    texto: 'Hombre',
                    simbolo: '♂',
                    elegido: _genero == 'hombre',
                    onTap: _cargando
                        ? null
                        : () => setState(() {
                              _genero = 'hombre';
                              _error = null;
                            }),
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: _OpcionGenero(
                    texto: 'Mujer',
                    simbolo: '♀',
                    elegido: _genero == 'mujer',
                    onTap: _cargando
                        ? null
                        : () => setState(() {
                              _genero = 'mujer';
                              _error = null;
                            }),
                  ),
                ),
              ],
            ),
            AnimatedSize(
              duration: TempleMotion.medio,
              curve: TempleMotion.suave,
              child: _esMenor && edad != null && edad >= 13
                  ? Padding(
                      padding: const EdgeInsets.only(top: 22),
                      child: _CasillaAcuerdo(
                        marcada: _tutor,
                        texto: 'Tengo menos de 18 años y mi madre, padre o tutor '
                            'conoce y autoriza que use Temple of Strength.',
                        onTap: () => setState(() {
                          _tutor = !_tutor;
                          if (_tutor) _error = null;
                        }),
                      ),
                    )
                  : const SizedBox(width: double.infinity),
            ),
            const SizedBox(height: 22),
            _CasillaAcuerdo(
              marcada: _terminos,
              texto: _terminos
                  ? 'Aceptaste los Términos y el Reglamento del templo '
                      '(versión ${ConfigSupabase.versionTerminos}).'
                  : 'Lee y acepta los Términos y el Reglamento del templo: '
                      'cómo funciona la app, el entrenamiento, Tenshi y el Clan.',
              accion: _terminos ? 'Volver a leer' : 'Leer y aceptar',
              onTap: _leerTerminos,
            ),
            BloqueError(mensaje: _error),
            const SizedBox(height: 26),
            DojoPrimaryButton(
              texto: 'Comenzar el Ascenso',
              cargando: _cargando,
              onPressed: _crear,
            ),
            const SizedBox(height: 18),
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: <Widget>[
                const Text(
                  '¿Ya tienes un nombre?',
                  style: TextStyle(fontSize: 13, color: TempleColors.textoSuave),
                ),
                DojoTextLink(
                  texto: 'Inicia sesión',
                  destacado: true,
                  onTap: () => Navigator.of(context).pop(),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

