/// Tres ruedas (día, mes, año) en una hoja inferior. Sin depender del
/// selector de fechas del sistema, que saldría en inglés sin localización.
Future<DateTime?> mostrarSelectorNacimiento(BuildContext context, DateTime? actual) {
  return showModalBottomSheet<DateTime>(
    context: context,
    backgroundColor: TempleColors.grafito,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
    ),
    builder: (_) => _HojaNacimiento(inicial: actual),
  );
}

class _HojaNacimiento extends StatefulWidget {
  const _HojaNacimiento({required this.inicial});
  final DateTime? inicial;

  @override
  State<_HojaNacimiento> createState() => _HojaNacimientoState();
}

class _HojaNacimientoState extends State<_HojaNacimiento> {
  late final int _anioMax = DateTime.now().year;
  late final int _anioMin = _anioMax - 100;

  late int _dia = widget.inicial?.day ?? 1;
  late int _mes = widget.inicial?.month ?? 1;
  late int _anio = widget.inicial?.year ?? (_anioMax - 18);

  late final FixedExtentScrollController _cDia =
      FixedExtentScrollController(initialItem: _dia - 1);
  late final FixedExtentScrollController _cMes =
      FixedExtentScrollController(initialItem: _mes - 1);
  late final FixedExtentScrollController _cAnio =
      FixedExtentScrollController(initialItem: _anioMax - _anio);

  @override
  void dispose() {
    _cDia.dispose();
    _cMes.dispose();
    _cAnio.dispose();
    super.dispose();
  }

  int get _diasDelMes => DateTime(_anio, _mes + 1, 0).day;

  Widget _rueda({
    required FixedExtentScrollController c,
    required int cantidad,
    required String Function(int i) texto,
    required ValueChanged<int> onCambio,
    required int seleccion,
  }) {
    return ListWheelScrollView.useDelegate(
      controller: c,
      itemExtent: 42,
      diameterRatio: 1.6,
      physics: const FixedExtentScrollPhysics(),
      onSelectedItemChanged: (int i) {
        HapticFeedback.selectionClick();
        onCambio(i);
      },
      childDelegate: ListWheelChildBuilderDelegate(
        childCount: cantidad,
        builder: (BuildContext context, int i) => Center(
          child: Text(
            texto(i),
            style: TextStyle(
              fontSize: i == seleccion ? 17 : 15,
              fontWeight: i == seleccion ? FontWeight.w600 : FontWeight.w400,
              color: i == seleccion ? TempleColors.blancoLuna : TempleColors.textoTenue,
            ),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final int diasMes = _diasDelMes;
    final int dia = _dia.clamp(1, diasMes);
    final DateTime fecha = DateTime(_anio, _mes, dia);
    final int edad = edadEnAnios(fecha);

    return SafeArea(
      top: false,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(20, 14, 20, 20),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: <Widget>[
            Center(
              child: Container(
                width: 40,
                height: 4,
                decoration: BoxDecoration(
                  color: TempleColors.bordeVivo,
                  borderRadius: BorderRadius.circular(2),
                ),
              ),
            ),
            const SizedBox(height: 18),
            const Text('¿Cuándo naciste?',
                style: TextStyle(
                    fontSize: 19, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
            const SizedBox(height: 4),
            Text(
              edad < 13 ? 'Necesitas al menos 13 años' : '$edad años',
              style: TextStyle(
                fontSize: 13,
                color: edad < 13 ? TempleColors.alertaSuave : TempleColors.textoSuave,
              ),
            ),
            const SizedBox(height: 12),
            SizedBox(
              height: 200,
              child: Stack(
                children: <Widget>[
                  Center(
                    child: Container(
                      height: 42,
                      decoration: BoxDecoration(
                        color: TempleColors.violeta.withValues(alpha: 0.10),
                        borderRadius: BorderRadius.circular(TempleRadius.chip),
                        border: Border.all(color: TempleColors.violeta.withValues(alpha: 0.25)),
                      ),
                    ),
                  ),
                  Row(
                    children: <Widget>[
                      Expanded(
                        flex: 2,
                        child: _rueda(
                          c: _cDia,
                          cantidad: 31,
                          seleccion: _dia - 1,
                          texto: (int i) => '${i + 1}',
                          onCambio: (int i) => setState(() => _dia = i + 1),
                        ),
                      ),
                      Expanded(
                        flex: 4,
                        child: _rueda(
                          c: _cMes,
                          cantidad: 12,
                          seleccion: _mes - 1,
                          texto: (int i) => kMesesTemplo[i],
                          onCambio: (int i) => setState(() => _mes = i + 1),
                        ),
                      ),
                      Expanded(
                        flex: 3,
                        child: _rueda(
                          c: _cAnio,
                          cantidad: _anioMax - _anioMin + 1,
                          seleccion: _anioMax - _anio,
                          texto: (int i) => '${_anioMax - i}',
                          onCambio: (int i) => setState(() => _anio = _anioMax - i),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
            if (_dia > diasMes)
              Padding(
                padding: const EdgeInsets.only(top: 6),
                child: Text(
                  '${kMesesTemplo[_mes - 1]} de $_anio tiene $diasMes días: se usará el $diasMes.',
                  textAlign: TextAlign.center,
                  style: const TextStyle(fontSize: 11.5, color: TempleColors.textoTenue),
                ),
              ),
            const SizedBox(height: 16),
            DojoPrimaryButton(
              texto: 'Listo',
              onPressed: () => Navigator.of(context).pop(fecha),
            ),
          ],
        ),
      ),
    );
  }
}

/// El código se muestra una sola vez. Sin él no hay forma de recuperar una
/// cuenta sin correo, así que no se puede cerrar sin confirmar.
Future<void> mostrarCodigoRecuperacion(BuildContext context, String codigo) {
  return showDialog<void>(
    context: context,
    barrierDismissible: false,
    builder: (BuildContext ctx) => _DialogoCodigo(codigo: codigo),
  );
}

class _DialogoCodigo extends StatefulWidget {
  const _DialogoCodigo({required this.codigo});
  final String codigo;

  @override
  State<_DialogoCodigo> createState() => _DialogoCodigoState();
}

class _DialogoCodigoState extends State<_DialogoCodigo> {
  bool _copiado = false;
  bool _guardado = false;

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      backgroundColor: TempleColors.superficieAlta,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
        side: const BorderSide(color: TempleColors.borde),
      ),
      title: const Text('Tu llave de repuesto',
          style: TextStyle(color: TempleColors.blancoLuna, fontSize: 19)),
      content: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: <Widget>[
          const Text(
            'Como no usamos correo, este código es la única forma de recuperar tu '
            'cuenta si olvidas la contraseña. Guárdalo donde no se pierda: una foto, '
            'una nota o un papel.',
            style: TextStyle(fontSize: 13, height: 1.5, color: TempleColors.textoSuave),
          ),
          const SizedBox(height: 18),
          GestureDetector(
            onTap: () async {
              await Clipboard.setData(ClipboardData(text: widget.codigo));
              HapticFeedback.selectionClick();
              if (mounted) setState(() => _copiado = true);
            },
            child: Container(
              padding: const EdgeInsets.symmetric(vertical: 16),
              decoration: BoxDecoration(
                color: TempleColors.negro.withValues(alpha: 0.5),
                borderRadius: BorderRadius.circular(TempleRadius.campo),
                border: Border.all(color: TempleColors.violeta.withValues(alpha: 0.4)),
              ),
              child: Column(
                children: <Widget>[
                  SelectableText(
                    widget.codigo,
                    textAlign: TextAlign.center,
                    style: const TextStyle(
                      fontSize: 20,
                      letterSpacing: 2.2,
                      fontWeight: FontWeight.w600,
                      color: TempleColors.blancoLuna,
                    ),
                  ),
                  const SizedBox(height: 6),
                  Text(
                    _copiado ? 'Copiado' : 'Toca para copiar',
                    style: TextStyle(
                      fontSize: 11.5,
                      color: _copiado ? TempleColors.exito : TempleColors.textoTenue,
                    ),
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 16),
          _CasillaAcuerdo(
            marcada: _guardado,
            texto: 'Ya guardé mi código en un lugar seguro.',
            onTap: () => setState(() => _guardado = !_guardado),
          ),
        ],
      ),
      actions: <Widget>[
        TextButton(
          onPressed: _guardado ? () => Navigator.of(context).pop() : null,
          child: Text('Continuar',
              style: TextStyle(
                  color: _guardado ? TempleColors.violetaClaro : TempleColors.textoTenue)),
        ),
      ],
    );
  }
}

/// Tres tramos que se encienden según la contraseña. Informa sin regañar: una
/// contraseña débil no impide entrar, solo se ve débil.
class _MedidorFuerza extends StatelessWidget {
  const _MedidorFuerza({required this.nivel});
  final int nivel;

  static const List<String> _texto = <String>[
    'Muy corta',
    'Aceptable',
    'Buena',
    'Firme como el acero',
  ];

  @override
  Widget build(BuildContext context) {
    final Color color = nivel <= 0
        ? TempleColors.error
        : nivel == 1
            ? TempleColors.alertaSuave
            : TempleColors.exito;

    return Row(
      children: <Widget>[
        for (int i = 0; i < 3; i++) ...<Widget>[
          Expanded(
            child: AnimatedContainer(
              duration: TempleMotion.medio,
              curve: TempleMotion.suave,
              height: 3,
              decoration: BoxDecoration(
                color: i < nivel ? color : TempleColors.borde,
                borderRadius: BorderRadius.circular(2),
              ),
            ),
          ),
          if (i != 2) const SizedBox(width: 5),
        ],
        const SizedBox(width: 12),
        SizedBox(
          width: 122,
          child: Text(
            _texto[nivel.clamp(0, 3)],
            textAlign: TextAlign.right,
            style: TextStyle(fontSize: 11, color: color),
          ),
        ),
      ],
    );
  }
}

