class TerminosScreen extends StatefulWidget {
  const TerminosScreen({super.key, this.paraAceptar = false, this.obligatorio = false, this.menor});

  /// La cuenta es de un menor: se muestran (y hay que aceptar) las reglas
  /// para menores. Si es null, se toma de la sesión.
  final bool? menor;

  /// Si es true, abajo aparece el botón de aceptar y la pantalla devuelve
  /// true al aceptarse.
  final bool paraAceptar;

  /// Los términos cambiaron y hay que aceptarlos para seguir: no se puede
  /// volver atrás; se acepta o se sale de la cuenta.
  final bool obligatorio;

  @override
  State<TerminosScreen> createState() => _TerminosScreenState();
}

class _TerminosScreenState extends State<TerminosScreen> {
  final ScrollController _scroll = ScrollController();

  /// El botón de aceptar se activa al llegar al final: hay que leerlo.
  bool _alFinal = false;

  /// Las personas menores de edad marcan además que leyeron sus reglas.
  bool _reglasMenor = false;

  bool get _menor => widget.menor ?? (SesionTemplo.instancia.actual?.esMenor ?? false);

  @override
  void initState() {
    super.initState();
    _scroll.addListener(() {
      if (!_alFinal && _scroll.hasClients && _scroll.position.extentAfter < 160) {
        setState(() => _alFinal = true);
      }
    });
  }

  @override
  void dispose() {
    _scroll.dispose();
    super.dispose();
  }

  Future<void> _noAcepto() async {
    final bool ok = await confirmarClan(
      context,
      titulo: '¿No aceptas los términos?',
      texto: 'Sin aceptarlos no se puede seguir usando el templo. Tu progreso queda guardado: '
          'podrás volver cuando quieras y aceptarlos entonces.',
      accion: 'Salir de mi cuenta',
    );
    if (ok && mounted) Navigator.of(context).pop(false);
  }

  @override
  Widget build(BuildContext context) {
    final double abajo = MediaQuery.paddingOf(context).bottom;
    final bool paraAceptar = widget.paraAceptar;
    return PopScope(
      canPop: !widget.obligatorio,
      child: Scaffold(
        backgroundColor: TempleColors.negro,
        body: FondoTemplo(
          child: SafeArea(
            bottom: false,
            child: Column(
              children: <Widget>[
                Padding(
                  padding: EdgeInsets.fromLTRB(widget.obligatorio ? 20 : 6, 4, 20, 0),
                  child: Row(
                    children: <Widget>[
                      if (!widget.obligatorio) ...<Widget>[
                        IconButton(
                          onPressed: () => Navigator.of(context).maybePop(),
                          icon: const Icon(Icons.arrow_back_rounded, color: TempleColors.textoSuave),
                        ),
                        const SizedBox(width: 4),
                      ],
                      Expanded(
                        child: Text(widget.obligatorio ? 'Términos actualizados' : 'Términos y reglamento',
                            style: const TextStyle(
                                fontSize: 18, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                      ),
                      const Text('v${ConfigSupabase.versionTerminos}',
