                      const SizedBox(height: 16),
                      if (_menor) ...<Widget>[
                        const TarjetaReglasMenores(),
                        const SizedBox(height: 16),
                      ],
                      const _ResumenTerminos(),
                      const SizedBox(height: 16),
                      for (int i = 0; i < _terminosTemplo.length; i++) ...<Widget>[
                        _ApartadoTarjeta(numero: i + 1, apartado: _terminosTemplo[i]),
                        const SizedBox(height: 12),
                      ],
