// ===========================================================================
// 19. RECUPERAR ACCESO
//
// Sin correo, la prueba de que eres tú es el código de recuperación que
// recibiste al crear la cuenta. Al usarlo se entrega uno nuevo.
// ===========================================================================

class RecuperarAccesoScreen extends StatefulWidget {
  const RecuperarAccesoScreen({super.key});

  @override
  State<RecuperarAccesoScreen> createState() => _RecuperarAccesoScreenState();
}

class _RecuperarAccesoScreenState extends State<RecuperarAccesoScreen> {
  final GlobalKey<FormState> _formKey = GlobalKey<FormState>();
  final TextEditingController _usuario = TextEditingController();
  final TextEditingController _codigo = TextEditingController();
  final TextEditingController _nueva = TextEditingController();
  final TextEditingController _confirmar = TextEditingController();
  final FocusNode _focoCodigo = FocusNode();
  final FocusNode _focoNueva = FocusNode();
  final FocusNode _focoConfirmar = FocusNode();

  bool _hecho = false;
  bool _cargando = false;
  String? _error;

  @override
  void dispose() {
    _usuario.dispose();
    _codigo.dispose();
    _nueva.dispose();
    _confirmar.dispose();
    _focoCodigo.dispose();
    _focoNueva.dispose();
    _focoConfirmar.dispose();
    super.dispose();
  }

  Future<void> _continuar() async {
    FocusScope.of(context).unfocus();
    setState(() => _error = null);
    if (!(_formKey.currentState?.validate() ?? false)) {
      HapticFeedback.lightImpact();
      return;
    }
    setState(() => _cargando = true);
    try {
      final String? nuevo = await SesionTemplo.instancia.recuperar(
        usuario: _usuario.text.trim(),
        codigo: _codigo.text,
        nueva: _nueva.text,
      );
      if (!mounted) return;
      HapticFeedback.heavyImpact();
      if (nuevo != null) await mostrarCodigoRecuperacion(context, nuevo);
      if (mounted) setState(() => _hecho = true);
    } on AuthFailure catch (e) {
      if (!mounted) return;
      HapticFeedback.vibrate();
      setState(() => _error = e.mensaje);
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_hecho) {
      return PantallaAcceso(
        titulo: 'Puerta abierta',
        subtitulo: 'Tu contraseña cambió. El templo te espera.',
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: <Widget>[
            const SizedBox(height: 10),
            Center(
              child: Container(
                width: 92,
                height: 92,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: TempleColors.exito.withValues(alpha: 0.10),
                  border: Border.all(color: TempleColors.exito.withValues(alpha: 0.35)),
                ),
                child: const Icon(Icons.check_rounded, size: 40, color: TempleColors.exito),
              ),
            ),
            const SizedBox(height: 40),
            DojoPrimaryButton(
              texto: 'Volver al inicio',
              onPressed: () => Navigator.of(context).pop(),
            ),
          ],
        ),
      );
    }

    return PantallaAcceso(
      titulo: 'Recuperar acceso',
      subtitulo: 'Escribe tu nombre y el código de recuperación que guardaste al '
          'crear la cuenta. Después eliges una contraseña nueva.',
      child: Form(
        key: _formKey,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: <Widget>[
            TempleTextField(
              controller: _usuario,
              etiqueta: 'Nombre de usuario',
              hint: 'tu_nombre',
              glifo: TempleGlyph.kitsune,
              enabled: !_cargando,
              validator: AuthValidators.usuario,
              inputFormatters: <TextInputFormatter>[
                FilteringTextInputFormatter.deny(RegExp(r'\s')),
              ],
              onSubmitted: (_) => _focoCodigo.requestFocus(),
            ),
            const SizedBox(height: 18),
            TempleTextField(
              controller: _codigo,
              focusNode: _focoCodigo,
              etiqueta: 'Código de recuperación',
              hint: 'XXXX-XXXX-XXXX-XXXX',
              glifo: TempleGlyph.lista,
              enabled: !_cargando,
              inputFormatters: <TextInputFormatter>[
                LengthLimitingTextInputFormatter(24),
              ],
              validator: (String? v) {
                final String s = (v ?? '').toUpperCase().replaceAll(RegExp(r'[^A-Z0-9]'), '');
                if (s.isEmpty) return 'Escribe tu código';
                if (s.length != 16) return 'El código tiene 16 caracteres';
                return null;
              },
              onSubmitted: (_) => _focoNueva.requestFocus(),
            ),
            const SizedBox(height: 18),
            TempleTextField(
              controller: _nueva,
              focusNode: _focoNueva,
              etiqueta: 'Contraseña nueva',
              hint: '••••••••',
              glifo: TempleGlyph.torii,
              esContrasena: true,
              enabled: !_cargando,
              validator: AuthValidators.contrasena,
              onSubmitted: (_) => _focoConfirmar.requestFocus(),
            ),
            const SizedBox(height: 18),
            TempleTextField(
              controller: _confirmar,
              focusNode: _focoConfirmar,
              etiqueta: 'Repítela',
              hint: '••••••••',
              glifo: TempleGlyph.torii,
              esContrasena: true,
              enabled: !_cargando,
              textInputAction: TextInputAction.done,
              validator: (String? v) {
                if ((v ?? '').isEmpty) return 'Repite la contraseña';
                if (v != _nueva.text) return 'Las dos no coinciden';
                return null;
              },
              onSubmitted: (_) => _continuar(),
            ),
            BloqueError(mensaje: _error),
            const SizedBox(height: 26),
            DojoPrimaryButton(
              texto: 'Cambiar contraseña',
              cargando: _cargando,
              onPressed: _continuar,
            ),
            const SizedBox(height: 18),
            const Text(
              '¿Perdiste el código? Escríbenos a ${ConfigSupabase.correoSoporte} '
              'desde el templo y te ayudaremos a comprobar que la cuenta es tuya.',
              textAlign: TextAlign.center,
              style: TextStyle(fontSize: 12, height: 1.5, color: TempleColors.textoTenue),
            ),
          ],
        ),
      ),
    );
  }
}

