/// Uno de los doce espíritus del templo.
class Espiritu {
  const Espiritu({
    required this.nombre,
    required this.kanji,
    required this.titulo,
    required this.descripcion,
  });

  final String nombre;
  final String kanji;
  final String titulo;
  final String descripcion;
}

