Espiritu revelarEspiritu(Map<String, String> r) {
  final String objetivo = r['objetivo'] ?? 'salud';
  final String voz = r['voz'] ?? 'serena';
  return espiritusDelTemplo['$objetivo|$voz'] ??
      espiritusDelTemplo['salud|serena']!;
}

class AscensoScreen extends StatefulWidget {
  const AscensoScreen({super.key, required this.usuario});
  final String usuario;

  @override
  State<AscensoScreen> createState() => _AscensoScreenState();
}

class _AscensoScreenState extends State<AscensoScreen> {
  final PageController _paginas = PageController();
  final Map<String, String> _respuestas = <String, String>{};

  int _indice = 0;

  // La meta (sección 46): qué quiere lograr, con sus palabras y una foto.
  String? _metaTipo;
  String? _metaPlazo;
  String _metaTexto = '';
  XFile? _metaFoto;

  /// A menores de edad no se les pide foto del cuerpo.
  late final bool _menor = SesionTemplo.instancia.actual?.esMenor ?? false;

  /// El orden de las páginas: bienvenida, la primera pregunta (qué viene a
  /// buscar), la meta en tres pasos, el resto de preguntas y la revelación.
  late final List<String> _orden = <String>[
    'b',
    'q0',
    'm1',
    'm2',
    if (!_menor) 'm3',
    for (int i = 1; i < preguntasAscenso.length; i++) 'q$i',
    'r',
  ];

  int get _total => _orden.length;

  /// Pasos que cuentan en la barra (todo menos bienvenida y revelación).
  int get _pasos => _total - 2;

  @override
  void dispose() {
    _paginas.dispose();
    super.dispose();
  }

  void _avanzar() {
    if (_indice >= _total - 1) return;
    _paginas.nextPage(
      duration: const Duration(milliseconds: 420),
      curve: TempleMotion.suave,
    );
  }

  void _retroceder() {
    if (_indice == 0) {
      Navigator.of(context).maybePop();
      return;
    }
    _paginas.previousPage(
      duration: const Duration(milliseconds: 420),
      curve: TempleMotion.suave,
    );
  }

  void _responder(String clave, String valor) {
    HapticFeedback.selectionClick();
    setState(() => _respuestas[clave] = valor);
    // Deja ver la selección antes de pasar de pantalla.
    Future<void>.delayed(const Duration(milliseconds: 280), () {
      if (mounted) _avanzar();
    });
  }

  void _entrarAlTemplo(Espiritu espiritu) {
    final PerfilUsuario perfil = PerfilUsuario.nuevo(
      nombre: widget.usuario,
      espiritu: espiritu.nombre,
    );
    AlmacenTemplo.instancia.guardarAscenso(widget.usuario, _respuestas);
    SesionTemplo.instancia.guardarAscenso(espiritu.nombre, _respuestas);
    if (_metaTipo != null || _metaTexto.isNotEmpty) {
      AlmacenMeta.instancia.guardar(
          widget.usuario, MetaPersonal(tipo: _metaTipo, plazo: _metaPlazo, texto: _metaTexto));
    }
    final XFile? foto = _metaFoto;
    if (foto != null) unawaited(AlmacenMeta.instancia.subirFoto(widget.usuario, foto));
    HapticFeedback.heavyImpact();
    Navigator.of(context)
        .pushAndRemoveUntil(rutaAlTemplo(perfil), (Route<dynamic> r) => false);
  }

  @override
  Widget build(BuildContext context) {
    // La barra de progreso solo cuenta las preguntas.
    final double progreso = (_indice.clamp(0, _pasos)) / _pasos;
    final bool enPreguntas = _indice > 0 && _indice <= _pasos;

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: Stack(
        fit: StackFit.expand,
        children: <Widget>[
          const DojoBackground(),
          const PetalField(cantidad: 10),
          SafeArea(
            child: Column(
              children: <Widget>[
                // Cabecera: retorno + progreso.
                AnimatedOpacity(
                  duration: TempleMotion.medio,
                  opacity: enPreguntas ? 1 : 0,
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(10, 4, 26, 0),
                    child: Row(
                      children: <Widget>[
                        IconButton(
                          onPressed: enPreguntas ? _retroceder : null,
                          icon: const Icon(
                            Icons.arrow_back_rounded,
                            color: TempleColors.textoSuave,
                          ),
                        ),
                        Expanded(
                          child: ClipRRect(
                            borderRadius: BorderRadius.circular(999),
                            child: TweenAnimationBuilder<double>(
                              tween: Tween<double>(begin: 0, end: progreso),
                              duration: TempleMotion.medio,
                              curve: TempleMotion.suave,
                              builder:
                                  (BuildContext context, double v, _) =>
                                      LinearProgressIndicator(
                                value: v,
                                minHeight: 3,
                                backgroundColor: TempleColors.borde,
                                valueColor:
                                    const AlwaysStoppedAnimation<Color>(
                                  TempleColors.violeta,
                                ),
                              ),
                            ),
                          ),
                        ),
                        const SizedBox(width: 14),
                        Text(
                          '${_indice.clamp(1, _pasos)}'
                          '/$_pasos',
                          style: const TextStyle(
                            fontSize: 11.5,
                            color: TempleColors.textoTenue,
                            fontFeatures: <FontFeature>[
                              FontFeature.tabularFigures()
                            ],
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
                Expanded(
                  child: PageView.builder(
                    controller: _paginas,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: _total,
                    onPageChanged: (int i) => setState(() => _indice = i),
                    itemBuilder: (BuildContext context, int i) {
                      final String pagina = _orden[i];
                      if (pagina == 'b') {
                        return _Bienvenida(
                          usuario: widget.usuario,
                          onComenzar: _avanzar,
                        );
                      }
                      if (pagina.startsWith('q')) {
                        final PreguntaAscenso p = preguntasAscenso[int.parse(pagina.substring(1))];
                        return _PaginaPregunta(
                          pregunta: p,
                          seleccion: _respuestas[p.clave],
                          onElegir: (String v) => _responder(p.clave, v),
                        );
                      }
                      if (pagina == 'm1') {
                        return _PaginaMetaConcreta(
                          objetivo: _respuestas['objetivo'],
                          tipo: _metaTipo,
                          plazo: _metaPlazo,
                          onTipo: (String v) => setState(() => _metaTipo = v),
                          onPlazo: (String v) => setState(() => _metaPlazo = v),
                          onSeguir: _avanzar,
                        );
                      }
                      if (pagina == 'm2') {
                        return _PaginaMetaTexto(
                          inicial: _metaTexto,
                          onListo: (String t) {
                            _metaTexto = t;
                            _avanzar();
                          },
                        );
                      }
                      if (pagina == 'm3') {
                        return _PaginaMetaFoto(
                          onListo: (XFile? f) {
                            _metaFoto = f;
                            _avanzar();
                          },
                        );
                      }
                      return _Revelacion(
                        espiritu: revelarEspiritu(_respuestas),
                        onEntrar: _entrarAlTemplo,
                      );
                    },
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

