// ===========================================================================
// TEMPLE OF STRENGTH — MODELO DE SESIÓN
//
// Sección 21 del archivo. Pegar al final de main.dart.
//
// Jerarquía:  Sesion  →  EjercicioSesion  →  SerieRegistrada
//
// Todo es serializable (toMap / fromMap) para que al conectar Supabase no haya
// que tocar ni una línea de las pantallas. Los nombres de campo del mapa son
// los que usarán las columnas de la base de datos.
// ===========================================================================
// ---------------------------------------------------------------------------
// 21.1 ENUMERACIONES
// ---------------------------------------------------------------------------

/// Los nueve grupos del sistema Ranked.
enum GrupoMuscular {
  pecho,
  espalda,
  hombros,
  biceps,
  triceps,
  antebrazos,
  abdomen,
  piernas,
  pantorrillas;

  String get etiqueta {
    switch (this) {
      case GrupoMuscular.pecho:
        return 'Pecho';
      case GrupoMuscular.espalda:
        return 'Espalda';
      case GrupoMuscular.hombros:
        return 'Hombros';
      case GrupoMuscular.biceps:
        return 'Bíceps';
      case GrupoMuscular.triceps:
        return 'Tríceps';
      case GrupoMuscular.antebrazos:
        return 'Antebrazos';
      case GrupoMuscular.abdomen:
        return 'Abdomen';
      case GrupoMuscular.piernas:
        return 'Piernas';
      case GrupoMuscular.pantorrillas:
        return 'Pantorrillas';
    }
  }
}

enum TipoSerie {
  /// No cuenta para el volumen ni para los récords.
  calentamiento,

  /// La serie que cuenta.
  efectiva,

  /// Bajada de peso encadenada sin descanso.
  descuelgue,

  /// Se llegó al fallo muscular.
  fallo;
}

/// Permite medir simetría. `ambos` es lo normal; los unilaterales registran
/// cada lado por separado.
enum Lado { ambos, izquierdo, derecho }

enum Equipo {
  barra,
  mancuerna,
  maquina,
  polea,
  pesoCorporal,
  banda,
  kettlebell,

  /// Lo que hay en casa: garrafas de agua, botellas, una mochila con libros.
  casero,
}

enum EstadoSesion {
  /// Abierta ahora mismo. Si la app se cierra, se recupera desde aquí.
  enCurso,
  completada,

  /// Se abrió y se dejó a medias. Se conserva: la tasa de abandono es un
  /// dato valioso, no basura que haya que borrar.
  abandonada,
}

/// Cómo se sintió la sesión. Se pregunta una sola vez, al cerrar.
enum Sensacion { terrible, floja, normal, buena, excelente }

// ---------------------------------------------------------------------------
// 21.2 CATÁLOGO DE EJERCICIOS
//
// La definición de un ejercicio es fija y compartida. Lo que cambia entre
// usuarios es lo que registran de él.
// ---------------------------------------------------------------------------

class Ejercicio {
  const Ejercicio({
    required this.id,
    required this.nombre,
    required this.equipo,
    required this.reparto,
    this.unilateral = false,
    this.compuesto = true,
    this.cargaCorporal = 0,
    this.porTiempo = false,
  });

  final String id;
  final String nombre;
  final Equipo equipo;

  /// Parte del peso corporal que mueve cada repetición (flexión ≈ 0,64).
  /// Sin esto, una sesión en casa sumaba 0 kg y los músculos no subían en
  /// Ranked aunque se entrenaran a diario.
  final double cargaCorporal;

  /// Se registra en segundos, no en repeticiones (plancha, sentadilla en la
  /// pared). Tres segundos de aguante cuentan como una repetición.
  final bool porTiempo;

  /// Cómo se reparte el volumen entre músculos. Las fracciones suman 1.0.
  ///
  /// Es el corazón del modelo: sin esto, Ranked le daría todo el crédito al
  /// músculo principal y los sinergistas parecerían abandonados aunque los
  /// entrenes a diario.
  final Map<GrupoMuscular, double> reparto;

  /// Si es cierto, cada serie debe indicar el lado.
  final bool unilateral;

  /// Los compuestos otorgan algo más de XP: mueven más masa y cuestan más.
  final bool compuesto;

  GrupoMuscular get grupoPrincipal => reparto.entries
      .reduce((MapEntry<GrupoMuscular, double> a,
              MapEntry<GrupoMuscular, double> b) =>
          a.value >= b.value ? a : b)
      .key;
}

/// Catálogo base. Se ampliará, pero estos cubren la mayoría de rutinas y ya
/// permiten calcular todo el sistema.
const List<Ejercicio> catalogoEjercicios = <Ejercicio>[
  // -- Pecho ---------------------------------------------------------------
  Ejercicio(
    id: 'press_banca',
    nombre: 'Press de banca',
    equipo: Equipo.barra,
    reparto: <GrupoMuscular, double>{
      GrupoMuscular.pecho: 0.60,
      GrupoMuscular.triceps: 0.25,
      GrupoMuscular.hombros: 0.15,
    },
  ),
  Ejercicio(
    id: 'press_inclinado_mancuerna',
    nombre: 'Press inclinado con mancuernas',
    equipo: Equipo.mancuerna,
    reparto: <GrupoMuscular, double>{
      GrupoMuscular.pecho: 0.55,
      GrupoMuscular.hombros: 0.25,
      GrupoMuscular.triceps: 0.20,
    },
