/// Búsqueda por id. Devuelve null si el ejercicio no existe en el catálogo.
Ejercicio? ejercicioPorId(String id) => _indiceEjercicios[id];

final Map<String, Ejercicio> _indiceEjercicios = <String, Ejercicio>{
  for (final Ejercicio e in catalogoEjercicios) e.id: e,
};

/// El peso corporal con el que se calculan los ejercicios sin pesas: la última
/// medida de Cuerpo, si no el de Nutrición, y si no 70 kg. Se guarda unos
/// segundos porque el Ranked lo consulta miles de veces al recalcular.
class CargaCorporal {
  const CargaCorporal._();

  static double _kg = 70;
  static DateTime _leido = DateTime.fromMillisecondsSinceEpoch(0);

  static double get kg {
    final DateTime ahora = DateTime.now();
    if (ahora.difference(_leido).inSeconds < 5) return _kg;
    _leido = ahora;
    final String? u = SesionTemplo.instancia.actual?.usuario;
    double? v;
    if (u != null) {
      v = CuerpoTemplo.instancia.ultimoPeso(u) ?? AlmacenNutricion.instancia.de(u)?.pesoCorporal;
    }
    _kg = (v ?? 70.0).clamp(35.0, 200.0);
    return _kg;
  }

  /// Tras registrar un peso nuevo, que se note al momento.
  static void olvidar() => _leido = DateTime.fromMillisecondsSinceEpoch(0);
}

// ---------------------------------------------------------------------------
// 21.3 SERIE
// ---------------------------------------------------------------------------

class SerieRegistrada {
  const SerieRegistrada({
    required this.numero,
    required this.peso,
    required this.repeticiones,
    this.tipo = TipoSerie.efectiva,
    this.lado = Lado.ambos,
    this.completada = false,
    this.descansoSeg,
    this.rpe,
    this.registradaEn,
  });

  /// Orden dentro del ejercicio, empezando en 1.
  final int numero;

  /// Kilos. En peso corporal es el lastre añadido (0 si no hay).
  final double peso;
  final int repeticiones;
  final TipoSerie tipo;
  final Lado lado;
  final bool completada;

  /// Descanso real medido por el temporizador tras esta serie.
  /// Es una métrica gratis: sale sola, sin pedirle nada al usuario.
  final int? descansoSeg;

  /// Esfuerzo 1–10. Opcional a propósito: pedirlo en cada serie es lo que
  /// hace que la gente abandone el registro.
  final double? rpe;

  final DateTime? registradaEn;

  /// Solo las series que cuentan suman volumen.
  bool get cuenta =>
      completada &&
      (tipo == TipoSerie.efectiva ||
          tipo == TipoSerie.fallo ||
          tipo == TipoSerie.descuelgue);

  double get volumen => cuenta ? peso * repeticiones : 0;

  /// 1RM estimado por la fórmula de Epley. Por encima de 12 repeticiones
  /// pierde fiabilidad, así que se corta ahí en lugar de inventar cifras.
  double? get unaRepeticionMaxima {
    if (!cuenta || repeticiones == 0 || repeticiones > 12 || peso <= 0) {
      return null;
    }
    return peso * (1 + repeticiones / 30.0);
  }

  SerieRegistrada copyWith({
    int? numero,
    double? peso,
    int? repeticiones,
    TipoSerie? tipo,
    Lado? lado,
    bool? completada,
    int? descansoSeg,
    double? rpe,
    DateTime? registradaEn,
  }) {
    return SerieRegistrada(
      numero: numero ?? this.numero,
      peso: peso ?? this.peso,
      repeticiones: repeticiones ?? this.repeticiones,
      tipo: tipo ?? this.tipo,
      lado: lado ?? this.lado,
      completada: completada ?? this.completada,
      descansoSeg: descansoSeg ?? this.descansoSeg,
      rpe: rpe ?? this.rpe,
      registradaEn: registradaEn ?? this.registradaEn,
    );
  }

  Map<String, dynamic> toMap() => <String, dynamic>{
        'numero': numero,
        'peso': peso,
        'repeticiones': repeticiones,
        'tipo': tipo.name,
        'lado': lado.name,
        'completada': completada,
        'descanso_seg': descansoSeg,
        'rpe': rpe,
        'registrada_en': registradaEn?.toIso8601String(),
      };

  factory SerieRegistrada.fromMap(Map<String, dynamic> m) => SerieRegistrada(
        numero: m['numero'] as int,
        peso: (m['peso'] as num).toDouble(),
        repeticiones: m['repeticiones'] as int,
        tipo: TipoSerie.values.byName(m['tipo'] as String? ?? 'efectiva'),
        lado: Lado.values.byName(m['lado'] as String? ?? 'ambos'),
        completada: m['completada'] as bool? ?? false,
        descansoSeg: m['descanso_seg'] as int?,
        rpe: (m['rpe'] as num?)?.toDouble(),
        registradaEn: m['registrada_en'] == null
            ? null
            : DateTime.parse(m['registrada_en'] as String),
      );
}

// ---------------------------------------------------------------------------
// 21.4 EJERCICIO DENTRO DE LA SESIÓN
// ---------------------------------------------------------------------------

class EjercicioSesion {
  const EjercicioSesion({
    required this.ejercicioId,
    required this.orden,
    required this.series,
    this.notas,
  });

  final String ejercicioId;
  final int orden;
  final List<SerieRegistrada> series;
  final String? notas;

  Ejercicio? get definicion => ejercicioPorId(ejercicioId);
  String get nombre => definicion?.nombre ?? ejercicioId;

  List<SerieRegistrada> get seriesEfectivas =>
      series.where((SerieRegistrada s) => s.cuenta).toList();

  /// Kilos movidos. En los ejercicios con el propio cuerpo se suma la parte
  /// del peso corporal que se levanta; lo que se escribe en KG es lastre.
  double get volumen =>
      series.fold<double>(0, (double a, SerieRegistrada s) => a + _volumenDe(s));

  double _volumenDe(SerieRegistrada s) {
    if (!s.cuenta) return 0;
    final Ejercicio? d = definicion;
    if (d == null || (d.cargaCorporal <= 0 && !d.porTiempo)) return s.volumen;
    final double carga = s.peso + d.cargaCorporal * CargaCorporal.kg;
    return carga * s.repeticiones * (d.porTiempo ? 1 / 3 : 1);
  }

  int get repeticionesTotales => seriesEfectivas.fold<int>(
      0, (int a, SerieRegistrada s) => a + s.repeticiones);

  double get pesoMaximo => seriesEfectivas.isEmpty
      ? 0
      : seriesEfectivas
          .map((SerieRegistrada s) => s.peso)
          .reduce((double a, double b) => a > b ? a : b);

  double? get mejor1RM {
    final List<double> ests = seriesEfectivas
        .map((SerieRegistrada s) => s.unaRepeticionMaxima)
        .whereType<double>()
        .toList();
    if (ests.isEmpty) return null;
    return ests.reduce((double a, double b) => a > b ? a : b);
  }

  /// Volumen repartido entre los músculos que realmente trabajan.
  Map<GrupoMuscular, double> get volumenPorGrupo {
    final Ejercicio? d = definicion;
    if (d == null) return <GrupoMuscular, double>{};
    final double v = volumen;
    return d.reparto.map(
      (GrupoMuscular g, double f) => MapEntry<GrupoMuscular, double>(g, v * f),
    );
  }

  /// Volumen por lado. Base de la métrica de simetría.
  double volumenDelLado(Lado lado) => series
      .where((SerieRegistrada s) => s.lado == lado)
      .fold<double>(0, (double a, SerieRegistrada s) => a + _volumenDe(s));

  /// Descanso medio real, en segundos.
  int? get descansoMedio {
    final List<int> ds =
        series.map((SerieRegistrada s) => s.descansoSeg).whereType<int>().toList();
    if (ds.isEmpty) return null;
    return ds.reduce((int a, int b) => a + b) ~/ ds.length;
  }

  EjercicioSesion copyWith({
    int? orden,
    List<SerieRegistrada>? series,
    String? notas,
  }) =>
      EjercicioSesion(
        ejercicioId: ejercicioId,
        orden: orden ?? this.orden,
        series: series ?? this.series,
        notas: notas ?? this.notas,
      );

  Map<String, dynamic> toMap() => <String, dynamic>{
        'ejercicio_id': ejercicioId,
        'orden': orden,
        'notas': notas,
        'series':
            series.map((SerieRegistrada s) => s.toMap()).toList(growable: false),
      };

  factory EjercicioSesion.fromMap(Map<String, dynamic> m) => EjercicioSesion(
        ejercicioId: m['ejercicio_id'] as String,
        orden: m['orden'] as int,
        notas: m['notas'] as String?,
        series: (m['series'] as List<dynamic>)
            .map((dynamic s) =>
                SerieRegistrada.fromMap(s as Map<String, dynamic>))
            .toList(),
      );
}

// ---------------------------------------------------------------------------
// 21.5 SESIÓN
// ---------------------------------------------------------------------------

class Sesion {
  const Sesion({
    required this.id,
    required this.usuario,
    required this.inicio,
    required this.ejercicios,
    this.fin,
    this.estado = EstadoSesion.enCurso,
    this.rutinaId,
    this.nombre,
    this.disposicionAlIniciar,
    this.esfuerzoGlobal,
    this.sensacion,
    this.notas,
  });

  final String id;
  final String usuario;
  final DateTime inicio;
  final DateTime? fin;
  final EstadoSesion estado;
  final List<EjercicioSesion> ejercicios;

  /// Null si fue una sesión libre.
  final String? rutinaId;
  final String? nombre;

  /// Foto de la disposición en el momento de empezar (0–100).
  ///
  /// Sin esto no se puede saber después si un mal día fue por dormir poco o
  /// porque el plan estaba mal calibrado.
  final int? disposicionAlIniciar;

  /// Esfuerzo percibido de toda la sesión, 1–10. Se pregunta al cerrar.
  final double? esfuerzoGlobal;
  final Sensacion? sensacion;
  final String? notas;

  // -- Cálculos -----------------------------------------------------------

  Duration get duracion => (fin ?? DateTime.now()).difference(inicio);
  int get minutos => duracion.inMinutes;

  double get volumenTotal => ejercicios.fold<double>(
      0, (double a, EjercicioSesion e) => a + e.volumen);

  int get seriesEfectivas => ejercicios.fold<int>(
      0, (int a, EjercicioSesion e) => a + e.seriesEfectivas.length);

  int get repeticionesTotales => ejercicios.fold<int>(
      0, (int a, EjercicioSesion e) => a + e.repeticionesTotales);

  /// Kilos por minuto. No se puede falsear añadiendo series de relleno:
  /// mide si entrenaste o si estuviste con el móvil entre series.
  double get densidad => minutos <= 0 ? 0 : volumenTotal / minutos;

  int? get descansoMedio {
    final List<int> ds = ejercicios
        .map((EjercicioSesion e) => e.descansoMedio)
        .whereType<int>()
        .toList();
    if (ds.isEmpty) return null;
    return ds.reduce((int a, int b) => a + b) ~/ ds.length;
  }

  /// Volumen agregado por grupo muscular. Es lo que consume Ranked.
  Map<GrupoMuscular, double> get volumenPorGrupo {
    final Map<GrupoMuscular, double> total = <GrupoMuscular, double>{};
    for (final EjercicioSesion e in ejercicios) {
      e.volumenPorGrupo.forEach((GrupoMuscular g, double v) {
        total[g] = (total[g] ?? 0) + v;
      });
    }
    return total;
  }

  List<GrupoMuscular> get gruposTrabajados {
    final List<MapEntry<GrupoMuscular, double>> e =
        volumenPorGrupo.entries.toList()
          ..sort((MapEntry<GrupoMuscular, double> a,
                  MapEntry<GrupoMuscular, double> b) =>
              b.value.compareTo(a.value));
    return e
        .where((MapEntry<GrupoMuscular, double> x) => x.value > 0)
        .map((MapEntry<GrupoMuscular, double> x) => x.key)
        .toList();
  }

  /// Simetría 0–1 entre los dos lados en ejercicios unilaterales.
  /// Devuelve null si no hubo trabajo unilateral, para no inventar un dato.
  double? get simetria {
    double izq = 0;
    double der = 0;
    for (final EjercicioSesion e in ejercicios) {
      izq += e.volumenDelLado(Lado.izquierdo);
      der += e.volumenDelLado(Lado.derecho);
    }
    if (izq + der <= 0) return null;
    final double mayor = izq > der ? izq : der;
    final double menor = izq > der ? der : izq;
    return mayor <= 0 ? null : menor / mayor;
  }

  bool get estaVacia => volumenTotal <= 0 && seriesEfectivas == 0;

  // -- Serialización ------------------------------------------------------

  Sesion copyWith({
    DateTime? fin,
    EstadoSesion? estado,
    List<EjercicioSesion>? ejercicios,
    String? nombre,
    int? disposicionAlIniciar,
    double? esfuerzoGlobal,
    Sensacion? sensacion,
    String? notas,
  }) =>
      Sesion(
        id: id,
        usuario: usuario,
        inicio: inicio,
        fin: fin ?? this.fin,
        estado: estado ?? this.estado,
        ejercicios: ejercicios ?? this.ejercicios,
        rutinaId: rutinaId,
        nombre: nombre ?? this.nombre,
        disposicionAlIniciar: disposicionAlIniciar ?? this.disposicionAlIniciar,
        esfuerzoGlobal: esfuerzoGlobal ?? this.esfuerzoGlobal,
        sensacion: sensacion ?? this.sensacion,
        notas: notas ?? this.notas,
      );

  Map<String, dynamic> toMap() => <String, dynamic>{
        'id': id,
        'usuario': usuario,
        'inicio': inicio.toIso8601String(),
        'fin': fin?.toIso8601String(),
        'estado': estado.name,
        'rutina_id': rutinaId,
        'nombre': nombre,
        'disposicion_inicial': disposicionAlIniciar,
        'esfuerzo_global': esfuerzoGlobal,
        'sensacion': sensacion?.name,
        'notas': notas,
        'ejercicios': ejercicios
            .map((EjercicioSesion e) => e.toMap())
            .toList(growable: false),
      };

  factory Sesion.fromMap(Map<String, dynamic> m) => Sesion(
        id: m['id'] as String,
        usuario: m['usuario'] as String,
        inicio: DateTime.parse(m['inicio'] as String),
        fin: m['fin'] == null ? null : DateTime.parse(m['fin'] as String),
        estado:
            EstadoSesion.values.byName(m['estado'] as String? ?? 'completada'),
        rutinaId: m['rutina_id'] as String?,
        nombre: m['nombre'] as String?,
        disposicionAlIniciar: m['disposicion_inicial'] as int?,
        esfuerzoGlobal: (m['esfuerzo_global'] as num?)?.toDouble(),
        sensacion: m['sensacion'] == null
            ? null
            : Sensacion.values.byName(m['sensacion'] as String),
        notas: m['notas'] as String?,
        ejercicios: (m['ejercicios'] as List<dynamic>)
            .map((dynamic e) =>
                EjercicioSesion.fromMap(e as Map<String, dynamic>))
            .toList(),
      );
}

// ---------------------------------------------------------------------------
// 21.6 RÉCORDS PERSONALES
//
// Se recalculan al cerrar cada sesión. Alimentan el perfil y las
// notificaciones de «has roto un récord».
// ---------------------------------------------------------------------------

class RecordPersonal {
  const RecordPersonal({
    required this.ejercicioId,
    required this.pesoMaximo,
    required this.mejor1RM,
    required this.mejorVolumenSesion,
    required this.fecha,
  });

  final String ejercicioId;
  final double pesoMaximo;
  final double mejor1RM;
  final double mejorVolumenSesion;
  final DateTime fecha;

  Map<String, dynamic> toMap() => <String, dynamic>{
        'ejercicio_id': ejercicioId,
        'peso_maximo': pesoMaximo,
        'mejor_1rm': mejor1RM,
        'mejor_volumen_sesion': mejorVolumenSesion,
        'fecha': fecha.toIso8601String(),
      };

  factory RecordPersonal.fromMap(Map<String, dynamic> m) => RecordPersonal(
        ejercicioId: m['ejercicio_id'] as String,
        pesoMaximo: (m['peso_maximo'] as num).toDouble(),
        mejor1RM: (m['mejor_1rm'] as num).toDouble(),
        mejorVolumenSesion: (m['mejor_volumen_sesion'] as num).toDouble(),
        fecha: DateTime.parse(m['fecha'] as String),
      );
}

/// Qué récords rompió una sesión respecto a los que había.
class RecordRoto {
  const RecordRoto({
    required this.ejercicioId,
    required this.tipo,
    required this.anterior,
    required this.nuevo,
  });

  final String ejercicioId;

  /// 'peso', '1rm' o 'volumen'.
  final String tipo;
  final double anterior;
  final double nuevo;

  double get mejora => anterior <= 0 ? 1 : (nuevo - anterior) / anterior;
}

// ---------------------------------------------------------------------------
// 21.7 XP HACIA RANKED
//
// Una sola fórmula, en un solo sitio. Si algún día hay que reequilibrar el
// juego, se toca aquí y todo el sistema se mueve con ella.
// ---------------------------------------------------------------------------

class ReglasXp {
  const ReglasXp._();

  /// 1 XP por cada 100 kg de volumen repartido al grupo.
  static const double xpPorKilo = 0.01;

  /// Los compuestos mueven más masa y cuestan más: se premian.
  static const double bonoCompuesto = 1.15;

  /// XP fijo por romper un récord en ese grupo.
  static const double bonoRecord = 40;

  /// Suelo por sesión: aparecer y trabajar el grupo siempre cuenta algo,
  /// aunque haya sido un día flojo.
  static const double sueloPorGrupo = 5;

  static Map<GrupoMuscular, double> deSesion(
    Sesion sesion, {
    List<RecordRoto> records = const <RecordRoto>[],
  }) {
    final Map<GrupoMuscular, double> xp = <GrupoMuscular, double>{};

    for (final EjercicioSesion e in sesion.ejercicios) {
      final Ejercicio? d = e.definicion;
      if (d == null) continue;
      final double factor = d.compuesto ? bonoCompuesto : 1.0;

      e.volumenPorGrupo.forEach((GrupoMuscular g, double v) {
        if (v <= 0) return;
        xp[g] = (xp[g] ?? 0) + v * xpPorKilo * factor;
      });
    }

    for (final RecordRoto r in records) {
      final Ejercicio? d = ejercicioPorId(r.ejercicioId);
      if (d == null) continue;
      xp[d.grupoPrincipal] = (xp[d.grupoPrincipal] ?? 0) + bonoRecord;
    }

    return xp.map((GrupoMuscular g, double v) =>
        MapEntry<GrupoMuscular, double>(g, v < sueloPorGrupo ? sueloPorGrupo : v));
  }
}

// ---------------------------------------------------------------------------
// 21.8 PERFIL DE COMPORTAMIENTO
//
// Se deriva del historial completo. No se pregunta nada: se observa.
// Es lo que permite que Tenshi proponga sesiones que encajen con la vida real
// del usuario, y no con la que dijo tener el día del Ascenso.
// ---------------------------------------------------------------------------

class PerfilEntrenamiento {
  const PerfilEntrenamiento({
    required this.sesionesTotales,
    required this.horaHabitual,
    required this.duracionMediaMin,
    required this.diasHabituales,
    required this.tasaAbandono,
    required this.descansoMedioSeg,
    required this.seriesPorSesion,
    required this.diasDesdeGrupo,
    required this.volumenSemanalPorGrupo,
    required this.ejerciciosFrecuentes,
    required this.ejerciciosEvitados,
    required this.pesoDelTemplo,
  });

  final int sesionesTotales;

  /// Hora del día a la que suele entrenar (0–23).
  final int horaHabitual;
  final int duracionMediaMin;

  /// Días de la semana en que entrena de verdad (1 = lunes … 7 = domingo).
  final List<int> diasHabituales;

  /// Sesiones abandonadas / sesiones abiertas. Si sube, el plan es demasiado
  /// largo para el tiempo que tiene.
  final double tasaAbandono;

  final int descansoMedioSeg;
  final int seriesPorSesion;

  /// Días transcurridos desde la última vez que tocó cada grupo.
  /// Es la deuda del templo.
  final Map<GrupoMuscular, int> diasDesdeGrupo;

  final Map<GrupoMuscular, double> volumenSemanalPorGrupo;

  /// Ejercicios que más repite.
  final List<String> ejerciciosFrecuentes;

  /// Los que estaban en la rutina y salta una y otra vez. Tenshi deja de
  /// proponerlos y busca un sustituto para el mismo grupo.
  final List<String> ejerciciosEvitados;

  /// Kilos acumulados desde siempre. Nunca baja.
  final double pesoDelTemplo;

  /// Los tres grupos con más deuda, de mayor a menor.
  List<GrupoMuscular> get gruposEnDeuda {
    final List<MapEntry<GrupoMuscular, int>> e = diasDesdeGrupo.entries.toList()
      ..sort((MapEntry<GrupoMuscular, int> a, MapEntry<GrupoMuscular, int> b) =>
          b.value.compareTo(a.value));
    return e.take(3).map((MapEntry<GrupoMuscular, int> x) => x.key).toList();
  }

  static const PerfilEntrenamiento vacio = PerfilEntrenamiento(
    sesionesTotales: 0,
    horaHabitual: 18,
    duracionMediaMin: 50,
    diasHabituales: <int>[],
    tasaAbandono: 0,
    descansoMedioSeg: 90,
    seriesPorSesion: 0,
    diasDesdeGrupo: <GrupoMuscular, int>{},
    volumenSemanalPorGrupo: <GrupoMuscular, double>{},
    ejerciciosFrecuentes: <String>[],
    ejerciciosEvitados: <String>[],
    pesoDelTemplo: 0,
  );
}
