// ---------------------------------------------------------------------------
// 22.1 REGISTRO DIARIO
//
// Lo que el usuario aporta con tres toques al final del día. Nada más se le
// pide fuera de la sesión.
// ---------------------------------------------------------------------------

class RegistroDiario {
  const RegistroDiario({
    required this.fecha,
    this.horasSueno,
    this.vasosAgua = 0,
    this.animo,
  });

  final DateTime fecha;
  final double? horasSueno;
  final int vasosAgua;
  final Sensacion? animo;

  String get clave =>
      '${fecha.year}-${fecha.month.toString().padLeft(2, '0')}-'
      '${fecha.day.toString().padLeft(2, '0')}';

  RegistroDiario copyWith({
    double? horasSueno,
    int? vasosAgua,
    Sensacion? animo,
  }) =>
      RegistroDiario(
        fecha: fecha,
        horasSueno: horasSueno ?? this.horasSueno,
        vasosAgua: vasosAgua ?? this.vasosAgua,
        animo: animo ?? this.animo,
      );

  Map<String, dynamic> toMap() => <String, dynamic>{
        'fecha': fecha.toIso8601String(),
        'horas_sueno': horasSueno,
        'vasos_agua': vasosAgua,
        'animo': animo?.name,
      };
}

// ---------------------------------------------------------------------------
// 22.2 NIVEL Y RANGO
//
// Una sola fuente de verdad para la progresión general. El nivel no sale de
// PerfilUsuario: se deriva del XP acumulado, así nunca se desincroniza.
// ---------------------------------------------------------------------------

class NivelTemplo {
  const NivelTemplo({
    required this.nivel,
    required this.xpEnNivel,
    required this.xpParaSiguiente,
    required this.rango,
    required this.rangoEspecial,
  });

  final int nivel;
  final int xpEnNivel;
  final int xpParaSiguiente;
  final String rango;
  final bool rangoEspecial;

  double get progreso =>
      xpParaSiguiente <= 0 ? 0 : (xpEnNivel / xpParaSiguiente).clamp(0.0, 1.0);

  /// Coste del nivel n. Sube un 11% cada vez: al principio se avanza rápido,
  /// después cada nivel cuesta de verdad.
  static int costeDeNivel(int n) => (400 * math.pow(1.11, n - 1)).round();

  static NivelTemplo desdeXp(double xpTotal) {
    int nivel = 1;
    double restante = xpTotal;
    while (restante >= costeDeNivel(nivel) && nivel < 200) {
      restante -= costeDeNivel(nivel);
      nivel++;
    }
    final String rango;
    final bool especial;
    if (nivel < 5) {
      rango = 'Aprendiz';
      especial = false;
    } else if (nivel < 10) {
      rango = 'Discípulo';
      especial = false;
    } else if (nivel < 20) {
      rango = 'Guerrero';
      especial = false;
    } else if (nivel < 35) {
      rango = 'Samurái';
      especial = false;
    } else if (nivel < 50) {
      rango = 'Samurái Élite';
      especial = false;
    } else if (nivel < 75) {
      rango = 'Maestro del Templo';
      especial = true;
    } else {
      rango = 'Leyenda';
      especial = true;
    }
    return NivelTemplo(
      nivel: nivel,
      xpEnNivel: restante.round(),
      xpParaSiguiente: costeDeNivel(nivel),
      rango: rango,
      rangoEspecial: especial,
    );
  }
}

// ---------------------------------------------------------------------------
// 22.3 LA LLAMA
//
// Constancia que se apaga poco a poco, nunca de golpe. Quien se enferma tres
// días vuelve a una brasa, no a cenizas: las rachas que se rompen enteras son
// las que hacen que la gente abandone.
// ---------------------------------------------------------------------------

enum EstadoLlama { apagada, brasa, viva, ardiente, sagrada }

class Llama {
  const Llama({
    required this.valor,
    required this.diasSeguidos,
    required this.diasSinEntrenar,
  });

  final int valor; // 0–100
  final int diasSeguidos;
  final int diasSinEntrenar;

  EstadoLlama get estado {
    if (valor < 15) return EstadoLlama.apagada;
    if (valor < 40) return EstadoLlama.brasa;
    if (valor < 65) return EstadoLlama.viva;
    if (valor < 88) return EstadoLlama.ardiente;
    return EstadoLlama.sagrada;
  }

  String get etiqueta {
    switch (estado) {
      case EstadoLlama.apagada:
        return 'Apagada';
      case EstadoLlama.brasa:
        return 'Brasa';
      case EstadoLlama.viva:
        return 'Viva';
      case EstadoLlama.ardiente:
        return 'Ardiente';
      case EstadoLlama.sagrada:
        return 'Sagrada';
    }
  }

  String get mensaje {
    switch (estado) {
      case EstadoLlama.apagada:
        return 'Una sola sesión vuelve a encenderla.';
      case EstadoLlama.brasa:
        return 'Queda rescoldo. No se ha perdido nada.';
      case EstadoLlama.viva:
        return 'Vas sosteniendo el ritmo.';
      case EstadoLlama.ardiente:
        return 'Esto ya es un hábito, no un esfuerzo.';
      case EstadoLlama.sagrada:
        return 'El templo arde por ti.';
    }
  }
}

// ---------------------------------------------------------------------------
// 22.4 DISPOSICIÓN
//
// Cuánto puede pedirte hoy el templo. No es decorativa: cambia la sesión que
// se propone.
// ---------------------------------------------------------------------------

enum EstadoDisposicion { agotado, cansado, estable, listo, enSuPunto }

class Disposicion {
  const Disposicion({required this.valor, required this.motivos});

  final int valor; // 0–100

  /// Qué la subió o la bajó. Se muestra al usuario: un número sin explicación
  /// no cambia comportamiento.
  final List<String> motivos;

  EstadoDisposicion get estado {
    if (valor < 25) return EstadoDisposicion.agotado;
    if (valor < 45) return EstadoDisposicion.cansado;
    if (valor < 65) return EstadoDisposicion.estable;
    if (valor < 85) return EstadoDisposicion.listo;
    return EstadoDisposicion.enSuPunto;
  }

  String get etiqueta {
    switch (estado) {
      case EstadoDisposicion.agotado:
        return 'Agotado';
      case EstadoDisposicion.cansado:
        return 'Cansado';
      case EstadoDisposicion.estable:
        return 'Estable';
      case EstadoDisposicion.listo:
        return 'Listo';
      case EstadoDisposicion.enSuPunto:
        return 'En su punto';
    }
  }

  String get consejo {
    switch (estado) {
      case EstadoDisposicion.agotado:
        return 'Hoy toca sostener, no romper. Sesión corta.';
      case EstadoDisposicion.cansado:
        return 'Baja el peso y cuida la técnica.';
      case EstadoDisposicion.estable:
        return 'Buen día para el trabajo de siempre.';
      case EstadoDisposicion.listo:
        return 'Puedes empujar en el ejercicio principal.';
      case EstadoDisposicion.enSuPunto:
        return 'Día de récord si lo hay.';
    }
  }
}

// ---------------------------------------------------------------------------
// 22.5 DATOS Y ALMACÉN
//
// Todo el progreso de una persona vive aquí. Es la clase que se sustituirá
// por Supabase: los métodos ya tienen la forma de las consultas futuras.
// ---------------------------------------------------------------------------

class DatosUsuario {
  DatosUsuario(this.usuario);

  final String usuario;

  /// Respuestas de El Ascenso. Definen objetivo, días, lugar, enfoque y voz.
  Map<String, String> ascenso = <String, String>{};

  final List<Sesion> sesiones = <Sesion>[];
  final Map<String, RecordPersonal> records = <String, RecordPersonal>{};
  final Map<GrupoMuscular, double> xpPorGrupo = <GrupoMuscular, double>{};
  final Map<String, RegistroDiario> diario = <String, RegistroDiario>{};

  double xpGeneral = 0;

  /// Sesión abierta, si la hay. Permite recuperar tras cerrar la app.
  Sesion? enCurso;

  List<Sesion> get completadas => sesiones
      .where((Sesion s) => s.estado == EstadoSesion.completada)
      .toList();
}

class AlmacenTemplo {
  AlmacenTemplo._();
  static final AlmacenTemplo instancia = AlmacenTemplo._();

  final Map<String, DatosUsuario> _datos = <String, DatosUsuario>{};

  DatosUsuario de(String usuario) =>
      _datos.putIfAbsent(usuario, () => DatosUsuario(usuario));

  // -- Ascenso -------------------------------------------------------------

  void guardarAscenso(String usuario, Map<String, String> respuestas) {
    de(usuario).ascenso = Map<String, String>.from(respuestas);
  }

  /// Días de entrenamiento a la semana que el usuario dijo poder sostener.
  double diasObjetivo(String usuario) {
    switch (de(usuario).ascenso['dias']) {
      case '2':
        return 2;
      case '5':
        return 5;
      case '6':
        return 6;
      default:
        return 3.5;
    }
  }

  // -- Sesiones ------------------------------------------------------------

  Sesion abrirSesion(String usuario, PlanSesion plan, int disposicion) {
    final Sesion s = Sesion(
      id: 'ses_${DateTime.now().microsecondsSinceEpoch}',
      usuario: usuario,
      inicio: DateTime.now(),
      nombre: plan.nombre,
      disposicionAlIniciar: disposicion,
      ejercicios: <EjercicioSesion>[
        for (int i = 0; i < plan.ejercicios.length; i++)
          EjercicioSesion(
            ejercicioId: plan.ejercicios[i].ejercicioId,
            orden: i,
            series: plan.ejercicios[i].seriesIniciales(),
          ),
      ],
    );
    de(usuario).enCurso = s;
    return s;
  }

  /// Guardado continuo: se llama tras cada serie marcada.
  void actualizarEnCurso(String usuario, Sesion s) {
    de(usuario).enCurso = s;
  }

  void descartarEnCurso(String usuario) {
    final DatosUsuario d = de(usuario);
    final Sesion? s = d.enCurso;
    if (s != null && !s.estaVacia) {
      d.sesiones.add(s.copyWith(
        estado: EstadoSesion.abandonada,
        fin: DateTime.now(),
      ));
    }
    d.enCurso = null;
  }

  /// Cierra la sesión, recalcula récords y reparte XP.
  ResumenCierre cerrarSesion(
    String usuario,
    Sesion sesion, {
    double? esfuerzo,
    Sensacion? sensacion,
  }) {
    final DatosUsuario d = de(usuario);

    final Sesion cerrada = sesion.copyWith(
      estado: EstadoSesion.completada,
      fin: DateTime.now(),
      esfuerzoGlobal: esfuerzo,
      sensacion: sensacion,
    );

    // Récords.
    final List<RecordRoto> rotos = <RecordRoto>[];
    for (final EjercicioSesion e in cerrada.ejercicios) {
      if (e.seriesEfectivas.isEmpty) continue;
      final RecordPersonal? previo = d.records[e.ejercicioId];
      final double nuevo1RM = e.mejor1RM ?? 0;

      if (previo == null) {
        d.records[e.ejercicioId] = RecordPersonal(
          ejercicioId: e.ejercicioId,
          pesoMaximo: e.pesoMaximo,
          mejor1RM: nuevo1RM,
          mejorVolumenSesion: e.volumen,
          fecha: DateTime.now(),
        );
        continue;
      }
      if (e.pesoMaximo > previo.pesoMaximo) {
        rotos.add(RecordRoto(
          ejercicioId: e.ejercicioId,
          tipo: 'peso',
          anterior: previo.pesoMaximo,
          nuevo: e.pesoMaximo,
        ));
      }
      if (e.volumen > previo.mejorVolumenSesion) {
        rotos.add(RecordRoto(
          ejercicioId: e.ejercicioId,
          tipo: 'volumen',
          anterior: previo.mejorVolumenSesion,
          nuevo: e.volumen,
        ));
      }
      d.records[e.ejercicioId] = RecordPersonal(
        ejercicioId: e.ejercicioId,
        pesoMaximo:
            e.pesoMaximo > previo.pesoMaximo ? e.pesoMaximo : previo.pesoMaximo,
        mejor1RM: nuevo1RM > previo.mejor1RM ? nuevo1RM : previo.mejor1RM,
        mejorVolumenSesion: e.volumen > previo.mejorVolumenSesion
            ? e.volumen
            : previo.mejorVolumenSesion,
        fecha: DateTime.now(),
      );
    }

    // XP.
    final NivelTemplo antes = NivelTemplo.desdeXp(d.xpGeneral);
    final Map<GrupoMuscular, double> xp =
        ReglasXp.deSesion(cerrada, records: rotos);
    double total = 0;
    xp.forEach((GrupoMuscular g, double v) {
      d.xpPorGrupo[g] = (d.xpPorGrupo[g] ?? 0) + v;
      total += v;
    });
    d.xpGeneral += total;
    final NivelTemplo despues = NivelTemplo.desdeXp(d.xpGeneral);

    final double pesoAntes = pesoDelTemplo(usuario);
    d.sesiones.add(cerrada);
    d.enCurso = null;
    final double pesoDespues = pesoDelTemplo(usuario);

    return ResumenCierre(
      sesion: cerrada,
      records: rotos,
      xpPorGrupo: xp,
      xpTotal: total,
      nivelAntes: antes,
      nivelDespues: despues,
      pesoTemploAntes: pesoAntes,
      pesoTemploDespues: pesoDespues,
      piezaDesbloqueada: PiezasDelTemplo.nuevaEntre(pesoAntes, pesoDespues),
    );
  }

  // -- Métricas ------------------------------------------------------------

  double pesoDelTemplo(String usuario) => de(usuario)
      .completadas
      .fold<double>(0, (double a, Sesion s) => a + s.volumenTotal);

  bool entrenoEse(String usuario, DateTime dia) => de(usuario)
      .completadas
      .any((Sesion s) => _mismoDia(s.inicio, dia));

  static bool _mismoDia(DateTime a, DateTime b) =>
      a.year == b.year && a.month == b.month && a.day == b.day;

  /// Días desde la última vez que se trabajó cada grupo. 99 = nunca.
  Map<GrupoMuscular, int> deuda(String usuario) {
    final DateTime hoy = DateTime.now();
    final Map<GrupoMuscular, int> r = <GrupoMuscular, int>{};
    for (final GrupoMuscular g in GrupoMuscular.values) {
      int dias = 99;
      for (final Sesion s in de(usuario).completadas) {
        final double v = s.volumenPorGrupo[g] ?? 0;
        if (v <= 0) continue;
        final int d = hoy.difference(s.inicio).inDays;
        if (d < dias) dias = d;
      }
      r[g] = dias;
    }
    return r;
  }

  Llama llama(String usuario) {
    final double objetivo = diasObjetivo(usuario);
    final int descansoPermitido = (7 / objetivo).ceil();

    double v = 0;
    int sinEntrenar = 0;
    int seguidos = 0;
    final DateTime hoy = DateTime.now();

    for (int i = 27; i >= 0; i--) {
      final DateTime dia = hoy.subtract(Duration(days: i));
      if (entrenoEse(usuario, dia)) {
        v = math.min(100, v + 18);
        sinEntrenar = 0;
        seguidos++;
      } else {
        sinEntrenar++;
        seguidos = 0;
        if (sinEntrenar > descansoPermitido) {
          v = math.max(0, v - 6.0 * (sinEntrenar - descansoPermitido));
        }
      }
    }

    return Llama(
      valor: v.round(),
      diasSeguidos: seguidos,
      diasSinEntrenar: sinEntrenar,
    );
  }

  RegistroDiario registroDe(String usuario, DateTime dia) {
    final RegistroDiario base = RegistroDiario(fecha: dia);
    return de(usuario).diario[base.clave] ?? base;
  }

  void guardarRegistro(String usuario, RegistroDiario r) {
    de(usuario).diario[r.clave] = r;
  }

  /// Disposición del día. Suma y resta desde una base neutra, y guarda el
  /// motivo de cada ajuste para poder explicárselo al usuario.
  Disposicion disposicion(String usuario, List<GrupoMuscular> gruposDeHoy) {
    final List<String> motivos = <String>[];
    double v = 50;

    final RegistroDiario hoy = registroDe(usuario, DateTime.now());
    final double? sueno = hoy.horasSueno ??
        registroDe(usuario, DateTime.now().subtract(const Duration(days: 1)))
            .horasSueno;

    if (sueno != null) {
      final double ajuste = ((sueno - 7) * 6).clamp(-20.0, 15.0);
      v += ajuste;
      if (ajuste <= -8) {
        motivos.add('Dormiste poco (${sueno.toStringAsFixed(1)} h)');
      } else if (ajuste >= 6) {
        motivos.add('Buen descanso (${sueno.toStringAsFixed(1)} h)');
      }
    }

    // Descanso del grupo que toca hoy.
    if (gruposDeHoy.isNotEmpty) {
      final Map<GrupoMuscular, int> d = deuda(usuario);
      final int dias = gruposDeHoy
          .map((GrupoMuscular g) => d[g] ?? 99)
          .reduce((int a, int b) => a < b ? a : b);
      if (dias == 0) {
        v -= 15;
        motivos.add('Ya entrenaste ese grupo hoy');
      } else if (dias == 1) {
        v -= 5;
        motivos.add('Solo un día de descanso');
      } else if (dias <= 4) {
        v += 10;
        motivos.add('El grupo está recuperado');
      } else if (dias < 90) {
        v += 4;
      }
    }

    // Resaca de la última sesión.
    final List<Sesion> c = de(usuario).completadas;
    if (c.isNotEmpty) {
      final Sesion ultima = c.last;
      final int horas = DateTime.now().difference(ultima.inicio).inHours;
      if (horas < 24 && (ultima.esfuerzoGlobal ?? 0) >= 8.5) {
        v -= 12;
        motivos.add('Ayer fue una sesión dura');
      }
    }

    final Llama l = llama(usuario);
    v += l.valor / 4.0;
    if (l.valor >= 65) motivos.add('La llama te sostiene');

    return Disposicion(
      valor: v.clamp(0, 100).round(),
      motivos: motivos,
    );
  }

  /// Perfil de comportamiento derivado del historial. No pregunta: observa.
  PerfilEntrenamiento perfil(String usuario) {
    final DatosUsuario d = de(usuario);
    final List<Sesion> c = d.completadas;
    if (c.isEmpty) return PerfilEntrenamiento.vacio;

    final Map<int, int> horas = <int, int>{};
    final Map<int, int> dias = <int, int>{};
    int minutos = 0;
    int series = 0;
    final List<int> descansos = <int>[];
    final Map<String, int> frecuencia = <String, int>{};

    for (final Sesion s in c) {
      horas[s.inicio.hour] = (horas[s.inicio.hour] ?? 0) + 1;
      dias[s.inicio.weekday] = (dias[s.inicio.weekday] ?? 0) + 1;
      minutos += s.minutos;
      series += s.seriesEfectivas;
      final int? dm = s.descansoMedio;
      if (dm != null) descansos.add(dm);
      for (final EjercicioSesion e in s.ejercicios) {
        if (e.seriesEfectivas.isNotEmpty) {
          frecuencia[e.ejercicioId] = (frecuencia[e.ejercicioId] ?? 0) + 1;
        }
      }
    }

    int modaDe(Map<int, int> m, int porDefecto) {
      if (m.isEmpty) return porDefecto;
      return m.entries
          .reduce((MapEntry<int, int> a, MapEntry<int, int> b) =>
              a.value >= b.value ? a : b)
          .key;
    }

    final List<MapEntry<String, int>> ordenados = frecuencia.entries.toList()
      ..sort((MapEntry<String, int> a, MapEntry<String, int> b) =>
          b.value.compareTo(a.value));

    // Ejercicios que estaban en la sesión pero nunca se completaron.
    final Map<String, int> saltados = <String, int>{};
    for (final Sesion s in c) {
      for (final EjercicioSesion e in s.ejercicios) {
        if (e.seriesEfectivas.isEmpty) {
          saltados[e.ejercicioId] = (saltados[e.ejercicioId] ?? 0) + 1;
        }
      }
    }
    final List<String> evitados = saltados.entries
        .where((MapEntry<String, int> e) => e.value >= 2)
        .map((MapEntry<String, int> e) => e.key)
        .toList();

    final int abiertas = d.sesiones.length;
    final int abandonadas = d.sesiones
        .where((Sesion s) => s.estado == EstadoSesion.abandonada)
        .length;

    final DateTime haceSemana =
        DateTime.now().subtract(const Duration(days: 7));
    final Map<GrupoMuscular, double> semanal = <GrupoMuscular, double>{};
    for (final Sesion s in c) {
      if (s.inicio.isBefore(haceSemana)) continue;
      s.volumenPorGrupo.forEach((GrupoMuscular g, double v) {
        semanal[g] = (semanal[g] ?? 0) + v;
      });
    }

    return PerfilEntrenamiento(
      sesionesTotales: c.length,
      horaHabitual: modaDe(horas, 18),
      duracionMediaMin: minutos ~/ c.length,
      diasHabituales: (dias.entries.toList()
            ..sort((MapEntry<int, int> a, MapEntry<int, int> b) =>
                b.value.compareTo(a.value)))
          .take(4)
          .map((MapEntry<int, int> e) => e.key)
          .toList(),
      tasaAbandono: abiertas == 0 ? 0 : abandonadas / abiertas,
      descansoMedioSeg: descansos.isEmpty
          ? 90
          : descansos.reduce((int a, int b) => a + b) ~/ descansos.length,
      seriesPorSesion: series ~/ c.length,
      diasDesdeGrupo: deuda(usuario),
      volumenSemanalPorGrupo: semanal,
      ejerciciosFrecuentes:
          ordenados.take(6).map((MapEntry<String, int> e) => e.key).toList(),
      ejerciciosEvitados: evitados,
      pesoDelTemplo: pesoDelTemplo(usuario),
    );
  }

  /// Último peso usado en un ejercicio, para prellenar la sesión siguiente.
  SerieRegistrada? ultimaSerieDe(String usuario, String ejercicioId) {
    for (final Sesion s in de(usuario).completadas.reversed) {
      for (final EjercicioSesion e in s.ejercicios) {
        if (e.ejercicioId == ejercicioId && e.seriesEfectivas.isNotEmpty) {
          return e.seriesEfectivas.last;
        }
      }
    }
    return null;
  }

  /// Volumen por día de los últimos siete, normalizado al mejor día.
  List<DiaSemana> semana(String usuario) {
    const List<String> ini = <String>['L', 'M', 'X', 'J', 'V', 'S', 'D'];
    final DateTime hoy = DateTime.now();
    final List<double> vols = <double>[];
    final List<DateTime> fechas = <DateTime>[];

    for (int i = 6; i >= 0; i--) {
      final DateTime dia = hoy.subtract(Duration(days: i));
      fechas.add(dia);
      vols.add(de(usuario).completadas.fold<double>(
            0,
            (double a, Sesion s) =>
                a + (_mismoDia(s.inicio, dia) ? s.volumenTotal : 0),
          ));
    }

    final double mejor = vols.fold<double>(0, math.max);
    return <DiaSemana>[
      for (int i = 0; i < 7; i++)
        DiaSemana(
          inicial: ini[fechas[i].weekday - 1],
          valor: mejor <= 0 ? 0 : vols[i] / mejor,
          esHoy: i == 6,
        ),
    ];
  }
}

// ---------------------------------------------------------------------------
// 22.6 PIEZAS DEL TEMPLO
//
// El peso acumulado levanta la Casa. Aquí es donde «cada repetición levanta el
// templo» deja de ser un lema y se vuelve mecánica.
// ---------------------------------------------------------------------------

class PiezaTemplo {
  const PiezaTemplo({
    required this.kilos,
    required this.nombre,
    required this.descripcion,
  });

  final double kilos;
  final String nombre;
  final String descripcion;
}

class PiezasDelTemplo {
  const PiezasDelTemplo._();

  static const List<PiezaTemplo> todas = <PiezaTemplo>[
    PiezaTemplo(
      kilos: 5000,
      nombre: 'El sendero',
      descripcion: 'Las primeras piedras marcan el camino hasta la puerta.',
    ),
    PiezaTemplo(
      kilos: 25000,
      nombre: 'El torii',
      descripcion: 'La puerta se levanta. Ya hay un umbral que cruzar.',
    ),
    PiezaTemplo(
      kilos: 60000,
      nombre: 'El estanque',
      descripcion: 'El agua refleja la luna. El templo respira.',
    ),
    PiezaTemplo(
      kilos: 120000,
      nombre: 'La campana',
      descripcion: 'Suena al amanecer. Se oye desde el valle.',
    ),
    PiezaTemplo(
      kilos: 220000,
      nombre: 'El jardín seco',
      descripcion: 'Quince piedras y arena rastrillada. Nadie las ve todas.',
    ),
    PiezaTemplo(
      kilos: 400000,
      nombre: 'La pagoda',
      descripcion: 'Cinco pisos sobre el bosque. Se ve desde lejos.',
    ),
    PiezaTemplo(
      kilos: 750000,
      nombre: 'El bosque de bambú',
      descripcion: 'Cerró el templo por completo. Ya es un lugar.',
    ),
  ];

  static PiezaTemplo? siguienteTras(double kilos) {
    for (final PiezaTemplo p in todas) {
      if (kilos < p.kilos) return p;
    }
    return null;
  }

  static PiezaTemplo? nuevaEntre(double antes, double despues) {
    for (final PiezaTemplo p in todas) {
      if (antes < p.kilos && despues >= p.kilos) return p;
    }
    return null;
  }

  static int desbloqueadas(double kilos) =>
      todas.where((PiezaTemplo p) => kilos >= p.kilos).length;
}

class ResumenCierre {
  const ResumenCierre({
    required this.sesion,
    required this.records,
    required this.xpPorGrupo,
    required this.xpTotal,
    required this.nivelAntes,
    required this.nivelDespues,
    required this.pesoTemploAntes,
    required this.pesoTemploDespues,
    this.piezaDesbloqueada,
  });

  final Sesion sesion;
  final List<RecordRoto> records;
  final Map<GrupoMuscular, double> xpPorGrupo;
  final double xpTotal;
  final NivelTemplo nivelAntes;
  final NivelTemplo nivelDespues;
  final double pesoTemploAntes;
  final double pesoTemploDespues;
  final PiezaTemplo? piezaDesbloqueada;

  bool get subioNivel => nivelDespues.nivel > nivelAntes.nivel;
}

// ---------------------------------------------------------------------------
// 23. GENERADOR DE RUTINA
//
// Cruza lo que el usuario dijo en El Ascenso con lo que de verdad hace: la
// deuda muscular, su disposición de hoy y los ejercicios que evita. Dos
// personas con el mismo objetivo reciben sesiones distintas al tercer mes.
// ---------------------------------------------------------------------------

class EjercicioPlan {
  const EjercicioPlan({
    required this.ejercicioId,
    required this.series,
    required this.repsObjetivo,
    this.pesoSugerido,
  });

  final String ejercicioId;
  final int series;
  final int repsObjetivo;
  final double? pesoSugerido;

  String get nombre => ejercicioPorId(ejercicioId)?.nombre ?? ejercicioId;

  List<SerieRegistrada> seriesIniciales() => <SerieRegistrada>[
        for (int i = 1; i <= series; i++)
          SerieRegistrada(
            numero: i,
            peso: pesoSugerido ?? 0,
            repeticiones: repsObjetivo,
          ),
      ];
}

class PlanSesion {
  const PlanSesion({
    required this.nombre,
    required this.grupos,
    required this.ejercicios,
    required this.minutos,
    required this.razon,
  });

  final String nombre;
  final List<GrupoMuscular> grupos;
  final List<EjercicioPlan> ejercicios;
  final int minutos;

  /// Por qué esta sesión y no otra. Se le enseña al usuario: una rutina que
  /// no se explica se siente arbitraria.
  final String razon;

  String get resumenGrupos =>
      grupos.map((GrupoMuscular g) => g.etiqueta).join(' · ');
  int get seriesTotales =>
      ejercicios.fold<int>(0, (int a, EjercicioPlan e) => a + e.series);
}

class GeneradorRutina {
  const GeneradorRutina._();

  /// Bloques de grupos que se entrenan juntos.
  static const Map<String, List<GrupoMuscular>> _bloques =
      <String, List<GrupoMuscular>>{
    'Empuje': <GrupoMuscular>[
      GrupoMuscular.pecho,
      GrupoMuscular.hombros,
      GrupoMuscular.triceps,
    ],
    'Tirón': <GrupoMuscular>[
      GrupoMuscular.espalda,
      GrupoMuscular.biceps,
      GrupoMuscular.antebrazos,
    ],
    'Pierna': <GrupoMuscular>[
      GrupoMuscular.piernas,
      GrupoMuscular.pantorrillas,
      GrupoMuscular.abdomen,
    ],
    'Cuerpo completo': <GrupoMuscular>[
      GrupoMuscular.piernas,
      GrupoMuscular.espalda,
      GrupoMuscular.pecho,
      GrupoMuscular.abdomen,
    ],
  };

  static List<Equipo> _equipoDisponible(String? lugar) {
    switch (lugar) {
      case 'casa':
        return <Equipo>[
          Equipo.pesoCorporal,
          Equipo.mancuerna,
          Equipo.banda,
          Equipo.kettlebell,
          Equipo.casero,
        ];
      case 'aire':
        return <Equipo>[Equipo.pesoCorporal, Equipo.banda];
      default:
        // En el gimnasio no hace falta cargar garrafas.
        return Equipo.values.where((Equipo e) => e != Equipo.casero).toList();
    }
  }

  static int _repsPara(String? objetivo) {
    switch (objetivo) {
      case 'fuerza':
        return 5;
      case 'grasa':
        return 14;
      case 'salud':
        return 12;
      default:
        return 10;
    }
  }

  static int _seriesPara(String? experiencia) {
    switch (experiencia) {
      case 'novato':
        return 3;
      case 'avanzado':
        return 4;
      case 'medio':
        return 4;
      default:
        return 3;
    }
  }

  static PlanSesion generar({
    required String usuario,
    required Disposicion disposicion,
  }) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final Map<String, String> asc = a.de(usuario).ascenso;
    final Map<GrupoMuscular, int> deuda = a.deuda(usuario);
    final PerfilEntrenamiento p = a.perfil(usuario);

    // 1. Bloque con más deuda acumulada.
    String mejorNombre = 'Cuerpo completo';
    double mejorDeuda = -1;
    final bool cuerpoCompleto = a.diasObjetivo(usuario) <= 2;

    if (!cuerpoCompleto) {
      _bloques.forEach((String nombre, List<GrupoMuscular> gs) {
        if (nombre == 'Cuerpo completo') return;
        final double d = gs
                .map((GrupoMuscular g) => (deuda[g] ?? 99).clamp(0, 14))
                .fold<int>(0, (int x, int y) => x + y) /
            gs.length;
        if (d > mejorDeuda) {
          mejorDeuda = d;
          mejorNombre = nombre;
        }
      });
    }

    final List<GrupoMuscular> grupos = _bloques[mejorNombre]!;

    // 2. Cuánta sesión aguanta hoy.
    final int cuantos;
    if (disposicion.valor < 45) {
      cuantos = 4;
    } else if (disposicion.valor < 70) {
      cuantos = 5;
    } else {
      cuantos = 6;
    }

    final int series = _seriesPara(asc['experiencia']);
    final int reps = _repsPara(asc['objetivo']);
    final List<Equipo> equipos = _equipoDisponible(asc['lugar']);

    // 3. Elegir ejercicios: los que tocan el bloque, con el material que
    //    tiene, descartando los que siempre salta.
    final List<Ejercicio> candidatos = catalogoEjercicios
        .where((Ejercicio e) =>
            equipos.contains(e.equipo) &&
            grupos.contains(e.grupoPrincipal) &&
            !p.ejerciciosEvitados.contains(e.id))
        .toList();

    // Primero compuestos, y dentro de ellos, los del grupo con más deuda.
    candidatos.sort((Ejercicio x, Ejercicio y) {
      if (x.compuesto != y.compuesto) return x.compuesto ? -1 : 1;
      final int dx = deuda[x.grupoPrincipal] ?? 99;
      final int dy = deuda[y.grupoPrincipal] ?? 99;
      return dy.compareTo(dx);
    });

    // Cubrir todos los grupos del bloque antes de repetir ninguno.
    final List<Ejercicio> elegidos = <Ejercicio>[];
    for (final GrupoMuscular g in grupos) {
      final Ejercicio? e = candidatos.firstWhereOrNullTemplo(
        (Ejercicio c) => c.grupoPrincipal == g && !elegidos.contains(c),
      );
      if (e != null) elegidos.add(e);
      if (elegidos.length >= cuantos) break;
    }
    for (final Ejercicio c in candidatos) {
      if (elegidos.length >= cuantos) break;
      if (!elegidos.contains(c)) elegidos.add(c);
    }

    // 4. Peso sugerido: lo último que levantó en ese ejercicio.
    final List<EjercicioPlan> plan = <EjercicioPlan>[
      for (final Ejercicio e in elegidos)
        EjercicioPlan(
          ejercicioId: e.id,
          series: e.compuesto ? series : series - 1 < 2 ? 2 : series - 1,
          repsObjetivo: e.porTiempo ? segundosAguante(asc['experiencia']) : (e.compuesto ? reps : reps + 2),
          pesoSugerido: a.ultimaSerieDe(usuario, e.id)?.peso,
        ),
    ];

    // 5. Explicar la decisión.
    final GrupoMuscular masEnDeuda = grupos.reduce(
        (GrupoMuscular x, GrupoMuscular y) =>
            (deuda[x] ?? 99) >= (deuda[y] ?? 99) ? x : y);
    final int diasDeuda = deuda[masEnDeuda] ?? 99;

    final String razon;
    if (p.sesionesTotales == 0) {
      razon = 'Tu primera sesión. Empezamos por lo básico y bien hecho.';
    } else if (diasDeuda >= 7 && diasDeuda < 90) {
      razon = '${masEnDeuda.etiqueta} lleva $diasDeuda días sin trabajo. '
          'Hoy toca saldar esa deuda.';
    } else if (disposicion.valor < 45) {
      razon = 'Vienes cansado, así que la sesión es más corta. '
          'Sostener también es entrenar.';
    } else if (disposicion.valor >= 85) {
      razon = 'Estás en tu punto. Si hay un récord que romper, es hoy.';
    } else {
      razon = 'Toca ${mejorNombre.toLowerCase()}: es lo que más descanso '
          'lleva de tu rotación.';
    }

    final int minutos = (plan.fold<int>(0, (int x, EjercicioPlan e) =>
                x + e.series) *
            3.2)
        .round();

    return PlanSesion(
      nombre: cuerpoCompleto ? 'Cuerpo completo' : mejorNombre,
      grupos: grupos.take(3).toList(),
      ejercicios: plan,
      minutos: minutos < 20 ? 20 : minutos,
      razon: razon,
    );
  }
}

/// Pequeña ayuda: `firstWhere` con null en vez de excepción.
extension _BuscarTemplo<T> on List<T> {
  T? firstWhereOrNullTemplo(bool Function(T) test) {
    for (final T e in this) {
      if (test(e)) return e;
    }
    return null;
  }
}

// ---------------------------------------------------------------------------
// 24. PANTALLA DE SESIÓN
//
// Todo viene prellenado con lo que hiciste la última vez: si repites peso y
// repeticiones —el caso normal— registrar una serie es UN TOQUE. Solo escribes
// cuando cambias algo. Es la diferencia entre una app que se usa y una que se
// abandona a las dos semanas.
// ---------------------------------------------------------------------------

class SesionScreen extends StatefulWidget {
  const SesionScreen({
    super.key,
    required this.usuario,
    required this.sesion,
  });

  final String usuario;
  final Sesion sesion;

  @override
  State<SesionScreen> createState() => _SesionScreenState();
}

class _SesionScreenState extends State<SesionScreen> {
  late Sesion _sesion = widget.sesion;
  Timer? _reloj;
  Timer? _descanso;
  int _restante = 0;
  int _objetivoDescanso = 90;

  /// Si la persona tocó ±15 s, se respeta su descanso el resto de la sesión.
  bool _descansoManual = false;

  /// Récords ya celebrados durante esta sesión (para no repetir el aviso).
  final Map<String, double> _prAnunciado = <String, double>{};

  /// La última vez y la sugerencia se calculan una vez por ejercicio: la
  /// pantalla se redibuja cada segundo por el cronómetro.
  final Map<String, EjercicioSesion?> _ultimas = <String, EjercicioSesion?>{};
  final Map<String, SugerenciaCarga?> _sugerencias = <String, SugerenciaCarga?>{};
  final Set<String> _aplicadas = <String>{};

  @override
  void initState() {
    super.initState();
    _reloj = Timer.periodic(const Duration(seconds: 1), (_) {
      if (mounted) setState(() {});
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) guiaSiEsNueva(context, widget.usuario, 'sesion');
    });
  }

  EjercicioSesion? _ultimaDe(String id) => _ultimas.putIfAbsent(
      id, () => ultimaVezEjercicio(widget.usuario, id, excluirSesion: _sesion.id));

  SugerenciaCarga? _sugerenciaDe(String id) => _sugerencias.putIfAbsent(
      id, () => sugerirCarga(widget.usuario, id, sesionActual: _sesion.id));

  @override
  void dispose() {
    _reloj?.cancel();
    _descanso?.cancel();
    super.dispose();
  }

  void _guardar() {
    AlmacenTemplo.instancia.actualizarEnCurso(widget.usuario, _sesion);
    // Si se cierra la app a mitad de sesión, nada se pierde.
    NubeTemplo.instancia.marcarCambio();
  }

  void _reemplazarEjercicio(int i, EjercicioSesion e) {
    setState(() {
      final List<EjercicioSesion> l =
          List<EjercicioSesion>.from(_sesion.ejercicios);
      l[i] = e;
      _sesion = _sesion.copyWith(ejercicios: l);
    });
    _guardar();
  }

  void _marcarSerie(int iEj, int iSerie, bool valor) {
    final EjercicioSesion e = _sesion.ejercicios[iEj];
    final List<SerieRegistrada> series =
        List<SerieRegistrada>.from(e.series);

    // El descanso se mide solo: desde la serie anterior hasta esta.
    int? descanso;
    if (valor) {
      final DateTime ahora = DateTime.now();
      DateTime? previa;
      for (final EjercicioSesion x in _sesion.ejercicios) {
        for (final SerieRegistrada s in x.series) {
          if (s.registradaEn != null &&
              (previa == null || s.registradaEn!.isAfter(previa))) {
            previa = s.registradaEn;
          }
        }
      }
      if (previa != null) {
        final int d = ahora.difference(previa).inSeconds;
        if (d > 5 && d < 900) descanso = d;
      }
    }

    series[iSerie] = series[iSerie].copyWith(
      completada: valor,
      registradaEn: valor ? DateTime.now() : null,
      descansoSeg: descanso,
    );
    _reemplazarEjercicio(iEj, e.copyWith(series: series));

    if (valor) {
      HapticFeedback.mediumImpact();
      sonar(SonidoTemplo.serie);
      final SerieRegistrada s = series[iSerie];
      if (!_descansoManual) {
        _objetivoDescanso = s.tipo == TipoSerie.calentamiento
            ? 60
            : (e.definicion?.compuesto ?? true)
                ? 120
                : 75;
      }
      _iniciarDescanso();
      _revisarRecord(e, s);
    }
  }

  /// Aviso en vivo cuando una serie supera el récord de peso.
  void _revisarRecord(EjercicioSesion e, SerieRegistrada s) {
    if (s.tipo == TipoSerie.calentamiento || s.peso <= 0) return;
    final RecordPersonal? r = AlmacenTemplo.instancia.de(widget.usuario).records[e.ejercicioId];
    if (r == null) return;
    final double previo = math.max(r.pesoMaximo, _prAnunciado[e.ejercicioId] ?? 0);
    if (s.peso <= previo) return;
    _prAnunciado[e.ejercicioId] = s.peso;
    HapticFeedback.heavyImpact();
    sonar(SonidoTemplo.record, retraso: const Duration(milliseconds: 250));
    ScaffoldMessenger.of(context)
      ..hideCurrentSnackBar()
      ..showSnackBar(
        SnackBar(
          behavior: SnackBarBehavior.floating,
          backgroundColor: TempleColors.superficieAlta,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(TempleRadius.campo),
            side: const BorderSide(color: TempleColors.dorado),
          ),
          content: Row(
            children: <Widget>[
              const Icon(Icons.emoji_events_rounded, color: TempleColors.dorado, size: 22),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  '¡Nuevo récord en ${e.nombre}! ${_num(s.peso)} kg '
                  '(antes ${_num(r.pesoMaximo)})',
                  style: const TextStyle(color: TempleColors.blancoLuna, fontWeight: FontWeight.w600),
                ),
              ),
            ],
          ),
        ),
      );
  }

  /// Añade las series de calentamiento al principio del ejercicio.
  void _calentar(int iEj) {
    final EjercicioSesion e = _sesion.ejercicios[iEj];
    if (e.series.any((SerieRegistrada s) => s.tipo == TipoSerie.calentamiento)) return;
    double trabajo = 0;
    for (final SerieRegistrada s in e.series) {
      if (s.tipo != TipoSerie.calentamiento && s.peso > trabajo) trabajo = s.peso;
    }
    final List<SerieRegistrada> cal = seriesCalentamiento(trabajo, e.definicion?.equipo);
    if (cal.isEmpty) {
      ScaffoldMessenger.of(context)
        ..hideCurrentSnackBar()
        ..showSnackBar(const SnackBar(
          behavior: SnackBarBehavior.floating,
          content: Text('Con este peso basta con 1 o 2 series ligeras sin carga.'),
        ));
      return;
    }
    _reemplazarEjercicio(iEj, e.copyWith(series: <SerieRegistrada>[...cal, ...e.series]));
  }

  /// Pone el peso y las repeticiones sugeridas en las series que faltan.
  void _aplicarSugerencia(int iEj, SugerenciaCarga s) {
    final EjercicioSesion e = _sesion.ejercicios[iEj];
    _aplicadas.add(e.ejercicioId);
    _reemplazarEjercicio(
      iEj,
      e.copyWith(series: <SerieRegistrada>[
        for (final SerieRegistrada x in e.series)
          x.completada || x.tipo == TipoSerie.calentamiento
              ? x
              : x.copyWith(peso: s.peso, repeticiones: s.reps),
      ]),
    );
  }

  void _editarSerie(int iEj, int iSerie, {double? peso, int? reps}) {
    final EjercicioSesion e = _sesion.ejercicios[iEj];
    final List<SerieRegistrada> series =
        List<SerieRegistrada>.from(e.series);
    series[iSerie] = series[iSerie].copyWith(peso: peso, repeticiones: reps);
    _reemplazarEjercicio(iEj, e.copyWith(series: series));
  }

  void _anadirSerie(int iEj) {
    final EjercicioSesion e = _sesion.ejercicios[iEj];
    final List<SerieRegistrada> trabajo = e.series
        .where((SerieRegistrada s) => s.tipo != TipoSerie.calentamiento)
        .toList();
    final SerieRegistrada ultima = trabajo.isEmpty
        ? const SerieRegistrada(numero: 0, peso: 0, repeticiones: 10)
        : trabajo.last;
    _reemplazarEjercicio(
      iEj,
      e.copyWith(series: <SerieRegistrada>[
        ...e.series,
        SerieRegistrada(
          numero: trabajo.length + 1,
          peso: ultima.peso,
          repeticiones: ultima.repeticiones,
        ),
      ]),
    );
  }

  void _iniciarDescanso() {
    _descanso?.cancel();
    setState(() => _restante = _objetivoDescanso);
    _descanso = Timer.periodic(const Duration(seconds: 1), (Timer t) {
      if (!mounted) return t.cancel();
      setState(() => _restante--);
      if (_restante <= 0) {
        t.cancel();
        // Fin del descanso: vibración doble y la campana (o un clic si los
        // sonidos del templo están apagados).
        HapticFeedback.heavyImpact();
        final bool campana = sonar(SonidoTemplo.descanso);
        if (!campana) SystemSound.play(SystemSoundType.click);
        Future<void>.delayed(const Duration(milliseconds: 220), () {
          HapticFeedback.heavyImpact();
          if (!campana) SystemSound.play(SystemSoundType.click);
        });
        ScaffoldMessenger.of(context)
          ..hideCurrentSnackBar()
          ..showSnackBar(const SnackBar(
            behavior: SnackBarBehavior.floating,
            duration: Duration(seconds: 2),
            content: Text('Descanso terminado. A la siguiente serie.'),
          ));
      }
    });
  }

  Future<void> _anadirEjercicio() async {
    final String? id = await showModalBottomSheet<String>(
      context: context,
      backgroundColor: TempleColors.grafito,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (_) => const _SelectorEjercicio(),
    );
    if (id == null || !mounted) return;
    setState(() {
      _sesion = _sesion.copyWith(ejercicios: <EjercicioSesion>[
        ..._sesion.ejercicios,
        EjercicioSesion(
          ejercicioId: id,
          orden: _sesion.ejercicios.length,
          series: <SerieRegistrada>[
            SerieRegistrada(
              numero: 1,
              peso: AlmacenTemplo.instancia
                      .ultimaSerieDe(widget.usuario, id)
                      ?.peso ??
                  0,
              repeticiones: 10,
            ),
          ],
        ),
      ]);
    });
    _guardar();
  }

  Future<void> _terminar() async {
    if (_sesion.estaVacia) {
      final bool salir = await _confirmar(
            'Salir sin registrar nada',
            'No has completado ninguna serie. La sesión se descartará.',
          ) ??
          false;
      if (!salir || !mounted) return;
      AlmacenTemplo.instancia.descartarEnCurso(widget.usuario);
      if (mounted) Navigator.of(context).pop();
      return;
    }

    final _CierreDatos? datos = await showModalBottomSheet<_CierreDatos>(
      context: context,
      backgroundColor: TempleColors.grafito,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (_) => const _HojaCierre(),
    );
    if (datos == null || !mounted) return;

    final ResumenCierre resumen = AlmacenTemplo.instancia.cerrarSesion(
      widget.usuario,
      _sesion,
      esfuerzo: datos.esfuerzo,
      sensacion: datos.sensacion,
    );
    final NovedadesProgreso nov =
        MotorProgresion.instancia.evaluar(widget.usuario);
    final int mon = MonedaTemplo.instancia
        .recompensarSesion(widget.usuario, resumen, nov);
    AlmacenAnuncios.instancia.registrarSesion(widget.usuario, mon);
    // Sus cifras van a los retos y a la tabla del clan; los recordatorios de
    // hoy se recalculan (ya entrenaste).
    unawaited(RetosRepo.instancia.aportar(widget.usuario, forzar: true));
    unawaited(Recordatorios.instancia.reprogramar());
    // La sesión terminada se guarda ya en el teléfono y en la nube; la racha,
    // la llama y el nivel nuevos pasan al perfil público al subir.
    NubeTemplo.instancia.marcarCambio();
    SesionTemplo.instancia.sincronizarIdentidad(widget.usuario);
    ProgramadorAvisos.trasSesion(
      widget.usuario,
      AlmacenTemplo.instancia.de(widget.usuario).ascenso['objetivo'] ?? '',
      resumen,
      nov,
      mon,
    );
    // Taiko y campana al cerrar; koto si subiste de nivel.
    sonar(resumen.subioNivel ? SonidoTemplo.nivel : SonidoTemplo.sesion);
    // Lo que esta sesión desbloqueó se celebra antes del resumen.
    final List<MarcoSello> marcosNuevos = MarcosTemplo.nuevos(widget.usuario);
    if (!mounted) return;
    if (nov.piezas.isNotEmpty || marcosNuevos.isNotEmpty) {
      await celebrarDesbloqueos(context, widget.usuario, piezas: nov.piezas, marcos: marcosNuevos);
      if (!mounted) return;
    }
    Navigator.of(context).pushReplacement(
      MaterialPageRoute<void>(
        builder: (_) => ResumenSesionScreen(resumen: resumen),
      ),
    );
  }

  Future<bool?> _confirmar(String titulo, String cuerpo) => showDialog<bool>(
        context: context,
        builder: (BuildContext c) => AlertDialog(
          backgroundColor: TempleColors.superficieAlta,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
          ),
          title: Text(titulo,
              style: const TextStyle(color: TempleColors.blancoLuna)),
          content: Text(cuerpo,
              style: const TextStyle(color: TempleColors.textoSuave)),
          actions: <Widget>[
            TextButton(
              onPressed: () => Navigator.of(c).pop(false),
              child: const Text('Seguir aquí'),
            ),
            TextButton(
              onPressed: () => Navigator.of(c).pop(true),
              child: const Text('Salir',
                  style: TextStyle(color: TempleColors.error)),
            ),
          ],
        ),
      );

  String get _crono {
    final Duration d = _sesion.duracion;
    final String m = d.inMinutes.remainder(60).toString().padLeft(2, '0');
    final String s = d.inSeconds.remainder(60).toString().padLeft(2, '0');
    return d.inHours > 0 ? '${d.inHours}:$m:$s' : '$m:$s';
  }

  @override
  Widget build(BuildContext context) {
    final int completadas = _sesion.ejercicios.fold<int>(
        0, (int a, EjercicioSesion e) => a + e.seriesEfectivas.length);
    final int totales = _sesion.ejercicios.fold<int>(
        0,
        (int a, EjercicioSesion e) =>
            a + e.series.where((SerieRegistrada s) => s.tipo != TipoSerie.calentamiento).length);

    return PopScope(
      canPop: false,
      onPopInvokedWithResult: (bool did, _) async {
        if (did) return;
        final bool salir = await _confirmar(
              'Dejar la sesión',
              'Se guardará como abandonada. Puedes retomarla desde el Dojo.',
            ) ??
            false;
        if (salir && mounted) Navigator.of(context).pop();
      },
      child: Scaffold(
        backgroundColor: TempleColors.negro,
        body: FondoTemplo(
          child: SafeArea(
            child: Column(
              children: <Widget>[
                // Cabecera con cronómetro.
                Padding(
                  padding: const EdgeInsets.fromLTRB(8, 4, 16, 8),
                  child: Row(
                    children: <Widget>[
                      IconButton(
                        onPressed: () => Navigator.of(context).maybePop(),
                        icon: const Icon(Icons.close_rounded,
                            color: TempleColors.textoSuave),
                      ),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: <Widget>[
                            Text(
                              _sesion.nombre ?? 'Sesión libre',
                              style: const TextStyle(
                                fontSize: 16,
                                fontWeight: FontWeight.w600,
                                color: TempleColors.blancoLuna,
                              ),
                            ),
                            Text(
                              '$_crono · $completadas/$totales series · '
                              '${_sesion.volumenTotal.round()} kg',
                              style: const TextStyle(
                                fontSize: 11.5,
                                color: TempleColors.textoSuave,
                              ),
                            ),
                          ],
                        ),
                      ),
                      TextButton(
                        onPressed: _terminar,
                        child: const Text(
                          'Terminar',
                          style: TextStyle(
                            color: TempleColors.violetaClaro,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
                Expanded(
                  child: ListView(
                    padding: const EdgeInsets.fromLTRB(16, 4, 16, 120),
                    children: <Widget>[
                      for (int i = 0; i < _sesion.ejercicios.length; i++)
                        Padding(
                          padding: const EdgeInsets.only(bottom: 14),
                          child: _TarjetaEjercicioSesion(
                            ejercicio: _sesion.ejercicios[i],
                            usuario: widget.usuario,
                            record: AlmacenTemplo.instancia
                                .de(widget.usuario)
                                .records[_sesion.ejercicios[i].ejercicioId],
                            ultimaVez: _ultimaDe(_sesion.ejercicios[i].ejercicioId),
                            sugerencia: _aplicadas.contains(_sesion.ejercicios[i].ejercicioId)
                                ? null
                                : _sugerenciaDe(_sesion.ejercicios[i].ejercicioId),
                            onMarcar: (int s, bool v) => _marcarSerie(i, s, v),
                            onEditar: (int s, {double? peso, int? reps}) =>
                                _editarSerie(i, s, peso: peso, reps: reps),
                            onAnadirSerie: () => _anadirSerie(i),
                            onCalentar: () => _calentar(i),
                            onAplicar: (SugerenciaCarga s) => _aplicarSugerencia(i, s),
                          ),
                        ),
                      OutlinedButton.icon(
                        onPressed: _anadirEjercicio,
                        icon: const Icon(Icons.add_rounded, size: 18),
                        label: const Text('Añadir ejercicio'),
                        style: OutlinedButton.styleFrom(
                          foregroundColor: TempleColors.violetaClaro,
                          side:
                              const BorderSide(color: TempleColors.bordeVivo),
                          padding: const EdgeInsets.symmetric(vertical: 14),
                          shape: RoundedRectangleBorder(
                            borderRadius:
                                BorderRadius.circular(TempleRadius.campo),
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
        bottomNavigationBar: _restante > 0
            ? _BarraDescanso(
                restante: _restante,
                objetivo: _objetivoDescanso,
                onAjustar: (int seg) => setState(() {
                  _descansoManual = true;
                  _objetivoDescanso = (_objetivoDescanso + seg).clamp(30, 300);
                  _restante = (_restante + seg).clamp(0, 300);
                }),
                onSaltar: () {
                  _descanso?.cancel();
                  setState(() => _restante = 0);
                },
              )
            : null,
      ),
    );
  }
}

/// Tarjeta de un ejercicio con sus filas de series.
class _TarjetaEjercicioSesion extends StatelessWidget {
  const _TarjetaEjercicioSesion({
    required this.ejercicio,
    required this.usuario,
    required this.record,
    required this.ultimaVez,
    required this.sugerencia,
    required this.onMarcar,
    required this.onEditar,
    required this.onAnadirSerie,
    required this.onCalentar,
    required this.onAplicar,
  });

  final EjercicioSesion ejercicio;
  final String usuario;
  final RecordPersonal? record;
  final EjercicioSesion? ultimaVez;
  final SugerenciaCarga? sugerencia;
  final void Function(int indice, bool valor) onMarcar;
  final void Function(int indice, {double? peso, int? reps}) onEditar;
  final VoidCallback onAnadirSerie;
  final VoidCallback onCalentar;
  final ValueChanged<SugerenciaCarga> onAplicar;

  Widget _chip(String texto, IconData icono, VoidCallback onTap) => Padding(
        padding: const EdgeInsets.only(right: 8),
        child: InkWell(
          onTap: onTap,
          borderRadius: BorderRadius.circular(999),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
            decoration: BoxDecoration(
              color: TempleColors.violeta.withValues(alpha: 0.10),
              borderRadius: BorderRadius.circular(999),
              border: Border.all(color: TempleColors.violeta.withValues(alpha: 0.35)),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: <Widget>[
                Icon(icono, size: 14, color: TempleColors.violetaClaro),
                const SizedBox(width: 5),
                Text(texto, style: const TextStyle(fontSize: 11.5, color: TempleColors.violetaClaro)),
              ],
            ),
          ),
        ),
      );

  @override
  Widget build(BuildContext context) {
    final Ejercicio? def = ejercicio.definicion;
    final Equipo? equipo = def?.equipo;
    final bool conCarga = equipo != null && equipo != Equipo.pesoCorporal && equipo != Equipo.banda && equipo != Equipo.casero;
    final bool yaCalento =
        ejercicio.series.any((SerieRegistrada s) => s.tipo == TipoSerie.calentamiento);
    double pesoTrabajo = 0;
    for (final SerieRegistrada s in ejercicio.series) {
      if (s.tipo != TipoSerie.calentamiento && s.peso > pesoTrabajo) pesoTrabajo = s.peso;
    }
    final bool todasHechas = ejercicio.series.isNotEmpty &&
        ejercicio.series.every((SerieRegistrada s) => s.completada);
    final SugerenciaCarga? sug = todasHechas ? null : sugerencia;

    return TempleCard(
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 8),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Row(
            children: <Widget>[
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    Text(
                      ejercicio.nombre,
                      style: const TextStyle(
                        fontSize: 15.5,
                        fontWeight: FontWeight.w600,
                        color: TempleColors.blancoLuna,
                      ),
                    ),
                    const SizedBox(height: 3),
                    Text(
                      def == null
                          ? ''
                          : def.reparto.keys
                              .map((GrupoMuscular g) => g.etiqueta)
                              .join(' · '),
                      style: const TextStyle(
                        fontSize: 11.5,
                        color: TempleColors.textoTenue,
                      ),
                    ),
                  ],
                ),
              ),
              if (record != null)
                Container(
                  padding: const EdgeInsets.symmetric(
                      horizontal: 9, vertical: 4),
                  decoration: BoxDecoration(
                    color: TempleColors.dorado.withValues(alpha: 0.10),
                    borderRadius: BorderRadius.circular(999),
                  ),
                  child: Text(
                    'PR ${record!.pesoMaximo.round()} kg',
                    style: const TextStyle(
                      fontSize: 10.5,
                      fontWeight: FontWeight.w600,
                      color: TempleColors.dorado,
                    ),
                  ),
                ),
            ],
          ),
          const SizedBox(height: 10),
          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            child: Row(
              children: <Widget>[
                _chip('Cómo se hace', Icons.accessibility_new_rounded,
                    () => mostrarTecnica(context, ejercicio.ejercicioId, usuario: usuario)),
                if (conCarga && !yaCalento && pesoTrabajo > 0)
                  _chip('Calentar', Icons.local_fire_department_outlined, onCalentar),
                if (equipo == Equipo.barra && pesoTrabajo > 0)
                  _chip('Discos', Icons.album_outlined, () => mostrarCalculadoraDiscos(context, pesoTrabajo)),
              ],
            ),
          ),
          if (ultimaVez != null) ...<Widget>[
            const SizedBox(height: 8),
            Text(
              'La última vez: ${textoUltimaVez(ultimaVez!)}',
              style: const TextStyle(fontSize: 11.5, color: TempleColors.textoSuave),
            ),
          ],
          if (sug != null) ...<Widget>[
            const SizedBox(height: 8),
            Container(
              padding: const EdgeInsets.fromLTRB(10, 6, 4, 6),
              decoration: BoxDecoration(
                color: TempleColors.negro.withValues(alpha: 0.35),
                borderRadius: BorderRadius.circular(TempleRadius.chip),
                border: Border.all(color: TempleColors.borde),
              ),
              child: Row(
                children: <Widget>[
                  const Icon(Icons.auto_graph_rounded, size: 16, color: TempleColors.violetaClaro),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(sug.texto,
                        style: const TextStyle(fontSize: 12, height: 1.35, color: TempleColors.texto)),
                  ),
                  TextButton(
                    onPressed: () => onAplicar(sug),
                    style: TextButton.styleFrom(
                      foregroundColor: TempleColors.violetaClaro,
                      minimumSize: Size.zero,
                      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
                    ),
                    child: const Text('Aplicar', style: TextStyle(fontSize: 12.5, fontWeight: FontWeight.w600)),
                  ),
                ],
              ),
            ),
          ],
          const SizedBox(height: 12),
          Row(
            children: <Widget>[
              const SizedBox(width: 26, child: Text('#', style: _estiloCabecera)),
              const SizedBox(width: 10),
              // Sin pesas, lo que se escribe es lastre (una mochila, un chaleco).
              Expanded(
                  child: Text(
                      equipo == Equipo.pesoCorporal || equipo == Equipo.banda ? 'LASTRE KG' : 'KG',
                      style: _estiloCabecera)),
              const SizedBox(width: 10),
              Expanded(child: Text(def?.porTiempo ?? false ? 'SEGUNDOS' : 'REPS', style: _estiloCabecera)),
              const SizedBox(width: 52),
            ],
          ),
          const SizedBox(height: 4),
          for (int i = 0; i < ejercicio.series.length; i++)
            _FilaSerie(
              serie: ejercicio.series[i],
              onMarcar: (bool v) => onMarcar(i, v),
              onPeso: (double p) => onEditar(i, peso: p),
              onReps: (int r) => onEditar(i, reps: r),
            ),
          TextButton.icon(
            onPressed: onAnadirSerie,
            icon: const Icon(Icons.add_rounded, size: 16),
            label: const Text('Serie', style: TextStyle(fontSize: 12.5)),
            style: TextButton.styleFrom(
              foregroundColor: TempleColors.textoSuave,
              minimumSize: Size.zero,
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
            ),
          ),
        ],
      ),
    );
  }
}

const TextStyle _estiloCabecera = TextStyle(
  fontSize: 10,
  fontWeight: FontWeight.w600,
  letterSpacing: 1.2,
  color: TempleColors.textoTenue,
);

class _FilaSerie extends StatelessWidget {
  const _FilaSerie({
    required this.serie,
    required this.onMarcar,
    required this.onPeso,
    required this.onReps,
  });

  final SerieRegistrada serie;
  final ValueChanged<bool> onMarcar;
  final ValueChanged<double> onPeso;
  final ValueChanged<int> onReps;

  @override
  Widget build(BuildContext context) {
    final bool ok = serie.completada;
    final bool calentamiento = serie.tipo == TipoSerie.calentamiento;

    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 3),
      child: Row(
        children: <Widget>[
          SizedBox(
            width: 26,
            child: Tooltip(
              message: calentamiento ? 'Serie de calentamiento (no suma volumen)' : 'Serie ${serie.numero}',
              child: Text(
                calentamiento ? 'C' : '${serie.numero}',
                style: TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w600,
                  color: ok
                      ? TempleColors.exito
                      : calentamiento
                          ? TempleColors.dorado.withValues(alpha: 0.8)
                          : TempleColors.textoSuave,
                ),
              ),
            ),
          ),
          const SizedBox(width: 10),
          Expanded(
            child: _CampoNumero(
              valor: serie.peso == 0 ? '' : _sinCero(serie.peso),
              hint: '0',
              activo: !ok,
              onCambio: (String s) => onPeso(double.tryParse(s) ?? 0),
            ),
          ),
          const SizedBox(width: 10),
          Expanded(
            child: _CampoNumero(
              valor: '${serie.repeticiones}',
              hint: '0',
              activo: !ok,
              soloEnteros: true,
              onCambio: (String s) => onReps(int.tryParse(s) ?? 0),
            ),
          ),
          const SizedBox(width: 8),
          SizedBox(
            width: 44,
            child: GestureDetector(
              onTap: () => onMarcar(!ok),
              child: AnimatedContainer(
                duration: TempleMotion.rapido,
                height: 38,
                decoration: BoxDecoration(
                  color: ok
                      ? TempleColors.exito.withValues(alpha: 0.18)
                      : TempleColors.superficieAlta,
                  borderRadius: BorderRadius.circular(TempleRadius.chip),
                  border: Border.all(
                    color: ok ? TempleColors.exito : TempleColors.borde,
                  ),
                ),
                child: Icon(
                  Icons.check_rounded,
                  size: 19,
                  color: ok ? TempleColors.exito : TempleColors.textoTenue,
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  static String _sinCero(double v) =>
      v == v.roundToDouble() ? v.round().toString() : v.toString();
}

class _CampoNumero extends StatefulWidget {
  const _CampoNumero({
    required this.valor,
    required this.hint,
    required this.activo,
    required this.onCambio,
    this.soloEnteros = false,
  });

  final String valor;
  final String hint;
  final bool activo;
  final bool soloEnteros;
  final ValueChanged<String> onCambio;

  @override
  State<_CampoNumero> createState() => _CampoNumeroState();
}

class _CampoNumeroState extends State<_CampoNumero> {
  late final TextEditingController _c = TextEditingController(text: widget.valor);

  @override
  void didUpdateWidget(_CampoNumero old) {
    super.didUpdateWidget(old);
    if (widget.valor != _c.text && !_c.selection.isValid) {
      _c.text = widget.valor;
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      height: 38,
      child: TextField(
        controller: _c,
        enabled: widget.activo,
        onChanged: widget.onCambio,
        keyboardType: TextInputType.numberWithOptions(
            decimal: !widget.soloEnteros),
        textAlign: TextAlign.center,
        style: TextStyle(
          fontSize: 14.5,
          fontWeight: FontWeight.w600,
          color: widget.activo
              ? TempleColors.blancoLuna
              : TempleColors.textoSuave,
        ),
        decoration: InputDecoration(
          hintText: widget.hint,
          hintStyle: const TextStyle(color: TempleColors.textoTenue),
          isDense: true,
          filled: true,
          fillColor: TempleColors.negro.withValues(alpha: 0.45),
          contentPadding: EdgeInsets.zero,
          enabledBorder: OutlineInputBorder(
            borderRadius: BorderRadius.circular(TempleRadius.chip),
            borderSide: const BorderSide(color: TempleColors.borde),
          ),
          disabledBorder: OutlineInputBorder(
            borderRadius: BorderRadius.circular(TempleRadius.chip),
            borderSide: BorderSide(
                color: TempleColors.borde.withValues(alpha: 0.4)),
          ),
          focusedBorder: OutlineInputBorder(
            borderRadius: BorderRadius.circular(TempleRadius.chip),
            borderSide:
                const BorderSide(color: TempleColors.violeta, width: 1.4),
          ),
        ),
      ),
    );
  }
}

/// Temporizador de descanso. Aparece solo al marcar una serie y mide de paso
/// el descanso real, sin pedirle nada al usuario.
class _BarraDescanso extends StatelessWidget {
  const _BarraDescanso({
    required this.restante,
    required this.objetivo,
    required this.onAjustar,
    required this.onSaltar,
  });

  final int restante;
  final int objetivo;
  final ValueChanged<int> onAjustar;
  final VoidCallback onSaltar;

  @override
  Widget build(BuildContext context) {
    final String m = (restante ~/ 60).toString();
    final String s = (restante % 60).toString().padLeft(2, '0');

    return Container(
      padding: EdgeInsets.only(
        left: 16,
        right: 16,
        top: 12,
        bottom: 12 + MediaQuery.paddingOf(context).bottom,
      ),
      decoration: const BoxDecoration(
        color: TempleColors.superficieAlta,
        border: Border(top: BorderSide(color: TempleColors.bordeVivo)),
      ),
      child: Row(
        children: <Widget>[
          const TempleIcon(TempleGlyph.reloj,
              size: 20, color: TempleColors.violetaClaro),
          const SizedBox(width: 12),
          Text(
            '$m:$s',
            style: const TextStyle(
              fontSize: 22,
              fontWeight: FontWeight.w600,
              color: TempleColors.blancoLuna,
              fontFeatures: <FontFeature>[FontFeature.tabularFigures()],
            ),
          ),
          const Spacer(),
          _BotonMini(texto: '−15', onTap: () => onAjustar(-15)),
          const SizedBox(width: 8),
          _BotonMini(texto: '+15', onTap: () => onAjustar(15)),
          const SizedBox(width: 8),
          TextButton(
            onPressed: onSaltar,
            child: const Text('Saltar',
                style: TextStyle(color: TempleColors.violetaClaro)),
          ),
        ],
      ),
    );
  }
}

