// ---------------------------------------------------------------------------
// 26. DOJO RECALCULADO
//
// Sustituye por completo a la clase DojoScreen de la sección 14.
// Borra la anterior antes de pegar esta.
// ---------------------------------------------------------------------------

class DojoScreen extends StatefulWidget {
  const DojoScreen({super.key});

  @override
  State<DojoScreen> createState() => _DojoScreenState();
}

class _DojoScreenState extends State<DojoScreen>
    with SingleTickerProviderStateMixin {
  late final AnimationController _entrada = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1100),
  );

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _entrada.forward();
    });
  }

  @override
  void dispose() {
    _entrada.dispose();
    super.dispose();
  }

  String get _saludo {
    final int h = DateTime.now().hour;
    if (h < 6) return 'Aún es de noche,';
    if (h < 12) return 'Buenos días,';
    if (h < 19) return 'Buenas tardes,';
    return 'Buenas noches,';
  }

  void _pendiente(String que) {
    ScaffoldMessenger.of(context)
      ..hideCurrentSnackBar()
      ..showSnackBar(
        SnackBar(
          behavior: SnackBarBehavior.floating,
          backgroundColor: TempleColors.superficieAlta,
          margin: const EdgeInsets.fromLTRB(20, 0, 20, kAlturaNavBar + 16),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(TempleRadius.campo),
            side: const BorderSide(color: TempleColors.borde),
          ),
          content: Text(
            '$que llega en la siguiente piedra del templo.',
            style: const TextStyle(color: TempleColors.texto, fontSize: 13),
          ),
        ),
      );
  }

  Future<void> _entrenar(String usuario, PlanSesion plan, int disp) async {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final Sesion s = a.de(usuario).enCurso ?? a.abrirSesion(usuario, plan, disp);

    await Navigator.of(context).push(
      MaterialPageRoute<void>(
        builder: (_) => SesionScreen(usuario: usuario, sesion: s),
      ),
    );
    if (mounted) setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final TempleShellScope shell = TempleShellScope.of(context);
    final String usuario = shell.perfil.nombre;
    ProgramadorAvisos.alAbrir(usuario, shell.perfil.espiritu);
    RecordatorioMeta.alAbrir(usuario, shell.perfil.espiritu);
    final AlmacenTemplo a = AlmacenTemplo.instancia;

    final NivelTemplo nivel = NivelTemplo.desdeXp(a.de(usuario).xpGeneral);
    final Llama llama = a.llama(usuario);
    final double peso = a.pesoDelTemplo(usuario);
    final Map<GrupoMuscular, int> deuda = a.deuda(usuario);

    // La disposición se calcula antes que el plan, porque el plan depende
    // de ella: si vienes cansado, la sesión es más corta.
    final Disposicion disp0 = a.disposicion(usuario, <GrupoMuscular>[]);
    final PlanSesion plan =
        GeneradorRutina.generar(usuario: usuario, disposicion: disp0);
    final Disposicion disp = a.disposicion(usuario, plan.grupos);

    final Sesion? enCurso = a.de(usuario).enCurso;

    return RefreshIndicator(
      onRefresh: () async => setState(() {}),
      color: TempleColors.violetaClaro,
      backgroundColor: TempleColors.superficieAlta,
      child: ListView(
        physics: const AlwaysScrollableScrollPhysics(
          parent: BouncingScrollPhysics(),
        ),
        padding: EdgeInsets.only(
          left: TempleSpace.borde,
          right: TempleSpace.borde,
          top: MediaQuery.paddingOf(context).top + 12,
          bottom: kAlturaNavBar + 28,
        ),
        children: <Widget>[
          Aparece(
            controlador: _entrada,
            desde: 0,
