class _TarjetaPeso extends StatelessWidget {
  const _TarjetaPeso({required this.kilos});
  final double kilos;

  @override
  Widget build(BuildContext context) {
    final PiezaTemplo? siguiente = PiezasDelTemplo.siguienteTras(kilos);
    final double v = siguiente == null ? 1 : kilos / siguiente.kilos;

    return TempleCard(
      padding: const EdgeInsets.all(14),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Row(
            children: <Widget>[
              const TempleIcon(TempleGlyph.casa,
                  size: 20, color: TempleColors.violetaClaro),
              const SizedBox(width: 8),
              const Text(
                'Peso del templo',
                style: TextStyle(
                    fontSize: 11,
                    letterSpacing: 1.4,
                    fontWeight: FontWeight.w600,
                    color: TempleColors.textoSuave),
              ),
            ],
          ),
          const SizedBox(height: 12),
          Text(
            kilos >= 1000
                ? '${(kilos / 1000).toStringAsFixed(1)} t'
                : '${kilos.round()} kg',
            style: const TextStyle(
              fontSize: 20,
              fontWeight: FontWeight.w600,
              color: TempleColors.blancoLuna,
            ),
          ),
          const SizedBox(height: 8),
          ClipRRect(
            borderRadius: BorderRadius.circular(999),
            child: LinearProgressIndicator(
              value: v.clamp(0.0, 1.0),
              minHeight: 5,
              backgroundColor: TempleColors.borde,
              valueColor:
                  const AlwaysStoppedAnimation<Color>(TempleColors.dorado),
            ),
          ),
          const SizedBox(height: 8),
          Text(
            siguiente == null
                ? 'El templo está completo.'
                : 'Siguiente: ${siguiente.nombre.toLowerCase()}',
            style: const TextStyle(
                fontSize: 11, height: 1.4, color: TempleColors.textoTenue),
          ),
        ],
      ),
    );
  }
}

class _TarjetaDeuda extends StatelessWidget {
  const _TarjetaDeuda({required this.deuda});
  final Map<GrupoMuscular, int> deuda;

  @override
  Widget build(BuildContext context) {
    final List<MapEntry<GrupoMuscular, int>> orden = deuda.entries.toList()
      ..sort((MapEntry<GrupoMuscular, int> a, MapEntry<GrupoMuscular, int> b) =>
          b.value.compareTo(a.value));
    final List<MapEntry<GrupoMuscular, int>> top = orden.take(3).toList();

    return TempleCard(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 6),
      child: Column(
        children: <Widget>[
          for (int i = 0; i < top.length; i++) ...<Widget>[
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 13),
              child: Row(
                children: <Widget>[
                  Container(
                    width: 8,
                    height: 8,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: top[i].value >= 10
                          ? TempleColors.error
                          : top[i].value >= 6
                              ? TempleColors.alertaSuave
                              : TempleColors.exito,
                    ),
                  ),
                  const SizedBox(width: 14),
                  Expanded(
                    child: Text(
                      top[i].key.etiqueta,
                      style: const TextStyle(
                          fontSize: 13.5, color: TempleColors.texto),
                    ),
                  ),
                  Text(
                    top[i].value >= 90
                        ? 'sin registrar'
                        : top[i].value == 0
                            ? 'hoy'
                            : '${top[i].value} días',
                    style: const TextStyle(
                        fontSize: 12, color: TempleColors.textoSuave),
                  ),
                ],
              ),
            ),
            if (i != top.length - 1)
              Divider(
                  height: 1,
                  color: TempleColors.borde.withValues(alpha: 0.7)),
          ],
        ],
      ),
    );
  }
}

/// Los tres toques del final del día. Nada de esto es obligatorio.
class _CierreDelDia extends StatelessWidget {
  const _CierreDelDia({required this.usuario, required this.onCambio});

  final String usuario;
  final VoidCallback onCambio;

  @override
  Widget build(BuildContext context) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final RegistroDiario r = a.registroDe(usuario, DateTime.now());

    return TempleCard(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Row(
            children: <Widget>[
              const TempleIcon(TempleGlyph.luna,
                  size: 18, color: TempleColors.violetaClaro),
              const SizedBox(width: 10),
              const Text('Sueño',
                  style: TextStyle(
                      fontSize: 13.5, color: TempleColors.texto)),
              const Spacer(),
              Text(
                r.horasSueno == null
                    ? 'sin registrar'
                    : '${r.horasSueno!.toStringAsFixed(1)} h',
                style: const TextStyle(
                    fontSize: 12.5, color: TempleColors.textoSuave),
              ),
            ],
          ),
          SliderTheme(
            data: SliderTheme.of(context).copyWith(
              activeTrackColor: TempleColors.violeta,
              inactiveTrackColor: TempleColors.borde,
              thumbColor: TempleColors.violetaClaro,
              trackHeight: 3,
            ),
            child: Slider(
              value: r.horasSueno ?? 7,
              min: 3,
              max: 11,
              divisions: 16,
              onChanged: (double v) {
                a.guardarRegistro(usuario, r.copyWith(horasSueno: v));
                onCambio();
              },
            ),
          ),
          Divider(color: TempleColors.borde.withValues(alpha: 0.7)),
          const SizedBox(height: 6),
          Row(
            children: <Widget>[
              const TempleIcon(TempleGlyph.gota,
                  size: 18, color: TempleColors.violetaClaro),
              const SizedBox(width: 10),
              const Text('Agua',
                  style: TextStyle(
                      fontSize: 13.5, color: TempleColors.texto)),
              const Spacer(),
              Text('${r.vasosAgua} vasos',
                  style: const TextStyle(
                      fontSize: 12.5, color: TempleColors.textoSuave)),
              const SizedBox(width: 10),
              _BotonMini(
                texto: '−',
                onTap: () {
                  a.guardarRegistro(
                      usuario,
                      r.copyWith(
                          vasosAgua:
                              r.vasosAgua > 0 ? r.vasosAgua - 1 : 0));
                  onCambio();
                },
              ),
              const SizedBox(width: 6),
              _BotonMini(
                texto: '+',
                onTap: () {
                  a.guardarRegistro(
                      usuario, r.copyWith(vasosAgua: r.vasosAgua + 1));
                  HapticFeedback.selectionClick();
                  // Al llegar a la meta del día se callan los avisos de agua.
                  if (r.vasosAgua + 1 == Recordatorios.metaVasos) {
                    unawaited(Recordatorios.instancia.reprogramar());
                  }
                  onCambio();
                },
              ),
            ],
          ),
        ],
      ),
    );
  }
}

// ---------------------------------------------------------------------------
// 26.1 ESCENA VIVA
//
// El paisaje deja de ser decorado: refleja tu estado. Con la llama alta el
// cielo se abre y la luna brilla; apagada, la niebla espesa y todo se enfría.
// Ves cómo vas antes de leer un solo número.
//
// Sustituye a EscenaDelDia (sección 12), que puedes borrar junto con
// _EscenaPainter cuando esto funcione.
// ---------------------------------------------------------------------------

class EscenaViva extends StatefulWidget {
  const EscenaViva({
    super.key,
    required this.vitalidad,
    required this.entrenoHoy,
    this.altura = 210,
  });

  /// 0 = templo frío y cerrado. 1 = templo encendido.
  final double vitalidad;
  final bool entrenoHoy;
  final double altura;

  @override
  State<EscenaViva> createState() => _EscenaVivaState();
}

class _EscenaVivaState extends State<EscenaViva>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;

  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 30),
  );

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (MediaQuery.maybeDisableAnimationsOf(context) ?? false) {
      _c.stop();
      _c.value = 0.2;
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  String get _frase {
    if (widget.entrenoHoy) return 'Hoy el templo se levantó contigo.';
    if (widget.vitalidad >= 0.85) return 'El fuego no se ha movido de sitio.';
    if (widget.vitalidad >= 0.6) return 'La constancia es fuerza.';
    if (widget.vitalidad >= 0.3) return 'Queda brasa. Basta con volver.';
    return 'El templo espera. Nunca se cierra.';
  }

  String get _kanji {
    if (widget.entrenoHoy) return '今日も一歩';
    if (widget.vitalidad >= 0.6) return '継続は力なり';
    return '一歩ずつ';
  }

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
      child: Container(
        height: widget.altura,
        decoration: BoxDecoration(
          border: Border.all(color: TempleColors.borde),
          borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
        ),
        child: Stack(
          fit: StackFit.expand,
          children: <Widget>[
            RepaintBoundary(
              child: AnimatedBuilder(
                animation: _c,
                builder: (BuildContext context, _) => CustomPaint(
                  painter: _EscenaVivaPainter(
                    t: _c.value,
                    vida: widget.vitalidad.clamp(0.0, 1.0),
                    encendido: widget.entrenoHoy,
                  ),
                ),
              ),
            ),
            Positioned(
              left: 18,
              right: 18,
              bottom: 16,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: <Widget>[
                  Text(
                    _kanji,
                    textAlign: TextAlign.center,
                    style: const TextStyle(
                      fontSize: 19,
                      height: 1.4,
                      letterSpacing: 3,
                      color: TempleColors.blancoLuna,
                      shadows: <Shadow>[
                        Shadow(color: Colors.black87, blurRadius: 12),
                      ],
                    ),
                  ),
                  const SizedBox(height: 4),
                  Text(
                    _frase,
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      fontSize: 12.5,
                      color: TempleColors.texto.withValues(alpha: 0.82),
                      shadows: const <Shadow>[
                        Shadow(color: Colors.black87, blurRadius: 10),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _EscenaVivaPainter extends CustomPainter {
  const _EscenaVivaPainter({
    required this.t,
    required this.vida,
    required this.encendido,
  });

  final double t;
  final double vida;
  final bool encendido;

  @override
  void paint(Canvas canvas, Size size) {
    final double w = size.width;
    final double h = size.height;
    final double horizonte = h * 0.68;

    // Cielo: se abre con la vitalidad.
    canvas.drawRect(
      Offset.zero & size,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[
            Color.lerp(const Color(0xFF120A20), const Color(0xFF2A1750), vida)!,
            Color.lerp(const Color(0xFF0C0718), const Color(0xFF170D2C), vida)!,
            const Color(0xFF08040F),
          ],
        ).createShader(Offset.zero & size),
    );

    // Luna: crece y aclara con la vitalidad.
    final Offset luna = Offset(w * 0.70, h * 0.30);
    final double rl = h * (0.10 + 0.05 * vida);
    canvas.drawCircle(
      luna,
      rl * (2.4 + 1.6 * vida),
      Paint()
        ..shader = RadialGradient(
          colors: <Color>[
            ColoresTradicion.violetaClaro.withValues(alpha: 0.10 + 0.26 * vida),
            Colors.transparent,
          ],
        ).createShader(
            Rect.fromCircle(center: luna, radius: rl * (2.4 + 1.6 * vida))),
    );
    canvas.drawCircle(
      luna,
      rl,
      Paint()
        ..color = Color.lerp(const Color(0xFF6E6088), const Color(0xFFE8DCFF),
            vida)!,
    );

    // Cordilleras.
    void cordillera(double base, double alto, Color color) {
      canvas.drawPath(
        Path()
          ..moveTo(0, horizonte)
          ..lineTo(0, base)
          ..quadraticBezierTo(w * 0.16, base - alto * 0.55, w * 0.30, base - alto)
          ..quadraticBezierTo(
              w * 0.44, base - alto * 0.35, w * 0.58, base - alto * 0.72)
          ..quadraticBezierTo(w * 0.78, base - alto * 1.05, w, base - alto * 0.25)
          ..lineTo(w, horizonte)
          ..close(),
        Paint()..color = color,
      );
    }

    cordillera(horizonte, h * 0.34,
        Color.lerp(const Color(0xFF150D26), const Color(0xFF20143A), vida)!);
    cordillera(horizonte + 6, h * 0.20, const Color(0xFF120A22));

    // Agua.
    canvas.drawRect(
      Rect.fromLTRB(0, horizonte, w, h),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[
            Color.lerp(const Color(0xFF130B24), const Color(0xFF1A0F30), vida)!,
            const Color(0xFF06040C),
          ],
        ).createShader(Rect.fromLTRB(0, horizonte, w, h)),
    );

    for (int i = 0; i < 4; i++) {
      final double y = horizonte + 8 + i * 9.0;
      final double d = math.sin((t * 2 * math.pi) + i) * 5;
      canvas.drawLine(
        Offset(luna.dx - 16 + d, y),
        Offset(luna.dx + 16 + d, y),
        Paint()
          ..color = ColoresTradicion.violetaClaro
              .withValues(alpha: (0.06 + 0.12 * vida) - i * 0.02)
          ..strokeWidth = 1.4
          ..strokeCap = StrokeCap.round,
      );
    }

    // Torii. Si entrenaste hoy, se enciende por dentro.
    _torii(canvas, Offset(w * 0.24, horizonte + 4), h * 0.30);
    if (encendido) {
      canvas.drawCircle(
        Offset(w * 0.24, horizonte - h * 0.10),
        h * 0.16,
        Paint()
          ..shader = RadialGradient(
            colors: <Color>[
              const Color(0xFFE0A84E).withValues(alpha: 0.30),
              Colors.transparent,
            ],
          ).createShader(Rect.fromCircle(
              center: Offset(w * 0.24, horizonte - h * 0.10),
              radius: h * 0.16)),
      );
    }

    // Niebla: espesa cuando la llama está baja. Es el castigo visual, y no
    // hace falta ni una palabra de reproche.
    final int bandas = (5 - 3 * vida).round().clamp(1, 5);
    for (int i = 0; i < bandas; i++) {
      final double fase = (t + i * 0.25) % 1.0;
      final double x = -w * 0.4 + fase * w * 1.8;
      final double y = horizonte - 30 + i * 11.0;
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromLTWH(x, y, w * 0.62, 11),
          const Radius.circular(6),
        ),
        Paint()
          ..color = Colors.white.withValues(alpha: 0.03 + 0.05 * (1 - vida))
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 10),
      );
    }

    // Pétalos: solo aparecen si el templo está vivo.
    final int petalos = (7 * vida).round();
    for (int i = 0; i < petalos; i++) {
      final double s = i / 7;
      final double fase = (t * (0.6 + s * 0.5) + s) % 1.0;
      final double x =
          w * (0.06 + s * 0.88) + math.sin(fase * 2 * math.pi + i) * 14;
      final double y = -8 + fase * (h + 16);
      canvas.save();
      canvas.translate(x, y);
      canvas.rotate(fase * 4 + i);
      canvas.drawOval(
        Rect.fromCenter(center: Offset.zero, width: 5.5, height: 3.4),
        Paint()
          ..color = const Color(0xFFE7B9F5).withValues(alpha: 0.42 * vida),
      );
      canvas.restore();
    }
  }

  void _torii(Canvas canvas, Offset base, double alto) {
    final double ancho = alto * 0.78;
    final double izq = base.dx - ancho / 2;
    final double der = base.dx + ancho / 2;
    final double top = base.dy - alto;

    Paint p(double w) => Paint()
      ..color = const Color(0xFF090512)
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeWidth = w;

    canvas.drawPath(
      Path()
        ..moveTo(izq - ancho * 0.12, top + alto * 0.10)
        ..quadraticBezierTo(
            base.dx, top - alto * 0.03, der + ancho * 0.12, top + alto * 0.10),
      p(alto * 0.07),
    );
    canvas.drawLine(Offset(izq - ancho * 0.02, top + alto * 0.20),
        Offset(der + ancho * 0.02, top + alto * 0.20), p(alto * 0.05));
    canvas.drawLine(Offset(izq + ancho * 0.06, top + alto * 0.40),
        Offset(der - ancho * 0.06, top + alto * 0.40), p(alto * 0.045));
    canvas.drawLine(Offset(izq + ancho * 0.02, top + alto * 0.20),
        Offset(izq + ancho * 0.06, base.dy), p(alto * 0.06));
    canvas.drawLine(Offset(der - ancho * 0.02, top + alto * 0.20),
        Offset(der - ancho * 0.06, base.dy), p(alto * 0.06));
    canvas.drawLine(Offset(base.dx, top + alto * 0.20),
        Offset(base.dx, top + alto * 0.40), p(alto * 0.028));
  }

  @override
  bool shouldRepaint(_EscenaVivaPainter old) =>
      old.t != t || old.vida != vida || old.encendido != encendido;
}
