// TEMPLE OF STRENGTH — SECCIÓN 27: MOTOR DE PROGRESIÓN
//
// Pegar al final de main.dart, después de la sección 26.
//
// Aquí no se dibuja nada. Esto es el sistema que decide qué has ganado, qué
// eres y qué te dice el templo. Las pantallas vendrán después y solo leerán
// de aquí.
//
//   27.1  Rasgos: cómo entrenas de verdad
//   27.2  Clases del templo
//   27.3  Rachas por semanas
//   27.4  Títulos
//   27.5  Piezas de la viñeta
//   27.6  Rangos del peso del templo
//   27.7  Semanas archivadas
//   27.8  Voz de Tenshi
//   27.9  Vigilancia del cuerpo
//   27.10 Las Primeras Piedras
//   27.11 Motor y estado guardado
// ===========================================================================

// ---------------------------------------------------------------------------
// 27.1 RASGOS
//
// Una radiografía numérica de cómo entrena alguien. De aquí sale la clase, y
// nada de esto se pregunta: todo se observa.
// ---------------------------------------------------------------------------

class RasgosEntrenamiento {
  const RasgosEntrenamiento({
    required this.sesiones,
    required this.fraccionCompuesto,
    required this.fraccionUnilateral,
    required this.fraccionSinMaquina,
    required this.simetriaMedia,
    required this.densidadMedia,
    required this.descansoMedio,
    required this.duracionMedia,
    required this.repeticionesMedias,
    required this.dispersionGrupos,
    required this.constancia,
    required this.tasaAbandono,
  });

  final int sesiones;

  /// Qué parte del volumen viene de ejercicios compuestos.
  final double fraccionCompuesto;
  final double fraccionUnilateral;

  /// Volumen hecho sin máquinas ni poleas: peso corporal, bandas, mancuernas.
  final double fraccionSinMaquina;

  /// 0–1. 1 = los dos lados idénticos.
  final double simetriaMedia;
  final double densidadMedia;
  final int descansoMedio;
  final int duracionMedia;
  final double repeticionesMedias;

  /// Coeficiente de variación del volumen entre los nueve grupos.
  /// Cerca de 0 = reparto parejo. Alto = muy especializado.
  final double dispersionGrupos;

  final int constancia;
  final double tasaAbandono;

  static const RasgosEntrenamiento vacio = RasgosEntrenamiento(
    sesiones: 0,
    fraccionCompuesto: 0,
    fraccionUnilateral: 0,
    fraccionSinMaquina: 0,
    simetriaMedia: 1,
    densidadMedia: 0,
    descansoMedio: 90,
    duracionMedia: 0,
    repeticionesMedias: 0,
    dispersionGrupos: 0,
    constancia: 0,
    tasaAbandono: 0,
  );

  static RasgosEntrenamiento calcular(String usuario) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final DatosUsuario d = a.de(usuario);
    final List<Sesion> ses = d.completadas;
    if (ses.isEmpty) return vacio;

    double volTotal = 0;
    double volCompuesto = 0;
    double volUnilateral = 0;
    double volSinMaquina = 0;
    double repsPesadas = 0;
    int seriesContadas = 0;
    int minutos = 0;
    final List<double> simetrias = <double>[];
    final List<double> densidades = <double>[];
    final List<int> descansos = <int>[];
    final Map<GrupoMuscular, double> porGrupo = <GrupoMuscular, double>{};

    for (final Sesion s in ses) {
      minutos += s.minutos;
      if (s.densidad > 0) densidades.add(s.densidad);
      final int? dm = s.descansoMedio;
      if (dm != null) descansos.add(dm);
      final double? sim = s.simetria;
      if (sim != null) simetrias.add(sim);

      s.volumenPorGrupo.forEach((GrupoMuscular g, double v) {
        porGrupo[g] = (porGrupo[g] ?? 0) + v;
      });

      for (final EjercicioSesion e in s.ejercicios) {
        final Ejercicio? def = e.definicion;
        final double v = e.volumen;
        if (v <= 0 || def == null) continue;
        volTotal += v;
        if (def.compuesto) volCompuesto += v;
        if (def.unilateral) volUnilateral += v;
        if (def.equipo != Equipo.maquina && def.equipo != Equipo.polea) {
          volSinMaquina += v;
        }
        for (final SerieRegistrada x in e.seriesEfectivas) {
          repsPesadas += x.repeticiones;
          seriesContadas++;
        }
      }
    }

    // Dispersión: qué tan desigual reparte el volumen entre los nueve grupos.
    double dispersion = 0;
    if (porGrupo.isNotEmpty) {
      final List<double> vals = <double>[
        for (final GrupoMuscular g in GrupoMuscular.values) porGrupo[g] ?? 0,
      ];
      final double media =
          vals.fold<double>(0, (double a, double b) => a + b) / vals.length;
      if (media > 0) {
        final double varianza = vals.fold<double>(
                0, (double a, double b) => a + math.pow(b - media, 2)) /
            vals.length;
        dispersion = math.sqrt(varianza) / media;
      }
    }

    double media(List<double> l) => l.isEmpty
        ? 0
        : l.fold<double>(0, (double a, double b) => a + b) / l.length;

    return RasgosEntrenamiento(
      sesiones: ses.length,
      fraccionCompuesto: volTotal <= 0 ? 0 : volCompuesto / volTotal,
      fraccionUnilateral: volTotal <= 0 ? 0 : volUnilateral / volTotal,
      fraccionSinMaquina: volTotal <= 0 ? 0 : volSinMaquina / volTotal,
      simetriaMedia: simetrias.isEmpty ? 1 : media(simetrias),
      densidadMedia: media(densidades),
      descansoMedio: descansos.isEmpty
          ? 90
          : descansos.reduce((int a, int b) => a + b) ~/ descansos.length,
      duracionMedia: minutos ~/ ses.length,
      repeticionesMedias:
          seriesContadas == 0 ? 0 : repsPesadas / seriesContadas,
      dispersionGrupos: dispersion,
      constancia: a.llama(usuario).valor,
      tasaAbandono: d.sesiones.isEmpty
          ? 0
          : d.sesiones
                  .where((Sesion s) => s.estado == EstadoSesion.abandonada)
                  .length /
              d.sesiones.length,
    );
  }
}

// ---------------------------------------------------------------------------
// 27.2 CLASES DEL TEMPLO
//
// La clase NO se elige: se gana entrenando, y cambia si tú cambias. En otras
// apps eliges arquetipo el primer día y ahí se queda. Aquí es un espejo:
// descubrir que te has vuelto Monje sin proponértelo vale más que cualquier
// insignia que hayas escogido de una lista.
// ---------------------------------------------------------------------------

enum ClaseTemplo { guardian, monje, tormenta, danzante, peregrino, asceta }

class DefinicionClase {
  const DefinicionClase({
    required this.clase,
    required this.nombre,
    required this.kanji,
    required this.lema,
    required this.descripcion,
    required this.glifo,
  });

  final ClaseTemplo clase;
  final String nombre;
  final String kanji;
  final String lema;
  final String descripcion;
  final TempleGlyph glifo;
}

class ClasesDelTemplo {
  const ClasesDelTemplo._();

  /// Mínimo de sesiones antes de asignar clase. Con menos, cualquier lectura
  /// sería ruido.
  static const int minimoSesiones = 6;

  static const Map<ClaseTemplo, DefinicionClase> todas =
      <ClaseTemplo, DefinicionClase>{
    ClaseTemplo.guardian: DefinicionClase(
      clase: ClaseTemplo.guardian,
      nombre: 'Guardián de Hierro',
      kanji: '鉄衛',
      lema: 'Lo pesado, bien hecho',
      descripcion:
          'Tu volumen vive en los movimientos grandes y las repeticiones '
          'bajas. No buscas variedad: buscas que el número suba.',
      glifo: TempleGlyph.mancuerna,
    ),
    ClaseTemplo.monje: DefinicionClase(
      clase: ClaseTemplo.monje,
      nombre: 'Monje',
      kanji: '僧',
      lema: 'Estar es la técnica',
      descripcion:
          'No eres el que más levanta. Eres el que nunca falta, y a los tres '
          'años eso deja a todos los demás atrás.',
      glifo: TempleGlyph.loto,
    ),
    ClaseTemplo.tormenta: DefinicionClase(
      clase: ClaseTemplo.tormenta,
      nombre: 'Tormenta',
      kanji: '嵐',
      lema: 'Entrar, arrasar, salir',
      descripcion:
          'Sesiones cortas y densas, descansos mínimos. Haces en cuarenta '
          'minutos lo que otros reparten en noventa.',
      glifo: TempleGlyph.rayo,
    ),
    ClaseTemplo.danzante: DefinicionClase(
      clase: ClaseTemplo.danzante,
      nombre: 'Danzante',
      kanji: '舞',
      lema: 'Los dos lados, el mismo peso',
      descripcion:
          'Trabajas unilateral y tus dos mitades se parecen. Es el camino '
          'lento que evita las lesiones que paran a los demás.',
      glifo: TempleGlyph.espadas,
    ),
    ClaseTemplo.peregrino: DefinicionClase(
      clase: ClaseTemplo.peregrino,
      nombre: 'Peregrino',
      kanji: '巡',
      lema: 'Ningún camino olvidado',
      descripcion:
          'Repartes el trabajo entre los nueve grupos sin favoritos. Tu cuerpo '
          'no tiene puntos ciegos.',
      glifo: TempleGlyph.montana,
    ),
    ClaseTemplo.asceta: DefinicionClase(
      clase: ClaseTemplo.asceta,
      nombre: 'Asceta',
      kanji: '苦行',
      lema: 'El cuerpo basta',
      descripcion:
          'Poco material, ninguna excusa. Entrenas con lo que hay y aun así '
          'el número sube.',
      glifo: TempleGlyph.torii,
    ),
  };

  /// Puntúa las seis y devuelve la dominante. Null si aún no hay historial
  /// suficiente para decir algo honesto.
  static ClaseTemplo? evaluar(RasgosEntrenamiento r) {
    if (r.sesiones < minimoSesiones) return null;

    final Map<ClaseTemplo, double> p = <ClaseTemplo, double>{
      ClaseTemplo.guardian: r.fraccionCompuesto * 60 +
          (r.repeticionesMedias <= 7 ? 30 : 0) +
          (r.descansoMedio >= 120 ? 15 : 0),
      ClaseTemplo.monje: (r.constancia / 100) * 65 +
          (1 - r.tasaAbandono) * 25 +
          (r.sesiones >= 20 ? 12 : 0),
      ClaseTemplo.tormenta: (r.densidadMedia / 120).clamp(0.0, 1.0) * 45 +
          (r.descansoMedio <= 70 ? 30 : 0) +
          (r.duracionMedia <= 45 ? 20 : 0),
      ClaseTemplo.danzante: r.fraccionUnilateral * 70 +
          (r.simetriaMedia >= 0.92 ? 28 : 0),
      ClaseTemplo.peregrino:
          ((1 - r.dispersionGrupos).clamp(0.0, 1.0)) * 75 +
              (r.fraccionCompuesto > 0.4 ? 10 : 0),
      ClaseTemplo.asceta: r.fraccionSinMaquina * 70 +
          (r.fraccionCompuesto > 0.5 ? 12 : 0),
    };

    ClaseTemplo mejor = ClaseTemplo.monje;
    double max = -1;
    p.forEach((ClaseTemplo c, double v) {
      if (v > max) {
        max = v;
        mejor = c;
      }
    });
    return mejor;
  }
}

// ---------------------------------------------------------------------------
// 27.3 RACHAS
//
// Se cuentan SEMANAS CUMPLIDAS, no días seguidos.
//
// Si prometiste tres días y haces tres, la semana entera cuenta. Los días de
// descanso no rompen nada: es lo correcto fisiológicamente y, sobre todo,
// evita que alguien entrene enfermo por no perder una cifra en la pantalla.
//
// Además, cada cuatro semanas cumplidas se gana un escudo que protege una
// semana fallada. Baja la ansiedad sin regalar el progreso.
// ---------------------------------------------------------------------------

enum NivelRacha {
  ninguna,
  chispa,
  brasa,
  llama,
  hoguera,
  fuegoTemplo,
  fuegoEterno,
  solInterior,
}

class DefinicionRacha {
  const DefinicionRacha({
    required this.nivel,
    required this.nombre,
    required this.kanji,
    required this.color,
    required this.glifo,
    required this.desdeSemanas,
    required this.mensaje,
  });

  final NivelRacha nivel;
  final String nombre;
  final String kanji;
  final Color color;
  final TempleGlyph glifo;
  final int desdeSemanas;
  final String mensaje;
}

class Racha {
  const Racha({
    required this.semanas,
    required this.diasSeguidos,
    required this.escudos,
    required this.sesionesEstaSemana,
    required this.objetivoSemanal,
  });

  /// Semanas consecutivas cumpliendo el objetivo.
  final int semanas;
  final int diasSeguidos;
  final int escudos;
  final int sesionesEstaSemana;
  final int objetivoSemanal;

  bool get semanaCumplida => sesionesEstaSemana >= objetivoSemanal;
  int get faltan =>
      (objetivoSemanal - sesionesEstaSemana).clamp(0, objetivoSemanal);

  DefinicionRacha get definicion {
    DefinicionRacha actual = NivelesDeRacha.todas.first;
    for (final DefinicionRacha d in NivelesDeRacha.todas) {
      if (semanas >= d.desdeSemanas) actual = d;
    }
    return actual;
  }

  /// Cuánto falta para el siguiente escalón. Null si está en el último.
  DefinicionRacha? get siguiente {
    for (final DefinicionRacha d in NivelesDeRacha.todas) {
      if (d.desdeSemanas > semanas) return d;
    }
    return null;
  }
}

