DateTime lunesDe(DateTime d) {
  final DateTime limpio = DateTime(d.year, d.month, d.day);
  return limpio.subtract(Duration(days: limpio.weekday - 1));
}

// ---------------------------------------------------------------------------
// 27.4 TÍTULOS
//
// Frases, no adjetivos. Se ganan por hazañas concretas y se equipa uno solo
// en el perfil: elegir cuál enseñas dice tanto como haberlo conseguido.
// ---------------------------------------------------------------------------

/// Todo lo que un título necesita para saber si se ha ganado.
class ContextoProgreso {
  const ContextoProgreso({
    required this.usuario,
    required this.sesiones,
    required this.rasgos,
    required this.perfil,
    required this.racha,
    required this.llama,
    required this.pesoTemplo,
    required this.nivel,
    required this.records,
    required this.clase,
  });

  final String usuario;
  final List<Sesion> sesiones;
  final RasgosEntrenamiento rasgos;
  final PerfilEntrenamiento perfil;
  final Racha racha;
  final Llama llama;
  final double pesoTemplo;
  final NivelTemplo nivel;
  final Map<String, RecordPersonal> records;
  final ClaseTemplo? clase;

  int sesionesDonde(bool Function(Sesion) test) =>
      sesiones.where(test).length;
}

class Titulo {
  const Titulo({
    required this.id,
    required this.texto,
    required this.pista,
    required this.condicion,
    this.raro = false,
  });

  final String id;
  final String texto;

  /// Qué hay que hacer para ganarlo. Se enseña aunque esté bloqueado: un
  /// título invisible no motiva a nadie.
  final String pista;
  final bool Function(ContextoProgreso) condicion;

  /// Los raros se muestran en dorado.
  final bool raro;
}

class TitulosDelTemplo {
  const TitulosDelTemplo._();

  static final List<Titulo> todos = <Titulo>[
    Titulo(
