      texto: 'Vuelve siempre',
      pista: 'Regresa tras dos semanas o más de ausencia',
      condicion: (ContextoProgreso c) {
        final List<Sesion> s = c.sesiones;
        for (int i = 1; i < s.length; i++) {
          if (s[i].inicio.difference(s[i - 1].inicio).inDays >= 14) return true;
