    Titulo(
      id: 'nunca_pierna',
      texto: 'Nunca salta pierna',
      pista: 'Que piernas no pase 7 días sin trabajo, con 15 sesiones hechas',
      condicion: (ContextoProgreso c) =>
          c.sesiones.length >= 15 &&
          (c.perfil.diasDesdeGrupo[GrupoMuscular.piernas] ?? 99) <= 7,
