    Titulo(
      id: 'rompe_hierro',
      texto: 'Rompe el hierro',
      pista: 'Consigue récord en 10 ejercicios distintos',
      condicion: (ContextoProgreso c) => c.records.length >= 10,
    ),
    Titulo(
      id: 'madrugador',
      texto: 'Madrugador del templo',
      pista: 'Entrena 10 veces antes de las 7 de la mañana',
      condicion: (ContextoProgreso c) =>
          c.sesionesDonde((Sesion s) => s.inicio.hour < 7) >= 10,
      raro: true,
    ),
    Titulo(
      id: 'hijo_noche',
      texto: 'Hijo de la noche',
      pista: 'Entrena 10 veces después de las 21',
      condicion: (ContextoProgreso c) =>
          c.sesionesDonde((Sesion s) => s.inicio.hour >= 21) >= 10,
    ),
    Titulo(
      id: 'sin_excusas',
      texto: 'Sin excusas',
      pista: 'Entrena 5 veces con la disposición por debajo de 40',
      condicion: (ContextoProgreso c) => c.sesionesDonde((Sesion s) =>
              (s.disposicionAlIniciar ?? 100) < 40) >=
          5,
      raro: true,
    ),
    Titulo(
      id: 'mueve_montanas',
      texto: 'El que mueve montañas',
      pista: 'Acumula 250 toneladas de peso del templo',
      condicion: (ContextoProgreso c) => c.pesoTemplo >= 250000,
      raro: true,
    ),
    Titulo(
      id: 'simetrico',
      texto: 'Las dos mitades',
      pista: 'Mantén una simetría superior al 95%',
      condicion: (ContextoProgreso c) =>
          c.rasgos.sesiones >= 10 && c.rasgos.simetriaMedia >= 0.95,
    ),
    Titulo(
      id: 'corazon_brasa',
      texto: 'Corazón de brasa',
      pista: 'Recupera la llama desde apagada hasta ardiente',
      condicion: (ContextoProgreso c) =>
          c.llama.valor >= 65 && c.racha.semanas >= 2 && c.sesiones.length >= 12,
      raro: true,
    ),
    Titulo(
      id: 'maraton',
      texto: 'El de aliento largo',
      pista: 'Completa una sesión de más de 90 minutos',
      condicion: (ContextoProgreso c) =>
          c.sesionesDonde((Sesion s) => s.minutos >= 90) >= 1,
    ),
    Titulo(
      id: 'relampago',
      texto: 'Relámpago',
      pista: 'Sesión de menos de 30 minutos con más de 100 kg por minuto',
      condicion: (ContextoProgreso c) => c.sesionesDonde(
              (Sesion s) => s.minutos <= 30 && s.densidad >= 100) >=
          1,
      raro: true,
    ),
    Titulo(
      id: 'nueve_caminos',
      texto: 'Los nueve caminos',
      pista: 'Trabaja los nueve grupos musculares en una sola semana',
      condicion: (ContextoProgreso c) {
        final DateTime lunes = lunesDe(DateTime.now());
        final Set<GrupoMuscular> g = <GrupoMuscular>{};
        for (final Sesion s in c.sesiones) {
          if (s.inicio.isBefore(lunes)) continue;
          g.addAll(s.gruposTrabajados);
        }
        return g.length >= 9;
      },
      raro: true,
    ),
    Titulo(
      id: 'constante',
      texto: 'El constante',
      pista: 'Completa 50 sesiones',
      condicion: (ContextoProgreso c) => c.sesiones.length >= 50,
    ),
    Titulo(
      id: 'centurion',
      texto: 'Centurión',
      pista: 'Completa 100 sesiones',
      condicion: (ContextoProgreso c) => c.sesiones.length >= 100,
      raro: true,
    ),
    Titulo(
      id: 'nada_pendiente',
      texto: 'Nada pendiente',
      pista: 'Termina 20 sesiones sin saltarte ningún ejercicio',
      condicion: (ContextoProgreso c) => c.sesionesDonde((Sesion s) => s
              .ejercicios
              .every((EjercicioSesion e) => e.seriesEfectivas.isNotEmpty)) >=
          20,
    ),
    Titulo(
      id: 'maestro_camino',
      texto: 'Maestro del camino',
      pista: 'Alcanza el nivel 50',
      condicion: (ContextoProgreso c) => c.nivel.nivel >= 50,
      raro: true,
    ),
  ];

  static Titulo? porId(String id) {
    for (final Titulo t in todos) {
      if (t.id == id) return t;
    }
    return null;
  }
}

// ---------------------------------------------------------------------------
// 27.5 PIEZAS DE LA VIÑETA
//
// La escena se descompone en capas y cada pieza se gana por una hazaña
// concreta. NO hay tienda de monedas a propósito: así la decoración es un
// currículum. En el Clan, ver el banner de alguien te dice qué hizo para
// tenerlo. Con monedas solo diría quién jugó más horas.
// ---------------------------------------------------------------------------

enum CapaVineta {
  cielo,
  luna,
  montanas,
  agua,
  estructura,
  vegetacion,
  criatura,
  clima,
}

extension EtiquetaCapa on CapaVineta {
  String get etiqueta {
    switch (this) {
      case CapaVineta.cielo:
        return 'Cielo';
      case CapaVineta.luna:
        return 'Luna';
      case CapaVineta.montanas:
        return 'Montañas';
      case CapaVineta.agua:
        return 'Agua';
      case CapaVineta.estructura:
        return 'Estructura';
      case CapaVineta.vegetacion:
        return 'Vegetación';
      case CapaVineta.criatura:
        return 'Criatura';
      case CapaVineta.clima:
        return 'Clima';
    }
  }
}

class PiezaVineta {
  const PiezaVineta({
    required this.id,
    required this.capa,
    required this.nombre,
    required this.comoSeGana,
    required this.condicion,
    this.base = false,
    this.rara = false,
