  static List<PiezaVineta> deCapa(CapaVineta c) =>
      todas.where((PiezaVineta p) => p.capa == c).toList();

  static PiezaVineta? porId(String id) {
    for (final PiezaVineta p in todas) {
      if (p.id == id) return p;
    }
    return null;
  }

  static Set<String> get base => todas
      .where((PiezaVineta p) => p.base)
      .map((PiezaVineta p) => p.id)
      .toSet();

  /// Configuración por defecto: una pieza base por capa.
  static Map<CapaVineta, String> configInicial() => <CapaVineta, String>{
        for (final CapaVineta c in CapaVineta.values)
          c: deCapa(c).firstWhere((PiezaVineta p) => p.base).id,
      };
}

// ---------------------------------------------------------------------------
// 27.6 RANGOS DEL PESO DEL TEMPLO
//
// El peso acumulado no solo levanta piezas: da títulos propios. Y se traduce
// a algo tangible, porque «182.000 kg» no significa nada para nadie.
// ---------------------------------------------------------------------------

class RangoPeso {
  const RangoPeso({
    required this.kilos,
    required this.titulo,
    required this.descripcion,
  });

  final double kilos;
  final String titulo;
  final String descripcion;
}

class RangosDelPeso {
  const RangosDelPeso._();

  static const List<RangoPeso> todos = <RangoPeso>[
    RangoPeso(
      kilos: 0,
      titulo: 'Sin carga',
      descripcion: 'Todo templo empieza vacío.',
    ),
    RangoPeso(
      kilos: 1000,
      titulo: 'Cargador',
      descripcion: 'Una tonelada. Ya has movido algo real.',
    ),
    RangoPeso(
      kilos: 10000,
      titulo: 'Portador de piedra',
      descripcion: 'Diez toneladas salidas de tus manos.',
    ),
    RangoPeso(
      kilos: 50000,
      titulo: 'Cantero',
      descripcion: 'Cincuenta toneladas. El templo tiene cimientos.',
    ),
    RangoPeso(
      kilos: 120000,
      titulo: 'Constructor',
      descripcion: 'Ciento veinte toneladas. Esto ya se ve desde lejos.',
    ),
    RangoPeso(
      kilos: 250000,
      titulo: 'El que mueve montañas',
      descripcion: 'Un cuarto de millón de kilos.',
    ),
    RangoPeso(
      kilos: 500000,
      titulo: 'Titán',
      descripcion: 'Medio millón. Muy poca gente llega aquí.',
    ),
    RangoPeso(
      kilos: 1000000,
      titulo: 'Leyenda de piedra',
      descripcion: 'Un millón de kilos. El templo lleva tu nombre.',
    ),
  ];

  static RangoPeso actual(double kilos) {
    RangoPeso r = todos.first;
    for (final RangoPeso x in todos) {
      if (kilos >= x.kilos) r = x;
    }
    return r;
  }

  static RangoPeso? siguiente(double kilos) {
    for (final RangoPeso x in todos) {
      if (kilos < x.kilos) return x;
    }
    return null;
  }

  /// Traduce el tonelaje a algo que se pueda imaginar.
  static String equivalencia(double kilos) {
    if (kilos < 500) return 'como una moto';
    if (kilos < 1500) return 'como un coche pequeño';
    if (kilos < 6000) return 'como un elefante africano';
    if (kilos < 30000) return 'como cinco elefantes';
    if (kilos < 80000) return 'como un avión de pasajeros';
    if (kilos < 200000) return 'como una ballena azul y media';
    if (kilos < 600000) return 'como la torre Eiffel entera';
    return 'como un buque de carga';
  }
}

// ---------------------------------------------------------------------------
// 27.7 SEMANAS ARCHIVADAS
//
// En el Dojo solo vive la semana en curso. Al cerrarse, se guarda aquí con su
// resumen y el historial queda navegable.
// ---------------------------------------------------------------------------

class SemanaArchivada {
  const SemanaArchivada({
    required this.lunes,
    required this.sesiones,
    required this.volumen,
    required this.minutos,
    required this.grupos,
    required this.objetivo,
    required this.mejorDiaVolumen,
    required this.records,
  });

  final DateTime lunes;
  final int sesiones;
  final double volumen;
  final int minutos;
  final List<GrupoMuscular> grupos;
  final int objetivo;
  final double mejorDiaVolumen;
  final int records;

  bool get cumplida => sesiones >= objetivo;
  DateTime get domingo => lunes.add(const Duration(days: 6));

  String get etiqueta =>
      '${lunes.day}/${lunes.month} – ${domingo.day}/${domingo.month}';

  Map<String, dynamic> toMap() => <String, dynamic>{
        'lunes': lunes.toIso8601String(),
        'sesiones': sesiones,
        'volumen': volumen,
        'minutos': minutos,
        'grupos': grupos.map((GrupoMuscular g) => g.name).toList(),
        'objetivo': objetivo,
        'mejor_dia': mejorDiaVolumen,
        'records': records,
      };

  static SemanaArchivada generar(String usuario, DateTime lunes) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final DateTime fin = lunes.add(const Duration(days: 7));
    final List<Sesion> ses = a
        .de(usuario)
        .completadas
        .where((Sesion s) =>
            !s.inicio.isBefore(lunes) && s.inicio.isBefore(fin))
        .toList();

    final Set<GrupoMuscular> grupos = <GrupoMuscular>{};
    double vol = 0;
    int min = 0;
    final Map<int, double> porDia = <int, double>{};

    for (final Sesion s in ses) {
      vol += s.volumenTotal;
      min += s.minutos;
      grupos.addAll(s.gruposTrabajados);
      porDia[s.inicio.weekday] =
          (porDia[s.inicio.weekday] ?? 0) + s.volumenTotal;
    }

    return SemanaArchivada(
      lunes: lunes,
      sesiones: ses.length,
      volumen: vol,
      minutos: min,
      grupos: grupos.toList(),
      objetivo: a.diasObjetivo(usuario).floor(),
      mejorDiaVolumen:
          porDia.values.isEmpty ? 0 : porDia.values.reduce(math.max),
      records: 0,
    );
  }
}

// ---------------------------------------------------------------------------
// 27.8 LA VOZ DE TENSHI
//
// El mismo hecho, tres redacciones según la voz elegida, más un cierre propio
// de cada espíritu. Doce espíritus por tres voces: dos usuarios no leen lo
// mismo nunca.
//
// REGLA QUE NO SE ROMPE: la voz no se aplica a los avisos de salud. Aunque
// hayas elegido «sin rodeos», un entrenador que aprieta a alguien que duerme
// cuatro horas no es exigente, es dañino.
// ---------------------------------------------------------------------------

enum TipoAviso {
  horaDeEntrenar,
  agua,
  cierreDelDia,
  rachaEnRiesgo,
  recordRoto,
  grupoEnDeuda,
  regresoTrasAusencia,
  subidaDeNivel,
  piezaNueva,
  descansoMerecido,
  bienvenida,
}

class MensajeTenshi {
  const MensajeTenshi({
    required this.tipo,
    required this.texto,
    this.firma,
    this.calido = false,
  });

  final TipoAviso tipo;
  final String texto;

  /// Coletilla del espíritu asignado.
  final String? firma;

  /// Los mensajes cálidos ignoran la voz elegida.
  final bool calido;

  String get completo => firma == null ? texto : '$texto $firma';
}

class VozTenshi {
  const VozTenshi._();

  /// texto[tipo][voz]
  static const Map<TipoAviso, Map<String, String>> _base =
      <TipoAviso, Map<String, String>>{
    TipoAviso.horaDeEntrenar: <String, String>{
      'serena': 'Es tu hora. El templo está abierto cuando quieras entrar.',
