    },
    TipoAviso.rachaEnRiesgo: <String, String>{
      'serena':
          'Te falta una sesión para cumplir la semana. Aún queda tiempo.',
      'exigente': 'Una sesión. Eso separa esta semana de la anterior.',
      'alegre': '¡Falta una! No me hagas usar el escudo, que duele.',
    },
    TipoAviso.recordRoto: <String, String>{
