class IdentidadUsuario {
  IdentidadUsuario({required this.usuario});

  /// Inmutable. Es la llave de la cuenta.
  final String usuario;

  /// Cómo quiere que le llamen. Por defecto, el usuario.
  String? nombreVisible;

  /// Una línea. Corta a propósito: las biografías largas no las lee nadie.
  String biografia = '';

  final List<String> etiquetas = <String>[];

  // -- Sello --------------------------------------------------------------
  int paleta = 0;
  SimboloSello simbolo = SimboloSello.kanji;
  MarcoSello marco = MarcoSello.simple;

  /// Foto de perfil elegida de la galería (ruta en el almacén del Clan).
  /// Si es null, el sello muestra su símbolo.
  String? foto;

  /// Estilo del nombre en el Clan (del Pase). Null = normal.
  String? estiloNombre;

  /// Enlaces a sus redes: instagram, facebook, tiktok, extra1, extra2.
  final Map<String, String> redes = <String, String>{};

  String nombreMostrado(String porDefecto) =>
      (nombreVisible == null || nombreVisible!.trim().isEmpty)
          ? porDefecto
          : nombreVisible!.trim();

  Map<String, dynamic> toMap() => <String, dynamic>{
        'usuario': usuario,
        'nombre_visible': nombreVisible,
        'biografia': biografia,
        'etiquetas': etiquetas,
        'paleta': paleta,
        'simbolo': simbolo.name,
        'marco': marco.name,
        'estilo': estiloNombre,
        'redes': redes,
      };
}

