/// Kanji del espíritu asignado en El Ascenso.
String kanjiDeEspiritu(String nombre) {
  for (final Espiritu e in espiritusDelTemplo.values) {
    if (e.nombre == nombre) return e.kanji;
  }
  return '道';
}

