/// Los cinco primeros se ganan por nivel. Los animados se compran con mon o
/// se ganan con una hazaña (racha, Ranked, sesiones). Los dos últimos son del
/// Pase del Templo.
enum MarcoSello {
  simple,
  doble,
  dentado,
  laurel,
  sagrado,
  sakura,
  llama,
  trueno,
  luna,
  enso,
  aurora,
  dragon,
  oro,
  kintsugi,
  hoshi,
}

extension DatosMarco on MarcoSello {
  String get etiqueta {
    switch (this) {
      case MarcoSello.simple:
        return 'Aro simple';
      case MarcoSello.doble:
        return 'Doble anillo';
      case MarcoSello.dentado:
        return 'Aro dentado';
      case MarcoSello.laurel:
        return 'Corona';
      case MarcoSello.sagrado:
        return 'Aro sagrado';
      case MarcoSello.sakura:
        return 'Ronda de sakura';
      case MarcoSello.llama:
        return 'Aro de fuego';
      case MarcoSello.trueno:
        return 'Trueno';
      case MarcoSello.luna:
        return 'Órbita lunar';
      case MarcoSello.enso:
        return 'Ensō de tinta';
      case MarcoSello.aurora:
        return 'Aurora';
      case MarcoSello.dragon:
        return 'Dragón guardián';
      case MarcoSello.oro:
        return 'Oro imperial';
      case MarcoSello.kintsugi:
        return 'Kintsugi';
      case MarcoSello.hoshi:
        return 'Constelación';
    }
  }

  /// Exclusivos del Pase: se ven mientras el Pase está activo.
  bool get dePase => this == MarcoSello.kintsugi || this == MarcoSello.hoshi;

  int get nivelMinimo {
    switch (this) {
      case MarcoSello.doble:
        return 5;
      case MarcoSello.dentado:
        return 15;
      case MarcoSello.laurel:
        return 30;
      case MarcoSello.sagrado:
        return 50;
      default:
        return 1;
    }
  }

  bool get animado => index >= MarcoSello.sakura.index;

  /// Mon que cuesta en el taller (0 = no se vende).
  int get precio {
    switch (this) {
      case MarcoSello.sakura:
        return 400;
      case MarcoSello.luna:
      case MarcoSello.aurora:
        return 900;
      case MarcoSello.oro:
        return 2000;
      default:
        return 0;
    }
  }

  bool get deLogro =>
      this == MarcoSello.llama || this == MarcoSello.trueno || this == MarcoSello.enso || this == MarcoSello.dragon;

  RarezaPieza? get rareza {
    switch (this) {
      case MarcoSello.sakura:
      case MarcoSello.llama:
      case MarcoSello.enso:
        return RarezaPieza.rara;
      case MarcoSello.luna:
      case MarcoSello.aurora:
      case MarcoSello.trueno:
        return RarezaPieza.epica;
      case MarcoSello.dragon:
      case MarcoSello.oro:
      case MarcoSello.kintsugi:
      case MarcoSello.hoshi:
        return RarezaPieza.legendaria;
      default:
        return null;
    }
  }

  /// Cómo se consigue, tal cual se enseña mientras está bloqueado.
  String get pista {
    switch (this) {
      case MarcoSello.llama:
        return 'Mantén la racha 8 semanas';
      case MarcoSello.trueno:
        return 'Alcanza Daimyō en cualquier músculo (Ranked)';
      case MarcoSello.enso:
        return 'Completa 100 sesiones';
      case MarcoSello.dragon:
        return 'Lleva tu cuerpo a Shōgun en Ranked';
      case MarcoSello.kintsugi:
      case MarcoSello.hoshi:
        return 'Exclusivo del Pase del Templo';
      default:
        return precio > 0 ? '$precio mon en el taller' : 'Nivel $nivelMinimo';
    }
  }

  /// Cómo se guarda entre las piezas del progreso (y en la nube).
  String get clave => 'marco_$name';
}

/// Quién tiene qué marco.
class MarcosTemplo {
  const MarcosTemplo._();

  static bool _hazana(MarcoSello m, String u) {
    switch (m) {
      case MarcoSello.llama:
        return MotorProgresion.instancia.racha(u).semanas >= 8;
      case MarcoSello.trueno:
        return MotorRanked.de(u).musculos.values.any((MusculoRanked x) => x.rango >= 12);
      case MarcoSello.enso:
        return AlmacenTemplo.instancia.de(u).completadas.length >= 100;
      case MarcoSello.dragon:
        return MotorRanked.de(u).rangoCuerpo >= 15;
      default:
        return false;
    }
  }

  static bool disponible(String u, MarcoSello m, int nivel) {
    if (m.dePase) return PaseTemplo.instancia.activo;
    if (!m.animado) return nivel >= m.nivelMinimo;
    if (MotorProgresion.instancia.de(u).piezas.contains(m.clave)) return true;
    return m.deLogro && _hazana(m, u);
  }

  /// Marcos de hazaña recién conseguidos. Se apuntan para no celebrarlos
  /// dos veces.
  static List<MarcoSello> nuevos(String u) {
    final Set<String> piezas = MotorProgresion.instancia.de(u).piezas;
    final List<MarcoSello> r = <MarcoSello>[];
    for (final MarcoSello m in MarcoSello.values) {
      if (!m.deLogro || piezas.contains(m.clave)) continue;
      if (_hazana(m, u)) {
        piezas.add(m.clave);
        r.add(m);
      }
    }
    if (r.isNotEmpty) NubeTemplo.instancia.marcarCambio();
    return r;
  }
}

class PaletaSello {
  const PaletaSello({
    required this.nombre,
    required this.fondoA,
    required this.fondoB,
    required this.tinta,
  });

  final String nombre;
  final Color fondoA;
  final Color fondoB;
  final Color tinta;
}

