class SelloUsuario extends StatelessWidget {
  const SelloUsuario({
    super.key,
    required this.identidad,
    required this.kanji,
    required this.nivel,
    this.size = 88,
    this.mostrarNivel = true,
    this.animar,
  });

  final IdentidadUsuario identidad;
  final String kanji;
  final int nivel;
  final double size;
  final bool mostrarNivel;

  /// Los marcos animados se mueven en los sellos grandes (perfil, editor).
  /// En las listas pequeñas quedan quietos para no gastar batería.
  final bool? animar;

  @override
  Widget build(BuildContext context) {
    final PaletaSello p =
        PaletasSello.todas[identidad.paleta % PaletasSello.todas.length];
    final TempleGlyph? g = identidad.simbolo.glifo;

    return SizedBox(
      width: size,
      height: size,
      child: Stack(
        alignment: Alignment.center,
        clipBehavior: Clip.none,
        children: <Widget>[
          if (identidad.marco.animado && (animar ?? size >= 56))
            MarcoVivo(paleta: p, marco: identidad.marco, size: size)
          else
            CustomPaint(
              size: Size.square(size),
              painter: _SelloPainter(paleta: p, marco: identidad.marco),
            ),
          if (identidad.foto != null)
            ClipOval(
              child: SizedBox(
                width: size * 0.74,
                height: size * 0.74,
                child: ImagenClan(
                  key: ValueKey<String>(identidad.foto!),
                  ruta: identidad.foto!,
                ),
              ),
            )
          else if (g == null)
            Text(
              kanji,
              style: TextStyle(
                fontSize: size * 0.40,
                height: 1,
                color: p.tinta,
              ),
            )
          else
            TempleIcon(g, size: size * 0.40, color: p.tinta, trazo: 1.6),
          if (mostrarNivel)
            Positioned(
              bottom: -size * 0.04,
              child: Container(
                padding: EdgeInsets.symmetric(
                  horizontal: size * 0.10,
                  vertical: size * 0.028,
                ),
                decoration: BoxDecoration(
                  color: TempleColors.violeta,
                  borderRadius: BorderRadius.circular(999),
                  border: Border.all(color: TempleColors.negro, width: 2),
                ),
                child: Text(
                  '$nivel',
                  style: TextStyle(
                    fontSize: size * 0.14,
                    fontWeight: FontWeight.w700,
                    color: Colors.white,
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }
}

/// Un marco animado en bucle de 6 s.
class MarcoVivo extends StatefulWidget {
  const MarcoVivo({super.key, required this.paleta, required this.marco, required this.size});
  final PaletaSello paleta;
  final MarcoSello marco;
  final double size;

  @override
  State<MarcoVivo> createState() => _MarcoVivoState();
}

class _MarcoVivoState extends State<MarcoVivo>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;
  late final AnimationController _c = AnimationController(vsync: this, duration: const Duration(seconds: 6));

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final bool reducir = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    if (reducir) {
      _c.stop();
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => RepaintBoundary(
        child: AnimatedBuilder(
          animation: _c,
          builder: (BuildContext context, _) => CustomPaint(
            size: Size.square(widget.size),
            painter: _SelloPainter(paleta: widget.paleta, marco: widget.marco, t: _c.value),
          ),
        ),
      );
}

double _hashMarco(double a, double b) {
  final double x = math.sin(a * 127.1 + b * 311.7) * 43758.5453;
  return x - x.floorToDouble();
}

class _SelloPainter extends CustomPainter {
  const _SelloPainter({required this.paleta, required this.marco, this.t = 0});

  final PaletaSello paleta;
  final MarcoSello marco;

  /// 0–1 del bucle. Todo usa múltiplos enteros de 2π·t: cierra sin saltos.
  final double t;

  @override
  void paint(Canvas canvas, Size size) {
    final Offset c = size.center(Offset.zero);
    final double r = size.shortestSide / 2;

    // Disco de fondo.
    canvas.drawCircle(
      c,
      r * 0.86,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: <Color>[paleta.fondoA, paleta.fondoB],
        ).createShader(Rect.fromCircle(center: c, radius: r * 0.86)),
    );

    final Paint aro = Paint()
      ..style = PaintingStyle.stroke
      ..color = paleta.tinta.withValues(alpha: 0.55)
      ..strokeWidth = r * 0.045
      ..strokeCap = StrokeCap.round;

    switch (marco) {
      case MarcoSello.simple:
        canvas.drawCircle(c, r * 0.90, aro);
      case MarcoSello.doble:
        canvas.drawCircle(c, r * 0.90, aro);
        canvas.drawCircle(
          c,
          r * 0.99,
          aro..strokeWidth = r * 0.022,
        );
      case MarcoSello.dentado:
        canvas.drawCircle(c, r * 0.88, aro);
        for (int i = 0; i < 24; i++) {
          final double a = i * math.pi / 12;
          final double d = i.isEven ? 0.99 : 0.94;
          canvas.drawLine(
            c + Offset(math.cos(a), math.sin(a)) * (r * 0.90),
            c + Offset(math.cos(a), math.sin(a)) * (r * d),
            Paint()
              ..color = paleta.tinta.withValues(alpha: 0.7)
              ..strokeWidth = r * 0.035
              ..strokeCap = StrokeCap.round,
          );
        }
      case MarcoSello.laurel:
        canvas.drawCircle(c, r * 0.88, aro);
        for (int i = 0; i < 18; i++) {
          final double a = math.pi * 0.35 + i * (math.pi * 2.3 / 18);
          final Offset base =
              c + Offset(math.cos(a), math.sin(a)) * (r * 0.94);
          canvas.save();
          canvas.translate(base.dx, base.dy);
          canvas.rotate(a);
          canvas.drawOval(
            Rect.fromCenter(
                center: Offset.zero, width: r * 0.16, height: r * 0.07),
            Paint()..color = paleta.tinta.withValues(alpha: 0.75),
          );
          canvas.restore();
        }
      case MarcoSello.sagrado:
        canvas.drawCircle(
          c,
          r * 0.99,
          Paint()
            ..shader = SweepGradient(
              colors: <Color>[
                paleta.tinta,
                ColoresTradicion.dorado,
                paleta.tinta,
                ColoresTradicion.dorado,
                paleta.tinta,
              ],
            ).createShader(Rect.fromCircle(center: c, radius: r))
            ..style = PaintingStyle.stroke
            ..strokeWidth = r * 0.055,
        );
        canvas.drawCircle(
          c,
          r * 1.06,
          Paint()
            ..color = ColoresTradicion.dorado.withValues(alpha: 0.22)
            ..style = PaintingStyle.stroke
            ..strokeWidth = r * 0.02,
        );
      default:
        _pintarAnimado(canvas, c, r, aro);
    }
  }

  void _pintarAnimado(Canvas canvas, Offset c, double r, Paint aro) {
    const double tau = math.pi * 2;
    Offset en(double a, double rr) => c + Offset(math.cos(a), math.sin(a)) * rr;
    Paint trazo(Color col, double w) => Paint()
      ..color = col
      ..style = PaintingStyle.stroke
      ..strokeWidth = w
      ..strokeCap = StrokeCap.round;
    switch (marco) {
      case MarcoSello.sakura:
        canvas.drawCircle(c, r * 0.90, aro);
        for (int i = 0; i < 7; i++) {
          final double a = t * tau + i * tau / 7;
          final Offset p = en(a, r * (0.93 + 0.03 * math.sin(t * tau * 2 + i)));
          canvas.save();
          canvas.translate(p.dx, p.dy);
          canvas.rotate(a + math.pi / 2 + math.sin(t * tau * 3 + i) * 0.4);
          canvas.drawOval(Rect.fromCenter(center: Offset.zero, width: r * 0.21, height: r * 0.126),
              Paint()..color = const Color(0xEBF6B8D8));
          canvas.drawOval(Rect.fromCenter(center: Offset(-r * 0.028, -r * 0.014), width: r * 0.07, height: r * 0.042),
              Paint()..color = const Color(0x80FFFFFF));
          canvas.restore();
        }
      case MarcoSello.llama:
        canvas.drawCircle(
            c,
            r * 0.92,
            trazo(const Color(0x73FF7A3A), r * 0.12)..maskFilter = MaskFilter.blur(BlurStyle.normal, r * 0.06));
        const int n = 16;
        for (int i = 0; i < n; i++) {
          final double a = i * tau / n + math.sin(t * tau + i) * 0.05;
          final double alto = r * (0.12 + 0.07 * (0.5 + 0.5 * math.sin(t * tau * 3 + i * 1.7)));
          final double base = r * 0.88, ancho = tau / n * 0.55;
          final Offset p0 = en(a - ancho, base), p1 = en(a + ancho, base);
          final Offset punta = en(a + 0.05, base + alto);
          final Offset c1 = en(a, base + alto * 0.6), c2 = en(a, base + alto * 0.4);
          canvas.drawPath(
            Path()
              ..moveTo(p0.dx, p0.dy)
              ..quadraticBezierTo(c1.dx, c1.dy, punta.dx, punta.dy)
              ..quadraticBezierTo(c2.dx, c2.dy, p1.dx, p1.dy)
              ..close(),
            Paint()
              ..shader = ui.Gradient.linear(
                  en(a, base), en(a, base + alto), <Color>[const Color(0xFFFFD36A), const Color(0x00FF5A2A)]),
          );
        }
        canvas.drawCircle(c, r * 0.88, trazo(const Color(0xFFFFB45A), r * 0.03));
      case MarcoSello.trueno:
        canvas.drawCircle(c, r * 0.90, trazo(const Color(0x998FB8FF), r * 0.03));
        canvas.drawCircle(
            c,
            r * 0.92,
            trazo(const Color(0x598FB8FF), r * 0.10)..maskFilter = MaskFilter.blur(BlurStyle.normal, r * 0.05));
        final double paso = (t * 18).floorToDouble();
        for (int k = 0; k < 3; k++) {
          if (_hashMarco(paso, k.toDouble()) < 0.35) continue;
          final double a0 = _hashMarco(k.toDouble(), paso) * tau;
          final double largo = 0.7 + _hashMarco(paso + 3, k.toDouble()) * 0.6;
          final Path rayo = Path();
          for (int s = 0; s <= 8; s++) {
            final Offset q = en(a0 + largo * s / 8, r * (0.94 + (_hashMarco(paso * 7 + s, k.toDouble()) - 0.5) * 0.12));
            if (s == 0) {
              rayo.moveTo(q.dx, q.dy);
            } else {
              rayo.lineTo(q.dx, q.dy);
            }
          }
          canvas.drawPath(rayo, trazo(const Color(0xF2E6F0FF), r * 0.022)..strokeJoin = StrokeJoin.round);
        }
      case MarcoSello.luna:
        canvas.drawCircle(c, r * 0.90, aro);
        for (int i = 0; i < 8; i++) {
          final double b = 0.5 + 0.5 * math.sin(t * tau * 2 + i * 1.3);
          canvas.drawCircle(en(i * tau / 8 + 0.2, r * 0.99), r * 0.018 + r * 0.012 * b,
              Paint()..color = Colors.white.withValues(alpha: 0.4 + 0.5 * b));
        }
        final Offset m = en(t * tau - math.pi / 2, r * 0.95);
        canvas.drawCircle(
            m,
            r * 0.2,
            Paint()
              ..color = const Color(0x59E8DCFF)
              ..maskFilter = MaskFilter.blur(BlurStyle.normal, r * 0.08));
        canvas.drawPath(
          Path.combine(
            PathOperation.difference,
            Path()..addOval(Rect.fromCircle(center: m, radius: r * 0.11)),
            Path()..addOval(Rect.fromCircle(center: m + Offset(r * 0.05, -r * 0.03), radius: r * 0.095)),
          ),
          Paint()..color = const Color(0xFFF2E9FF),
        );
      case MarcoSello.enso:
        // Un trazo de pincel que casi cierra, con un destello de tinta fresca.
        const double inicio = -math.pi * 0.42, fin = inicio + tau * 0.9;
        const int n = 60;
        for (int i = 0; i < n; i++) {
          final double u = i / n;
          final double a1 = inicio + (fin - inicio) * u, a2 = inicio + (fin - inicio) * (u + 1 / n);
          final double grosor = r * (0.05 + 0.06 * math.sin(math.pi * math.min(1.0, u * 1.4)) - 0.035 * u);
          final double rr = r * (0.92 + 0.015 * math.sin(u * 9));
          canvas.drawLine(en(a1, rr), en(a2, rr),
              trazo(paleta.tinta.withValues(alpha: 0.95 - 0.35 * u), math.max(grosor, r * 0.012)));
        }
        canvas.drawCircle(
            en(inicio + (fin - inicio) * t, r * 0.92),
            r * 0.06,
            Paint()
              ..color = Colors.white.withValues(alpha: 0.45 * math.sin(math.pi * t))
              ..maskFilter = MaskFilter.blur(BlurStyle.normal, r * 0.03));
      case MarcoSello.aurora:
        final Shader brillo = SweepGradient(
          colors: const <Color>[Color(0xFF5BD6A0), Color(0xFFB79CFF), Color(0xFF6FD3FF), Color(0xFF5BD6A0)],
          transform: GradientRotation(t * tau),
        ).createShader(Rect.fromCircle(center: c, radius: r));
        canvas.drawCircle(
            c,
            r * 0.93,
            trazo(Colors.white, r * 0.12)
              ..shader = brillo
              ..maskFilter = MaskFilter.blur(BlurStyle.normal, r * 0.05));
        canvas.drawCircle(c, r * 0.93, trazo(Colors.white, r * 0.04)..shader = brillo);
      case MarcoSello.dragon:
        canvas.drawCircle(c, r * 0.88, trazo(const Color(0x73E8B65A), r * 0.025));
        final double cabeza = t * tau;
        const int n = 44;
        for (int i = n - 1; i >= 0; i--) {
          final double a = cabeza - i * 0.11;
          final double rr = r * (0.95 + 0.03 * math.sin(i * 0.9 + t * tau * 2));
          final double rad = r * 0.075 * (1 - i / n * 0.7);
          canvas.drawCircle(en(a, rr), rad, Paint()..color = i.isOdd ? const Color(0xFF3FAE7E) : const Color(0xFF5BD6A0));
          if (i % 4 == 0) {
            canvas.drawCircle(en(a, rr - rad * 0.4), rad * 0.35, Paint()..color = const Color(0xFFE8B65A));
          }
        }
        final Offset h = en(cabeza, r * 0.95);
        canvas.save();
        canvas.translate(h.dx, h.dy);
        canvas.rotate(cabeza + math.pi / 2);
        canvas.drawOval(Rect.fromCenter(center: Offset(r * 0.04, 0), width: r * 0.2, height: r * 0.15),
            Paint()..color = const Color(0xFF7FE6B8));
        canvas.drawCircle(Offset(r * 0.07, -r * 0.03), r * 0.02, Paint()..color = const Color(0xFFFFE08A));
        canvas.drawPath(
            Path()
              ..moveTo(r * 0.12, r * 0.02)
              ..quadraticBezierTo(r * 0.2, r * 0.08, r * 0.17, r * 0.16),
            trazo(const Color(0xFFE8B65A), r * 0.015));
        canvas.restore();
      case MarcoSello.oro:
        canvas.drawCircle(
          c,
          r * 0.93,
          trazo(Colors.white, r * 0.075)
            ..shader = SweepGradient(
              colors: const <Color>[
                Color(0xFF8A6420),
                Color(0xFFFFF1B8),
                Color(0xFFD9A441),
                Color(0xFF8A6420),
                Color(0xFFE8B65A),
                Color(0xFF8A6420),
              ],
              stops: const <double>[0, 0.1, 0.2, 0.6, 0.75, 1],
              transform: GradientRotation(t * tau),
            ).createShader(Rect.fromCircle(center: c, radius: r)),
        );
        canvas.drawCircle(c, r * 1.03, trazo(const Color(0x4DE8B65A), r * 0.02));
        final double paso = (t * 10).floorToDouble();
        final double vida = (t * 10) % 1.0;
        for (int k = 0; k < 3; k++) {
          final Offset p = en(_hashMarco(paso, k.toDouble()) * tau, r * 0.93);
          final double s = r * 0.09 * math.sin(math.pi * vida);
          final Paint chispa = trazo(const Color(0xE6FFF6D6), r * 0.015);
          canvas.drawLine(p - Offset(s, 0), p + Offset(s, 0), chispa);
          canvas.drawLine(p - Offset(0, s), p + Offset(0, s), chispa);
        }
      case MarcoSello.kintsugi:
        // Cerámica oscura reparada con oro: las grietas brillan por turnos.
        canvas.drawCircle(c, r * 0.91, trazo(const Color(0xFF3A3150), r * 0.13));
        canvas.drawCircle(c, r * 0.95, trazo(Colors.white.withValues(alpha: 0.18), r * 0.015));
        canvas.drawCircle(c, r * 0.91,
            trazo(const Color(0x40E8B65A), r * 0.2)..maskFilter = MaskFilter.blur(BlurStyle.normal, r * 0.06));
        for (int k = 0; k < 7; k++) {
          final double a0 = k * tau / 7 + 0.3;
          final double b = 0.5 + 0.5 * math.sin(t * tau * 2 - k * 0.9);
          final Path grieta = Path();
          for (int s = 0; s <= 5; s++) {
            final Offset q = en(a0 + s * 0.13 + (_hashMarco(k.toDouble(), s.toDouble()) - 0.5) * 0.08,
                r * (0.85 + 0.12 * (s / 5) + (s.isOdd ? 0.025 : -0.025)));
            if (s == 0) {
              grieta.moveTo(q.dx, q.dy);
            } else {
              grieta.lineTo(q.dx, q.dy);
            }
          }
          canvas.drawPath(
              grieta,
              trazo(const Color(0xFFF2D493).withValues(alpha: 0.55 + 0.45 * b), r * 0.032)
                ..strokeJoin = StrokeJoin.round);
          canvas.drawCircle(
              en(a0, r * 0.86),
              r * 0.05,
              Paint()
                ..color = const Color(0xFFFFE7A8).withValues(alpha: 0.25 * b)
                ..maskFilter = MaskFilter.blur(BlurStyle.normal, r * 0.03));
        }
        canvas.drawCircle(
            en(t * tau, r * 0.91),
            r * 0.08,
            Paint()
              ..color = const Color(0x8CFFF4CC)
              ..maskFilter = MaskFilter.blur(BlurStyle.normal, r * 0.04));
      case MarcoSello.hoshi:
        // Una constelación que gira alrededor del sello.
        canvas.drawCircle(
          c,
          r * 0.9,
          trazo(Colors.white, r * 0.05)
            ..shader = SweepGradient(
              colors: const <Color>[Color(0x808B5CF6), Color(0x73E8B65A), Color(0x808B5CF6)],
              transform: GradientRotation(t * tau),
            ).createShader(Rect.fromCircle(center: c, radius: r)),
        );
        const int n = 10;
        final List<Offset> pts = <Offset>[
          for (int i = 0; i < n; i++)
            en(t * tau * 0.5 + i * tau / n + (_hashMarco(i.toDouble(), 3) - 0.5) * 0.25,
                r * (0.97 + (_hashMarco(3, i.toDouble()) - 0.5) * 0.08)),
        ];
        canvas.drawPath(Path()..addPolygon(pts, true), trazo(const Color(0x99D9CCFF), r * 0.016));
        for (int i = 0; i < n; i++) {
          final double b = 0.5 + 0.5 * math.sin(t * tau * 3 + i * 1.7);
          canvas.drawCircle(pts[i], r * (0.025 + 0.02 * b), Paint()..color = Colors.white.withValues(alpha: 0.6 + 0.4 * b));
          if (i % 3 == 0) {
            canvas.drawCircle(
                pts[i],
                r * 0.07,
                Paint()
                  ..color = const Color(0xFFF2D493).withValues(alpha: 0.3 * b)
                  ..maskFilter = MaskFilter.blur(BlurStyle.normal, r * 0.03));
          }
        }
      default:
        canvas.drawCircle(c, r * 0.90, aro);
    }
  }

  @override
  bool shouldRepaint(_SelloPainter old) =>
      old.paleta != paleta || old.marco != marco || old.t != t;
}

// ---------------------------------------------------------------------------
// 28.4 PANTALLA DE PERFIL
// ---------------------------------------------------------------------------

class PerfilScreen extends StatefulWidget {
  const PerfilScreen({super.key, required this.perfil});

  final PerfilUsuario perfil;

  @override
  State<PerfilScreen> createState() => _PerfilScreenState();
}

class _PerfilScreenState extends State<PerfilScreen> {
  bool _verTodosTitulos = false;

  String get _usuario => widget.perfil.nombre;

  void _refrescar() => setState(() {});

  @override
  void dispose() {
    // Lo que se editó aquí (nombre, biografía, sello) pasa al perfil público.
    SesionTemplo.instancia.sincronizarIdentidad(_usuario);
    super.dispose();
  }

  void _aviso(String txt) {
    ScaffoldMessenger.of(context)
      ..hideCurrentSnackBar()
      ..showSnackBar(
        SnackBar(
          behavior: SnackBarBehavior.floating,
          backgroundColor: TempleColors.superficieAlta,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(TempleRadius.campo),
            side: const BorderSide(color: TempleColors.borde),
          ),
          content: Text(txt,
              style: const TextStyle(
                  color: TempleColors.texto, fontSize: 13)),
        ),
      );
  }

  @override
  Widget build(BuildContext context) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final MotorProgresion m = MotorProgresion.instancia;
    final IdentidadUsuario id = AlmacenIdentidad.instancia.de(_usuario);
    final EstadoProgreso prog = m.de(_usuario);

    final NivelTemplo nivel = NivelTemplo.desdeXp(a.de(_usuario).xpGeneral);
    final Racha racha = m.racha(_usuario);
    final double peso = a.pesoDelTemplo(_usuario);
    final RangoPeso rango = RangosDelPeso.actual(peso);
    final RasgosEntrenamiento r = RasgosEntrenamiento.calcular(_usuario);
    final List<Sesion> sesiones = a.de(_usuario).completadas;
    final Titulo? equipado = prog.tituloEquipado == null
        ? null
        : TitulosDelTemplo.porId(prog.tituloEquipado!);
    final DefinicionClase? clase =
        prog.clase == null ? null : ClasesDelTemplo.todas[prog.clase!];

    final int minutos = sesiones.fold<int>(0, (int x, Sesion s) => x + s.minutos);

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: ListView(
          padding: EdgeInsets.zero,
          children: <Widget>[
            // -- Banner + sello ------------------------------------------
            Stack(
              clipBehavior: Clip.none,
              children: <Widget>[
                VinetaPerfil(config: prog.vineta, altura: 200),
                Positioned(
                  top: MediaQuery.paddingOf(context).top + 6,
                  left: 6,
                  child: IconButton(
                    onPressed: () => Navigator.of(context).maybePop(),
                    icon: const Icon(Icons.arrow_back_rounded,
                        color: TempleColors.blancoLuna),
                  ),
                ),
                Positioned(
                  top: MediaQuery.paddingOf(context).top + 6,
                  right: 6,
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: <Widget>[
                      const BotonPase(),
                      TextButton.icon(
                    onPressed: () =>       Navigator.of(context).push(
        MaterialPageRoute<void>(
          builder: (_) => TallerVinetaScreen(usuario: _usuario),
        ),
      ).then((_) => _refrescar()),
                    icon: const Icon(Icons.auto_fix_high_rounded,
                        size: 17, color: TempleColors.blancoLuna),
                    label: const Text('Viñeta',
                        style: TextStyle(
                            fontSize: 12.5,
                            color: TempleColors.blancoLuna)),
                  ),
                    ],
                  ),
                ),
                Positioned(
                  left: TempleSpace.borde,
                  bottom: -34,
                  child: GestureDetector(
                    // Foto de la galería, quitarla o editar el sello.
                    onTap: () => mostrarOpcionesClan(context, <OpcionHoja>[
                      OpcionHoja(Icons.photo_library_outlined, 'Elegir foto de mi galería', () async {
                        if (await elegirFotoPerfil(context) && mounted) _refrescar();
                      }),
                      if (id.foto != null)
                        OpcionHoja(Icons.hide_image_outlined, 'Quitar la foto (volver al sello)', () async {
                          await SesionTemplo.instancia.quitarFotoPerfil(_usuario);
                          if (mounted) _refrescar();
                        }),
                      OpcionHoja(Icons.brush_outlined, 'Editar mi sello', () async {
                        await _abrirEditorSello(context, _usuario, widget.perfil.espiritu, nivel.nivel);
                        if (mounted) _refrescar();
                      }),
                    ]),
                    child: Stack(
                      clipBehavior: Clip.none,
                      children: <Widget>[
                        Container(
                          padding: const EdgeInsets.all(3),
                          decoration: const BoxDecoration(
                            shape: BoxShape.circle,
                            color: TempleColors.negro,
                          ),
                          child: SelloUsuario(
                            identidad: id,
                            kanji: kanjiDeEspiritu(widget.perfil.espiritu),
                            nivel: nivel.nivel,
                            size: 92,
                          ),
                        ),
                        Positioned(
                          right: 2,
                          bottom: 2,
                          child: Container(
                            width: 28,
                            height: 28,
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
                              color: TempleColors.violeta,
                              border: Border.all(color: TempleColors.negro, width: 2),
                            ),
                            child: const Icon(Icons.photo_camera_outlined, size: 15, color: TempleColors.blancoLuna),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 46),

            // -- Identidad -----------------------------------------------
            Padding(
              padding:
                  const EdgeInsets.symmetric(horizontal: TempleSpace.borde),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Row(
                    children: <Widget>[
                      Expanded(
                        child: Row(
                          children: <Widget>[
                            Flexible(
                              child: Text(
                                id.nombreMostrado(_usuario),
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                  fontSize: 25,
                                  fontWeight: FontWeight.w600,
                                  color: TempleColors.blancoLuna,
                                ),
                              ),
                            ),
                            if (SesionTemplo.instancia.actual != null) ...<Widget>[
                              const SizedBox(width: 8),
                              BurbujaEdadGenero(
                                edad: SesionTemplo.instancia.actual!.edad,
                                genero: SesionTemplo.instancia.actual!.genero,
                              ),
                            ],
                            const SizedBox(width: 8),
                          ],
                        ),
                      ),
                      OutlinedButton(
                        onPressed: () async {
                          await _abrirEditorIdentidad(context, _usuario);
                          _refrescar();
                        },
                        style: OutlinedButton.styleFrom(
                          foregroundColor: TempleColors.violetaClaro,
                          side: const BorderSide(
                              color: TempleColors.bordeVivo),
