                  if (!(SesionTemplo.instancia.actual?.esMenor ?? false)) ...<Widget>[
                    const SizedBox(height: 14),
                    if (RedesSociales.visibles(id.redes).isNotEmpty)
                      FilaRedes(
                        redes: RedesSociales.visibles(id.redes),
