/// Los títulos bloqueados se ven, con su pista. Un logro secreto no motiva a
/// nadie a intentarlo.
class _ListaTitulos extends StatelessWidget {
  const _ListaTitulos({
    required this.usuario,
    required this.verTodos,
    required this.onAlternar,
    required this.onEquipar,
  });

  final String usuario;
  final bool verTodos;
  final VoidCallback onAlternar;
  final ValueChanged<String> onEquipar;

  @override
  Widget build(BuildContext context) {
    final MotorProgresion m = MotorProgresion.instancia;
    final EstadoProgreso e = m.de(usuario);
    final List<Titulo> ganados = m.titulosGanados(usuario);
    final List<Titulo> pendientes = m.titulosPendientes(usuario);
    final List<Titulo> mostrar = <Titulo>[
      ...ganados,
      if (verTodos) ...pendientes else ...pendientes.take(3),
    ];

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: <Widget>[
        TempleCard(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 6),
          child: Column(
            children: <Widget>[
              for (int i = 0; i < mostrar.length; i++) ...<Widget>[
                _FilaTitulo(
                  titulo: mostrar[i],
                  ganado: e.titulos.contains(mostrar[i].id),
                  equipado: e.tituloEquipado == mostrar[i].id,
                  onTap: () {
                    if (e.titulos.contains(mostrar[i].id)) {
                      onEquipar(mostrar[i].id);
                    }
                  },
                ),
                if (i != mostrar.length - 1)
                  Divider(
                      height: 1,
                      color: TempleColors.borde.withValues(alpha: 0.6)),
              ],
            ],
          ),
        ),
        const SizedBox(height: 10),
        Center(
          child: TextButton(
            onPressed: onAlternar,
            child: Text(
              verTodos
                  ? 'Ver menos'
                  : 'Ver los ${pendientes.length} pendientes',
              style: const TextStyle(
                  fontSize: 12.5, color: TempleColors.violetaClaro),
            ),
          ),
        ),
      ],
    );
  }
}

class _FilaTitulo extends StatelessWidget {
  const _FilaTitulo({
    required this.titulo,
    required this.ganado,
    required this.equipado,
    required this.onTap,
  });

  final Titulo titulo;
  final bool ganado;
  final bool equipado;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final Color c = !ganado
        ? TempleColors.textoTenue
        : titulo.raro
            ? TempleColors.dorado
            : TempleColors.violetaClaro;

    return InkWell(
      onTap: ganado ? onTap : null,
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 13),
        child: Row(
          children: <Widget>[
            Opacity(
              opacity: ganado ? 1 : 0.35,
              child: TempleIcon(
                ganado ? TempleGlyph.medalla : TempleGlyph.luna,
                size: 18,
                color: c,
              ),
            ),
            const SizedBox(width: 13),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Text(
                    titulo.texto,
                    style: TextStyle(
                      fontSize: 13.5,
                      fontWeight:
                          ganado ? FontWeight.w600 : FontWeight.w400,
                      color: ganado
                          ? TempleColors.texto
                          : TempleColors.textoTenue,
                    ),
                  ),
                  const SizedBox(height: 2),
                  Text(
                    titulo.pista,
                    style: const TextStyle(
                        fontSize: 11, color: TempleColors.textoTenue),
                  ),
                ],
              ),
            ),
            if (equipado)
              Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 9, vertical: 4),
                decoration: BoxDecoration(
                  color: c.withValues(alpha: 0.14),
                  borderRadius: BorderRadius.circular(999),
                ),
                child: Text('Equipado',
                    style: TextStyle(fontSize: 10, color: c)),
              )
            else if (ganado)
              const Icon(Icons.circle_outlined,
                  size: 15, color: TempleColors.textoTenue),
          ],
        ),
      ),
    );
  }
}

