Widget _asaHoja() => Center(
      child: Container(
        width: 40,
        height: 4,
        margin: const EdgeInsets.only(top: 12, bottom: 8),
        decoration: BoxDecoration(
          color: TempleColors.bordeVivo,
          borderRadius: BorderRadius.circular(2),
        ),
      ),
    );

Future<void> _abrirEditorIdentidad(BuildContext context, String usuario) {
  return showModalBottomSheet<void>(
    context: context,
    backgroundColor: TempleColors.grafito,
    isScrollControlled: true,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
    ),
    builder: (_) => _HojaIdentidad(usuario: usuario),
  );
}

class _HojaIdentidad extends StatefulWidget {
  const _HojaIdentidad({required this.usuario});
  final String usuario;

  @override
  State<_HojaIdentidad> createState() => _HojaIdentidadState();
}

class _HojaIdentidadState extends State<_HojaIdentidad> {
  late final IdentidadUsuario _id =
      AlmacenIdentidad.instancia.de(widget.usuario);
  late final TextEditingController _nombre =
      TextEditingController(text: _id.nombreVisible ?? '');
  late final TextEditingController _bio =
      TextEditingController(text: _id.biografia);

  @override
  void dispose() {
    _nombre.dispose();
    _bio.dispose();
    super.dispose();
  }

  void _alternarEtiqueta(String e) {
    setState(() {
      if (_id.etiquetas.contains(e)) {
        _id.etiquetas.remove(e);
      } else if (_id.etiquetas.length < EtiquetasTemplo.maximo) {
        _id.etiquetas.add(e);
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: EdgeInsets.only(
        bottom: MediaQuery.viewInsetsOf(context).bottom,
      ),
      child: SizedBox(
        height: MediaQuery.sizeOf(context).height * 0.85,
        child: Column(
          children: <Widget>[
            _asaHoja(),
            Expanded(
              child: ListView(
                padding: const EdgeInsets.fromLTRB(22, 12, 22, 24),
                children: <Widget>[
                  const Text(
                    'Editar perfil',
                    style: TextStyle(
                      fontSize: 21,
                      fontWeight: FontWeight.w600,
                      color: TempleColors.blancoLuna,
                    ),
                  ),
                  const SizedBox(height: 24),
                  const EtiquetaSeccion('Cómo te llamamos'),
                  TextField(
                    controller: _nombre,
                    maxLength: 24,
                    style: const TextStyle(
                        color: TempleColors.blancoLuna, fontSize: 15),
                    decoration: InputDecoration(
                      hintText: widget.usuario,
                      hintStyle:
                          const TextStyle(color: TempleColors.textoTenue),
                      counterStyle:
                          const TextStyle(color: TempleColors.textoTenue),
                      filled: true,
                      fillColor: TempleColors.superficie,
                      border: OutlineInputBorder(
                        borderRadius:
                            BorderRadius.circular(TempleRadius.campo),
                        borderSide: BorderSide.none,
                      ),
                    ),
                  ),
                  const Text(
                    'Tu @usuario no cambia: es tu llave en el templo y tu '
                    'referencia en el Clan.',
                    style: TextStyle(
                        fontSize: 11.5, color: TempleColors.textoTenue),
                  ),
                  const SizedBox(height: 22),
                  const EtiquetaSeccion('Una línea sobre ti'),
                  TextField(
                    controller: _bio,
                    maxLength: 90,
                    maxLines: 2,
                    style: const TextStyle(
                        color: TempleColors.blancoLuna, fontSize: 14),
                    decoration: InputDecoration(
                      hintText: 'Vengo a levantar el templo.',
                      hintStyle:
                          const TextStyle(color: TempleColors.textoTenue),
                      counterStyle:
                          const TextStyle(color: TempleColors.textoTenue),
                      filled: true,
                      fillColor: TempleColors.superficie,
                      border: OutlineInputBorder(
                        borderRadius:
                            BorderRadius.circular(TempleRadius.campo),
                        borderSide: BorderSide.none,
                      ),
                    ),
                  ),
                  const SizedBox(height: 14),
                  EtiquetaSeccion(
                    'Etiquetas · ${_id.etiquetas.length}/'
                    '${EtiquetasTemplo.maximo}',
                  ),
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children: EtiquetasTemplo.todas.map((String e) {
                      final bool ok = _id.etiquetas.contains(e);
                      return GestureDetector(
                        onTap: () => _alternarEtiqueta(e),
                        child: AnimatedContainer(
                          duration: TempleMotion.rapido,
                          padding: const EdgeInsets.symmetric(
                              horizontal: 13, vertical: 8),
                          decoration: BoxDecoration(
                            color: ok
                                ? TempleColors.violeta
                                    .withValues(alpha: 0.18)
                                : TempleColors.superficie,
                            borderRadius: BorderRadius.circular(999),
                            border: Border.all(
                              color: ok
                                  ? TempleColors.violeta
                                  : TempleColors.borde,
                            ),
                          ),
                          child: Text(
                            e,
                            style: TextStyle(
                              fontSize: 12.5,
                              color: ok
                                  ? TempleColors.violetaClaro
                                  : TempleColors.textoSuave,
                            ),
                          ),
                        ),
                      );
                    }).toList(),
                  ),
                  const SizedBox(height: 8),
                  const Text(
                    'Solo tres. Elegir es lo que hace que signifiquen algo.',
                    style: TextStyle(
                        fontSize: 11.5, color: TempleColors.textoTenue),
                  ),
                  if (!(SesionTemplo.instancia.actual?.esMenor ?? false)) ...<Widget>[
                    const SizedBox(height: 22),
                    const EtiquetaSeccion('Tus redes sociales'),
                    OutlinedButton.icon(
                      onPressed: () => abrirEditorRedes(context, widget.usuario),
                      icon: const Icon(Icons.link_rounded, size: 18),
                      label: Text(_id.redes.isEmpty
                          ? 'Añadir Instagram, Facebook, TikTok…'
                          : '${_id.redes.length} ${_id.redes.length == 1 ? 'enlace' : 'enlaces'} · editar'),
                      style: OutlinedButton.styleFrom(
                        foregroundColor: TempleColors.violetaClaro,
                        side: const BorderSide(color: TempleColors.bordeVivo),
                        padding: const EdgeInsets.symmetric(vertical: 13),
                      ),
                    ),
                  ],
                  const SizedBox(height: 28),
                  DojoPrimaryButton(
                    texto: 'Guardar',
                    onPressed: () {
                      _id.nombreVisible = _nombre.text.trim();
                      _id.biografia = _bio.text.trim();
                      Navigator.of(context).pop();
                    },
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

Future<void> _abrirEditorSello(
  BuildContext context,
  String usuario,
  String espiritu,
  int nivel,
) {
  return showModalBottomSheet<void>(
    context: context,
    backgroundColor: TempleColors.grafito,
    isScrollControlled: true,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
    ),
    builder: (_) =>
        _HojaSello(usuario: usuario, espiritu: espiritu, nivel: nivel),
  );
}

class _HojaSello extends StatefulWidget {
  const _HojaSello({
    required this.usuario,
    required this.espiritu,
    required this.nivel,
  });

  final String usuario;
  final String espiritu;
  final int nivel;

  @override
  State<_HojaSello> createState() => _HojaSelloState();
}

class _HojaSelloState extends State<_HojaSello> {
  late final IdentidadUsuario _id =
      AlmacenIdentidad.instancia.de(widget.usuario);

  PaletaSello get _paleta => PaletasSello.todas[_id.paleta % PaletasSello.todas.length];

  Future<void> _comprarMarco(MarcoSello m, String kanji) async {
    final MonedaTemplo mon = MonedaTemplo.instancia;
    final int saldo = mon.saldo(widget.usuario);
    if (saldo < m.precio) {
      avisoClan(context, 'Te faltan ${m.precio - saldo} mon. Entrena y vuelve.');
      return;
    }
    final bool? ok = await showDialog<bool>(
      context: context,
      builder: (BuildContext c) => AlertDialog(
        backgroundColor: TempleColors.superficieAlta,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(TempleRadius.tarjeta)),
        title: Text(m.etiqueta, style: const TextStyle(color: TempleColors.blancoLuna)),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            MarcoVivo(paleta: _paleta, marco: m, size: 96),
            const SizedBox(height: 14),
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: <Widget>[
                const IconoMon(size: 18),
                const SizedBox(width: 8),
                Text('${m.precio}',
                    style: const TextStyle(color: TempleColors.dorado, fontSize: 17, fontWeight: FontWeight.w700)),
                const SizedBox(width: 14),
                Text('Te quedan ${saldo - m.precio}',
                    style: const TextStyle(color: TempleColors.textoTenue, fontSize: 11.5)),
              ],
            ),
          ],
        ),
        actions: <Widget>[
          TextButton(onPressed: () => Navigator.of(c).pop(false), child: const Text('Ahora no')),
          TextButton(
            onPressed: () => Navigator.of(c).pop(true),
            child: const Text('Comprar', style: TextStyle(color: TempleColors.dorado, fontWeight: FontWeight.w600)),
          ),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    if (!mon.gastar(widget.usuario, m.precio, 'Marco: ${m.etiqueta}')) return;
    MotorProgresion.instancia.de(widget.usuario).piezas.add(m.clave);
    setState(() => _id.marco = m);
    NubeTemplo.instancia.marcarCambio();
    await mostrarCelebracion(
      context,
      titulo: 'Marco nuevo',
      nombre: m.etiqueta,
      color: m.rareza?.color ?? TempleColors.violetaClaro,
      vista: SelloUsuario(identidad: _id, kanji: kanji, nivel: widget.nivel, size: 120, animar: true),
      boton: 'Listo',
    );
  }

  /// El color del nombre en el Clan (del Pase).
  Widget _estiloNombre() {
    final EstiloNombre? actual = DatosEstiloNombre.desde(_id.estiloNombre);
    return TempleCard(
      padding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          const Text('Tu nombre en el Clan',
              style: TextStyle(fontSize: 14, fontWeight: FontWeight.w600, color: TempleColors.texto)),
          const SizedBox(height: 8),
          NombreConEstilo(_id.nombreMostrado(widget.usuario),
              estilo: LimitesPase.pase ? actual : null,
              insignia: LimitesPase.pase,
              style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w700, color: TempleColors.blancoLuna)),
          const SizedBox(height: 10),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: <Widget>[
              ChoiceChip(
                label: const Text('Normal', style: TextStyle(fontSize: 12)),
                selected: actual == null,
                onSelected: (_) => setState(() => _id.estiloNombre = null),
                showCheckmark: false,
                selectedColor: TempleColors.violeta.withValues(alpha: 0.3),
                backgroundColor: TempleColors.superficie,
                labelStyle: const TextStyle(color: TempleColors.texto),
              ),
              for (final EstiloNombre e in EstiloNombre.values)
                ChoiceChip(
                  avatar: Container(
                    width: 14,
                    height: 14,
                    decoration: BoxDecoration(shape: BoxShape.circle, gradient: LinearGradient(colors: e.colores)),
                  ),
                  label: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: <Widget>[
                      Text(e.etiqueta, style: const TextStyle(fontSize: 12)),
                      if (!LimitesPase.pase) ...<Widget>[
                        const SizedBox(width: 4),
                        const Icon(Icons.lock_outline_rounded, size: 11, color: Color(0xFFE8B65A)),
                      ],
                    ],
                  ),
                  selected: actual == e,
                  onSelected: (_) {
                    if (!LimitesPase.pase) {
                      mostrarMuroPase(
                        context,
                        titulo: 'Tu nombre con color',
                        texto: 'Con el Pase tu nombre luce un degradado en el Clan, junto al sello dorado 金.',
                        icono: Icons.palette_outlined,
                      );
                      return;
                    }
                    HapticFeedback.selectionClick();
                    setState(() => _id.estiloNombre = e.name);
                    NubeTemplo.instancia.marcarCambio();
                  },
                  showCheckmark: false,
                  selectedColor: const Color(0xFFE8B65A).withValues(alpha: 0.22),
                  backgroundColor: TempleColors.superficie,
                  labelStyle: const TextStyle(color: TempleColors.texto),
                ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _filaMarco(MarcoSello mm, String kanji) {
    final bool libre = MarcosTemplo.disponible(widget.usuario, mm, widget.nivel);
    final bool ok = _id.marco == mm;
    final bool comprable = !libre && mm.precio > 0;
    final Color acento = mm.rareza?.color ?? TempleColors.violetaClaro;
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: TempleCard(
        destacada: ok,
        onTap: libre
            ? () => setState(() => _id.marco = mm)
            : comprable
                ? () => _comprarMarco(mm, kanji)
                : mm.dePase
                    ? () => mostrarMuroPase(
                          context,
                          titulo: mm.etiqueta,
                          texto: 'Un marco animado que solo existe con el Pase del Templo. Se mueve en tu perfil y en el Clan.',
                          icono: Icons.auto_awesome_rounded,
                        )
                    : null,
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
        child: Row(
          children: <Widget>[
            Opacity(
              opacity: libre || comprable ? 1 : 0.4,
              child: SizedBox(
                width: 46,
                height: 46,
                child: mm.animado
                    ? MarcoVivo(paleta: _paleta, marco: mm, size: 46)
                    : CustomPaint(painter: _SelloPainter(paleta: _paleta, marco: mm)),
              ),
            ),
            const SizedBox(width: 14),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Row(
                    children: <Widget>[
                      Flexible(
                        child: Text(
                          mm.etiqueta,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                            fontSize: 14,
                            fontWeight: FontWeight.w600,
                            color: libre ? TempleColors.texto : TempleColors.textoSuave,
                          ),
                        ),
                      ),
                      if (mm.rareza != null) ...<Widget>[
                        const SizedBox(width: 8),
                        Container(
                          padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 2),
                          decoration: BoxDecoration(
                            color: acento.withValues(alpha: 0.14),
                            borderRadius: BorderRadius.circular(999),
                          ),
                          child: Text(mm.rareza!.etiqueta, style: TextStyle(fontSize: 9.5, color: acento)),
                        ),
                      ],
                    ],
                  ),
                  if (!libre) ...<Widget>[
                    const SizedBox(height: 3),
                    Text(mm.pista,
                        style: TextStyle(
                            fontSize: 11.5, color: comprable ? TempleColors.textoTenue : TempleColors.alertaSuave)),
                  ],
                ],
              ),
            ),
            if (ok)
              const Icon(Icons.check_circle_rounded, size: 19, color: TempleColors.exito)
            else if (comprable)
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 11, vertical: 7),
                decoration: BoxDecoration(
                  color: TempleColors.dorado.withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(999),
                  border: Border.all(color: TempleColors.dorado.withValues(alpha: 0.35)),
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: <Widget>[
                    const IconoMon(size: 14),
                    const SizedBox(width: 6),
                    Text('${mm.precio}',
                        style: const TextStyle(fontSize: 12.5, fontWeight: FontWeight.w700, color: TempleColors.dorado)),
                  ],
                ),
              )
            else if (!libre)
              const Icon(Icons.lock_outline_rounded, size: 17, color: TempleColors.textoTenue),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final String kanji = kanjiDeEspiritu(widget.espiritu);

    return SizedBox(
      height: MediaQuery.sizeOf(context).height * 0.85,
      child: Column(
        children: <Widget>[
          _asaHoja(),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.fromLTRB(22, 12, 22, 24),
              children: <Widget>[
                const Text(
                  'Tu sello',
                  style: TextStyle(
                    fontSize: 21,
                    fontWeight: FontWeight.w600,
                    color: TempleColors.blancoLuna,
                  ),
                ),
                const SizedBox(height: 6),
                const Text(
                  'Paleta, símbolo y marco. Si pones foto, el marco la rodea.',
                  style: TextStyle(
                      fontSize: 12.5, color: TempleColors.textoSuave),
                ),
                const SizedBox(height: 24),
                Center(
                  child: SelloUsuario(
                    identidad: _id,
                    kanji: kanji,
                    nivel: widget.nivel,
                    size: 128,
                    animar: true,
                  ),
                ),
                const SizedBox(height: 30),
                const EtiquetaSeccion('Paleta'),
                Wrap(
                  spacing: 12,
                  runSpacing: 12,
                  children: List<Widget>.generate(
                    PaletasSello.todas.length,
                    (int i) {
                      final PaletaSello p = PaletasSello.todas[i];
                      final bool ok = _id.paleta == i;
                      return GestureDetector(
                        onTap: () => setState(() => _id.paleta = i),
                        child: Column(
                          children: <Widget>[
                            AnimatedContainer(
                              duration: TempleMotion.rapido,
                              width: 46,
                              height: 46,
                              decoration: BoxDecoration(
                                shape: BoxShape.circle,
                                gradient: LinearGradient(
                                  begin: Alignment.topLeft,
                                  end: Alignment.bottomRight,
                                  colors: <Color>[p.fondoA, p.fondoB],
                                ),
                                border: Border.all(
                                  color: ok
                                      ? p.tinta
                                      : TempleColors.borde,
                                  width: ok ? 2 : 1,
                                ),
                              ),
                            ),
                            const SizedBox(height: 5),
                            Text(p.nombre,
                                style: const TextStyle(
                                    fontSize: 10,
                                    color: TempleColors.textoTenue)),
                          ],
                        ),
                      );
                    },
                  ),
                ),
                const SizedBox(height: 26),
                const EtiquetaSeccion('Símbolo'),
                Wrap(
                  spacing: 10,
                  runSpacing: 10,
                  children: SimboloSello.values.map((SimboloSello s) {
                    final bool ok = _id.simbolo == s;
                    return GestureDetector(
                      onTap: () => setState(() => _id.simbolo = s),
                      child: AnimatedContainer(
                        duration: TempleMotion.rapido,
                        width: 54,
                        height: 54,
                        decoration: BoxDecoration(
                          color: ok
                              ? TempleColors.violeta.withValues(alpha: 0.16)
                              : TempleColors.superficie,
                          borderRadius:
                              BorderRadius.circular(TempleRadius.chip),
                          border: Border.all(
                            color: ok
                                ? TempleColors.violeta
                                : TempleColors.borde,
                          ),
                        ),
                        child: Center(
                          child: s.glifo == null
                              ? Text(
                                  kanji,
                                  style: TextStyle(
                                    fontSize: 22,
                                    color: ok
                                        ? TempleColors.violetaClaro
                                        : TempleColors.textoSuave,
                                  ),
                                )
                              : TempleIcon(
                                  s.glifo!,
                                  size: 24,
                                  color: ok
                                      ? TempleColors.violetaClaro
                                      : TempleColors.textoSuave,
                                ),
                        ),
                      ),
                    );
                  }).toList(),
                ),
                const SizedBox(height: 26),
                const EtiquetaSeccion('Marcos por nivel'),
                for (final MarcoSello mm in MarcoSello.values.where((MarcoSello m) => !m.animado))
                  _filaMarco(mm, kanji),
                const SizedBox(height: 16),
                const EtiquetaSeccion('Marcos animados'),
                const Padding(
                  padding: EdgeInsets.only(bottom: 10),
                  child: Text('Se mueven en tu perfil. Unos se compran con mon y otros se ganan con hazañas.',
                      style: TextStyle(fontSize: 12, color: TempleColors.textoTenue)),
                ),
                for (final MarcoSello mm in MarcoSello.values.where((MarcoSello m) => m.animado && !m.dePase))
                  _filaMarco(mm, kanji),
                const SizedBox(height: 16),
                const EtiquetaSeccion('Del Pase del Templo', accion: ChipPase()),
                for (final MarcoSello mm in MarcoSello.values.where((MarcoSello m) => m.dePase))
                  _filaMarco(mm, kanji),
                const SizedBox(height: 6),
                _estiloNombre(),
                const SizedBox(height: 20),
                DojoPrimaryButton(
                  texto: 'Listo',
                  onPressed: () => Navigator.of(context).pop(),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

Future<void> _abrirSelectorTitulo(BuildContext context, String usuario) {
  return showModalBottomSheet<void>(
    context: context,
    backgroundColor: TempleColors.grafito,
    isScrollControlled: true,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
    ),
    builder: (BuildContext c) {
      final MotorProgresion m = MotorProgresion.instancia;
      final List<Titulo> ganados = m.titulosGanados(usuario);

      return SizedBox(
        height: MediaQuery.sizeOf(c).height * 0.6,
        child: Column(
          children: <Widget>[
            _asaHoja(),
            const Padding(
              padding: EdgeInsets.fromLTRB(22, 10, 22, 4),
              child: Align(
                alignment: Alignment.centerLeft,
                child: Text(
                  'Elige tu título',
                  style: TextStyle(
                    fontSize: 20,
                    fontWeight: FontWeight.w600,
                    color: TempleColors.blancoLuna,
                  ),
                ),
              ),
            ),
            const Padding(
              padding: EdgeInsets.fromLTRB(22, 0, 22, 12),
              child: Align(
                alignment: Alignment.centerLeft,
                child: Text(
                  'Cuál enseñas dice tanto como haberlo conseguido.',
                  style: TextStyle(
                      fontSize: 12.5, color: TempleColors.textoSuave),
                ),
              ),
            ),
            Expanded(
              child: ListView(
                padding: const EdgeInsets.fromLTRB(22, 0, 22, 24),
                children: <Widget>[
                  for (final Titulo t in ganados)
                    ListTile(
                      onTap: () {
                        m.equiparTitulo(usuario, t.id);
                        Navigator.of(c).pop();
                      },
                      leading: TempleIcon(
                        TempleGlyph.medalla,
                        size: 20,
                        color: t.raro
                            ? TempleColors.dorado
                            : TempleColors.violetaClaro,
                      ),
                      title: Text('«${t.texto}»',
                          style: const TextStyle(
                              color: TempleColors.texto, fontSize: 14)),
                      trailing:
                          m.de(usuario).tituloEquipado == t.id
                              ? const Icon(Icons.check_rounded,
                                  color: TempleColors.exito, size: 18)
                              : null,
                    ),
                  if (ganados.isEmpty)
                    const Padding(
                      padding: EdgeInsets.symmetric(vertical: 30),
                      child: Text(
                        'Aún no tienes títulos. El primero llega con tu '
                        'primera sesión.',
                        textAlign: TextAlign.center,
                        style: TextStyle(
                            fontSize: 13, color: TempleColors.textoSuave),
                      ),
                    ),
                ],
              ),
            ),
          ],
        ),
      );
    },
  );
}
