// ---------------------------------------------------------------------------
// 29.1 EL MON
//
// El mon (文) era la moneda japonesa con un agujero cuadrado en el centro:
// se enhebraban en un cordel para llevarlas. Es la moneda del templo, y se
// dibuja en vector como todo lo demás.
//
// Los importes de abajo son un borrador: la economía se afina cuando haya
// gente jugando, no antes.
// ---------------------------------------------------------------------------

class MovimientoMon {
  const MovimientoMon({
    required this.fecha,
    required this.cantidad,
    required this.motivo,
  });

  final DateTime fecha;

  /// Positivo al ganar, negativo al gastar.
  final int cantidad;
  final String motivo;

  bool get esIngreso => cantidad > 0;

  Map<String, dynamic> toMap() => <String, dynamic>{
        'fecha': fecha.toIso8601String(),
        'cantidad': cantidad,
        'motivo': motivo,
      };
}

class MonedaTemplo {
  MonedaTemplo._();
  static final MonedaTemplo instancia = MonedaTemplo._();

  // -- Recompensa diaria --------------------------------------------------
  // Solo la primera sesión completada de cada día paga, y paga entre 15 y 35
  // mon según lo que se logró en ella. Entrenar dos veces el mismo día no
  // da más: el mon premia la constancia, no el volumen.
  static const int minimoDiario = 15;
  static const int maximoDiario = 35;
  static const int porRecord = 10;
  static const int porNivel = 10;
  static const int porSemanaCumplida = 10;
  static const int porMision = 5;

  /// Último día (aaaa-mm-dd) en que cada usuario cobró su recompensa.
  final Map<String, String> _ultimoCobro = <String, String>{};

  static String _clave(DateTime d) =>
      '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';

  bool cobradoHoy(String usuario) => _ultimoCobro[usuario] == _clave(DateTime.now());

  final Map<String, int> _saldos = <String, int>{};
  final Map<String, List<MovimientoMon>> _historial =
      <String, List<MovimientoMon>>{};

  int saldo(String usuario) => _saldos[usuario] ?? 0;

  List<MovimientoMon> historial(String usuario) =>
      List<MovimientoMon>.unmodifiable(
          (_historial[usuario] ?? <MovimientoMon>[]).reversed);

  void ganar(String usuario, int cantidad, String motivo) {
    if (cantidad <= 0) return;
    _saldos[usuario] = saldo(usuario) + cantidad;
    _historial
        .putIfAbsent(usuario, () => <MovimientoMon>[])
        .add(MovimientoMon(
          fecha: DateTime.now(),
          cantidad: cantidad,
          motivo: motivo,
        ));
  }

  bool gastar(String usuario, int cantidad, String motivo) {
    if (saldo(usuario) < cantidad) return false;
    _saldos[usuario] = saldo(usuario) - cantidad;
    _historial
        .putIfAbsent(usuario, () => <MovimientoMon>[])
        .add(MovimientoMon(
          fecha: DateTime.now(),
          cantidad: -cantidad,
          motivo: motivo,
        ));
    return true;
  }

  /// Reparto tras cerrar una sesión. Se llama desde el resumen.
  /// Devuelve 0 si hoy ya se cobró.
  int recompensarSesion(
    String usuario,
    ResumenCierre resumen,
    NovedadesProgreso novedades,
  ) {
    if (cobradoHoy(usuario)) return 0;

    int total = minimoDiario;
    final List<String> motivos = <String>['Sesión del día'];

    if (resumen.records.isNotEmpty) {
      total += porRecord * resumen.records.length;
      motivos.add('${resumen.records.length} récord(s)');
    }
    if (resumen.subioNivel) {
      total += porNivel;
      motivos.add('Nivel ${resumen.nivelDespues.nivel}');
    }
    if (novedades.rachaSubio) {
      total += porSemanaCumplida;
      motivos.add('Semana cumplida');
    }
    if (novedades.misiones.isNotEmpty) {
      total += porMision * novedades.misiones.length;
      motivos.add(novedades.misiones.length == 1
          ? novedades.misiones.first.titulo
          : '${novedades.misiones.length} misiones');
    }

    total = total.clamp(minimoDiario, maximoDiario);
    ganar(usuario, total, motivos.join(' · '));
    _ultimoCobro[usuario] = _clave(DateTime.now());
    return total;
  }
}

/// La moneda dibujada: círculo con agujero cuadrado, como el mon real.
class IconoMon extends StatelessWidget {
  const IconoMon({super.key, this.size = 18, this.color});

  final double size;
  final Color? color;

  @override
  Widget build(BuildContext context) => SizedBox(
        width: size,
        height: size,
        child: CustomPaint(
          painter: _MonPainter(color ?? TempleColors.dorado),
        ),
      );
}

class _MonPainter extends CustomPainter {
  const _MonPainter(this.color);
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    final Offset c = size.center(Offset.zero);
    final double r = size.shortestSide / 2;

    canvas.drawCircle(
      c,
      r * 0.94,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: <Color>[
            Color.lerp(color, Colors.white, 0.35)!,
            color,
            Color.lerp(color, Colors.black, 0.28)!,
          ],
        ).createShader(Rect.fromCircle(center: c, radius: r)),
    );

    canvas.drawCircle(
      c,
      r * 0.94,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = r * 0.10
        ..color = Color.lerp(color, Colors.black, 0.35)!,
    );

    // Agujero cuadrado.
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        Rect.fromCenter(center: c, width: r * 0.62, height: r * 0.62),
        Radius.circular(r * 0.06),
      ),
      Paint()..color = ColoresTradicion.negro,
    );
  }

  @override
  bool shouldRepaint(_MonPainter old) => old.color != color;
}

/// Contador de saldo reutilizable.
class SaldoMon extends StatelessWidget {
  const SaldoMon({super.key, required this.usuario, this.compacto = false});

  final String usuario;
  final bool compacto;

  @override
  Widget build(BuildContext context) {
    final int s = MonedaTemplo.instancia.saldo(usuario);
    return Container(
      padding: EdgeInsets.symmetric(
          horizontal: compacto ? 10 : 13, vertical: compacto ? 6 : 8),
      decoration: BoxDecoration(
        color: TempleColors.dorado.withValues(alpha: 0.10),
        borderRadius: BorderRadius.circular(999),
        border:
            Border.all(color: TempleColors.dorado.withValues(alpha: 0.30)),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: <Widget>[
          IconoMon(size: compacto ? 15 : 18),
          const SizedBox(width: 8),
          Text(
            '$s',
            style: TextStyle(
              fontSize: compacto ? 12.5 : 14,
              fontWeight: FontWeight.w700,
              color: TempleColors.dorado,
              fontFeatures: const <FontFeature>[FontFeature.tabularFigures()],
            ),
          ),
        ],
      ),
    );
  }
}

// ---------------------------------------------------------------------------
// 29.2 CATÁLOGO DE LA TIENDA
//
// Las piezas de la sección 27 se GANAN por hazañas y no se pueden comprar:
// esas son el currículum. Estas otras son puramente estéticas y se compran
// con mon. La frontera importa: si lo que cuenta una historia se pudiera
// comprar, dejaría de contar nada.
// ---------------------------------------------------------------------------

enum RarezaPieza { comun, rara, epica, legendaria }

extension DatosRareza on RarezaPieza {
  String get etiqueta {
    switch (this) {
      case RarezaPieza.comun:
        return 'Común';
      case RarezaPieza.rara:
        return 'Rara';
      case RarezaPieza.epica:
        return 'Épica';
      case RarezaPieza.legendaria:
        return 'Legendaria';
    }
  }

  /// Precios en borrador.
  int get precio {
    switch (this) {
      case RarezaPieza.comun:
        return 150;
      case RarezaPieza.rara:
        return 400;
      case RarezaPieza.epica:
        return 900;
      case RarezaPieza.legendaria:
        return 2000;
    }
  }

  Color get color {
    switch (this) {
      case RarezaPieza.comun:
        return TempleColors.textoSuave;
      case RarezaPieza.rara:
        return TempleColors.violetaClaro;
      case RarezaPieza.epica:
        return TempleColors.exito;
      case RarezaPieza.legendaria:
        return TempleColors.dorado;
    }
  }
}

