    PiezaTienda(
      id: 'cli_brasas',
      capa: CapaVineta.clima,
      nombre: 'Brasas',
      descripcion: 'Chispas que suben del suelo como un fuego que no se apaga.',
      rareza: RarezaPieza.epica,
    ),
  ];

  static List<PiezaTienda> deCapa(CapaVineta c) =>
      todas.where((PiezaTienda p) => p.capa == c).toList();

  static PiezaTienda? porId(String id) {
    for (final PiezaTienda p in todas) {
      if (p.id == id) return p;
    }
    return null;
  }
}

/// Vista unificada de una pieza, venga de logro o de tienda.
class PiezaUnificada {
  const PiezaUnificada({
    required this.id,
    required this.capa,
    required this.nombre,
    required this.detalle,
    required this.deTienda,
    required this.precio,
    required this.rareza,
  });

  final String id;
  final CapaVineta capa;
  final String nombre;

  /// Cómo se gana (logro) o su descripción (tienda).
  final String detalle;
  final bool deTienda;
  final int precio;
  final RarezaPieza? rareza;

  static List<PiezaUnificada> deCapa(CapaVineta c) => <PiezaUnificada>[
        for (final PiezaVineta p in PiezasVineta.deCapa(c))
          PiezaUnificada(
            id: p.id,
            capa: c,
            nombre: p.nombre,
            detalle: p.comoSeGana,
            deTienda: false,
            precio: 0,
            rareza: p.rara ? RarezaPieza.legendaria : null,
          ),
        for (final PiezaTienda p in TiendaVineta.deCapa(c))
          PiezaUnificada(
            id: p.id,
            capa: c,
            nombre: p.nombre,
            detalle: p.descripcion,
            deTienda: true,
            precio: p.precio,
            rareza: p.rareza,
          ),
      ];
}

// ---------------------------------------------------------------------------
// 29.3 EL LIENZO
//
// Sustituye a VinetaPerfil de la sección 28.3, con la misma API. Dibuja las
// 88 piezas: 38 de logro, 46 de tienda y 4 de la temporada del Pase. Todas
// se mueven con un reloj continuo, sin saltos. Las piezas originales se
// redibujaron con luz de borde, profundidad y animación propia.
// ---------------------------------------------------------------------------

class VinetaPerfil extends StatefulWidget {
  const VinetaPerfil({
    super.key,
    required this.config,
    this.altura = 190,
    this.animada = true,
  });

  final Map<CapaVineta, String> config;
  final double altura;
  final bool animada;

  @override
  State<VinetaPerfil> createState() => _VinetaPerfilState();
}

class _VinetaPerfilState extends State<VinetaPerfil>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;

  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 34),
  )..addListener(_avanzar);

  /// Reloj continuo: cuenta las vueltas para que el tiempo nunca regrese a
  /// cero. Antes, cada 34 s los pétalos, la nieve o el humo saltaban de sitio.
  final ValueNotifier<double> _reloj = ValueNotifier<double>(0.25);
  int _vueltas = 0;
  double _ultimo = 0;

  void _avanzar() {
    if (_c.value < _ultimo) _vueltas++;
    _ultimo = _c.value;
    _reloj.value = 0.25 + _vueltas + _c.value;
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final bool reducir = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    if (!widget.animada || reducir) {
      _c.stop();
      _reloj.value = 0.25;
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    _reloj.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => SizedBox(
        height: widget.altura,
        child: RepaintBoundary(
          child: CustomPaint(
            painter: _LienzoPainter(reloj: _reloj, config: widget.config),
            size: Size.infinite,
          ),
        ),
      );
}

/// Cómo se pinta cada cielo original: degradado, resplandor del horizonte
/// y cuántas estrellas lleva.
class _DefCielo {
  const _DefCielo(this.cols, this.hz, this.hzA, this.estrellas);
  final List<Color> cols;
  final Color hz;
  final double hzA;
  final int estrellas;
}

const Map<String, _DefCielo> _cielosViejos = <String, _DefCielo>{
  'cielo_noche': _DefCielo(<Color>[Color(0xFF160C2E), Color(0xFF241442), Color(0xFF1B1036), Color(0xFF0B0718)],
      Color(0xFF6A4BC4), 0.20, 34),
  'cielo_alba': _DefCielo(<Color>[Color(0xFF1E1640), Color(0xFF4A2F66), Color(0xFFB76A73), Color(0xFFF0A77A)],
      Color(0xFFFFC48A), 0.40, 10),
  'cielo_ocaso': _DefCielo(<Color>[Color(0xFF140C30), Color(0xFF43215A), Color(0xFF9C3F5A), Color(0xFFE0754E)],
      Color(0xFFFF8A5A), 0.36, 14),
  'cielo_estrellado': _DefCielo(<Color>[Color(0xFF060918), Color(0xFF0E1434), Color(0xFF1A1844), Color(0xFF0B0A1C)],
      Color(0xFF6E7BFF), 0.14, 120),
  'cielo_aurora': _DefCielo(<Color>[Color(0xFF040A16), Color(0xFF0A1A2C), Color(0xFF0E2A33), Color(0xFF081422)],
      Color(0xFF3FE0A8), 0.14, 60),
  'cielo_tinta': _DefCielo(<Color>[Color(0xFF3C3C42), Color(0xFF29292E), Color(0xFF18181B), Color(0xFF0D0D0F)],
      Color(0xFFFFFFFF), 0.06, 0),
  'cielo_sangre': _DefCielo(<Color>[Color(0xFF22060E), Color(0xFF5E1222), Color(0xFFA3263A), Color(0xFF3A0B14)],
      Color(0xFFFF5A4A), 0.26, 0),
  'cielo_cosmos': _DefCielo(<Color>[Color(0xFF0B0520), Color(0xFF1E0D44), Color(0xFF2E1258), Color(0xFF07030F)],
      Color(0xFFB79CFF), 0.16, 150),
  'cielo_oro': _DefCielo(<Color>[Color(0xFF2A1A14), Color(0xFF6E4520), Color(0xFFC88A35), Color(0xFFF2CB7A)],
      Color(0xFFFFE0A0), 0.42, 0),
};

/// Luz, sombra del borde, halo y fuerza del halo de cada luna original.
class _DefLuna {
  const _DefLuna(this.luz, this.sombra, this.halo, this.a);
  final Color luz;
  final Color sombra;
  final Color halo;
  final double a;
}

const Map<String, _DefLuna> _lunasViejas = <String, _DefLuna>{
  'luna_llena': _DefLuna(Color(0xFFF4EEFF), Color(0xFFBDB0E6), Color(0xFFE8DCFF), 0.26),
  'luna_creciente': _DefLuna(Color(0xFFF0E6FF), Color(0xFFB9A8E8), Color(0xFFE8DCFF), 0.20),
  'luna_roja': _DefLuna(Color(0xFFFFB09A), Color(0xFFB8343A), Color(0xFFE86A5C), 0.30),
  'luna_eclipse': _DefLuna(Color(0xFF1A1226), Color(0xFF0C0814), Color(0xFFF2D493), 0.12),
  'luna_velada': _DefLuna(Color(0xFFF0EAFF), Color(0xFFB4A8DC), Color(0xFFE8DCFF), 0.16),
  'luna_gemela': _DefLuna(Color(0xFFF2ECFF), Color(0xFFB9AEE0), Color(0xFFE8DCFF), 0.22),
  'luna_dorada': _DefLuna(Color(0xFFFFF0BE), Color(0xFFD49A36), Color(0xFFF2D493), 0.34),
  'luna_kanji': _DefLuna(Color(0xFFF2ECFF), Color(0xFFBCAFE4), Color(0xFFE8DCFF), 0.24),
};

class _LienzoPainter extends CustomPainter {
  _LienzoPainter({required this.reloj, required this.config}) : super(repaint: reloj);

  final ValueNotifier<double> reloj;
  final Map<CapaVineta, String> config;

  double get t => reloj.value;

  String _id(CapaVineta c, String d) => config[c] ?? d;

  @override
  void paint(Canvas canvas, Size size) {
    final double w = size.width;
    final double h = size.height;
    final double hz = h * 0.70;

    _cielo(canvas, w, h);
    _luna(canvas, w, h);
    _montanas(canvas, w, h, hz);
    _agua(canvas, w, h, hz);
    _vegetacion(canvas, w, h, hz);
    _estructura(canvas, w, h, hz);
    _criatura(canvas, w, h, hz);
    _clima(canvas, w, h, hz);

    canvas.drawRect(
      Offset.zero & size,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.center,
          end: Alignment.bottomCenter,
          colors: <Color>[
            Colors.transparent,
            ColoresTradicion.negro.withValues(alpha: 0.60),
          ],
        ).createShader(Offset.zero & size),
    );
  }

  // ===== PIEZAS ORIGINALES, REDIBUJADAS ==================================
  //
  // Mismo dibujo que el prototipo (viejas.js). Las posiciones salen de
  // _hash(): ni una partícula salta al recargar la escena.

  static double _h(num a, num b) => _hash(a.toDouble(), b.toDouble());

  static Color _al(Color col, double a) => col.withValues(alpha: a.clamp(0.0, 1.0));

  /// Degradado lineal. dart:ui lanza un error si hay más de dos colores sin
  /// paradas, y ese error dejaba sin pintar todas las capas que venían
  /// después (vegetación, estructura, criatura y clima). Aquí las paradas
  /// se reparten solas.
  static Shader _lin(Offset a, Offset b, List<Color> cols, [List<double>? stops]) {
    final List<double>? paradas = stops ??
        (cols.length == 2 ? null : List<double>.generate(cols.length, (int i) => i / (cols.length - 1)));
    return ui.Gradient.linear(a, b, cols, paradas);
  }

  void _glowE(Canvas c, Offset p, double rx, double ry, Color col, double a) {
    if (rx <= 0 || ry <= 0 || a <= 0) return;
    c.save();
    c.translate(p.dx, p.dy);
    c.scale(1, ry / rx);
    _glow(c, Offset.zero, rx, col, a);
    c.restore();
  }

  void _linea(Canvas c, Offset a, Offset b, double ancho, Color col) => c.drawLine(a, b, _raya(col, ancho));

  void _destello(Canvas c, Offset p, double s, Color col, double ancho) {
    _linea(c, p.translate(-s, 0), p.translate(s, 0), ancho, col);
    _linea(c, p.translate(0, -s), p.translate(0, s), ancho, col);
  }

  void _ovalo(Canvas c, Offset p, double rx, double ry, Color col, [double giro = 0]) =>
      _elipse(c, p, math.max(rx, 0.01), math.max(ry, 0.01), giro, Paint()..color = col);

  /// Nube de anime: base plana y lomos redondos; degradado vertical.
  void _nube(Canvas c, Offset p, double s, Color arriba, Color abajo, double a) {
    const List<List<double>> lomos = <List<double>>[
      <double>[-0.62, 0.34],
      <double>[-0.28, 0.5],
      <double>[0.12, 0.62],
      <double>[0.5, 0.42],
      <double>[0.8, 0.26],
    ];
    final Path n = Path()..moveTo(p.dx - s, p.dy);
    for (final List<double> l in lomos) {
      n.arcTo(Rect.fromCircle(center: Offset(p.dx + l[0] * s, p.dy - l[1] * s * 0.35), radius: l[1] * s * 0.55),
          math.pi, math.pi, false);
    }
    n
      ..lineTo(p.dx + s, p.dy)
      ..close();
    c.drawPath(
        n,
        Paint()
          ..shader = _lin(Offset(0, p.dy - s * 0.6), Offset(0, p.dy), <Color>[_al(arriba, a), _al(abajo, a)]));
    _glowE(c, p, s * 1.1, s * 0.14, abajo, a * 0.35);
  }

  // ---- CIELO ------------------------------------------------------------

  void _estrellasV(Canvas c, double w, double h, int n, int semilla) {
    for (int i = 0; i < n; i++) {
      final Offset p = Offset(_h(i, semilla) * w, math.pow(_h(semilla, i), 1.5).toDouble() * h * 0.64);
      final double tam = 0.35 + 1.05 * _h(i + 7, semilla);
      final double brillo = 0.5 + 0.5 * math.sin(t * _tau * (2 + i % 3) + i * 1.7);
      _punto(c, p, tam, _al(Colors.white, (0.35 + 0.55 * brillo) * (0.5 + 0.5 * _h(i, 3))));
      if (_h(i + 3, semilla) > 0.94) {
        _glow(c, p, tam * 5, const Color(0xFFCFC4FF), 0.35 * brillo);
        _destello(c, p, tam * 3.2 * (0.6 + 0.4 * brillo), _al(Colors.white, 0.7 * brillo), 0.6);
      }
    }
  }

  /// Cielos de la tanda nueva: se quedan como estaban.
  void _cieloNuevo(Canvas c, double w, double h, String id) {
    final Rect r = Rect.fromLTWH(0, 0, w, h);
    final List<Color> cols = id == 'cielo_fugaces'
        ? const <Color>[Color(0xFF0E0B2A), Color(0xFF1D1450), Color(0xFF0A0618)]
        : const <Color>[Color(0xFF160C2C), Color(0xFF3A1D44), Color(0xFF1E0B18)];
    c.drawRect(
      r,
      Paint()
        ..shader = LinearGradient(begin: Alignment.topCenter, end: Alignment.bottomCenter, colors: cols)
            .createShader(r),
    );
    if (id == 'cielo_fugaces') _vFugaces(c, w, h);
    if (id == 'cielo_linternas') _vLinternasCielo(c, w, h);
    final math.Random rnd = math.Random(11);
    final int n = id == 'cielo_linternas' ? 30 : 70;
    for (int i = 0; i < n; i++) {
      final double x = rnd.nextDouble() * w;
      final double y = rnd.nextDouble() * h * 0.62;
      final double b = 0.4 + 0.4 * math.sin(t * 2 * math.pi * 2 + i.toDouble());
      c.drawCircle(Offset(x, y), rnd.nextDouble() * 1.2 + 0.35, Paint()..color = Colors.white.withValues(alpha: b * 0.8));
    }
  }

  void _cielo(Canvas c, double w, double h) {
    final String id = _id(CapaVineta.cielo, 'cielo_noche');
    if (id == 'cielo_fugaces' || id == 'cielo_linternas') {
      _cieloNuevo(c, w, h, id);
      return;
    }
    if (id == 'cielo_kintsugi') {
      _vCieloKintsugi(c, w, h);
      return;
    }
    final double hz = h * 0.70;
    final _DefCielo d = _cielosViejos[id] ?? _cielosViejos['cielo_noche']!;
    c.drawRect(
        Rect.fromLTWH(0, 0, w, h),
        Paint()..shader = _lin(Offset.zero, Offset(0, h), d.cols, const <double>[0, 0.42, 0.72, 1]));
    // Resplandor del horizonte.
    _glowE(c, Offset(w * 0.5, hz), w * 0.8, h * 0.32, d.hz, d.hzA);

    if (id == 'cielo_estrellado') {
      // Vía láctea: una banda diagonal de luz y polvo de estrellas.
      for (int i = 0; i < 9; i++) {
        final double u = i / 8;
        _glowE(c, Offset(w * u, h * (0.58 - 0.52 * u)), w * 0.16, h * 0.09,
            i.isOdd ? const Color(0xFF8E9BFF) : const Color(0xFFC7B6FF), 0.07);
      }
      for (int i = 0; i < 90; i++) {
        final double u = _h(i, 21);
        final double off = (_h(21, i) - 0.5) * (_h(i, 4) + _h(4, i)) * h * 0.14;
        _punto(c, Offset(w * u, h * (0.58 - 0.52 * u) + off), 0.3 + 0.5 * _h(i, 9),
            _al(Colors.white, 0.25 + 0.4 * (0.5 + 0.5 * math.sin(t * _tau * 3 + i))));
      }
    }
    if (id == 'cielo_cosmos') {
      // Nebulosas que giran muy despacio alrededor del centro.
      final Offset centro = Offset(w * 0.5, h * 0.3);
      const List<Color> cols = <Color>[
        Color(0xFFB79CFF),
        Color(0xFF5BD6A0),
        Color(0xFFF06BB0),
        Color(0xFF6FA8FF),
        Color(0xFFB79CFF),
      ];
      for (int i = 0; i < 5; i++) {
        final double a = t * _tau * 0.5 + i * _tau / 5;
        final double rr = w * (0.18 + 0.08 * (i % 2));
        _glowE(c, centro + Offset(math.cos(a) * rr, math.sin(a) * rr * 0.4), w * (0.2 + 0.05 * (i % 2)), h * 0.16,
            cols[i], 0.22);
      }
      _glowE(c, centro, w * 0.3, h * 0.12, Colors.white, 0.06);
    }
    if (d.estrellas > 0) _estrellasV(c, w, h, d.estrellas, id == 'cielo_cosmos' ? 31 : 11);

    if (id == 'cielo_aurora') {
      const List<Color> cols = <Color>[Color(0xFF5BE3A8), Color(0xFF6FD3FF), Color(0xFFB79CFF)];
      for (int i = 0; i < 3; i++) {
        double base(double x) =>
            h * (0.30 + 0.06 * i) + math.sin(x / w * _tau * 1.2 + t * _tau * 2 + i * 1.3) * h * 0.05;
        double largo(double x) => h * (0.2 + 0.08 * math.sin(x / w * _tau * 3 + t * _tau * 3 + i));
        final Path borde = Path();
        final Path cortina = Path();
        for (double x = -10; x <= w + 10; x += 8) {
          if (x == -10) {
            borde.moveTo(x, base(x));
            cortina.moveTo(x, base(x));
          } else {
            borde.lineTo(x, base(x));
            cortina.lineTo(x, base(x));
          }
        }
        double xr = -10;
        while (xr + 8 <= w + 10) {
          xr += 8;
        }
        for (; xr >= -10; xr -= 8) {
          cortina.lineTo(xr, base(xr) - largo(xr));
        }
        cortina.close();
        c.drawPath(
            cortina,
            Paint()
              ..shader =
                  _lin(Offset(0, h * 0.05), Offset(0, h * 0.44), <Color>[_al(cols[i], 0), _al(cols[i], 0.17)]));
        // Estrías verticales que laten.
        for (int k = 0; k < 40; k++) {
          final double xx = w * _h(k, i + 40);
          final double a = 0.07 * (0.4 + 0.6 * math.sin(t * _tau * 5 + k * 2 + i));
          _linea(c, Offset(xx, base(xx)), Offset(xx, base(xx) - largo(xx) * (0.4 + 0.6 * _h(i + 40, k))), 2,
              _al(cols[i], a));
        }
        c.drawPath(borde, _raya(_al(cols[i], 0.16), 3.2));
        c.drawPath(borde, _raya(_al(Colors.white, 0.22), 0.8));
      }
    }

    if (id == 'cielo_sangre') {
      // Sol hinchado y bajo, antes de la batalla.
      final Offset s = Offset(w * 0.3, h * 0.3);
      _glow(c, s, h * 0.55, const Color(0xFFFF5A3A), 0.30);
      _punto(c, s, h * 0.12, _al(const Color(0xFFFF8A5A), 0.85));
      _punto(c, s, h * 0.10, _al(const Color(0xFFFFC08A), 0.55));
    }
    if (id == 'cielo_oro') {
      // Rayos de luz que se abren desde arriba.
      final Offset o = Offset(w * 0.74, -h * 0.1);
      for (int i = 0; i < 7; i++) {
        final double a = math.pi * 0.25 + i * 0.13 + math.sin(t * _tau * 2 + i) * 0.02;
        c.drawPath(
          Path()
            ..moveTo(o.dx, o.dy)
            ..lineTo(o.dx + math.cos(a - 0.035) * w * 1.2, o.dy + math.sin(a - 0.035) * w * 1.2)
            ..lineTo(o.dx + math.cos(a + 0.035) * w * 1.2, o.dy + math.sin(a + 0.035) * w * 1.2)
            ..close(),
          Paint()
            ..shader = _lin(o, Offset(o.dx, hz),
                <Color>[_al(const Color(0xFFFFF2C8), 0.16), _al(const Color(0xFFFFF2C8), 0)]),
        );
      }
    }
    // Nubes que cruzan muy despacio.
    final (Color, Color, double, int)? nubes = switch (id) {
      'cielo_noche' => (const Color(0xFF3A2A66), const Color(0xFF4E3A84), 0.18, 2),
      'cielo_alba' => (const Color(0xFF6A4778), const Color(0xFFF2A88A), 0.42, 4),
      'cielo_ocaso' => (const Color(0xFF4A2450), const Color(0xFFE8835E), 0.42, 4),
      'cielo_tinta' => (const Color(0xFF0E0E10), const Color(0xFF46464C), 0.32, 4),
      'cielo_sangre' => (const Color(0xFF14040A), const Color(0xFF5A1420), 0.62, 3),
      'cielo_oro' => (const Color(0xFF7A5020), const Color(0xFFFFE2A0), 0.36, 3),
      _ => null,
    };
    if (nubes != null) {
      for (int i = 0; i < nubes.$4; i++) {
        final double vel = 0.05 + 0.03 * _h(i, 5);
        final double x = (((_h(5, i) + t * vel) % 1.4) - 0.2) * w;
        final double y = h * (0.12 + 0.34 * _h(i, 8));
        final double s = w * (0.07 + 0.05 * _h(i, 12));
        _nube(c, Offset(x, y), s, nubes.$1, nubes.$2, nubes.$3);
      }
    }
    if (id == 'cielo_tinta') {
      // Trazos de pincel horizontales, como sumi-e.
      for (int i = 0; i < 4; i++) {
        final double y = h * (0.16 + i * 0.12);
        final double x0 = w * (0.05 + 0.5 * _h(i, 2)) + math.sin(t * _tau + i) * w * 0.01;
        final double largo = w * (0.25 + 0.2 * _h(2, i));
        c.drawPath(
          Path()
            ..moveTo(x0, y)
            ..quadraticBezierTo(x0 + largo * 0.5, y - h * 0.035, x0 + largo, y + h * 0.006)
            ..quadraticBezierTo(x0 + largo * 0.5, y + h * 0.01, x0, y + h * 0.008)
            ..close(),
          Paint()..color = _al(const Color(0xFF0A0A0C), 0.38),
        );
      }
    }
  }

  // ---- LUNA -------------------------------------------------------------

  void _discoV(Canvas c, Offset p, double r, _DefLuna d, {bool crateres = true}) {
    final double latido = 1 + 0.12 * math.sin(t * _tau * 3);
    _glow(c, p, r * 3.6, d.halo, d.a * latido);
    _glow(c, p, r * 1.55, d.halo, d.a * 0.9);
    c.drawCircle(
        p,
        r,
        Paint()
          ..shader = ui.Gradient.radial(p, r, <Color>[d.luz, d.luz, d.sombra], const <double>[0, 0.7, 1],
              TileMode.clamp, null, p.translate(-r * 0.35, -r * 0.35), r * 0.1));
    if (crateres) {
      c.save();
      c.clipPath(Path()..addOval(Rect.fromCircle(center: p, radius: r)));
      const List<List<double>> cr = <List<double>>[
        <double>[-0.3, -0.15, 0.26, 0.10],
        <double>[0.25, 0.2, 0.2, 0.12],
        <double>[0.05, -0.42, 0.13, 0.08],
        <double>[-0.15, 0.4, 0.16, 0.09],
        <double>[0.45, -0.25, 0.1, 0.07],
      ];
      for (final List<double> k in cr) {
        _punto(c, p.translate(k[0] * r, k[1] * r), k[2] * r, _al(d.sombra, k[3] * 1.1));
      }
      c.restore();
    }
    // Borde iluminado.
    c.drawArc(Rect.fromCircle(center: p, radius: r * 0.97), -math.pi * 0.9, math.pi * 0.7, false,
        _raya(_al(Colors.white, 0.35), r * 0.05));
  }

  void _luna(Canvas c, double w, double h) {
    final String id = _id(CapaVineta.luna, 'luna_llena');
    final Offset p = Offset(w * 0.74, h * 0.27);
    final double r = h * 0.15;

    // La luna de las piezas nuevas (halo y conejo) se queda como estaba.
    void discoViejo(Color col, double halo) {
      c.drawCircle(
        p,
        r * 3.4,
        Paint()
          ..shader = RadialGradient(colors: <Color>[col.withValues(alpha: halo), Colors.transparent])
              .createShader(Rect.fromCircle(center: p, radius: r * 3.4)),
      );
      c.drawCircle(p, r, Paint()..color = col.withValues(alpha: 0.94));
    }

    final _DefLuna d = _lunasViejas[id] ?? _lunasViejas['luna_llena']!;
    switch (id) {
      case 'luna_halo':
        discoViejo(const Color(0xFFE8DCFF), 0.2);
        _vHalo(c, h, p, r);
      case 'luna_conejo':
        discoViejo(const Color(0xFFF2E9FF), 0.24);
        _vConejo(c, p, r);
      case 'luna_creciente':
        _glow(c, p, r * 3.2, d.halo, 0.2 * (1 + 0.1 * math.sin(t * _tau * 3)));
        // Luz cenicienta en la parte oscura.
        _punto(c, p, r, _al(const Color(0xFF3A2E5A), 0.55));
        c.drawPath(
          Path.combine(
            PathOperation.difference,
            Path()..addOval(Rect.fromCircle(center: p, radius: r)),
            Path()..addOval(Rect.fromCircle(center: p.translate(r * 0.42, -r * 0.16), radius: r * 0.92)),
          ),
          Paint()
            ..shader = ui.Gradient.radial(p, r, <Color>[d.luz, d.sombra], null, TileMode.clamp, null,
                p.translate(-r * 0.5, 0), r * 0.1),
        );
      case 'luna_eclipse':
        // Corona que respira y el anillo de diamante.
        _glow(c, p, r * 3.0, const Color(0xFFF2D493), 0.16);
        for (int i = 0; i < 28; i++) {
          final double ang = i * _tau / 28;
          final double largo = r * (0.28 + 0.22 * (0.5 + 0.5 * math.sin(t * _tau * 4 + i * 1.9)));
          final Offset u = Offset(math.cos(ang), math.sin(ang));
          _linea(c, p + u * r, p + u * (r + largo), r * 0.05, _al(const Color(0xFFFFE6A8), 0.22));
        }
        _glow(c, p, r * 1.35, const Color(0xFFFFE6A8), 0.55);
        _punto(c, p, r, const Color(0xFF0E0918));
        final double dia = 0.5 + 0.5 * math.sin(t * _tau * 2);
        final Offset q = p + Offset(math.cos(-math.pi * 0.3), math.sin(-math.pi * 0.3)) * r;
        _glow(c, q, r * 0.6, Colors.white, 0.6 * dia);
        _destello(c, q, r * 0.5 * dia, _al(Colors.white, 0.9 * dia), 1);
      case 'luna_gemela':
        final double b = math.sin(t * _tau * 2) * h * 0.01;
        _discoV(c, p.translate(-w * 0.06, h * 0.02 + b), r * 0.72, d);
        _discoV(
            c,
            p.translate(w * 0.075, -h * 0.065 - b),
            r * 0.46,
            const _DefLuna(Color(0xFFDCEBFF), Color(0xFF8EA4D8), Color(0xFFBFD8FF), 0.2));
      case 'luna_dorada':
        _discoV(c, p, r * 1.05, d);
        // Un brillo que cruza el disco.
        c.save();
        c.clipPath(Path()..addOval(Rect.fromCircle(center: p, radius: r * 1.05)));
        final double f = (t * 3) % 1.0;
        final double bx = p.dx - r * 1.6 + f * r * 3.2;
        c.drawRect(
          Rect.fromLTWH(bx - r * 0.3, p.dy - r * 1.1, r * 0.6, r * 2.2),
          Paint()
            ..shader = _lin(Offset(bx - r * 0.3, 0), Offset(bx + r * 0.3, 0),
                <Color>[_al(Colors.white, 0), _al(Colors.white, 0.45), _al(Colors.white, 0)]),
        );
        c.restore();
      case 'luna_velada':
        _discoV(c, p, r, d);
        for (int i = 0; i < 3; i++) {
          final double f = (t * (0.35 + i * 0.12) + i * 0.33) % 1.0;
          final Offset n = Offset(p.dx - w * 0.32 + f * w * 0.64, p.dy - r * 0.35 + i * r * 0.42);
          _nube(c, n, r * 1.1, const Color(0xFF1A1236), const Color(0xFF4E4380), 0.55);
          // Borde de luz de la nube.
          _glowE(c, n.translate(0, -r * 0.25), r * 1.2, r * 0.18, const Color(0xFFE8DCFF), 0.10);
        }
      case 'luna_kanji':
        _discoV(c, p, r, d, crateres: false);
        final double pulso = 0.5 + 0.5 * math.sin(t * _tau * 4);
        _glow(c, p, r * 0.9, const Color(0xFF8B5CF6), 0.18 * pulso);
        final TextPainter tp = TextPainter(
          text: TextSpan(
            text: '力',
            style: TextStyle(fontSize: r * 1.1, color: _al(const Color(0xFF2B1B52), 0.5 + 0.25 * pulso)),
          ),
          textDirection: TextDirection.ltr,
        )..layout();
        tp.paint(c, p + Offset(-tp.width / 2, -tp.height / 2 + r * 0.04));
      case 'luna_roja':
        _discoV(c, p, r, d);
        _glow(c, p, r * 5, const Color(0xFFE83A3A), 0.08);
      default:
        _discoV(c, p, r, d);
    }
  }

  // ---- MONTAÑAS ---------------------------------------------------------

  static const Color _lejosV = Color(0xFF2A1B4A);
  static const Color _medioV = Color(0xFF1E1236);
  static const Color _cercaV = Color(0xFF150C28);
  static const Color _bordeLuz = Color(0xFF9A7BFF);

  void _cordillera(Canvas c, double w, double h, double hz, int semilla, double altoMin, double altoMax, double paso,
      Color col, Color? luz, bool dentada) {
    final List<Offset> pts = <Offset>[];
    for (double x = -paso; x <= w + paso; x += paso) {
      pts.add(Offset(x, hz - h * (altoMin + (altoMax - altoMin) * _h((x / paso).round(), semilla))));
    }
    Path cresta() {
      final Path p = Path()..moveTo(pts[0].dx, pts[0].dy);
      for (int i = 1; i < pts.length; i++) {
        final Offset a = pts[i - 1], b = pts[i];
        if (dentada) {
          p.lineTo(b.dx, b.dy);
        } else {
          p.quadraticBezierTo(a.dx + (b.dx - a.dx) * 0.5, math.min(a.dy, b.dy) - h * 0.02, b.dx, b.dy);
        }
      }
      return p;
    }

    final Path relleno = Path()
      ..moveTo(-5, hz)
      ..lineTo(pts[0].dx, pts[0].dy)
      ..extendWithPath(cresta(), Offset.zero)
      ..lineTo(w + 5, hz)
      ..close();
    c.drawPath(relleno, Paint()..color = col);
    if (luz != null) c.drawPath(cresta(), _raya(luz, 1));
  }

  void _bruma(Canvas c, double w, double h, double hz, double tt, double a) {
    for (int i = 0; i < 3; i++) {
      final double f = ((tt * (0.12 + i * 0.05) + i * 0.37) % 1.4) - 0.2;
      _glowE(c, Offset(f * w, hz - h * 0.02 - i * h * 0.03), w * 0.35, h * 0.05, const Color(0xFFC9BCEB), a);
    }
  }

  void _cono(Canvas c, double hz, double cx, double top, double ancho, Color a, Color b, Color? nieve) {
    final double alto = hz - top;
    final Path cono = Path()
      ..moveTo(cx - ancho, hz)
      ..cubicTo(cx - ancho * 0.55, hz - alto * 0.35, cx - ancho * 0.22, top + alto * 0.05, cx - ancho * 0.08, top)
      ..lineTo(cx + ancho * 0.08, top)
      ..cubicTo(cx + ancho * 0.22, top + alto * 0.05, cx + ancho * 0.55, hz - alto * 0.35, cx + ancho, hz)
      ..close();
    c.drawPath(cono, Paint()..shader = _lin(Offset(0, top), Offset(0, hz), <Color>[a, b]));
    // Sombra del lado opuesto a la luna.
    c.save();
    c.clipPath(cono);
    c.drawRect(
      Rect.fromLTWH(cx - ancho, top, ancho * 1.2, alto),
      Paint()
        ..shader = _lin(Offset(cx - ancho, 0), Offset(cx + ancho * 0.2, 0),
            <Color>[_al(Colors.black, 0.35), _al(Colors.black, 0)]),
    );
    c.restore();
    if (nieve != null) {
      final double an = alto * 0.3;
      final Path n = Path()
        ..moveTo(cx - ancho * 0.08, top)
        ..lineTo(cx + ancho * 0.08, top)
        ..lineTo(cx + ancho * 0.26, top + an * 0.8);
      double s = 1;
      for (final double d in const <double>[0.18, 0.1, 0.03, -0.05, -0.13, -0.2, -0.27]) {
        n.lineTo(cx + ancho * d, top + an * (s > 0 ? 1.05 : 0.62));
        s = -s;
      }
      n.close();
      c.drawPath(
          n,
          Paint()
            ..shader = _lin(Offset(0, top), Offset(0, top + an), <Color>[nieve, _al(const Color(0xFF9C92C4), 0.9)]));
    }
    c.drawPath(
      Path()
        ..moveTo(cx + ancho * 0.08, top)
        ..cubicTo(cx + ancho * 0.22, top + alto * 0.05, cx + ancho * 0.55, hz - alto * 0.35, cx + ancho, hz),
      _raya(_al(_bordeLuz, 0.35), 1),
    );
  }

  void _montanas(Canvas c, double w, double h, double hz) {
    final String id = _id(CapaVineta.montanas, 'mont_colinas');

    switch (id) {
      case 'mont_cristal':
        _vCristal(c, w, h, hz);
      case 'mont_fuji':
      case 'mont_volcan':
      case 'mont_nevadas':
        _cordillera(c, w, h, hz, 3, 0.06, 0.14, w * 0.12, _al(_lejosV, 0.8), null, false);
        if (id == 'mont_nevadas') {
          _cono(c, hz, w * 0.18, h * 0.32, w * 0.2, const Color(0xFF2E2258), _medioV, const Color(0xFFE9E4F5));
          _cono(c, hz, w * 0.82, h * 0.30, w * 0.2, const Color(0xFF2E2258), _medioV, const Color(0xFFE9E4F5));
          _cono(c, hz, w * 0.48, h * 0.16, w * 0.32, const Color(0xFF3A2C66), _medioV, const Color(0xFFF2EEFA));
        } else if (id == 'mont_fuji') {
          _cono(c, hz, w * 0.44, h * 0.17, w * 0.38, const Color(0xFF3A2C66), const Color(0xFF1A1032),
              const Color(0xFFF2EEFA));
        } else {
          _cono(c, hz, w * 0.44, h * 0.19, w * 0.36, const Color(0xFF2E1424), const Color(0xFF120810), null);
          // Cráter encendido, coladas y humo.
          final double pl = 0.5 + 0.5 * math.sin(t * _tau * 6);
          _glow(c, Offset(w * 0.44, h * 0.19), w * 0.09, const Color(0xFFFF6A3A), 0.45 + 0.2 * pl);
          _ovalo(c, Offset(w * 0.44, h * 0.195), w * 0.03, h * 0.012, _al(const Color(0xFFFFC27A), 0.9));
          for (int i = 0; i < 3; i++) {
            final double sx = w * (0.425 + i * 0.016);
            c.drawPath(
              Path()
                ..moveTo(sx, h * 0.2)
                ..quadraticBezierTo(sx + (i - 1) * w * 0.03, h * 0.32, sx + (i - 1) * w * 0.06, h * (0.4 + 0.06 * i)),
              _raya(Colors.white, 1.6)
                ..shader = _lin(Offset(0, h * 0.2), Offset(0, h * 0.45),
                    <Color>[_al(const Color(0xFFFFB45A), 0.85), _al(const Color(0xFFE83A2A), 0)]),
            );
          }
          for (int i = 0; i < 6; i++) {
            final double f = (t * 0.8 + i / 6) % 1.0;
            _glow(c, Offset(w * 0.44 + math.sin(f * 5 + i) * w * 0.04 + f * w * 0.06, h * 0.17 - f * h * 0.2),
                w * (0.03 + f * 0.06), const Color(0xFFBFB6C8), 0.22 * (1 - f));
          }
        }
      case 'mont_dentadas':
        _cordillera(c, w, h, hz, 5, 0.16, 0.36, w * 0.06, _lejosV, _al(_bordeLuz, 0.25), true);
        _cordillera(c, w, h, hz, 9, 0.06, 0.2, w * 0.09, _medioV, _al(_bordeLuz, 0.3), true);
      case 'mont_acantilado':
        for (final double lado in <double>[-1, 1]) {
          final double x0 = lado < 0 ? 0 : w;
          final double borde = lado < 0 ? w * 0.27 : w * 0.71;
          final double top = lado < 0 ? h * 0.28 : h * 0.34;
          c.drawPath(
            Path()
              ..moveTo(x0, hz)
              ..lineTo(x0, top)
              ..lineTo(borde - lado * w * 0.02, top + h * 0.01)
              ..lineTo(borde, top + h * 0.08)
              ..lineTo(borde + lado * w * 0.01, top + h * 0.2)
              ..lineTo(borde + lado * w * 0.03, hz)
              ..close(),
            Paint()
              ..shader = _lin(Offset(0, top), Offset(0, hz),
                  <Color>[lado < 0 ? const Color(0xFF2A1D4A) : const Color(0xFF231840), _cercaV]),
          );
          // Estratos.
          for (int k = 1; k < 6; k++) {
            final double y = top + (hz - top) * k / 6;
            _linea(c, Offset(x0, y), Offset(borde + lado * w * 0.015 * k / 6, y + h * 0.006), 0.8,
                _al(const Color(0xFFB79CFF), 0.10));
          }
          _linea(c, Offset(x0, top), Offset(borde - lado * w * 0.02, top + h * 0.01), 1, _al(_bordeLuz, 0.3));
          // Pinos en el borde.
          for (int k = 0; k < 2; k++) {
            final double px = borde - lado * w * (0.04 + k * 0.05), py = top + h * 0.005;
            c.drawPath(
              Path()
                ..moveTo(px - 1.2, py)
                ..quadraticBezierTo(px + lado * w * 0.01, py - h * 0.03, px - lado * w * 0.004, py - h * 0.06)
                ..lineTo(px + 1.2, py)
                ..close(),
              Paint()..color = const Color(0xFF0C0718),
            );
            final Offset copa = Offset(px - lado * w * 0.004, py - h * 0.06);
            _ovalo(c, copa, w * 0.022, h * 0.012, const Color(0xFF0C0718));
            _ovalo(c, Offset(px + lado * w * 0.008, py - h * 0.038), w * 0.016, h * 0.01, const Color(0xFF0C0718));
            c.drawArc(Rect.fromCenter(center: copa, width: w * 0.044, height: h * 0.024), math.pi * 1.1,
                math.pi * 0.8, false, _raya(_al(_bordeLuz, 0.3), 0.7));
          }
        }
        _bruma(c, w, h, hz, t, 0.10);
      case 'mont_agujas':
        const List<(Color, double, double, int)> capas = <(Color, double, double, int)>[
          (_lejosV, 0.75, 0.3, 13),
          (_medioV, 0.9, 0.42, 17),
          (Color(0xFF150C28), 1.0, 0.3, 23),
        ];
        for (int k = 0; k < capas.length; k++) {
          final (Color col, double a, double altoMax, int s) = capas[k];
          for (int i = 0; i < 6; i++) {
            final double x = w * (0.04 + i * 0.18 + 0.08 * _h(i, s));
            final double alto = h * (0.14 + altoMax * _h(s, i));
            final double an = w * (0.03 + 0.015 * _h(i + 1, s));
            final double inc = (_h(i + 5, s) - 0.5) * an * 0.8;
            c.drawPath(
              Path()
                ..moveTo(x - an * 1.2, hz)
                ..cubicTo(x - an * 1.25, hz - alto * 0.55, x - an * 0.55 + inc, hz - alto * 0.95, x + inc, hz - alto)
                ..cubicTo(x + an * 0.55 + inc, hz - alto * 0.95, x + an * 1.15, hz - alto * 0.5, x + an * 1.3, hz)
                ..close(),
              Paint()..color = _al(col, a),
            );
            c.drawPath(
              Path()
                ..moveTo(x + inc, hz - alto)
                ..cubicTo(x + an * 0.55 + inc, hz - alto * 0.95, x + an * 1.15, hz - alto * 0.5, x + an * 1.3, hz),
              _raya(_al(_bordeLuz, 0.16 + 0.08 * k), 0.8),
            );
            // Matorrales en la cima.
            for (int m = -1; m <= 1; m++) {
              _punto(c, Offset(x + inc + m * an * 0.3, hz - alto + h * 0.004 - (m == 0 ? h * 0.006 : 0)), an * 0.22,
                  _al(const Color(0xFF0C0718), a));
            }
          }
          _bruma(c, w, h, hz - h * 0.05 * (2 - k), t + k * 0.3, 0.08);
        }
      case 'mont_islas':
        for (int i = 0; i < 3; i++) {
          final double x = w * (0.18 + i * 0.30);
          final double y = h * (0.30 + (i % 2) * 0.10) + math.sin(t * _tau * 2 + i * 2) * h * 0.02;
          final double an = w * (0.10 - 0.015 * (i % 2));
          // Raíces que cuelgan y se mecen.
          for (int k = 0; k < 4; k++) {
            final double rx = x - an * 0.5 + k * an * 0.33;
            final double s = math.sin(t * _tau * 3 + k + i) * w * 0.006;
            c.drawPath(
              Path()
                ..moveTo(rx, y + h * 0.03)
                ..quadraticBezierTo(rx + s, y + h * 0.09, rx + s * 2, y + h * (0.12 + 0.03 * _h(k, i))),
              _raya(_al(const Color(0xFF3B2A63), 0.8), 0.9),
            );
          }
          c.drawPath(
            Path()
              ..moveTo(x - an, y)
              ..quadraticBezierTo(x - an * 0.6, y + h * 0.1, x + an * 0.05, y + h * 0.15)
              ..quadraticBezierTo(x + an * 0.6, y + h * 0.08, x + an, y)
              ..close(),
            Paint()
              ..shader = _lin(Offset(0, y), Offset(0, y + h * 0.15),
                  const <Color>[Color(0xFF2E2052), Color(0xFF120A22)]),
          );
          _ovalo(c, Offset(x, y), an * 1.02, h * 0.022, const Color(0xFF3E2E72));
          _ovalo(c, Offset(x - an * 0.1, y - h * 0.008), an * 0.8, h * 0.012, _al(const Color(0xFF6A55A8), 0.6));
          // Un pino y, en la isla del medio, una cascada fina.
          _linea(c, Offset(x + an * 0.4, y), Offset(x + an * 0.4, y - h * 0.05), 1.2, const Color(0xFF0C0718));
          _ovalo(c, Offset(x + an * 0.4, y - h * 0.05), w * 0.018, h * 0.012, const Color(0xFF0C0718));
          if (i == 1) {
            for (int k = 0; k < 5; k++) {
              final double f = (t * 14 + k / 5) % 1.0;
              _linea(c, Offset(x - an * 0.7, y + h * 0.01 + f * h * 0.16), Offset(x - an * 0.7, y + h * 0.03 + f * h * 0.16),
                  1, _al(const Color(0xFFDCD4FF), 0.5 * (1 - f)));
            }
          }
        }
      default:
        // Colinas: dos cordones ondulados, el lejano más claro.
        final Path lomo = Path()
          ..moveTo(0, hz - h * 0.16)
          ..quadraticBezierTo(w * 0.22, hz - h * 0.36, w * 0.46, hz - h * 0.2)
          ..quadraticBezierTo(w * 0.7, hz - h * 0.38, w, hz - h * 0.22);
        c.drawPath(
          Path()
            ..moveTo(0, hz)
            ..extendWithPath(lomo, Offset.zero)
            ..lineTo(w, hz)
            ..close(),
          Paint()
            ..shader = _lin(Offset(0, hz - h * 0.38), Offset(0, hz),
                const <Color>[Color(0xFF2C1D50), Color(0xFF1C1134)]),
        );
        c.drawPath(lomo, _raya(_al(_bordeLuz, 0.25), 1));
        c.drawPath(
          Path()
            ..moveTo(0, hz)
            ..lineTo(0, hz - h * 0.08)
            ..quadraticBezierTo(w * 0.3, hz - h * 0.2, w * 0.6, hz - h * 0.07)
            ..quadraticBezierTo(w * 0.82, hz - h * 0.14, w, hz - h * 0.06)
            ..lineTo(w, hz)
            ..close(),
          Paint()..color = _medioV,
        );
        _bruma(c, w, h, hz, t, 0.07);
    }

    // Orilla cercana.
    final Path orilla = Path()
      ..moveTo(0, hz + 2)
      ..quadraticBezierTo(w * 0.35, hz - h * 0.10, w * 0.72, hz + 2);
    c.drawPath(
      Path()
        ..moveTo(0, hz + 2)
        ..quadraticBezierTo(w * 0.35, hz - h * 0.10, w * 0.72, hz + 2)
        ..lineTo(w, hz + 2)
        ..lineTo(w, hz + 8)
        ..lineTo(0, hz + 8)
        ..close(),
      Paint()..color = _cercaV,
    );
    c.drawPath(orilla, _raya(_al(_bordeLuz, 0.18), 0.8));
  }

  // ---- AGUA -------------------------------------------------------------

  void _reflejoLuna(Canvas c, double w, double h, double hz, Color col, double fuerza) {
    final double x = w * 0.74;
    for (int i = 0; i < 9; i++) {
      final double y = hz + h * 0.025 + i * h * 0.027;
      final double ancho = w * (0.07 - i * 0.004) * (0.8 + 0.2 * math.sin(t * _tau * 6 + i * 1.3));
      final double dx = math.sin(t * _tau * 4 + i * 0.9) * w * 0.008;
      _linea(c, Offset(x - ancho + dx, y), Offset(x + ancho + dx, y), 1.6, _al(col, fuerza * (0.55 - i * 0.05)));
    }
    _glowE(c, Offset(x, hz + h * 0.1), w * 0.1, h * 0.12, col, fuerza * 0.25);
  }

  /// Agua de la tanda nueva (farolillos y olas): se queda como estaba.
  void _aguaNueva(Canvas c, double w, double h, double hz, String id) {
    final Rect r = Rect.fromLTRB(0, hz, w, h);
    final List<Color> col = id == 'agua_toro'
        ? const <Color>[Color(0xFF1A1236), Color(0xFF07040E)]
        : const <Color>[Color(0xFF0E2A3A), Color(0xFF040C14)];
    c.drawRect(
      r,
      Paint()
        ..shader = LinearGradient(begin: Alignment.topCenter, end: Alignment.bottomCenter, colors: col).createShader(r),
    );
    for (int i = 0; i < 4; i++) {
      final double y = hz + h * 0.03 + i * h * 0.045;
      final double d = math.sin(t * 2 * math.pi + i) * w * 0.015;
      c.drawLine(
        Offset(w * 0.74 - w * 0.05 + d, y),
        Offset(w * 0.74 + w * 0.05 + d, y),
        Paint()
          ..color = Colors.white.withValues(alpha: 0.16 - i * 0.02)
          ..strokeWidth = 1.4
          ..strokeCap = StrokeCap.round,
      );
    }
    if (id == 'agua_toro') _vToro(c, w, h, hz);
    if (id == 'agua_olas') _vOlas(c, w, h, hz);
  }

  void _agua(Canvas c, double w, double h, double hz) {
    final String id = _id(CapaVineta.agua, 'agua_lago');
    if (id == 'agua_toro' || id == 'agua_olas') {
      _aguaNueva(c, w, h, hz, id);
      return;
    }
    final List<Color> cols = switch (id) {
      'agua_helada' => const <Color>[Color(0xFF2C3E58), Color(0xFF18243A), Color(0xFF0B1018)],
      'agua_seca' => const <Color>[Color(0xFF4A443A), Color(0xFF2C2820), Color(0xFF17150F)],
      'agua_laca' => const <Color>[Color(0xFF5A1422), Color(0xFF2E0912), Color(0xFF120409)],
      'agua_oro' => const <Color>[Color(0xFF6E521E), Color(0xFF33250C), Color(0xFF120C04)],
      'agua_espejo' => const <Color>[Color(0xFF211A44), Color(0xFF121030), Color(0xFF060810)],
      _ => const <Color>[Color(0xFF1C1236), Color(0xFF0E0820), Color(0xFF07040E)],
    };
    c.drawRect(Rect.fromLTRB(0, hz, w, h),
        Paint()..shader = _lin(Offset(0, hz), Offset(0, h), cols, const <double>[0, 0.5, 1]));
    final Color colLuna = (_lunasViejas[_id(CapaVineta.luna, 'luna_llena')] ?? _lunasViejas['luna_llena']!).halo;

    if (id == 'agua_seca') {
      // Jardín de arena rastrillada alrededor de tres piedras.
      const List<List<double>> piedras = <List<double>>[
        <double>[0.34, 0.15, 0.05],
        <double>[0.62, 0.22, 0.035],
        <double>[0.86, 0.12, 0.028],
      ];
      for (int k = 0; k < 6; k++) {
        final double y = hz + h * 0.03 + k * h * 0.05;
        final Path surco = Path();
        for (double x = 0; x <= w; x += 6) {
          double yy = y;
          for (final List<double> pd in piedras) {
            final double dx = (x - w * pd[0]) / (w * pd[2] * 3.4), dy = (y - (hz + h * pd[1])) / (h * 0.12);
            final double dd = dx * dx + dy * dy;
            if (dd < 1) yy += (y < hz + h * pd[1] ? -1 : 1) * (1 - dd) * h * 0.035;
          }
          if (x == 0) {
            surco.moveTo(x, yy);
          } else {
            surco.lineTo(x, yy);
          }
        }
        c.drawPath(surco, _raya(_al(const Color(0xFFFFF4DC), 0.08), 1));
      }
      for (final List<double> pd in piedras) {
        final Offset centro = Offset(w * pd[0], hz + h * pd[1]);
        for (int k = 1; k < 4; k++) {
          c.drawOval(
              Rect.fromCenter(
                  center: centro, width: 2 * w * pd[2] * (1 + k * 0.7), height: 2 * h * pd[2] * 0.9 * (1 + k * 0.7)),
              _raya(_al(const Color(0xFFFFF4DC), 0.09), 1));
        }
        _ovalo(c, centro, w * pd[2], h * pd[2] * 0.75, const Color(0xFF1E1B16));
        _ovalo(c, centro.translate(-w * pd[2] * 0.2, -h * pd[2] * 0.3), w * pd[2] * 0.6, h * pd[2] * 0.3,
            _al(const Color(0xFF4A6A3A), 0.55));
      }
      return;
    }

    // Línea de luz del horizonte.
    c.drawRect(
        Rect.fromLTWH(0, hz, w, 1.2),
        Paint()
          ..shader = _lin(Offset.zero, Offset(w, 0),
              <Color>[_al(Colors.white, 0), _al(Colors.white, 0.10), _al(Colors.white, 0)]));

    if (id == 'agua_espejo') {
      // El cielo vuelto del revés y la luna reflejada entera.
      c.drawRect(
          Rect.fromLTRB(0, hz, w, h),
          Paint()
            ..shader = _lin(Offset(0, hz), Offset(0, h),
                <Color>[_al(const Color(0xFF3A2A6A), 0.35), _al(Colors.black, 0)]));
      for (int i = 0; i < 26; i++) {
        _punto(c, Offset(_h(i, 11) * w, hz + (h - hz) * _h(11, i) * 0.9), 0.4 + 0.6 * _h(i, 7),
            _al(Colors.white, 0.25 * (0.5 + 0.5 * math.sin(t * _tau * 2 + i))));
      }
      final Offset rl = Offset(w * 0.74, hz + h * 0.12);
      c.save();
      c.translate(rl.dx, rl.dy);
      c.scale(1, 0.62);
      c.drawCircle(
          Offset.zero,
          h * 0.15,
          Paint()
            ..shader = ui.Gradient.radial(Offset(0, -h * 0.03), h * 0.15,
                <Color>[_al(colLuna, 0.6), _al(colLuna, 0.32)]));
      c.restore();
      _glowE(c, rl, h * 0.4, h * 0.16, colLuna, 0.18);
      for (int i = 0; i < 3; i++) {
        final double f = (t * 1.5 + i / 3) % 1.0;
        c.drawOval(Rect.fromCenter(center: rl, width: 2 * h * (0.15 + f * 0.3), height: 2 * h * (0.04 + f * 0.08)),
            _raya(_al(Colors.white, 0.12 * (1 - f)), 0.8));
      }
      return;
    }

    _reflejoLuna(
        c,
        w,
        h,
        hz,
        id == 'agua_oro'
            ? const Color(0xFFFFE6A0)
            : id == 'agua_laca'
                ? const Color(0xFFFFB09A)
                : colLuna,
        id == 'agua_helada' ? 0.25 : 0.5);

    // Ondas que se deslizan.
    for (int i = 0; i < 6; i++) {
      final double y = hz + h * (0.05 + i * 0.045);
      final double f = (t * (1 + i * 0.3) + _h(i, 2)) % 1.0;
      final double x = (f * 1.3 - 0.15) * w, largo = w * (0.06 + 0.06 * _h(2, i));
      _linea(c, Offset(x, y), Offset(x + largo, y), 1, _al(Colors.white, 0.08 * math.sin(f * math.pi)));
    }

    if (id == 'agua_helada') {
      // Grietas en el hielo con un destello que las recorre.
      const List<List<double>> grietas = <List<double>>[
        <double>[0.08, 0.1, 0.3, 0.2, 0.45, 0.14],
        <double>[0.55, 0.06, 0.62, 0.18, 0.8, 0.24],
        <double>[0.2, 0.26, 0.38, 0.22, 0.5, 0.28],
        <double>[0.7, 0.1, 0.92, 0.16, 0.98, 0.08],
      ];
      for (int k = 0; k < grietas.length; k++) {
        final List<double> g = grietas[k];
        c.drawPath(
          Path()
            ..moveTo(w * g[0], hz + h * g[1])
            ..lineTo(w * g[2], hz + h * g[3])
            ..lineTo(w * g[4], hz + h * g[5]),
          _raya(_al(const Color(0xFFE6F2FF), 0.22), 0.9),
        );
        final double f = (t * 2 + k * 0.27) % 1.0;
        if (f < 0.3) {
          final double q = f / 0.3;
          final double px = q < 0.5 ? g[0] + (g[2] - g[0]) * q * 2 : g[2] + (g[4] - g[2]) * (q - 0.5) * 2;
          final double py = q < 0.5 ? g[1] + (g[3] - g[1]) * q * 2 : g[3] + (g[5] - g[3]) * (q - 0.5) * 2;
          _glow(c, Offset(w * px, hz + h * py), 5, Colors.white, 0.7 * math.sin(q * math.pi));
        }
      }
      c.drawRect(
          Rect.fromLTWH(0, hz, w, h * 0.06),
          Paint()
            ..shader = _lin(Offset(0, hz), Offset(0, hz + h * 0.06),
                <Color>[_al(const Color(0xFFE6F2FF), 0.28), _al(const Color(0xFFE6F2FF), 0)]));
    }
    if (id == 'agua_cascada') _vCascada(c, w, h, hz);
    if (id == 'agua_oro' || id == 'agua_laca') {
      final int n = id == 'agua_oro' ? 30 : 16;
      for (int i = 0; i < n; i++) {
        final double x = ((_h(i, 41) + t * 0.2 * (0.5 + _h(41, i))) % 1.0) * w;
        final double y = hz + (h - hz) * (0.08 + 0.85 * _h(i, 43));
        final double b = 0.5 + 0.5 * math.sin(t * _tau * 3 + i * 2.1);
        if (id == 'agua_oro') {
          _punto(c, Offset(x, y), 0.6 + 0.8 * _h(i, 3), _al(const Color(0xFFFFE6A0), 0.3 + 0.6 * b));
          if (b > 0.85) _destello(c, Offset(x, y), 3.5 * b, _al(const Color(0xFFFFF6D6), 0.8 * b), 0.6);
        } else {
          // Pan de oro flotando sobre la laca.
          c.save();
          c.translate(x, y);
          c.rotate(i + t * _tau * 0.3);
          c.drawRect(const Rect.fromLTWH(-2, -1.2, 4, 2.4), Paint()..color = _al(const Color(0xFFF2D493), 0.35 + 0.4 * b));
          c.restore();
        }
      }
    }
  }

  // ---- VEGETACIÓN -------------------------------------------------------

  static const Color _tintaV = Color(0xFF0C0718);

  /// Pétalo de sakura con la muesca en la punta; [vuelta] es la escala X
  /// (el aleteo en 3D).
  void _petalo(Canvas c, Offset p, double s, double giro, double vuelta, Color col) {
    c.save();
    c.translate(p.dx, p.dy);
    c.rotate(giro);
    c.scale(math.max(0.15, vuelta.abs()), 1);
    c.drawPath(
      Path()
        ..moveTo(0, s)
        ..cubicTo(-s * 0.9, s * 0.3, -s * 0.7, -s * 0.8, -s * 0.15, -s)
        ..lineTo(0, -s * 0.72)
        ..lineTo(s * 0.15, -s)
        ..cubicTo(s * 0.7, -s * 0.8, s * 0.9, s * 0.3, 0, s)
        ..close(),
      Paint()..color = col,
    );
    c.restore();
  }

  void _arbolV(Canvas c, double w, double h, double hz, Color copaA, Color copaB, Color copaC,
      {bool petalos = false, bool brillo = false}) {
    final double bx = w * 0.925, by = hz + 4;
    final double giro = math.sin(t * _tau * 3) * 0.012;
    c.save();
    c.translate(bx, by);
    c.rotate(giro);
    c.translate(-bx, -by);
    // Tronco curvo que se afina, con dos ramas.
    c.drawPath(
      Path()
        ..moveTo(bx - w * 0.01, by)
        ..cubicTo(bx - w * 0.008, by - h * 0.1, bx - w * 0.04, by - h * 0.14, bx - w * 0.025, by - h * 0.24)
        ..lineTo(bx - w * 0.018, by - h * 0.24)
        ..cubicTo(bx - w * 0.028, by - h * 0.14, bx + w * 0.006, by - h * 0.1, bx + w * 0.01, by)
        ..close(),
      Paint()..color = _tintaV,
    );
    _linea(c, Offset(bx - w * 0.025, by - h * 0.16), Offset(bx - w * 0.085, by - h * 0.21), w * 0.005, _tintaV);
    _linea(c, Offset(bx - w * 0.02, by - h * 0.19), Offset(bx + w * 0.035, by - h * 0.25), w * 0.004, _tintaV);
    // Copa: muchos racimos pequeños dentro de un óvalo, en tres tonos.
    final Offset centro = Offset(bx - w * 0.03, by - h * 0.25);
    final double rx = w * 0.085, ry = h * 0.09;
    final List<(Offset, double)> racimos = <(Offset, double)>[
      for (int i = 0; i < 16; i++)
        (
          centro +
              Offset(math.cos(_h(i, 51) * _tau) * rx * math.sqrt(_h(51, i)),
                  math.sin(_h(i, 51) * _tau) * ry * math.sqrt(_h(51, i))),
          w * (0.016 + 0.014 * _h(i, 53)),
        ),
    ];
    if (brillo) _glowE(c, centro, rx * 1.9, ry * 1.9, copaB, 0.2);
    for (final (Offset, double) q in racimos) {
      _punto(c, q.$1.translate(0, q.$2 * 0.25), q.$2, _al(copaA, 0.95));
    }
    for (final (Offset, double) q in racimos) {
      _punto(c, q.$1.translate(-q.$2 * 0.15, -q.$2 * 0.1), q.$2 * 0.8, _al(copaB, 0.92));
    }
    for (final (Offset, double) q in racimos) {
      _punto(c, q.$1.translate(-q.$2 * 0.35, -q.$2 * 0.35), q.$2 * 0.32, _al(copaC, 0.55));
    }
    c.restore();
    if (petalos) {
      for (int i = 0; i < 9; i++) {
        final double f = (t * (1.4 + 0.3 * _h(i, 61)) + i / 9) % 1.0;
        _petalo(
            c,
            Offset(bx - w * 0.05 - f * w * 0.32 + math.sin(f * 7 + i) * w * 0.02, by - h * 0.26 + f * h * 0.3),
            2.4,
            f * 9 + i,
            math.cos(f * _tau * 2 + i),
            _al(copaB, 0.85 * (1 - f * 0.7)));
      }
    }
  }

  void _hojaArce(Canvas c, Offset p, double s, double giro, Color col) {
    c.save();
    c.translate(p.dx, p.dy);
    c.rotate(giro);
    final Path hoja = Path();
    for (int k = 0; k < 5; k++) {
      final double a = -math.pi / 2 + k * _tau / 5;
      final Offset punta = Offset(math.cos(a) * s, math.sin(a) * s);
      if (k == 0) {
        hoja.moveTo(punta.dx, punta.dy);
      } else {
        hoja.lineTo(punta.dx, punta.dy);
      }
      hoja.lineTo(math.cos(a + _tau / 10) * s * 0.42, math.sin(a + _tau / 10) * s * 0.42);
    }
    hoja.close();
    c.drawPath(hoja, Paint()..color = col);
    c.restore();
  }

  void _vegetacion(Canvas c, double w, double h, double hz) {
    final String id = _id(CapaVineta.vegetacion, 'veg_ninguna');

    switch (id) {
      case 'veg_sakura':
        _arbolV(c, w, h, hz, const Color(0xFF8A4E8E), const Color(0xFFE7B9F5), const Color(0xFFFBE6FF), petalos: true);
      case 'veg_sakura_nocturno':
        _arbolV(c, w, h, hz, const Color(0xFF9A4A86), const Color(0xFFFFC9E8), Colors.white,
            petalos: true, brillo: true);
      case 'veg_sauce':
        _vSauce(c, w, h, hz);
      case 'veg_susuki':
        _vSusuki(c, w, h, hz);
      case 'veg_arce':
        _arbolV(c, w, h, hz, const Color(0xFF7A1E1A), const Color(0xFFE8563C), const Color(0xFFFFB070));
        for (int i = 0; i < 5; i++) {
          final double f = (t * (1.1 + 0.3 * _h(i, 71)) + i / 5) % 1.0;
          _hojaArce(c, Offset(w * 0.88 - f * w * 0.3 + math.sin(f * 6 + i) * w * 0.02, hz - h * 0.3 + f * h * 0.34), 3,
              f * 8 + i, _al(const Color(0xFFE8563C), 0.9 * (1 - f * 0.6)));
        }
      case 'veg_bambu':
        for (int capa = 0; capa < 2; capa++) {
          for (int i = 0; i < 5; i++) {
            final double x = w * (0.015 + i * 0.045 + capa * 0.022);
            final double alto = h * (0.48 + 0.14 * _h(i, capa + 3)) * (capa == 1 ? 1 : 0.86);
            final double brisa = math.sin(t * _tau * 2 + i + capa) * w * 0.008;
            final Color col = capa == 1 ? _tintaV : _al(const Color(0xFF2A1E46), 0.85);
            final double grosor = w * (capa == 1 ? 0.009 : 0.006);
            c.drawPath(
              Path()
                ..moveTo(x, hz + 6)
                ..quadraticBezierTo(x + brisa * 0.3, hz - alto * 0.5, x + brisa, hz - alto),
              _raya(col, grosor),
            );
            for (int n = 1; n < 5; n++) {
              final double u = n / 5, y = hz + 6 - (alto + 6) * u, dx = brisa * u * u;
              _linea(c, Offset(x + dx - grosor * 0.9, y), Offset(x + dx + grosor * 0.9, y), 1.2,
                  capa == 1 ? _al(const Color(0xFF3A2C5E), 0.9) : _al(const Color(0xFF44366E), 0.6));
            }
            // Hojas lanceoladas en lo alto.
            for (int k = 0; k < 4; k++) {
              final double u = 0.62 + k * 0.1, y = hz + 6 - (alto + 6) * u, dx = brisa * u * u;
              final double lado = k.isOdd ? 1.0 : -1.0;
              final double ang = lado * (0.5 + 0.2 * math.sin(t * _tau * 3 + k + i)) + math.pi / 2;
              c.save();
              c.translate(x + dx, y);
              c.rotate(-ang + math.pi);
              c.drawPath(
                Path()
                  ..moveTo(0, 0)
                  ..quadraticBezierTo(w * 0.012, h * 0.01, w * 0.04, 0)
                  ..quadraticBezierTo(w * 0.012, -h * 0.01, 0, 0),
                Paint()..color = col,
              );
              c.restore();
            }
          }
        }
      case 'veg_pino':
        final double bx = w * 0.08, by = hz + 4;
        c.save();
        c.translate(bx, by);
        c.rotate(math.sin(t * _tau * 2) * 0.01);
        c.translate(-bx, -by);
        c.drawPath(
          Path()
            ..moveTo(bx - w * 0.012, by)
            ..cubicTo(bx - w * 0.03, by - h * 0.1, bx + w * 0.05, by - h * 0.16, bx + w * 0.02, by - h * 0.3)
            ..lineTo(bx + w * 0.03, by - h * 0.3)
            ..cubicTo(bx + w * 0.065, by - h * 0.16, bx - w * 0.01, by - h * 0.1, bx + w * 0.012, by)
            ..close(),
          Paint()..color = _tintaV,
        );
        // Almohadillas de agujas, horizontales, como en un bonsái.
        const List<List<double>> pads = <List<double>>[
          <double>[0.02, -0.3, 0.07],
          <double>[0.09, -0.22, 0.06],
          <double>[-0.03, -0.19, 0.05],
          <double>[0.07, -0.36, 0.045],
        ];
        for (final List<double> pd in pads) {
          final Offset q = Offset(bx + pd[0] * w, by + pd[1] * h);
          final double r = pd[2] * w;
          _linea(c, Offset(bx + w * 0.02, q.dy + h * 0.03), q, 1.5, _tintaV);
          _ovalo(c, q, r, r * 0.38, _tintaV);
          _ovalo(c, q.translate(-r * 0.15, -r * 0.12), r * 0.75, r * 0.2, _al(const Color(0xFF2E3A3A), 0.8));
          c.drawArc(Rect.fromCenter(center: q, width: r * 2, height: r * 0.76), math.pi * 1.1, math.pi * 0.8, false,
              _raya(_al(_bordeLuz, 0.25), 0.8));
        }
        c.restore();
      case 'veg_glicina':
        c.drawPath(
          Path()
            ..moveTo(-4, h * 0.04)
            ..quadraticBezierTo(w * 0.5, h * 0.1, w + 4, h * 0.03),
          _raya(_tintaV, 2.4),
        );
        for (int i = 0; i < 10; i++) {
          final double x = w * (0.04 + i * 0.1 + 0.03 * _h(i, 5));
          final double y0 = h * 0.04 + (h * 0.06) * math.sin(math.pi * x / w);
          final double largo = h * (0.12 + 0.1 * _h(5, i));
          final double s = math.sin(t * _tau * 2 + i * 0.8) * 0.08;
          for (int k = 0; k < 14; k++) {
            final double u = k / 13;
            final Offset q = Offset(x + s * largo * u * u * 1.5 + (k.isOdd ? 1 : -1) * w * 0.004 * (1 - u), y0 + largo * u);
            final double r = w * 0.012 * (1 - u * 0.65);
            _punto(c, q, r, _al(u < 0.5 ? const Color(0xFF8E6CE0) : const Color(0xFFC9B4FF), 0.65 + 0.3 * u));
            if (k % 3 == 0) _punto(c, q.translate(-r * 0.3, -r * 0.3), r * 0.4, _al(Colors.white, 0.35));
          }
        }
      case 'veg_loto':
        for (int i = 0; i < 6; i++) {
          final double x = w * (0.1 + i * 0.15 + 0.03 * _h(i, 2)), y = hz + h * (0.09 + 0.12 * _h(2, i));
          final double bob = math.sin(t * _tau * 2 + i) * 0.8;
          // Hoja con su muesca.
          c.save();
          c.translate(x, y + bob);
          c.scale(1, 0.38);
          final Path hoja = Path()
            ..moveTo(0, 0)
            ..arcTo(Rect.fromCircle(center: Offset.zero, radius: w * 0.04), 0.25, _tau - 0.5, false)
            ..close();
          c.drawPath(hoja, Paint()..color = const Color(0xFF1E4A34));
          c.drawPath(hoja, _raya(_al(const Color(0xFF5BD6A0), 0.35), 1.2));
          c.restore();
          if (i.isEven) {
            final double abre = 0.75 + 0.25 * math.sin(t * _tau + i);
            for (int k = -2; k <= 2; k++) {
              c.save();
              c.translate(x, y + bob - h * 0.01);
              c.rotate(k * 0.38 * abre);
              c.drawPath(
                Path()
                  ..moveTo(0, 0)
                  ..quadraticBezierTo(-w * 0.012, -h * 0.03, 0, -h * 0.055)
                  ..quadraticBezierTo(w * 0.012, -h * 0.03, 0, 0),
                Paint()
                  ..shader = _lin(Offset.zero, Offset(0, -h * 0.055), const <Color>[Color(0xFFE07AB8), Color(0xFFFFE2F2)]),
              );
              c.restore();
            }
            _glow(c, Offset(x, y + bob - h * 0.03), w * 0.03, const Color(0xFFFFC9E8), 0.25);
          }
        }
      default:
        break;
    }
  }

  // ---- ESTRUCTURA -------------------------------------------------------

  static const Color _sombraV = Color(0xFF0A0614);
  static const Color _luzC = Color(0xFFFFB45A);

  void _toriiV(Canvas c, Offset b, double a, Color col, Color? borde, {double niebla = 0}) {
    final double an = a * 0.82, iz = b.dx - an / 2, de = b.dx + an / 2, top = b.dy - a;
    final Paint relleno = Paint()..color = col;
    // Pilares ligeramente inclinados.
    for (final List<double> x in <List<double>>[
      <double>[iz + an * 0.08, iz + an * 0.12],
      <double>[de - an * 0.08, de - an * 0.12],
    ]) {
      c.drawPath(
        Path()
          ..moveTo(x[1] - a * 0.035, top + a * 0.18)
          ..lineTo(x[1] + a * 0.035, top + a * 0.18)
          ..lineTo(x[0] + a * 0.042, b.dy)
          ..lineTo(x[0] - a * 0.042, b.dy)
          ..close(),
        relleno,
      );
      c.drawRect(Rect.fromLTWH(x[0] - a * 0.055, b.dy - a * 0.06, a * 0.11, a * 0.06), Paint()..color = _sombraV);
    }
    // Nuki (la viga que atraviesa), shimaki y kasagi con las puntas arriba.
    c.drawRect(Rect.fromLTWH(iz - an * 0.02, top + a * 0.36, an * 1.04, a * 0.055), relleno);
    c.drawRect(Rect.fromLTWH(iz - an * 0.06, top + a * 0.14, an * 1.12, a * 0.05), relleno);
    c.drawPath(
      Path()
        ..moveTo(iz - an * 0.2, top - a * 0.02)
        ..quadraticBezierTo(b.dx, top + a * 0.07, de + an * 0.2, top - a * 0.02)
        ..lineTo(de + an * 0.16, top + a * 0.08)
        ..quadraticBezierTo(b.dx, top + a * 0.15, iz - an * 0.16, top + a * 0.08)
        ..close(),
      relleno,
    );
    // Gakuzuka: la tablilla del centro.
    c.drawRect(Rect.fromLTWH(b.dx - a * 0.04, top + a * 0.13, a * 0.08, a * 0.24), relleno);
    if (borde != null) {
      c.drawPath(
        Path()
          ..moveTo(iz - an * 0.2, top - a * 0.02)
          ..quadraticBezierTo(b.dx, top + a * 0.07, de + an * 0.2, top - a * 0.02),
        _raya(borde, a * 0.015),
      );
    }
    if (niebla > 0) _glowE(c, b.translate(0, -a * 0.1), an * 0.9, a * 0.4, const Color(0xFF2A1D4A), niebla);
  }

  /// Tejado japonés: alero ancho con las puntas levantadas.
  void _techo(Canvas c, double cx, double y, double an, double alto, Color col) {
    c.drawPath(
      Path()
        ..moveTo(cx - an, y - alto * 0.18)
        ..quadraticBezierTo(cx - an * 0.6, y, cx - an * 0.35, y - alto * 0.55)
        ..lineTo(cx, y - alto)
        ..lineTo(cx + an * 0.35, y - alto * 0.55)
        ..quadraticBezierTo(cx + an * 0.6, y, cx + an, y - alto * 0.18)
        ..lineTo(cx + an * 0.9, y)
        ..lineTo(cx - an * 0.9, y)
        ..close(),
      Paint()..color = col,
    );
    c.drawPath(
      Path()
        ..moveTo(cx, y - alto)
        ..lineTo(cx + an * 0.35, y - alto * 0.55)
        ..quadraticBezierTo(cx + an * 0.6, y, cx + an, y - alto * 0.18),
      _raya(_al(_bordeLuz, 0.35), 0.9),
    );
  }

  double _llamita(int i) => 0.78 + 0.12 * math.sin(t * _tau * 41 + i * 2.3) + 0.08 * math.sin(t * _tau * 97 + i);

  void _estructura(Canvas c, double w, double h, double hz) {
    final String id = _id(CapaVineta.estructura, 'est_torii');
    final Offset base = Offset(w * 0.26, hz + h * 0.06);
    final double bx = base.dx, by = base.dy, a = h * 0.28;
    final Paint sombra = Paint()..color = _sombraV;

    switch (id) {
      case 'est_faroles':
        _vFaroles(c, w, h);
      case 'est_puerta_luna':
        _vPuertaLuna(c, w, h, hz);
      case 'est_torii_dorado':
        _vToriiDorado(c, w, h, hz);
      case 'est_torii_doble':
        for (int i = 4; i >= 1; i--) {
          _toriiV(c, base.translate(w * 0.045 * i, -h * 0.012 * i), a * (1 - i * 0.13),
              i > 2 ? const Color(0xFF3A1420) : const Color(0xFF2A0C16), _al(const Color(0xFFFF6A5A), 0.15),
              niebla: 0.25);
        }
        _toriiV(c, base, a, const Color(0xFF1E070E), _al(const Color(0xFFFF6A5A), 0.38));
      case 'est_santuario':
        final double s = a;
        c.drawRect(Rect.fromLTWH(bx - s * 0.52, by - s * 0.08, s * 1.04, s * 0.08), sombra);
        for (int k = 0; k < 3; k++) {
          c.drawRect(Rect.fromLTWH(bx - s * 0.12 + k * s * 0.02, by - s * 0.02 * k, s * 0.24 - k * s * 0.04, s * 0.02), sombra);
        }
        c.drawRect(Rect.fromLTWH(bx - s * 0.36, by - s * 0.44, s * 0.72, s * 0.36), Paint()..color = const Color(0xFF100A1E));
        final double l = _llamita(1);
        c.drawRect(
            Rect.fromLTWH(bx - s * 0.1, by - s * 0.36, s * 0.2, s * 0.28),
            Paint()
              ..shader = _lin(Offset(0, by - s * 0.36), Offset(0, by - s * 0.08),
                  <Color>[_al(const Color(0xFFFFD08A), 0.65 * l), _al(const Color(0xFFE0A84E), 0.45 * l)]));
        _glow(c, Offset(bx, by - s * 0.22), s * 0.5, _luzC, 0.18 * l);
        for (final double lado in <double>[-1, 1]) {
          c.drawRect(Rect.fromLTWH(bx + lado * s * 0.34 - s * 0.02, by - s * 0.44, s * 0.04, s * 0.36), sombra);
          final Offset lq = Offset(bx + lado * s * 0.45, by - s * 0.3);
          final double ll = _llamita(lado.round() + 3);
          _ovalo(c, lq, s * 0.035, s * 0.05, _al(const Color(0xFFFFB45A), 0.85 * ll));
          _glow(c, lq, s * 0.16, _luzC, 0.28 * ll);
        }
        _techo(c, bx, by - s * 0.44, s * 0.62, s * 0.36, _sombraV);
        // Chigi cruzados en la cumbrera.
        _linea(c, Offset(bx - s * 0.06, by - s * 0.86), Offset(bx + s * 0.03, by - s * 0.74), 1.6, _sombraV);
        _linea(c, Offset(bx + s * 0.06, by - s * 0.86), Offset(bx - s * 0.03, by - s * 0.74), 1.6, _sombraV);
      case 'est_pagoda':
        final double s = a * 1.15;
        _linea(c, Offset(bx, by - s * 1.2), Offset(bx, by - s * 1.48), 1.4, _sombraV);
        for (int k = 0; k < 6; k++) {
          _punto(c, Offset(bx, by - s * (1.24 + k * 0.035)), s * 0.018, _sombraV);
        }
        for (int i = 0; i < 5; i++) {
          final double y = by - s * (0.08 + i * 0.22);
          final double an = s * (0.48 - i * 0.07);
          c.drawRect(Rect.fromLTWH(bx - an * 0.5, y - s * 0.13, an, s * 0.13), Paint()..color = const Color(0xFF0E0A1C));
          final double l = _llamita(i * 3);
          if (i.isEven || i == 3) {
            c.drawRect(Rect.fromLTWH(bx - an * 0.12, y - s * 0.1, an * 0.24, s * 0.06),
                Paint()..color = _al(const Color(0xFFFFC77A), 0.55 * l));
            _glow(c, Offset(bx, y - s * 0.07), an * 0.5, _luzC, 0.12 * l);
          }
          _techo(c, bx, y - s * 0.12, an * 1.05, s * 0.1, _sombraV);
        }
      case 'est_puente':
        final double s = a;
        Offset q(double u, Offset p0, Offset p1, Offset p2) =>
            p0 * ((1 - u) * (1 - u)) + p1 * (2 * u * (1 - u)) + p2 * (u * u);
        void pinta(bool refl) {
          double yb(double y) => refl ? by + (by - y) * 0.8 : y;
          double ola(int i) => refl ? math.sin(t * _tau * 6 + i) * 1.2 : 0;
          // Tablero.
          c.drawPath(
            Path()
              ..moveTo(bx - s * 0.78 + ola(0), yb(by))
              ..quadraticBezierTo(bx, yb(by - s * 0.62), bx + s * 0.78, yb(by)),
            _raya(refl ? _al(const Color(0xFFC8323A), 0.22) : const Color(0xFFA82830), s * 0.075),
          );
          if (!refl) {
            c.drawPath(
              Path()
                ..moveTo(bx - s * 0.78, by - s * 0.035)
                ..quadraticBezierTo(bx, by - s * 0.66, bx + s * 0.78, by - s * 0.035),
              _raya(_al(const Color(0xFFFF8A7A), 0.6), 1),
            );
          }
          // Barandilla y postes.
          c.drawPath(
            Path()
              ..moveTo(bx - s * 0.7, yb(by - s * 0.16))
              ..quadraticBezierTo(bx, yb(by - s * 0.76), bx + s * 0.7, yb(by - s * 0.16)),
            _raya(refl ? _al(const Color(0xFFC8323A), 0.18) : const Color(0xFF8E1E26), s * 0.03),
          );
          for (int i = 0; i <= 6; i++) {
            final double u = 0.08 + i * 0.14;
            final Offset p1 = q(u, Offset(bx - s * 0.78, by), Offset(bx, by - s * 0.62), Offset(bx + s * 0.78, by));
            final Offset p2 = q(u, Offset(bx - s * 0.7, by - s * 0.16), Offset(bx, by - s * 0.76),
                Offset(bx + s * 0.7, by - s * 0.16));
            _linea(c, Offset(p1.dx + ola(i), yb(p1.dy)), Offset(p2.dx + ola(i), yb(p2.dy)), s * 0.022,
                refl ? _al(const Color(0xFFC8323A), 0.15) : const Color(0xFF8E1E26));
            if (!refl && (i == 0 || i == 6)) {
              _punto(c, p2.translate(0, -s * 0.03), s * 0.03, const Color(0xFFE0A84E));
              _glow(c, p2.translate(0, -s * 0.03), s * 0.08, const Color(0xFFE0A84E), 0.3);
            }
          }
        }

        pinta(true);
        pinta(false);
      case 'est_dojo':
        final double s = a;
        c.drawRect(Rect.fromLTWH(bx - s * 0.6, by - s * 0.07, s * 1.2, s * 0.07), sombra);
        c.drawRect(Rect.fromLTWH(bx - s * 0.5, by - s * 0.4, s * 1.0, s * 0.33), Paint()..color = const Color(0xFF120C20));
        for (int i = 0; i < 4; i++) {
          final double x = bx - s * 0.42 + i * s * 0.22, l = _llamita(i + 7);
          c.drawRect(
              Rect.fromLTWH(x, by - s * 0.34, s * 0.18, s * 0.22),
              Paint()
                ..shader = _lin(Offset(0, by - s * 0.34), Offset(0, by - s * 0.12),
                    <Color>[_al(const Color(0xFFFFE2A8), 0.62 * l), _al(const Color(0xFFE0A84E), 0.45 * l)]));
          final Paint marco = _raya(_al(const Color(0xFF3A2414), 0.8), 0.8);
          c.drawLine(Offset(x + s * 0.09, by - s * 0.34), Offset(x + s * 0.09, by - s * 0.12), marco);
          c.drawLine(Offset(x, by - s * 0.23), Offset(x + s * 0.18, by - s * 0.23), marco);
        }
        _glow(c, Offset(bx, by - s * 0.2), s * 0.8, _luzC, 0.12);
        _techo(c, bx, by - s * 0.4, s * 0.72, s * 0.34, _sombraV);
        _linea(c, Offset(bx - s * 0.2, by - s * 0.74), Offset(bx + s * 0.2, by - s * 0.74), 2, _sombraV);
      case 'est_linterna':
        final double s = a * 0.62, l = _llamita(2);
        c.drawRect(Rect.fromLTWH(bx - s * 0.3, by - s * 0.08, s * 0.6, s * 0.08), sombra);
        c.drawRect(Rect.fromLTWH(bx - s * 0.1, by - s * 0.5, s * 0.2, s * 0.42), sombra);
        c.drawRect(Rect.fromLTWH(bx - s * 0.28, by - s * 0.56, s * 0.56, s * 0.07), sombra);
        c.drawRect(Rect.fromLTWH(bx - s * 0.24, by - s * 0.88, s * 0.48, s * 0.32), sombra);
        c.drawRect(
            Rect.fromLTWH(bx - s * 0.14, by - s * 0.82, s * 0.28, s * 0.2),
            Paint()
              ..shader = _lin(Offset(0, by - s * 0.84), Offset(0, by - s * 0.6),
                  <Color>[_al(const Color(0xFFFFE2A8), 0.85 * l), _al(const Color(0xFFFFB45A), 0.7 * l)]));
        _glow(c, Offset(bx, by - s * 0.72), s * 1.3, _luzC, 0.26 * l);
        _techo(c, bx, by - s * 0.88, s * 0.42, s * 0.24, _sombraV);
        _punto(c, Offset(bx, by - s * 1.14), s * 0.05, _sombraV);
        // Dos polillas que rondan la luz.
        for (int k = 0; k < 2; k++) {
          final double ang = t * _tau * (5 + k * 2) + k * 2;
          _punto(c, Offset(bx + math.cos(ang) * s * 0.45, by - s * 0.72 + math.sin(ang * 1.3) * s * 0.25), 1.1,
              _al(const Color(0xFFFFF2D0), 0.8));
        }
      case 'est_campana':
        final double s = a * 0.7;
        for (final double lado in <double>[-1, 1]) {
          c.drawRect(Rect.fromLTWH(bx + lado * s * 0.62 - s * 0.03, by - s * 1.3, s * 0.06, s * 1.3), sombra);
        }
        _techo(c, bx, by - s * 1.3, s * 0.95, s * 0.36, _sombraV);
        c.save();
        c.translate(bx, by - s * 1.26);
        c.rotate(math.sin(t * _tau * 4) * 0.08);
        _linea(c, Offset.zero, Offset(0, s * 0.12), 1.2, _sombraV);
        c.drawPath(
          Path()
            ..moveTo(-s * 0.3, s * 0.95)
            ..lineTo(-s * 0.27, s * 0.3)
            ..quadraticBezierTo(0, s * 0.02, s * 0.27, s * 0.3)
            ..lineTo(s * 0.3, s * 0.95)
            ..close(),
          Paint()
            ..shader = _lin(Offset(-s * 0.3, 0), Offset(s * 0.3, 0),
                const <Color>[Color(0xFF2A2416), Color(0xFF6A5A34), Color(0xFF2A2416)]),
        );
        _linea(c, Offset(-s * 0.3, s * 0.78), Offset(s * 0.3, s * 0.78), 1, _al(const Color(0xFFE0C98A), 0.4));
        _linea(c, Offset(-s * 0.28, s * 0.45), Offset(s * 0.28, s * 0.45), 1, _al(const Color(0xFFE0C98A), 0.3));
        c.restore();
        // El tronco que golpea (shumoku), a destiempo.
        final double golpe = math.sin(t * _tau * 4 + 1.2) * s * 0.06;
        _linea(c, Offset(bx + s * 0.62, by - s * 0.62), Offset(bx + s * 0.34 + golpe, by - s * 0.62), s * 0.08,
            const Color(0xFF3A2A1A));
        // Ondas del sonido.
        final double f = (t * 4) % 1.0;
        final Rect onda = Rect.fromCircle(center: Offset(bx, by - s * 0.8), radius: s * (0.4 + f * 0.8));
        final Paint pOnda = _raya(_al(const Color(0xFFE0C98A), 0.35 * (1 - f)), 1);
        c.drawArc(onda, -math.pi * 0.15, math.pi * 0.3, false, pOnda);
        c.drawArc(onda, math.pi * 0.85, math.pi * 0.3, false, pOnda);
      case 'est_castillo':
        final double s = a;
        // Muralla de piedra.
        c.drawPath(
          Path()
            ..moveTo(bx - s * 0.75, by)
            ..lineTo(bx - s * 0.6, by - s * 0.22)
            ..lineTo(bx + s * 0.6, by - s * 0.22)
            ..lineTo(bx + s * 0.75, by)
            ..close(),
          Paint()..color = const Color(0xFF16121E),
        );
        for (int k = 1; k < 4; k++) {
          _linea(c, Offset(bx - s * (0.75 - 0.05 * k), by - s * 0.055 * k), Offset(bx + s * (0.75 - 0.05 * k), by - s * 0.055 * k),
              0.6, _al(const Color(0xFFB79CFF), 0.12));
        }
        for (int i = 0; i < 4; i++) {
          final double y = by - s * (0.22 + i * 0.2), an = s * (0.5 - i * 0.09);
          c.drawRect(Rect.fromLTWH(bx - an * 0.8, y - s * 0.14, an * 1.6, s * 0.14), Paint()..color = const Color(0xFF1C1828));
          final double l = _llamita(i + 11);
          for (int k = -1; k <= 1; k++) {
            c.drawRect(Rect.fromLTWH(bx + k * an * 0.45 - s * 0.025, y - s * 0.1, s * 0.05, s * 0.05),
                Paint()..color = _al(const Color(0xFFFFC77A), (0.4 + 0.2 * ((i + k) % 2)) * l));
          }
          _techo(c, bx, y - s * 0.13, an * 1.1, s * 0.1, _sombraV);
          if (i == 1) {
            c.drawPath(
              Path()
                ..moveTo(bx - an * 0.3, y - s * 0.13)
                ..lineTo(bx, y - s * 0.25)
                ..lineTo(bx + an * 0.3, y - s * 0.13)
                ..close(),
              sombra,
            );
          }
        }
        final double top = by - s * 1.03;
        for (final double lado in <double>[-1, 1]) {
          _glow(c, Offset(bx + lado * s * 0.12, top), s * 0.06, const Color(0xFFF2D493), 0.5);
          _ovalo(c, Offset(bx + lado * s * 0.12, top), s * 0.025, s * 0.04, const Color(0xFFE0B85A), lado * 0.4);
        }
      default:
        _toriiV(c, base, a, const Color(0xFF1E070E), _al(const Color(0xFFFF6A5A), 0.38));
    }
  }

  // ---- CRIATURA ---------------------------------------------------------

  void _criatura(Canvas c, double w, double h, double hz) {
    final String id = _id(CapaVineta.criatura, 'cri_ninguna');

    switch (id) {
      case 'cri_grulla':
        _vAves(c, w, h, cuervo: false);
      case 'cri_cuervos':
        _vAves(c, w, h, cuervo: true);
      case 'cri_dragon':
        _vDragon(c, w, h);
      case 'cri_mariposas':
        _vMariposas(c, w, h, hz);
      case 'cri_grullas_papel':
        _vGrullasPapel(c, w, h);
      case 'cri_fenix':
        _vFenix(c, w, h);
      case 'cri_kitsune':
        _vKitsune(c, w, h, hz);
      case 'cri_koi_dorado':
        _vKoiDorado(c, w, h, hz);
      case 'cri_kitsunebi':
        _vKitsunebi(c, w, h, hz);
      case 'cri_zorro':
        final double x = w * 0.62, y = hz - 2, s = h * 0.13;
        const Color pelo = Color(0xFFEDE6F8);
        _glowE(c, Offset(x, y - s * 0.5), s * 1.2, s * 0.9, pelo, 0.10);
        c.save();
        c.translate(x + s * 0.18, y - s * 0.08);
        c.rotate(-0.6 + math.sin(t * _tau * 3) * 0.25);
        c.drawPath(
          Path()
            ..moveTo(0, 0)
            ..quadraticBezierTo(s * 0.55, -s * 0.05, s * 0.62, -s * 0.5)
            ..quadraticBezierTo(s * 0.4, -s * 0.2, 0, -s * 0.16)
            ..close(),
          Paint()..color = _al(pelo, 0.85),
        );
        _ovalo(c, Offset(s * 0.6, -s * 0.48), s * 0.07, s * 0.09, Colors.white);
        c.restore();
        c.drawPath(
          Path()
            ..moveTo(x - s * 0.22, y)
            ..quadraticBezierTo(x - s * 0.28, y - s * 0.4, x - s * 0.12, y - s * 0.62)
            ..lineTo(x - s * 0.17, y - s * 0.92)
            ..lineTo(x - s * 0.03, y - s * 0.74)
            ..lineTo(x + s * 0.05, y - s * 0.74)
            ..lineTo(x + s * 0.13, y - s * 0.92)
            ..lineTo(x + s * 0.1, y - s * 0.6)
            ..quadraticBezierTo(x + s * 0.06, y - s * 0.52, x + s * 0.02, y - s * 0.5)
            ..quadraticBezierTo(x + s * 0.24, y - s * 0.3, x + s * 0.22, y)
            ..close(),
          Paint()..color = _al(pelo, 0.92),
        );
        // Marcas rojas y ojos que parpadean.
        _linea(c, Offset(x - s * 0.1, y - s * 0.7), Offset(x - s * 0.06, y - s * 0.66), 1, _al(const Color(0xFFE2566F), 0.8));
        _linea(c, Offset(x + s * 0.06, y - s * 0.7), Offset(x + s * 0.02, y - s * 0.66), 1, _al(const Color(0xFFE2566F), 0.8));
        final double parp = ((t * 7) % 1.0) < 0.05 ? 0.2 : 1.0;
        _ovalo(c, Offset(x - s * 0.06, y - s * 0.63), s * 0.025, s * 0.02 * parp, const Color(0xFF2B1B52));
        _ovalo(c, Offset(x + s * 0.03, y - s * 0.63), s * 0.025, s * 0.02 * parp, const Color(0xFF2B1B52));
      case 'cri_carpa':
        const List<List<Color>> cols = <List<Color>>[
          <Color>[Color(0xFFF2F0F6), Color(0xFFE8563C)],
          <Color>[Color(0xFFFFB45A), Color(0xFFFFFFFF)],
        ];
        for (int i = 0; i < 2; i++) {
          final double ang = t * _tau * (1 + i * 0.5) + i * math.pi;
          final Offset centro =
              Offset(w * 0.52 + math.cos(ang) * w * 0.16, hz + h * (0.13 + i * 0.07) + math.sin(ang) * h * 0.04);
          final double ola = math.sin(t * _tau * 18 + i) * 0.35;
          final double l = w * 0.075;
          c.save();
          c.translate(centro.dx, centro.dy);
          c.scale(1, 0.5);
          c.rotate(ang + math.pi / 2);
          c.drawPath(
            Path()
              ..moveTo(l * 0.5, 0)
              ..quadraticBezierTo(l * 0.2, -l * 0.22, -l * 0.3, -l * 0.08)
              ..lineTo(-l * 0.55, -l * 0.2 + ola * l * 0.2)
              ..lineTo(-l * 0.5, 0)
              ..lineTo(-l * 0.55, l * 0.2 + ola * l * 0.2)
              ..lineTo(-l * 0.3, l * 0.08)
              ..quadraticBezierTo(l * 0.2, l * 0.22, l * 0.5, 0)
              ..close(),
            Paint()..color = _al(cols[i][0], 0.85),
          );
          _ovalo(c, Offset(l * 0.08, -l * 0.03), l * 0.14, l * 0.07, _al(cols[i][1], 0.85));
          _ovalo(c, Offset(-l * 0.15, l * 0.03), l * 0.08, l * 0.05, _al(cols[i][1], 0.75));
          c.restore();
          final double f = (t * 3 + i * 0.5) % 1.0;
          c.drawOval(Rect.fromCenter(center: centro, width: 2 * w * (0.01 + 0.04 * f), height: 2 * h * (0.006 + 0.02 * f)),
              _raya(_al(const Color(0xFFF0A0AE), 0.3 * (1 - f)), 1));
        }
      case 'cri_luciernagas':
        for (int i = 0; i < 18; i++) {
          final double x = w * _h(23, i) +
              math.sin(t * _tau * (1 + i % 3) + i) * w * 0.04 +
              math.sin(t * _tau * 2 + i * 3) * w * 0.015;
          final double y = hz - h * 0.24 * _h(i, 29) + math.cos(t * _tau * (1 + i % 2) + i) * h * 0.04;
          final double pulso = math.max(0.0, math.sin(t * _tau * (5 + i % 4) + i * 1.7));
          final double br = pulso * pulso;
          _glow(c, Offset(x, y), w * 0.025, const Color(0xFFDDF08A), 0.35 * br);
          _punto(c, Offset(x, y), 1.3, _al(const Color(0xFFF4FFB0), 0.25 + 0.75 * br));
        }
      case 'cri_espiritus':
        for (int i = 0; i < 4; i++) {
          final double f = (t * 0.5 + i * 0.25) % 1.0;
          final double x = w * (0.15 + i * 0.22) + math.sin(f * _tau + i) * w * 0.04;
          final double y = hz - h * 0.08 - f * h * 0.2;
          final double al = math.sin(f * math.pi);
          final double r = w * 0.016;
          _glow(c, Offset(x, y), r * 4, const Color(0xFF8FE8D8), 0.25 * al);
          // Llama de hitodama con su cola.
          c.save();
          c.translate(x, y);
          c.rotate(math.sin(t * _tau * 6 + i) * 0.25);
          c.drawPath(
            Path()
              ..moveTo(r, 0)
              ..arcTo(Rect.fromCircle(center: Offset.zero, radius: r), 0, math.pi, false)
              ..quadraticBezierTo(-r * 0.6, r * 2.8, r * 0.2, r * 3.6)
              ..quadraticBezierTo(r * 0.5, r * 2, r, 0)
              ..close(),
            Paint()
              ..shader = _lin(Offset(0, -r), Offset(0, r * 3.6),
                  <Color>[_al(const Color(0xFFE8FFFA), 0.85 * al), _al(const Color(0xFF5FC8C0), 0)]),
          );
          c.restore();
          _punto(c, Offset(x, y - r * 0.2), r * 0.45, _al(Colors.white, 0.9 * al));
        }
      case 'cri_tigre':
        final double x = w * 0.13, y = hz - h * 0.01;
        // Agazapado detrás de la hierba: lomo naranja con rayas de tinta.
        c.drawPath(
          Path()
            ..moveTo(x - w * 0.07, y)
            ..quadraticBezierTo(x - w * 0.06, y - h * 0.09, x - w * 0.01, y - h * 0.1)
            ..quadraticBezierTo(x + w * 0.04, y - h * 0.115, x + w * 0.065, y - h * 0.1)
            ..quadraticBezierTo(x + w * 0.1, y - h * 0.09, x + w * 0.105, y - h * 0.05)
            ..lineTo(x + w * 0.11, y)
            ..close(),
          Paint()
            ..shader = _lin(Offset(0, y - h * 0.11), Offset(0, y), const <Color>[Color(0xFFC8742A), Color(0xFF5A2E12)]),
        );
        for (int k = 0; k < 6; k++) {
          final double sx = x - w * 0.05 + k * w * 0.02;
          c.drawPath(
            Path()
              ..moveTo(sx, y - h * 0.1 + (k > 4 ? h * 0.01 : 0))
              ..quadraticBezierTo(sx + w * 0.008, y - h * 0.075, sx - w * 0.002, y - h * 0.05),
            _raya(_al(_tintaV, 0.85), 1.6),
          );
        }
        // Orejas.
        for (final double dx in <double>[0.05, 0.085]) {
          c.drawPath(
            Path()
              ..moveTo(x + w * (dx - 0.008), y - h * 0.1)
              ..lineTo(x + w * dx, y - h * 0.125)
              ..lineTo(x + w * (dx + 0.008), y - h * 0.1)
              ..close(),
            Paint()..color = const Color(0xFF7A4018),
          );
        }
        final double parp = ((t * 5) % 1.0) < 0.04 ? 0.15 : 1.0;
        for (final double dx in <double>[0.058, 0.08]) {
          _glow(c, Offset(x + w * dx, y - h * 0.08), w * 0.018, const Color(0xFFF4E08A), 0.55);
          _ovalo(c, Offset(x + w * dx, y - h * 0.08), w * 0.007, w * 0.005 * parp, const Color(0xFFFFF2A0));
        }
        // Hierba delante.
        for (int k = 0; k < 10; k++) {
          final double gx = x - w * 0.085 + k * w * 0.022, alto = h * (0.05 + 0.05 * _h(k, 3));
          final double sw = math.sin(t * _tau * 3 + k * 0.7) * w * 0.006;
          c.drawPath(
            Path()
              ..moveTo(gx - 1.2, y + 3)
              ..quadraticBezierTo(gx + sw, y - alto * 0.5, gx + sw * 2, y - alto)
              ..lineTo(gx + 1.2, y + 3)
              ..close(),
            Paint()..color = _tintaV,
          );
        }
      default:
        break;
    }
  }

  // ---- CLIMA ------------------------------------------------------------

  void _clima(Canvas c, double w, double h, double hz) {
    final String id = _id(CapaVineta.clima, 'cli_sereno');

    void caer(int n, int semilla, double vel, void Function(int i, double s, double f, double y) dibujar) {
      for (int i = 0; i < n; i++) {
        final double s = _h(i, semilla);
        final double f = (t * vel * (0.6 + 0.8 * s) + _h(semilla, i)) % 1.0;
        dibujar(i, s, f, -8 + f * (h + 16));
      }
    }

    switch (id) {
      case 'cli_momiji':
        _vMomiji(c, w, h);
      case 'cli_ventisca':
        _vVentisca(c, w, h);
      case 'cli_brasas':
        _vBrasas(c, w, h);
      case 'cli_niebla':
        for (int i = 0; i < 6; i++) {
          final double f = ((t * (0.18 + 0.06 * (i % 3)) + i / 6) % 1.6) - 0.3;
          _glowE(c, Offset(f * w, hz - h * 0.1 + i * h * 0.045), w * (0.32 + 0.1 * _h(i, 1)), h * 0.05,
              const Color(0xFFE6E0F5), 0.15);
        }
        c.drawRect(
            Rect.fromLTRB(0, hz - h * 0.2, w, h),
            Paint()
              ..shader = _lin(Offset(0, hz - h * 0.2), Offset(0, h),
                  <Color>[_al(const Color(0xFFE6E0F5), 0), _al(const Color(0xFFE6E0F5), 0.06)]));
      case 'cli_nieve':
        for (final (int, int, double, double, double) capa in const <(int, int, double, double, double)>[
          (26, 17, 0.4, 0.8, 0.45),
          (20, 19, 0.6, 1.4, 0.65),
          (8, 13, 0.9, 2.4, 0.8),
        ]) {
          caer(capa.$1, capa.$2, capa.$3, (int i, double s, double f, double y) {
            final Offset p = Offset(w * _h(capa.$2, i * 3) + math.sin(f * _tau * 2 + i) * w * 0.03, y);
            if (capa.$4 > 2) _glow(c, p, capa.$4 * 2.6, Colors.white, 0.25);
            _punto(c, p, capa.$4 * (0.7 + 0.5 * s), _al(Colors.white, capa.$5));
          });
        }
      case 'cli_lluvia':
      case 'cli_tormenta':
        final bool fuerte = id == 'cli_tormenta';
        if (fuerte) c.drawRect(Rect.fromLTWH(0, 0, w, h), Paint()..color = _al(const Color(0xFF05040A), 0.25));
        for (final (int, int, double, double, double) capa in <(int, int, double, double, double)>[
          (fuerte ? 34 : 22, 31, 5.0, 0.05, 0.18),
          (fuerte ? 24 : 14, 37, 7.0, 0.08, 0.3),
        ]) {
          caer(capa.$1, capa.$2, capa.$3, (int i, double s, double f, double y) {
            final Offset a = Offset(w * _h(capa.$2, i * 5) + f * w * 0.06, y);
            final Offset b = a.translate(-w * 0.012, h * capa.$4);
            c.drawLine(
                a,
                b,
                Paint()
                  ..strokeWidth = 1
                  ..shader = _lin(a, b, <Color>[_al(const Color(0xFF8FB6E8), 0), _al(const Color(0xFFBFD6FF), capa.$5)]));
          });
        }
        // Salpicaduras en el agua.
        for (int i = 0; i < (fuerte ? 7 : 4); i++) {
          final double u = t * 6 + i * 0.37;
          final double k = u.floorToDouble(), f = u - k;
          final Offset p = Offset(w * _h(k, i), hz + (h - hz) * (0.1 + 0.8 * _h(i, k)));
          c.drawOval(Rect.fromCenter(center: p, width: 2 * w * 0.02 * f, height: 2 * h * 0.008 * f),
              _raya(_al(const Color(0xFFBFD6FF), 0.35 * (1 - f)), 0.8));
        }
        if (fuerte) _vRayo(c, w, h);
      case 'cli_petalos':
        caer(24, 71, 0.6, (int i, double s, double f, double y) {
          _petalo(c, Offset(w * _h(71, i) + math.sin(f * _tau + i) * w * 0.06 + f * w * 0.1, y), 2.6 + 1.6 * s, f * 7 + i,
              math.cos(f * _tau * 3 + i * 2), _al(s > 0.5 ? const Color(0xFFF6C2E6) : const Color(0xFFE7B9F5), 0.8));
        });
      case 'cli_ceniza':
        caer(36, 53, 0.35, (int i, double s, double f, double y) {
          final Offset p = Offset(w * _h(53, i) + math.sin(f * _tau * 2 + i) * w * 0.03, y);
          if (s > 0.85) {
            final double b = 0.5 + 0.5 * math.sin(t * _tau * 9 + i);
            _glow(c, p, 4, const Color(0xFFFF8A3A), 0.45 * b);
            _punto(c, p, 1, _al(const Color(0xFFFFC08A), 0.8));
          } else {
            _ovalo(c, p, 1.4 * (0.6 + s), 0.9 * (0.6 + s), _al(const Color(0xFFBFB6A8), 0.35 + 0.2 * s), f * 6 + i);
          }
        });
      case 'cli_polvo_oro':
        caer(40, 67, 0.25, (int i, double s, double f, double y) {
          final Offset p = Offset(w * _h(67, i) + math.sin(f * _tau * 2 + i) * w * 0.04, y);
          final double b = 0.5 + 0.5 * math.sin(t * _tau * 6 + i * 2.3);
          _punto(c, p, 0.6 + 0.7 * s, _al(const Color(0xFFF2D493), 0.35 + 0.5 * b));
          if (b > 0.9 && s > 0.4) _destello(c, p, 3.5, _al(const Color(0xFFFFF6D6), 0.85), 0.6);
        });
      default:
        // Sereno: unos pocos pétalos y una brisa que apenas se nota.
        for (int i = 0; i < 6; i++) {
          final double s = i / 6;
          final double f = (t * (0.5 + s * 0.4) + s) % 1.0;
          _petalo(c, Offset(w * (0.10 + s * 0.8) + math.sin(f * _tau + i) * w * 0.03, -8 + f * (h + 16)), 2.4, f * 5 + i,
              math.cos(f * _tau * 2 + i), _al(const Color(0xFFE7B9F5), 0.55));
        }
    }
  }

  // ===== TEMPORADA DEL PASE ===============================================

  void _vCieloKintsugi(Canvas c, double w, double h) {
    final double hz = h * 0.7;
    c.drawRect(
        Rect.fromLTWH(0, 0, w, h),
        Paint()
          ..shader = _lin(Offset.zero, Offset(0, h),
              const <Color>[Color(0xFF0B0718), Color(0xFF160C2A), Color(0xFF1E1034), Color(0xFF0A0614)],
              const <double>[0, 0.4, 0.75, 1]));
    _glowE(c, Offset(w * 0.5, hz), w * 0.8, h * 0.3, const Color(0xFFE8B65A), 0.12);
    _estrellasV(c, w, h, 30, 47);
    // Grietas doradas: el cielo roto y reparado con oro.
    for (int k = 0; k < 5; k++) {
      final bool izq = k.isEven;
      final List<Offset> pts = <Offset>[];
      double x = izq ? -4 : w + 4, y = h * (0.06 + 0.5 * _h(81, k));
      double ang = (izq ? 0 : math.pi) + (_h(k, 82) - 0.5) * 0.7;
      for (int i = 0; i < 9; i++) {
        pts.add(Offset(x, y));
        ang += (_h(i, k + 83) - 0.5) * 0.9;
        final double paso = w * (0.05 + 0.04 * _h(k + 84, i));
        x += math.cos(ang) * paso;
        y += math.sin(ang) * paso * 0.6;
        y = y.clamp(2.0, hz - h * 0.1);
      }
      final Path camino = Path()..moveTo(pts[0].dx, pts[0].dy);
      for (int i = 1; i < pts.length; i++) {
        camino.lineTo(pts[i].dx, pts[i].dy);
      }
      c.drawPath(camino, _raya(_al(const Color(0xFFE8B65A), 0.18), 4.5));
      c.drawPath(camino, _raya(_al(const Color(0xFFFFE7A8), 0.85), 1.1));
      // Un pulso de luz recorre cada grieta.
      final double f = (t * 3 + k * 0.23) % 1.0;
      final double idx = f * (pts.length - 1);
      final int i0 = idx.floor();
      if (i0 < pts.length - 1) {
        final Offset q = Offset.lerp(pts[i0], pts[i0 + 1], idx - i0)!;
        _glow(c, q, 9, const Color(0xFFFFE7A8), 0.75);
        _punto(c, q, 1.4, Colors.white);
      }
      // Ramitas.
      for (int i = 1; i < pts.length - 1; i += 3) {
        final double a2 = (_h(i, k) - 0.5) * 2 + math.pi / 2;
        _linea(c, pts[i], pts[i] + Offset(math.cos(a2), math.sin(a2)) * (h * 0.04), 0.7,
            _al(const Color(0xFFFFE7A8), 0.6));
      }
    }
  }

  void _vToriiDorado(Canvas c, double w, double h, double hz) {
    final double bx = w * 0.26, by = hz + h * 0.06, a = h * 0.3;
    final double pulso = 0.5 + 0.5 * math.sin(t * _tau * 3);
    _glow(c, Offset(bx, by - a * 0.55), a * 1.3, const Color(0xFFF2D493), 0.16 + 0.08 * pulso);
    // Chispas que suben.
    for (int i = 0; i < 10; i++) {
      final double f = (t * (1.2 + 0.4 * _h(i, 91)) + _h(91, i)) % 1.0;
      _punto(c, Offset(bx + (_h(i, 92) - 0.5) * a * 1.1 + math.sin(f * _tau + i) * a * 0.05, by - f * a * 1.3), 0.9,
          _al(const Color(0xFFFFE7A8), 0.9 * math.sin(f * math.pi)));
    }
    _toriiV(c, Offset(bx, by), a, const Color(0xFFB8862A), _al(const Color(0xFFFFF2C8), 0.9));
    // Shimenawa: la soga sagrada, combada entre los pilares.
    final double an = a * 0.82, top = by - a;
    final Offset iz = Offset(bx - an / 2 + an * 0.12, top + a * 0.42);
    final Offset de = Offset(bx + an / 2 - an * 0.12, top + a * 0.42);
    final Offset ctrl = Offset(bx, top + a * 0.56);
    c.drawPath(
      Path()
        ..moveTo(iz.dx, iz.dy)
        ..quadraticBezierTo(ctrl.dx, ctrl.dy, de.dx, de.dy),
      _raya(const Color(0xFFD9C08A), a * 0.06),
    );
    Offset sobre(double u) => iz * ((1 - u) * (1 - u)) + ctrl * (2 * u * (1 - u)) + de * (u * u);
    for (int k = 0; k <= 10; k++) {
      final Offset q = sobre(k / 10);
      _linea(c, q.translate(-a * 0.015, -a * 0.025), q.translate(a * 0.015, a * 0.025), 1,
          _al(const Color(0xFF8A6A30), 0.9));
    }
    // Shide: papeles en zigzag que se mecen.
    final double s = a * 0.05;
    for (int k = 0; k < 4; k++) {
      final Offset q = sobre(0.2 + k * 0.2);
      c.save();
      c.translate(q.dx, q.dy + a * 0.02);
      c.rotate(math.sin(t * _tau * 5 + k * 1.7) * 0.18);
      c.drawPath(
        Path()
          ..moveTo(-s * 0.5, 0)
          ..lineTo(s * 0.5, 0)
          ..lineTo(s * 0.5, s)
          ..lineTo(-s * 0.2, s)
          ..lineTo(-s * 0.2, s * 2)
          ..lineTo(s * 0.5, s * 2)
          ..lineTo(s * 0.5, s * 3)
          ..lineTo(-s * 0.5, s * 3)
          ..close(),
        Paint()..color = _al(Colors.white, 0.92),
      );
      c.restore();
    }
  }

  void _vKitsunebi(Canvas c, double w, double h, double hz) {
    for (int i = 0; i < 7; i++) {
      final double f = (t * 0.6 + i / 7) % 1.0;
      final Offset p = Offset(
          w * (0.08 + f * 0.84), hz - h * (0.06 + 0.06 * math.sin(f * _tau * 2 + i)) - h * 0.03 * _h(i, 5));
      final double fl = 0.75 + 0.25 * math.sin(t * _tau * 23 + i * 3);
      final double a = math.min(1.0, math.sin(f * math.pi) * 1.6);
      final double r = w * 0.014 * fl;
      _glow(c, p, r * 5, const Color(0xFF7FA8FF), 0.3 * a);
      c.save();
      c.translate(p.dx, p.dy);
      c.rotate(math.sin(t * _tau * 7 + i) * 0.15);
      c.drawPath(
        Path()
          ..moveTo(r, 0)
          ..arcTo(Rect.fromCircle(center: Offset.zero, radius: r), 0, math.pi, false)
          ..quadraticBezierTo(-r * 0.4, -r * 2.2, r * 0.3, -r * 3.4)
          ..quadraticBezierTo(r * 0.6, -r * 1.6, r, 0)
          ..close(),
        Paint()
          ..shader = _lin(Offset(0, r), Offset(0, -r * 3.4),
              <Color>[_al(const Color(0xFFE6F0FF), 0.95 * a), _al(const Color(0xFF8E6CFF), 0)]),
      );
      c.restore();
      _punto(c, p, r * 0.5, _al(Colors.white, 0.9 * a));
    }
  }

  void _vSusuki(Canvas c, double w, double h, double hz) {
    for (int capa = 0; capa < 2; capa++) {
      final int n = capa == 1 ? 16 : 12;
      for (int i = 0; i < n; i++) {
        final double x0 = w * (capa == 1 ? 0.52 + 0.5 * _h(i, 95) : 0.6 + 0.4 * _h(i, 96));
        final double alto = h * (capa == 1 ? 0.26 + 0.12 * _h(96, i) : 0.2 + 0.08 * _h(95, i));
        // Una ola de viento recorre el campo.
        final double viento = math.sin(t * _tau * 3 - x0 / w * 6 + capa) * 0.5 + 0.5;
        final double dx = -w * (0.03 + 0.04 * viento) * (capa == 1 ? 1 : 0.7);
        final double y0 = h + 4;
        final Offset punta = Offset(x0 + dx, y0 - alto);
        c.drawPath(
          Path()
            ..moveTo(x0, y0)
            ..quadraticBezierTo(x0, y0 - alto * 0.6, punta.dx, punta.dy),
          _raya(capa == 1 ? _tintaV : _al(const Color(0xFF2A1E46), 0.9), capa == 1 ? 1.4 : 1),
        );
        // Penacho plateado.
        final double ang = math.atan2(punta.dy - (y0 - alto * 0.6), punta.dx - x0);
        for (int k = 0; k < 7; k++) {
          final double u = k / 6;
          final double lado = (k.isOdd ? 1.0 : -1.0) * w * 0.006 * (1 - u * 0.5);
          final Offset q = punta +
              Offset(math.cos(ang) * alto * 0.18 * u + math.sin(ang) * lado,
                  math.sin(ang) * alto * 0.18 * u - math.cos(ang) * lado);
          _ovalo(c, q, w * 0.011 * (1 - u * 0.4), w * 0.004,
              _al(capa == 1 ? const Color(0xFFE8E2F2) : const Color(0xFF9C92C4), capa == 1 ? 0.75 : 0.5), ang);
        }
      }
    }
    // Semillas al viento.
    for (int i = 0; i < 8; i++) {
      final double f = (t * (1.5 + _h(i, 97)) + _h(97, i)) % 1.0;
      _punto(c, Offset(w * (1 - f * 1.1), hz + h * 0.05 - f * h * 0.3 + math.sin(f * _tau * 2 + i) * h * 0.03), 0.8,
          _al(const Color(0xFFF4F1FA), 0.6 * math.sin(f * math.pi)));
    }
  }


  // ===== PIEZAS ANIMADAS NUEVAS =========================================
  //
  // t no vuelve a cero (ver _VinetaPerfilState): las partículas que caen o
  // suben se reciclan solas con % 1.0, sin saltos cada 34 segundos.

  static const double _tau = math.pi * 2;

  static double _hash(double a, double b) {
    final double x = math.sin(a * 127.1 + b * 311.7) * 43758.5453;
    return x - x.floorToDouble();
  }

  void _glow(Canvas c, Offset p, double r, Color col, double a) {
    if (r <= 0 || a <= 0) return;
    c.drawCircle(
      p,
      r,
      Paint()
        ..shader = RadialGradient(colors: <Color>[col.withValues(alpha: a.clamp(0.0, 1.0)), col.withValues(alpha: 0)])
            .createShader(Rect.fromCircle(center: p, radius: r)),
    );
  }

  void _punto(Canvas c, Offset p, double r, Color col, {double blur = 0}) {
    final Paint paint = Paint()..color = col;
    if (blur > 0) paint.maskFilter = MaskFilter.blur(BlurStyle.normal, blur);
    c.drawCircle(p, math.max(r, 0.01), paint);
  }

  Paint _raya(Color col, double ancho) => Paint()
    ..color = col
    ..style = PaintingStyle.stroke
    ..strokeWidth = ancho
    ..strokeCap = StrokeCap.round;

  void _elipse(Canvas c, Offset centro, double rx, double ry, double giro, Paint p) {
    c.save();
    c.translate(centro.dx, centro.dy);
    c.rotate(giro);
    c.drawOval(Rect.fromCenter(center: Offset.zero, width: rx * 2, height: ry * 2), p);
    c.restore();
  }

  // ---- Cielo ----

  void _vFugaces(Canvas c, double w, double h) {
    for (int i = 0; i < 3; i++) {
      final double u = (t + i * 0.37) / 0.16;
      final double k = u.floorToDouble();
      final double f = u - k;
      if (f > 0.2) continue;
      final double p = f / 0.2;
      final Offset o = Offset(w * (0.35 + 0.6 * _hash(k, i.toDouble())), h * (0.05 + 0.25 * _hash(i.toDouble(), k)));
      const Offset dir = Offset(-0.86, 0.5);
      final Offset cabeza = o + dir * (w * 0.32 * p);
      final Offset cola = cabeza - dir * (w * 0.12);
      final double a = math.sin(p * math.pi);
      c.drawLine(
        cabeza,
        cola,
        Paint()
          ..shader = ui.Gradient.linear(
              cabeza, cola, <Color>[Colors.white.withValues(alpha: 0.9 * a), const Color(0x00B79CFF)])
          ..strokeWidth = 1.6
          ..strokeCap = StrokeCap.round,
      );
      _punto(c, cabeza, 1.6, Colors.white.withValues(alpha: a));
      _punto(c, cabeza, 4, const Color(0xFFD9CCFF).withValues(alpha: 0.35 * a), blur: 2);
    }
  }

  void _vLinternasCielo(Canvas c, double w, double h) {
    final double hz = h * 0.70;
    final math.Random rnd = math.Random(29);
    for (int i = 0; i < 16; i++) {
      final double s = rnd.nextDouble(), base = rnd.nextDouble(), px = rnd.nextDouble();
      final double prof = 0.45 + 0.55 * s;
      final double f = (t * (0.9 + s * 0.6) + base) % 1.0;
      final double y = hz - f * (hz + 24) + 8;
      final double x = w * (0.04 + 0.92 * px) + math.sin(t * _tau * 3 + i) * w * 0.012;
      final double tam = 3 + 4.5 * prof;
      final double a = (math.min(1.0, (1 - f) * 2.2) * (0.55 + 0.45 * prof)).clamp(0.0, 1.0);
      final double parpadeo = 0.85 + 0.15 * math.sin(t * _tau * 37 + i * 2.3);
      _glow(c, Offset(x, y), tam * 3.2, const Color(0xFFFFB45A), 0.32 * a * parpadeo);
      c.drawRRect(
          RRect.fromRectAndRadius(
              Rect.fromLTWH(x - tam * 0.5, y - tam * 0.62, tam, tam * 1.2), Radius.circular(tam * 0.25)),
          Paint()..color = const Color(0xFFF6A94E).withValues(alpha: a));
      c.drawRRect(
          RRect.fromRectAndRadius(
              Rect.fromLTWH(x - tam * 0.3, y - tam * 0.4, tam * 0.6, tam * 0.8), Radius.circular(tam * 0.2)),
          Paint()..color = const Color(0xFFFFE1A6).withValues(alpha: a));
      final Paint banda = Paint()..color = const Color(0xFF7A3A22).withValues(alpha: a);
      c.drawRect(Rect.fromLTWH(x - tam * 0.55, y - tam * 0.66, tam * 1.1, tam * 0.14), banda);
      c.drawRect(Rect.fromLTWH(x - tam * 0.55, y + tam * 0.52, tam * 1.1, tam * 0.14), banda);
    }
  }

  // ---- Luna ----

  void _vHalo(Canvas c, double h, Offset p, double r) {
    final double pulso = 0.5 + 0.5 * math.sin(t * _tau * 4);
    c.drawCircle(
      p,
      r * 2.25,
      _raya(Colors.white.withValues(alpha: 0.10 + 0.12 * pulso), h * 0.018)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 1.6),
    );
    c.drawCircle(
      p,
      r * 2.6,
      _raya(const Color(0xFFCFE6FF).withValues(alpha: 0.08 + 0.08 * pulso), h * 0.008)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 1.6),
    );
    for (int i = 0; i < 4; i++) {
      final double a = t * _tau * 1.5 + i * _tau / 4;
      _punto(c, p + Offset(math.cos(a), math.sin(a)) * (r * 2.25), 1.3, Colors.white.withValues(alpha: 0.55 * pulso));
    }
  }

  void _vConejo(Canvas c, Offset p, double r) {
    final Paint col = Paint()..color = const Color(0xFFB9A8E0).withValues(alpha: 0.85);
    final double golpe = math.max(0.0, math.sin(t * _tau * 18));
    _elipse(c, p + Offset(-r * 0.18, r * 0.22), r * 0.30, r * 0.24, 0, col); // cuerpo
    _elipse(c, p + Offset(-r * 0.02, -r * 0.02), r * 0.16, r * 0.14, 0, col); // cabeza
    _elipse(c, p + Offset(-r * 0.06, -r * 0.28), r * 0.05, r * 0.18, -0.25, col); // orejas
    _elipse(c, p + Offset(r * 0.04, -r * 0.27), r * 0.05, r * 0.17, 0.2, col);
    c.drawPath(
        Path()
          ..moveTo(p.dx + r * 0.14, p.dy + r * 0.30)
          ..lineTo(p.dx + r * 0.52, p.dy + r * 0.30)
          ..lineTo(p.dx + r * 0.46, p.dy + r * 0.52)
          ..lineTo(p.dx + r * 0.20, p.dy + r * 0.52)
          ..close(),
        col); // mortero
    final double ang = -0.9 + golpe * 0.75; // el mazo sube y baja
    final Offset mango = p + Offset(r * 0.06, r * 0.10);
    final Offset punta = mango + Offset(math.cos(ang), math.sin(ang)) * (r * 0.42);
    c.drawLine(mango, punta, _raya(col.color, r * 0.06));
    c.save();
    c.translate(punta.dx, punta.dy);
    c.rotate(ang + math.pi / 2);
    c.drawRect(Rect.fromLTWH(-r * 0.12, -r * 0.07, r * 0.24, r * 0.14), col);
    c.restore();
  }

  // ---- Montañas ----

  void _vCristal(Canvas c, double w, double h, double hz) {
    const List<List<double>> picos = <List<double>>[
      <double>[0.10, 0.30, 0.08],
      <double>[0.26, 0.46, 0.10],
      <double>[0.44, 0.36, 0.09],
      <double>[0.62, 0.50, 0.11],
      <double>[0.82, 0.34, 0.09],
    ];
    for (int i = 0; i < picos.length; i++) {
      final double x = w * picos[i][0], top = hz - h * picos[i][1], a = w * picos[i][2];
      final double brillo = 0.55 + 0.25 * math.sin(t * _tau * 2 + i * 1.3);
      c.drawPath(
        Path()
          ..moveTo(x - a, hz)
          ..lineTo(x - a * 0.25, top + h * 0.06)
          ..lineTo(x, top)
          ..lineTo(x + a * 0.35, top + h * 0.08)
          ..lineTo(x + a, hz)
          ..close(),
        Paint()
          ..shader = ui.Gradient.linear(
            Offset(x, top),
            Offset(x, hz),
            <Color>[
              const Color(0xFFCDB8FF).withValues(alpha: 0.80 * brillo),
              const Color(0xFF6E52C8).withValues(alpha: 0.55),
              const Color(0xFF1E1236).withValues(alpha: 0.9),
            ],
            <double>[0, 0.5, 1],
          ),
      );
      c.drawLine(Offset(x, top), Offset(x - a * 0.1, hz), Paint()
        ..color = const Color(0xFFF1E9FF).withValues(alpha: 0.5 * brillo)
        ..strokeWidth = 1);
      final double f = (t * 6 + i * 0.21) % 1.0;
      if (f < 0.25) {
        final double q = f / 0.25;
        _punto(c, Offset(x - a * 0.1 * q, top + (hz - top) * q), 2.2,
            Colors.white.withValues(alpha: math.sin(q * math.pi) * 0.9),
            blur: 1);
      }
    }
  }

  // ---- Agua ----

  void _vToro(Canvas c, double w, double h, double hz) {
    final math.Random rnd = math.Random(47);
    for (int i = 0; i < 8; i++) {
      final double s = rnd.nextDouble(), base = rnd.nextDouble();
      final double prof = 0.4 + 0.6 * ((i % 3) / 2);
      final double x = (((t * (2.2 + s) + base) % 1.15) - 0.075) * w;
      final double y = hz + h * (0.05 + 0.2 * prof) + math.sin(t * _tau * 6 + i) * 1.2;
      final double tam = 2.5 + 3.5 * prof;
      c.drawRect(
        Rect.fromLTWH(x - tam * 0.5, y, tam, tam * 4),
        Paint()
          ..shader = ui.Gradient.linear(Offset(x, y), Offset(x, y + tam * 4),
              <Color>[const Color(0x59FFB45A), const Color(0x00FFB45A)]),
      );
      _glow(c, Offset(x, y - tam * 0.4), tam * 3, const Color(0xFFFFB45A), 0.28);
      c.drawRect(Rect.fromLTWH(x - tam * 0.7, y - tam * 0.1, tam * 1.4, tam * 0.3), Paint()..color = const Color(0xFF3A2414));
      c.drawRect(Rect.fromLTWH(x - tam * 0.45, y - tam, tam * 0.9, tam * 0.9), Paint()..color = const Color(0xFFFFD38A));
    }
  }

  void _vOlas(Canvas c, double w, double h, double hz) {
    for (int fila = 0; fila < 3; fila++) {
      final double y = hz + h * (0.04 + fila * 0.085);
      final double amp = h * (0.018 + fila * 0.008);
      final double vel = (fila + 1) * 2.0;
      final Path ola = Path();
      for (double x = -10; x <= w + 10; x += 4) {
        final double yy = y + math.sin(x / w * _tau * (2 + fila) + t * _tau * vel) * amp;
        if (x == -10) {
          ola.moveTo(x, yy);
        } else {
          ola.lineTo(x, yy);
        }
      }
      c.drawPath(ola, _raya(const Color(0xFFCFE8F2).withValues(alpha: 0.22 + fila * 0.12), 1.2 + fila * 0.5));
      // Crestas que se enroscan
      final int n = 4 + fila;
      for (int k = 0; k < n; k++) {
        final double x = ((k / n + t * vel * 0.16) % 1.0) * w;
        final double yy = y + math.sin(x / w * _tau * (2 + fila) + t * _tau * vel) * amp;
        c.drawArc(Rect.fromCircle(center: Offset(x, yy - amp * 0.6), radius: amp * 0.9), math.pi * 0.9, math.pi * 1.1,
            false, _raya(Colors.white.withValues(alpha: 0.35 + fila * 0.15), 1.4));
        _punto(c, Offset(x + amp * 0.9, yy - amp * 0.4), 0.9 + fila * 0.3, Colors.white.withValues(alpha: 0.6));
      }
    }
  }

  void _vCascada(Canvas c, double w, double h, double hz) {
    final double top = hz - h * 0.16, alto = h * 0.17;
    c.drawRect(Rect.fromLTWH(w * 0.055, top, w * 0.085, alto), Paint()..color = Colors.white.withValues(alpha: 0.07));
    for (int i = 0; i < 7; i++) {
      final double x = w * (0.06 + i * 0.011);
      for (int k = 0; k < 3; k++) {
        final double f = (t * (24 + i * 2) + k / 3 + i * 0.17) % 1.0;
        final double y = top + f * alto;
        c.drawLine(Offset(x, y), Offset(x, math.min(y + h * 0.045, top + alto)),
            _raya(Colors.white.withValues(alpha: 0.30 * (1 - f * 0.6)), 1));
      }
    }
    final double espuma = 0.5 + 0.5 * math.sin(t * _tau * 20);
    _punto(c, Offset(w * 0.10, hz), w * 0.05, Colors.white.withValues(alpha: 0.08 + 0.06 * espuma), blur: 8);
  }

  // ---- Estructura ----

  void _vFaroles(Canvas c, double w, double h) {
    final double y0 = h * 0.08, y1 = h * 0.16, comba = h * 0.12;
    c.drawPath(
        Path()
          ..moveTo(-5, y0)
          ..quadraticBezierTo(w * 0.5, y0 + comba * 2, w + 5, y1),
        _raya(const Color(0xF20C0818), 1.2));
    const int n = 7;
    for (int i = 0; i < n; i++) {
      final double u = (i + 0.5) / n;
      final double x = u * w;
      final double y = (1 - u) * (1 - u) * y0 + 2 * u * (1 - u) * (y0 + comba * 2) + u * u * y1;
      final double vaiven = math.sin(t * _tau * 7 + i * 0.8) * 0.12;
      final double tam = h * 0.055;
      c.save();
      c.translate(x, y);
      c.rotate(vaiven);
      c.drawLine(Offset.zero, Offset(0, tam * 0.5), _raya(const Color(0xFF0C0818), 1));
      _glow(c, Offset(0, tam * 1.4), tam * 2.6, const Color(0xFFFF6A4A), 0.30 + 0.06 * math.sin(t * _tau * 41 + i));
      c.drawOval(Rect.fromCenter(center: Offset(0, tam * 1.4), width: tam * 1.24, height: tam * 1.7),
          Paint()..color = const Color(0xFFD9402E));
      for (final double k in <double>[-0.4, 0, 0.4]) {
        c.drawOval(
            Rect.fromCenter(
                center: Offset(0, tam * 1.4 + k * tam), width: tam * 1.24 * math.sqrt(1 - k * k), height: tam * 0.16),
            _raya(const Color(0x80FFC08A), 0.7));
      }
      final Paint aro = Paint()..color = const Color(0xFF1A0F14);
      c.drawRect(Rect.fromLTWH(-tam * 0.35, tam * 0.5, tam * 0.7, tam * 0.16), aro);
      c.drawRect(Rect.fromLTWH(-tam * 0.35, tam * 2.12, tam * 0.7, tam * 0.16), aro);
      c.restore();
    }
  }

  void _vPuertaLuna(Canvas c, double w, double h, double hz) {
    final double x = w * 0.26, y = hz - h * 0.14, r = h * 0.15;
    final double pulso = 0.5 + 0.5 * math.sin(t * _tau * 3);
    _glow(c, Offset(x, y), r * 1.4, const Color(0xFFB79CFF), 0.25 + 0.15 * pulso);
    c.drawPath(
      Path()
        ..fillType = PathFillType.evenOdd
        ..addRect(Rect.fromLTWH(x - r * 1.9, y - r * 1.5, r * 3.8, hz + h * 0.06 - (y - r * 1.5)))
        ..addOval(Rect.fromCircle(center: Offset(x, y), radius: r)),
      Paint()..color = const Color(0xFF2A1D47),
    );
    c.drawPath(
        Path()
          ..moveTo(x - r * 2.2, y - r * 1.46)
          ..lineTo(x + r * 2.2, y - r * 1.46)
          ..lineTo(x + r * 1.95, y - r * 1.78)
          ..lineTo(x - r * 1.95, y - r * 1.78)
          ..close(),
        Paint()..color = const Color(0xFF120A20));
    c.drawCircle(
      Offset(x, y),
      r + 0.5,
      _raya(const Color(0xFFE8DCFF).withValues(alpha: 0.25 + 0.3 * pulso), 2.4)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 2),
    );
    c.drawCircle(Offset(x, y), r + 0.5, _raya(const Color(0x99F2E9FF), 0.9));
  }

  // ---- Vegetación ----

  void _vSauce(Canvas c, double w, double h, double hz) {
    final double bx = w * 0.88, by = hz + 4;
    c.drawPath(
        Path()
          ..moveTo(bx, by)
          ..quadraticBezierTo(bx - w * 0.02, by - h * 0.2, bx - w * 0.06, by - h * 0.34),
        _raya(const Color(0xFF0C0718), w * 0.016));
    final double cx = bx - w * 0.06, cy = by - h * 0.34;
    for (int i = 0; i < 5; i++) {
      final double a = -math.pi + i * math.pi / 4;
      c.drawOval(
          Rect.fromCenter(
              center: Offset(cx + math.cos(a) * w * 0.07, cy + math.sin(a) * h * 0.04), width: w * 0.12, height: h * 0.10),
          Paint()..color = const Color(0xD924493D));
    }
    for (int i = 0; i < 18; i++) {
      final double s = i / 17;
      final double ox = cx + (s - 0.5) * w * 0.26;
      final double oy = cy + (s - 0.5).abs() * h * 0.06;
      final double sn = math.sin(i * 1.7);
      final double largo = h * (0.2 + 0.16 * sn * sn);
      final double viento = math.sin(t * _tau * 3 + i * 0.4) * w * 0.014 + w * 0.006;
      c.drawPath(
          Path()
            ..moveTo(ox, oy)
            ..quadraticBezierTo(ox + viento * 0.5, oy + largo * 0.6, ox + viento, oy + largo),
          _raya(i % 3 == 0 ? const Color(0xD94F8A70) : const Color(0xD92F5E4E), 2.2 - (i % 2) * 0.6));
      _punto(c, Offset(ox + viento, oy + largo), 1.4, const Color(0xCC6FA88C));
    }
  }

  // ---- Criaturas ----

  void _vAves(Canvas c, double w, double h, {required bool cuervo}) {
    for (int i = 0; i < 3; i++) {
      final double x = w * (0.40 + i * 0.13) + math.sin(t * _tau + i) * w * 0.03;
      final double y = h * (0.16 + (i % 2) * 0.07);
      final double s = w * (0.030 - i * 0.004);
      final double ala = math.sin(t * _tau * 24 + i * 1.7); // aleteo
      c.drawPath(
        Path()
          ..moveTo(x - s, y - s * 0.3 * ala)
          ..quadraticBezierTo(x - s * 0.4, y - s * (0.2 + 0.55 * ala), x, y - s * 0.15)
          ..quadraticBezierTo(x + s * 0.4, y - s * (0.2 + 0.55 * ala), x + s, y - s * 0.3 * ala),
        _raya((cuervo ? Colors.black : const Color(0xFF0A0518)).withValues(alpha: 0.88), w * (cuervo ? 0.007 : 0.005)),
      );
    }
  }

  void _vDragon(Canvas c, double w, double h) {
    const int n = 26;
    final double avance = (t * 3) % 1.4 - 0.2;
    final List<Offset> pts = <Offset>[
      for (int i = 0; i < n; i++)
        Offset((avance - i * 0.02) * w,
            h * 0.22 + math.sin((avance - i * 0.02) * _tau * 1.6 + t * _tau * 2) * h * 0.06),
    ];
    _glow(c, pts.first, h * 0.1, const Color(0xFF8FB6E8), 0.35);
    for (int i = n - 1; i >= 0; i--) {
      final double r = h * 0.034 * (1 - i / n * 0.75);
      _punto(c, pts[i], r, (i.isOdd ? const Color(0xFF5E86C8) : const Color(0xFF7FA6E2)).withValues(alpha: 0.9));
      if (i % 3 == 0) _punto(c, pts[i] + Offset(0, -r * 0.6), r * 0.35, const Color(0x99D9E8FF));
    }
    final Offset cab = pts.first;
    c.drawOval(Rect.fromCenter(center: cab + Offset(h * 0.02, 0), width: h * 0.07, height: h * 0.044),
        Paint()..color = const Color(0xFF9BC0F2));
    _punto(c, cab + Offset(h * 0.03, -h * 0.006), 1.4, const Color(0xFFFFE08A));
    c.drawPath(
        Path()
          ..moveTo(cab.dx + h * 0.05, cab.dy + 1)
          ..quadraticBezierTo(cab.dx + h * 0.08, cab.dy + h * 0.03, cab.dx + h * 0.06,
              cab.dy + h * 0.06 + math.sin(t * _tau * 8) * 2),
        _raya(const Color(0xB3D9E8FF), 0.8));
  }

  void _vMariposas(Canvas c, double w, double h, double hz) {
    const List<Color> cols = <Color>[
      Color(0xFFB79CFF),
      Color(0xFF8FE8D8),
      Color(0xFFF0A0CE),
      Color(0xFFFFD38A),
      Color(0xFFB79CFF),
    ];
    for (int i = 0; i < 5; i++) {
      final double x = w * (0.15 + i * 0.17) + math.sin(t * _tau * (2 + i % 2) + i) * w * 0.06;
      final double y = hz - h * (0.08 + 0.18 * ((i * 37) % 10) / 10) + math.cos(t * _tau * 3 + i * 2) * h * 0.04;
      final double aleteo = math.sin(t * _tau * 55 + i * 1.3).abs();
      final double tam = h * 0.03;
      _glow(c, Offset(x, y), tam * 3, cols[i], 0.25);
      final Paint ala = Paint()..color = cols[i].withValues(alpha: 0.85);
      for (final double s in <double>[-1, 1]) {
        _elipse(c, Offset(x + s * tam * 0.6 * aleteo, y - tam * 0.2), tam * aleteo + 0.4, tam * 0.8, s * 0.5, ala);
        _elipse(c, Offset(x + s * tam * 0.45 * aleteo, y + tam * 0.5), tam * 0.65 * aleteo + 0.3, tam * 0.5, -s * 0.4, ala);
      }
      c.drawLine(Offset(x, y - tam * 0.6), Offset(x, y + tam * 0.6), _raya(const Color(0xFF1A1226), 0.9));
    }
  }

  void _vGrullasPapel(Canvas c, double w, double h) {
    for (int i = 0; i < 4; i++) {
      final double x = (((t * 1.5 + i * 0.22) % 1.2) - 0.1) * w;
      final double y = h * (0.18 + 0.08 * (i % 2)) + math.sin(t * _tau * 5 + i) * h * 0.02;
      final double s = h * (0.045 - i * 0.004);
      final double ala = math.sin(t * _tau * 12 + i) * 0.35;
      final Color claro = i.isOdd ? const Color(0xFFF0A0AE) : const Color(0xFFF2EAFB);
      final Color sombra = i.isOdd ? const Color(0xFFD9808E) : const Color(0xFFCFC4E6);
      c.drawPath(
          Path()
            ..moveTo(x - s * 1.2, y)
            ..lineTo(x, y - s * 0.25)
            ..lineTo(x + s * 1.1, y - s * 0.6)
            ..lineTo(x + s * 0.2, y + s * 0.25)
            ..close(),
          Paint()..color = claro);
      c.drawPath(
          Path()
            ..moveTo(x - s * 0.3, y - s * 0.1)
            ..lineTo(x + s * 0.1, y - s * (1.2 + ala))
            ..lineTo(x + s * 0.45, y - s * 0.2)
            ..close(),
          Paint()..color = sombra);
      c.drawLine(Offset(x + s * 1.1, y - s * 0.6), Offset(x + s * 1.35, y - s * 0.45), _raya(claro, 1));
    }
  }

  void _vFenix(Canvas c, double w, double h) {
    const double periodo = 0.5; // unos 17 s
    final double u = (t / periodo) % 1.0;
    if (u > 0.45) return;
    final double p = u / 0.45;
    Offset en(double q) => Offset(-w * 0.15 + q * w * 1.3, h * 0.34 - math.sin(q * math.pi) * h * 0.16);
    for (int k = 14; k >= 0; k--) {
      final double q = math.max(0.0, p - k * 0.012);
      final double a = 1 - k / 15;
      _punto(c, en(q) + Offset(0, math.sin(t * _tau * 40 + k) * 2), 2 + k * 0.55,
          (k < 5 ? const Color(0xFFFFD36A) : const Color(0xFFFF7A3A)).withValues(alpha: 0.35 * a),
          blur: 2);
    }
    final Offset o = en(p);
    final double ala = math.sin(t * _tau * 30) * 0.6;
    _glow(c, o, h * 0.12, const Color(0xFFFFB45A), 0.45);
    _elipse(c, o, h * 0.035, h * 0.016, -0.2, Paint()..color = const Color(0xFFFFE0A0));
    for (final double s in <double>[-1, 1]) {
      c.drawPath(
          Path()
            ..moveTo(o.dx - h * 0.01, o.dy)
            ..quadraticBezierTo(o.dx - h * 0.03, o.dy - s * h * (0.06 + 0.04 * ala), o.dx - h * 0.09,
                o.dy - s * h * (0.05 + 0.05 * ala))
            ..quadraticBezierTo(o.dx - h * 0.04, o.dy - s * h * 0.01, o.dx - h * 0.01, o.dy),
          Paint()..color = const Color(0xFFFF8A3A));
    }
    _punto(c, o + Offset(h * 0.03, -h * 0.008), h * 0.012, const Color(0xFFFFF3C4));
  }

  void _vKitsune(Canvas c, double w, double h, double hz) {
    final double x = w * 0.66, y = hz - 2;
    c.drawOval(Rect.fromCenter(center: Offset(x, y + h * 0.012), width: w * 0.15, height: h * 0.07),
        Paint()..color = const Color(0xFF0D0918));
    // Nueve colas en abanico, detrás del cuerpo
    final Offset o = Offset(x - w * 0.012, y - h * 0.04);
    for (int i = 0; i < 9; i++) {
      final double ang = -math.pi * 0.98 + (i / 8) * math.pi * 0.62 + math.sin(t * _tau * 4 + i * 0.6) * 0.09;
      final double largo = h * (0.2 + 0.025 * math.sin(i * 2.1));
      final Offset fin = o + Offset(math.cos(ang), math.sin(ang)) * largo;
      final Offset medio = o + Offset(math.cos(ang + 0.45), math.sin(ang + 0.45)) * (largo * 0.55);
      c.drawPath(
          Path()
            ..moveTo(o.dx, o.dy)
            ..quadraticBezierTo(medio.dx, medio.dy, fin.dx, fin.dy),
          _raya(const Color(0xE6E9E2FA), h * 0.042));
      _punto(c, fin, h * 0.02, const Color(0xF2BFE6FF));
    }
    // Fuegos fatuos azules
    for (int i = 0; i < 3; i++) {
      final double a = t * _tau * 2 + i * _tau / 3;
      final Offset f = Offset(x + math.cos(a) * w * 0.1, y - h * 0.18 + math.sin(a) * h * 0.05);
      _glow(c, f, h * 0.05, const Color(0xFF8FD8FF), 0.45);
      _punto(c, f, h * 0.011, const Color(0xF2E0F6FF));
    }
    // Cuerpo sentado, cabeza con hocico y orejas
    final Paint blanco = Paint()..color = const Color(0xFFF7F3FF);
    _elipse(c, Offset(x + w * 0.012, y - h * 0.055), w * 0.028, h * 0.06, 0.15, blanco);
    final Offset cab = Offset(x + w * 0.026, y - h * 0.125);
    c.drawOval(Rect.fromCenter(center: cab, width: w * 0.036, height: h * 0.06), blanco);
    c.drawPath(
        Path()
          ..moveTo(cab.dx + w * 0.006, cab.dy - h * 0.005)
          ..lineTo(cab.dx + w * 0.04, cab.dy + h * 0.012)
          ..lineTo(cab.dx + w * 0.01, cab.dy + h * 0.022)
          ..close(),
        blanco);
    for (final double s in <double>[-1, 1]) {
      c.drawPath(
          Path()
            ..moveTo(cab.dx + s * w * 0.012 - w * 0.004, cab.dy - h * 0.018)
            ..lineTo(cab.dx + s * w * 0.008, cab.dy - h * 0.065)
            ..lineTo(cab.dx + s * w * 0.002 + w * 0.006, cab.dy - h * 0.02)
            ..close(),
          blanco);
    }
    c.drawLine(cab + Offset(w * 0.006, -h * 0.004), cab + Offset(w * 0.016, -h * 0.008), _raya(const Color(0xFFC2303F), 1.2));
    c.drawLine(Offset(x, y - h * 0.1), Offset(x + w * 0.028, y - h * 0.095), _raya(const Color(0xFFC2303F), 1.6));
  }

  void _vKoiDorado(Canvas c, double w, double h, double hz) {
    const double periodo = 0.18; // unos 6 s
    final double u = (t / periodo) % 1.0;
    final double x0 = w * 0.42, x1 = w * 0.60;
    void ondas(double cx, double edad) {
      for (int k = 0; k < 2; k++) {
        final double e = edad - k * 0.12;
        if (e < 0 || e > 1) continue;
        c.drawOval(
            Rect.fromCenter(
                center: Offset(cx, hz + h * 0.05), width: w * (0.02 + 0.12 * e), height: h * (0.012 + 0.04 * e)),
            _raya(const Color(0xFFF2D493).withValues(alpha: 0.45 * (1 - e)), 1));
      }
    }

    if (u < 0.35) {
      final double p = u / 0.35;
      final double x = x0 + (x1 - x0) * p;
      final double y = hz + h * 0.05 - math.sin(p * math.pi) * h * 0.22;
      final double ang = math.atan2(-math.cos(p * math.pi) * h * 0.22 * math.pi, x1 - x0);
      _glow(c, Offset(x, y), h * 0.09, const Color(0xFFF2D493), 0.4);
      c.save();
      c.translate(x, y);
      c.rotate(ang);
      c.drawOval(Rect.fromCenter(center: Offset.zero, width: h * 0.10, height: h * 0.04), Paint()..color = const Color(0xFFF2B544));
      c.drawPath(
          Path()
            ..moveTo(-h * 0.045, 0)
            ..lineTo(-h * 0.085, -h * 0.025 + math.sin(t * _tau * 60) * 2)
            ..lineTo(-h * 0.08, h * 0.022)
            ..close(),
          Paint()..color = const Color(0xFFFFE08A));
      _punto(c, Offset(h * 0.03, -h * 0.006), 1, const Color(0xFF3A2414));
      c.restore();
      if (p < 0.25) ondas(x0, p / 0.25 * 0.5);
    }
    if (u >= 0.3) ondas(x1, (u - 0.3) / 0.7);
    if (u < 0.15) ondas(x0, 0.5 + u / 0.15 * 0.5);
  }

  // ---- Clima ----

  void _vMomiji(Canvas c, double w, double h) {
    final math.Random rnd = math.Random(83);
    for (int i = 0; i < 18; i++) {
      final double s = rnd.nextDouble(), px = rnd.nextDouble();
      final double f = (t * (0.45 + s * 0.4) + s) % 1.0;
      final double x = w * px + math.sin(f * _tau * 1.5 + i) * w * 0.07;
      final double y = -10 + f * (h + 20);
      final double tam = 3.4 + s * 2.6;
      final Color col = (i % 3 == 0 ? const Color(0xFFF0A03C) : const Color(0xFFE0482E)).withValues(alpha: 0.8);
      c.save();
      c.translate(x, y);
      c.rotate(f * 9 + i);
      c.scale(1, 0.55 + 0.45 * math.sin(f * _tau * 2 + i).abs());
      final Path hoja = Path();
      for (int k = 0; k < 10; k++) {
        final double a = -math.pi / 2 + k * math.pi / 5;
        final double rr = k.isEven ? tam : tam * 0.55;
        if (k == 0) {
          hoja.moveTo(math.cos(a) * rr, math.sin(a) * rr);
        } else {
          hoja.lineTo(math.cos(a) * rr, math.sin(a) * rr);
        }
      }
      c.drawPath(hoja..close(), Paint()..color = col);
      c.drawLine(Offset.zero, Offset(0, tam * 1.25), _raya(col, 0.8));
      c.restore();
    }
  }

  void _vVentisca(Canvas c, double w, double h) {
    for (int i = 0; i < 3; i++) {
      final double f = (t * 3 + i / 3) % 1.0;
      c.drawRect(
        Rect.fromLTWH(-w * 0.5 + f * w * 2, h * (0.2 + i * 0.22), w * 0.5, h * 0.08),
        Paint()
          ..color = Colors.white.withValues(alpha: 0.05)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 10),
      );
    }
    final math.Random rnd = math.Random(91);
    for (int i = 0; i < 70; i++) {
      final double s = rnd.nextDouble(), px = rnd.nextDouble();
      final double f = (t * (5 + s * 4) + s) % 1.0;
      final double x = (px * 1.4 - 0.2) * w + f * w * 0.6 - w * 0.3;
      final double y = -6 + f * (h + 12);
      c.drawLine(Offset(x, y), Offset(x - 4 - s * 3, y - 1.5 - s), _raya(Colors.white.withValues(alpha: 0.35 + s * 0.35), 1 + s * 0.6));
    }
  }

  void _vBrasas(Canvas c, double w, double h) {
    final math.Random rnd = math.Random(101);
    for (int i = 0; i < 34; i++) {
      final double s = rnd.nextDouble(), px = rnd.nextDouble();
      final double f = (t * (1.2 + s * 1.2) + s) % 1.0;
      final double x = w * px + math.sin(f * _tau * 2 + i) * w * 0.03;
      final double y = h + 6 - f * (h + 12);
      final double vida = math.sin(f * math.pi);
      final double parp = 0.7 + 0.3 * math.sin(t * _tau * 50 + i * 1.9);
      _punto(c, Offset(x, y), 2.6 + s * 2, const Color(0xFFFF7A3A).withValues(alpha: 0.22 * vida * parp), blur: 2);
      _punto(c, Offset(x, y), 0.8 + s * 0.7,
          (s > 0.6 ? const Color(0xFFFFE08A) : const Color(0xFFFF9A4A)).withValues(alpha: 0.9 * vida * parp));
    }
  }

  void _vRayo(Canvas c, double w, double h) {
    if (math.sin(t * _tau * 3) <= 0.985) return;
    c.drawRect(Rect.fromLTWH(0, 0, w, h), Paint()..color = Colors.white.withValues(alpha: 0.12));
    final math.Random rnd = math.Random((t * 3).floor());
    double x = w * (0.2 + 0.6 * rnd.nextDouble()), y = 0;
    final Path rayo = Path()..moveTo(x, y);
    while (y < h * 0.62) {
      x += (rnd.nextDouble() - 0.5) * w * 0.08;
      y += h * (0.06 + rnd.nextDouble() * 0.06);
      rayo.lineTo(x, y);
    }
    c.drawPath(
        rayo,
        _raya(const Color(0xF2F2F6FF), 1.8)
          ..strokeJoin = StrokeJoin.round
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 0.6));
  }

  @override
  bool shouldRepaint(_LienzoPainter old) =>
      old.reloj != reloj || old.config != config;
}

// ---------------------------------------------------------------------------
// 29.4 EL TALLER
//
// Equipar y comprar en la misma pantalla, con la viñeta viva arriba: cada
// cambio se ve al instante sobre lo que ya tienes puesto. Probar antes de
// pagar evita el arrepentimiento, que es lo que mata una tienda.
// ---------------------------------------------------------------------------

class TallerVinetaScreen extends StatefulWidget {
  const TallerVinetaScreen({super.key, required this.usuario});

  final String usuario;

  @override
  State<TallerVinetaScreen> createState() => _TallerVinetaScreenState();
}

class _TallerVinetaScreenState extends State<TallerVinetaScreen> {
  CapaVineta _capa = CapaVineta.cielo;

  @override
  void initState() {
    super.initState();
    // Si la pieza lucida 24 h ya venció (o se compró), se cierra la prueba.
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted && AlmacenAnuncios.instancia.revisarPrueba(widget.usuario)) setState(() {});
    });
  }

  /// Pieza de la tienda que se está probando sin tenerla.
  String? _previaId;

  @override
  void dispose() {
    // Al salir del taller, la viñeta nueva pasa a tu perfil público.
    SesionTemplo.instancia.sincronizarIdentidad(widget.usuario);
    super.dispose();
  }

  /// Vista temporal: deja probar una pieza sin comprarla.
  Map<CapaVineta, String>? _previa;

  Map<CapaVineta, String> get _config =>
      _previa ?? MotorProgresion.instancia.de(widget.usuario).vineta;

  void _probar(String id) {
    final Map<CapaVineta, String> base = Map<CapaVineta, String>.from(
        MotorProgresion.instancia.de(widget.usuario).vineta);
    base[_capa] = id;
    setState(() {
      _previa = base;
      _previaId = id;
    });
  }

  void _equipar(String id) {
    MotorProgresion.instancia.colocarPieza(widget.usuario, _capa, id);
    NubeTemplo.instancia.marcarCambio();
    HapticFeedback.selectionClick();
    setState(() {
      _previa = null;
      _previaId = null;
    });
  }

  /// La viñeta actual con esta pieza puesta (para la miniatura).
  Map<CapaVineta, String> _conPieza(String id) =>
      Map<CapaVineta, String>.from(MotorProgresion.instancia.de(widget.usuario).vineta)..[_capa] = id;

  Future<void> _comprar(PiezaUnificada p) async {
    final MonedaTemplo m = MonedaTemplo.instancia;
    final int saldo = m.saldo(widget.usuario);

    if (saldo < p.precio) {
      ScaffoldMessenger.of(context)
        ..hideCurrentSnackBar()
        ..showSnackBar(
          SnackBar(
            behavior: SnackBarBehavior.floating,
            backgroundColor: TempleColors.superficieAlta,
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(TempleRadius.campo),
              side: const BorderSide(color: TempleColors.borde),
            ),
            content: Text(
              'Te faltan ${p.precio - saldo} mon. Entrena y vuelve.',
              style:
                  const TextStyle(color: TempleColors.texto, fontSize: 13),
            ),
          ),
        );
      return;
    }

    final bool? ok = await showDialog<bool>(
      context: context,
      builder: (BuildContext c) => AlertDialog(
        backgroundColor: TempleColors.superficieAlta,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
        ),
        title: Text(p.nombre,
            style: const TextStyle(color: TempleColors.blancoLuna)),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: <Widget>[
            Text(p.detalle,
                style: const TextStyle(
                    color: TempleColors.textoSuave, fontSize: 13, height: 1.5)),
            const SizedBox(height: 16),
            Row(
              children: <Widget>[
                const IconoMon(size: 18),
                const SizedBox(width: 8),
                Text(
                  '${p.precio}',
                  style: const TextStyle(
                    color: TempleColors.dorado,
                    fontSize: 17,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                const Spacer(),
                Text('Te quedan ${saldo - p.precio}',
                    style: const TextStyle(
                        color: TempleColors.textoTenue, fontSize: 11.5)),
              ],
            ),
          ],
        ),
        actions: <Widget>[
          TextButton(
            onPressed: () => Navigator.of(c).pop(false),
            child: const Text('Ahora no'),
          ),
          TextButton(
            onPressed: () => Navigator.of(c).pop(true),
            child: const Text('Comprar',
                style: TextStyle(
                    color: TempleColors.dorado, fontWeight: FontWeight.w600)),
          ),
        ],
      ),
    );

    if (ok != true || !mounted) return;

    final bool pagado =
        m.gastar(widget.usuario, p.precio, 'Pieza: ${p.nombre}');
    if (!pagado) return;

    MotorProgresion.instancia.de(widget.usuario).piezas.add(p.id);
    MotorProgresion.instancia.colocarPieza(widget.usuario, _capa, p.id);
    AlmacenAnuncios.instancia.revisarPrueba(widget.usuario);
    NubeTemplo.instancia.marcarCambio();
    setState(() {
      _previa = null;
      _previaId = null;
    });
    await mostrarCelebracion(
      context,
      titulo: 'Pieza nueva',
      sonido: SonidoTemplo.compra,
      nombre: p.nombre,
      detalle: p.detalle,
      color: p.rareza?.color ?? TempleColors.violetaClaro,
      vista: MiniVineta(
        config: MotorProgresion.instancia.de(widget.usuario).vineta,
        ancho: 250,
        alto: 136,
        animada: true,
      ),
      boton: 'Listo',
    );
  }

  @override
  Widget build(BuildContext context) {
    final EstadoProgreso prog = MotorProgresion.instancia.de(widget.usuario);
    final List<PiezaUnificada> piezas = PiezaUnificada.deCapa(_capa);

    final List<PiezaUnificada> tengo = piezas
        .where((PiezaUnificada p) => prog.piezas.contains(p.id))
        .toList();
    final List<PiezaUnificada> tienda = piezas
        .where((PiezaUnificada p) =>
            !prog.piezas.contains(p.id) && p.deTienda)
        .toList()
      ..sort((PiezaUnificada a, PiezaUnificada b) =>
          a.precio.compareTo(b.precio));
    final List<PiezaUnificada> logros = piezas
        .where((PiezaUnificada p) =>
            !prog.piezas.contains(p.id) && !p.deTienda)
        .toList();
    final List<PiezaPase> temporada = PiezasPase.deCapa(_capa);

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: SafeArea(
          child: Column(
            children: <Widget>[
              // Cabecera.
              Padding(
                padding: const EdgeInsets.fromLTRB(8, 4, 16, 4),
                child: Row(
                  children: <Widget>[
                    IconButton(
                      onPressed: () => Navigator.of(context).maybePop(),
                      icon: const Icon(Icons.arrow_back_rounded,
                          color: TempleColors.textoSuave),
                    ),
                    const Expanded(
                      child: Text(
                        'El Taller',
                        style: TextStyle(
                          fontSize: 18,
                          fontWeight: FontWeight.w600,
                          color: TempleColors.blancoLuna,
                        ),
                      ),
                    ),
                    SaldoMon(usuario: widget.usuario),
                    const BotonPase(),
                  ],
                ),
              ),

              // Vista previa.
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 16),
                child: ClipRRect(
                  borderRadius:
                      BorderRadius.circular(TempleRadius.tarjeta),
                  child: AnimatedSwitcher(
                    duration: const Duration(milliseconds: 450),
                    switchInCurve: Curves.easeOut,
                    child: VinetaPerfil(
                      key: ValueKey<String>(
                          _config.entries.map((MapEntry<CapaVineta, String> e) => '${e.key.name}:${e.value}').join('|')),
                      config: _config,
                      altura: 176,
                    ),
                  ),
                ),
              ),

              if (_previa != null)
                Padding(
                  padding: const EdgeInsets.only(top: 10),
                  child: Text(
                    'Estás probando una pieza que no tienes.',
                    style: TextStyle(
                        fontSize: 11.5, color: TempleColors.alertaSuave),
                  ),
                ),
              BarraPruebaPieza(
                usuario: widget.usuario,
                probando: _previa != null &&
                        _previaId != null &&
                        tienda.any((PiezaUnificada p) => p.id == _previaId)
                    ? (capa: _capa, id: _previaId!)
                    : null,
                onCambio: () => setState(() {
                  _previa = null;
                  _previaId = null;
                }),
              ),

              const SizedBox(height: 14),

              // Capas.
              SizedBox(
                height: 38,
                child: ListView(
                  scrollDirection: Axis.horizontal,
                  padding: const EdgeInsets.symmetric(horizontal: 16),
                  children: CapaVineta.values.map((CapaVineta c) {
                    final bool act = c == _capa;
                    return Padding(
                      padding: const EdgeInsets.only(right: 8),
                      child: GestureDetector(
                        onTap: () => setState(() {
                          _capa = c;
                          _previa = null;
                          _previaId = null;
                        }),
                        child: AnimatedContainer(
                          duration: TempleMotion.rapido,
                          padding: const EdgeInsets.symmetric(
                              horizontal: 14, vertical: 9),
                          decoration: BoxDecoration(
                            color: act
                                ? TempleColors.violeta
                                    .withValues(alpha: 0.18)
                                : TempleColors.superficie,
                            borderRadius: BorderRadius.circular(999),
                            border: Border.all(
                                color: act
                                    ? TempleColors.violeta
                                    : TempleColors.borde),
                          ),
                          child: Text(
                            c.etiqueta,
                            style: TextStyle(
                              fontSize: 12.5,
                              fontWeight:
                                  act ? FontWeight.w600 : FontWeight.w400,
                              color: act
                                  ? TempleColors.violetaClaro
                                  : TempleColors.textoSuave,
                            ),
                          ),
                        ),
                      ),
                    );
                  }).toList(),
                ),
              ),
              const SizedBox(height: 6),

              Expanded(
                child: ListView(
                  padding: const EdgeInsets.fromLTRB(16, 10, 16, 30),
                  children: <Widget>[
                    if (OfrendaPase.disponible(widget.usuario)) ...<Widget>[
                      TempleCard(
                        destacada: true,
                        onTap: () async {
                          if (!OfrendaPase.cobrar(widget.usuario)) return;
                          await mostrarCelebracion(
                            context,
                            titulo: 'Ofrenda del mes',
                            sonido: SonidoTemplo.mon,
                            nombre: '+${LimitesPase.monOfrenda} mon',
                            detalle: 'Gracias por sostener el templo.',
                            color: const Color(0xFFE8B65A),
                            vista: const IconoMon(size: 72),
                            boton: 'Al Taller',
                          );
                          if (mounted) setState(() {});
                        },
                        child: const Row(
                          children: <Widget>[
                            EmblemaPase(size: 34),
                            SizedBox(width: 12),
                            Expanded(
                              child: Text('Tu ofrenda del mes te espera: 300 mon para el Taller.',
                                  style: TextStyle(fontSize: 13, color: TempleColors.texto)),
                            ),
                            Icon(Icons.redeem_rounded, color: Color(0xFFF2D493)),
                          ],
                        ),
                      ),
                      const SizedBox(height: 14),
                    ],
                    TarjetaAnunciosTaller(usuario: widget.usuario, onMon: () => setState(() {})),
                    if (temporada.isNotEmpty) ...<Widget>[
                      const EtiquetaSeccion(PiezasPase.temporada, accion: ChipPase()),
                      for (final PiezaPase p in temporada)
                        FilaPiezaPase(
                          pieza: p,
                          vista: _conPieza(p.id),
                          puesta: _config[_capa] == p.id,
                          onTap: () {
                            if (PaseTemplo.instancia.activo) {
                              _equipar(p.id);
                            } else {
                              _probar(p.id);
                              mostrarMuroPase(
                                context,
                                titulo: p.nombre,
                                texto: '${p.descripcion} Es de la temporada del Pase: la estás viendo en tu viñeta.',
                                ventajas: const <String>[
                                  'Las 4 piezas animadas de la temporada',
                                  '300 mon cada mes para el Taller',
                                  'Marcos exclusivos para tu sello',
                                ],
                                icono: Icons.brush_outlined,
                              );
                            }
                          },
                        ),
                      const SizedBox(height: 18),
                    ],
                    if (tengo.isNotEmpty) ...<Widget>[
                      const EtiquetaSeccion('Tuyas'),
                      ...tengo.map((PiezaUnificada p) => _FilaPieza(
                            pieza: p,
                            vista: _conPieza(p.id),
                            estado: _EstadoPieza.propia,
                            puesta: _config[_capa] == p.id,
                            onTap: () => _equipar(p.id),
                          )),
                      const SizedBox(height: 18),
                    ],
                    if (tienda.isNotEmpty) ...<Widget>[
                      const EtiquetaSeccion('En la tienda'),
                      ...tienda.map((PiezaUnificada p) => _FilaPieza(
                            pieza: p,
                            vista: _conPieza(p.id),
                            estado: _EstadoPieza.comprable,
                            puesta: _config[_capa] == p.id,
                            onTap: () => _probar(p.id),
                            onComprar: () => _comprar(p),
                          )),
                      const SizedBox(height: 18),
                    ],
                    if (logros.isNotEmpty) ...<Widget>[
                      const EtiquetaSeccion('Se ganan entrenando'),
                      ...logros.map((PiezaUnificada p) => _FilaPieza(
                            pieza: p,
                            vista: _conPieza(p.id),
                            estado: _EstadoPieza.porLogro,
                            puesta: false,
                            onTap: null,
                          )),
                    ],
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

enum _EstadoPieza { propia, comprable, porLogro }

class _FilaPieza extends StatelessWidget {
  const _FilaPieza({
    required this.pieza,
    required this.vista,
    required this.estado,
    required this.puesta,
    required this.onTap,
    this.onComprar,
  });

  final PiezaUnificada pieza;
  final Map<CapaVineta, String> vista;
  final _EstadoPieza estado;
  final bool puesta;
  final VoidCallback? onTap;
  final VoidCallback? onComprar;

  @override
  Widget build(BuildContext context) {
    final Color acento = pieza.rareza?.color ?? TempleColors.violetaClaro;

    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: TempleCard(
        destacada: puesta,
        onTap: onTap,
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 13),
        child: Row(
          children: <Widget>[
            // Miniatura de la viñeta con esta pieza, y su estado encima.
            Stack(
              clipBehavior: Clip.none,
              children: <Widget>[
                Opacity(
                  opacity: estado == _EstadoPieza.porLogro ? 0.45 : 1,
                  child: MiniVineta(config: vista, ancho: 64, alto: 40),
                ),
                Positioned(
                  right: -5,
                  bottom: -5,
                  child: Container(
                    width: 20,
                    height: 20,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: TempleColors.grafito,
                      border: Border.all(color: TempleColors.borde),
                    ),
                    child: Icon(
                      switch (estado) {
                        _EstadoPieza.propia => puesta ? Icons.check_rounded : Icons.circle_outlined,
                        _EstadoPieza.comprable => Icons.storefront_rounded,
                        _EstadoPieza.porLogro => Icons.lock_outline_rounded,
                      },
                      size: 12,
                      color: estado == _EstadoPieza.porLogro
                          ? TempleColors.textoTenue
                          : puesta
                              ? TempleColors.exito
                              : acento,
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(width: 13),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Row(
                    children: <Widget>[
                      Flexible(
                        child: Text(
                          pieza.nombre,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                            fontSize: 14,
                            fontWeight: FontWeight.w600,
                            color: estado == _EstadoPieza.porLogro
                                ? TempleColors.textoSuave
                                : TempleColors.blancoLuna,
                          ),
                        ),
                      ),
                      if (piezasAnimadas.contains(pieza.id)) ...<Widget>[
                        const SizedBox(width: 6),
                        const Icon(Icons.auto_awesome_rounded, size: 13, color: TempleColors.violetaClaro),
                      ],
                      if (pieza.rareza != null &&
                          pieza.deTienda) ...<Widget>[
                        const SizedBox(width: 8),
                        Container(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 7, vertical: 2),
                          decoration: BoxDecoration(
                            color: acento.withValues(alpha: 0.14),
                            borderRadius: BorderRadius.circular(999),
                          ),
                          child: Text(
                            pieza.rareza!.etiqueta,
                            style: TextStyle(fontSize: 9.5, color: acento),
                          ),
                        ),
                      ],
                    ],
                  ),
                  const SizedBox(height: 3),
                  Text(
                    pieza.detalle,
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      fontSize: 11.5,
                      height: 1.35,
                      color: estado == _EstadoPieza.porLogro
                          ? TempleColors.alertaSuave
                          : TempleColors.textoTenue,
                    ),
                  ),
                ],
              ),
            ),
            if (estado == _EstadoPieza.comprable) ...<Widget>[
              const SizedBox(width: 10),
              GestureDetector(
                onTap: onComprar,
                child: Container(
                  padding: const EdgeInsets.symmetric(
                      horizontal: 11, vertical: 8),
                  decoration: BoxDecoration(
                    color: TempleColors.dorado.withValues(alpha: 0.12),
                    borderRadius: BorderRadius.circular(999),
                    border: Border.all(
                        color: TempleColors.dorado.withValues(alpha: 0.35)),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: <Widget>[
                      const IconoMon(size: 14),
                      const SizedBox(width: 6),
                      Text(
                        '${pieza.precio}',
                        style: const TextStyle(
                          fontSize: 12.5,
                          fontWeight: FontWeight.w700,
                          color: TempleColors.dorado,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }
}

// ---------------------------------------------------------------------------
// 29.5 REDACTOR DE MENSAJES
//
// Cada aviso tiene varias redacciones por voz, y el espíritu añade su cierre.
// Con 12 espíritus × 3 voces × varias variantes, dos usuarios no leen lo
// mismo casi nunca — y el mismo usuario tampoco se repite.
// ---------------------------------------------------------------------------

enum TipoMensaje {
  bienvenida,
  horaDeEntrenar,
  agua,
  cierreDelDia,
  rachaEnRiesgo,
  rachaSubida,
  recordRoto,
  grupoEnDeuda,
  regreso,
  subidaNivel,
  piezaNueva,
  tituloNuevo,
  claseNueva,
  monGanados,
  descanso,
  cuerpo,
  semanaCerrada,

  /// Sus propias palabras: lo que escribió que quería lograr (sección 46).
  meta,
}

enum CategoriaMensaje { entrenamiento, habito, logro, cuerpo, templo }

extension DatosCategoria on CategoriaMensaje {
  String get etiqueta {
    switch (this) {
      case CategoriaMensaje.entrenamiento:
        return 'Entrenamiento';
      case CategoriaMensaje.habito:
        return 'Hábitos';
      case CategoriaMensaje.logro:
        return 'Logros';
      case CategoriaMensaje.cuerpo:
        return 'Tu cuerpo';
      case CategoriaMensaje.templo:
        return 'El templo';
    }
  }

  TempleGlyph get glifo {
    switch (this) {
      case CategoriaMensaje.entrenamiento:
        return TempleGlyph.mancuerna;
      case CategoriaMensaje.habito:
        return TempleGlyph.gota;
      case CategoriaMensaje.logro:
        return TempleGlyph.medalla;
      case CategoriaMensaje.cuerpo:
        return TempleGlyph.loto;
      case CategoriaMensaje.templo:
        return TempleGlyph.torii;
    }
  }
}

class MensajeTemplo {
  MensajeTemplo({
    required this.id,
    required this.tipo,
    required this.categoria,
    required this.titulo,
    required this.cuerpo,
    required this.fecha,
    this.firma,
    this.dorado = false,
    this.leido = false,
  });

  final String id;
  final TipoMensaje tipo;
  final CategoriaMensaje categoria;
  final String titulo;
  final String cuerpo;
  final DateTime fecha;
  final String? firma;

  /// Los mensajes de logro se sellan en dorado.
  final bool dorado;
  bool leido;

  String get textoCompleto => firma == null ? cuerpo : '$cuerpo\n\n— $firma';

  Map<String, dynamic> toMap() => <String, dynamic>{
        'id': id,
        'tipo': tipo.name,
        'categoria': categoria.name,
        'titulo': titulo,
        'cuerpo': cuerpo,
        'fecha': fecha.toIso8601String(),
        'firma': firma,
        'dorado': dorado,
        'leido': leido,
      };
}

