// ---------------------------------------------------------------------------
// 30.1 MODELO DEL CICLO
// ---------------------------------------------------------------------------

/// Limitaciones que filtran ejercicios. No es un adorno: sin esto el
/// generador te propondría sentadilla con la rodilla mal.
enum Limitacion { ninguna, hombro, rodilla, espalda, muneca, tobillo }

extension DatosLimitacion on Limitacion {
  String get etiqueta {
    switch (this) {
      case Limitacion.ninguna:
        return 'Ninguna';
      case Limitacion.hombro:
        return 'Hombro';
      case Limitacion.rodilla:
        return 'Rodilla';
      case Limitacion.espalda:
        return 'Espalda baja';
      case Limitacion.muneca:
        return 'Muñeca';
      case Limitacion.tobillo:
        return 'Tobillo';
    }
  }

  String get nota {
    switch (this) {
      case Limitacion.ninguna:
        return 'Sin restricciones';
      case Limitacion.hombro:
        return 'Fuera press por encima de la cabeza y fondos';
      case Limitacion.rodilla:
        return 'Fuera sentadilla, prensa y zancadas';
      case Limitacion.espalda:
        return 'Fuera peso muerto y remo con barra';
      case Limitacion.muneca:
        return 'Fuera curl de muñeca y press francés';
      case Limitacion.tobillo:
        return 'Fuera zancadas y elevación de talones';
    }
  }

  Set<String> get excluidos {
    switch (this) {
      case Limitacion.ninguna:
        return <String>{};
      case Limitacion.hombro:
        return <String>{
          'press_militar',
          'elevaciones_laterales',
          'pajaro',
          'fondos',
          'fondos_silla',
          'flexiones_pica',
          'press_banda',
          'elevaciones_botellas',
        };
      case Limitacion.rodilla:
        return <String>{
          'sentadilla', 'prensa', 'zancadas', 'zancada_atras', 'sentadilla_bulgara',
          'sentadilla_salto', 'subida_escalon', 'sentadilla_pared',
        };
      case Limitacion.espalda:
        return <String>{'peso_muerto', 'remo_barra', 'rueda_abdominal', 'superman', 'remo_garrafa'};
      case Limitacion.muneca:
        return <String>{
          'curl_muneca', 'press_frances', 'plancha', 'curl_muneca_garrafa',
          'flexiones_declinadas', 'flexiones_pica', 'escaladores',
        };
      case Limitacion.tobillo:
        return <String>{'zancadas', 'elevacion_talones', 'saltitos', 'saltos_tijera', 'sentadilla_salto'};
    }
  }
}

/// Lo que el usuario responde al entrar al Taller.
class RespuestasCiclo {
  const RespuestasCiclo({
    required this.prioridad,
    required this.semanas,
    required this.limitacion,
    required this.material,
  });

  /// Null = repartir parejo entre todos los grupos.
  final GrupoMuscular? prioridad;
  final int semanas;
  final Limitacion limitacion;

  /// 'gimnasio', 'casa', 'aire', 'mixto'
  final String material;
}

class DiaCiclo {
  const DiaCiclo({
    required this.nombre,
    required this.grupos,
    required this.ejercicios,
  });

  final String nombre;
  final List<GrupoMuscular> grupos;
  final List<EjercicioPlan> ejercicios;

  int get series =>
      ejercicios.fold<int>(0, (int a, EjercicioPlan e) => a + e.series);
  int get minutos => (series * 3.2).round().clamp(20, 120);

  String get resumen => grupos.map((GrupoMuscular g) => g.etiqueta).join(' · ');

  /// Convierte el día en una sesión lista para registrar.
  PlanSesion aPlan(String razon) => PlanSesion(
        nombre: nombre,
        grupos: grupos,
        ejercicios: ejercicios,
        minutos: minutos,
        razon: razon,
      );
}

class SemanaCiclo {
  const SemanaCiclo({
    required this.numero,
    required this.dias,
    required this.factorCarga,
    required this.titulo,
    required this.nota,
    required this.esDescarga,
  });

  final int numero;
  final List<DiaCiclo> dias;

  /// Multiplicador sobre el peso base.
  final double factorCarga;
  final String titulo;
  final String nota;
  final bool esDescarga;
}

/// Un cambio que el sistema hizo solo. Se enseña al usuario: una rutina que
/// se modifica en secreto se siente rota, no inteligente.
class AjusteCiclo {
  const AjusteCiclo({
    required this.fecha,
    required this.titulo,
    required this.motivo,
  });

  final DateTime fecha;
  final String titulo;
  final String motivo;
}

class CicloEntrenamiento {
  CicloEntrenamiento({
    required this.creado,
    required this.respuestas,
    required this.semanas,
  });

  final DateTime creado;
  final RespuestasCiclo respuestas;
  List<SemanaCiclo> semanas;
  final List<AjusteCiclo> ajustes = <AjusteCiclo>[];

  /// Semana en curso, 1-indexada, calculada desde la fecha de creación.
  int get semanaActual {
    final int transcurridas =
        DateTime.now().difference(lunesDe(creado)).inDays ~/ 7;
    return (transcurridas + 1).clamp(1, semanas.length);
  }

  SemanaCiclo get semana => semanas[semanaActual - 1];
  bool get terminado =>
      DateTime.now().difference(lunesDe(creado)).inDays ~/ 7 >=
      semanas.length;

  double get progreso => (semanaActual / semanas.length).clamp(0.0, 1.0);
}

// ---------------------------------------------------------------------------
// 30.2 GENERADOR DEL CICLO
//
// No genera «la sesión de hoy» sino un ciclo entero con progresión de cargas.
// La semana de descarga NO es opcional ni es un premio: es la que hace que
// las tres anteriores sirvan de algo.
// ---------------------------------------------------------------------------

class GeneradorCiclo {
  const GeneradorCiclo._();

  static const Map<String, List<GrupoMuscular>> _divisiones =
      <String, List<GrupoMuscular>>{
    'Empuje': <GrupoMuscular>[
      GrupoMuscular.pecho,
      GrupoMuscular.hombros,
      GrupoMuscular.triceps,
    ],
    'Tirón': <GrupoMuscular>[
      GrupoMuscular.espalda,
      GrupoMuscular.biceps,
      GrupoMuscular.antebrazos,
    ],
    'Pierna': <GrupoMuscular>[
      GrupoMuscular.piernas,
      GrupoMuscular.pantorrillas,
      GrupoMuscular.abdomen,
    ],
    'Cuerpo completo': <GrupoMuscular>[
      GrupoMuscular.piernas,
      GrupoMuscular.espalda,
      GrupoMuscular.pecho,
      GrupoMuscular.abdomen,
    ],
  };

  static List<Equipo> _equipos(String material) {
    switch (material) {
      case 'casa':
        return <Equipo>[
          Equipo.pesoCorporal,
          Equipo.mancuerna,
          Equipo.banda,
          Equipo.kettlebell,
          Equipo.casero,
        ];
      case 'aire':
        return <Equipo>[Equipo.pesoCorporal, Equipo.banda];
      default:
        return Equipo.values.where((Equipo e) => e != Equipo.casero).toList();
    }
  }

  static int _reps(String objetivo) {
    switch (objetivo) {
      case 'fuerza':
        return 5;
      case 'grasa':
        return 14;
      case 'salud':
        return 12;
      default:
        return 10;
    }
  }

  static int _seriesBase(String experiencia) {
    switch (experiencia) {
      case 'novato':
        return 3;
      case 'avanzado':
        return 4;
      case 'medio':
        return 4;
      default:
        return 3;
    }
  }

  static CicloEntrenamiento generar({
    required String usuario,
    required RespuestasCiclo r,
  }) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final Map<String, String> asc = a.de(usuario).ascenso;
    final PerfilEntrenamiento perfil = a.perfil(usuario);
    final double diasSemana = a.diasObjetivo(usuario);

    // 1. División según los días que puede sostener.
    final List<String> plantilla;
    if (diasSemana <= 2) {
      plantilla = <String>['Cuerpo completo', 'Cuerpo completo'];
    } else if (diasSemana <= 4) {
      plantilla = <String>['Empuje', 'Tirón', 'Pierna'];
    } else if (diasSemana <= 5) {
      plantilla = <String>['Empuje', 'Tirón', 'Pierna', 'Empuje', 'Tirón'];
    } else {
      plantilla = <String>[
        'Empuje',
        'Tirón',
        'Pierna',
        'Empuje',
        'Tirón',
        'Pierna',
      ];
    }

    final List<Equipo> equipos = _equipos(r.material);
    final Set<String> vetados = <String>{
      ...r.limitacion.excluidos,
      ...perfil.ejerciciosEvitados,
    };
    final int reps = _reps(asc['objetivo'] ?? 'musculo');
    final int series = _seriesBase(asc['experiencia'] ?? 'inicial');

    // 2. Construir cada día.
    List<DiaCiclo> construirDias() {
      final List<DiaCiclo> dias = <DiaCiclo>[];

      for (final String nombre in plantilla) {
        final List<GrupoMuscular> grupos = _divisiones[nombre]!;

        List<Ejercicio> candidatos = catalogoEjercicios
            .where((Ejercicio e) =>
                equipos.contains(e.equipo) &&
                grupos.contains(e.grupoPrincipal) &&
                !vetados.contains(e.id))
            .toList();

        // Si el filtro deja el día vacío, relajamos el material antes que
        // devolver una sesión sin ejercicios.
        if (candidatos.isEmpty) {
          candidatos = catalogoEjercicios
              .where((Ejercicio e) =>
                  grupos.contains(e.grupoPrincipal) &&
                  !r.limitacion.excluidos.contains(e.id))
              .toList();
        }

        // Compuestos primero; y si hay grupo prioritario, ese delante.
        candidatos.sort((Ejercicio x, Ejercicio y) {
          if (r.prioridad != null) {
            final bool px = x.grupoPrincipal == r.prioridad;
            final bool py = y.grupoPrincipal == r.prioridad;
            if (px != py) return px ? -1 : 1;
          }
          if (x.compuesto != y.compuesto) return x.compuesto ? -1 : 1;
          return 0;
        });

        // Cubrir todos los grupos del bloque antes de repetir.
        final List<Ejercicio> elegidos = <Ejercicio>[];
        for (final GrupoMuscular g in grupos) {
          for (final Ejercicio c in candidatos) {
            if (c.grupoPrincipal == g && !elegidos.contains(c)) {
              elegidos.add(c);
              break;
            }
          }
        }
        for (final Ejercicio c in candidatos) {
          if (elegidos.length >= 6) break;
          if (!elegidos.contains(c)) elegidos.add(c);
        }

        dias.add(DiaCiclo(
          nombre: nombre,
          grupos: grupos.take(3).toList(),
          ejercicios: <EjercicioPlan>[
            for (final Ejercicio e in elegidos)
              EjercicioPlan(
                ejercicioId: e.id,
                // Al grupo prioritario le damos una serie más.
                series: (e.grupoPrincipal == r.prioridad
                        ? series + 1
                        : e.compuesto
                            ? series
                            : series - 1)
                    .clamp(2, 6),
                repsObjetivo: e.porTiempo
                    ? segundosAguante(a.de(usuario).ascenso['experiencia'])
                    : (e.compuesto ? reps : reps + 2),
                pesoSugerido: a.ultimaSerieDe(usuario, e.id)?.peso,
              ),
          ],
        ));
      }
      return dias;
    }

    // 3. Progresión por semanas. Cada cuarta semana es de descarga.
    final List<SemanaCiclo> semanas = <SemanaCiclo>[];
    for (int i = 1; i <= r.semanas; i++) {
      final bool descarga = i % 4 == 0;
      final int enBloque = ((i - 1) % 4) + 1;

      final double factor;
      final String titulo;
      final String nota;

      if (descarga) {
        factor = 0.65;
        titulo = 'La semana del agua';
        nota =
            'Baja la carga a propósito. El músculo no crece entrenando: crece '
            'cuando le dejas. Esta semana es la que hace que las tres '
            'anteriores hayan servido de algo.';
      } else if (enBloque == 1) {
        factor = 1.0;
        titulo = 'Asentar';
        nota =
            'Semana de referencia. Registra bien los pesos: todo lo que viene '
            'después se calcula desde aquí.';
      } else if (enBloque == 2) {
        factor = 1.025;
        titulo = 'Empujar';
        nota =
            'Sube un poco el peso o una repetición más por serie. Poco. La '
            'prisa aquí se paga en tres semanas.';
      } else {
        factor = 1.05;
        titulo = 'Romper';
        nota =
            'La semana dura del bloque. Si hay un récord que intentar, es '
            'ahora y en el primer ejercicio del día.';
      }

      semanas.add(SemanaCiclo(
        numero: i,
        dias: construirDias(),
        factorCarga: factor,
        titulo: titulo,
        nota: nota,
        esDescarga: descarga,
      ));
    }

    return CicloEntrenamiento(
      creado: DateTime.now(),
      respuestas: r,
      semanas: semanas,
    );
  }
}

// ---------------------------------------------------------------------------
// 30.3 ALMACÉN Y ADAPTACIÓN
//
// El ciclo se revisa solo cada semana con lo que de verdad hiciste, y cada
// cambio queda anotado con su motivo.
// ---------------------------------------------------------------------------

class AlmacenCiclos {
  AlmacenCiclos._();
  static final AlmacenCiclos instancia = AlmacenCiclos._();

  final Map<String, CicloEntrenamiento> _ciclos =
      <String, CicloEntrenamiento>{};

  CicloEntrenamiento? de(String usuario) => _ciclos[usuario];

  void guardar(String usuario, CicloEntrenamiento c) =>
      _ciclos[usuario] = c;

  void borrar(String usuario) => _ciclos.remove(usuario);

  /// Ajustes automáticos. Se llama al abrir el Camino.
  void revisar(String usuario) {
    final CicloEntrenamiento? c = _ciclos[usuario];
    if (c == null) return;

    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final PerfilEntrenamiento p = a.perfil(usuario);
    if (p.sesionesTotales < 3) return;

    // No repetir el mismo ajuste dos veces en la misma semana.
    bool yaEstaSemana(String titulo) => c.ajustes.any((AjusteCiclo x) =>
        x.titulo == titulo &&
        DateTime.now().difference(x.fecha).inDays < 7);

    // 1. Abandonas sesiones: el plan es más largo que tu tiempo real.
    if (p.tasaAbandono > 0.3 && !yaEstaSemana('Sesiones más cortas')) {
      for (final SemanaCiclo s in c.semanas) {
        for (final DiaCiclo d in s.dias) {
          if (d.ejercicios.length > 4) {
            d.ejercicios.removeRange(4, d.ejercicios.length);
          }
        }
      }
      c.ajustes.add(AjusteCiclo(
        fecha: DateTime.now(),
        titulo: 'Sesiones más cortas',
        motivo:
            'Has dejado a medias ${(p.tasaAbandono * 100).round()}% de tus '
            'sesiones. El plan era más largo que tu tiempo real, así que '
            'ahora son cuatro ejercicios por día.',
      ));
    }

    // 2. Ejercicios que siempre saltas: se sustituyen por otro del grupo.
    for (final String evitado in p.ejerciciosEvitados) {
      final Ejercicio? viejo = ejercicioPorId(evitado);
      if (viejo == null) continue;
      if (yaEstaSemana('Cambio de ejercicio')) break;

      final Ejercicio? nuevo = catalogoEjercicios.firstWhereOrNullTemplo(
        (Ejercicio e) =>
            e.grupoPrincipal == viejo.grupoPrincipal &&
            e.id != viejo.id &&
            !c.respuestas.limitacion.excluidos.contains(e.id),
      );
      if (nuevo == null) continue;

      bool cambiado = false;
      for (final SemanaCiclo s in c.semanas) {
        for (final DiaCiclo d in s.dias) {
          for (int i = 0; i < d.ejercicios.length; i++) {
            if (d.ejercicios[i].ejercicioId == evitado) {
              d.ejercicios[i] = EjercicioPlan(
                ejercicioId: nuevo.id,
                series: d.ejercicios[i].series,
                repsObjetivo: d.ejercicios[i].repsObjetivo,
                pesoSugerido: a.ultimaSerieDe(usuario, nuevo.id)?.peso,
              );
              cambiado = true;
            }
          }
        }
      }

      if (cambiado) {
        c.ajustes.add(AjusteCiclo(
          fecha: DateTime.now(),
          titulo: 'Cambio de ejercicio',
          motivo:
              '${viejo.nombre} estaba en tu plan y lo saltabas una y otra '
              'vez. Lo he cambiado por ${nuevo.nombre}, que trabaja lo '
              'mismo. Si tampoco te convence, dímelo.',
        ));
        break;
      }
    }

    // 3. El cuerpo pide freno: se suaviza la semana en curso.
    if (VigilanciaCuerpo.debeSuavizarRutina(usuario) &&
        !yaEstaSemana('Semana suavizada')) {
      final SemanaCiclo actual = c.semana;
      final int i = actual.numero - 1;
      c.semanas[i] = SemanaCiclo(
        numero: actual.numero,
        dias: actual.dias,
        factorCarga: actual.factorCarga * 0.8,
        titulo: actual.titulo,
        nota: actual.nota,
        esDescarga: actual.esDescarga,
      );
      c.ajustes.add(AjusteCiclo(
        fecha: DateTime.now(),
        titulo: 'Semana suavizada',
        motivo:
            'Tus datos de descanso y esfuerzo dicen que vienes fundido. He '
            'bajado la carga de esta semana un 20%. No es un castigo: es la '
            'forma de que la siguiente sirva.',
      ));
    }
  }
}

// ---------------------------------------------------------------------------
// 30.4 EL CAMINO
//
// La rutina no es una lista: es un ciclo con principio y final. Se ve como
// un sendero de piedras, una por semana.
// ---------------------------------------------------------------------------

class CaminoScreen extends StatefulWidget {
  const CaminoScreen({super.key, required this.usuario});

  final String usuario;

  @override
  State<CaminoScreen> createState() => _CaminoScreenState();
}

class _CaminoScreenState extends State<CaminoScreen> {
  int _diaVisible = 0;

  @override
  void initState() {
    super.initState();
    AlmacenCiclos.instancia.revisar(widget.usuario);
  }

  Future<void> _crear() async {
    if (!puedeRehacerCiclo(context, widget.usuario)) return;
    final RespuestasCiclo? r = await Navigator.of(context).push<RespuestasCiclo>(
      MaterialPageRoute<RespuestasCiclo>(
        builder: (_) => PreguntasCicloScreen(usuario: widget.usuario),
      ),
    );
    if (r == null || !mounted) return;
    AlmacenCiclos.instancia.guardar(
      widget.usuario,
      GeneradorCiclo.generar(usuario: widget.usuario, r: r),
    );
    setState(() => _diaVisible = 0);
  }

  Future<void> _entrenar(DiaCiclo d, SemanaCiclo s) async {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final Disposicion disp = a.disposicion(widget.usuario, d.grupos);

    // Aplicar el factor de carga de la semana al peso sugerido.
    final PlanSesion plan = PlanSesion(
      nombre: '${d.nombre} · Semana ${s.numero}',
      grupos: d.grupos,
      minutos: d.minutos,
      razon: '${s.titulo}: ${s.nota}',
      ejercicios: <EjercicioPlan>[
        for (final EjercicioPlan e in d.ejercicios)
          EjercicioPlan(
            ejercicioId: e.ejercicioId,
            series: s.esDescarga ? (e.series - 1).clamp(2, 6) : e.series,
            repsObjetivo: e.repsObjetivo,
            pesoSugerido: e.pesoSugerido == null
                ? null
                : (e.pesoSugerido! * s.factorCarga / 2.5).round() * 2.5,
          ),
      ],
    );

    final Sesion ses = a.de(widget.usuario).enCurso ??
        a.abrirSesion(widget.usuario, plan, disp.valor);

    await Navigator.of(context).push(
      MaterialPageRoute<void>(
        builder: (_) => SesionScreen(usuario: widget.usuario, sesion: ses),
      ),
    );
    if (mounted) setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final CicloEntrenamiento? ciclo = AlmacenCiclos.instancia.de(widget.usuario);

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: SafeArea(
          child: ciclo == null
              ? _SinCiclo(onCrear: _crear)
              : _ConCiclo(
                  ciclo: ciclo,
                  usuario: widget.usuario,
                  diaVisible: _diaVisible,
                  onDia: (int i) => setState(() => _diaVisible = i),
                  onEntrenar: _entrenar,
                  onRehacer: _crear,
                ),
        ),
      ),
    );
  }
}

