/// El sendero de piedras: una por semana, iluminada la actual.
class _Sendero extends StatelessWidget {
  const _Sendero({required this.ciclo});
  final CicloEntrenamiento ciclo;

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      height: 62,
      child: Row(
        children: List<Widget>.generate(ciclo.semanas.length, (int i) {
          final SemanaCiclo s = ciclo.semanas[i];
          final bool pasada = i + 1 < ciclo.semanaActual;
          final bool actual = i + 1 == ciclo.semanaActual;
          final Color c = s.esDescarga
              ? TempleColors.exito
              : TempleColors.violeta;

          return Expanded(
            child: Column(
              children: <Widget>[
                Stack(
                  alignment: Alignment.center,
                  children: <Widget>[
                    if (i < ciclo.semanas.length - 1)
                      Positioned(
                        left: 20,
                        right: -20,
                        child: Container(
                          height: 2,
                          color: pasada
                              ? c.withValues(alpha: 0.5)
                              : TempleColors.borde,
                        ),
                      ),
                    AnimatedContainer(
                      duration: TempleMotion.medio,
                      width: actual ? 34 : 26,
                      height: actual ? 34 : 26,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        color: pasada || actual
                            ? c.withValues(alpha: actual ? 0.26 : 0.14)
                            : TempleColors.superficie,
                        border: Border.all(
                          color: pasada || actual ? c : TempleColors.borde,
                          width: actual ? 1.8 : 1,
                        ),
                        boxShadow: actual
                            ? <BoxShadow>[
                                BoxShadow(
                                  color: c.withValues(alpha: 0.4),
                                  blurRadius: 14,
                                )
                              ]
                            : null,
                      ),
                      child: Center(
                        child: pasada
                            ? Icon(Icons.check_rounded, size: 14, color: c)
                            : Text(
                                '${s.numero}',
                                style: TextStyle(
                                  fontSize: actual ? 13 : 11,
                                  fontWeight: FontWeight.w700,
                                  color: actual
                                      ? c
                                      : TempleColors.textoTenue,
                                ),
                              ),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 7),
                Text(
                  s.esDescarga ? 'agua' : s.titulo.toLowerCase(),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                    fontSize: 9.5,
                    color: actual ? c : TempleColors.textoTenue,
                  ),
                ),
              ],
            ),
          );
        }),
      ),
    );
  }
}

