/// Llama dibujada: tres capas que tiemblan a distinto ritmo, más brasas
/// subiendo. El tamaño y el color salen del escalón de racha.
class _LlamaPainter extends CustomPainter {
  const _LlamaPainter({
    required this.t,
    required this.color,
    required this.intensidad,
    required this.viva,
  });

  final double t;
  final Color color;
  final double intensidad;
  final bool viva;

  Path _forma(Offset base, double alto, double ancho, double meneo) {
    return Path()
      ..moveTo(base.dx, base.dy)
      ..cubicTo(
        base.dx - ancho, base.dy - alto * 0.35,
        base.dx - ancho * 0.75 + meneo, base.dy - alto * 0.72,
        base.dx + meneo * 0.6, base.dy - alto,
      )
      ..cubicTo(
        base.dx + ancho * 0.75 + meneo, base.dy - alto * 0.72,
        base.dx + ancho, base.dy - alto * 0.35,
        base.dx, base.dy,
      )
      ..close();
  }

  @override
  void paint(Canvas canvas, Size size) {
    final Offset base = Offset(size.width / 2, size.height * 0.86);
    final double escala = 0.45 + 0.55 * intensidad;
    final double altoMax = size.height * 0.66 * escala;

    // Resplandor.
    canvas.drawCircle(
      base.translate(0, -altoMax * 0.45),
      altoMax * 0.9,
      Paint()
        ..shader = RadialGradient(colors: <Color>[
          color.withValues(alpha: viva ? 0.24 : 0.05),
          Colors.transparent,
        ]).createShader(Rect.fromCircle(
            center: base.translate(0, -altoMax * 0.45),
            radius: altoMax * 0.9)),
    );

    if (!viva) {
      // Apagada: solo brasas.
      for (int i = 0; i < 5; i++) {
        canvas.drawCircle(
          base.translate((i - 2) * 9.0, -2),
          3.5,
          Paint()
            ..color = const Color(0xFF6B4A3A).withValues(
                alpha: 0.4 + 0.3 * math.sin(t * 2 * math.pi + i)),
        );
      }
      return;
    }

    // Tres capas, cada una con su ritmo.
    final List<List<double>> capas = <List<double>>[
      <double>[1.0, 0.46, 1.0, 0.30],
      <double>[0.72, 0.32, 1.7, 0.55],
      <double>[0.42, 0.18, 2.6, 0.9],
    ];

    for (int i = 0; i < capas.length; i++) {
      final double alto = altoMax * capas[i][0];
      final double ancho = altoMax * capas[i][1];
      final double vel = capas[i][2];
      final double op = capas[i][3];
      final double meneo =
          math.sin(t * 2 * math.pi * vel + i) * altoMax * 0.055;

      canvas.drawPath(
        _forma(base, alto, ancho, meneo),
        Paint()
          ..shader = LinearGradient(
            begin: Alignment.bottomCenter,
            end: Alignment.topCenter,
            colors: <Color>[
              Color.lerp(color, Colors.white, 0.15 + i * 0.25)!
                  .withValues(alpha: op),
              color.withValues(alpha: op * 0.85),
              color.withValues(alpha: 0),
            ],
            stops: const <double>[0, 0.55, 1],
          ).createShader(Rect.fromLTWH(
              base.dx - ancho, base.dy - alto, ancho * 2, alto))
          ..maskFilter = MaskFilter.blur(BlurStyle.normal, i == 0 ? 6 : 2),
      );
    }

    // Núcleo claro.
    canvas.drawPath(
      _forma(base, altoMax * 0.26, altoMax * 0.12,
          math.sin(t * 2 * math.pi * 3) * 2),
      Paint()..color = Colors.white.withValues(alpha: 0.55),
    );

    // Brasas que suben.
    for (int i = 0; i < 8; i++) {
      final double s = i / 8;
      final double fase = (t * (0.5 + s) + s) % 1.0;
      final double x = base.dx +
          math.sin(fase * 4 * math.pi + i) * altoMax * 0.22;
      final double y = base.dy - fase * altoMax * 1.25;
      canvas.drawCircle(
        Offset(x, y),
        1.6 * (1 - fase) + 0.5,
        Paint()..color = color.withValues(alpha: 0.75 * (1 - fase)),
      );
    }
  }

  @override
  bool shouldRepaint(_LlamaPainter old) =>
      old.t != t ||
      old.color != color ||
      old.intensidad != intensidad ||
      old.viva != viva;
}
