// ---------------------------------------------------------------------------
// 31.1 EL PESO DEL TEMPLO
//
// El número que nunca baja. Aquí se ve qué has levantado, en qué se ha
// convertido y cuánto falta para la siguiente pieza.
// ---------------------------------------------------------------------------

class PesoTemploScreen extends StatelessWidget {
  const PesoTemploScreen({super.key, required this.usuario});

  final String usuario;

  @override
  Widget build(BuildContext context) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final double kilos = a.pesoDelTemplo(usuario);
    final RangoPeso rango = RangosDelPeso.actual(kilos);
    final RangoPeso? siguienteRango = RangosDelPeso.siguiente(kilos);
    final PiezaTemplo? siguientePieza = PiezasDelTemplo.siguienteTras(kilos);
    final List<Sesion> ses = a.de(usuario).completadas;

    // Reparto por grupo: de dónde salió el peso.
    final Map<GrupoMuscular, double> porGrupo = <GrupoMuscular, double>{};
    for (final Sesion s in ses) {
      s.volumenPorGrupo.forEach((GrupoMuscular g, double v) {
        porGrupo[g] = (porGrupo[g] ?? 0) + v;
      });
    }
    final double mayor = porGrupo.values.isEmpty
        ? 1
        : porGrupo.values.reduce((double x, double y) => x > y ? x : y);
    final List<MapEntry<GrupoMuscular, double>> reparto =
        porGrupo.entries.toList()
          ..sort((MapEntry<GrupoMuscular, double> x,
                  MapEntry<GrupoMuscular, double> y) =>
              y.value.compareTo(x.value));

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: SafeArea(
          child: ListView(
            padding: const EdgeInsets.fromLTRB(20, 4, 20, 34),
            children: <Widget>[
              Row(
                children: <Widget>[
                  IconButton(
                    onPressed: () => Navigator.of(context).maybePop(),
                    icon: const Icon(Icons.arrow_back_rounded,
                        color: TempleColors.textoSuave),
                  ),
                  const Expanded(
                    child: Text(
                      'El Peso del Templo',
                      style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.w600,
                        color: TempleColors.blancoLuna,
                      ),
                    ),
                  ),
                  const BotonPase(),
                ],
              ),
              const SizedBox(height: 14),

              // Cifra grande y su equivalencia.
              Center(
                child: Column(
                  children: <Widget>[
                    TweenAnimationBuilder<double>(
                      tween: Tween<double>(begin: 0, end: kilos),
                      duration: const Duration(milliseconds: 1400),
                      curve: TempleMotion.suave,
                      builder: (BuildContext c, double v, _) => Text(
                        v >= 1000
                            ? '${(v / 1000).toStringAsFixed(1)} t'
                            : '${v.round()} kg',
                        style: const TextStyle(
                          fontSize: 46,
                          height: 1,
                          fontWeight: FontWeight.w600,
                          color: TempleColors.blancoLuna,
                        ),
                      ),
                    ),
                    const SizedBox(height: 10),
                    Text(
                      kilos <= 0
                          ? 'Todo templo empieza vacío.'
                          : 'Has levantado ${RangosDelPeso.equivalencia(kilos)}.',
                      textAlign: TextAlign.center,
                      style: const TextStyle(
                          fontSize: 13.5, color: TempleColors.textoSuave),
                    ),
                    const SizedBox(height: 14),
                    InsigniaRango(rango.titulo,
                        especial: kilos >= 250000),
                  ],
                ),
              ),
              const SizedBox(height: 26),

              // Siguiente rango.
              if (siguienteRango != null) ...<Widget>[
                const EtiquetaSeccion('Siguiente título'),
                TempleCard(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: <Widget>[
                      Row(
                        children: <Widget>[
                          Expanded(
                            child: Text(
                              siguienteRango.titulo,
                              style: const TextStyle(
                                fontSize: 16,
                                fontWeight: FontWeight.w600,
                                color: TempleColors.blancoLuna,
                              ),
                            ),
                          ),
                          Text(
                            '${((siguienteRango.kilos - kilos) / 1000).toStringAsFixed(1)} t',
                            style: const TextStyle(
                                fontSize: 13,
                                color: TempleColors.violetaClaro),
                          ),
                        ],
                      ),
                      const SizedBox(height: 6),
                      Text(
                        siguienteRango.descripcion,
                        style: const TextStyle(
                            fontSize: 12.5,
                            height: 1.45,
                            color: TempleColors.textoSuave),
                      ),
                      const SizedBox(height: 12),
                      ClipRRect(
                        borderRadius: BorderRadius.circular(999),
                        child: LinearProgressIndicator(
                          value:
                              (kilos / siguienteRango.kilos).clamp(0.0, 1.0),
                          minHeight: 6,
                          backgroundColor: TempleColors.borde,
                          valueColor: const AlwaysStoppedAnimation<Color>(
                              TempleColors.dorado),
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 22),
              ],

              // Las piezas del templo.
              EtiquetaSeccion(
                'Lo que has levantado',
                accion: Text(
                  '${PiezasDelTemplo.desbloqueadas(kilos)}/'
                  '${PiezasDelTemplo.todas.length}',
                  style: const TextStyle(
                    fontSize: 11,
                    fontWeight: FontWeight.w600,
                    color: TempleColors.violetaClaro,
                  ),
                ),
              ),
              TempleCard(
                padding:
                    const EdgeInsets.symmetric(horizontal: 16, vertical: 6),
                child: Column(
                  children: PiezasDelTemplo.todas.map((PiezaTemplo p) {
                    final bool tiene = kilos >= p.kilos;
                    final bool proxima = p == siguientePieza;
                    return Padding(
                      padding: const EdgeInsets.symmetric(vertical: 12),
                      child: Row(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: <Widget>[
                          Icon(
                            tiene
                                ? Icons.check_circle_rounded
                                : Icons.lock_outline_rounded,
                            size: 18,
                            color: tiene
                                ? TempleColors.dorado
                                : TempleColors.textoTenue,
                          ),
                          const SizedBox(width: 13),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: <Widget>[
                                Row(
                                  children: <Widget>[
                                    Text(
                                      p.nombre,
                                      style: TextStyle(
                                        fontSize: 14,
                                        fontWeight: proxima
                                            ? FontWeight.w700
                                            : FontWeight.w500,
                                        color: tiene
                                            ? TempleColors.blancoLuna
                                            : TempleColors.textoSuave,
                                      ),
                                    ),
                                    if (proxima) ...<Widget>[
                                      const SizedBox(width: 8),
                                      Container(
                                        padding: const EdgeInsets.symmetric(
                                            horizontal: 7, vertical: 2),
                                        decoration: BoxDecoration(
                                          color: TempleColors.violeta
                                              .withValues(alpha: 0.16),
                                          borderRadius:
                                              BorderRadius.circular(999),
                                        ),
                                        child: const Text('la siguiente',
                                            style: TextStyle(
                                                fontSize: 9.5,
                                                color: TempleColors
                                                    .violetaClaro)),
                                      ),
                                    ],
                                  ],
                                ),
                                const SizedBox(height: 3),
                                Text(
                                  tiene
                                      ? p.descripcion
                                      : '${(p.kilos / 1000).toStringAsFixed(0)} t · '
                                          'te faltan '
                                          '${((p.kilos - kilos) / 1000).toStringAsFixed(1)} t',
                                  style: TextStyle(
                                    fontSize: 11.5,
                                    height: 1.4,
                                    color: tiene
                                        ? TempleColors.textoTenue
                                        : TempleColors.alertaSuave,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),
                    );
                  }).toList(),
                ),
              ),
              const SizedBox(height: 22),

              // De dónde salió.
              if (reparto.isNotEmpty) ...<Widget>[
                const EtiquetaSeccion('De dónde salió'),
                TempleCard(
                  child: Column(
                    children: reparto.map(
                        (MapEntry<GrupoMuscular, double> e) {
                      return Padding(
                        padding: const EdgeInsets.only(bottom: 12),
                        child: Row(
                          children: <Widget>[
                            SizedBox(
                              width: 96,
                              child: Text(
                                e.key.etiqueta,
                                style: const TextStyle(
                                    fontSize: 12,
                                    color: TempleColors.textoSuave),
                              ),
                            ),
                            Expanded(
                              child: ClipRRect(
                                borderRadius: BorderRadius.circular(999),
                                child: LinearProgressIndicator(
                                  value: (e.value / mayor).clamp(0.02, 1.0),
                                  minHeight: 5,
                                  backgroundColor: TempleColors.borde,
                                  valueColor:
                                      const AlwaysStoppedAnimation<Color>(
                                          TempleColors.violeta),
                                ),
                              ),
                            ),
                            const SizedBox(width: 10),
                            SizedBox(
                              width: 54,
                              child: Text(
                                e.value >= 1000
                                    ? '${(e.value / 1000).toStringAsFixed(1)} t'
                                    : '${e.value.round()} kg',
                                textAlign: TextAlign.right,
                                style: const TextStyle(
                                    fontSize: 11,
                                    color: TempleColors.textoTenue),
                              ),
                            ),
                          ],
                        ),
                      );
                    }).toList(),
                  ),
                ),
                const SizedBox(height: 22),
              ],

              TempleCard(
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    const TempleIcon(TempleGlyph.casa,
                        size: 20, color: TempleColors.violetaClaro),
                    const SizedBox(width: 14),
                    const Expanded(
                      child: Text(
                        'Este número nunca baja.\n\n'
                        'Puedes fallar una semana, lesionarte o desaparecer '
                        'seis meses: los kilos que levantaste siguen ahí. '
                        'Es lo único del templo que no se puede perder.',
                        style: TextStyle(
                            fontSize: 12.5,
                            height: 1.55,
                            color: TempleColors.textoSuave),
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------------------------------------------------------------------
// 31.2 LA SEMANA
//
// En el Dojo solo vive la semana en curso. Al cerrarse se archiva, y aquí
// está el historial completo.
// ---------------------------------------------------------------------------

class SemanaScreen extends StatelessWidget {
  const SemanaScreen({super.key, required this.usuario});

  final String usuario;

  @override
  Widget build(BuildContext context) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final MotorProgresion m = MotorProgresion.instancia;
    final DateTime lunes = lunesDe(DateTime.now());
    final Racha racha = m.racha(usuario);

    final List<Sesion> deLaSemana = a
        .de(usuario)
        .completadas
        .where((Sesion s) =>
            !s.inicio.isBefore(lunes) &&
            s.inicio.isBefore(lunes.add(const Duration(days: 7))))
        .toList();

    final double volumen = deLaSemana.fold<double>(
        0, (double x, Sesion s) => x + s.volumenTotal);
    final int minutos =
        deLaSemana.fold<int>(0, (int x, Sesion s) => x + s.minutos);
    final int series = deLaSemana.fold<int>(
        0, (int x, Sesion s) => x + s.seriesEfectivas);
    final Set<GrupoMuscular> grupos = <GrupoMuscular>{};
    for (final Sesion s in deLaSemana) {
      grupos.addAll(s.gruposTrabajados);
    }

    // Comparación con la semana anterior.
    final List<SemanaArchivada> archivo = m.de(usuario).semanas;
    final SemanaArchivada? anterior =
        archivo.isEmpty ? null : archivo.last;
    final double difVolumen =
        anterior == null || anterior.volumen <= 0
            ? 0
            : (volumen - anterior.volumen) / anterior.volumen;

    // Volumen por día.
    final List<double> porDia = List<double>.filled(7, 0);
    for (final Sesion s in deLaSemana) {
      porDia[s.inicio.weekday - 1] += s.volumenTotal;
    }
    final double mejorDia = porDia.fold<double>(0, math.max);
    const List<String> ini = <String>['L', 'M', 'X', 'J', 'V', 'S', 'D'];

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: SafeArea(
          child: ListView(
            padding: const EdgeInsets.fromLTRB(20, 4, 20, 34),
            children: <Widget>[
              Row(
                children: <Widget>[
                  IconButton(
                    onPressed: () => Navigator.of(context).maybePop(),
                    icon: const Icon(Icons.arrow_back_rounded,
                        color: TempleColors.textoSuave),
                  ),
                  const Expanded(
                    child: Text(
                      'La Semana',
                      style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.w600,
                        color: TempleColors.blancoLuna,
                      ),
                    ),
                  ),
                  const BotonPase(),
                ],
              ),
              const SizedBox(height: 8),

              // Estado.
              TempleCard(
                destacada: racha.semanaCumplida,
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    Row(
                      children: <Widget>[
                        Text(
                          '${racha.sesionesEstaSemana} / ${racha.objetivoSemanal}',
                          style: const TextStyle(
                            fontSize: 30,
                            height: 1,
                            fontWeight: FontWeight.w600,
                            color: TempleColors.blancoLuna,
                          ),
                        ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: Text(
                            racha.semanaCumplida
                                ? 'Semana cumplida. Lo que venga es regalo.'
                                : 'Sesiones de esta semana.',
                            style: TextStyle(
                              fontSize: 12.5,
                              height: 1.4,
                              color: racha.semanaCumplida
                                  ? TempleColors.exito
                                  : TempleColors.textoSuave,
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 18),
                    SizedBox(
                      height: 92,
                      child: Row(
                        crossAxisAlignment: CrossAxisAlignment.end,
                        children: List<Widget>.generate(7, (int i) {
                          final DateTime dia =
                              lunes.add(Duration(days: i));
                          final bool hoy = i == DateTime.now().weekday - 1;
                          final bool futuro = dia.isAfter(DateTime.now());
                          final double v = mejorDia <= 0
                              ? 0
                              : porDia[i] / mejorDia;
                          return Expanded(
                            child: Column(
                              mainAxisAlignment: MainAxisAlignment.end,
                              children: <Widget>[
                                if (porDia[i] > 0)
                                  Text(
                                    '${(porDia[i] / 1000).toStringAsFixed(1)}t',
                                    style: const TextStyle(
                                        fontSize: 8.5,
                                        color: TempleColors.textoTenue),
                                  ),
                                const SizedBox(height: 4),
                                Expanded(
                                  child: FractionallySizedBox(
                                    heightFactor: math.max(v, 0.03),
                                    alignment: Alignment.bottomCenter,
                                    child: Container(
                                      width: 12,
                                      decoration: BoxDecoration(
                                        borderRadius:
                                            BorderRadius.circular(4),
                                        gradient: LinearGradient(
                                          begin: Alignment.bottomCenter,
                                          end: Alignment.topCenter,
                                          colors: porDia[i] > 0
                                              ? const <Color>[
                                                  TempleColors.violeta,
                                                  TempleColors.violetaClaro,
                                                ]
                                              : <Color>[
                                                  TempleColors.borde,
                                                  TempleColors.borde,
                                                ],
                                        ),
                                      ),
                                    ),
                                  ),
                                ),
                                const SizedBox(height: 8),
                                Text(
                                  ini[i],
                                  style: TextStyle(
                                    fontSize: 10.5,
                                    fontWeight: hoy
                                        ? FontWeight.w700
                                        : FontWeight.w400,
                                    color: hoy
                                        ? TempleColors.violetaClaro
                                        : futuro
                                            ? TempleColors.textoTenue
                                            : TempleColors.textoSuave,
                                  ),
                                ),
                              ],
                            ),
                          );
                        }),
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 22),

              // Cifras.
              const EtiquetaSeccion('Lo que llevas'),
              TempleCard(
                child: Row(
                  children: <Widget>[
                    _CifraSemana(
                      valor: volumen >= 1000
                          ? (volumen / 1000).toStringAsFixed(1)
                          : volumen.round().toString(),
                      unidad: volumen >= 1000 ? 't' : 'kg',
                      etiqueta: 'Volumen',
                    ),
                    _CifraSemana(
                        valor: '$series', unidad: '', etiqueta: 'Series'),
                    _CifraSemana(
                        valor: '$minutos', unidad: 'min', etiqueta: 'Tiempo'),
                    _CifraSemana(
                        valor: '${grupos.length}',
                        unidad: '/9',
                        etiqueta: 'Grupos'),
                  ],
                ),
              ),
              const SizedBox(height: 14),

              if (anterior != null)
                TempleCard(
                  child: Row(
                    children: <Widget>[
                      Icon(
                        difVolumen >= 0
                            ? Icons.trending_up_rounded
                            : Icons.trending_down_rounded,
                        size: 20,
                        color: difVolumen >= 0
                            ? TempleColors.exito
                            : TempleColors.alertaSuave,
                      ),
                      const SizedBox(width: 13),
                      Expanded(
                        child: Text(
                          difVolumen == 0
                              ? 'Misma carga que la semana pasada.'
                              : '${difVolumen >= 0 ? "+" : ""}'
                                  '${(difVolumen * 100).round()}% de volumen '
                                  'respecto a la semana pasada.',
                          style: const TextStyle(
                              fontSize: 12.5, color: TempleColors.textoSuave),
                        ),
                      ),
                    ],
                  ),
                ),
              const SizedBox(height: 22),

              // Grupos de la semana.
              const EtiquetaSeccion('Grupos tocados'),
              TempleCard(
                child: Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: GrupoMuscular.values.map((GrupoMuscular g) {
                    final bool ok = grupos.contains(g);
                    return Container(
                      padding: const EdgeInsets.symmetric(
                          horizontal: 11, vertical: 7),
                      decoration: BoxDecoration(
                        color: ok
                            ? TempleColors.violeta.withValues(alpha: 0.14)
                            : Colors.transparent,
                        borderRadius: BorderRadius.circular(999),
                        border: Border.all(
                          color: ok
                              ? TempleColors.violeta.withValues(alpha: 0.4)
                              : TempleColors.borde,
                        ),
                      ),
                      child: Text(
                        g.etiqueta,
                        style: TextStyle(
                          fontSize: 11.5,
                          color: ok
                              ? TempleColors.violetaClaro
                              : TempleColors.textoTenue,
                        ),
                      ),
                    );
                  }).toList(),
                ),
              ),
              const SizedBox(height: 22),

              // Historial.
              if (archivo.isNotEmpty) ...<Widget>[
                const EtiquetaSeccion('Semanas archivadas'),
                TempleCard(
                  padding: const EdgeInsets.symmetric(
                      horizontal: 16, vertical: 6),
                  child: Column(
                    children: archivo.reversed
                        .take(12)
                        .map((SemanaArchivada s) => Padding(
                              padding:
                                  const EdgeInsets.symmetric(vertical: 12),
                              child: Row(
                                children: <Widget>[
                                  Icon(
                                    s.cumplida
                                        ? Icons.check_circle_rounded
                                        : Icons
                                            .remove_circle_outline_rounded,
                                    size: 17,
                                    color: s.cumplida
                                        ? TempleColors.exito
                                        : TempleColors.textoTenue,
                                  ),
                                  const SizedBox(width: 12),
                                  Expanded(
                                    child: Column(
                                      crossAxisAlignment:
                                          CrossAxisAlignment.start,
                                      children: <Widget>[
                                        Text(
                                          s.etiqueta,
                                          style: const TextStyle(
                                              fontSize: 13,
                                              color: TempleColors.texto),
                                        ),
                                        const SizedBox(height: 2),
                                        Text(
                                          '${s.grupos.length} grupos · '
                                          '${s.minutos} min',
                                          style: const TextStyle(
                                              fontSize: 11,
                                              color:
                                                  TempleColors.textoTenue),
                                        ),
                                      ],
                                    ),
                                  ),
                                  Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.end,
                                    children: <Widget>[
                                      Text(
                                        '${s.sesiones}/${s.objetivo}',
                                        style: const TextStyle(
                                          fontSize: 13,
                                          fontWeight: FontWeight.w600,
                                          color: TempleColors.blancoLuna,
                                        ),
                                      ),
                                      Text(
                                        '${(s.volumen / 1000).toStringAsFixed(1)} t',
                                        style: const TextStyle(
                                            fontSize: 10.5,
                                            color: TempleColors.textoSuave),
                                      ),
                                    ],
                                  ),
                                ],
                              ),
                            ))
                        .toList(),
                  ),
                ),
              ] else
                TempleCard(
                  child: const Text(
                    'Cuando termine esta semana se archivará aquí con su '
                    'resumen, y podrás volver a mirarla siempre que quieras.',
                    style: TextStyle(
                        fontSize: 12.5,
                        height: 1.5,
                        color: TempleColors.textoSuave),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }
}

class _CifraSemana extends StatelessWidget {
