    required this.valor,
    required this.unidad,
    required this.etiqueta,
  });

  final String valor;
  final String unidad;
  final String etiqueta;

  @override
  Widget build(BuildContext context) => Expanded(
        child: Column(
          children: <Widget>[
            RichText(
              text: TextSpan(
                text: valor,
