}

// ---------------------------------------------------------------------------
// 31.3 NUTRICIÓN: MODELO
//
// Nutrición POR HÁBITOS, no por calorías.
//
// Esta app no calcula un número de calorías ni receta déficits. Un objetivo
// calórico dado por un programa que no conoce tu historial médico ni tu
// relación con la comida hace más daño que bien. Lo que sí funciona —y
// además es mejor producto— es estructura, rangos y comidas concretas con
// lo que tienes en casa.
// ---------------------------------------------------------------------------

enum RitmoComidas { tres, cuatro, cinco, irregular }

extension DatosRitmo on RitmoComidas {
  String get etiqueta {
    switch (this) {
      case RitmoComidas.tres:
        return 'Tres comidas';
      case RitmoComidas.cuatro:
        return 'Tres y algo entre medias';
      case RitmoComidas.cinco:
        return 'Cinco tomas pequeñas';
      case RitmoComidas.irregular:
        return 'Cambia cada día';
    }
  }

  int get tomas {
    switch (this) {
      case RitmoComidas.tres:
        return 3;
      case RitmoComidas.cuatro:
        return 4;
      case RitmoComidas.cinco:
        return 5;
      case RitmoComidas.irregular:
        return 3;
    }
  }
}

enum TiempoCocina { nada, poco, normal, mucho }

extension DatosTiempo on TiempoCocina {
  String get etiqueta {
    switch (this) {
      case TiempoCocina.nada:
        return 'Casi nada';
      case TiempoCocina.poco:
        return 'Diez minutos';
      case TiempoCocina.normal:
        return 'Media hora';
      case TiempoCocina.mucho:
        return 'Me gusta cocinar';
    }
  }

  int get minutos {
    switch (this) {
      case TiempoCocina.nada:
        return 5;
      case TiempoCocina.poco:
        return 12;
      case TiempoCocina.normal:
        return 30;
      case TiempoCocina.mucho:
        return 60;
    }
  }
}

enum Restriccion { vegetariano, vegano, sinLactosa, sinGluten, sinCerdo }

extension DatosRestriccion on Restriccion {
  String get etiqueta {
    switch (this) {
      case Restriccion.vegetariano:
        return 'Vegetariano';
      case Restriccion.vegano:
        return 'Vegano';
      case Restriccion.sinLactosa:
        return 'Sin lactosa';
      case Restriccion.sinGluten:
        return 'Sin gluten';
      case Restriccion.sinCerdo:
        return 'Sin cerdo';
    }
  }

  String get etiquetaComida {
    switch (this) {
      case Restriccion.vegetariano:
        return 'vegetariano';
      case Restriccion.vegano:
        return 'vegano';
      case Restriccion.sinLactosa:
        return 'sinLactosa';
      case Restriccion.sinGluten:
        return 'sinGluten';
      case Restriccion.sinCerdo:
        return 'sinCerdo';
    }
  }
}

enum Dificultad { desayuno, proteina, picoteo, cocinar, horarios }

extension DatosDificultad on Dificultad {
  String get etiqueta {
    switch (this) {
      case Dificultad.desayuno:
        return 'Me salto el desayuno';
      case Dificultad.proteina:
        return 'Me cuesta llegar a la proteína';
      case Dificultad.picoteo:
        return 'Pico entre horas';
      case Dificultad.cocinar:
        return 'No tengo tiempo de cocinar';
      case Dificultad.horarios:
        return 'Como a horas raras';
    }
  }

  String get consejo {
    switch (this) {
      case Dificultad.desayuno:
        return 'No pasa nada por no desayunar, siempre que el resto del día '
            'cubra lo que necesitas. Si entrenas por la mañana, al menos algo '
            'ligero antes: un plátano o un yogur bastan.';
      case Dificultad.proteina:
        return 'El truco no es comer más, es repartir. Una fuente de proteína '
            'en cada toma —huevo, pollo, atún, lentejas, yogur— llega mucho '
            'más lejos que intentar meterlo todo en la cena.';
      case Dificultad.picoteo:
        return 'Picar no es el problema; picar sin querer, sí. Ten a mano algo '
            'con proteína o fibra —frutos secos, yogur, fruta— y deja lo demás '
            'fuera de la vista.';
      case Dificultad.cocinar:
        return 'Cocina una vez, come tres. Una tanda de arroz, otra de '
            'legumbre y una proteína a la plancha el domingo te resuelven la '
            'mitad de la semana.';
      case Dificultad.horarios:
        return 'Comer a horas raras no arruina nada. Lo que importa es el '
            'total del día y que alrededor del entrenamiento haya algo. El '
            'resto es flexible.';
    }
  }
}

class PerfilNutricion {
  PerfilNutricion({
    required this.ritmo,
    required this.tiempo,
    required this.restricciones,
    required this.dificultad,
    this.pesoCorporal,
  });

  final RitmoComidas ritmo;
  final TiempoCocina tiempo;
  final Set<Restriccion> restricciones;
  final Dificultad dificultad;

  /// Opcional. Solo se usa para dar rangos, nunca objetivos cerrados.
  final double? pesoCorporal;
}

class Comida {
  const Comida({
    required this.nombre,
    required this.momento,
    required this.minutos,
    required this.descripcion,
    required this.apto,
    this.altaProteina = true,
  });

  final String nombre;

  /// 'desayuno', 'principal', 'entre', 'post'
  final String momento;
  final int minutos;
  final String descripcion;

  /// Etiquetas que cumple: vegetariano, vegano, sinLactosa, sinGluten, sinCerdo
  final Set<String> apto;
  final bool altaProteina;
}

