/// El plato dibujado: tres sectores proporcionales.
class _PlatoPainter extends CustomPainter {
  const _PlatoPainter(this.proporciones);
  final List<int> proporciones;

  @override
  void paint(Canvas canvas, Size size) {
    final Offset c = Offset(size.width / 2, size.height / 2);
    final double r = size.shortestSide / 2 - 6;

    const List<Color> colores = <Color>[
      TempleColors.violeta,
      TempleColors.dorado,
      Color(0xFF5BD6A0),
    ];

    double inicio = -math.pi / 2;
    for (int i = 0; i < proporciones.length; i++) {
      final double barrido = 2 * math.pi * (proporciones[i] / 100);
      canvas.drawArc(
        Rect.fromCircle(center: c, radius: r),
        inicio,
        barrido - 0.03,
        true,
        Paint()..color = colores[i].withValues(alpha: 0.75),
      );
      inicio += barrido;
    }

    // Borde del plato.
    canvas.drawCircle(
      c,
      r,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2
        ..color = TempleColors.negro,
    );
    canvas.drawCircle(
      c,
      r * 0.30,
      Paint()..color = TempleColors.superficie,
    );
  }

  @override
  bool shouldRepaint(_PlatoPainter old) =>
      old.proporciones != proporciones;
}

