// ---------------------------------------------------------------------------
// 31.5 RECUPERACIÓN: MODELO
// ---------------------------------------------------------------------------

class EstadoRecuperacion {
  const EstadoRecuperacion({
    required this.fecha,
    this.dolor = 0,
    this.estres = 0,
    this.energia = 2,
  });

  final DateTime fecha;

  /// 0 = nada, 4 = mucho.
  final int dolor;
  final int estres;

  /// 0 = agotado, 4 = pleno.
  final int energia;

  String get clave =>
      '${fecha.year}-${fecha.month.toString().padLeft(2, '0')}-'
      '${fecha.day.toString().padLeft(2, '0')}';

  EstadoRecuperacion copyWith({int? dolor, int? estres, int? energia}) =>
      EstadoRecuperacion(
        fecha: fecha,
        dolor: dolor ?? this.dolor,
        estres: estres ?? this.estres,
        energia: energia ?? this.energia,
      );
}

class AlmacenRecuperacion {
  AlmacenRecuperacion._();
  static final AlmacenRecuperacion instancia = AlmacenRecuperacion._();

  final Map<String, Map<String, EstadoRecuperacion>> _datos =
      <String, Map<String, EstadoRecuperacion>>{};

  EstadoRecuperacion de(String usuario, DateTime dia) {
    final EstadoRecuperacion base = EstadoRecuperacion(fecha: dia);
    return _datos[usuario]?[base.clave] ?? base;
  }

  void guardar(String usuario, EstadoRecuperacion e) {
    _datos
        .putIfAbsent(usuario, () => <String, EstadoRecuperacion>{})[e.clave] = e;
  }

  /// Índice de recuperación 0–100. Cruza sueño, agua, dolor, estrés y días
  /// desde el último entrenamiento.
  int indice(String usuario) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final RegistroDiario r = a.registroDe(usuario, DateTime.now());
    final EstadoRecuperacion e = de(usuario, DateTime.now());

    double v = 50;

    final double? sueno = r.horasSueno;
    if (sueno != null) {
      v += ((sueno - 7) * 7).clamp(-25.0, 18.0);
    }

    v += (r.vasosAgua.clamp(0, 8) - 4) * 1.5;
    v -= e.dolor * 6;
    v -= e.estres * 5;
    v += (e.energia - 2) * 6;

    // Días seguidos entrenando sin descanso.
    int seguidos = 0;
    for (int i = 0; i < 10; i++) {
      if (a.entrenoEse(usuario, DateTime.now().subtract(Duration(days: i)))) {
        seguidos++;
      } else {
        break;
      }
    }
    if (seguidos >= 4) v -= (seguidos - 3) * 5;

    return v.clamp(0, 100).round();
  }
}

/// Un ritual: algo concreto que hacer hoy. Nada de consejos vagos.
class RitualRecuperacion {
  const RitualRecuperacion({
    required this.nombre,
    required this.minutos,
    required this.descripcion,
    required this.glifo,
  });

  final String nombre;
  final int minutos;
  final String descripcion;
  final TempleGlyph glifo;
}

class RitualesDelTemplo {
  const RitualesDelTemplo._();

  static const List<RitualRecuperacion> todos = <RitualRecuperacion>[
    RitualRecuperacion(
      nombre: 'Respiración del bambú',
      minutos: 4,
      descripcion:
          'Inhala cuatro segundos, sostén cuatro, exhala seis. Doce rondas. '
          'Baja el pulso y ordena la cabeza mejor que cualquier estiramiento.',
      glifo: TempleGlyph.loto,
    ),
    RitualRecuperacion(
      nombre: 'Caminar sin destino',
      minutos: 20,
      descripcion:
          'Veinte minutos a paso suave, sin música si puedes. Mueve la sangre '
          'sin sumar fatiga: es la recuperación activa más infravalorada.',
      glifo: TempleGlyph.montana,
    ),
    RitualRecuperacion(
      nombre: 'Movilidad de caderas',
      minutos: 8,
      descripcion:
          'Sentadilla profunda sostenida, rotaciones y estocada con giro. '
          'Si entrenas pierna, esto vale más que masajear el músculo dolorido.',
      glifo: TempleGlyph.espadas,
    ),
    RitualRecuperacion(
      nombre: 'Apertura de pecho',
      minutos: 6,
      descripcion:
          'Estiramiento en marco de puerta, treinta segundos por lado, tres '
          'veces. Imprescindible si haces mucho press.',
      glifo: TempleGlyph.mancuerna,
    ),
    RitualRecuperacion(
      nombre: 'La hora sin pantallas',
      minutos: 60,
      descripcion:
          'La última hora del día sin móvil. Es lo que más mejora el sueño de '
          'todo lo que puedes hacer gratis.',
      glifo: TempleGlyph.luna,
    ),
    RitualRecuperacion(
      nombre: 'Piernas en la pared',
      minutos: 10,
      descripcion:
          'Tumbado, piernas apoyadas en vertical contra la pared. Diez '
          'minutos. Alivia las piernas cargadas y calma el sistema nervioso.',
      glifo: TempleGlyph.torii,
    ),
    RitualRecuperacion(
      nombre: 'Comer y no hacer nada',
      minutos: 30,
      descripcion:
          'Una comida completa sin pantalla delante. Digerir bien también es '
          'recuperarse, y comer distraído hace que comas peor.',
      glifo: TempleGlyph.cuenco,
    ),
    RitualRecuperacion(
      nombre: 'Dormir antes',
      minutos: 45,
      descripcion:
          'Acuéstate 45 minutos antes de lo normal. Ningún suplemento se '
          'acerca a lo que hace una hora más de sueño.',
      glifo: TempleGlyph.luna,
    ),
  ];

  /// Elige los rituales que tocan según el estado de hoy.
  static List<RitualRecuperacion> paraHoy(
    String usuario,
    EstadoRecuperacion e,
    double? sueno,
  ) {
    final List<RitualRecuperacion> l = <RitualRecuperacion>[];

    if (sueno != null && sueno < 6.5) {
      l.add(todos[7]); // Dormir antes
      l.add(todos[4]); // Hora sin pantallas
    }
    if (e.estres >= 2) l.add(todos[0]); // Respiración
    if (e.dolor >= 2) {
      l.add(todos[1]); // Caminar
      l.add(todos[5]); // Piernas en la pared
    }
    if (e.energia <= 1) l.add(todos[1]);

    final Map<GrupoMuscular, int> deuda =
        AlmacenTemplo.instancia.deuda(usuario);
    if ((deuda[GrupoMuscular.piernas] ?? 99) <= 2) l.add(todos[2]);
    if ((deuda[GrupoMuscular.pecho] ?? 99) <= 2) l.add(todos[3]);

    if (l.length < 3) {
      for (final RitualRecuperacion r in todos) {
        if (!l.contains(r)) l.add(r);
        if (l.length >= 3) break;
      }
    }

    // Sin repetidos, máximo cuatro.
    return l.toSet().take(4).toList();
  }
}

