/// Escala de cinco puntos. Más rápida que un slider y más clara que un número.
class _FilaEscala extends StatelessWidget {
  const _FilaEscala({
    required this.glifo,
    required this.etiqueta,
    required this.valor,
    required this.textos,
    required this.onCambio,
  });

  final TempleGlyph glifo;
  final String etiqueta;
  final int valor;
  final List<String> textos;
  final ValueChanged<int> onCambio;

  @override
  Widget build(BuildContext context) => Padding(
        padding: const EdgeInsets.symmetric(vertical: 12),
        child: Column(
          children: <Widget>[
            Row(
              children: <Widget>[
                TempleIcon(glifo,
                    size: 18, color: TempleColors.violetaClaro),
                const SizedBox(width: 12),
                Expanded(
                  child: Text(etiqueta,
                      style: const TextStyle(
                          fontSize: 13.5, color: TempleColors.texto)),
                ),
                Text(textos[valor.clamp(0, 4)],
                    style: const TextStyle(
                        fontSize: 12.5, color: TempleColors.textoSuave)),
              ],
            ),
            const SizedBox(height: 10),
            Row(
              children: List<Widget>.generate(5, (int i) {
                final bool act = i <= valor;
                return Expanded(
                  child: GestureDetector(
                    onTap: () => onCambio(i),
                    child: Container(
                      height: 26,
                      margin: const EdgeInsets.symmetric(horizontal: 3),
                      decoration: BoxDecoration(
                        color: act
                            ? TempleColors.violeta.withValues(alpha: 0.22)
                            : TempleColors.superficie,
                        borderRadius: BorderRadius.circular(7),
                        border: Border.all(
                          color: i == valor
                              ? TempleColors.violeta
                              : TempleColors.borde,
                        ),
                      ),
                    ),
                  ),
                );
              }),
            ),
          ],
        ),
      );
}
