// TEMPLE OF STRENGTH — SECCIÓN 32: LA CASA
//
// Pegar al final de main.dart, después de la sección 31.
//
// ANTES DE PEGAR: borra de la sección 15 la clase `CasaScreen` (el andamio de
// cinco líneas que devuelve PantallaEnForja). Aquí se sustituye por la versión
// real, con la misma firma `const CasaScreen({super.key})`, así que MainShell
// no necesita ningún cambio.
//
//   32.1  Momento del día y estación
//   32.2  Estado de la Casa y almacén
//   32.3  La escena (dibujo del templo)
//   32.4  La ceremonia de una pieza nueva
//   32.5  Pantalla de la Casa
//   32.6  Tarjeta del templo para el Dojo
// ===========================================================================

// ---------------------------------------------------------------------------
// 32.1 MOMENTO DEL DÍA Y ESTACIÓN
//
// La casa cambia con el reloj real y con el mes. Es contenido que no cuesta
// nada producir y que hace que abrir la app un martes cualquiera tenga algo
// distinto que mirar.
// ---------------------------------------------------------------------------

enum MomentoDia { amanecer, dia, atardecer, noche }

extension DatosMomento on MomentoDia {
  String get etiqueta {
    switch (this) {
      case MomentoDia.amanecer:
        return 'Amanecer';
      case MomentoDia.dia:
        return 'Día';
      case MomentoDia.atardecer:
        return 'Atardecer';
      case MomentoDia.noche:
        return 'Noche';
    }
  }

  /// Degradado del cielo, de arriba a abajo.
  List<Color> get cielo {
    switch (this) {
      case MomentoDia.amanecer:
        return const <Color>[
          Color(0xFF3A2450),
          Color(0xFF8A4A5E),
          Color(0xFFC98A62),
        ];
      case MomentoDia.dia:
        return const <Color>[
          Color(0xFF243A5E),
          Color(0xFF476B96),
          Color(0xFF7E9BB8),
        ];
      case MomentoDia.atardecer:
        return const <Color>[
          Color(0xFF241338),
          Color(0xFF7A3450),
          Color(0xFFC26A48),
        ];
      case MomentoDia.noche:
        return const <Color>[
          Color(0xFF150C28),
          Color(0xFF1B0F35),
          Color(0xFF0A0616),
        ];
    }
  }

  /// Tinte general de las siluetas.
  Color get tinta {
    switch (this) {
      case MomentoDia.amanecer:
        return const Color(0xFF2A1B32);
      case MomentoDia.dia:
        return const Color(0xFF1B2740);
      case MomentoDia.atardecer:
        return const Color(0xFF2A1226);
      case MomentoDia.noche:
        return const Color(0xFF0C0718);
    }
  }

  /// Cuánto se notan las ventanas encendidas.
  double get fuerzaLuz {
    switch (this) {
      case MomentoDia.amanecer:
        return 0.55;
      case MomentoDia.dia:
        return 0.15;
      case MomentoDia.atardecer:
        return 0.75;
      case MomentoDia.noche:
        return 1.0;
    }
  }

  static MomentoDia deHora(int h) {
    if (h >= 5 && h < 9) return MomentoDia.amanecer;
    if (h >= 9 && h < 17) return MomentoDia.dia;
    if (h >= 17 && h < 20) return MomentoDia.atardecer;
    return MomentoDia.noche;
  }
}

enum Estacion { primavera, verano, otono, invierno }

extension DatosEstacion on Estacion {
  String get etiqueta {
    switch (this) {
      case Estacion.primavera:
        return 'Primavera';
      case Estacion.verano:
        return 'Verano';
      case Estacion.otono:
        return 'Otoño';
      case Estacion.invierno:
        return 'Invierno';
    }
  }

  String get kanji {
    switch (this) {
      case Estacion.primavera:
        return '春';
      case Estacion.verano:
        return '夏';
      case Estacion.otono:
        return '秋';
      case Estacion.invierno:
        return '冬';
    }
  }

  String get nota {
    switch (this) {
      case Estacion.primavera:
        return 'Los cerezos están en flor. Duran poco: por eso se miran.';
      case Estacion.verano:
        return 'El follaje está cerrado y las noches traen luciérnagas.';
      case Estacion.otono:
        return 'Los arces se encendieron. El templo huele a hoja seca.';
      case Estacion.invierno:
        return 'Nieve en los tejados. El silencio se oye más.';
    }
  }

  Color get follaje {
    switch (this) {
      case Estacion.primavera:
        return const Color(0xFFE7A8D0);
      case Estacion.verano:
        return const Color(0xFF2F5E42);
      case Estacion.otono:
        return const Color(0xFFC85A32);
      case Estacion.invierno:
        return const Color(0xFF4A4258);
    }
  }

  static Estacion delMes(int m) {
    if (m >= 3 && m <= 5) return Estacion.primavera;
    if (m >= 6 && m <= 8) return Estacion.verano;
    if (m >= 9 && m <= 11) return Estacion.otono;
    return Estacion.invierno;
  }
}

// ---------------------------------------------------------------------------
// 32.2 ESTADO DE LA CASA
//
// La Casa no se decide: se deriva. Los kilos levantados dicen qué está
// construido, el reloj dice cómo se ve y la llama dice si está encendida.
// ---------------------------------------------------------------------------

class EstadoCasa {
  const EstadoCasa({
    required this.kilos,
    required this.piezas,
    required this.siguiente,
    required this.momento,
    required this.estacion,
    required this.vitalidad,
    required this.entrenoHoy,
  });

  final double kilos;

  /// Piezas ya levantadas, en orden.
  final List<PiezaTemplo> piezas;
  final PiezaTemplo? siguiente;
  final MomentoDia momento;
  final Estacion estacion;

  /// 0 = templo a oscuras. 1 = templo encendido.
  final double vitalidad;
  final bool entrenoHoy;

  bool tiene(String nombre) =>
      piezas.any((PiezaTemplo p) => p.nombre == nombre);

  double get progresoSiguiente =>
      siguiente == null ? 1 : (kilos / siguiente!.kilos).clamp(0.0, 1.0);

  double get faltanToneladas =>
      siguiente == null ? 0 : (siguiente!.kilos - kilos) / 1000;

  static EstadoCasa de(String usuario) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final double kilos = a.pesoDelTemplo(usuario);
    final DateTime ahora = DateTime.now();

    return EstadoCasa(
      kilos: kilos,
      piezas: PiezasDelTemplo.todas
          .where((PiezaTemplo p) => kilos >= p.kilos)
          .toList(),
      siguiente: PiezasDelTemplo.siguienteTras(kilos),
      momento: DatosMomento.deHora(ahora.hour),
      estacion: DatosEstacion.delMes(ahora.month),
      vitalidad: (a.llama(usuario).valor / 100).clamp(0.0, 1.0),
      entrenoHoy: a.entrenoEse(usuario, ahora),
    );
  }
}

/// Guarda hasta dónde había visto construido el usuario, para poder
/// celebrar lo que se levantó desde su última visita.
class AlmacenCasa {
  AlmacenCasa._();
  static final AlmacenCasa instancia = AlmacenCasa._();

  final Map<String, double> _ultimoPesoVisto = <String, double>{};

  /// Piezas levantadas desde la última vez que entró a la Casa.
  List<PiezaTemplo> piezasNuevas(String usuario) {
    final double antes = _ultimoPesoVisto[usuario] ?? 0;
    final double ahora = AlmacenTemplo.instancia.pesoDelTemplo(usuario);
    return PiezasDelTemplo.todas
        .where((PiezaTemplo p) => p.kilos > antes && p.kilos <= ahora)
        .toList();
  }

  void marcarVistas(String usuario) {
    _ultimoPesoVisto[usuario] =
        AlmacenTemplo.instancia.pesoDelTemplo(usuario);
  }

  /// Primera visita: no celebramos nada retroactivo, solo sincronizamos.
  void sincronizarSiEsPrimeraVez(String usuario) {
    if (!_ultimoPesoVisto.containsKey(usuario)) {
      _ultimoPesoVisto[usuario] =
          AlmacenTemplo.instancia.pesoDelTemplo(usuario);
    }
  }
}

// ---------------------------------------------------------------------------
// 32.3 LA ESCENA
//
// El templo entero dibujado en vector. Es la pieza más grande de arte de la
// app y la que se reutilizará para la postal compartible del Clan.
// ---------------------------------------------------------------------------

class EscenaCasa extends StatefulWidget {
  const EscenaCasa({
    super.key,
    required this.estado,
    this.altura = 300,
    this.animada = true,
  });

  final EstadoCasa estado;
  final double altura;
  final bool animada;

  @override
  State<EscenaCasa> createState() => _EscenaCasaState();
}

class _EscenaCasaState extends State<EscenaCasa>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;

  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 40),
  );

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final bool reducir = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    if (!widget.animada || reducir) {
      _c.stop();
      _c.value = 0.3;
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => SizedBox(
        height: widget.altura,
        width: double.infinity,
        child: RepaintBoundary(
          child: AnimatedBuilder(
            animation: _c,
            builder: (BuildContext context, _) => CustomPaint(
              painter: _CasaPainter(estado: widget.estado, t: _c.value),
            ),
          ),
        ),
      );
}

class _CasaPainter extends CustomPainter {
  const _CasaPainter({required this.estado, required this.t});

  final EstadoCasa estado;
  final double t;

  @override
  void paint(Canvas canvas, Size size) {
    final double w = size.width;
    final double h = size.height;
    final double hz = h * 0.60; // línea del horizonte
    final Color tinta = estado.momento.tinta;
    final bool nieve = estado.estacion == Estacion.invierno;

    _cielo(canvas, w, h);
    _astro(canvas, w, h);
    _montanas(canvas, w, h, hz, tinta);

    // Fondo: bambú y pagoda, las piezas grandes.
    if (estado.tiene('El bosque de bambú')) _bambu(canvas, w, h, hz, tinta);
    if (estado.tiene('La pagoda')) _pagoda(canvas, w, h, hz, tinta);

    _terreno(canvas, w, h, hz, tinta, nieve);

    if (estado.tiene('El estanque')) _estanque(canvas, w, h, tinta);
    if (estado.tiene('El jardín seco')) _jardinSeco(canvas, w, h);
    if (estado.tiene('El sendero')) _sendero(canvas, w, h, nieve);

    _salaPrincipal(canvas, w, h, tinta, nieve);

    if (estado.tiene('El torii')) _torii(canvas, w, h, tinta, nieve);
    if (estado.tiene('La campana')) _campana(canvas, w, h, tinta, nieve);

    _vegetacionEstacional(canvas, w, h, hz, tinta);
    _niebla(canvas, w, h, hz);
    _particulas(canvas, w, h);

    // Viñeta inferior: garantiza que el texto encima siempre se lea.
    canvas.drawRect(
      Offset.zero & size,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.center,
          end: Alignment.bottomCenter,
          colors: <Color>[
            Colors.transparent,
            ColoresTradicion.negro.withValues(alpha: 0.55),
          ],
        ).createShader(Offset.zero & size),
    );
  }

  // ---- Cielo y astro ----------------------------------------------------

  void _cielo(Canvas c, double w, double h) {
    c.drawRect(
      Rect.fromLTWH(0, 0, w, h),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: estado.momento.cielo,
        ).createShader(Rect.fromLTWH(0, 0, w, h)),
    );

    // Estrellas solo de noche.
    if (estado.momento == MomentoDia.noche) {
      final math.Random rnd = math.Random(13);
      for (int i = 0; i < 46; i++) {
        final double x = rnd.nextDouble() * w;
        final double y = rnd.nextDouble() * h * 0.48;
        final double br =
            0.35 + 0.35 * math.sin(t * 2 * math.pi * 3 + i.toDouble());
        c.drawCircle(Offset(x, y), rnd.nextDouble() * 1.1 + 0.35,
            Paint()..color = Colors.white.withValues(alpha: br * 0.7));
      }
    }
  }

  void _astro(Canvas c, double w, double h) {
    final bool luna = estado.momento == MomentoDia.noche ||
        estado.momento == MomentoDia.atardecer;
    final Offset p = Offset(w * 0.78, h * (luna ? 0.18 : 0.16));
    final double r = h * 0.055;
    final Color col = luna ? const Color(0xFFE8DCFF) : const Color(0xFFFFE0A8);

    c.drawCircle(
      p,
      r * 4.2,
      Paint()
        ..shader = RadialGradient(colors: <Color>[
          col.withValues(alpha: luna ? 0.26 : 0.34),
          Colors.transparent,
        ]).createShader(Rect.fromCircle(center: p, radius: r * 4.2)),
    );
    c.drawCircle(p, r, Paint()..color = col.withValues(alpha: 0.94));
  }

  // ---- Paisaje ----------------------------------------------------------

  void _montanas(Canvas c, double w, double h, double hz, Color tinta) {
    final Color lejos = Color.lerp(tinta, Colors.white, 0.10)!;
    c.drawPath(
      Path()
        ..moveTo(0, hz)
        ..lineTo(0, hz - h * 0.14)
        ..quadraticBezierTo(w * 0.18, hz - h * 0.34, w * 0.38, hz - h * 0.16)
        ..quadraticBezierTo(w * 0.58, hz - h * 0.38, w * 0.78, hz - h * 0.18)
        ..quadraticBezierTo(w * 0.90, hz - h * 0.26, w, hz - h * 0.12)
        ..lineTo(w, hz)
        ..close(),
      Paint()..color = lejos.withValues(alpha: 0.85),
    );

    if (estado.estacion == Estacion.invierno) {
      c.drawPath(
        Path()
          ..moveTo(w * 0.30, hz - h * 0.22)
          ..quadraticBezierTo(w * 0.38, hz - h * 0.17, w * 0.46, hz - h * 0.21)
          ..quadraticBezierTo(w * 0.40, hz - h * 0.30, w * 0.30, hz - h * 0.22)
          ..close(),
        Paint()..color = Colors.white.withValues(alpha: 0.18),
      );
    }
  }

  void _terreno(
      Canvas c, double w, double h, double hz, Color tinta, bool nieve) {
    c.drawRect(
      Rect.fromLTRB(0, hz, w, h),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[
            Color.lerp(tinta, Colors.white, nieve ? 0.14 : 0.04)!,
            Color.lerp(tinta, Colors.black, 0.45)!,
          ],
        ).createShader(Rect.fromLTRB(0, hz, w, h)),
    );

    // Loma suave delante.
    c.drawPath(
      Path()
        ..moveTo(0, hz + h * 0.06)
        ..quadraticBezierTo(w * 0.40, hz - h * 0.02, w, hz + h * 0.08)
        ..lineTo(w, h)
        ..lineTo(0, h)
        ..close(),
      Paint()
        ..color = Color.lerp(tinta, Colors.black, nieve ? 0.10 : 0.28)!
            .withValues(alpha: 0.95),
    );
  }

  // ---- Piezas del templo -------------------------------------------------

  /// 5 t · el sendero
  void _sendero(Canvas c, double w, double h, bool nieve) {
    final Color piedra = nieve
        ? Colors.white.withValues(alpha: 0.32)
        : Colors.white.withValues(alpha: 0.13);
    for (int i = 0; i < 7; i++) {
      final double p = i / 6;
      final double x = w * (0.50 - 0.06 * math.sin(p * math.pi)) +
          (p - 0.5) * w * 0.05;
      final double y = h * (0.98 - p * 0.20);
      final double ancho = w * (0.075 - p * 0.035);
      c.drawOval(
        Rect.fromCenter(
            center: Offset(x, y), width: ancho, height: ancho * 0.34),
        Paint()..color = piedra,
      );
    }
  }

  /// 25 t · el torii
  void _torii(Canvas c, double w, double h, Color tinta, bool nieve) {
    final Offset base = Offset(w * 0.20, h * 0.87);
    final double alto = h * 0.26;
    final double an = alto * 0.72;
    final double izq = base.dx - an / 2;
    final double der = base.dx + an / 2;
    final double top = base.dy - alto;
    final Color col = Color.lerp(tinta, const Color(0xFF7A1F2B), 0.45)!;

    Paint p(double g) => Paint()
      ..color = col
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeWidth = g;

    c.drawPath(
      Path()
        ..moveTo(izq - an * 0.14, top + alto * 0.10)
        ..quadraticBezierTo(
            base.dx, top - alto * 0.04, der + an * 0.14, top + alto * 0.10),
      p(alto * 0.085),
    );
    c.drawLine(Offset(izq - an * 0.03, top + alto * 0.21),
        Offset(der + an * 0.03, top + alto * 0.21), p(alto * 0.055));
    c.drawLine(Offset(izq + an * 0.06, top + alto * 0.42),
        Offset(der - an * 0.06, top + alto * 0.42), p(alto * 0.048));
    c.drawLine(Offset(izq + an * 0.02, top + alto * 0.21),
        Offset(izq + an * 0.07, base.dy), p(alto * 0.07));
    c.drawLine(Offset(der - an * 0.02, top + alto * 0.21),
        Offset(der - an * 0.07, base.dy), p(alto * 0.07));

    if (nieve) {
      c.drawLine(
        Offset(izq - an * 0.12, top + alto * 0.07),
        Offset(der + an * 0.12, top + alto * 0.07),
        Paint()
          ..color = Colors.white.withValues(alpha: 0.5)
          ..strokeWidth = alto * 0.03
          ..strokeCap = StrokeCap.round,
      );
    }
  }

  /// 60 t · el estanque
  void _estanque(Canvas c, double w, double h, Color tinta) {
    final Rect r = Rect.fromCenter(
      center: Offset(w * 0.30, h * 0.955),
      width: w * 0.40,
      height: h * 0.13,
    );
    c.drawOval(
      r,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[
            Color.lerp(estado.momento.cielo[1], Colors.white, 0.10)!
                .withValues(alpha: 0.75),
            Color.lerp(tinta, Colors.black, 0.3)!,
          ],
        ).createShader(r),
    );

    // Ondas.
    for (int i = 0; i < 3; i++) {
      final double d = math.sin(t * 2 * math.pi + i * 1.4) * w * 0.012;
      c.drawLine(
        Offset(w * 0.22 + d, h * (0.935 + i * 0.017)),
        Offset(w * 0.38 + d, h * (0.935 + i * 0.017)),
        Paint()
          ..color = Colors.white.withValues(alpha: 0.14 - i * 0.035)
          ..strokeWidth = 1.3
          ..strokeCap = StrokeCap.round,
      );
    }
  }

  /// 120 t · la campana
  void _campana(Canvas c, double w, double h, Color tinta, bool nieve) {
    final Offset base = Offset(w * 0.80, h * 0.86);
    final double s = h * 0.10;
    final Color madera = Color.lerp(tinta, Colors.white, 0.06)!;

    // Postes y techo.
    c.drawLine(Offset(base.dx - s * 0.8, base.dy),
        Offset(base.dx - s * 0.7, base.dy - s * 1.5), Paint()
          ..color = madera
          ..strokeWidth = s * 0.16
          ..strokeCap = StrokeCap.round);
    c.drawLine(Offset(base.dx + s * 0.8, base.dy),
        Offset(base.dx + s * 0.7, base.dy - s * 1.5), Paint()
          ..color = madera
          ..strokeWidth = s * 0.16
          ..strokeCap = StrokeCap.round);
    c.drawPath(
      Path()
        ..moveTo(base.dx - s * 1.15, base.dy - s * 1.45)
        ..quadraticBezierTo(base.dx, base.dy - s * 2.05, base.dx + s * 1.15,
            base.dy - s * 1.45)
        ..close(),
      Paint()..color = madera,
    );

    // La campana.
    c.drawPath(
      Path()
        ..moveTo(base.dx - s * 0.42, base.dy - s * 0.25)
        ..lineTo(base.dx - s * 0.38, base.dy - s * 1.05)
        ..quadraticBezierTo(
            base.dx, base.dy - s * 1.45, base.dx + s * 0.38, base.dy - s * 1.05)
        ..lineTo(base.dx + s * 0.42, base.dy - s * 0.25)
        ..close(),
      Paint()..color = const Color(0xFF4A3D22),
    );

    if (nieve) {
      c.drawPath(
        Path()
          ..moveTo(base.dx - s * 1.1, base.dy - s * 1.48)
          ..quadraticBezierTo(base.dx, base.dy - s * 1.92, base.dx + s * 1.1,
              base.dy - s * 1.48)
          ..close(),
        Paint()..color = Colors.white.withValues(alpha: 0.45),
      );
    }
  }

  /// 220 t · el jardín seco
  void _jardinSeco(Canvas c, double w, double h) {
    final Offset centro = Offset(w * 0.74, h * 0.955);
    for (int i = 1; i <= 5; i++) {
      c.drawOval(
        Rect.fromCenter(
          center: centro,
          width: w * 0.055 * i,
          height: h * 0.016 * i,
        ),
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1
          ..color = Colors.white.withValues(alpha: 0.10),
      );
    }
    c.drawOval(
      Rect.fromCenter(
          center: centro, width: w * 0.032, height: h * 0.014),
      Paint()..color = Colors.black.withValues(alpha: 0.55),
    );
    c.drawOval(
      Rect.fromCenter(
          center: centro.translate(w * 0.07, -h * 0.012),
          width: w * 0.022,
          height: h * 0.010),
      Paint()..color = Colors.black.withValues(alpha: 0.5),
    );
  }

  /// 400 t · la pagoda
  void _pagoda(Canvas c, double w, double h, double hz, Color tinta) {
    final Offset base = Offset(w * 0.11, hz + h * 0.04);
    final double s = h * 0.055;
    final Color col = Color.lerp(tinta, Colors.black, 0.25)!;

    for (int i = 0; i < 5; i++) {
      final double y = base.dy - s * (0.5 + i * 0.85);
      final double an = s * (1.15 - i * 0.16);
      c.drawPath(
        Path()
          ..moveTo(base.dx - an, y)
          ..quadraticBezierTo(base.dx, y - s * 0.42, base.dx + an, y)
          ..close(),
        Paint()..color = col,
      );
      c.drawRect(
        Rect.fromLTWH(base.dx - an * 0.42, y, an * 0.84, s * 0.55),
        Paint()..color = col,
      );
    }
    // Aguja.
    c.drawLine(
      Offset(base.dx, base.dy - s * 4.7),
      Offset(base.dx, base.dy - s * 5.5),
      Paint()
        ..color = col
        ..strokeWidth = s * 0.10
        ..strokeCap = StrokeCap.round,
    );
  }

  /// 750 t · el bosque de bambú
  void _bambu(Canvas c, double w, double h, double hz, Color tinta) {
    final Color col = Color.lerp(tinta, const Color(0xFF1E4A32), 0.35)!;
    for (int i = 0; i < 9; i++) {
      final double x = w * (0.86 + i * 0.022) - w * 0.02 * (i % 3);
      final double alto = h * (0.34 + (i % 4) * 0.07);
      final double meneo = math.sin(t * 2 * math.pi + i) * w * 0.004;

      final Paint canya = Paint()
        ..color = col
        ..strokeWidth = w * 0.010
        ..strokeCap = StrokeCap.round;
      c.drawLine(Offset(x, hz + h * 0.10),
          Offset(x + w * 0.008 + meneo, hz + h * 0.10 - alto), canya);

      for (int n = 1; n < 5; n++) {
        final double y = hz + h * 0.10 - alto * n / 5;
        c.drawLine(Offset(x - 3, y), Offset(x + 5, y),
            canya..strokeWidth = w * 0.005);
      }
    }
  }

  // ---- La sala principal --------------------------------------------------

  void _salaPrincipal(
      Canvas c, double w, double h, Color tinta, bool nieve) {
    final Offset base = Offset(w * 0.50, h * 0.80);
    final double an = w * 0.17;
    final double alto = h * 0.15;
    final Color madera = Color.lerp(tinta, Colors.white, 0.05)!;

    // Plataforma.
    c.drawRect(
      Rect.fromLTWH(base.dx - an * 1.15, base.dy, an * 2.3, h * 0.022),
      Paint()..color = Color.lerp(tinta, Colors.black, 0.35)!,
    );

    // Cuerpo.
    c.drawRect(
      Rect.fromLTWH(base.dx - an, base.dy - alto, an * 2, alto),
      Paint()..color = madera,
    );

    // Ventanas. Se encienden con la vitalidad y con la hora.
    final double luz =
        (estado.vitalidad * estado.momento.fuerzaLuz).clamp(0.0, 1.0);
    for (int i = 0; i < 4; i++) {
      final Rect v = Rect.fromLTWH(
        base.dx - an * 0.78 + i * an * 0.42,
        base.dy - alto * 0.72,
        an * 0.28,
        alto * 0.40,
      );
      c.drawRect(
        v,
        Paint()
          ..color = Color.lerp(const Color(0xFF15101F),
              const Color(0xFFF0B45C), luz * (i == 1 || i == 2 ? 1 : 0.75))!,
      );
      if (luz > 0.12) {
        c.drawRect(
          v.inflate(an * 0.10),
          Paint()
            ..color = const Color(0xFFF0B45C).withValues(alpha: 0.16 * luz)
            ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 10),
        );
      }
    }

    // Tejado con aleros curvos.
    c.drawPath(
      Path()
        ..moveTo(base.dx - an * 1.45, base.dy - alto * 0.94)
        ..quadraticBezierTo(base.dx - an * 0.7, base.dy - alto * 1.62,
            base.dx, base.dy - alto * 1.70)
        ..quadraticBezierTo(base.dx + an * 0.7, base.dy - alto * 1.62,
            base.dx + an * 1.45, base.dy - alto * 0.94)
        ..quadraticBezierTo(base.dx, base.dy - alto * 1.16,
            base.dx - an * 1.45, base.dy - alto * 0.94)
        ..close(),
      Paint()..color = Color.lerp(tinta, Colors.black, 0.30)!,
    );

    if (nieve) {
      c.drawPath(
        Path()
          ..moveTo(base.dx - an * 1.38, base.dy - alto * 1.00)
          ..quadraticBezierTo(base.dx - an * 0.7, base.dy - alto * 1.60,
              base.dx, base.dy - alto * 1.68)
          ..quadraticBezierTo(base.dx + an * 0.7, base.dy - alto * 1.60,
              base.dx + an * 1.38, base.dy - alto * 1.00)
          ..quadraticBezierTo(base.dx, base.dy - alto * 1.30,
              base.dx - an * 1.38, base.dy - alto * 1.00)
          ..close(),
        Paint()..color = Colors.white.withValues(alpha: 0.42),
      );
    }

    // Humo: solo si el templo está vivo.
    if (estado.vitalidad > 0.35) {
      for (int i = 0; i < 4; i++) {
        final double fase = (t * 1.6 + i * 0.25) % 1.0;
        final double x = base.dx + an * 0.72 +
            math.sin(fase * 3.2 + i) * w * 0.018;
        final double y = base.dy - alto * 1.75 - fase * h * 0.16;
        c.drawCircle(
          Offset(x, y),
          w * (0.010 + fase * 0.028),
          Paint()
            ..color = Colors.white
                .withValues(alpha: 0.13 * (1 - fase) * estado.vitalidad)
            ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 8),
        );
      }
    }
  }

  // ---- Estación y ambiente ------------------------------------------------

  void _vegetacionEstacional(
      Canvas c, double w, double h, double hz, Color tinta) {
    final Color copa = estado.estacion.follaje;

    void arbol(double cx, double base, double escala) {
      c.drawLine(
        Offset(cx, base),
        Offset(cx - w * 0.008, base - h * 0.11 * escala),
        Paint()
          ..color = Color.lerp(tinta, Colors.black, 0.4)!
          ..strokeWidth = w * 0.011 * escala
          ..strokeCap = StrokeCap.round,
      );
      for (int i = 0; i < 4; i++) {
        final double a = -0.5 - i * 0.55;
        final Offset p = Offset(
          cx - w * 0.008 + math.cos(a) * w * 0.035 * escala,
          base - h * 0.11 * escala + math.sin(a) * h * 0.022 * escala,
        );
        c.drawCircle(p, w * 0.030 * escala,
            Paint()..color = copa.withValues(alpha: 0.30));
      }
    }

    arbol(w * 0.90, hz + h * 0.12, 1.0);
    arbol(w * 0.06, hz + h * 0.16, 0.85);
  }

  void _niebla(Canvas c, double w, double h, double hz) {
    // A menos vitalidad, más niebla. Es el castigo visual, sin una palabra.
    final int bandas = (5 - 3.6 * estado.vitalidad).round().clamp(1, 5);
    for (int i = 0; i < bandas; i++) {
      final double fase = (t + i * 0.22) % 1.0;
      final double x = -w * 0.5 + fase * w * 2.0;
      final double y = hz - h * 0.02 + i * h * 0.045;
      c.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromLTWH(x, y, w * 0.68, h * 0.05),
          Radius.circular(h * 0.03),
        ),
        Paint()
          ..color = Colors.white
              .withValues(alpha: 0.030 + 0.055 * (1 - estado.vitalidad))
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 14),
      );
    }
  }

  void _particulas(Canvas c, double w, double h) {
    final math.Random rnd = math.Random(37);

    switch (estado.estacion) {
      case Estacion.primavera:
        for (int i = 0; i < 16; i++) {
          final double s = rnd.nextDouble();
          final double fase = (t * (0.5 + s * 0.5) + s) % 1.0;
          final double x =
              w * rnd.nextDouble() + math.sin(fase * 2 * math.pi + i) * w * 0.05;
          final double y = -8 + fase * (h + 16);
          c.save();
          c.translate(x, y);
          c.rotate(fase * 7 + i);
          c.drawOval(
            Rect.fromCenter(center: Offset.zero, width: 7, height: 4),
            Paint()..color = const Color(0xFFE7B9F5).withValues(alpha: 0.50),
          );
          c.restore();
        }
      case Estacion.verano:
        // Luciérnagas, solo al caer la luz.
        if (estado.momento == MomentoDia.noche ||
            estado.momento == MomentoDia.atardecer) {
          for (int i = 0; i < 14; i++) {
            final double s = rnd.nextDouble();
            final double x = w * s +
                math.sin(t * 2 * math.pi * (0.3 + s) + i) * w * 0.06;
            final double y = h * (0.62 + rnd.nextDouble() * 0.3) +
                math.cos(t * 2 * math.pi * (0.25 + s) + i) * h * 0.04;
            final double br =
                (0.3 + 0.7 * math.sin(t * 2 * math.pi * 4 + i * 1.7))
                    .clamp(0.0, 1.0);
            c.drawCircle(
              Offset(x, y),
              w * 0.014,
              Paint()
                ..color = const Color(0xFFDDF08A).withValues(alpha: 0.20 * br)
                ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6),
            );
            c.drawCircle(Offset(x, y), 1.4,
                Paint()..color = const Color(0xFFF4FFB0).withValues(alpha: br));
          }
        }
      case Estacion.otono:
        for (int i = 0; i < 14; i++) {
          final double s = rnd.nextDouble();
          final double fase = (t * (0.4 + s * 0.4) + s) % 1.0;
          final double x =
              w * rnd.nextDouble() + math.sin(fase * 2 * math.pi + i) * w * 0.07;
          final double y = -8 + fase * (h + 16);
          c.save();
          c.translate(x, y);
          c.rotate(fase * 9 + i);
          c.drawOval(
            Rect.fromCenter(center: Offset.zero, width: 8, height: 5),
            Paint()..color = const Color(0xFFD9702E).withValues(alpha: 0.55),
          );
          c.restore();
        }
      case Estacion.invierno:
        for (int i = 0; i < 30; i++) {
          final double s = rnd.nextDouble();
          final double fase = (t * (0.35 + s * 0.35) + s) % 1.0;
          final double x =
              w * rnd.nextDouble() + math.sin(fase * 2 * math.pi + i) * w * 0.03;
          final double y = -6 + fase * (h + 12);
          c.drawCircle(Offset(x, y), 1 + s * 1.8,
              Paint()..color = Colors.white.withValues(alpha: 0.62));
        }
    }
  }

  @override
  bool shouldRepaint(_CasaPainter old) =>
      old.t != t ||
      old.estado.kilos != estado.kilos ||
      old.estado.momento != estado.momento ||
      old.estado.estacion != estado.estacion ||
      old.estado.vitalidad != estado.vitalidad;
}

// ---------------------------------------------------------------------------
// 32.4 LA CEREMONIA
//
// Cuando el peso acumulado cruza un umbral, la pieza se levanta delante del
// usuario al entrar a la Casa. Es el momento de recompensa del módulo: no se
// anuncia con un texto, se ve aparecer.
// ---------------------------------------------------------------------------

class CeremoniaPieza extends StatefulWidget {
  const CeremoniaPieza({
    super.key,
    required this.pieza,
    required this.estado,
    required this.onCerrar,
  });

  final PiezaTemplo pieza;
  final EstadoCasa estado;
  final VoidCallback onCerrar;

  @override
  State<CeremoniaPieza> createState() => _CeremoniaPiezaState();
}

class _CeremoniaPiezaState extends State<CeremoniaPieza>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 2600),
  );

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _c.forward();
    });
    HapticFeedback.heavyImpact();
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Positioned.fill(
      child: Container(
        color: TempleColors.negro.withValues(alpha: 0.90),
        child: SafeArea(
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 30),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: <Widget>[
                Aparece(
                  controlador: _c,
                  desde: 0,
                  hasta: 0.30,
                  child: const Text(
                    'EL TEMPLO HA CRECIDO',
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      letterSpacing: 4,
                      color: TempleColors.textoSuave,
                    ),
                  ),
                ),
                const SizedBox(height: 26),
                Aparece(
                  controlador: _c,
                  desde: 0.10,
                  hasta: 0.58,
                  desplazamiento: 26,
                  child: ClipRRect(
                    borderRadius:
                        BorderRadius.circular(TempleRadius.tarjeta),
                    child: SizedBox(
                      height: 220,
                      child: Stack(
                        fit: StackFit.expand,
                        children: <Widget>[
                          EscenaCasa(estado: widget.estado, altura: 220),
                          IgnorePointer(
                            child: DecoratedBox(
                              decoration: BoxDecoration(
                                border: Border.all(
                                  color: TempleColors.dorado
                                      .withValues(alpha: 0.45),
                                ),
                                borderRadius: BorderRadius.circular(
                                    TempleRadius.tarjeta),
                              ),
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
                const SizedBox(height: 30),
                Aparece(
                  controlador: _c,
                  desde: 0.42,
                  hasta: 0.82,
                  child: Column(
                    children: <Widget>[
                      Text(
                        widget.pieza.nombre,
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                          fontSize: 30,
                          height: 1.1,
                          fontWeight: FontWeight.w600,
                          color: TempleColors.dorado,
                        ),
                      ),
                      const SizedBox(height: 12),
                      Text(
                        widget.pieza.descripcion,
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                          fontSize: 14,
                          height: 1.7,
                          color: TempleColors.textoSuave,
                        ),
                      ),
                      const SizedBox(height: 14),
                      Text(
                        '${(widget.pieza.kilos / 1000).toStringAsFixed(0)} '
                        'toneladas levantadas',
                        style: const TextStyle(
                          fontSize: 12,
                          letterSpacing: 1.2,
                          color: TempleColors.textoTenue,
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 40),
                Aparece(
                  controlador: _c,
                  desde: 0.62,
                  hasta: 1.0,
                  child: SizedBox(
                    width: double.infinity,
                    child: DojoPrimaryButton(
                      texto: 'Entrar al templo',
                      onPressed: widget.onCerrar,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

// ---------------------------------------------------------------------------
// 32.5 PANTALLA DE LA CASA
//
// Sustituye al andamio `CasaScreen` de la sección 15. Misma firma, así que
// MainShell no cambia.
// ---------------------------------------------------------------------------

class CasaScreen extends StatefulWidget {
  const CasaScreen({super.key});

  @override
  State<CasaScreen> createState() => _CasaScreenState();
}

class _CasaScreenState extends State<CasaScreen> {
  int _pestana = 0;
  List<PiezaTemplo> _porCelebrar = <PiezaTemplo>[];
  bool _revisado = false;

  void _revisarCeremonia(String usuario) {
    if (_revisado) return;
    _revisado = true;
    final AlmacenCasa a = AlmacenCasa.instancia;
    a.sincronizarSiEsPrimeraVez(usuario);
    final List<PiezaTemplo> nuevas = a.piezasNuevas(usuario);
    if (nuevas.isNotEmpty) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) setState(() => _porCelebrar = nuevas);
      });
    }
  }

  void _siguienteCeremonia(String usuario) {
    setState(() {
      _porCelebrar = _porCelebrar.sublist(1);
      if (_porCelebrar.isEmpty) AlmacenCasa.instancia.marcarVistas(usuario);
    });
  }

  @override
  Widget build(BuildContext context) {
    final TempleShellScope shell = TempleShellScope.of(context);
    final String usuario = shell.perfil.nombre;
    final EstadoCasa estado = EstadoCasa.de(usuario);

    _revisarCeremonia(usuario);

    return Stack(
      children: <Widget>[
        ListView(
          physics: const BouncingScrollPhysics(),
          padding: EdgeInsets.only(bottom: kAlturaNavBar + 28),
          children: <Widget>[
            // -- La escena, a sangre --------------------------------------
            Stack(
              children: <Widget>[
                EscenaCasa(
                  estado: estado,
                  altura: 320 + MediaQuery.paddingOf(context).top,
                ),
                Positioned(
                  top: MediaQuery.paddingOf(context).top + 12,
                  left: 20,
                  right: 20,
                  child: Row(
                    children: <Widget>[
                      _Sello2(
                          texto: estado.estacion.kanji,
                          nota: estado.estacion.etiqueta),
                      const SizedBox(width: 8),
                      _Sello2(
                          texto: '', nota: estado.momento.etiqueta),
                      const Spacer(),
                      if (estado.entrenoHoy)
                        _Sello2(texto: '', nota: 'Encendido hoy'),
                      const SizedBox(width: 6),
                      BotonMenuTemplo(
                        sobreImagen: true,
                        onTap: () => menuCasa(
                          context,
                          usuario: usuario,
                          espiritu: shell.perfil.espiritu,
                        ),
                      ),
                    ],
                  ),
                ),
                Positioned(
                  left: 20,
                  right: 20,
                  bottom: 16,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: <Widget>[
                      Text(
                        'El templo de ${shell.perfil.nombre}',
                        style: const TextStyle(
                          fontSize: 21,
                          fontWeight: FontWeight.w600,
