// ---------------------------------------------------------------------------
// 33.1 NIVEL POR MÚSCULO
//
// Cada grupo sube por su cuenta con el XP que ya reparte ReglasXp. La curva
// es más barata que la del nivel general: aquí interesa que se vea moverse.
// ---------------------------------------------------------------------------

class NivelMusculo {
  const NivelMusculo({
    required this.nivel,
    required this.xpEnNivel,
    required this.xpSiguiente,
    required this.rango,
  });

  final int nivel;
  final int xpEnNivel;
  final int xpSiguiente;
  final String rango;

  double get progreso =>
      xpSiguiente <= 0 ? 0 : (xpEnNivel / xpSiguiente).clamp(0.0, 1.0);

  static int coste(int n) => (180 * math.pow(1.13, n - 1)).round();

  static NivelMusculo desdeXp(double xp) {
    int nivel = 1;
    double resto = xp;
    while (resto >= coste(nivel) && nivel < 120) {
      resto -= coste(nivel);
      nivel++;
    }
    final String rango;
    if (nivel < 3) {
      rango = 'Dormido';
    } else if (nivel < 6) {
      rango = 'Despierto';
    } else if (nivel < 11) {
      rango = 'Firme';
    } else if (nivel < 19) {
      rango = 'Forjado';
    } else if (nivel < 30) {
      rango = 'Templado';
    } else {
      rango = 'Maestro';
    }
    return NivelMusculo(
      nivel: nivel,
      xpEnNivel: resto.round(),
      xpSiguiente: coste(nivel),
      rango: rango,
    );
  }
}

/// Todo lo que una linterna necesita saber de su músculo.
class LuzMusculo {
  const LuzMusculo({
    required this.grupo,
    required this.nivel,
    required this.dias,
    required this.volumenSemanal,
    required this.xp,
  });

  final GrupoMuscular grupo;
  final NivelMusculo nivel;

  /// Días desde el último trabajo. 99 = nunca.
  final int dias;
  final double volumenSemanal;
  final double xp;

  /// 0 = apagada, 1 = encendida del todo. Se apaga a los catorce días.
  double get brillo {
    if (dias >= 90) return 0;
    return (1 - (dias / 14)).clamp(0.05, 1.0);
  }

  bool get enDeuda => dias >= 10 && dias < 90;
  bool get nunca => dias >= 90;

  static List<LuzMusculo> todas(String usuario) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final DatosUsuario d = a.de(usuario);
    final Map<GrupoMuscular, int> deuda = a.deuda(usuario);
    final PerfilEntrenamiento p = a.perfil(usuario);

    return GrupoMuscular.values.map((GrupoMuscular g) {
      final double xp = d.xpPorGrupo[g] ?? 0;
      return LuzMusculo(
        grupo: g,
        nivel: NivelMusculo.desdeXp(xp),
        dias: deuda[g] ?? 99,
        volumenSemanal: p.volumenSemanalPorGrupo[g] ?? 0,
        xp: xp,
      );
    }).toList();
  }
}

// ---------------------------------------------------------------------------
// 33.2 LA SALA DE LOS NUEVE
//
// Nueve linternas colgadas, una por grupo muscular. El tamaño es el nivel y
// el brillo son los días sin trabajo. Entras y ves tu deuda sin leer un solo
// número: la que lleva dos semanas apagada se nota a la primera.
// ---------------------------------------------------------------------------

class SalaNueveScreen extends StatefulWidget {
  const SalaNueveScreen({super.key, required this.usuario});

  final String usuario;

  @override
  State<SalaNueveScreen> createState() => _SalaNueveScreenState();
}

class _SalaNueveScreenState extends State<SalaNueveScreen>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 6),
  );

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (MediaQuery.maybeDisableAnimationsOf(context) ?? false) {
      _c.stop();
      _c.value = 0.3;
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  Future<void> _detalle(LuzMusculo l) async {
    await showModalBottomSheet<void>(
      context: context,
      backgroundColor: TempleColors.grafito,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (_) => _HojaMusculo(luz: l),
    );
  }

  @override
  Widget build(BuildContext context) {
    final List<LuzMusculo> luces = LuzMusculo.todas(widget.usuario);
    final LuzMusculo masApagada = luces.reduce(
        (LuzMusculo a, LuzMusculo b) => a.brillo <= b.brillo ? a : b);
    final int encendidas =
        luces.where((LuzMusculo l) => l.brillo > 0.55).length;
    final Habitante? hab = AlmacenHabitante.instancia.elegido(widget.usuario);

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: Container(
        decoration: const BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: <Color>[
              Color(0xFF120C1E),
              Color(0xFF0A0714),
              Color(0xFF06040C),
            ],
          ),
        ),
        child: SafeArea(
          child: Column(
            children: <Widget>[
              Row(
                children: <Widget>[
                  IconButton(
                    onPressed: () => Navigator.of(context).maybePop(),
                    icon: const Icon(Icons.arrow_back_rounded,
                        color: TempleColors.textoSuave),
                  ),
                  const Expanded(
                    child: Text(
                      'La Sala de los Nueve',
                      style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.w600,
                        color: TempleColors.blancoLuna,
                      ),
                    ),
                  ),
                  Padding(
                    padding: const EdgeInsets.only(right: 16),
                    child: Text(
                      '$encendidas/9 encendidas',
                      style: const TextStyle(
                          fontSize: 11.5, color: TempleColors.textoTenue),
                    ),
                  ),
                  const BotonPase(),
                ],
              ),
              Expanded(
                child: SingleChildScrollView(
                  padding: const EdgeInsets.fromLTRB(16, 10, 16, 30),
                  child: Column(
                    children: <Widget>[
                      // La sala: viga superior y tres hileras de linternas.
                      RepaintBoundary(
                        child: AnimatedBuilder(
                          animation: _c,
                          builder: (BuildContext context, _) {
                            return Column(
                              children: <Widget>[
                                for (int fila = 0; fila < 3; fila++)
                                  _HileraLinternas(
                                    luces: luces.sublist(fila * 3, fila * 3 + 3),
                                    t: _c.value,
                                    fila: fila,
                                    onTap: _detalle,
                                  ),
                              ],
                            );
                          },
                        ),
                      ),
                      const SizedBox(height: 18),

                      // El habitante se sienta junto a la más apagada.
                      if (hab != null)
                        TempleCard(
                          child: Row(
                            children: <Widget>[
                              SizedBox(
                                width: 54,
                                height: 54,
                                child: CustomPaint(
                                  painter: HabitantePainter(
                                    habitante: hab,
                                    estado: EstadoHabitante.atento,
                                    t: 0.3,
                                  ),
                                ),
                              ),
                              const SizedBox(width: 14),
                              Expanded(
                                child: Text(
                                  masApagada.nunca
