// 33.3 EL DOJO INTERIOR
//
// Tus récords convertidos en objetos. La barra del soporte carga los discos
// de tu mejor levantamiento: no es un número en una lista, es peso apilado.
// ---------------------------------------------------------------------------

class DojoInteriorScreen extends StatelessWidget {
  const DojoInteriorScreen({super.key, required this.usuario});

  final String usuario;

  @override
  Widget build(BuildContext context) {
    final DatosUsuario d = AlmacenTemplo.instancia.de(usuario);
    final List<RecordPersonal> records = d.records.values.toList()
      ..sort((RecordPersonal a, RecordPersonal b) =>
          b.pesoMaximo.compareTo(a.pesoMaximo));

    final RecordPersonal? mejor = records.isEmpty ? null : records.first;
    final double pesoBarra = mejor?.pesoMaximo ?? 0;

    // Agrupar récords por grupo muscular.
    final Map<GrupoMuscular, List<RecordPersonal>> porGrupo =
        <GrupoMuscular, List<RecordPersonal>>{};
    for (final RecordPersonal r in records) {
      final Ejercicio? e = ejercicioPorId(r.ejercicioId);
      if (e == null) continue;
      porGrupo.putIfAbsent(e.grupoPrincipal, () => <RecordPersonal>[]).add(r);
    }

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: SafeArea(
          child: ListView(
            padding: const EdgeInsets.fromLTRB(20, 4, 20, 34),
            children: <Widget>[
              Row(
                children: <Widget>[
                  IconButton(
                    onPressed: () => Navigator.of(context).maybePop(),
                    icon: const Icon(Icons.arrow_back_rounded,
                        color: TempleColors.textoSuave),
                  ),
                  const Expanded(
                    child: Text(
                      'El Dojo interior',
                      style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.w600,
                        color: TempleColors.blancoLuna,
                      ),
                    ),
                  ),
                  const BotonPase(),
                ],
              ),
              const SizedBox(height: 8),

              // El soporte con la barra cargada.
              ClipRRect(
                borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
                child: Container(
                  height: 190,
                  decoration: BoxDecoration(
                    border: Border.all(color: TempleColors.borde),
                    borderRadius:
                        BorderRadius.circular(TempleRadius.tarjeta),
                  ),
                  child: CustomPaint(
                    painter: _RackPainter(peso: pesoBarra),
                    child: const SizedBox.expand(),
                  ),
                ),
              ),
              const SizedBox(height: 12),
              Center(
                child: Text(
                  mejor == null
                      ? 'El soporte está vacío. Tu primer récord lo carga.'
                      : '${ejercicioPorId(mejor.ejercicioId)?.nombre ?? ""} · '
                          '${mejor.pesoMaximo.round()} kg',
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    fontSize: 13.5,
                    fontWeight: FontWeight.w600,
                    color: mejor == null
                        ? TempleColors.textoTenue
                        : TempleColors.dorado,
                  ),
                ),
              ),
              const SizedBox(height: 24),

              if (records.isEmpty)
                TempleCard(
                  child: const Text(
                    'Cada vez que superes tu marca en un ejercicio, aparecerá '
                    'aquí. Esta sala es tu fuerza convertida en objetos: se '
                    'llena sola.',
                    style: TextStyle(
                        fontSize: 12.5,
                        height: 1.55,
                        color: TempleColors.textoSuave),
                  ),
                )
              else ...<Widget>[
                EtiquetaSeccion(
                  'El muro de los récords',
                  accion: Text(
                    '${records.length}',
                    style: const TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: TempleColors.dorado,
                    ),
                  ),
                ),
                ...porGrupo.entries.map(
                  (MapEntry<GrupoMuscular, List<RecordPersonal>> e) => Padding(
                    padding: const EdgeInsets.only(bottom: 12),
                    child: TempleCard(
                      padding: const EdgeInsets.symmetric(
                          horizontal: 16, vertical: 8),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: <Widget>[
                          Padding(
                            padding: const EdgeInsets.symmetric(vertical: 6),
                            child: Text(
                              e.key.etiqueta.toUpperCase(),
                              style: const TextStyle(
                                fontSize: 10.5,
                                fontWeight: FontWeight.w600,
                                letterSpacing: 1.4,
                                color: TempleColors.violetaClaro,
                              ),
                            ),
                          ),
                          ...e.value.map((RecordPersonal r) => Padding(
                                padding:
                                    const EdgeInsets.symmetric(vertical: 9),
                                child: Row(
                                  children: <Widget>[
                                    const TempleIcon(TempleGlyph.medalla,
                                        size: 15,
                                        color: TempleColors.dorado),
                                    const SizedBox(width: 11),
                                    Expanded(
                                      child: Text(
                                        ejercicioPorId(r.ejercicioId)
                                                ?.nombre ??
                                            r.ejercicioId,
                                        style: const TextStyle(
                                            fontSize: 13,
                                            color: TempleColors.texto),
                                      ),
                                    ),
                                    Column(
                                      crossAxisAlignment:
                                          CrossAxisAlignment.end,
                                      children: <Widget>[
                                        Text(
                                          '${r.pesoMaximo.round()} kg',
                                          style: const TextStyle(
                                            fontSize: 13.5,
                                            fontWeight: FontWeight.w600,
                                            color: TempleColors.blancoLuna,
                                          ),
                                        ),
                                        Text(
                                          r.mejor1RM > 0
                                              ? '1RM ~${r.mejor1RM.round()} kg'
                                              : '${r.mejorVolumenSesion.round()} kg de volumen',
                                          style: const TextStyle(
                                              fontSize: 10,
                                              color:
