    );
  }
}

class _RackPainter extends CustomPainter {
  const _RackPainter({required this.peso});

  /// Kilos del mejor levantamiento. Define cuántos discos se apilan.
  final double peso;

  @override
  void paint(Canvas canvas, Size size) {
    final double w = size.width;
    final double h = size.height;

    // Pared de madera.
    canvas.drawRect(
      Rect.fromLTWH(0, 0, w, h),
      Paint()
        ..shader = const LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[Color(0xFF1E1729), Color(0xFF120D1C)],
        ).createShader(Rect.fromLTWH(0, 0, w, h)),
    );
    for (int i = 1; i < 7; i++) {
      canvas.drawLine(
        Offset(w * i / 7, 0),
        Offset(w * i / 7, h),
        Paint()
          ..color = Colors.black.withValues(alpha: 0.18)
          ..strokeWidth = 1,
      );
    }

    // Postes del soporte.
    final double baseY = h * 0.86;
    final Paint poste = Paint()..color = const Color(0xFF2E2440);
    canvas.drawRect(
        Rect.fromLTWH(w * 0.16, h * 0.26, w * 0.035, baseY - h * 0.26), poste);
    canvas.drawRect(
        Rect.fromLTWH(w * 0.805, h * 0.26, w * 0.035, baseY - h * 0.26), poste);
    canvas.drawRect(
        Rect.fromLTWH(w * 0.10, baseY, w * 0.80, h * 0.035), poste);

    // Ganchos.
    final Paint gancho = Paint()
      ..color = const Color(0xFF4A3B66)
      ..style = PaintingStyle.stroke
      ..strokeWidth = w * 0.012
      ..strokeCap = StrokeCap.round;
    canvas.drawLine(Offset(w * 0.178, h * 0.44),
        Offset(w * 0.225, h * 0.40), gancho);
    canvas.drawLine(Offset(w * 0.822, h * 0.44),
        Offset(w * 0.775, h * 0.40), gancho);

    // La barra.
    final double barraY = h * 0.41;
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        Rect.fromLTWH(w * 0.10, barraY - h * 0.012, w * 0.80, h * 0.024),
        Radius.circular(h * 0.012),
      ),
      Paint()
        ..shader = const LinearGradient(
          colors: <Color>[
            Color(0xFF6E6478),
            Color(0xFFBFB6C8),
            Color(0xFF6E6478),
          ],
        ).createShader(
            Rect.fromLTWH(w * 0.10, barraY - h * 0.012, w * 0.80, h * 0.024)),
    );

    // Discos: uno por cada 20 kg, máximo cinco por lado.
    final int discos = (peso / 20).floor().clamp(0, 5);
    for (int lado = 0; lado < 2; lado++) {
      for (int i = 0; i < discos; i++) {
        final double x = lado == 0
            ? w * 0.255 - i * w * 0.036
            : w * 0.745 + i * w * 0.036;
        final double alto = h * (0.30 - i * 0.028);
        final Rect disco = Rect.fromCenter(
          center: Offset(x, barraY),
          width: w * 0.030,
          height: alto,
        );
        canvas.drawRRect(
          RRect.fromRectAndRadius(disco, Radius.circular(w * 0.010)),
          Paint()
            ..shader = LinearGradient(
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter,
              colors: <Color>[
                Color.lerp(const Color(0xFF8B5CF6), Colors.white, 0.25)!,
                const Color(0xFF3B2668),
              ],
            ).createShader(disco),
        );
        canvas.drawRRect(
          RRect.fromRectAndRadius(disco, Radius.circular(w * 0.010)),
          Paint()
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1
            ..color = Colors.black.withValues(alpha: 0.35),
        );
      }
    }

    // Brillo sobre la barra si hay carga.
    if (discos > 0) {
      canvas.drawCircle(
        Offset(w / 2, barraY),
        w * 0.30,
        Paint()
          ..shader = RadialGradient(colors: <Color>[
            ColoresTradicion.dorado.withValues(alpha: 0.10),
            Colors.transparent,
          ]).createShader(
              Rect.fromCircle(center: Offset(w / 2, barraY), radius: w * 0.30)),
      );
    }
  }

  @override
  bool shouldRepaint(_RackPainter old) => old.peso != peso;
}

// ---------------------------------------------------------------------------
// 33.4 EL JARDÍN
//
// Crece con las semanas cumplidas. Cada semana planta algo y lo plantado no
// se muere nunca: una semana fallada deja un hueco, no un cadáver.
// ---------------------------------------------------------------------------

class JardinScreen extends StatefulWidget {
  const JardinScreen({super.key, required this.usuario});

  final String usuario;

  @override
  State<JardinScreen> createState() => _JardinScreenState();
}

class _JardinScreenState extends State<JardinScreen>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;

  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 22),
  );

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (MediaQuery.maybeDisableAnimationsOf(context) ?? false) {
      _c.stop();
      _c.value = 0.25;
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final MotorProgresion m = MotorProgresion.instancia;
    final List<SemanaArchivada> semanas = m.de(widget.usuario).semanas;
    final Racha racha = m.racha(widget.usuario);
    final Estacion estacion = DatosEstacion.delMes(DateTime.now().month);

    final int cumplidas =
        semanas.where((SemanaArchivada s) => s.cumplida).length;
    final int falladas = semanas.length - cumplidas;

    // Últimas 24 semanas, en orden, para dibujar el cantero.
    final List<bool> plantas = semanas
        .map((SemanaArchivada s) => s.cumplida)
        .toList()
        .reversed
        .take(24)
        .toList()
        .reversed
        .toList();

    return Scaffold(
