class _JardinPainter extends CustomPainter {
  const _JardinPainter({
    required this.plantas,
    required this.semanasTotales,
    required this.estacion,
    required this.t,
  });

  /// Una entrada por semana archivada: true = cumplida.
  final List<bool> plantas;
  final int semanasTotales;
  final Estacion estacion;
  final double t;

  @override
  void paint(Canvas canvas, Size size) {
    final double w = size.width;
    final double h = size.height;
    final Color copa = estacion.follaje;

    // Fondo y suelo.
    canvas.drawRect(
      Rect.fromLTWH(0, 0, w, h),
      Paint()
        ..shader = const LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[Color(0xFF1A1030), Color(0xFF0C0718)],
        ).createShader(Rect.fromLTWH(0, 0, w, h)),
    );
    canvas.drawPath(
      Path()
        ..moveTo(0, h * 0.58)
        ..quadraticBezierTo(w * 0.5, h * 0.50, w, h * 0.58)
        ..lineTo(w, h)
        ..lineTo(0, h)
        ..close(),
      Paint()..color = const Color(0xFF14102A),
    );

    // Muro bajo del fondo.
    canvas.drawRect(
      Rect.fromLTWH(0, h * 0.50, w, h * 0.055),
      Paint()..color = const Color(0xFF1B1430),
    );

    // El árbol central: crece con el total de semanas.
    final double escala = (0.35 + semanasTotales / 30).clamp(0.35, 1.4);
    _arbol(canvas, Offset(w * 0.5, h * 0.62), h * 0.34 * escala, copa);

    // El cantero: una planta por semana.
    if (plantas.isNotEmpty) {
      const int porFila = 12;
      for (int i = 0; i < plantas.length; i++) {
        final int fila = i ~/ porFila;
        final int col = i % porFila;
        final double x = w * (0.07 + col * 0.0715);
        final double y = h * (0.80 + fila * 0.085);
        final double meneo =
            math.sin(t * 2 * math.pi + i * 0.6) * w * 0.0035;

        if (plantas[i]) {
          // Brote: tallo y dos hojas.
          final double alto = h * 0.055;
          canvas.drawLine(
            Offset(x, y),
            Offset(x + meneo, y - alto),
            Paint()
              ..color = const Color(0xFF3E7A52)
              ..strokeWidth = 2
              ..strokeCap = StrokeCap.round,
          );
          canvas.drawOval(
            Rect.fromCenter(
              center: Offset(x + meneo - w * 0.012, y - alto * 0.75),
              width: w * 0.026,
              height: h * 0.016,
            ),
            Paint()..color = copa.withValues(alpha: 0.75),
          );
          canvas.drawOval(
            Rect.fromCenter(
              center: Offset(x + meneo + w * 0.012, y - alto * 0.95),
              width: w * 0.026,
              height: h * 0.016,
            ),
            Paint()..color = copa.withValues(alpha: 0.55),
          );
        } else {
          // Hueco: solo la piedra, sin nada plantado.
          canvas.drawOval(
            Rect.fromCenter(
                center: Offset(x, y), width: w * 0.030, height: h * 0.012),
            Paint()..color = Colors.white.withValues(alpha: 0.07),
          );
        }
      }
    }

    // Partículas de la estación.
    final math.Random rnd = math.Random(19);
    final int n = estacion == Estacion.invierno ? 24 : 12;
    for (int i = 0; i < n; i++) {
      final double s = rnd.nextDouble();
      final double fase = (t * (0.4 + s * 0.4) + s) % 1.0;
      final double x =
          w * rnd.nextDouble() + math.sin(fase * 2 * math.pi + i) * w * 0.04;
      final double y = -6 + fase * (h + 12);
      if (estacion == Estacion.invierno) {
        canvas.drawCircle(Offset(x, y), 1 + s * 1.5,
            Paint()..color = Colors.white.withValues(alpha: 0.55));
      } else {
        canvas.save();
        canvas.translate(x, y);
        canvas.rotate(fase * 6 + i);
        canvas.drawOval(
          Rect.fromCenter(center: Offset.zero, width: 6, height: 3.5),
          Paint()..color = copa.withValues(alpha: 0.45),
        );
        canvas.restore();
      }
    }
  }

  void _arbol(Canvas c, Offset base, double alto, Color copa) {
    final Paint tronco = Paint()
      ..color = const Color(0xFF2A1E1A)
      ..strokeWidth = alto * 0.10
      ..strokeCap = StrokeCap.round;

    c.drawLine(base, base.translate(-alto * 0.05, -alto * 0.55), tronco);
    // Ramas.
    c.drawLine(
        base.translate(-alto * 0.04, -alto * 0.42),
        base.translate(-alto * 0.30, -alto * 0.62),
        tronco..strokeWidth = alto * 0.05);
    c.drawLine(
        base.translate(-alto * 0.045, -alto * 0.48),
        base.translate(alto * 0.26, -alto * 0.70),
        tronco..strokeWidth = alto * 0.05);

    // Copa: cinco masas.
    final List<List<double>> masas = <List<double>>[
      <double>[-0.30, -0.66, 0.26],
      <double>[0.26, -0.74, 0.24],
      <double>[-0.02, -0.86, 0.30],
      <double>[-0.22, -0.88, 0.20],
      <double>[0.16, -0.92, 0.19],
    ];
    for (final List<double> m in masas) {
      c.drawCircle(
        base.translate(alto * m[0], alto * m[1]),
        alto * m[2],
        Paint()..color = copa.withValues(alpha: 0.30),
      );
    }
  }

  @override
  bool shouldRepaint(_JardinPainter old) =>
      old.t != t ||
      old.semanasTotales != semanasTotales ||
      old.estacion != estacion;
}

// ---------------------------------------------------------------------------
// 33.5 LOS PERGAMINOS
//
// La crónica del templo: todo lo que has hecho, en orden, como una línea de
// tiempo. Sin gráficas: aquí se viene a leer tu propia historia.
// ---------------------------------------------------------------------------

class _Cronica {
  const _Cronica({
    required this.fecha,
    required this.titulo,
    required this.detalle,
    required this.glifo,
    this.dorado = false,
  });

  final DateTime fecha;
  final String titulo;
  final String detalle;
  final TempleGlyph glifo;
  final bool dorado;
}

class PergaminosScreen extends StatelessWidget {
  const PergaminosScreen({super.key, required this.usuario});

  final String usuario;

  List<_Cronica> _construir() {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final MotorProgresion m = MotorProgresion.instancia;
    final List<_Cronica> lista = <_Cronica>[];

    for (final Sesion s in a.de(usuario).completadas) {
      lista.add(_Cronica(
        fecha: s.inicio,
        titulo: s.nombre ?? 'Sesión libre',
        detalle: '${s.volumenTotal.round()} kg · ${s.seriesEfectivas} series · '
            '${s.minutos} min',
        glifo: TempleGlyph.mancuerna,
      ));
    }

    for (final SemanaArchivada s in m.de(usuario).semanas) {
      lista.add(_Cronica(
        fecha: s.domingo,
        titulo: s.cumplida ? 'Semana cumplida' : 'Semana incompleta',
        detalle: '${s.etiqueta} · ${s.sesiones}/${s.objetivo} sesiones · '
            '${(s.volumen / 1000).toStringAsFixed(1)} t',
        glifo: s.cumplida ? TempleGlyph.llama : TempleGlyph.luna,
        dorado: s.cumplida,
      ));
    }

    for (final RecordPersonal r in a.de(usuario).records.values) {
      lista.add(_Cronica(
        fecha: r.fecha,
        titulo: 'Récord: ${ejercicioPorId(r.ejercicioId)?.nombre ?? r.ejercicioId}',
        detalle: '${r.pesoMaximo.round()} kg de peso máximo',
        glifo: TempleGlyph.medalla,
        dorado: true,
      ));
    }

    lista.sort((_Cronica x, _Cronica y) => y.fecha.compareTo(x.fecha));
    return lista.take(60).toList();
  }

  @override
  Widget build(BuildContext context) {
    final MotorProgresion m = MotorProgresion.instancia;
    final EstadoProgreso prog = m.de(usuario);
    final List<Titulo> titulos = m.titulosGanados(usuario);
    final DefinicionClase? clase =
        prog.clase == null ? null : ClasesDelTemplo.todas[prog.clase!];
    final List<_Cronica> cronica = _construir();

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: SafeArea(
          child: ListView(
            padding: const EdgeInsets.fromLTRB(20, 4, 20, 34),
            children: <Widget>[
              Row(
                children: <Widget>[
                  IconButton(
                    onPressed: () => Navigator.of(context).maybePop(),
                    icon: const Icon(Icons.arrow_back_rounded,
                        color: TempleColors.textoSuave),
                  ),
                  const Expanded(
                    child: Text(
                      'Los pergaminos',
                      style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.w600,
                        color: TempleColors.blancoLuna,
                      ),
                    ),
                  ),
                  const BotonPase(),
                ],
              ),
              const SizedBox(height: 8),

              if (clase != null) ...<Widget>[
                TempleCard(
                  destacada: true,
                  child: Row(
                    children: <Widget>[
                      TempleIcon(clase.glifo,
                          size: 26, color: TempleColors.violetaClaro),
                      const SizedBox(width: 14),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: <Widget>[
                            Text(
                              clase.nombre,
                              style: const TextStyle(
                                fontSize: 16,
                                fontWeight: FontWeight.w600,
                                color: TempleColors.blancoLuna,
                              ),
                            ),
                            Text(
                              '${clase.kanji} · ${clase.lema}',
                              style: const TextStyle(
                                  fontSize: 12,
                                  color: TempleColors.violetaClaro),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 20),
              ],

              if (titulos.isNotEmpty) ...<Widget>[
                EtiquetaSeccion(
                  'Títulos ganados',
                  accion: Text(
                    '${titulos.length}',
                    style: const TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: TempleColors.violetaClaro,
                    ),
                  ),
                ),
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: titulos
                      .map((Titulo t) => Container(
                            padding: const EdgeInsets.symmetric(
                                horizontal: 11, vertical: 7),
                            decoration: BoxDecoration(
                              color: (t.raro
                                      ? TempleColors.dorado
                                      : TempleColors.violeta)
                                  .withValues(alpha: 0.12),
                              borderRadius: BorderRadius.circular(999),
                              border: Border.all(
                                color: (t.raro
                                        ? TempleColors.dorado
                                        : TempleColors.violeta)
                                    .withValues(alpha: 0.32),
                              ),
                            ),
                            child: Text(
                              t.texto,
                              style: TextStyle(
                                fontSize: 11.5,
                                color: t.raro
                                    ? TempleColors.dorado
                                    : TempleColors.violetaClaro,
                              ),
                            ),
                          ))
                      .toList(),
                ),
                const SizedBox(height: 22),
              ],

              const EtiquetaSeccion('La crónica'),
              if (cronica.isEmpty)
                TempleCard(
                  child: const Text(
                    'Todavía no hay nada escrito. Tu primera sesión abre el '
                    'primer pergamino.',
                    style: TextStyle(
                        fontSize: 12.5,
                        height: 1.5,
                        color: TempleColors.textoSuave),
                  ),
                )
              else
                ...cronica.map((_Cronica c) => _FilaCronica(entrada: c)),
            ],
          ),
        ),
      ),
    );
  }
}

class _FilaCronica extends StatelessWidget {
  const _FilaCronica({required this.entrada});

  final _Cronica entrada;

  String get _fecha {
    const List<String> meses = <String>[
      'ene', 'feb', 'mar', 'abr', 'may', 'jun',
      'jul', 'ago', 'sep', 'oct', 'nov', 'dic'
    ];
    return '${entrada.fecha.day} ${meses[entrada.fecha.month - 1]}';
  }

  @override
  Widget build(BuildContext context) {
    final Color c =
        entrada.dorado ? TempleColors.dorado : TempleColors.violetaClaro;

    return IntrinsicHeight(
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: <Widget>[
          // Línea de tiempo.
          SizedBox(
            width: 46,
            child: Column(
              children: <Widget>[
                Container(
                  width: 26,
                  height: 26,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: c.withValues(alpha: 0.14),
                    border: Border.all(color: c.withValues(alpha: 0.40)),
                  ),
                  child: Center(
                    child: TempleIcon(entrada.glifo, size: 13, color: c),
                  ),
                ),
                Expanded(
                  child: Container(
                    width: 1,
                    color: TempleColors.borde,
                  ),
                ),
              ],
            ),
          ),
          Expanded(
            child: Padding(
              padding: const EdgeInsets.only(bottom: 14),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Row(
                    children: <Widget>[
                      Expanded(
                        child: Text(
                          entrada.titulo,
                          style: const TextStyle(
                            fontSize: 13.5,
                            fontWeight: FontWeight.w600,
                            color: TempleColors.texto,
                          ),
                        ),
                      ),
                      Text(
                        _fecha,
                        style: const TextStyle(
                            fontSize: 10.5, color: TempleColors.textoTenue),
                      ),
                    ],
                  ),
                  const SizedBox(height: 3),
                  Text(
                    entrada.detalle,
                    style: const TextStyle(
                        fontSize: 11.5, color: TempleColors.textoSuave),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

// ---------------------------------------------------------------------------
// 33.6 LA HOGUERA
//
// El sitio tranquilo. La llama arde según lo recuperado que estés, y desde
// aquí se entra a recuperación y a nutrición.
// ---------------------------------------------------------------------------

class HogueraScreen extends StatefulWidget {
  const HogueraScreen({
    super.key,
    required this.usuario,
    required this.espiritu,
  });

  final String usuario;
  final String espiritu;

  @override
  State<HogueraScreen> createState() => _HogueraScreenState();
}

class _HogueraScreenState extends State<HogueraScreen>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 3),
  );

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (MediaQuery.maybeDisableAnimationsOf(context) ?? false) {
      _c.stop();
      _c.value = 0.3;
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final AlmacenRecuperacion ar = AlmacenRecuperacion.instancia;
    final int indice = ar.indice(widget.usuario);
    final EstadoRecuperacion est = ar.de(widget.usuario, DateTime.now());
    final RegistroDiario diario = a.registroDe(widget.usuario, DateTime.now());
    final List<AvisoSalud> avisos = VigilanciaCuerpo.evaluar(widget.usuario);
    final List<RitualRecuperacion> rituales =
        RitualesDelTemplo.paraHoy(widget.usuario, est, diario.horasSueno);
    final RitualRecuperacion ritual =
        rituales[DateTime.now().day % rituales.length];

    final Color fuego = indice >= 72
        ? const Color(0xFFF2C14E)
        : indice >= 45
            ? const Color(0xFFEE7B3C)
            : const Color(0xFF8A5A44);

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: Container(
        decoration: const BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: <Color>[
              Color(0xFF1A0F16),
              Color(0xFF0D0810),
              Color(0xFF06040A),
            ],
          ),
        ),
        child: SafeArea(
          child: ListView(
            padding: const EdgeInsets.fromLTRB(20, 4, 20, 34),
            children: <Widget>[
              Row(
                children: <Widget>[
                  IconButton(
                    onPressed: () => Navigator.of(context).maybePop(),
                    icon: const Icon(Icons.arrow_back_rounded,
                        color: TempleColors.textoSuave),
                  ),
                  const Expanded(
                    child: Text(
                      'La hoguera',
                      style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.w600,
                        color: TempleColors.blancoLuna,
                      ),
                    ),
                  ),
                  const BotonPase(),
                ],
              ),

              SizedBox(
                height: 230,
                child: RepaintBoundary(
                  child: AnimatedBuilder(
                    animation: _c,
                    builder: (BuildContext context, _) => CustomPaint(
                      painter: _LlamaPainter(
                        t: _c.value,
                        color: fuego,
                        intensidad: (indice / 100).clamp(0.15, 1.0),
                        viva: indice > 12,
                      ),
                    ),
                  ),
                ),
              ),

              Center(
                child: Column(
                  children: <Widget>[
                    Text(
                      '$indice',
                      style: const TextStyle(
                        fontSize: 34,
                        height: 1,
                        fontWeight: FontWeight.w600,
                        color: TempleColors.blancoLuna,
                      ),
                    ),
                    const SizedBox(height: 6),
                    const Text(
                      'ÍNDICE DE RECUPERACIÓN',
                      style: TextStyle(
                        fontSize: 10,
                        letterSpacing: 3,
                        color: TempleColors.textoSuave,
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 26),

              if (avisos.isNotEmpty) ...<Widget>[
                ...avisos.take(1).map((AvisoSalud av) {
