// ---------------------------------------------------------------------------
// 33.7 EL HABITANTE
//
// REGLA QUE NO SE ROMPE: el habitante nunca sufre, nunca enferma y nunca
// reprocha. Si no entrenas, se echa a dormir. Si vuelves después de un mes,
// se alegra igual. Los animales virtuales que se mueren generan culpa, y la
// culpa hace que la gente desinstale para dejar de sentirla.
// ---------------------------------------------------------------------------

enum Habitante { zorro, grulla, tanuki, gato }

enum EstadoHabitante { durmiendo, tranquilo, atento, alegre }

class DefinicionHabitante {
  const DefinicionHabitante({
    required this.habitante,
    required this.nombre,
    required this.kanji,
    required this.descripcion,
    required this.comoSeGana,
    required this.color,
  });

  final Habitante habitante;
  final String nombre;
  final String kanji;
  final String descripcion;
  final String comoSeGana;
  final Color color;
}

class Habitantes {
  const Habitantes._();

  static const Map<Habitante, DefinicionHabitante> todos =
      <Habitante, DefinicionHabitante>{
    Habitante.zorro: DefinicionHabitante(
      habitante: Habitante.zorro,
      nombre: 'Kitsune',
      kanji: '狐',
      descripcion:
          'El zorro blanco de los santuarios. Vigila la puerta y no se va '
          'nunca, aunque tú tardes en volver.',
      comoSeGana: 'Completa tu primera sesión',
      color: Color(0xFFEDE6F8),
    ),
    Habitante.grulla: DefinicionHabitante(
      habitante: Habitante.grulla,
      nombre: 'Tsuru',
      kanji: '鶴',
      descripcion:
          'La grulla vive mil años según el dicho. Aparece cuando demuestras '
          'que sabes sostener algo en el tiempo.',
      comoSeGana: 'Cumple cuatro semanas seguidas',
      color: Color(0xFFDCE8F5),
    ),
    Habitante.tanuki: DefinicionHabitante(
      habitante: Habitante.tanuki,
      nombre: 'Tanuki',
      kanji: '狸',
      descripcion:
          'El perro mapache de la panza redonda. Símbolo de abundancia: llega '
          'cuando el templo pesa de verdad.',
      comoSeGana: 'Acumula 50 toneladas de peso del templo',
      color: Color(0xFFC9A87C),
    ),
    Habitante.gato: DefinicionHabitante(
      habitante: Habitante.gato,
      nombre: 'Maneki',
      kanji: '猫',
      descripcion:
          'El gato que llama a la suerte con la pata levantada. Solo se '
          'presenta ante quien ya lleva un buen camino andado.',
      comoSeGana: 'Alcanza el nivel 15',
      color: Color(0xFFF0D9B5),
    ),
  };

  static bool desbloqueado(String usuario, Habitante h) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final MotorProgresion m = MotorProgresion.instancia;
    switch (h) {
      case Habitante.zorro:
        return a.de(usuario).completadas.isNotEmpty;
      case Habitante.grulla:
        return m.racha(usuario).semanas >= 4;
      case Habitante.tanuki:
        return a.pesoDelTemplo(usuario) >= 50000;
      case Habitante.gato:
        return NivelTemplo.desdeXp(a.de(usuario).xpGeneral).nivel >= 15;
    }
  }

  /// Qué está haciendo hoy. Nunca hay un estado negativo.
  static EstadoHabitante estado(String usuario) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    if (a.entrenoEse(usuario, DateTime.now())) return EstadoHabitante.alegre;
    final int llama = a.llama(usuario).valor;
    if (llama >= 60) return EstadoHabitante.atento;
    if (llama >= 25) return EstadoHabitante.tranquilo;
    return EstadoHabitante.durmiendo;
  }

  static String frase(EstadoHabitante e, String nombre) {
    switch (e) {
      case EstadoHabitante.alegre:
        return '$nombre te vio entrenar hoy y no ha parado de dar vueltas '
            'por el patio.';
      case EstadoHabitante.atento:
        return '$nombre está despierto, sentado junto a la puerta. Sabe que '
            'vuelves pronto.';
      case EstadoHabitante.tranquilo:
        return '$nombre descansa al sol, sin prisa. El templo está en calma.';
      case EstadoHabitante.durmiendo:
        return '$nombre se echó a dormir. No pasa nada: se despierta en '
            'cuanto vuelvas.';
    }
  }
}

class AlmacenHabitante {
  AlmacenHabitante._();
  static final AlmacenHabitante instancia = AlmacenHabitante._();

  final Map<String, Habitante> _elegidos = <String, Habitante>{};

  Habitante? elegido(String usuario) {
    final Habitante? h = _elegidos[usuario];
    if (h != null && Habitantes.desbloqueado(usuario, h)) return h;
    for (final Habitante x in Habitante.values) {
      if (Habitantes.desbloqueado(usuario, x)) return x;
    }
    return null;
  }

  void elegir(String usuario, Habitante h) {
    if (Habitantes.desbloqueado(usuario, h)) _elegidos[usuario] = h;
  }
}

/// Dibujo del habitante. Cuatro criaturas, cuatro estados.
class HabitantePainter extends CustomPainter {
  const HabitantePainter({
    required this.habitante,
    required this.estado,
    required this.t,
  });

  final Habitante habitante;
  final EstadoHabitante estado;
  final double t;

  @override
  void paint(Canvas canvas, Size size) {
    final double s = size.shortestSide;
    final Offset c = Offset(size.width / 2, size.height * 0.62);
    final Color col = Habitantes.todos[habitante]!.color;
    final bool duerme = estado == EstadoHabitante.durmiendo;

    // Respiración: el cuerpo sube y baja.
    final double resp =
        math.sin(t * 2 * math.pi * (duerme ? 0.6 : 1.4)) * s * 0.012;

    canvas.save();
    canvas.translate(0, resp);

    switch (habitante) {
      case Habitante.zorro:
        _zorro(canvas, c, s, col, duerme);
      case Habitante.grulla:
        _grulla(canvas, c, s, col, duerme);
      case Habitante.tanuki:
        _tanuki(canvas, c, s, col, duerme);
      case Habitante.gato:
        _gato(canvas, c, s, col, duerme);
    }

    canvas.restore();

    // Zetas de sueño.
    if (duerme) {
      for (int i = 0; i < 3; i++) {
        final double fase = (t * 0.8 + i * 0.33) % 1.0;
        final TextPainter tp = TextPainter(
          text: TextSpan(
            text: 'z',
            style: TextStyle(
              fontSize: s * (0.10 + fase * 0.05),
              color: Colors.white.withValues(alpha: 0.45 * (1 - fase)),
            ),
          ),
          textDirection: TextDirection.ltr,
        )..layout();
        tp.paint(
          canvas,
          Offset(c.dx + s * 0.20 + fase * s * 0.10,
              c.dy - s * 0.30 - fase * s * 0.22),
        );
      }
    }

    // Chispa de alegría.
    if (estado == EstadoHabitante.alegre) {
      for (int i = 0; i < 4; i++) {
        final double a = t * 2 * math.pi + i * math.pi / 2;
        canvas.drawCircle(
          c.translate(math.cos(a) * s * 0.34, -s * 0.16 + math.sin(a) * s * 0.14),
          s * 0.014,
          Paint()
            ..color = ColoresTradicion.dorado.withValues(
                alpha: 0.4 + 0.4 * math.sin(t * 2 * math.pi * 3 + i)),
        );
      }
    }
  }

  void _ojos(Canvas c, Offset cabeza, double s, bool duerme, double sep) {
    final Paint p = Paint()
      ..color = const Color(0xFF241C2E)
      ..strokeWidth = s * 0.018
      ..strokeCap = StrokeCap.round;
    if (duerme) {
      for (int i = -1; i <= 1; i += 2) {
        c.drawArc(
          Rect.fromCenter(
            center: cabeza.translate(sep * i, 0),
            width: s * 0.075,
            height: s * 0.055,
          ),
          0.2,
          2.7,
          false,
          p..style = PaintingStyle.stroke,
        );
      }
    } else {
      c.drawCircle(cabeza.translate(-sep, 0), s * 0.022,
          Paint()..color = const Color(0xFF241C2E));
      c.drawCircle(cabeza.translate(sep, 0), s * 0.022,
          Paint()..color = const Color(0xFF241C2E));
    }
  }

  void _zorro(Canvas c, Offset base, double s, Color col, bool duerme) {
    final Paint cuerpo = Paint()..color = col.withValues(alpha: 0.92);

    // Cola.
    c.drawPath(
      Path()
        ..moveTo(base.dx + s * 0.10, base.dy + s * 0.02)
        ..quadraticBezierTo(base.dx + s * 0.40, base.dy - s * 0.02,
            base.dx + s * 0.28, base.dy - s * 0.24),
      Paint()
        ..color = col.withValues(alpha: 0.75)
        ..style = PaintingStyle.stroke
        ..strokeWidth = s * 0.10
        ..strokeCap = StrokeCap.round,
    );

    // Cuerpo sentado.
    c.drawPath(
      Path()
        ..moveTo(base.dx - s * 0.16, base.dy + s * 0.08)
        ..quadraticBezierTo(base.dx - s * 0.14, base.dy - s * 0.14,
            base.dx, base.dy - s * 0.16)
        ..quadraticBezierTo(base.dx + s * 0.14, base.dy - s * 0.14,
            base.dx + s * 0.16, base.dy + s * 0.08)
        ..close(),
      cuerpo,
    );

    // Cabeza con orejas.
    final Offset cab = base.translate(0, -s * 0.24);
    c.drawPath(
      Path()
        ..moveTo(cab.dx - s * 0.13, cab.dy - s * 0.08)
        ..lineTo(cab.dx - s * 0.16, cab.dy - s * 0.20)
        ..lineTo(cab.dx - s * 0.05, cab.dy - s * 0.12)
        ..lineTo(cab.dx + s * 0.05, cab.dy - s * 0.12)
        ..lineTo(cab.dx + s * 0.16, cab.dy - s * 0.20)
        ..lineTo(cab.dx + s * 0.13, cab.dy - s * 0.08)
        ..quadraticBezierTo(
            cab.dx + s * 0.13, cab.dy + s * 0.10, cab.dx, cab.dy + s * 0.11)
        ..quadraticBezierTo(cab.dx - s * 0.13, cab.dy + s * 0.10,
            cab.dx - s * 0.13, cab.dy - s * 0.08)
        ..close(),
      cuerpo,
    );

    _ojos(c, cab.translate(0, -s * 0.01), s, duerme, s * 0.055);
    c.drawCircle(cab.translate(0, s * 0.055), s * 0.016,
        Paint()..color = const Color(0xFF7A4A52));
  }

  void _grulla(Canvas c, Offset base, double s, Color col, bool duerme) {
    final Paint cuerpo = Paint()..color = col.withValues(alpha: 0.92);

    // Patas.
    for (int i = -1; i <= 1; i += 2) {
      c.drawLine(
        base.translate(i * s * 0.04, base.dy > 0 ? s * 0.02 : 0),
        base.translate(i * s * 0.05, s * 0.16),
        Paint()
          ..color = const Color(0xFF3A3040)
          ..strokeWidth = s * 0.016
          ..strokeCap = StrokeCap.round,
      );
    }

    // Cuerpo.
    c.drawOval(
      Rect.fromCenter(
          center: base, width: s * 0.34, height: s * 0.24),
      cuerpo,
    );

    // Cuello y cabeza.
    final Offset cab = base.translate(s * 0.10, -s * 0.30);
    c.drawPath(
      Path()
        ..moveTo(base.dx + s * 0.06, base.dy - s * 0.08)
        ..quadraticBezierTo(base.dx + s * 0.18, base.dy - s * 0.22,
            cab.dx, cab.dy + s * 0.03),
      Paint()
        ..color = col.withValues(alpha: 0.9)
        ..style = PaintingStyle.stroke
        ..strokeWidth = s * 0.055
        ..strokeCap = StrokeCap.round,
    );
    c.drawCircle(cab, s * 0.055, cuerpo);
    // Copete rojo.
    c.drawCircle(cab.translate(0, -s * 0.04), s * 0.022,
        Paint()..color = const Color(0xFFC0433F));
    // Pico.
    c.drawLine(
      cab.translate(s * 0.04, 0),
      cab.translate(s * 0.15, s * 0.01),
      Paint()
        ..color = const Color(0xFF3A3040)
        ..strokeWidth = s * 0.016
        ..strokeCap = StrokeCap.round,
    );
    _ojos(c, cab.translate(0, -s * 0.005), s * 0.7, duerme, s * 0.02);
  }

  void _tanuki(Canvas c, Offset base, double s, Color col, bool duerme) {
    final Paint cuerpo = Paint()..color = col.withValues(alpha: 0.92);

    // Panza.
    c.drawOval(
      Rect.fromCenter(
          center: base.translate(0, -s * 0.02),
          width: s * 0.40,
          height: s * 0.34),
      cuerpo,
    );
    c.drawOval(
      Rect.fromCenter(
          center: base.translate(0, s * 0.02),
          width: s * 0.24,
          height: s * 0.20),
      Paint()..color = Color.lerp(col, Colors.white, 0.35)!,
    );

    // Cabeza.
    final Offset cab = base.translate(0, -s * 0.26);
    c.drawCircle(cab, s * 0.15, cuerpo);
    for (int i = -1; i <= 1; i += 2) {
      c.drawCircle(cab.translate(i * s * 0.13, -s * 0.11), s * 0.05,
          Paint()..color = Color.lerp(col, Colors.black, 0.3)!);
    }
    // Antifaz.
    for (int i = -1; i <= 1; i += 2) {
      c.drawOval(
        Rect.fromCenter(
          center: cab.translate(i * s * 0.055, 0),
          width: s * 0.09,
          height: s * 0.07,
        ),
        Paint()..color = Color.lerp(col, Colors.black, 0.45)!,
      );
    }
    _ojos(c, cab, s, duerme, s * 0.055);
    c.drawCircle(cab.translate(0, s * 0.05), s * 0.018,
        Paint()..color = const Color(0xFF2A2028));
  }

  void _gato(Canvas c, Offset base, double s, Color col, bool duerme) {
    final Paint cuerpo = Paint()..color = col.withValues(alpha: 0.92);

    // Cola enroscada.
    c.drawArc(
      Rect.fromCircle(
          center: base.translate(s * 0.20, s * 0.02), radius: s * 0.11),
      -1.0,
      4.2,
      false,
      Paint()
        ..color = col.withValues(alpha: 0.85)
        ..style = PaintingStyle.stroke
        ..strokeWidth = s * 0.045
        ..strokeCap = StrokeCap.round,
    );

    // Cuerpo.
    c.drawPath(
      Path()
        ..moveTo(base.dx - s * 0.15, base.dy + s * 0.09)
        ..quadraticBezierTo(base.dx - s * 0.15, base.dy - s * 0.13,
            base.dx, base.dy - s * 0.15)
        ..quadraticBezierTo(base.dx + s * 0.15, base.dy - s * 0.13,
            base.dx + s * 0.15, base.dy + s * 0.09)
        ..close(),
      cuerpo,
    );

    // Pata levantada, la del maneki-neko.
    c.drawLine(
      base.translate(-s * 0.10, -s * 0.05),
      base.translate(-s * 0.17, -s * 0.19),
      Paint()
        ..color = col
        ..strokeWidth = s * 0.045
        ..strokeCap = StrokeCap.round,
    );

    // Cabeza con orejas.
    final Offset cab = base.translate(0, -s * 0.25);
    c.drawCircle(cab, s * 0.135, cuerpo);
    for (int i = -1; i <= 1; i += 2) {
      c.drawPath(
        Path()
          ..moveTo(cab.dx + i * s * 0.05, cab.dy - s * 0.11)
          ..lineTo(cab.dx + i * s * 0.13, cab.dy - s * 0.21)
          ..lineTo(cab.dx + i * s * 0.14, cab.dy - s * 0.07)
          ..close(),
        cuerpo,
      );
    }
    _ojos(c, cab.translate(0, -s * 0.01), s, duerme, s * 0.05);
    c.drawCircle(cab.translate(0, s * 0.045), s * 0.014,
        Paint()..color = const Color(0xFFC0736F));
    // Collar.
    c.drawArc(
      Rect.fromCircle(center: cab, radius: s * 0.14),
      0.5,
      2.1,
      false,
      Paint()
        ..color = const Color(0xFFC0433F)
        ..style = PaintingStyle.stroke
        ..strokeWidth = s * 0.022,
    );
  }

  @override
  bool shouldRepaint(HabitantePainter old) =>
      old.t != t || old.habitante != habitante || old.estado != estado;
}

class HabitanteScreen extends StatefulWidget {
  const HabitanteScreen({super.key, required this.usuario});

  final String usuario;

  @override
  State<HabitanteScreen> createState() => _HabitanteScreenState();
}

class _HabitanteScreenState extends State<HabitanteScreen>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 5),
  );

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (MediaQuery.maybeDisableAnimationsOf(context) ?? false) {
      _c.stop();
      _c.value = 0.3;
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final AlmacenHabitante ah = AlmacenHabitante.instancia;
    final Habitante? elegido = ah.elegido(widget.usuario);
