class InteriorCasa extends StatelessWidget {
  const InteriorCasa({super.key, required this.usuario, required this.espiritu});

  final String usuario;
  final String espiritu;

  @override
  Widget build(BuildContext context) {
    final List<LuzMusculo> luces = LuzMusculo.todas(usuario);
    final int encendidas =
        luces.where((LuzMusculo l) => l.brillo > 0.55).length;
    final int records = AlmacenTemplo.instancia.de(usuario).records.length;
    final int semanas = MotorProgresion.instancia
        .de(usuario)
        .semanas
        .where((SemanaArchivada s) => s.cumplida)
        .length;
    final int recuperacion = AlmacenRecuperacion.instancia.indice(usuario);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: <Widget>[
        _AccesoSala(
          glifo: TempleGlyph.chispa,
          titulo: 'La Sala de los Nueve',
          nota: '$encendidas de 9 linternas encendidas',
          onTap: () => Navigator.of(context).push(
            MaterialPageRoute<void>(
              builder: (_) => SalaNueveScreen(usuario: usuario),
            ),
          ),
        ),
        _AccesoSala(
          glifo: TempleGlyph.mancuerna,
          titulo: 'El Dojo interior',
          nota: records == 0
              ? 'El soporte está vacío'
              : '$records récord${records == 1 ? "" : "s"} en el muro',
          onTap: () => Navigator.of(context).push(
            MaterialPageRoute<void>(
              builder: (_) => DojoInteriorScreen(usuario: usuario),
            ),
          ),
        ),
        _AccesoSala(
          glifo: TempleGlyph.loto,
          titulo: 'El jardín',
          nota: semanas == 0
              ? 'El cantero está vacío'
              : '$semanas semana${semanas == 1 ? "" : "s"} plantada${semanas == 1 ? "" : "s"}',
          onTap: () => Navigator.of(context).push(
            MaterialPageRoute<void>(
              builder: (_) => JardinScreen(usuario: usuario),
