// ===========================================================================
// TEMPLE OF STRENGTH — SECCIÓN 34: TENSHI IA  (versión 2 — mente completa)
//
// SUSTITUYE a la sección 34 anterior entera. Borra desde el encabezado
// «SECCIÓN 34: TENSHI IA» hasta el final del archivo y pega esto en su lugar.
//
// Y borra también, si sigue ahí, la clase `TenshiScreen` de la sección 15
// (el andamio que devuelve PantallaEnForja). Dos clases con el mismo nombre
// es lo que provoca «TenshiScreen doesn't conform to the bound».
//
// AL PRINCIPIO DE main.dart, junto a los demás imports, añade estas dos
// líneas. Van con prefijo a propósito: así es imposible que choquen con
// ningún nombre de tus 28.000 líneas, y si ya importas dart:convert sin
// prefijo, no pasa nada por tenerlo dos veces.
//
//     import 'dart:convert' as convert;
//     import 'package:http/http.dart' as http;   (flutter pub add http)
//
// QUÉ CAMBIA RESPECTO A LA VERSIÓN 1
//
//   · Tenshi piensa con un modelo de lenguaje real. Conversa de lo que sea:
//     tu día, tu trabajo, una duda cualquiera, cómo te sientes. Conecta con el
//     entrenamiento cuando tiene sentido, sin forzarlo.
//   · Recuerda. Lo que le cuentas de ti queda guardado y lo usa después sin
//     anunciarlo. Puedes ver y borrar sus recuerdos desde la pantalla.
//   · Escribe en vivo, palabra a palabra.
//   · Las sugerencias de abajo ya no son fijas: las propone el propio modelo
//     según lo que estáis hablando.
//   · Puede abrir pantallas del templo cuando viene a cuento (el Camino, la
//     guía de comida, la hoguera…).
//
// QUÉ NO CAMBIA
//
//   · Sin configurar, funciona igual que antes con el cerebro local. Nada se
//     rompe: en cuanto rellenes TenshiConfig (34.6), pasa a la mente completa.
//   · Si se cae la red, responde el cerebro local y lo dice.
//   · La crisis NUNCA sale a la red: la responde la app, antes que nadie.
//   · Los límites de seguridad viven en el servidor, no en el cliente: un APK
//     modificado no puede quitárselos.
//
//   34.1  Voz y turnos
//   34.2  La guardia: registro del turno y auxilio
//   34.3  Lo que Tenshi sabe de ti
//   34.4  Temas y detección (solo cerebro local)
//   34.5  El cerebro local (respaldo sin red)
//   34.6  La mente: configuración, intérprete y conexión
//   34.7  La conversación y la memoria
//   34.8  El avatar
//   34.9  La pantalla
// ===========================================================================

// ---------------------------------------------------------------------------
// 34.1 VOZ Y TURNOS
//
// La voz NO se elige aquí: ya la elegiste en El Ascenso («¿Cómo quieres que
// te hable Tenshi?»). Esta sección la lee de `ascenso['voz']` y la respeta.
// Desde la pantalla se puede cambiar, y al cambiarla cambian también los
// avisos de la sección 29: es la misma voz en toda la app.
// ---------------------------------------------------------------------------

enum TonoTenshi { serena, alegre, exigente }

extension DatosTono on TonoTenshi {
  /// Clave que se guarda en `ascenso['voz']`. No traducir.
  String get clave {
    switch (this) {
      case TonoTenshi.serena:
        return 'serena';
      case TonoTenshi.alegre:
        return 'alegre';
      case TonoTenshi.exigente:
        return 'exigente';
    }
  }

  String get titulo {
    switch (this) {
      case TonoTenshi.serena:
        return 'Con calma';
      case TonoTenshi.alegre:
        return 'Con chispa';
      case TonoTenshi.exigente:
        return 'Sin rodeos';
    }
  }

  String get descripcion {
    switch (this) {
      case TonoTenshi.serena:
        return 'Te acompaña. Celebra que apareciste, no cuánto levantaste.';
      case TonoTenshi.alegre:
        return 'Cercana y animada. Se alegra de tus cosas más que tú.';
      case TonoTenshi.exigente:
        return 'Directa. Te dice lo que estás evitando y espera que vuelvas.';
    }
  }

  /// El usuario elige oyendo, no leyendo una etiqueta.
  String get ejemplo {
    switch (this) {
      case TonoTenshi.serena:
        return 'Tres días fuera no borran lo anterior. Entra cuando puedas.';
      case TonoTenshi.alegre:
        return 'Tres días desaparecido, ¿eh? Venga, que hoy es fácil volver.';
      case TonoTenshi.exigente:
        return 'Tres días. La espalda te está esperando y tú lo sabes.';
    }
  }

  TempleGlyph get glifo {
    switch (this) {
      case TonoTenshi.serena:
        return TempleGlyph.loto;
      case TonoTenshi.alegre:
        return TempleGlyph.chispa;
      case TonoTenshi.exigente:
        return TempleGlyph.espadas;
    }
  }

  /// Acento cromático. Es el único punto de la app donde el acento se aparta
  /// del violeta: el usuario debe VER qué voz eligió.
  Color get acento {
    switch (this) {
      case TonoTenshi.serena:
        return const Color(0xFFD9A7D4);
      case TonoTenshi.alegre:
        return TempleColors.violetaClaro;
      case TonoTenshi.exigente:
        return const Color(0xFF7C8AD6);
    }
  }

  static TonoTenshi desdeClave(String? c) {
    switch (c) {
      case 'alegre':
        return TonoTenshi.alegre;
      case 'exigente':
        return TonoTenshi.exigente;
      default:
        return TonoTenshi.serena;
    }
  }
}

enum AutorTurno { usuario, tenshi }

/// Un turno de la conversación.
class TurnoTenshi {
  const TurnoTenshi({
    required this.id,
    required this.autor,
    required this.texto,
    required this.creadoEn,
    this.kokoro = false,
    this.auxilio = false,
    this.sugerencias = const <SugerenciaTenshi>[],
  });

  final String id;
  final AutorTurno autor;
  final String texto;
  final DateTime creadoEn;

  /// El turno se respondió en registro emocional, no técnico.
  final bool kokoro;

  /// Respuesta escrita por la app, no por el cerebro. Solo en crisis.
  final bool auxilio;

  /// Accesos que Tenshi ofrece debajo de su respuesta.
  final List<SugerenciaTenshi> sugerencias;
}

/// Acceso rápido contextual. No son botones fijos: se generan con tus datos,
/// así que cambian cada día.
class SugerenciaTenshi {
  const SugerenciaTenshi({
    required this.etiqueta,
    required this.mensaje,
    required this.glifo,
    this.destino,
  });

  /// Lo que ve el usuario.
  final String etiqueta;

  /// Lo que se envía realmente al tocarlo.
  final String mensaje;

  final TempleGlyph glifo;

  /// Si no es null, en vez de escribir lleva a otra pantalla del templo.
  final void Function(BuildContext)? destino;
}

// ---------------------------------------------------------------------------
// 34.2 LA GUARDIA
//
// Decide en qué registro entra cada turno ANTES de que el cerebro vea nada.
//
//   tecnico  — flujo normal.
//   kokoro   — turno emocional. Tenshi escucha y NO propone entrenar.
//              Anula el tono exigente: quien llega roto no recibe exigencia.
//   crisis   — la app responde por su cuenta, sin cerebro y sin voz.
//
// Sobre por qué la crisis no pasa por ninguna generación de texto: una
// respuesta improvisada frente a alguien en riesgo es un resultado
// inaceptable, por buena que sea el 95% de las veces. Aquí responde un texto
// escrito por personas, con recursos verificables.
// ---------------------------------------------------------------------------

enum RegistroTurno { tecnico, kokoro, crisis }

class GuardiaTenshi {
  const GuardiaTenshi._();

  static RegistroTurno evaluar(String texto) {
    final String t = normalizar(texto);
    if (_alguna(t, _crisis)) return RegistroTurno.crisis;
    if (_alguna(t, _kokoro)) return RegistroTurno.kokoro;
    return RegistroTurno.tecnico;
  }

  /// Quita tildes y baja a minúsculas: la detección no puede depender de cómo
  /// escriba la persona.
  static String normalizar(String s) {
    const Map<String, String> m = <String, String>{
      'á': 'a', 'é': 'e', 'í': 'i', 'ó': 'o', 'ú': 'u', 'ü': 'u', 'ñ': 'n',
    };
    String r = s.toLowerCase();
    m.forEach((String k, String v) => r = r.replaceAll(k, v));
    return r;
  }

  static bool _alguna(String texto, List<String> claves) =>
      claves.any(texto.contains);

  /// Señales de riesgo. Centradas en la intención y la desesperanza, nunca en
  /// métodos: esta lista no describe ninguna forma de hacerse daño.
  static const List<String> _crisis = <String>[
    'quiero morir',
    'quiero morirme',
    'no quiero vivir',
    'no quiero seguir viviendo',
    'ya no quiero estar',
    'me quiero matar',
    'quitarme la vida',
    'acabar con todo',
    'terminar con todo',
    'seria mejor si no estuviera',
    'estarian mejor sin mi',
    'no vale la pena vivir',
    'hacerme dano',
    'lastimarme',
    'me quiero desaparecer',
    'no aguanto mas la vida',
  ];

  /// Carga emocional sin riesgo.
  static const List<String> _kokoro = <String>[
    'me siento mal',
    'me siento vacio',
    'me siento sola',
    'me siento solo',
    'estoy triste',
    'estoy deprimid',
    'estoy ansios',
    'tengo ansiedad',
    'me odio',
    'odio mi cuerpo',
    'odio como me veo',
    'me da verguenza',
    'no sirvo para nada',
    'soy un fracaso',
    'me siento inutil',
    'ya no puedo mas',
    'no tengo ganas de nada',
    'quiero rendirme',
    'me quiero rendir',
    'todo me sale mal',
    'estoy harto',
    'estoy harta',
    'perdi a',
    'murio mi',
    'fallecio',
    'la estoy pasando mal',
    'estoy pasando por',
    'me dejo mi',
    'estoy quemad',
  ];
}

