// ---------------------------------------------------------------------------
// 34.3 LO QUE TENSHI SABE DE TI
//
// Una fotografía del usuario armada desde los almacenes que ya existen. Esto
// es lo que separa a Tenshi de un chatbot: no espera a que le cuentes tu
// situación, ya la tiene.
// ---------------------------------------------------------------------------

class ContextoTenshi {
  const ContextoTenshi({
    required this.usuario,
    required this.espiritu,
    required this.tono,
    required this.nivel,
    required this.racha,
    required this.llama,
    required this.disposicion,
    required this.deuda,
    required this.pesoTemplo,
    required this.recuperacion,
    required this.diasSinEntrenar,
    required this.entrenoHoy,
    required this.sesiones,
    required this.objetivo,
    required this.experiencia,
    required this.lugar,
    required this.avisos,
    required this.grupoEnDeuda,
    required this.grupoFuerte,
    this.ciclo,
  });

  final String usuario;
  final String espiritu;
  final TonoTenshi tono;
  final NivelTemplo nivel;
  final Racha racha;
  final Llama llama;
  final Disposicion disposicion;
  final Map<GrupoMuscular, int> deuda;
  final double pesoTemplo;
  final int recuperacion;
  final int diasSinEntrenar;
  final bool entrenoHoy;
  final int sesiones;

  /// Claves de El Ascenso.
  final String objetivo;
  final String experiencia;
  final String lugar;

  final List<AvisoSalud> avisos;

  /// El grupo con más días sin trabajo (null si no hay historial).
  final GrupoMuscular? grupoEnDeuda;
  final GrupoMuscular? grupoFuerte;

  final CicloEntrenamiento? ciclo;

  bool get primeraVez => sesiones == 0;
  bool get vuelveDePausa => diasSinEntrenar >= 7;
  bool get cuerpoPideFreno =>
      avisos.any((AvisoSalud a) => a.gravedad == GravedadAviso.alto);

  int get diasDeuda =>
      grupoEnDeuda == null ? 0 : (deuda[grupoEnDeuda] ?? 0);

  static ContextoTenshi leer(String usuario, String espiritu) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final MotorProgresion m = MotorProgresion.instancia;
    final DatosUsuario d = a.de(usuario);
    final Map<GrupoMuscular, int> deuda = a.deuda(usuario);

    // Grupo con más deuda, ignorando los que nunca se han tocado si ya hay
    // historial: señalar «pantorrillas, 99 días» a alguien con dos sesiones
    // no aporta nada.
    GrupoMuscular? peor;
    int maxDias = -1;
    deuda.forEach((GrupoMuscular g, int dias) {
      final int normalizado = dias >= 90 ? (d.completadas.isEmpty ? 0 : 21) : dias;
      if (normalizado > maxDias) {
        maxDias = normalizado;
        peor = g;
      }
    });

    GrupoMuscular? fuerte;
    double mejorXp = 0;
    d.xpPorGrupo.forEach((GrupoMuscular g, double xp) {
      if (xp > mejorXp) {
        mejorXp = xp;
        fuerte = g;
      }
    });

    int sinEntrenar = 0;
    for (int i = 0; i < 120; i++) {
      if (a.entrenoEse(usuario, DateTime.now().subtract(Duration(days: i)))) {
        break;
      }
      sinEntrenar++;
    }

    return ContextoTenshi(
      usuario: usuario,
      espiritu: espiritu,
      tono: DatosTono.desdeClave(d.ascenso['voz']),
      nivel: NivelTemplo.desdeXp(d.xpGeneral),
      racha: m.racha(usuario),
      llama: a.llama(usuario),
      disposicion: a.disposicion(usuario, const <GrupoMuscular>[]),
      deuda: deuda,
      pesoTemplo: a.pesoDelTemplo(usuario),
      recuperacion: AlmacenRecuperacion.instancia.indice(usuario),
      diasSinEntrenar: sinEntrenar,
      entrenoHoy: a.entrenoEse(usuario, DateTime.now()),
      sesiones: d.completadas.length,
      objetivo: d.ascenso['objetivo'] ?? 'salud',
      experiencia: d.ascenso['experiencia'] ?? 'inicial',
      lugar: d.ascenso['lugar'] ?? 'gimnasio',
      avisos: VigilanciaCuerpo.evaluar(usuario),
      grupoEnDeuda: d.completadas.isEmpty ? null : peor,
      grupoFuerte: fuerte,
      ciclo: AlmacenCiclos.instancia.de(usuario),
    );
  }
}

// ---------------------------------------------------------------------------
// 34.4 TEMAS Y DETECCIÓN
//
// Solo lo usa el cerebro local, cuando no hay conexión. Con la mente
// completa conectada, el modelo entiende cualquier tema y esta tabla de
// palabras clave no interviene.
// ---------------------------------------------------------------------------

enum TemaTenshi {
  rutina,
  tecnica,
  progreso,
  deuda,
  nutricion,
  descanso,
  motivacion,
  app,
  saludo,
  gracias,
  fuera,
  desconocido,
}

class DetectorTema {
  const DetectorTema._();

  static const Map<TemaTenshi, List<String>> _claves =
      <TemaTenshi, List<String>>{
    TemaTenshi.rutina: <String>[
      'rutina', 'entrenar', 'entrenamiento', 'sesion', 'ejercicios de',
      'que hago hoy', 'que entreno', 'plan', 'ciclo', 'series', 'repeticiones',
      'volumen', 'dividir', 'split', 'cuantos dias',
    ],
    TemaTenshi.tecnica: <String>[
      'tecnica', 'como se hace', 'como hago', 'postura', 'form', 'ejecuto',
      'me duele al hacer', 'agarre', 'respiracion al',
    ],
    TemaTenshi.progreso: <String>[
      'progreso', 'nivel', 'rango', 'xp', 'experiencia', 'record', 'marca',
      'estancad', 'no subo', 'no avanzo', 'meseta', 'peso del templo',
      'cuanto he levantado', 'estadistica',
    ],
    TemaTenshi.deuda: <String>[
      'deuda', 'que me falta', 'que grupo', 'musculo', 'atrasad', 'olvidad',
      'desbalance', 'simetria', 'pierna', 'espalda', 'pecho', 'brazo',
      'hombro', 'abdomen', 'pantorrilla', 'biceps', 'triceps', 'antebrazo',
    ],
    TemaTenshi.nutricion: <String>[
      'comer', 'comida', 'nutricion', 'proteina', 'dieta', 'caloria',
      'que como', 'alimenta', 'suplement', 'creatina', 'batido', 'carbo',
      'grasa corporal', 'bajar de peso', 'subir de peso', 'deficit',
      'superavit', 'ayuno', 'agua',
    ],
    TemaTenshi.descanso: <String>[
      'descanso', 'dormir', 'sueno', 'cansad', 'agotad', 'recuperar',
      'recuperacion', 'dolor muscular', 'agujetas', 'sobreentren', 'lesion',
      'lesionad', 'me duele', 'estres', 'descargar', 'deload',
    ],
    TemaTenshi.motivacion: <String>[
      'motiva', 'no tengo ganas', 'pereza', 'flojera', 'me cuesta', 'aburr',
      'dejar de entrenar', 'abandonar', 'vale la pena', 'animo', 'constancia',
      'disciplina',
    ],
    TemaTenshi.app: <String>[
      'la app', 'aplicacion', 'como funciona', 'que es el', 'que es la',
      'dojo', 'la casa', 'el clan', 'ranked', 'mon', 'monedas', 'taller',
      'vineta', 'habitante', 'llama', 'escudo', 'titulo', 'clase',
      'linterna', 'hoguera', 'pergamino', 'jardin',
    ],
    TemaTenshi.saludo: <String>[
      'hola', 'buenas', 'buenos dias', 'buenas tardes', 'buenas noches',
      'que tal', 'como estas', 'ey tenshi', 'hey',
    ],
    TemaTenshi.gracias: <String>[
      'gracias', 'genial', 'perfecto', 'vale', 'ok tenshi', 'entendido',
      'buenisimo', 'crack',
    ],
    // Temas que quedan fuera del templo. Se detectan explícitamente para
    // poder devolver la conversación en vez de improvisar.
    TemaTenshi.fuera: <String>[
      'programar', 'codigo', 'python', 'javascript', 'traduce', 'traducir',
      'receta de cocina para mi novia', 'pelicula', 'serie', 'futbol',
      'politica', 'presidente', 'noticia', 'clima', 'tarea', 'examen',
      'matematica', 'historia de', 'chiste', 'poema', 'cancion',
      'quien gano', 'bitcoin', 'invertir', 'novia', 'novio', 'ligar',
    ],
  };

  static TemaTenshi detectar(String texto) {
    final String t = GuardiaTenshi.normalizar(texto);

    // Fuera de alcance manda sobre todo lo demás.
    if (_hay(t, _claves[TemaTenshi.fuera]!)) return TemaTenshi.fuera;

    // Orden a propósito: descanso antes que rutina, porque «estoy cansado,
    // ¿entreno?» es una pregunta de descanso, no de rutina.
    const List<TemaTenshi> orden = <TemaTenshi>[
      TemaTenshi.descanso,
      TemaTenshi.nutricion,
      TemaTenshi.tecnica,
      TemaTenshi.deuda,
      TemaTenshi.progreso,
      TemaTenshi.rutina,
      TemaTenshi.motivacion,
      TemaTenshi.app,
      TemaTenshi.gracias,
      TemaTenshi.saludo,
    ];

    for (final TemaTenshi tema in orden) {
      if (_hay(t, _claves[tema]!)) return tema;
    }
    return TemaTenshi.desconocido;
  }

  static bool _hay(String t, List<String> claves) => claves.any(t.contains);

  /// Busca un grupo muscular nombrado en el texto.
  static GrupoMuscular? grupoMencionado(String texto) {
    final String t = GuardiaTenshi.normalizar(texto);
    const Map<String, GrupoMuscular> alias = <String, GrupoMuscular>{
      'pecho': GrupoMuscular.pecho,
      'pectoral': GrupoMuscular.pecho,
      'espalda': GrupoMuscular.espalda,
      'dorsal': GrupoMuscular.espalda,
      'hombro': GrupoMuscular.hombros,
      'deltoide': GrupoMuscular.hombros,
      'biceps': GrupoMuscular.biceps,
      'triceps': GrupoMuscular.triceps,
      'antebrazo': GrupoMuscular.antebrazos,
      'abdomen': GrupoMuscular.abdomen,
      'abdominal': GrupoMuscular.abdomen,
      'core': GrupoMuscular.abdomen,
      'pierna': GrupoMuscular.piernas,
      'cuadriceps': GrupoMuscular.piernas,
      'femoral': GrupoMuscular.piernas,
      'gluteo': GrupoMuscular.piernas,
      'pantorrilla': GrupoMuscular.pantorrillas,
      'gemelo': GrupoMuscular.pantorrillas,
    };
    for (final MapEntry<String, GrupoMuscular> e in alias.entries) {
      if (t.contains(e.key)) return e.value;
    }
    return null;
  }
}

// ---------------------------------------------------------------------------
// 34.5 EL CEREBRO LOCAL
//
// Responde con TUS datos, sin red y sin coste. Cada respuesta pasa por tres
// capas: qué se pregunta (tema), qué dicen tus números (contexto) y cómo
// suena (tono).
//
// LÍMITES QUE NO CAMBIAN CON EL TONO:
//   · Nunca comenta tu cuerpo ni tu apariencia de forma negativa.
//   · Nunca da cifras de calorías, déficits ni pesos objetivo.
//   · Nunca diagnostica ni interpreta síntomas.
//   · Nunca empuja a entrenar con dolor, enfermo o sin dormir, ni a
//     compensar días perdidos con volumen extra. Ni siquiera en «exigente».
//
// El filo corta el trabajo, no a la persona.
// ---------------------------------------------------------------------------

class RespuestaTenshi {
  const RespuestaTenshi({
    required this.texto,
    this.sugerencias = const <SugerenciaTenshi>[],
    this.kokoro = false,
  });

  final String texto;
  final List<SugerenciaTenshi> sugerencias;
  final bool kokoro;
}

class CerebroTenshi {
  const CerebroTenshi._();

  static final math.Random _azar = math.Random();

  static String _una(List<String> opciones) =>
      opciones[_azar.nextInt(opciones.length)];

  // -- Apertura: la Lectura del Templo -------------------------------------
  //
  // Tenshi habla PRIMERO. No espera a que escribas: al abrir el módulo ya
  // sabe cómo vienes hoy y lo dice.

  static RespuestaTenshi lectura(ContextoTenshi c) {
    final TonoTenshi v = c.tono;

    if (c.primeraVez) {
      return RespuestaTenshi(
        texto: switch (v) {
          TonoTenshi.serena =>
            'Bienvenido, ${c.usuario}. Todavía no hay nada que leer en tus '
                'datos, y no pasa nada: el templo empieza vacío para todos.\n\n'
                'Cuéntame qué buscas y armamos el camino sin prisa.',
          TonoTenshi.alegre =>
            '¡${c.usuario}! Por fin. Aún no tengo datos tuyos, así que ahora '
                'mismo eres un misterio.\n\n'
                'Dime qué quieres conseguir y empezamos hoy mismo.',
          TonoTenshi.exigente =>
            'Cero sesiones, ${c.usuario}. Ese es todo tu historial.\n\n'
                'No me cuentes tus planes: dime cuándo entrenas por primera vez '
                'y lo preparo.',
        },
        sugerencias: _sugerencias(c),
      );
    }

    if (c.cuerpoPideFreno) {
      final AvisoSalud a = c.avisos.firstWhere(
        (AvisoSalud x) => x.gravedad == GravedadAviso.alto,
      );
      // Este caso ignora el tono a propósito. Un entrenador que aprieta a
      // alguien que duerme cuatro horas no es exigente, es dañino.
      return RespuestaTenshi(
        texto: 'Antes de nada: ${a.observacion.toLowerCase()}\n\n'
            '${a.sugerencia}\n\n'
            'Hoy no vamos a hablar de subir cargas.',
        sugerencias: <SugerenciaTenshi>[
          SugerenciaTenshi(
            etiqueta: 'Ir a recuperación',
            mensaje: '',
            glifo: TempleGlyph.loto,
            destino: (BuildContext ctx) => Navigator.of(ctx).push(
              MaterialPageRoute<void>(
                builder: (_) => RecuperacionScreen(
                  usuario: c.usuario,
                  espiritu: c.espiritu,
                ),
              ),
            ),
          ),
          const SugerenciaTenshi(
            etiqueta: '¿Qué hago mientras tanto?',
            mensaje: 'Si no debo entrenar fuerte hoy, ¿qué hago?',
            glifo: TempleGlyph.gota,
          ),
        ],
      );
    }

    if (c.vuelveDePausa) {
      return RespuestaTenshi(
        texto: switch (v) {
          TonoTenshi.serena =>
            '${c.diasSinEntrenar} días fuera no borran lo que construiste, '
                '${c.usuario}. El peso del templo sigue ahí y nadie te lo quita.\n\n'
                'Hoy alcanza con volver. Suave.',
          TonoTenshi.alegre =>
            '¡Volviste! ${c.diasSinEntrenar} días, pero quién los cuenta.\n\n'
                'Bajamos el peso, hacemos algo corto y mañana ya vemos.',
          TonoTenshi.exigente =>
            '${c.diasSinEntrenar} días. No te voy a preguntar por qué.\n\n'
                'Te voy a preguntar qué haces hoy, y hoy vamos con menos carga '
                'de la que crees que aguantas.',
        },
        sugerencias: _sugerencias(c),
      );
    }

    if (c.disposicion.valor < 45 || c.recuperacion < 40) {
      return RespuestaTenshi(
        texto: switch (v) {
          TonoTenshi.serena =>
            'Vienes con poca energía: disposición en ${c.disposicion.valor}.\n\n'
                '${c.disposicion.consejo} Descansar también levanta el templo.',
          TonoTenshi.alegre =>
            'Disposición en ${c.disposicion.valor}. Vamos a ser realistas hoy.\n\n'
                '${c.disposicion.consejo}',
          TonoTenshi.exigente =>
            'Disposición en ${c.disposicion.valor}. Entrenar así es tirar la '
                'sesión.\n\n${c.disposicion.consejo}',
        },
        sugerencias: _sugerencias(c),
      );
    }

    if (c.entrenoHoy) {
      return RespuestaTenshi(
        texto: switch (v) {
          TonoTenshi.serena =>
            'Ya entrenaste hoy. Eso está hecho y nadie te lo quita.\n\n'
                'Si quieres, hablamos de comida o de descanso.',
          TonoTenshi.alegre =>
            '¡Ya entrenaste hoy! Me encanta cuando llegas con los deberes '
                'hechos.\n\n¿Hablamos de la comida o te dejo en paz?',
          TonoTenshi.exigente =>
            'Entrenaste hoy. Bien.\n\n'
                'Ahora la otra mitad del trabajo: comer y dormir. Ahí es donde '
                'la gente lo tira todo.',
        },
        sugerencias: _sugerencias(c),
      );
    }

    if (c.grupoEnDeuda != null && c.diasDeuda >= 8) {
      final String g = c.grupoEnDeuda!.etiqueta.toLowerCase();
      return RespuestaTenshi(
        texto: switch (v) {
          TonoTenshi.serena =>
            'Vas bien: racha de ${c.racha.semanas} '
                '${c.racha.semanas == 1 ? "semana" : "semanas"} y la llama en '
                '${c.llama.valor}.\n\n'
                'Cuando quieras, $g lleva ${c.diasDeuda} días esperando su turno.',
          TonoTenshi.alegre =>
            'Llama en ${c.llama.valor} y racha de ${c.racha.semanas}. '
                'Vas fino.\n\n'
                'Aunque… $g lleva ${c.diasDeuda} días sin verte. Solo lo digo.',
          TonoTenshi.exigente =>
            'Racha de ${c.racha.semanas} y $g sin tocar en ${c.diasDeuda} días.\n\n'
                'Sabes exactamente por qué lo estás evitando.',
        },
        sugerencias: _sugerencias(c),
      );
    }

    return RespuestaTenshi(
      texto: switch (v) {
        TonoTenshi.serena =>
          'Nivel ${c.nivel.nivel}, racha de ${c.racha.semanas}, disposición en '
              '${c.disposicion.valor}. Terreno tranquilo.\n\n'
              'Dime qué necesitas hoy.',
        TonoTenshi.alegre =>
          'Nivel ${c.nivel.nivel} y disposición en ${c.disposicion.valor}. '
              'Buen día para hacer algo bueno.\n\n¿Por dónde empezamos?',
        TonoTenshi.exigente =>
          'Nivel ${c.nivel.nivel}, disposición en ${c.disposicion.valor}, '
              'todo en orden.\n\n'
              'Estás cómodo. Ahí es exactamente donde la gente se estanca.',
      },
      sugerencias: _sugerencias(c),
    );
  }

  // -- Sugerencias contextuales --------------------------------------------

  static List<SugerenciaTenshi> _sugerencias(ContextoTenshi c) {
    final List<SugerenciaTenshi> s = <SugerenciaTenshi>[];

    if (c.grupoEnDeuda != null && c.diasDeuda >= 6) {
      final String g = c.grupoEnDeuda!.etiqueta;
      s.add(SugerenciaTenshi(
        etiqueta: '$g está esperando',
        mensaje: '¿Cómo trabajo $g esta semana?',
        glifo: TempleGlyph.mancuerna,
      ));
    }

    if (c.disposicion.valor < 50 || c.recuperacion < 45) {
      s.add(const SugerenciaTenshi(
        etiqueta: 'Algo corto hoy',
        mensaje: 'Vengo cansado. Dame algo corto que valga la pena.',
        glifo: TempleGlyph.gota,
      ));
    }

    if (c.ciclo == null && c.sesiones >= 1) {
      s.add(const SugerenciaTenshi(
        etiqueta: 'No tengo rutina',
        mensaje: 'No tengo una rutina armada. ¿Qué hago?',
        glifo: TempleGlyph.lista,
      ));
    }

    s.addAll(const <SugerenciaTenshi>[
      SugerenciaTenshi(
        etiqueta: 'Revisar mi técnica',
        mensaje: 'Quiero revisar mi técnica en un ejercicio.',
        glifo: TempleGlyph.espadas,
      ),
      SugerenciaTenshi(
        etiqueta: 'Qué como hoy',
        mensaje: '¿Qué debería comer hoy?',
        glifo: TempleGlyph.cuenco,
      ),
      SugerenciaTenshi(
        etiqueta: 'No tengo ganas',
        mensaje: 'Hoy no tengo ganas de nada.',
        glifo: TempleGlyph.luna,
      ),
    ]);

    return s.take(5).toList();
  }

  // -- Respuesta a un turno -------------------------------------------------

  static RespuestaTenshi responder(String texto, ContextoTenshi c) {
    final RegistroTurno registro = GuardiaTenshi.evaluar(texto);

    if (registro == RegistroTurno.crisis) {
      return const RespuestaTenshi(texto: AuxilioTenshi.texto, kokoro: true);
    }
    if (registro == RegistroTurno.kokoro) {
      return _kokoro(texto, c);
    }

    switch (DetectorTema.detectar(texto)) {
      case TemaTenshi.rutina:
        return _rutina(texto, c);
      case TemaTenshi.tecnica:
        return _tecnica(texto, c);
      case TemaTenshi.progreso:
        return _progreso(c);
      case TemaTenshi.deuda:
        return _deuda(texto, c);
      case TemaTenshi.nutricion:
        return _nutricion(texto, c);
      case TemaTenshi.descanso:
        return _descanso(texto, c);
      case TemaTenshi.motivacion:
        return _motivacion(c);
      case TemaTenshi.app:
        return _app(texto, c);
      case TemaTenshi.saludo:
        return _saludo(c);
      case TemaTenshi.gracias:
        return _gracias(c);
      case TemaTenshi.fuera:
        return _fuera(c);
      case TemaTenshi.desconocido:
        return _noEntiendo(c);
    }
  }

  // -- Modo Kokoro ----------------------------------------------------------
  //
  // El turno es emocional, no técnico. Tenshi no propone entrenar, no
  // convierte lo que dijiste en una lección de disciplina y no salta a la
  // solución. Y aquí el tono exigente NO se aplica: es una decisión de
  // producto, no una limitación.

  static RespuestaTenshi _kokoro(String texto, ContextoTenshi c) {
    final String t = GuardiaTenshi.normalizar(texto);

    if (t.contains('odio mi cuerpo') || t.contains('odio como me veo')) {
      return const RespuestaTenshi(
        kokoro: true,
        texto:
            'Eso pesa, y no lo voy a arreglar con una rutina.\n\n'
            'No voy a decirte cómo deberías verte, ni a proponerte entrenar '
            'para arreglarlo. Entrenar desde ahí casi nunca sale bien.\n\n'
            'Si esto te da vueltas seguido, hablarlo con un profesional ayuda '
            'de verdad. Yo aquí sigo.',
      );
    }

    if (t.contains('perdi a') ||
        t.contains('murio mi') ||
        t.contains('fallecio')) {
      return const RespuestaTenshi(
        kokoro: true,
        texto:
            'Lo siento mucho.\n\n'
            'No hay nada que hacer con eso hoy, y no hace falta que lo haya. '
            'El templo puede esperar todo lo que necesites.',
      );
    }

    if (t.contains('quiero rendirme') || t.contains('me quiero rendir')) {
      return RespuestaTenshi(
        kokoro: true,
        texto:
            'Te escucho.\n\n'
            'No te voy a dar un discurso. Solo una cosa: llevas '
            '${c.sesiones} ${c.sesiones == 1 ? "sesión" : "sesiones"} y '
            '${c.pesoTemplo >= 1000 ? "${(c.pesoTemplo / 1000).toStringAsFixed(1)} toneladas" : "${c.pesoTemplo.round()} kilos"} '
            'levantados. Eso ya pasó y no se borra, pares o no pares.\n\n'
            '¿Qué es lo que más pesa ahora mismo?',
      );
    }

    return const RespuestaTenshi(
      kokoro: true,
      texto:
          'Vale. Gracias por decírmelo.\n\n'
          'No vamos a hablar de entrenar ahora. Si quieres contarme qué está '
          'pasando, te leo; y si prefieres dejarlo aquí, también está bien.',
    );
  }

  // -- Rutina ---------------------------------------------------------------

  static RespuestaTenshi _rutina(String texto, ContextoTenshi c) {
    // El cuerpo manda sobre cualquier plan.
    if (c.cuerpoPideFreno) {
      return RespuestaTenshi(
        texto: 'Hoy no te voy a armar nada exigente.\n\n'
            '${c.avisos.first.observacion} '
            '${c.avisos.first.sugerencia}',
        sugerencias: <SugerenciaTenshi>[
          SugerenciaTenshi(
            etiqueta: 'Ver recuperación',
            mensaje: '',
            glifo: TempleGlyph.loto,
            destino: (BuildContext ctx) => Navigator.of(ctx).push(
              MaterialPageRoute<void>(
                builder: (_) => RecuperacionScreen(
                  usuario: c.usuario, espiritu: c.espiritu),
              ),
            ),
          ),
        ],
      );
    }

    if (c.ciclo == null) {
      return RespuestaTenshi(
        texto: switch (c.tono) {
          TonoTenshi.serena =>
            'Todavía no tienes un camino armado, y eso explica bastante.\n\n'
                'Una rutina no es la sesión de hoy: es un ciclo con las cargas '
                'subiendo semana a semana y una semana de descarga cada cuatro. '
                'Son cuatro preguntas.',
          TonoTenshi.alegre =>
            'No tienes camino armado. ¡Eso lo arreglamos en un minuto!\n\n'
                'Cuatro preguntas y te monto un ciclo entero, con su semana de '
                'descarga incluida.',
          TonoTenshi.exigente =>
            'No tienes ciclo. Entrenar sin plan es improvisar, y improvisando '
                'no se progresa.\n\n'
                'Cuatro preguntas. Vamos.',
        },
        sugerencias: <SugerenciaTenshi>[
          SugerenciaTenshi(
            etiqueta: 'Armar mi camino',
            mensaje: '',
            glifo: TempleGlyph.torii,
            destino: (BuildContext ctx) => Navigator.of(ctx).push(
              MaterialPageRoute<void>(
                builder: (_) => CaminoScreen(usuario: c.usuario),
              ),
            ),
          ),
        ],
      );
    }

    final CicloEntrenamiento ciclo = c.ciclo!;
    final SemanaCiclo s = ciclo.semana;
    final DiaCiclo d = s.dias.first;

    return RespuestaTenshi(
      texto: switch (c.tono) {
        TonoTenshi.serena =>
          'Estás en la semana ${s.numero} de ${ciclo.semanas.length}: '
              '${s.titulo.toLowerCase()}, carga al '
              '${(s.factorCarga * 100).round()}%.\n\n'
              '${s.nota}\n\n'
              'El día que toca es ${d.nombre.toLowerCase()}: '
              '${d.ejercicios.length} ejercicios, unos ${d.minutos} minutos.',
        TonoTenshi.alegre =>
          '¡Semana ${s.numero}! ${s.titulo}, carga al '
              '${(s.factorCarga * 100).round()}%.\n\n'
              'Te toca ${d.nombre.toLowerCase()}: ${d.ejercicios.length} '
              'ejercicios y unos ${d.minutos} minutos. Nada raro.\n\n${s.nota}',
        TonoTenshi.exigente =>
          'Semana ${s.numero}, ${s.titulo.toLowerCase()}, carga al '
              '${(s.factorCarga * 100).round()}%.\n\n'
              '${d.nombre}: ${d.ejercicios.length} ejercicios, ${d.series} '
              'series. ${d.minutos} minutos.\n\n${s.nota}',
      },
      sugerencias: <SugerenciaTenshi>[
        SugerenciaTenshi(
          etiqueta: 'Abrir el Camino',
          mensaje: '',
          glifo: TempleGlyph.torii,
          destino: (BuildContext ctx) => Navigator.of(ctx).push(
            MaterialPageRoute<void>(
              builder: (_) => CaminoScreen(usuario: c.usuario),
            ),
          ),
        ),
        const SugerenciaTenshi(
          etiqueta: '¿Cuánto peso pongo?',
          mensaje: '¿Cuánto peso debería poner esta semana?',
          glifo: TempleGlyph.mancuerna,
        ),
      ],
    );
  }

  // -- Técnica --------------------------------------------------------------

  static RespuestaTenshi _tecnica(String texto, ContextoTenshi c) {
    final String t = GuardiaTenshi.normalizar(texto);

    // Dolor durante un ejercicio: esto no es una duda de técnica, es una
    // señal. No se resuelve con consejos de agarre.
    if (t.contains('me duele') || t.contains('dolor')) {
      return const RespuestaTenshi(
        texto:
            'Si duele mientras lo haces, para. No es cuestión de aguantar ni '
            'de corregir el agarre.\n\n'
            'Dolor articular, punzadas o algo que persiste después de la sesión '
            'lo mira un fisioterapeuta o un médico, no una app. Yo puedo '
            'ajustarte la rutina alrededor mientras tanto.',
      );
    }

    final Ejercicio? mencionado = _ejercicioMencionado(t);

    if (mencionado == null) {
      return RespuestaTenshi(
        texto: switch (c.tono) {
          TonoTenshi.exigente =>
            'Dime qué ejercicio. Sin el nombre no hay nada que corregir.',
          _ =>
            'Dime cuál y lo vemos: sentadilla, press de banca, peso muerto, '
                'dominadas, remo… lo que estés haciendo.',
        },
      );
    }

    final String claves = _clavesTecnica(mencionado.id);

    return RespuestaTenshi(
      texto: switch (c.tono) {
        TonoTenshi.serena =>
          '${mencionado.nombre}. Lo importante, sin adornos:\n\n$claves\n\n'
              'Si algo se siente raro, baja el peso antes que forzar la '
              'posición.',
        TonoTenshi.alegre =>
          '¡${mencionado.nombre}! Vale, las claves:\n\n$claves\n\n'
              'Y si dudas, baja el peso. Nadie mira, te lo prometo.',
        TonoTenshi.exigente =>
          '${mencionado.nombre}:\n\n$claves\n\n'
              'Si no puedes cumplir esos puntos con el peso que usas, el peso '
              'está mal, no tú.',
      },
    );
  }

  static Ejercicio? _ejercicioMencionado(String t) {
    for (final Ejercicio e in catalogoEjercicios) {
      final String n = GuardiaTenshi.normalizar(e.nombre);
      final String primera = n.split(' ').first;
      if (t.contains(n) || (primera.length > 4 && t.contains(primera))) {
        return e;
      }
    }
    return null;
  }

  /// Claves de ejecución. Puntos de seguridad y posición, nunca promesas de
  /// resultado.
  static String _clavesTecnica(String id) {
    switch (id) {
      case 'sentadilla':
        return '· Pies a la anchura de los hombros, puntas ligeramente abiertas.\n'
            '· Baja controlando, rodillas siguiendo la línea de los pies.\n'
            '· Espalda neutra: ni arqueada ni redondeada.\n'
            '· Sube empujando el suelo, sin adelantar la cadera antes que el pecho.';
      case 'peso_muerto':
        return '· La barra pegada a las espinillas antes de empezar.\n'
            '· Espalda neutra y pecho alto: si se redondea, el peso sobra.\n'
            '· Empuja el suelo con las piernas; no tires con la espalda.\n'
            '· Bloquea arriba sin echar el tronco hacia atrás.';
      case 'press_banca':
        return '· Escápulas retraídas y apoyadas: el pecho trabaja, no el hombro.\n'
            '· Codos a unos 45 grados del tronco, no abiertos del todo.\n'
            '· Baja a la parte baja del pecho, tocando sin rebotar.\n'
            '· Pies firmes en el suelo durante todo el recorrido.';
      case 'dominadas':
        return '· Empieza colgado del todo, hombros activos, no muertos.\n'
            '· Tira llevando los codos hacia las costillas.\n'
            '· Sube hasta que la barbilla pase la barra sin dar tirones.\n'
            '· Baja controlando: la bajada es la mitad del ejercicio.';
      case 'press_militar':
        return '· Barra a la altura de la clavícula, codos ligeramente delante.\n'
            '· Aprieta glúteo y abdomen para no arquear la espalda.\n'
            '· Empuja hacia arriba y ligeramente atrás, pasando la cabeza.\n'
            '· Bloquea arriba con los hombros activos.';
      case 'remo_barra':
        return '· Cadera atrás, tronco a unos 45 grados, espalda neutra.\n'
            '· Tira hacia el ombligo, no hacia el pecho.\n'
            '· Codos pegados al cuerpo, aprieta la escápula arriba.\n'
            '· Sin balancear el tronco para subir el peso.';
      default:
        return '· Recorrido completo antes que peso alto.\n'
            '· Bajada controlada: ahí está la mitad del estímulo.\n'
            '· Misma posición en todas las repeticiones de la serie.\n'
            '· Si la técnica se rompe, esa serie terminó.';
    }
  }

  // -- Progreso -------------------------------------------------------------

  static RespuestaTenshi _progreso(ContextoTenshi c) {
    if (c.primeraVez) {
      return const RespuestaTenshi(
        texto: 'Todavía no hay progreso que leer: no has registrado ninguna '
            'sesión.\n\n'
            'En cuanto cierres la primera, empiezo a tener algo que decirte.',
      );
    }

    final String peso = c.pesoTemplo >= 1000
        ? '${(c.pesoTemplo / 1000).toStringAsFixed(1)} toneladas'
        : '${c.pesoTemplo.round()} kg';

    return RespuestaTenshi(
      texto: switch (c.tono) {
        TonoTenshi.serena =>
          'Nivel ${c.nivel.nivel}, ${c.nivel.rango}. Llevas ${c.sesiones} '
              'sesiones y $peso levantados.\n\n'
              'Tu racha va por ${c.racha.semanas} '
              '${c.racha.semanas == 1 ? "semana" : "semanas"} y la llama en '
              '${c.llama.valor}. ${c.llama.mensaje}',
        TonoTenshi.alegre =>
          '¡Nivel ${c.nivel.nivel}! ${c.sesiones} sesiones y $peso movidos.\n\n'
              'Racha de ${c.racha.semanas} y llama en ${c.llama.valor}. '
              '${c.llama.mensaje}',
        TonoTenshi.exigente =>
          'Nivel ${c.nivel.nivel}. ${c.sesiones} sesiones, $peso.\n\n'
              'Racha de ${c.racha.semanas}, llama en ${c.llama.valor}. '
              '${c.racha.semanaCumplida ? "La semana está cumplida." : "Te faltan ${c.racha.faltan} sesiones esta semana."}',
      },
      sugerencias: <SugerenciaTenshi>[
        SugerenciaTenshi(
          etiqueta: 'Ver el peso del templo',
          mensaje: '',
          glifo: TempleGlyph.casa,
          destino: (BuildContext ctx) => Navigator.of(ctx).push(
            MaterialPageRoute<void>(
              builder: (_) => PesoTemploScreen(usuario: c.usuario),
            ),
          ),
        ),
        SugerenciaTenshi(
          etiqueta: 'Ver la semana',
          mensaje: '',
          glifo: TempleGlyph.lista,
          destino: (BuildContext ctx) => Navigator.of(ctx).push(
            MaterialPageRoute<void>(
              builder: (_) => SemanaScreen(usuario: c.usuario),
            ),
          ),
        ),
      ],
    );
  }

  // -- Deuda muscular -------------------------------------------------------

  static RespuestaTenshi _deuda(String texto, ContextoTenshi c) {
    final GrupoMuscular? preguntado = DetectorTema.grupoMencionado(texto);

    if (preguntado != null) {
      final int dias = c.deuda[preguntado] ?? 99;
      final String g = preguntado.etiqueta.toLowerCase();

      if (dias >= 90) {
        return RespuestaTenshi(
          texto: 'No tengo ningún registro de $g. Su linterna nunca se ha '
              'encendido.\n\n'
              'Un solo ejercicio que lo trabaje basta para prenderla.',
          sugerencias: _atajoSala(c),
        );
      }

      return RespuestaTenshi(
        texto: switch (c.tono) {
          TonoTenshi.serena =>
            dias == 0
                ? 'Hoy mismo trabajaste $g. Dale su descanso.'
                : '$g lleva $dias ${dias == 1 ? "día" : "días"} sin trabajo.\n\n'
                    '${dias >= 8 ? "Ya se está apagando; cuando puedas, dale una sesión." : "Va en buen ritmo."}',
          TonoTenshi.alegre =>
            dias == 0
                ? '¡Hoy le tocó! $g ya cumplió por hoy.'
                : '$g: $dias ${dias == 1 ? "día" : "días"}. '
                    '${dias >= 8 ? "Empieza a mirarme raro." : "Todo bien por ahí."}',
          TonoTenshi.exigente =>
            dias == 0
                ? 'Hoy trabajaste $g. Descansa: no se crece entrenándolo dos '
                    'veces seguidas.'
                : '$g: $dias ${dias == 1 ? "día" : "días"}. '
                    '${dias >= 8 ? "Demasiado. Esta semana toca." : "Aceptable."}',
        },
        sugerencias: _atajoSala(c),
      );
    }

    if (c.grupoEnDeuda == null) {
      return const RespuestaTenshi(
        texto: 'Todavía no hay historial suficiente para hablar de deuda. '
            'Registra un par de sesiones y te digo qué se está quedando atrás.',
      );
    }

    final List<MapEntry<GrupoMuscular, int>> orden = c.deuda.entries
        .where((MapEntry<GrupoMuscular, int> e) => e.value < 90)
        .toList()
      ..sort((MapEntry<GrupoMuscular, int> a, MapEntry<GrupoMuscular, int> b) =>
          b.value.compareTo(a.value));
    final List<MapEntry<GrupoMuscular, int>> top = orden.take(3).toList();

    final String lista = top
        .map((MapEntry<GrupoMuscular, int> e) =>
            '· ${e.key.etiqueta}: ${e.value} ${e.value == 1 ? "día" : "días"}')
        .join('\n');

    return RespuestaTenshi(
      texto: switch (c.tono) {
        TonoTenshi.serena =>
          'Lo que lleva más tiempo esperando:\n\n$lista\n\n'
              'No hace falta arreglarlo todo esta semana. Uno basta.',
        TonoTenshi.alegre =>
          'Los que te echan de menos:\n\n$lista\n\n'
              'Elige uno y ya. No hay que salvarlos a todos hoy.',
        TonoTenshi.exigente =>
          'Tu deuda:\n\n$lista\n\n'
              '${top.first.key.etiqueta} entra en la próxima sesión. No es '
              'negociable.',
      },
      sugerencias: _atajoSala(c),
    );
  }

  static List<SugerenciaTenshi> _atajoSala(ContextoTenshi c) =>
      <SugerenciaTenshi>[
        SugerenciaTenshi(
          etiqueta: 'Ver la Sala de los Nueve',
          mensaje: '',
          glifo: TempleGlyph.chispa,
          destino: (BuildContext ctx) => Navigator.of(ctx).push(
            MaterialPageRoute<void>(
              builder: (_) => SalaNueveScreen(usuario: c.usuario),
            ),
          ),
        ),
      ];

  // -- Nutrición ------------------------------------------------------------
  //
  // Aquí no se dan cifras de calorías ni déficits. Un objetivo calórico dado
  // por un programa que no conoce tu historial médico ni tu relación con la
  // comida hace más daño que bien.

  static RespuestaTenshi _nutricion(String texto, ContextoTenshi c) {
    final String t = GuardiaTenshi.normalizar(texto);

    // Señales de restricción o de relación difícil con la comida: se para el
    // tema, se nombra con cuidado y no se da ninguna cifra.
    const List<String> alarma = <String>[
      'ayuno', 'no comer', 'dejar de comer', 'no como nada', 'me da culpa',
      'culpa por comer', 'vomit', 'purga', 'contar cada', 'obsesion',
      'castigo', 'quemar lo que comi', 'compensar lo que comi',
    ];
    if (alarma.any(t.contains)) {
      return const RespuestaTenshi(
        texto:
            'Voy a parar aquí, porque eso que describes no se arregla con un '
            'plan de comidas.\n\n'
            'No te voy a dar cifras ni estrategias para comer menos. Entrenar '
            'para compensar comida, o sentir culpa por comer, es algo que '
            'conviene hablar con un nutricionista o un psicólogo.\n\n'
            'De entrenamiento seguimos cuando quieras.',
      );
    }

    if (t.contains('caloria') || t.contains('deficit') || t.contains('macro')) {
      return const RespuestaTenshi(
        texto:
            'No doy números de calorías, y es a propósito: un objetivo '
            'calculado por una app que no conoce tu salud ni tu historial hace '
            'más daño que bien.\n\n'
            'Lo que sí funciona: proteína en cada comida, verdura en la mayoría, '
            'y comer suficiente para sostener el entrenamiento. Si quieres un '
            'plan cerrado con cifras, eso es trabajo de un nutricionista.',
        sugerencias: <SugerenciaTenshi>[],
      );
    }

    final PerfilNutricion? p = AlmacenNutricion.instancia.de(c.usuario);

    if (p == null) {
      return RespuestaTenshi(
        texto: switch (c.tono) {
          TonoTenshi.exigente =>
            'No tienes guía de nutrición armada. Cinco preguntas y la tienes.\n\n'
                'Entrenar bien y comer al azar es media app desperdiciada.',
          _ =>
            'Todavía no armaste tu guía de comida.\n\n'
                'Son cinco preguntas y sale con tu tiempo real de cocina y lo '
                'que sí comes. Sin contar calorías.',
        },
        sugerencias: <SugerenciaTenshi>[
          SugerenciaTenshi(
            etiqueta: 'Armar mi guía',
            mensaje: '',
            glifo: TempleGlyph.cuenco,
            destino: (BuildContext ctx) => Navigator.of(ctx).push(
              MaterialPageRoute<void>(
                builder: (_) => NutricionScreen(usuario: c.usuario),
              ),
            ),
          ),
        ],
      );
    }

    final GuiaNutricion g = GuiaNutricion.generar(c.usuario, p);
    final List<int> plato = c.entrenoHoy ? g.platoEntreno : g.platoDescanso;

    return RespuestaTenshi(
      texto:
          '${c.entrenoHoy ? "Hoy entrenaste, así que sube el carbohidrato." : "Hoy no entrenas: más verdura, algo menos de carbohidrato."}\n\n'
          'Tu plato: ${plato[0]}% proteína, ${plato[1]}% carbohidrato, '
          '${plato[2]}% verdura.\n\n'
          '${g.rangoProteina == null ? "Si me das tu peso en la guía, te doy el rango de proteína." : "Proteína: ${g.rangoProteina}."}',
      sugerencias: <SugerenciaTenshi>[
        SugerenciaTenshi(
          etiqueta: 'Ver mi guía completa',
          mensaje: '',
          glifo: TempleGlyph.cuenco,
          destino: (BuildContext ctx) => Navigator.of(ctx).push(
            MaterialPageRoute<void>(
              builder: (_) => NutricionScreen(usuario: c.usuario),
            ),
          ),
        ),
      ],
    );
  }

  // -- Descanso -------------------------------------------------------------

  static RespuestaTenshi _descanso(String texto, ContextoTenshi c) {
    final String t = GuardiaTenshi.normalizar(texto);

    if (t.contains('lesion') || t.contains('lesionad')) {
      return const RespuestaTenshi(
        texto:
            'Con una lesión no improviso. Eso lo valora un fisioterapeuta o un '
            'médico: no tengo forma de ver qué te pasa.\n\n'
            'Mientras tanto puedo armarte la rutina esquivando la zona, si me '
            'dices cuál es. En el Camino hay una pregunta para eso.',
      );
    }

    if (c.avisos.isNotEmpty) {
      final AvisoSalud a = c.avisos.first;
      return RespuestaTenshi(
        texto: '${a.observacion}\n\n${a.sugerencia}',
        sugerencias: _atajoHoguera(c),
      );
    }

    return RespuestaTenshi(
      texto: switch (c.tono) {
        TonoTenshi.serena =>
          'Tu índice de recuperación está en ${c.recuperacion} de 100 y la '
              'disposición en ${c.disposicion.valor}.\n\n'
              '${c.disposicion.consejo}',
        TonoTenshi.alegre =>
          'Recuperación en ${c.recuperacion}, disposición en '
              '${c.disposicion.valor}.\n\n${c.disposicion.consejo}',
        TonoTenshi.exigente =>
          'Recuperación: ${c.recuperacion}. Disposición: '
              '${c.disposicion.valor}.\n\n'
              '${c.disposicion.consejo} El descanso es entrenamiento, no una '
              'pausa del entrenamiento.',
      },
      sugerencias: _atajoHoguera(c),
    );
  }

  static List<SugerenciaTenshi> _atajoHoguera(ContextoTenshi c) =>
      <SugerenciaTenshi>[
        SugerenciaTenshi(
          etiqueta: 'Ir a la hoguera',
          mensaje: '',
          glifo: TempleGlyph.llama,
          destino: (BuildContext ctx) => Navigator.of(ctx).push(
            MaterialPageRoute<void>(
              builder: (_) => HogueraScreen(
                usuario: c.usuario,
                espiritu: c.espiritu,
              ),
            ),
          ),
        ),
      ];

  // -- Motivación -----------------------------------------------------------

  static RespuestaTenshi _motivacion(ContextoTenshi c) {
    if (c.sesiones == 0) {
      return RespuestaTenshi(
        texto: switch (c.tono) {
          TonoTenshi.exigente =>
            'No tienes ganas y no has entrenado nunca. Normal: las ganas '
                'llegan después, no antes.\n\n'
                'Quince minutos hoy. Nada más.',
          _ =>
            'Las ganas casi nunca vienen antes. Vienen a los diez minutos de '
                'haber empezado.\n\n'
                'Hoy no busques una gran sesión: busca aparecer.',
        },
      );
    }

    final String peso = c.pesoTemplo >= 1000
        ? '${(c.pesoTemplo / 1000).toStringAsFixed(1)} toneladas'
        : '${c.pesoTemplo.round()} kilos';

    return RespuestaTenshi(
      texto: switch (c.tono) {
        TonoTenshi.serena =>
          'Está bien no tener ganas. No hace falta tenerlas para ir.\n\n'
              'Llevas ${c.sesiones} sesiones y $peso levantados: eso ya no se '
              'borra, entrenes hoy o no.\n\n'
              'Si vas, que sea corto.',
        TonoTenshi.alegre =>
          'Nadie tiene ganas siempre, tranquilo.\n\n'
              'Mira: ${c.sesiones} sesiones y $peso. Eso lo hiciste tú, muchas '
              'veces sin ganas también.\n\n'
              'Hoy hazlo corto y ya está.',
        TonoTenshi.exigente =>
          'Las ganas no son un requisito. Nunca lo fueron.\n\n'
              'Llevas ${c.sesiones} sesiones. Ninguna la hiciste porque te '
              'apeteciera especialmente.\n\n'
              'Quince minutos. Si a los quince quieres parar, paras.',
      },
    );
  }

  // -- La app ---------------------------------------------------------------

  static RespuestaTenshi _app(String texto, ContextoTenshi c) {
    final String t = GuardiaTenshi.normalizar(texto);

    String? explicacion;
    if (t.contains('llama')) {
      explicacion =
          'La llama mide tu constancia y se apaga poco a poco, nunca de golpe. '
          'Si te enfermas tres días vuelves a una brasa, no a cenizas.\n\n'
          'Ahora está en ${c.llama.valor}: ${c.llama.etiqueta.toLowerCase()}.';
    } else if (t.contains('escudo')) {
      explicacion =
          'Cada cuatro semanas cumplidas ganas un escudo. Si fallas una semana, '
          'se gasta uno y la racha sigue.\n\n'
          'Tienes ${c.racha.escudos}.';
    } else if (t.contains('mon') || t.contains('moneda')) {
      explicacion =
          'El mon es la moneda del templo. Se gana entrenando y sirve para '
          'comprar piezas de la viñeta en el Taller.\n\n'
          'Lo que se gana con hazañas no se puede comprar: esas piezas son tu '
          'currículum, no decoración.';
    } else if (t.contains('clase')) {
      explicacion =
          'Tu clase no se elige: se deduce de cómo entrenas de verdad, y cambia '
          'si tú cambias. Hacen falta seis sesiones para que aparezca.';
    } else if (t.contains('ranked') || t.contains('linterna')) {
      explicacion =
          'Cada grupo muscular sube de nivel por su cuenta. En la Sala de los '
          'Nueve hay una linterna por músculo: el tamaño es su nivel y la luz '
          'son los días que lleva sin que lo toques.';
    } else if (t.contains('casa') || t.contains('templo')) {
      explicacion =
          'La Casa se levanta con los kilos que acumulas. Cada pieza —el '
          'sendero, el torii, el estanque, la campana— aparece al cruzar un '
          'umbral de peso.\n\n'
          'Llevas ${c.pesoTemplo >= 1000 ? "${(c.pesoTemplo / 1000).toStringAsFixed(1)} t" : "${c.pesoTemplo.round()} kg"}.';
    } else if (t.contains('clan')) {
      explicacion =
          'El Clan es la comunidad del templo: publicas tu progreso, das Respeto, '
          'comentas y sigues a otros guerreros. Puedes reportar y bloquear a quien '
          'falte al reglamento.';
    }

    return RespuestaTenshi(
      texto: explicacion ??
          'El templo tiene cinco módulos: el Dojo es donde entrenas, la Casa '
              'es lo que levantas con tus kilos, yo soy Tenshi, el Clan es la '
              'comunidad y Ranked es el nivel de cada músculo.\n\n'
              '¿Cuál te explico?',
    );
  }

  // -- Sociales -------------------------------------------------------------

  static RespuestaTenshi _saludo(ContextoTenshi c) {
    return RespuestaTenshi(
      texto: switch (c.tono) {
        TonoTenshi.serena => _una(<String>[
            'Aquí estoy. ¿Qué necesitas?',
            'Dime.',
            'Te escucho, ${c.usuario}.',
          ]),
        TonoTenshi.alegre => _una(<String>[
            '¡Ey! ¿Qué se cuece hoy?',
            '¡${c.usuario}! Cuéntame.',
            'Aquí andaba. ¿Qué hacemos?',
          ]),
        TonoTenshi.exigente => _una(<String>[
            'Dime qué necesitas.',
            'Al grano: ¿qué hacemos hoy?',
            'Aquí estoy. Habla.',
          ]),
      },
      sugerencias: _sugerencias(c),
    );
  }

  static RespuestaTenshi _gracias(ContextoTenshi c) {
    return RespuestaTenshi(
      texto: switch (c.tono) {
        TonoTenshi.serena => _una(<String>[
            'Para eso estoy. Nos vemos en el Dojo.',
            'Cuando quieras.',
          ]),
        TonoTenshi.alegre => _una(<String>[
            '¡A mandar! Ve a levantar algo.',
            'Cuando quieras. Y ahora, al Dojo.',
          ]),
        TonoTenshi.exigente => _una(<String>[
            'Ahora hazlo.',
            'Bien. Nos vemos cuando lo hayas hecho.',
          ]),
      },
    );
  }

  // Cuando el cerebro local no sabe responder, es honesto sobre el motivo:
  // no es que el tema esté prohibido, es que sin conexión solo puede leer tus
  // datos del templo. Con la mente completa conectada, esto casi nunca se ve.

  static RespuestaTenshi _fuera(ContextoTenshi c) {
    return RespuestaTenshi(
      texto: switch (c.tono) {
        TonoTenshi.serena =>
          'De eso me gustaría hablar contigo, pero ahora mismo estoy sin mi '
              'mente completa: solo puedo leer lo que pasa en el templo.\n\n'
              'Cuando vuelva la conexión, pregúntamelo otra vez.',
        TonoTenshi.alegre =>
          '¡Buena pregunta! Y me fastidia, porque ahora mismo estoy '
              'desconectado y solo sé leer tus datos del templo.\n\n'
              'Pregúntamelo luego y lo hablamos bien.',
        TonoTenshi.exigente =>
          'Para eso necesito mi mente completa, y ahora mismo no está '
              'conectada.\n\nMientras tanto: entrenamiento, comida, descanso o '
              'tu progreso.',
      },
      sugerencias: _sugerencias(c),
    );
  }

  static RespuestaTenshi _noEntiendo(ContextoTenshi c) => _fuera(c);
}

// ---------------------------------------------------------------------------
// 34.6 LA MENTE
//
// Por qué la versión 1 se sentía sin vida: el cerebro local es un árbol de
// palabras clave. Por bien escrito que esté, solo reconoce lo que alguien
// previó, y todo lo demás lo devuelve igual. Ninguna cantidad de reglas lo
// arregla: hace falta un modelo de lenguaje.
//
// Cómo queda ahora:
//
//   Pantalla ──► MenteTenshi ──► Edge Function (Supabase) ──► modelo
//                    │                    └─ aquí viven la personalidad y
//                    │                       los límites de seguridad
//                    └─ si no hay red o no está configurada:
//                       CerebroLocal (la versión 1, intacta)
//
// La clave del modelo NUNCA está en el APK: vive como secreto en Supabase.
// Lo único que el cliente conoce es la URL de la función y la clave anónima
// de Supabase, que es pública por diseño.
//
// El modelo responde texto normal y, al final, unas etiquetas invisibles que
// el intérprete convierte en acciones:
//
//   <<sugiere:¿Y si mañana no puedo?>>   → botón de respuesta rápida
//   <<abrir:camino>>                     → botón que abre una pantalla
//   <<recuerda:trabaja de noche>>        → se guarda en su memoria
//   <<olvida:trabaja de noche>>          → se borra de su memoria
//
// Así el modelo puede actuar sobre la app sin que la app tenga que entender
// lenguaje natural.
// ---------------------------------------------------------------------------

/// Rellena estos dos valores y Tenshi pasa a la mente completa. Mientras
/// estén vacíos, sigue funcionando con el cerebro local.
class TenshiConfig {
  const TenshiConfig._();

  /// Supabase → Project Settings → API → Project URL, más la ruta de la
  /// función. Ejemplo:
  /// 'https://abcdefghijkl.supabase.co/functions/v1/tenshi-chat'
  static const String urlFuncion =
      'https://edppszkriwsyabgrnkkh.supabase.co/functions/v1/tenshi-chat';

  /// Supabase → Project Settings → API → anon public key.
  /// Es pública por diseño: solo permite lo que tus reglas de Supabase
  /// permiten. La clave del modelo NO va aquí.
  static const String claveAnon =
      'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImVkcHBzemtyaXdzeWFiZ3Jua2toIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODYyMzc2MDcsImV4cCI6MjEwMTgxMzYwN30.tdydDLBZPFVIgs9hYdb2LwHJGK8MLirlz8yDYpGbepk';

  static bool get conectada => urlFuncion.isNotEmpty && claveAnon.isNotEmpty;

  /// Turnos anteriores que se envían para que el modelo siga el hilo.
  static const int turnosDeHistorial = 16;
}

// -- Lo que viaja entre la pantalla y la mente ------------------------------

class PeticionTenshi {
  const PeticionTenshi({
    required this.texto,
    required this.contexto,
    required this.historial,
    required this.recuerdos,
    required this.registro,
  });

  final String texto;
  final ContextoTenshi contexto;
  final List<TurnoTenshi> historial;
  final List<String> recuerdos;
  final RegistroTurno registro;
}

/// Cada evento es o un fragmento de texto en vivo, o el cierre del turno.
class EventoTenshi {
  const EventoTenshi._({
    this.delta,
    this.respuesta,
    this.recuerdos = const <String>[],
    this.olvidos = const <String>[],
    this.local = false,
  });

  factory EventoTenshi.delta(String d) => EventoTenshi._(delta: d);

  factory EventoTenshi.fin(
    RespuestaTenshi r, {
    List<String> recuerdos = const <String>[],
    List<String> olvidos = const <String>[],
    bool local = false,
  }) =>
      EventoTenshi._(
        respuesta: r,
        recuerdos: recuerdos,
        olvidos: olvidos,
        local: local,
      );

  final String? delta;
  final RespuestaTenshi? respuesta;
  final List<String> recuerdos;
  final List<String> olvidos;

  /// La respuesta la dio el cerebro local, no el modelo.
  final bool local;

  bool get esFin => respuesta != null;
}

// -- El contexto en prosa ---------------------------------------------------
//
// Se envía en prosa y no en JSON: los modelos tienden a repetir literalmente
// las claves de un JSON dentro de la respuesta («tu racha_dias es 3»). En
// prosa eso no pasa.

extension ContextoEnProsa on ContextoTenshi {
  static const List<String> _dias = <String>[
    'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo',
  ];

  String comoTexto() {
    final DateTime ahora = DateTime.now();
    final int h = ahora.hour;
    final String momento = h < 6
        ? 'de madrugada'
        : h < 12
            ? 'por la mañana'
            : h < 19
                ? 'por la tarde'
                : 'por la noche';

    final List<String> l = <String>[
      'Se llama $usuario. Su espíritu es $espiritu.',
      'Hoy es ${_dias[ahora.weekday - 1]} y es $momento '
          '(${h.toString().padLeft(2, '0')}:${ahora.minute.toString().padLeft(2, '0')}).',
      'Objetivo que eligió al empezar: $objetivo. Experiencia: $experiencia. '
          'Entrena en: $lugar.',
      if (AlmacenMeta.instancia.paraTenshi(usuario) case final String meta) meta,
    ];

    if (primeraVez) {
      l.add('Todavía no ha registrado ninguna sesión.');
    } else {
      l.add('Nivel ${nivel.nivel} (${nivel.rango}). $sesiones sesiones '
          'registradas y ${pesoTemplo.round()} kg levantados en total.');
      l.add(entrenoHoy
          ? 'Hoy ya entrenó.'
          : 'Lleva $diasSinEntrenar '
              '${diasSinEntrenar == 1 ? "día" : "días"} sin entrenar.');
      l.add('Racha: ${racha.semanas} '
          '${racha.semanas == 1 ? "semana" : "semanas"}, '
          '${racha.escudos} escudos. '
          '${racha.semanaCumplida ? "Esta semana ya está cumplida." : "Le faltan ${racha.faltan} sesiones para cumplir la semana."}');
      l.add('Llama de constancia: ${llama.valor}/100 (${llama.etiqueta}).');
    }

    l.add('Disposición hoy: ${disposicion.valor}/100. '
        'Recuperación: $recuperacion/100.');

    if (grupoEnDeuda != null && diasDeuda > 0) {
      l.add('El grupo muscular más descuidado es '
          '${grupoEnDeuda!.etiqueta.toLowerCase()} ($diasDeuda días sin '
          'trabajarlo).');
    }
    if (grupoFuerte != null) {
      l.add('Su grupo más trabajado es ${grupoFuerte!.etiqueta.toLowerCase()}.');
    }

    final CicloEntrenamiento? ci = ciclo;
    if (ci == null) {
      l.add('No tiene un ciclo de entrenamiento armado.');
    } else {
      l.add('Está en la semana ${ci.semana.numero} de ${ci.semanas.length} de '
          'su ciclo: ${ci.semana.titulo.toLowerCase()}.');
    }

    for (final AvisoSalud a in avisos) {
      l.add('Aviso de cuerpo (${a.gravedad.name}): ${a.observacion}');
    }

    l.add('Voz que eligió para ti: ${tono.titulo.toLowerCase()} '
        '(${tono.clave}).');

    return l.join('\n');
  }
}

// -- El intérprete ----------------------------------------------------------

class InterpreteTenshi {
  const InterpreteTenshi._();

  static final RegExp _etiqueta = RegExp(
    r'<<\s*(sugiere|abrir|recuerda|olvida)\s*:\s*([^>]+?)\s*>>',
    caseSensitive: false,
  );

  /// Texto que se muestra mientras llega: sin etiquetas completas y sin el
  /// trozo de una etiqueta que todavía no terminó de llegar. Si no se corta,
  /// el usuario ve «<<recue» parpadeando al final del mensaje.
  static String visible(String crudo) {
    String t = crudo.replaceAll(_etiqueta, '');
    final int abierta = t.lastIndexOf('<<');
    if (abierta != -1 && !t.substring(abierta).contains('>>')) {
      t = t.substring(0, abierta);
    }
    if (t.endsWith('<')) t = t.substring(0, t.length - 1);
    return t.trimRight();
  }

  static EventoTenshi interpretar(
    String crudo,
    ContextoTenshi c, {
    required bool kokoro,
  }) {
    final List<SugerenciaTenshi> sugerencias = <SugerenciaTenshi>[];
    final List<String> recuerdos = <String>[];
    final List<String> olvidos = <String>[];
    final Set<String> abiertas = <String>{};

    for (final RegExpMatch m in _etiqueta.allMatches(crudo)) {
      final String tipo = m.group(1)!.toLowerCase();
      final String valor = m.group(2)!.trim();
      if (valor.isEmpty) continue;

      switch (tipo) {
        case 'sugiere':
          if (sugerencias.length < 4 && valor.length <= 60) {
            sugerencias.add(SugerenciaTenshi(
              etiqueta: valor,
              mensaje: valor,
              glifo: TempleGlyph.chispa,
            ));
          }
        case 'abrir':
          final SugerenciaTenshi? s = _destino(valor.toLowerCase(), c);
          if (s != null && abiertas.add(valor.toLowerCase())) {
            sugerencias.insert(0, s);
          }
        case 'recuerda':
          // Defensa extra: nada que suene a crisis entra en la memoria,
          // aunque el modelo lo pida.
          if (valor.length <= 200 &&
              GuardiaTenshi.evaluar(valor) != RegistroTurno.crisis) {
            recuerdos.add(valor);
          }
        case 'olvida':
          olvidos.add(valor);
      }
    }

    final String limpio = crudo
        .replaceAll(_etiqueta, '')
        .replaceAll(RegExp(r'\n{3,}'), '\n\n')
        .trim();

    return EventoTenshi.fin(
      RespuestaTenshi(
        texto: limpio.isEmpty ? '…' : limpio,
        sugerencias: sugerencias,
        kokoro: kokoro,
      ),
      recuerdos: recuerdos,
      olvidos: olvidos,
    );
  }

  /// Pantallas que el modelo puede abrir. Si inventa una que no existe, se
  /// ignora en silencio.
  static SugerenciaTenshi? _destino(String clave, ContextoTenshi c) {
    switch (clave) {
      case 'camino':
        return SugerenciaTenshi(
          etiqueta: 'Abrir el Camino',
          mensaje: '',
          glifo: TempleGlyph.torii,
          destino: (BuildContext ctx) => Navigator.of(ctx).push(
            MaterialPageRoute<void>(
                builder: (_) => CaminoScreen(usuario: c.usuario)),
          ),
        );
      case 'comida':
      case 'nutricion':
        return SugerenciaTenshi(
          etiqueta: 'Mi guía de comida',
          mensaje: '',
          glifo: TempleGlyph.cuenco,
          destino: (BuildContext ctx) => Navigator.of(ctx).push(
            MaterialPageRoute<void>(
                builder: (_) => NutricionScreen(usuario: c.usuario)),
          ),
        );
      case 'hoguera':
        return SugerenciaTenshi(
          etiqueta: 'Ir a la hoguera',
          mensaje: '',
          glifo: TempleGlyph.llama,
          destino: (BuildContext ctx) => Navigator.of(ctx).push(
            MaterialPageRoute<void>(
              builder: (_) =>
                  HogueraScreen(usuario: c.usuario, espiritu: c.espiritu),
            ),
          ),
        );
      case 'recuperacion':
        return SugerenciaTenshi(
          etiqueta: 'Ver recuperación',
          mensaje: '',
          glifo: TempleGlyph.loto,
          destino: (BuildContext ctx) => Navigator.of(ctx).push(
            MaterialPageRoute<void>(
              builder: (_) =>
                  RecuperacionScreen(usuario: c.usuario, espiritu: c.espiritu),
            ),
          ),
        );
      case 'sala':
        return SugerenciaTenshi(
          etiqueta: 'Sala de los Nueve',
          mensaje: '',
          glifo: TempleGlyph.chispa,
          destino: (BuildContext ctx) => Navigator.of(ctx).push(
            MaterialPageRoute<void>(
                builder: (_) => SalaNueveScreen(usuario: c.usuario)),
          ),
        );
      case 'peso':
        return SugerenciaTenshi(
          etiqueta: 'Peso del templo',
          mensaje: '',
          glifo: TempleGlyph.casa,
          destino: (BuildContext ctx) => Navigator.of(ctx).push(
            MaterialPageRoute<void>(
                builder: (_) => PesoTemploScreen(usuario: c.usuario)),
          ),
        );
      case 'semana':
        return SugerenciaTenshi(
          etiqueta: 'Ver la semana',
          mensaje: '',
          glifo: TempleGlyph.lista,
          destino: (BuildContext ctx) => Navigator.of(ctx).push(
            MaterialPageRoute<void>(
                builder: (_) => SemanaScreen(usuario: c.usuario)),
          ),
        );
    }
    return null;
  }
}

// -- La interfaz ------------------------------------------------------------

abstract class TenshiGateway {
  /// Apertura al abrir el módulo. Siempre local: aparece al instante, no
  /// gasta una llamada y no puede inventar un dato.
  RespuestaTenshi lectura(ContextoTenshi contexto);

  /// Respuesta en vivo a un turno.
  Stream<EventoTenshi> conversar(PeticionTenshi peticion);
}

// -- Respaldo: el cerebro local ---------------------------------------------

class CerebroLocal implements TenshiGateway {
  const CerebroLocal();

  @override
  RespuestaTenshi lectura(ContextoTenshi c) => CerebroTenshi.lectura(c);

  @override
  Stream<EventoTenshi> conversar(PeticionTenshi p) async* {
    final RespuestaTenshi r = CerebroTenshi.responder(p.texto, p.contexto);

    // La crisis no se «escribe» palabra a palabra: aparece entera tras una
    // pausa. Teclearla en directo le quitaría todo el peso.
    if (p.registro == RegistroTurno.crisis) {
      await Future<void>.delayed(const Duration(milliseconds: 900));
      yield EventoTenshi.fin(r, local: true);
      return;
    }

    await Future<void>.delayed(const Duration(milliseconds: 380));
    final List<String> palabras = r.texto.split(' ');
    for (int i = 0; i < palabras.length; i++) {
      await Future<void>.delayed(Duration(milliseconds: r.kokoro ? 34 : 18));
      yield EventoTenshi.delta(i == 0 ? palabras[i] : ' ${palabras[i]}');
    }
    yield EventoTenshi.fin(r, local: true);
  }
}

// -- La mente completa ------------------------------------------------------

class MenteTenshi implements TenshiGateway {
  const MenteTenshi({this.respaldo = const CerebroLocal()});

  /// Si la red falla, se responde igual. Nunca dejar a la persona en blanco.
  final TenshiGateway respaldo;

  @override
  RespuestaTenshi lectura(ContextoTenshi c) => respaldo.lectura(c);

  @override
  Stream<EventoTenshi> conversar(PeticionTenshi p) async* {
    // La crisis nunca sale a la red. La responde la app, sin depender de que
    // haya conexión ni de lo que diga un modelo.
    if (p.registro == RegistroTurno.crisis || !TenshiConfig.conectada) {
      yield* respaldo.conversar(p);
      return;
    }

    final bool kokoro = p.registro == RegistroTurno.kokoro;
    final StringBuffer crudo = StringBuffer();
    int estado = 0;
    bool fallo = false;
    // package:http funciona igual en Windows, Android, iOS y Chrome. En el
    // navegador entrega la respuesta de golpe en vez de palabra a palabra;
    // en el móvil y en Windows sí llega en vivo.
    final http.Client cliente = http.Client();

    try {
      final http.Request req =
          http.Request('POST', Uri.parse(TenshiConfig.urlFuncion))
            ..headers.addAll(<String, String>{
              'Authorization': 'Bearer ${supa.auth.currentSession?.accessToken ?? TenshiConfig.claveAnon}',
              'apikey': TenshiConfig.claveAnon,
              'Content-Type': 'application/json; charset=utf-8',
              'Accept': 'text/event-stream',
            })
            ..body = convert.jsonEncode(<String, Object>{
              'mensaje': p.texto,
              'tono': p.contexto.tono.clave,
              'kokoro': kokoro,
              'contexto': p.contexto.comoTexto(),
              'recuerdos': p.recuerdos,
              'historial': p.historial
                  .where((TurnoTenshi t) => !t.auxilio)
                  .map((TurnoTenshi t) => <String, String>{
                        'rol': t.autor == AutorTurno.usuario
                            ? 'usuario'
                            : 'tenshi',
                        'texto': t.texto,
                      })
                  .toList(),
            });

      final http.StreamedResponse res =
          await cliente.send(req).timeout(const Duration(seconds: 25));
      estado = res.statusCode;
      if (estado != 200) {
        await res.stream.drain<void>();
        throw StateError('estado $estado');
      }

      // SSE: líneas `data: {...}`. Se acumula en búfer porque un trozo de red
      // puede partir una línea por la mitad; asumir que cada trozo es una
      // línea completa produce texto roto de forma intermitente.
      String pendiente = '';
      await for (final String trozo in res.stream
          .transform(convert.utf8.decoder)
          .timeout(const Duration(seconds: 45))) {
        pendiente += trozo;
        final List<String> lineas = pendiente.split('\n');
        pendiente = lineas.removeLast();

        for (final String linea in lineas) {
          final String l = linea.trim();
          if (!l.startsWith('data:')) continue;
          final String carga = l.substring(5).trim();
          if (carga.isEmpty || carga == '[DONE]') continue;

          Object? j;
          try {
            j = convert.jsonDecode(carga);
          } on FormatException {
            continue; // un fragmento ilegible no corta la respuesta entera
          }
          if (j is! Map<String, dynamic>) continue;
          if (j['error'] != null) throw StateError('${j['error']}');

          final Object? d = j['delta'];
          if (d is String && d.isNotEmpty) {
            crudo.write(d);
            yield EventoTenshi.delta(d);
          }
        }
      }
    } catch (_) {
      fallo = true;
    } finally {
      cliente.close();
    }

    // Llegó algo antes del corte: se cierra con lo que hay.
    if (crudo.isNotEmpty) {
      yield InterpreteTenshi.interpretar(crudo.toString(), p.contexto,
          kokoro: kokoro);
      return;
    }

    if (fallo && estado == 402) {
      UsoPase.instancia.agotarTenshi();
      yield* respaldo.conversar(p);
      return;
    }

    if (fallo && estado == 429) {
      yield EventoTenshi.fin(
        RespuestaTenshi(
          texto: switch (p.contexto.tono) {
            TonoTenshi.exigente => 'Demasiado rápido. Respira y vuelve a '
                'preguntarme en un minuto.',
            _ => 'Vamos un poco más despacio. Dame un minuto y me lo '
                'vuelves a preguntar.',
          },
        ),
      );
      return;
    }

    // Sin red o sin respuesta: el cerebro local toma el turno.
    yield* respaldo.conversar(p);
  }
}

// ---------------------------------------------------------------------------
// 34.7 LA CONVERSACIÓN Y LA MEMORIA
//
// Dos cosas distintas, guardadas por separado:
//
//   · La conversación: los turnos. Se pueden borrar sin que Tenshi olvide
//     quién eres.
//   · Los recuerdos: hechos sobre ti que el modelo decidió guardar («trabaja
//     de noche», «tiene una boda en diciembre», «le molesta la rodilla
//     izquierda en sentadilla»). Viajan en cada turno, así que Tenshi los usa
//     aunque la conversación sea nueva.
//
// La persona ve todos sus recuerdos y puede borrar cualquiera. Una memoria
// que no se puede revisar es una memoria que da miedo.
//
// Vive en memoria, igual que el resto de almacenes de la app: el día que
// persistas AlmacenTemplo, persiste este con el mismo mecanismo.
// ---------------------------------------------------------------------------

class RecuerdoTenshi {
  const RecuerdoTenshi({required this.texto, required this.creado});
  final String texto;
  final DateTime creado;
}

class AlmacenTenshi {
  AlmacenTenshi._();
  static final AlmacenTenshi instancia = AlmacenTenshi._();

  /// Tope de recuerdos. Cada uno viaja en cada turno: sin tope, el prompt
  /// crece sin fin y cada respuesta cuesta y tarda más.
  static const int maxRecuerdos = 40;

  final Map<String, List<TurnoTenshi>> _turnos = <String, List<TurnoTenshi>>{};
  final Map<String, List<RecuerdoTenshi>> _recuerdos =
      <String, List<RecuerdoTenshi>>{};

  // -- Turnos ---------------------------------------------------------------

  List<TurnoTenshi> de(String usuario) =>
      List<TurnoTenshi>.unmodifiable(_turnos[usuario] ?? <TurnoTenshi>[]);

  void agregar(String usuario, TurnoTenshi t) {
    _turnos.putIfAbsent(usuario, () => <TurnoTenshi>[]).add(t);
  }

  bool vacia(String usuario) => (_turnos[usuario] ?? <TurnoTenshi>[]).isEmpty;

  /// Borra la conversación. Los recuerdos se quedan.
  void borrar(String usuario) => _turnos.remove(usuario);

  /// Últimos turnos para que el modelo siga el hilo. Sin los turnos de
  /// auxilio: un momento de crisis no debe volver como contexto.
  List<TurnoTenshi> historial(String usuario, {int max = 16}) {
    final List<TurnoTenshi> todos = (_turnos[usuario] ?? <TurnoTenshi>[])
        .where((TurnoTenshi t) => !t.auxilio)
        .toList();
    return todos.length <= max ? todos : todos.sublist(todos.length - max);
  }

  // -- Recuerdos ------------------------------------------------------------

  List<RecuerdoTenshi> recuerdos(String usuario) =>
      List<RecuerdoTenshi>.unmodifiable(
          _recuerdos[usuario] ?? <RecuerdoTenshi>[]);

  /// Los que viajan en cada turno: gratis, los 8 más recientes; con el Pase,
  /// los 40. Se guardan todos igual: si el Pase termina, no se borra nada.
  List<String> recuerdosTexto(String usuario) {
    final List<String> todos =
        recuerdos(usuario).map((RecuerdoTenshi r) => r.texto).toList(growable: false);
    final int n = LimitesPase.pase ? LimitesPase.recuerdosPase : LimitesPase.recuerdosGratis;
    return todos.length <= n ? todos : todos.sublist(todos.length - n);
  }

  /// Guarda un hecho. Si ya hay uno casi igual, lo sustituye por el nuevo
  /// (es la versión más actual de lo mismo).
  void recordar(String usuario, String hecho) {
    final String limpio = hecho.trim();
    if (limpio.isEmpty) return;

    final List<RecuerdoTenshi> lista =
        _recuerdos.putIfAbsent(usuario, () => <RecuerdoTenshi>[]);
    final String n = GuardiaTenshi.normalizar(limpio);

    lista.removeWhere((RecuerdoTenshi r) {
      final String o = GuardiaTenshi.normalizar(r.texto);
      return o == n || o.contains(n) || n.contains(o);
    });
    lista.add(RecuerdoTenshi(texto: limpio, creado: DateTime.now()));

    while (lista.length > maxRecuerdos) {
      lista.removeAt(0);
    }
  }

  /// Borra los recuerdos que contengan el fragmento indicado.
  void olvidarFragmento(String usuario, String fragmento) {
    final String n = GuardiaTenshi.normalizar(fragmento.trim());
    if (n.length < 3) return;
    _recuerdos[usuario]?.removeWhere(
      (RecuerdoTenshi r) => GuardiaTenshi.normalizar(r.texto).contains(n),
    );
  }

  void olvidarRecuerdo(String usuario, RecuerdoTenshi r) {
    _recuerdos[usuario]?.remove(r);
  }

  void olvidarTodo(String usuario) => _recuerdos.remove(usuario);

  static String nuevoId() => 'tsh_${DateTime.now().microsecondsSinceEpoch}';
}

// ---------------------------------------------------------------------------
// 34.8 EL AVATAR
//
// Tenshi no es un personaje con cara: es una luna creciente velada con el
// torii dentro, el mismo lenguaje del logo pero en movimiento.
//
// La decisión es deliberada. Una cara anime obliga a resolver una expresión
// para cada estado emocional y envejece mal; una forma abstracta que respira
// nunca queda fuera de lugar, ni celebrando una racha ni acompañando un mal
// día.
//
// Cuatro estados cambian tres cosas: velocidad de respiración, densidad de
// partículas e intensidad del halo. Nunca cambian la forma: Tenshi siempre
// se reconoce.
// ---------------------------------------------------------------------------

enum EstadoAvatar { reposo, escuchando, pensando, kokoro }

class AvatarTenshi extends StatefulWidget {
  const AvatarTenshi({
    super.key,
    required this.estado,
    required this.tono,
    this.size = 76,
  });

  final EstadoAvatar estado;
  final TonoTenshi tono;
  final double size;

  @override
  State<AvatarTenshi> createState() => _AvatarTenshiState();
}

class _AvatarTenshiState extends State<AvatarTenshi>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 12),
  );

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (MediaQuery.maybeDisableAnimationsOf(context) ?? false) {
      _c.stop();
      _c.value = 0.25;
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    // El color se interpola: al cambiar de voz, Tenshi no salta de un color a
    // otro, se enfría o se entibia. El cambio de personalidad se ve.
    return TweenAnimationBuilder<Color?>(
      tween: ColorTween(end: widget.tono.acento),
      duration: const Duration(milliseconds: 700),
      curve: Curves.easeInOutCubic,
      builder: (BuildContext context, Color? color, _) => RepaintBoundary(
        child: AnimatedBuilder(
          animation: _c,
          builder: (BuildContext context, _) => CustomPaint(
            size: Size.square(widget.size),
            painter: _AvatarTenshiPainter(
              t: _c.value,
              estado: widget.estado,
              acento: color ?? widget.tono.acento,
            ),
          ),
        ),
      ),
    );
  }
}

class _AvatarTenshiPainter extends CustomPainter {
  const _AvatarTenshiPainter({
    required this.t,
    required this.estado,
    required this.acento,
  });

  final double t;
  final EstadoAvatar estado;
  final Color acento;

  double get _ritmo {
    switch (estado) {
      case EstadoAvatar.reposo:
        return 1.0;
      case EstadoAvatar.escuchando:
        return 1.4;
      case EstadoAvatar.pensando:
        return 3.0;
      case EstadoAvatar.kokoro:
        return 0.55; // respira más lento: acompaña, no apura
    }
  }

  double get _halo {
    switch (estado) {
      case EstadoAvatar.reposo:
        return 0.30;
      case EstadoAvatar.escuchando:
        return 0.44;
      case EstadoAvatar.pensando:
        return 0.62;
      case EstadoAvatar.kokoro:
        return 0.20;
    }
  }

  int get _particulas {
    switch (estado) {
      case EstadoAvatar.reposo:
        return 7;
      case EstadoAvatar.escuchando:
        return 10;
      case EstadoAvatar.pensando:
        return 15;
      case EstadoAvatar.kokoro:
        return 4;
    }
  }

  @override
  void paint(Canvas canvas, Size size) {
    final Offset c = size.center(Offset.zero);
    final double r = size.width * 0.30;
    final double fase = t * _ritmo * 2 * math.pi;

    // Respiración: ±3.5%. Suficiente para leerse como vivo, poco para
    // distraer mientras se lee el texto de al lado.
    final double resp = 1 + math.sin(fase) * 0.035;

    _halos(canvas, c, r * resp);
    _particulasOrbita(canvas, c, r, fase);
    _luna(canvas, c, r * resp);
    _torii(canvas, c, r * resp);
  }

  void _halos(Canvas canvas, Offset c, double r) {
    final double pulso = (math.sin(t * _ritmo * 4) + 1) / 2;
    final double alcance = r * (2.5 + pulso * 0.35);

    canvas.drawCircle(
      c,
      alcance,
      Paint()
        ..shader = RadialGradient(
          colors: <Color>[
            acento.withValues(alpha: _halo * 0.5),
            acento.withValues(alpha: _halo * 0.16),
            Colors.transparent,
          ],
          stops: const <double>[0, 0.45, 1],
        ).createShader(Rect.fromCircle(center: c, radius: alcance)),
    );

    // Anillo que gira solo mientras piensa. Es el indicador de trabajo: nada
    // de puntos suspensivos.
    if (estado == EstadoAvatar.pensando) {
      final double inicio = t * _ritmo * 2 * math.pi;
      canvas.drawArc(
        Rect.fromCircle(center: c, radius: r * 1.62),
        inicio,
        math.pi * 0.85,
        false,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.2
          ..strokeCap = StrokeCap.round
          ..shader = SweepGradient(
            startAngle: inicio,
            endAngle: inicio + math.pi * 0.85,
            colors: <Color>[
              acento.withValues(alpha: 0),
              acento.withValues(alpha: 0.85),
            ],
          ).createShader(Rect.fromCircle(center: c, radius: r * 1.62)),
      );
    }
  }

  void _particulasOrbita(Canvas canvas, Offset c, double r, double fase) {
    final math.Random rnd = math.Random(7);
    final Paint p = Paint();

    for (int i = 0; i < _particulas; i++) {
      final double s = rnd.nextDouble();
      final double orbita = r * (1.5 + s * 1.15);
      final double vel = 0.35 + s * 0.5;
      final double ang = s * 2 * math.pi + fase * vel * (i.isEven ? 1 : -1);

      // Deriva vertical: no orbitan en círculo perfecto. Un anillo geométrico
      // exacto se lee como spinner de carga.
      final double deriva = math.sin(fase * 0.6 + s * 6) * r * 0.16;

      final Offset pos = Offset(
        c.dx + math.cos(ang) * orbita,
        c.dy + math.sin(ang) * orbita * 0.72 + deriva,
      );

      final double op =
          (0.20 + (math.sin(fase * vel + s * 9) + 1) / 2 * 0.55) *
              (estado == EstadoAvatar.kokoro ? 0.5 : 1.0);

      p.color = acento.withValues(alpha: op.clamp(0.0, 1.0));
      canvas.drawCircle(pos, 0.9 + s * 1.4, p);
    }
  }

  void _luna(Canvas canvas, Offset c, double r) {
    // Creciente por diferencia de dos círculos. El desplazamiento define el
    // grosor del filo: 0.46 da una hoz marcada sin llegar a hilo, que a
    // tamaños pequeños desaparecería.
    final Path lleno = Path()
      ..addOval(Rect.fromCircle(center: c, radius: r));
    final Path recorte = Path()
      ..addOval(
        Rect.fromCircle(center: c.translate(r * 0.46, -r * 0.14), radius: r),
      );
    final Path creciente =
        Path.combine(PathOperation.difference, lleno, recorte);

    canvas.drawPath(
      creciente,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: <Color>[
            Color.lerp(ColoresTradicion.blancoLuna, acento, 0.18)!,
            Color.lerp(acento, ColoresTradicion.negro, 0.35)!,
          ],
        ).createShader(Rect.fromCircle(center: c, radius: r)),
    );

    canvas.drawPath(
      creciente,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.1
        ..color = Color.lerp(ColoresTradicion.blancoLuna, acento, 0.45)!
            .withValues(alpha: 0.9),
    );
  }

  void _torii(Canvas canvas, Offset c, double r) {
    // Dentro del hueco del creciente, desplazado hacia donde hay espacio.
    final Offset o = c.translate(r * 0.30, r * 0.02);
    final double a = r * 0.58;
    final double h = r * 0.52;

    final Paint trazo = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = math.max(1.0, r * 0.055)
      ..strokeCap = StrokeCap.round
      ..color = Color.lerp(ColoresTradicion.blancoLuna, acento, 0.30)!
          .withValues(alpha: 0.92);

    final double izq = o.dx - a / 2;
    final double der = o.dx + a / 2;
    final double top = o.dy - h / 2;
    final double abajo = o.dy + h / 2;

    canvas.drawLine(
        Offset(izq - a * 0.13, top), Offset(der + a * 0.13, top), trazo);
    canvas.drawLine(Offset(izq - a * 0.02, top + h * 0.26),
        Offset(der + a * 0.02, top + h * 0.26), trazo);
    canvas.drawLine(Offset(izq, top), Offset(izq, abajo), trazo);
    canvas.drawLine(Offset(der, top), Offset(der, abajo), trazo);
  }

  @override
  bool shouldRepaint(_AvatarTenshiPainter old) =>
      old.t != t || old.estado != estado || old.acento != acento;
}

// ---------------------------------------------------------------------------
// 34.9 LA PANTALLA
//
// Sustituye al andamio `TenshiScreen` de la sección 15. Misma firma, así que
// MainShell no cambia.
//
// El avatar NO hace scroll: queda anclado arriba mientras la conversación
// corre por debajo. Es lo que convierte a Tenshi en una presencia en la sala
// en lugar de un mensaje más del hilo.
// ---------------------------------------------------------------------------

class TenshiScreen extends StatefulWidget {
  const TenshiScreen({super.key});

  @override
  State<TenshiScreen> createState() => _TenshiScreenState();
}

class _TenshiScreenState extends State<TenshiScreen> {
  final TenshiGateway _mente = const MenteTenshi();

  final ScrollController _scroll = ScrollController();
  final TextEditingController _campo = TextEditingController();
  final FocusNode _foco = FocusNode();

  EstadoAvatar _estado = EstadoAvatar.reposo;
  bool _ocupado = false;
  bool _iniciado = false;
  bool _sinConexion = false;

  /// Texto que está llegando en vivo. Null cuando no hay respuesta en curso.
  String? _borrador;
  bool _borradorKokoro = false;

  List<SugerenciaTenshi> _chips = const <SugerenciaTenshi>[];

  @override
  void initState() {
    super.initState();
    _campo.addListener(() {
      if (_ocupado) return;
      final EstadoAvatar nuevo = _campo.text.trim().isNotEmpty
          ? EstadoAvatar.escuchando
          : EstadoAvatar.reposo;
      if (nuevo != _estado) setState(() => _estado = nuevo);
    });
  }

  @override
  void dispose() {
    _scroll.dispose();
    _campo.dispose();
    _foco.dispose();
    super.dispose();
  }

  ContextoTenshi _contexto(BuildContext context) {
    final PerfilUsuario p = TempleShellScope.of(context).perfil;
    return ContextoTenshi.leer(p.nombre, p.espiritu);
  }

  void _abrirSiHaceFalta(ContextoTenshi c) {
    if (_iniciado) return;
    _iniciado = true;
    if (!AlmacenTenshi.instancia.vacia(c.usuario)) return;

    final RespuestaTenshi r = _mente.lectura(c);
    AlmacenTenshi.instancia.agregar(
      c.usuario,
      TurnoTenshi(
        id: AlmacenTenshi.nuevoId(),
        autor: AutorTurno.tenshi,
        texto: r.texto,
        creadoEn: DateTime.now(),
        sugerencias: r.sugerencias,
      ),
    );
    _chips = r.sugerencias;
  }

  /// Durante la escritura en vivo solo se baja si la persona ya estaba abajo:
  /// si subió a releer algo, arrastrarla de vuelta cada palabra es hostil.
  void _bajar({bool forzar = false}) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!_scroll.hasClients) return;
      final ScrollPosition pos = _scroll.position;
      if (!forzar && pos.maxScrollExtent - pos.pixels > 140) return;
      if (forzar) {
        _scroll.animateTo(pos.maxScrollExtent,
            duration: TempleMotion.medio, curve: TempleMotion.suave);
      } else {
        _scroll.jumpTo(pos.maxScrollExtent);
      }
    });
  }

  Future<void> _enviar(String texto, ContextoTenshi c) async {
    final String limpio = texto.trim();
    if (limpio.isEmpty || _ocupado) return;

    _campo.clear();
    HapticFeedback.selectionClick();

    final AlmacenTenshi a = AlmacenTenshi.instancia;
    final RegistroTurno registro = GuardiaTenshi.evaluar(limpio);

    // El historial se toma ANTES de añadir el turno nuevo: el mensaje actual
    // viaja aparte.
    final PeticionTenshi peticion = PeticionTenshi(
      texto: limpio,
      contexto: c,
      historial: a.historial(c.usuario, max: TenshiConfig.turnosDeHistorial),
      recuerdos: a.recuerdosTexto(c.usuario),
      registro: registro,
    );

    a.agregar(
      c.usuario,
      TurnoTenshi(
        id: AlmacenTenshi.nuevoId(),
        autor: AutorTurno.usuario,
        texto: limpio,
        creadoEn: DateTime.now(),
      ),
    );

    setState(() {
      _ocupado = true;
      _estado = EstadoAvatar.pensando;
      _chips = const <SugerenciaTenshi>[];
      _borrador = null;
      _borradorKokoro = registro == RegistroTurno.kokoro;
    });
    _bajar(forzar: true);

    String crudo = '';
    EventoTenshi? fin;

    // Gratis: 10 mensajes al día con la mente completa. Después responde
    // Tenshi ligero (el cerebro del teléfono), que nunca deja a nadie en
    // blanco. Una crisis nunca cuenta ni se limita.
    final bool completa = registro == RegistroTurno.crisis || UsoPase.instancia.tenshiDisponible;
    final TenshiGateway mente = completa ? _mente : const CerebroLocal();

    await for (final EventoTenshi e in mente.conversar(peticion)) {
      if (!mounted) return;
      if (e.esFin) {
        fin = e;
        break;
      }
      crudo += e.delta!;
      final String visible = InterpreteTenshi.visible(crudo);
      setState(() {
        _borrador = visible;
        _estado = _borradorKokoro ? EstadoAvatar.kokoro : EstadoAvatar.pensando;
      });
      _bajar();
    }
    if (!mounted) return;

    // Si el flujo se cerró sin evento final, se interpreta lo que llegó.
    fin ??= InterpreteTenshi.interpretar(crudo, c,
        kokoro: registro == RegistroTurno.kokoro);

    final RespuestaTenshi r = fin.respuesta!;
    if (completa && registro != RegistroTurno.crisis && !fin.local) UsoPase.instancia.sumarTenshi();
    for (final String h in fin.recuerdos) {
      a.recordar(c.usuario, h);
    }
    for (final String h in fin.olvidos) {
      a.olvidarFragmento(c.usuario, h);
    }

    a.agregar(
      c.usuario,
      TurnoTenshi(
        id: AlmacenTenshi.nuevoId(),
        autor: AutorTurno.tenshi,
        texto: r.texto,
        creadoEn: DateTime.now(),
        kokoro: r.kokoro,
        auxilio: registro == RegistroTurno.crisis,
        sugerencias: r.sugerencias,
      ),
    );

    if (registro != RegistroTurno.crisis) sonar(SonidoTemplo.tenshi);
    setState(() {
      _ocupado = false;
      _borrador = null;
      _sinConexion = fin!.local && TenshiConfig.conectada;
      _estado = r.kokoro ? EstadoAvatar.kokoro : EstadoAvatar.reposo;
      _chips = r.sugerencias;
    });
    _bajar(forzar: true);
  }

  Future<void> _cambiarVoz(ContextoTenshi c) async {
    final TonoTenshi? elegido = await showModalBottomSheet<TonoTenshi>(
      context: context,
      backgroundColor: TempleColors.grafito,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (_) => _TshHojaVoz(actual: c.tono),
    );
    if (elegido == null || !mounted) return;

    // Mismo sitio que El Ascenso: así cambian también los avisos de la
    // sección 29. Una sola voz en toda la app.
    AlmacenTemplo.instancia.de(c.usuario).ascenso['voz'] = elegido.clave;
    HapticFeedback.selectionClick();
    setState(() {});
  }

  Future<void> _verRecuerdos(ContextoTenshi c) async {
    await showModalBottomSheet<void>(
      context: context,
      backgroundColor: TempleColors.grafito,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (_) => _TshHojaRecuerdos(usuario: c.usuario, tono: c.tono),
    );
    if (mounted) setState(() {});
  }

  /// Menú «⋮» de Tenshi: su voz, su memoria, la conversación y ayuda.
  void _menu(ContextoTenshi c, {required bool puedeBorrar}) {
    mostrarMenuTemplo(
      context,
      titulo: 'Tenshi',
      subtitulo: 'Tu maestro del templo',
      guia: 'tenshi',
      opciones: <OpcionHoja>[
        if (puedeBorrar)
          OpcionHoja(Icons.refresh_rounded, 'Conversación nueva', () => _borrarConversacion(c)),
        OpcionHoja(Icons.record_voice_over_outlined, 'Cómo te habla Tenshi', () => _cambiarVoz(c)),
        OpcionHoja(Icons.bookmark_border_rounded, 'Lo que Tenshi recuerda de ti', () => _verRecuerdos(c)),
        OpcionHoja(Icons.auto_stories_outlined, 'El informe de tu semana', () {
          Navigator.of(context).push(MaterialPageRoute<void>(
            builder: (_) => InformeSemanalScreen(usuario: c.usuario),
          ));
        }),
        OpcionHoja(Icons.support_outlined, 'Líneas de apoyo', () {
          showModalBottomSheet<void>(
            context: context,
            backgroundColor: TempleColors.grafito,
            isScrollControlled: true,
            shape: const RoundedRectangleBorder(
              borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
            ),
            builder: (BuildContext ctx) => const SafeArea(
              top: false,
              child: SingleChildScrollView(
                padding: EdgeInsets.fromLTRB(4, 8, 20, 20),
                child: _TshLineasApoyo(),
              ),
            ),
          );
        }),
        OpcionHoja(Icons.info_outline_rounded, 'Sobre Tenshi', () {
          showDialog<void>(
            context: context,
            builder: (BuildContext ctx) => AlertDialog(
              backgroundColor: TempleColors.superficieAlta,
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
                side: const BorderSide(color: TempleColors.borde),
              ),
              title: const Text('Sobre Tenshi',
                  style: TextStyle(color: TempleColors.blancoLuna, fontSize: 18)),
              content: const Text(
                'Tenshi es una inteligencia artificial. Conoce tu progreso dentro del templo y te '
                'acompaña, pero puede equivocarse y no reemplaza a un médico, nutricionista o '
                'psicólogo. Si algo duele o te preocupa, consulta a un profesional.',
                style: TextStyle(fontSize: 13.5, height: 1.5, color: TempleColors.textoSuave),
              ),
              actions: <Widget>[
                TextButton(
                  onPressed: () => Navigator.of(ctx).pop(),
                  child: const Text('Entendido', style: TextStyle(color: TempleColors.violetaClaro)),
                ),
              ],
            ),
          );
        }),
      ],
    );
  }

  Future<void> _borrarConversacion(ContextoTenshi c) async {
    final bool? si = await showDialog<bool>(
      context: context,
      builder: (BuildContext ctx) => AlertDialog(
        backgroundColor: TempleColors.superficieAlta,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
        ),
        title: const Text('Empezar una conversación nueva',
            style: TextStyle(color: TempleColors.blancoLuna)),
        content: const Text(
          'Se borra lo que hablaron. Lo que Tenshi recuerda de ti se queda: '
          'eso lo revisas en el icono de recuerdos.',
          style: TextStyle(color: TempleColors.textoSuave),
        ),
        actions: <Widget>[
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(false),
            child: const Text('Cancelar'),
          ),
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(true),
            child: const Text('Borrar',
                style: TextStyle(color: TempleColors.error)),
          ),
        ],
      ),
    );
    if (si != true || !mounted) return;
    AlmacenTenshi.instancia.borrar(c.usuario);
    _iniciado = false;
    _sinConexion = false;
    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final ContextoTenshi c = _contexto(context);
    _abrirSiHaceFalta(c);

    final List<TurnoTenshi> turnos = AlmacenTenshi.instancia.de(c.usuario);
    final int nRecuerdos =
        AlmacenTenshi.instancia.recuerdos(c.usuario).length;

    return Stack(
      fit: StackFit.expand,
      children: <Widget>[
        // Pétalos de cerezo que caen despacio detrás de la conversación.
        const Positioned.fill(child: PetalosSakura()),
        SafeArea(
          bottom: false,
          child: Column(
            children: <Widget>[
              _TshCabecera(
                estado: _estado,
                tono: c.tono,
                espiritu: c.espiritu,
                escribiendo: _borrador != null,
                sinConexion: _sinConexion,
                recuerdos: nRecuerdos,
                onVoz: () => _cambiarVoz(c),
                onRecuerdos: () => _verRecuerdos(c),
                onBorrar: turnos.length <= 1 || _ocupado
                    ? null
                    : () => _borrarConversacion(c),
                onMenu: () => _menu(c, puedeBorrar: turnos.length > 1 && !_ocupado),
              ),
              Expanded(
                child: GestureDetector(
                  onTap: () => _foco.unfocus(),
                  behavior: HitTestBehavior.translucent,
                  child: ListView(
                    controller: _scroll,
                    physics: const BouncingScrollPhysics(),
                    padding: const EdgeInsets.fromLTRB(20, 6, 20, 12),
                    children: <Widget>[
                      for (int i = 0; i < turnos.length; i++) ...<Widget>[
                        _TshTurno(
                          turno: turnos[i],
                          tono: c.tono,
                          onReportar: turnos[i].autor == AutorTurno.tenshi && !turnos[i].auxilio && i > 0
                              ? () => reportarRespuestaTenshi(context, turnos[i], turnos)
                              : null,
                        ),
                        if (turnos[i].auxilio) const _TshLineasApoyo(),
                        const SizedBox(height: 18),
                      ],
                      if (_ocupado && (_borrador == null || _borrador!.isEmpty))
                        _TshPensando(tono: c.tono),
                      if (_borrador != null && _borrador!.isNotEmpty)
                        _TshTurno(
                          turno: TurnoTenshi(
                            id: 'borrador',
                            autor: AutorTurno.tenshi,
                            texto: _borrador!,
                            creadoEn: DateTime.now(),
                            kokoro: _borradorKokoro,
                          ),
                          tono: c.tono,
                        ),
                    ],
                  ),
                ),
              ),
              if (_chips.isNotEmpty && !_ocupado)
                _TshChips(
                  sugerencias: _chips,
                  tono: c.tono,
                  onTexto: (String m) => _enviar(m, c),
                ),
              _TshCupo(tono: c.tono),
              _TshCampo(
                controller: _campo,
                foco: _foco,
                tono: c.tono,
                habilitado: !_ocupado,
                onEnviar: () => _enviar(_campo.text, c),
              ),
            ],
          ),
        ),
      ],
    );
  }
}

// -- Cabecera ---------------------------------------------------------------

class _TshCabecera extends StatelessWidget {
  const _TshCabecera({
    required this.estado,
    required this.tono,
    required this.espiritu,
    required this.escribiendo,
    required this.sinConexion,
    required this.recuerdos,
    required this.onVoz,
    required this.onRecuerdos,
    required this.onBorrar,
    required this.onMenu,
  });

  final VoidCallback onMenu;
  final EstadoAvatar estado;
  final TonoTenshi tono;
  final String espiritu;
  final bool escribiendo;
  final bool sinConexion;
  final int recuerdos;
  final VoidCallback onVoz;
  final VoidCallback onRecuerdos;
  final VoidCallback? onBorrar;

  /// El estado se nombra, no se deja adivinar por la animación.
  String get _pie {
    if (escribiendo) return 'Escribiendo';
    switch (estado) {
      case EstadoAvatar.pensando:
        return 'Pensando';
      case EstadoAvatar.escuchando:
        return 'Te escucha';
      case EstadoAvatar.kokoro:
        return 'Aquí, sin prisa';
      case EstadoAvatar.reposo:
        return sinConexion
            ? 'Sin conexión · solo lee el templo'
            : tono.titulo;
    }
  }

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.fromLTRB(18, 6, 6, 4),
      child: Row(
        children: <Widget>[
          AvatarTenshi(estado: estado, tono: tono, size: 64),
          const SizedBox(width: 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: <Widget>[
                Row(
                  children: <Widget>[
                    const Flexible(
                      child: Text(
                        'TENSHI',
                        maxLines: 1,
                        overflow: TextOverflow.fade,
                        softWrap: false,
                        style: TextStyle(
                          fontSize: 17,
                          fontWeight: FontWeight.w600,
                          letterSpacing: 3,
                          color: TempleColors.blancoLuna,
                        ),
                      ),
                    ),
                    const SizedBox(width: 9),
                    Text(
                      kanjiDeEspiritu(espiritu),
                      style: TextStyle(fontSize: 14, color: tono.acento),
                    ),
                  ],
                ),
                const SizedBox(height: 3),
                AnimatedSwitcher(
                  duration: TempleMotion.rapido,
                  child: Text(
                    _pie,
                    key: ValueKey<String>(_pie),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      fontSize: 11.5,
                      letterSpacing: 0.4,
                      color: sinConexion && estado == EstadoAvatar.reposo
                          ? TempleColors.textoTenue
                          : TempleColors.textoSuave,
                    ),
                  ),
                ),
              ],
            ),
          ),
          IconButton(
            onPressed: onVoz,
            tooltip: 'Cómo te habla',
            icon: TempleIcon(tono.glifo, size: 19, color: tono.acento),
          ),
          IconButton(
            onPressed: onRecuerdos,
            tooltip: 'Lo que Tenshi recuerda',
            icon: Badge(
              isLabelVisible: recuerdos > 0,
              label: Text('$recuerdos'),
              backgroundColor: tono.acento.withValues(alpha: 0.85),
              textColor: TempleColors.negro,
              child: const Icon(Icons.bookmark_border_rounded,
                  size: 20, color: TempleColors.textoSuave),
            ),
          ),
          BotonMenuTemplo(onTap: onMenu),
        ],
      ),
    );
  }
}

