// ---------------------------------------------------------------------------
// 35.2 REPOSITORIO
// ---------------------------------------------------------------------------

class ClanRepo {
  ClanRepo._();
  static final ClanRepo instancia = ClanRepo._();

  String get _yo {
    final String? id = SesionTemplo.instancia.uid;
    if (id == null) throw const AuthFailure('Tu sesión se cerró. Vuelve a entrar.');
    return id;
  }

  List<Map<String, dynamic>> _filas(Object? r) => r is List
      ? r.map((Object? e) => Map<String, dynamic>.from(e as Map)).toList()
      : <Map<String, dynamic>>[];

  // -- Publicaciones --------------------------------------------------------

  Future<List<ClanPublicacion>> publicaciones({
    String modo = 'para_ti',
    DateTime? antes,
    String? deAutor,
    String? etiqueta,
    String? soloId,
    String? deClan,
    int limite = 15,
  }) async {
    final Object? r = await supa.rpc('publicaciones_lista', params: <String, dynamic>{
      'modo': modo,
      'antes': antes?.toUtc().toIso8601String(),
      'limite': limite,
      'de_autor': deAutor,
      'filtro_etiqueta': etiqueta,
      'solo_id': soloId,
      if (deClan != null) 'de_clan': deClan,
    });
    final List<ClanPublicacion> lista =
        _filas(r).map(ClanPublicacion.desdeMapa).toList();
    await MediosClan.instancia.firmar(<String>[
      for (final ClanPublicacion p in lista)
        for (final ClanMedio m in p.medios) m.ruta,
    ]);
    return lista;
  }

  Future<ClanPublicacion?> publicacion(String id) async {
    final List<ClanPublicacion> l = await publicaciones(soloId: id, limite: 1);
    return l.isEmpty ? null : l.first;
  }

  Future<void> publicar({
    required String id,
    required String texto,
    required List<ClanMedio> medios,
    Map<String, dynamic>? adjunto,
    String? clanId,
  }) async {
    await supa.from('publicaciones').insert(<String, dynamic>{
      'id': id,
      'autor': _yo,
      'texto': texto.trim(),
      'medios': medios.map((ClanMedio m) => m.aMapa()).toList(),
      if (adjunto != null) 'adjunto': adjunto,
      if (clanId != null) 'clan_id': clanId,
    });
  }

  Future<void> borrarPublicacion(ClanPublicacion p) async {
    await supa.from('publicaciones').delete().eq('id', p.id);
    final List<String> rutas = p.medios.map((ClanMedio m) => m.ruta).toList();
    if (rutas.isNotEmpty) {
      try {
        await supa.storage.from(MediosClan.bucket).remove(rutas);
      } catch (_) {}
    }
  }

  Future<void> darRespeto(String publicacionId, bool dar) async {
    if (dar) {
      await supa.from('respetos').insert(<String, dynamic>{
        'publicacion_id': publicacionId,
        'usuario': _yo,
      });
    } else {
      await supa
          .from('respetos')
          .delete()
          .eq('publicacion_id', publicacionId)
          .eq('usuario', _yo);
    }
  }

  // -- Comentarios ----------------------------------------------------------

  Future<List<ClanComentario>> comentarios(String publicacionId) async {
    final Object? r = await supa.rpc('comentarios_de',
        params: <String, dynamic>{'pub': publicacionId});
    return _filas(r).map(ClanComentario.desdeMapa).toList();
  }

  Future<void> comentar(String publicacionId, String texto) async {
    await supa.from('comentarios').insert(<String, dynamic>{
      'publicacion_id': publicacionId,
      'autor': _yo,
      'texto': texto.trim(),
    });
  }

  Future<void> borrarComentario(String id) async {
    await supa.from('comentarios').delete().eq('id', id);
  }

  // -- Perfiles y seguidores ------------------------------------------------

  Future<ClanPerfilPublico?> perfil(String id) async {
    final Object? r =
        await supa.rpc('perfil_publico', params: <String, dynamic>{'u': id});
    if (r is! Map) return null;
    return ClanPerfilPublico.desdeMapa(Map<String, dynamic>.from(r));
  }

  Future<void> seguir(String id, bool seguir) async {
    if (seguir) {
      await supa.from('seguidores').insert(<String, dynamic>{
        'seguidor': _yo,
        'seguido': id,
      });
    } else {
      await supa.from('seguidores').delete().eq('seguidor', _yo).eq('seguido', id);
    }
  }

  Future<List<ClanPersona>> listaSeguidores(String id, {required bool siguiendo}) async {
    final Object? r = await supa.rpc('lista_seguidores', params: <String, dynamic>{
      'u': id,
      'cuales': siguiendo ? 'siguiendo' : 'seguidores',
    });
    return _filas(r).map(ClanPersona.desdeMapa).toList();
  }

  // -- Búsqueda -------------------------------------------------------------

  Future<List<ClanPersona>> buscarPersonas(String q) async {
    final Object? r =
        await supa.rpc('buscar_usuarios', params: <String, dynamic>{'q': q});
    return _filas(r).map(ClanPersona.desdeMapa).toList();
  }

  Future<List<MapEntry<String, int>>> hashtags(String q) async {
    final Object? r = q.trim().isEmpty
        ? await supa.rpc('tendencias')
        : await supa.rpc('buscar_hashtags', params: <String, dynamic>{'q': q});
    return _filas(r)
        .map((Map<String, dynamic> m) => MapEntry<String, int>(
            m['etiqueta'] as String, (m['usos'] as num?)?.toInt() ?? 0))
        .toList();
  }

  // -- Mensajes -------------------------------------------------------------

  Future<List<ClanConversacion>> bandeja() async {
    final Object? r = await supa.rpc('bandeja');
    return _filas(r).map(ClanConversacion.desdeMapa).toList();
  }

  Future<int> sinLeer() async {
    final Object? r = await supa.rpc('mensajes_sin_leer');
    return r is num ? r.toInt() : 0;
  }

  Future<String> abrirConversacion(String otro) async {
    final Object? r =
        await supa.rpc('abrir_conversacion', params: <String, dynamic>{'otro': otro});
    return r.toString();
  }

  Future<Map<String, dynamic>?> conversacion(String id) async {
    final List<Map<String, dynamic>> r = await supa
        .from('conversaciones')
        .select('id, estado, creada_por')
        .eq('id', id)
        .limit(1);
    return r.isEmpty ? null : r.first;
  }

  Stream<List<ClanMensaje>> mensajes(String conversacionId) {
    return supa
        .from('mensajes')
        .stream(primaryKey: <String>['id'])
        .eq('conversacion_id', conversacionId)
        .order('id', ascending: true)
        .map((List<Map<String, dynamic>> filas) =>
            filas.map(ClanMensaje.desdeMapa).toList());
  }

  Future<void> enviar(String conversacionId, String texto) async {
    await supa.from('mensajes').insert(<String, dynamic>{
      'conversacion_id': conversacionId,
      'autor': _yo,
      'texto': texto.trim(),
    });
  }

  Future<void> marcarLeido(String conversacionId) async {
    try {
      await supa
          .from('participantes')
          .update(<String, dynamic>{
            'ultima_lectura': DateTime.now().toUtc().toIso8601String(),
          })
          .eq('conversacion_id', conversacionId)
          .eq('usuario', _yo);
    } catch (_) {}
  }

  Future<void> responderSolicitud(String conversacionId, bool aceptar) async {
    await supa.rpc('responder_solicitud', params: <String, dynamic>{
      'c': conversacionId,
      'aceptar': aceptar,
    });
  }

  // -- Seguridad ------------------------------------------------------------

  Future<void> reportar({
    required String tipo,
    required String objetivo,
    required String motivo,
    String detalle = '',
  }) async {
    try {
      await supa.from('reportes').insert(<String, dynamic>{
        'reportante': _yo,
        'tipo': tipo,
        'objetivo': objetivo,
        'motivo': motivo,
        'detalle': detalle.trim(),
      });
    } on PostgrestException catch (e) {
      // Ya lo habías reportado: no es un error para la persona.
      if (e.code != '23505') rethrow;
    }
  }

  Future<void> bloquear(String id) async {
    try {
      await supa.from('bloqueos').insert(<String, dynamic>{
        'bloqueador': _yo,
        'bloqueado': id,
      });
    } on PostgrestException catch (e) {
      if (e.code != '23505') rethrow;
    }
  }

  Future<void> desbloquear(String id) async {
    await supa.from('bloqueos').delete().eq('bloqueador', _yo).eq('bloqueado', id);
  }

  Future<List<ClanPersona>> bloqueados() async {
    final Object? r = await supa.rpc('mis_bloqueados');
    return _filas(r).map(ClanPersona.desdeMapa).toList();
  }
}

// ---------------------------------------------------------------------------
// 35.3 MEDIOS
//
// El bucket es privado: cada archivo se ve con una URL firmada que caduca en
// una hora y que el servidor solo entrega si puedes ver al autor. Se
// guardan en memoria para no pedirlas dos veces.
// ---------------------------------------------------------------------------

class MediosClan {
  MediosClan._();
  static final MediosClan instancia = MediosClan._();

  static const String bucket = 'clan';
  static const int maxBytes = 50 * 1024 * 1024;

  final Map<String, MapEntry<String, DateTime>> _urls =
      <String, MapEntry<String, DateTime>>{};

  String? url(String ruta) {
    final MapEntry<String, DateTime>? e = _urls[ruta];
    if (e == null || DateTime.now().isAfter(e.value)) return null;
    return e.key;
  }

  Future<void> firmar(List<String> rutas) async {
    final List<String> faltan =
        rutas.where((String r) => url(r) == null).toSet().toList();
    if (faltan.isEmpty) return;
    try {
      final List<SignedUrl> firmadas =
          await supa.storage.from(bucket).createSignedUrls(faltan, 3600);
      final DateTime caduca = DateTime.now().add(const Duration(minutes: 55));
      for (final SignedUrl s in firmadas) {
        _urls[s.path] = MapEntry<String, DateTime>(s.signedUrl, caduca);
      }
    } catch (_) {
      // Si falla, las imágenes mostrarán su estado de error y se reintenta.
    }
  }

  Future<String?> urlDe(String ruta) async {
    final String? u = url(ruta);
    if (u != null) return u;
    await firmar(<String>[ruta]);
    return url(ruta);
  }

  static String _extension(XFile f, {required bool video}) {
    final String n = f.name.toLowerCase();
    final int punto = n.lastIndexOf('.');
    final String ext = punto == -1 ? '' : n.substring(punto + 1);
    const Set<String> validas = <String>{'jpg', 'jpeg', 'png', 'webp', 'gif', 'heic', 'mp4', 'mov', 'webm'};
    if (validas.contains(ext)) return ext == 'jpeg' ? 'jpg' : ext;
    return video ? 'mp4' : 'jpg';
  }

  static String _tipoMime(String ext) {
    switch (ext) {
      case 'png':
        return 'image/png';
      case 'webp':
        return 'image/webp';
      case 'gif':
        return 'image/gif';
      case 'heic':
        return 'image/heic';
      case 'mp4':
        return 'video/mp4';
      case 'mov':
        return 'video/quicktime';
      case 'webm':
        return 'video/webm';
      default:
        return 'image/jpeg';
    }
  }

  /// Sube un archivo a la carpeta propia: <uid>/<publicación>/<n>.<ext>
  Future<ClanMedio> subir({
    required XFile archivo,
    required String publicacionId,
    required int indice,
    required bool video,
  }) async {
    final String? yo = SesionTemplo.instancia.uid;
    if (yo == null) throw const AuthFailure('Tu sesión se cerró. Vuelve a entrar.');
    final Uint8List bytes = await archivo.readAsBytes();
    if (bytes.length > maxBytes) {
      throw const AuthFailure('El archivo pesa más de 50 MB. Elige uno más corto.');
    }
    final String ext = _extension(archivo, video: video);
    final String ruta = '$yo/$publicacionId/$indice.$ext';
    try {
      await supa.storage.from(bucket).uploadBinary(
            ruta,
            bytes,
            fileOptions: FileOptions(contentType: _tipoMime(ext), upsert: false),
          );
    } on StorageException catch (e) {
      // El servidor solo acepta videos de cuentas con el Pase activo.
      final String m = e.message.toLowerCase();
      if (video && (e.statusCode == '403' || m.contains('row-level security') || m.contains('unauthorized'))) {
        throw const AuthFailure('Subir videos al Clan es una ventaja del Pase del Templo. '
            'Si ya lo tienes, cierra y vuelve a abrir la app.');
      }
      rethrow;
    }
    return ClanMedio(ruta: ruta, tipo: video ? 'video' : 'foto');
  }
}

/// Identificador v4 generado en el dispositivo: así las rutas de los archivos
/// y la publicación comparten nombre antes de existir en el servidor.
String uuidClan() {
  final math.Random r = math.Random.secure();
  final List<int> b = List<int>.generate(16, (_) => r.nextInt(256));
  b[6] = (b[6] & 0x0f) | 0x40;
  b[8] = (b[8] & 0x3f) | 0x80;
  final String h = b.map((int x) => x.toRadixString(16).padLeft(2, '0')).join();
  return '${h.substring(0, 8)}-${h.substring(8, 12)}-${h.substring(12, 16)}-'
      '${h.substring(16, 20)}-${h.substring(20)}';
}

// ---------------------------------------------------------------------------
// 35.4 PIEZAS VISUALES COMPARTIDAS
// ---------------------------------------------------------------------------

String tiempoClan(DateTime t) {
  final Duration d = DateTime.now().difference(t);
  if (d.inSeconds < 60) return 'ahora';
  if (d.inMinutes < 60) return 'hace ${d.inMinutes} min';
  if (d.inHours < 24) return 'hace ${d.inHours} h';
  if (d.inDays < 7) return 'hace ${d.inDays} d';
  final String mes = kMesesTemplo[t.month - 1].substring(0, 3);
  return t.year == DateTime.now().year ? '${t.day} $mes' : '${t.day} $mes ${t.year}';
}

String horaClan(DateTime t) =>
    '${t.hour.toString().padLeft(2, '0')}:${t.minute.toString().padLeft(2, '0')}';

void avisoClan(BuildContext context, String texto, {bool error = false}) {
  ScaffoldMessenger.of(context)
