/// Texto de publicación con los hashtags tocables.
class TextoClan extends StatelessWidget {
  const TextoClan({
    super.key,
    required this.texto,
    this.estilo = const TextStyle(fontSize: 14, height: 1.5, color: TempleColors.texto),
    this.maxLineas,
  });

  final String texto;
  final TextStyle estilo;
  final int? maxLineas;

  static final RegExp _hashtag = RegExp(r'#([A-Za-z0-9_ÁÉÍÓÚÑÜáéíóúñü]{2,40})');

  @override
  Widget build(BuildContext context) {
    final List<InlineSpan> partes = <InlineSpan>[];
    int cursor = 0;
    for (final RegExpMatch m in _hashtag.allMatches(texto)) {
      if (m.start > cursor) partes.add(TextSpan(text: texto.substring(cursor, m.start)));
      final String etiqueta = m.group(1)!.toLowerCase();
      partes.add(WidgetSpan(
        alignment: PlaceholderAlignment.baseline,
        baseline: TextBaseline.alphabetic,
        child: GestureDetector(
          onTap: () => Navigator.of(context).push(MaterialPageRoute<void>(
            builder: (_) => HashtagScreen(etiqueta: etiqueta),
          )),
          child: Text(
            m.group(0)!,
            style: estilo.copyWith(color: TempleColors.violetaClaro, fontWeight: FontWeight.w600),
          ),
        ),
      ));
      cursor = m.end;
    }
    if (cursor < texto.length) partes.add(TextSpan(text: texto.substring(cursor)));
    return Text.rich(
      TextSpan(style: estilo, children: partes),
      maxLines: maxLineas,
      overflow: maxLineas == null ? TextOverflow.clip : TextOverflow.ellipsis,
    );
  }
}

/// Imagen del bucket privado: pide su URL firmada si aún no la tiene.
class ImagenClan extends StatefulWidget {
  const ImagenClan({super.key, required this.ruta, this.fit = BoxFit.cover});

  final String ruta;
  final BoxFit fit;

  @override
  State<ImagenClan> createState() => _ImagenClanState();
}

class _ImagenClanState extends State<ImagenClan> {
  String? _url;
  bool _fallo = false;

  @override
  void initState() {
    super.initState();
    _url = MediosClan.instancia.url(widget.ruta);
    if (_url == null) _cargar();
  }

  Future<void> _cargar() async {
    final String? u = await MediosClan.instancia.urlDe(widget.ruta);
    if (!mounted) return;
    setState(() {
      _url = u;
      _fallo = u == null;
    });
  }

  @override
  Widget build(BuildContext context) {
    if (_fallo) return const _MedioRoto();
    if (_url == null) return const _MedioCargando();
    return Image.network(
      _url!,
      fit: widget.fit,
      gaplessPlayback: true,
      loadingBuilder: (BuildContext c, Widget hijo, ImageChunkEvent? p) =>
          p == null ? hijo : const _MedioCargando(),
      errorBuilder: (BuildContext c, Object e, StackTrace? s) => const _MedioRoto(),
    );
  }
}

class _MedioCargando extends StatelessWidget {
  const _MedioCargando();

  @override
  Widget build(BuildContext context) {
    return Container(
      color: TempleColors.superficie,
      alignment: Alignment.center,
      child: const SizedBox(
        width: 20,
        height: 20,
        child: CircularProgressIndicator(strokeWidth: 1.6, color: TempleColors.violeta),
