// ---------------------------------------------------------------------------
// 35.5 PANTALLA PRINCIPAL DEL CLAN
// ---------------------------------------------------------------------------

class ClanScreen extends StatefulWidget {
  const ClanScreen({super.key});

  @override
  State<ClanScreen> createState() => _ClanScreenState();
}

class _ClanScreenState extends State<ClanScreen> {
  int _pestana = 0; // 0 = Para ti, 1 = Siguiendo
  final GlobalKey<_FeedClanState> _paraTi = GlobalKey<_FeedClanState>();
  final GlobalKey<_FeedClanState> _siguiendo = GlobalKey<_FeedClanState>();

  int _sinLeer = 0;
  RealtimeChannel? _canal;
  bool _sincronizado = false;

  @override
  void initState() {
    super.initState();
    _contarMensajes();
    // Cualquier mensaje nuevo que me llegue actualiza el contador. El
    // servidor solo envía los de conversaciones en las que participo.
    _canal = supa
        .channel('clan-bandeja')
        .onPostgresChanges(
          event: PostgresChangeEvent.insert,
          schema: 'public',
          table: 'mensajes',
          callback: (PostgresChangePayload _) => _contarMensajes(),
        )
        .subscribe();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (!_sincronizado) {
      _sincronizado = true;
      // Lleva al perfil público el nombre, el sello y el nivel actuales.
      SesionTemplo.instancia.sincronizarIdentidad(TempleShellScope.of(context).perfil.nombre);
    }
  }

  @override
  void dispose() {
    final RealtimeChannel? c = _canal;
    if (c != null) supa.removeChannel(c);
    super.dispose();
  }

  Future<void> _contarMensajes() async {
    try {
      final int n = await ClanRepo.instancia.sinLeer();
      if (mounted) setState(() => _sinLeer = n);
    } catch (_) {}
  }

  Future<void> _publicar() async {
    final MiClanInfo? mio = ClanesRepo.instancia.mio;
    final bool alMuro = _pestana == 2 && mio != null && mio.activo;
    final bool? hecho = await Navigator.of(context).push<bool>(
      MaterialPageRoute<bool>(
        builder: (_) => alMuro ? PublicarScreen(clanId: mio.id, clanNombre: mio.nombre) : const PublicarScreen(),
      ),
    );
    if (hecho == true && !alMuro) {
      _paraTi.currentState?.recargar();
      _siguiendo.currentState?.recargar();
    }
  }

  Future<void> _abrir(Widget pantalla) async {
    await Navigator.of(context).push(MaterialPageRoute<void>(builder: (_) => pantalla));
    _contarMensajes();
  }

  @override
  Widget build(BuildContext context) {
    final String? yo = SesionTemplo.instancia.uid;
    return SafeArea(
      bottom: false,
      child: Stack(
        children: <Widget>[
          Column(
            children: <Widget>[
              Padding(
                padding: const EdgeInsets.fromLTRB(TempleSpace.borde, 10, 8, 0),
                child: Row(
                  children: <Widget>[
                    const Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: <Widget>[
                          Text('Clan',
                              style: TextStyle(
                                  fontSize: 26,
                                  fontWeight: FontWeight.w600,
                                  letterSpacing: 0.4,
                                  color: TempleColors.blancoLuna)),
                          SizedBox(height: 2),
                          Text('Aquí solo se habla de progreso',
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(fontSize: 12.5, color: TempleColors.textoSuave)),
                        ],
                      ),
                    ),
                    const BotonActividad(),
                    IconButton(
                      visualDensity: VisualDensity.compact,
