/// Lista paginada de publicaciones. La usan el feed, los hashtags y el
/// detalle de un perfil.
class FeedClan extends StatefulWidget {
  const FeedClan({
    super.key,
    this.modo = 'para_ti',
    this.etiqueta,
    this.deAutor,
    this.clanId,
    this.alRecargar,
    required this.vacio,
    this.cabecera,
    this.relleno = const EdgeInsets.fromLTRB(TempleSpace.borde, 8, TempleSpace.borde, 0),
  });

  final String modo;
  final String? etiqueta;
  final String? deAutor;

  /// El muro de un clan.
  final String? clanId;

  /// Al tirar para recargar (la cabecera también se refresca).
  final Future<void> Function()? alRecargar;
  final Widget vacio;
  final Widget? cabecera;
  final EdgeInsets relleno;

  @override
  State<FeedClan> createState() => _FeedClanState();
}

class _FeedClanState extends State<FeedClan> {
  final List<ClanPublicacion> _lista = <ClanPublicacion>[];
  final ScrollController _scroll = ScrollController();
  bool _cargando = false;
  bool _fin = false;
  String? _error;

  @override
  void initState() {
    super.initState();
    _scroll.addListener(() {
      if (_scroll.position.pixels > _scroll.position.maxScrollExtent - 600) _mas();
    });
    recargar();
  }

  @override
  void dispose() {
    _scroll.dispose();
    super.dispose();
  }

  Future<void> recargar() async {
    setState(() {
      _lista.clear();
      _fin = false;
      _error = null;
    });
    final Future<void> Function()? extra = widget.alRecargar;
    await Future.wait(<Future<void>>[_mas(), if (extra != null) extra()]);
  }

  Future<void> _mas() async {
    if (_cargando || _fin) return;
    setState(() => _cargando = true);
    try {
      final List<ClanPublicacion> nuevas = await ClanRepo.instancia.publicaciones(
        modo: widget.modo,
        etiqueta: widget.etiqueta,
        deAutor: widget.deAutor,
        deClan: widget.clanId,
        antes: _lista.isEmpty ? null : _lista.last.creadoEn,
      );
      if (!mounted) return;
      setState(() {
        _lista.addAll(nuevas);
        _fin = nuevas.length < 15;
        _error = null;
      });
    } catch (e) {
      if (mounted) setState(() => _error = SesionTemplo.mensajeDe(e));
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  void _quitar(ClanPublicacion p) => setState(() => _lista.remove(p));

  @override
  Widget build(BuildContext context) {
    final double abajo = kAlturaNavBar + MediaQuery.paddingOf(context).bottom + 96;
    final bool vacio = _lista.isEmpty && !_cargando && _error == null;

    return RefreshIndicator(
      color: TempleColors.violeta,
      backgroundColor: TempleColors.superficieAlta,
      onRefresh: recargar,
      child: ListView.builder(
        controller: _scroll,
        physics: const AlwaysScrollableScrollPhysics(),
        padding: widget.relleno.copyWith(bottom: abajo),
        itemCount: _lista.length + 2,
        itemBuilder: (BuildContext context, int i) {
          if (i == 0) {
            return widget.cabecera ?? const SizedBox.shrink();
          }
          if (i == _lista.length + 1) {
            if (_error != null) {
              return VacioClan(
                glifo: TempleGlyph.montana,
                titulo: 'No pudimos cargar el Clan',
                texto: _error!,
                accion: 'Reintentar',
                onAccion: _lista.isEmpty ? recargar : _mas,
              );
            }
            if (vacio) return widget.vacio;
            if (_cargando) {
              return const Padding(
                padding: EdgeInsets.all(28),
                child: Center(
                  child: SizedBox(
                    width: 22,
                    height: 22,
                    child: CircularProgressIndicator(strokeWidth: 1.8, color: TempleColors.violeta),
                  ),
                ),
              );
            }
            return const SizedBox(height: 12);
          }
          final ClanPublicacion p = _lista[i - 1];
          return Padding(
            padding: const EdgeInsets.only(bottom: 14),
            child: TarjetaPublicacion(
              key: ValueKey<String>(p.id),
              publicacion: p,
              onEliminada: () => _quitar(p),
            ),
          );
        },
      ),
    );
  }
}

// ---------------------------------------------------------------------------
// 35.6 TARJETA DE PUBLICACIÓN
// ---------------------------------------------------------------------------

class TarjetaPublicacion extends StatefulWidget {
  const TarjetaPublicacion({
    super.key,
    required this.publicacion,
    required this.onEliminada,
    this.enDetalle = false,
  });

  final ClanPublicacion publicacion;
  final VoidCallback onEliminada;
  final bool enDetalle;

  @override
  State<TarjetaPublicacion> createState() => _TarjetaPublicacionState();
}

class _TarjetaPublicacionState extends State<TarjetaPublicacion> {
  bool _destello = false;
  bool _enviando = false;

  ClanPublicacion get _p => widget.publicacion;

  Future<void> _respeto({bool soloDar = false}) async {
    if (_enviando) return;
    if (soloDar && _p.yoRespeto) {
      setState(() => _destello = true);
      Future<void>.delayed(const Duration(milliseconds: 700), () {
        if (mounted) setState(() => _destello = false);
      });
      return;
    }
    final bool dar = !_p.yoRespeto;
    HapticFeedback.lightImpact();
    if (dar) sonar(SonidoTemplo.respeto);
    setState(() {
      _enviando = true;
      _p.yoRespeto = dar;
      _p.nRespetos += dar ? 1 : -1;
      if (dar) _destello = true;
    });
    if (dar) {
      Future<void>.delayed(const Duration(milliseconds: 700), () {
        if (mounted) setState(() => _destello = false);
      });
    }
    try {
      await ClanRepo.instancia.darRespeto(_p.id, dar);
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _p.yoRespeto = !dar;
        _p.nRespetos += dar ? -1 : 1;
      });
      avisoClan(context, SesionTemplo.mensajeDe(e), error: true);
    } finally {
      if (mounted) setState(() => _enviando = false);
    }
  }

  void _abrirPerfil() {
    Navigator.of(context).push(MaterialPageRoute<void>(
      builder: (_) => PerfilClanScreen(id: _p.autor.id),
    ));
  }

  /// Comentarios en hoja rápida, sin salir del feed. En el detalle ya están
  /// abajo, así que ahí el botón solo lleva a escribir.
  Future<void> _comentarios() async {
    await mostrarComentarios(context, _p);
    if (mounted) setState(() {});
  }

  Future<void> _abrirDetalle() async {
    if (widget.enDetalle) return;
    final bool? eliminada = await Navigator.of(context).push<bool>(MaterialPageRoute<bool>(
      builder: (_) => DetallePublicacionScreen(publicacion: _p),
    ));
    if (eliminada == true) {
      widget.onEliminada();
    } else if (mounted) {
      setState(() {});
    }
  }

  void _opciones() {
    mostrarOpcionesClan(context, <OpcionHoja>[
      if (_p.esMia)
        OpcionHoja(Icons.delete_outline_rounded, 'Eliminar publicación', () async {
          final bool ok = await confirmarClan(
            context,
            titulo: 'Eliminar publicación',
            texto: 'Se borrará para siempre, con sus fotos, videos y comentarios.',
            accion: 'Eliminar',
            peligro: true,
          );
          if (!ok) return;
          try {
            await ClanRepo.instancia.borrarPublicacion(_p);
            if (!mounted) return;
            avisoClan(context, 'Publicación eliminada');
            widget.onEliminada();
          } catch (e) {
            if (mounted) avisoClan(context, SesionTemplo.mensajeDe(e), error: true);
          }
        }, peligro: true)
      else ...<OpcionHoja>[
        OpcionHoja(Icons.flag_outlined, 'Reportar publicación', () async {
          final bool hecho = await mostrarReporte(
            context,
            tipo: 'publicacion',
            objetivo: _p.id,
            persona: _p.autor,
          );
          if (hecho) widget.onEliminada();
        }, peligro: true),
        OpcionHoja(Icons.block_rounded, 'Bloquear a @${_p.autor.usuario}', () async {
          final bool hecho = await bloquearConConfirmacion(context, _p.autor);
          if (hecho) widget.onEliminada();
        }, peligro: true),
        OpcionHoja(Icons.person_outline_rounded, 'Ver perfil', _abrirPerfil),
      ],
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final ClanPublicacion p = _p;
    return Container(
      decoration: BoxDecoration(
        color: TempleColors.superficie.withValues(alpha: 0.92),
        borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
        border: Border.all(color: TempleColors.borde),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: <Widget>[
          // -- Autor ---------------------------------------------------------
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 12, 4, 8),
            child: Row(
              children: <Widget>[
                ClanAvatar(persona: p.autor, size: 40, onTap: _abrirPerfil),
                const SizedBox(width: 11),
                Expanded(
                  child: GestureDetector(
                    onTap: _abrirPerfil,
                    behavior: HitTestBehavior.opaque,
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: <Widget>[
                        Row(
                          children: <Widget>[
                            Flexible(
                              child: NombreConEstilo(p.autor.nombre,
                                  estilo: p.autor.estilo,
                                  insignia: p.autor.pase,
                                  style: const TextStyle(
                                      fontSize: 14,
                                      fontWeight: FontWeight.w600,
                                      color: TempleColors.blancoLuna)),
                            ),
                            const SizedBox(width: 7),
                            Container(
                              padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                              decoration: BoxDecoration(
                                color: TempleColors.violeta.withValues(alpha: 0.12),
                                borderRadius: BorderRadius.circular(6),
                              ),
                              child: Text('Nv ${p.autor.nivel}',
                                  style: const TextStyle(
                                      fontSize: 10,
                                      fontWeight: FontWeight.w600,
                                      color: TempleColors.violetaClaro)),
                            ),
                          ],
                        ),
                        const SizedBox(height: 2),
                        Text('@${p.autor.usuario} · ${tiempoClan(p.creadoEn)}',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(fontSize: 11.5, color: TempleColors.textoTenue)),
                      ],
                    ),
                  ),
                ),
                IconButton(
                  tooltip: 'Opciones',
                  onPressed: _opciones,
                  icon: const Icon(Icons.more_horiz_rounded, color: TempleColors.textoSuave),
                ),
              ],
            ),
          ),

          if (p.oculta && p.esMia)
            Container(
              margin: const EdgeInsets.fromLTRB(14, 0, 14, 10),
              padding: const EdgeInsets.all(10),
              decoration: BoxDecoration(
                color: TempleColors.alertaSuave.withValues(alpha: 0.10),
                borderRadius: BorderRadius.circular(TempleRadius.chip),
                border: Border.all(color: TempleColors.alertaSuave.withValues(alpha: 0.35)),
              ),
              child: const Text(
                'Esta publicación fue reportada y está oculta mientras la revisamos. '
                'Solo tú puedes verla.',
                style: TextStyle(fontSize: 12, height: 1.4, color: TempleColors.texto),
              ),
            ),

          // -- Texto ---------------------------------------------------------
          if (p.texto.trim().isNotEmpty)
            GestureDetector(
              onTap: _abrirDetalle,
              behavior: HitTestBehavior.opaque,
              child: Padding(
                padding: EdgeInsets.fromLTRB(14, 0, 14, p.medios.isEmpty ? 12 : 10),
                child: TextoClan(
                  texto: p.texto,
                  maxLineas: widget.enDetalle ? null : 6,
                  estilo: TextStyle(
                    fontSize: p.medios.isEmpty && p.texto.length < 120 ? 16 : 14,
                    height: 1.5,
                    color: TempleColors.texto,
                  ),
                ),
              ),
            ),

          // -- Récord, sesión o rutina (sección 55) ---------------------------
          if (p.adjunto != null)
            Padding(
              padding: EdgeInsets.fromLTRB(12, p.texto.trim().isEmpty ? 0 : 2, 12, p.medios.isEmpty ? 12 : 10),
              child: TarjetaAdjunto(adjunto: p.adjunto!),
            ),

          // -- Medios --------------------------------------------------------
          if (p.medios.isNotEmpty)
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 10),
              child: GestureDetector(
                onDoubleTap: () => _respeto(soloDar: true),
                child: Stack(
                  alignment: Alignment.center,
                  children: <Widget>[
                    ClipRRect(
                      borderRadius: BorderRadius.circular(TempleRadius.campo),
                      child: p.medios.first.esVideo
                          ? VideoClan(ruta: p.medios.first.ruta)
                          : GaleriaClan(medios: p.medios),
                    ),
                    IgnorePointer(
                      child: AnimatedOpacity(
                        duration: const Duration(milliseconds: 260),
                        opacity: _destello ? 1 : 0,
                        child: AnimatedScale(
                          duration: const Duration(milliseconds: 420),
                          curve: Curves.easeOutBack,
                          scale: _destello ? 1 : 0.6,
                          child: Container(
                            width: 96,
                            height: 96,
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
                              color: TempleColors.negro.withValues(alpha: 0.45),
                              boxShadow: <BoxShadow>[
                                BoxShadow(
                                  color: TempleColors.violeta.withValues(alpha: 0.5),
                                  blurRadius: 40,
                                ),
                              ],
                            ),
                            alignment: Alignment.center,
                            child: const TempleIcon(TempleGlyph.loto,
                                size: 52, color: TempleColors.violetaClaro, trazo: 2),
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ),

          // -- Acciones ------------------------------------------------------
          Padding(
            padding: const EdgeInsets.fromLTRB(6, 4, 10, 6),
            child: Row(
              children: <Widget>[
                _AccionPublicacion(
                  activa: p.yoRespeto,
                  glifo: TempleGlyph.loto,
                  texto: p.nRespetos == 0 ? 'Respeto' : '${p.nRespetos}',
                  onTap: () => _respeto(),
                  etiqueta: p.yoRespeto ? 'Quitar respeto' : 'Dar respeto',
                ),
                _AccionPublicacion(
                  activa: false,
                  icono: Icons.mode_comment_outlined,
                  texto: p.nComentarios == 0 ? 'Comentar' : '${p.nComentarios}',
                  onTap: _comentarios,
                  etiqueta: 'Comentarios',
                ),
              ],
            ),
          ),
          if (!widget.enDetalle)
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 0, 16, 12),
            child: GestureDetector(
              onTap: _comentarios,
              child: Text(
                p.nComentarios == 0
                    ? 'Sé el primero en comentar'
                    : p.nComentarios == 1
                        ? 'Ver el comentario'
                        : 'Ver los ${p.nComentarios} comentarios',
                style: const TextStyle(fontSize: 12.5, color: TempleColors.textoSuave),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _AccionPublicacion extends StatelessWidget {
  const _AccionPublicacion({
    required this.activa,
    required this.texto,
    required this.onTap,
    required this.etiqueta,
    this.glifo,
    this.icono,
  });

  final bool activa;
  final String texto;
  final VoidCallback onTap;
  final String etiqueta;
  final TempleGlyph? glifo;
  final IconData? icono;

  @override
  Widget build(BuildContext context) {
    final Color color = activa ? TempleColors.violetaClaro : TempleColors.textoSuave;
    return Semantics(
      button: true,
      label: etiqueta,
      child: InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(TempleRadius.pastilla),
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
          child: Row(
            children: <Widget>[
              AnimatedScale(
                duration: TempleMotion.rapido,
                scale: activa ? 1.12 : 1,
                child: glifo != null
                    ? TempleIcon(glifo!, size: 21, color: color, trazo: activa ? 2.1 : 1.7)
                    : Icon(icono, size: 19, color: color),
              ),
              const SizedBox(width: 7),
              Text(texto,
                  style: TextStyle(
                      fontSize: 12.5,
                      fontWeight: activa ? FontWeight.w600 : FontWeight.w400,
                      color: color)),
            ],
          ),
        ),
      ),
    );
  }
}

/// Hasta cuatro fotos que se deslizan, con puntos de posición.
class GaleriaClan extends StatefulWidget {
  const GaleriaClan({super.key, required this.medios});
  final List<ClanMedio> medios;

  @override
  State<GaleriaClan> createState() => _GaleriaClanState();
}

class _GaleriaClanState extends State<GaleriaClan> {
  int _i = 0;

  @override
  Widget build(BuildContext context) {
    final List<ClanMedio> fotos = widget.medios;
    return AspectRatio(
      aspectRatio: 4 / 5,
      child: Stack(
        children: <Widget>[
          PageView.builder(
            itemCount: fotos.length,
            onPageChanged: (int i) => setState(() => _i = i),
            itemBuilder: (BuildContext c, int i) => ImagenClan(ruta: fotos[i].ruta),
          ),
          if (fotos.length > 1) ...<Widget>[
            Positioned(
              top: 10,
              right: 10,
              child: Container(
                padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 4),
                decoration: BoxDecoration(
                  color: TempleColors.negro.withValues(alpha: 0.6),
                  borderRadius: BorderRadius.circular(TempleRadius.pastilla),
                ),
                child: Text('${_i + 1}/${fotos.length}',
                    style: const TextStyle(fontSize: 11, color: TempleColors.blancoLuna)),
              ),
            ),
            Positioned(
              bottom: 10,
              left: 0,
              right: 0,
              child: Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: <Widget>[
                  for (int i = 0; i < fotos.length; i++)
                    AnimatedContainer(
                      duration: TempleMotion.rapido,
                      width: i == _i ? 16 : 6,
                      height: 6,
                      margin: const EdgeInsets.symmetric(horizontal: 3),
                      decoration: BoxDecoration(
                        color: i == _i
                            ? TempleColors.blancoLuna
                            : TempleColors.blancoLuna.withValues(alpha: 0.4),
                        borderRadius: BorderRadius.circular(3),
                      ),
                    ),
                ],
              ),
            ),
          ],
        ],
      ),
    );
  }
}

/// Video que se reproduce al tocarlo. Se carga solo cuando se pide, para no
/// gastar datos en todo el feed.
class VideoClan extends StatefulWidget {
  const VideoClan({super.key, required this.ruta});
  final String ruta;

  @override
  State<VideoClan> createState() => _VideoClanState();
}

class _VideoClanState extends State<VideoClan> {
  VideoPlayerController? _c;
  bool _cargando = false;
  String? _error;
  bool _silencio = false;

  @override
  void dispose() {
    _c?.dispose();
    super.dispose();
  }

  Future<void> _tocar() async {
    final VideoPlayerController? c = _c;
    if (c != null && c.value.isInitialized) {
      setState(() {
        if (c.value.isPlaying) {
          c.pause();
        } else {
          c.play();
        }
      });
      return;
    }
    if (_cargando) return;
    setState(() {
      _cargando = true;
      _error = null;
    });
    try {
      final String? url = await MediosClan.instancia.urlDe(widget.ruta);
      if (url == null) throw const AuthFailure('No pudimos abrir el video');
      final VideoPlayerController nuevo = VideoPlayerController.networkUrl(Uri.parse(url));
      await nuevo.initialize();
      await nuevo.setLooping(true);
      nuevo.addListener(() {
        if (mounted) setState(() {});
      });
      if (!mounted) {
        nuevo.dispose();
        return;
      }
      setState(() => _c = nuevo);
      await nuevo.play();
    } catch (_) {
      if (mounted) {
        setState(() => _error = 'Este dispositivo no pudo reproducir el video.');
      }
    } finally {
      if (mounted) setState(() => _cargando = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final VideoPlayerController? c = _c;
    final bool listo = c != null && c.value.isInitialized;
    final double proporcion =
        listo ? c!.value.aspectRatio.clamp(0.56, 1.78).toDouble() : 4 / 5;

    return GestureDetector(
      onTap: _tocar,
      child: AspectRatio(
        aspectRatio: proporcion,
        child: Stack(
          fit: StackFit.expand,
          children: <Widget>[
            Container(
              decoration: const BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: <Color>[TempleColors.moradoProfundo, TempleColors.negro],
                ),
              ),
            ),
            if (listo) FittedBox(
              fit: BoxFit.cover,
              clipBehavior: Clip.hardEdge,
              child: SizedBox(
                width: c!.value.size.width,
                height: c.value.size.height,
                child: VideoPlayer(c),
              ),
            ),
            if (!listo || !c!.value.isPlaying)
              Center(
                child: _error != null
                    ? Padding(
                        padding: const EdgeInsets.all(20),
                        child: Text(_error!,
                            textAlign: TextAlign.center,
                            style: const TextStyle(fontSize: 12.5, color: TempleColors.textoSuave)),
                      )
                    : Container(
                        width: 64,
                        height: 64,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color: TempleColors.negro.withValues(alpha: 0.55),
                          border: Border.all(color: TempleColors.blancoLuna.withValues(alpha: 0.3)),
                        ),
                        child: _cargando
                            ? const Padding(
                                padding: EdgeInsets.all(20),
                                child: CircularProgressIndicator(
                                    strokeWidth: 1.8, color: TempleColors.blancoLuna),
                              )
                            : const Icon(Icons.play_arrow_rounded,
                                size: 36, color: TempleColors.blancoLuna),
                      ),
              ),
            if (listo)
              Positioned(
                right: 8,
                bottom: 8,
                child: IconButton(
                  tooltip: _silencio ? 'Activar sonido' : 'Silenciar',
                  onPressed: () {
                    setState(() => _silencio = !_silencio);
                    c!.setVolume(_silencio ? 0 : 1);
                  },
                  icon: Icon(_silencio ? Icons.volume_off_rounded : Icons.volume_up_rounded,
                      color: TempleColors.blancoLuna, size: 20),
                ),
              ),
            if (listo)
              Positioned(
                left: 0,
                right: 0,
                bottom: 0,
                child: VideoProgressIndicatorClan(controller: c!),
              ),
          ],
        ),
      ),
    );
  }
}

class VideoProgressIndicatorClan extends StatelessWidget {
  const VideoProgressIndicatorClan({super.key, required this.controller});
  final VideoPlayerController controller;

  @override
  Widget build(BuildContext context) {
    final Duration total = controller.value.duration;
    final Duration pos = controller.value.position;
    final double v = total.inMilliseconds <= 0
        ? 0
        : (pos.inMilliseconds / total.inMilliseconds).clamp(0.0, 1.0);
    return LinearProgressIndicator(
      value: v,
      minHeight: 2.5,
      backgroundColor: TempleColors.blancoLuna.withValues(alpha: 0.15),
      valueColor: const AlwaysStoppedAnimation<Color>(TempleColors.violetaClaro),
    );
  }
}

// ---------------------------------------------------------------------------
// 35.7 PUBLICAR
//
// Fotos: hasta cuatro, reducidas en el propio teléfono a 1600 px para que
// suban rápido y no gasten datos de más. Video: uno solo, de hasta 60
// segundos y 50 MB.
//
// Los permisos de cámara y galería los pide el sistema la primera vez que se
// usan. En Android moderno la galería no necesita permiso de almacenamiento:
// el selector del sistema entrega solo la foto elegida.
// ---------------------------------------------------------------------------

class _ArchivoElegido {
  _ArchivoElegido(this.archivo, this.bytes, {required this.video});
  final XFile archivo;
  final Uint8List? bytes; // vista previa de fotos
  final bool video;
}

class PublicarScreen extends StatefulWidget {
  const PublicarScreen({super.key, this.adjunto, this.clanId, this.clanNombre, this.textoInicial});

  /// Récord, sesión o rutina que se comparte (sección 55).
  final Map<String, dynamic>? adjunto;

  /// Publicar en el muro de este clan.
  final String? clanId;
  final String? clanNombre;
  final String? textoInicial;

  @override
  State<PublicarScreen> createState() => _PublicarScreenState();
}

class _PublicarScreenState extends State<PublicarScreen> {
  final TextEditingController _texto = TextEditingController();
  final ImagePicker _picker = ImagePicker();
  final List<_ArchivoElegido> _archivos = <_ArchivoElegido>[];

  bool _publicando = false;
  int _subidos = 0;
  String? _error;

  static const int _maxTexto = 2200;

  bool get _tieneVideo => _archivos.any((_ArchivoElegido a) => a.video);
  bool get _puedePublicar =>
      !_publicando && (_texto.text.trim().isNotEmpty || _archivos.isNotEmpty || widget.adjunto != null);

  /// En el muro del clan (si tienes uno) o en todo el Clan.
  late bool _enMuro = widget.clanId != null;

  String? get _clanDestino => widget.clanId ?? ClanesRepo.instancia.mio?.id;
  String? get _nombreClanDestino => widget.clanNombre ?? ClanesRepo.instancia.mio?.nombre;

  @override
  void initState() {
    super.initState();
    if ((widget.textoInicial ?? '').isNotEmpty) _texto.text = widget.textoInicial!;
    _texto.addListener(() => setState(() {}));
  }

  @override
  void dispose() {
    _texto.dispose();
    super.dispose();
  }

  Future<void> _fotosGaleria() async {
    if (_tieneVideo) {
      avisoClan(context, 'Un video va solo en su publicación. Quítalo para añadir fotos.');
      return;
    }
    final int libres = 4 - _archivos.length;
    if (libres <= 0) {
      avisoClan(context, 'Máximo cuatro fotos por publicación');
      return;
    }
    try {
      final List<XFile> elegidas =
          await _picker.pickMultiImage(maxWidth: 1600, maxHeight: 1600, imageQuality: 82);
      if (elegidas.isEmpty) return;
      if (elegidas.length > libres && mounted) {
        avisoClan(context, 'Solo se añadieron $libres: el máximo son cuatro fotos.');
      }
      for (final XFile f in elegidas.take(libres)) {
        _archivos.add(_ArchivoElegido(f, await f.readAsBytes(), video: false));
      }
      if (mounted) setState(() => _error = null);
    } catch (_) {
      if (mounted) avisoClan(context, 'No pudimos abrir la galería. Revisa los permisos.', error: true);
    }
  }

  Future<void> _fotoCamara() async {
    if (_tieneVideo || _archivos.length >= 4) {
      avisoClan(context, _tieneVideo
          ? 'Un video va solo en su publicación.'
          : 'Máximo cuatro fotos por publicación');
      return;
    }
    try {
      final XFile? f = await _picker.pickImage(
        source: ImageSource.camera,
        maxWidth: 1600,
        maxHeight: 1600,
        imageQuality: 82,
      );
      if (f == null) return;
      final Uint8List b = await f.readAsBytes();
      if (mounted) {
        setState(() {
          _archivos.add(_ArchivoElegido(f, b, video: false));
          _error = null;
        });
      }
    } catch (_) {
      if (mounted) {
        avisoClan(context, 'La cámara no está disponible en este dispositivo o no tiene permiso.',
            error: true);
      }
    }
  }

  /// Subir videos es una ventaja del Pase: el servidor también lo exige.
  Future<void> _muroVideos() => mostrarMuroPase(
        context,
        titulo: 'Videos con el Pase',
        texto: 'Subir videos al Clan es una ventaja del Pase del Templo: hasta '
            '${LimitesPase.videoPase} segundos, una serie completa de principio a fin. '
            'Las fotos siguen siendo gratis para todos.',
        icono: Icons.videocam_outlined,
      );

  Future<void> _video({required bool grabar}) async {
    if (!LimitesPase.pase) {
      await _muroVideos();
      return;
    }
    if (_archivos.isNotEmpty) {
      avisoClan(context, 'Un video va solo en su publicación. Quita las fotos primero.');
      return;
    }
    try {
      const int limite = LimitesPase.videoPase;
      final XFile? f = await _picker.pickVideo(
        source: grabar ? ImageSource.camera : ImageSource.gallery,
        maxDuration: const Duration(seconds: limite),
      );
      if (f == null) return;
      final Duration? dura = await duracionVideo(f);
      if (dura != null && dura.inMilliseconds > (limite + 1) * 1000) {
        if (!mounted) return;
        avisoClan(context, 'El video dura más de $limite s. Recórtalo y vuelve a intentarlo.', error: true);
        return;
      }
      final int peso = await f.length();
      if (peso > MediosClan.maxBytes) {
        if (mounted) {
          avisoClan(context, 'El video pesa más de 50 MB. Elige uno más corto.', error: true);
        }
        return;
      }
      if (mounted) {
        setState(() {
          _archivos.add(_ArchivoElegido(f, null, video: true));
          _error = null;
        });
      }
    } catch (_) {
      if (mounted) {
        avisoClan(context, grabar
            ? 'No se puede grabar video en este dispositivo.'
            : 'No pudimos abrir tus videos. Revisa los permisos.', error: true);
      }
    }
  }

  void _elegirVideo() {
    if (!LimitesPase.pase) {
      _muroVideos();
      return;
    }
    mostrarOpcionesClan(context, <OpcionHoja>[
      OpcionHoja(Icons.video_library_outlined, 'Elegir de la galería', () => _video(grabar: false)),
      OpcionHoja(Icons.videocam_outlined, 'Grabar ahora (máximo ${LimitesPase.videoPase} s)',
          () => _video(grabar: true)),
    ]);
  }

  Future<void> _publicar() async {
    if (!_puedePublicar) return;
    FocusScope.of(context).unfocus();
    setState(() {
      _publicando = true;
      _subidos = 0;
      _error = null;
    });
    final String id = uuidClan();
    final List<ClanMedio> subidos = <ClanMedio>[];
    try {
      for (int i = 0; i < _archivos.length; i++) {
        final _ArchivoElegido a = _archivos[i];
        subidos.add(await MediosClan.instancia.subir(
          archivo: a.archivo,
          publicacionId: id,
          indice: i,
          video: a.video,
        ));
        if (mounted) setState(() => _subidos = i + 1);
      }
      final String? clan = _enMuro ? _clanDestino : null;
      await ClanRepo.instancia.publicar(
        id: id,
        texto: _texto.text,
        medios: subidos,
        adjunto: widget.adjunto,
        clanId: clan,
      );
      if (clan != null) ClanesRepo.instancia.muro.value++;
      if (!mounted) return;
      HapticFeedback.heavyImpact();
      Navigator.of(context).pop(true);
    } catch (e) {
      // Si la publicación no se creó, se borran los archivos ya subidos.
      if (subidos.isNotEmpty) {
        try {
          await supa.storage
              .from(MediosClan.bucket)
              .remove(subidos.map((ClanMedio m) => m.ruta).toList());
        } catch (_) {}
      }
      if (mounted) {
        HapticFeedback.vibrate();
        setState(() {
          _publicando = false;
          _error = SesionTemplo.mensajeDe(e);
        });
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final int largo = _texto.text.length;
    final double abajo = MediaQuery.paddingOf(context).bottom;
    final String usuario = SesionTemplo.instancia.actual?.usuario ?? '';
    final String? espiritu = SesionTemplo.instancia.actual?.espiritu;
    final IdentidadUsuario ident = AlmacenIdentidad.instancia.de(usuario);

    return PopScope(
      canPop: !_publicando,
      child: Scaffold(
        backgroundColor: TempleColors.negro,
        body: FondoTemplo(
          child: SafeArea(
            bottom: false,
            child: Column(
              children: <Widget>[
                Padding(
                  padding: const EdgeInsets.fromLTRB(4, 4, 14, 4),
                  child: Row(
                    children: <Widget>[
                      IconButton(
                        tooltip: 'Cerrar',
                        onPressed: _publicando ? null : () => Navigator.of(context).maybePop(),
                        icon: const Icon(Icons.close_rounded, color: TempleColors.textoSuave),
                      ),
                      Expanded(
                        child: Text(_enMuro && _nombreClanDestino != null ? 'Muro de $_nombreClanDestino' : 'Nueva publicación',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                fontSize: 17,
                                fontWeight: FontWeight.w600,
                                color: TempleColors.blancoLuna)),
                      ),
                      AnimatedOpacity(
                        duration: TempleMotion.rapido,
                        opacity: _puedePublicar ? 1 : 0.4,
                        child: FilledButton(
                          onPressed: _puedePublicar ? _publicar : null,
                          style: FilledButton.styleFrom(
                            backgroundColor: TempleColors.violeta,
                            disabledBackgroundColor: TempleColors.violeta.withValues(alpha: 0.4),
                            foregroundColor: Colors.white,
                            padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 10),
                            shape: RoundedRectangleBorder(
                                borderRadius: BorderRadius.circular(TempleRadius.pastilla)),
                          ),
                          child: const Text('Publicar', style: TextStyle(fontWeight: FontWeight.w600)),
                        ),
                      ),
                    ],
                  ),
                ),
                if (_publicando)
                  Padding(
                    padding: const EdgeInsets.symmetric(horizontal: TempleSpace.borde, vertical: 6),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: <Widget>[
                        ClipRRect(
                          borderRadius: BorderRadius.circular(999),
                          child: LinearProgressIndicator(
                            value: _archivos.isEmpty ? null : _subidos / (_archivos.length + 1),
                            minHeight: 3,
                            backgroundColor: TempleColors.borde,
                            valueColor: const AlwaysStoppedAnimation<Color>(TempleColors.violeta),
                          ),
                        ),
                        const SizedBox(height: 6),
                        Text(
                          _archivos.isEmpty || _subidos >= _archivos.length
                              ? 'Publicando…'
                              : 'Subiendo ${_subidos + 1} de ${_archivos.length}…',
                          style: const TextStyle(fontSize: 11.5, color: TempleColors.textoSuave),
                        ),
                      ],
                    ),
                  ),
                Expanded(
                  child: ListView(
                    padding: const EdgeInsets.fromLTRB(TempleSpace.borde, 10, TempleSpace.borde, 20),
                    children: <Widget>[
                      Row(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: <Widget>[
                          SelloUsuario(
                            identidad: ident,
                            kanji: kanjiDeEspiritu(espiritu ?? ''),
                            nivel: 1,
                            size: 42,
                            mostrarNivel: false,
                          ),
                          const SizedBox(width: 12),
                          Expanded(
                            child: TextField(
                              controller: _texto,
                              enabled: !_publicando,
                              autofocus: true,
                              minLines: 4,
                              maxLines: null,
                              maxLength: _maxTexto,
                              textCapitalization: TextCapitalization.sentences,
                              style: const TextStyle(
                                  fontSize: 15.5, height: 1.5, color: TempleColors.blancoLuna),
                              cursorColor: TempleColors.violetaClaro,
                              decoration: const InputDecoration(
                                hintText: '¿Qué conquistaste hoy? Un récord, una rutina, '
                                    'una vuelta después de un parón…',
                                hintStyle: TextStyle(color: TempleColors.textoTenue, height: 1.5),
                                border: InputBorder.none,
                                counterText: '',
                              ),
                            ),
                          ),
                        ],
                      ),
                      if (widget.adjunto != null) ...<Widget>[
                        const SizedBox(height: 12),
                        TarjetaAdjunto(adjunto: widget.adjunto!),
                      ],
                      if (_clanDestino != null && (widget.clanId == null || ClanesRepo.instancia.mio?.activo == true)) ...<Widget>[
                        const SizedBox(height: 14),
                        Wrap(
                          spacing: 8,
                          runSpacing: 8,
                          crossAxisAlignment: WrapCrossAlignment.center,
                          children: <Widget>[
                            const Text('Dónde:', style: TextStyle(fontSize: 12.5, color: TempleColors.textoSuave)),
                            for (final bool muro in const <bool>[false, true])
                              ChoiceChip(
                                label: Text(muro ? 'Muro de ${_nombreClanDestino ?? 'mi clan'}' : 'Todo el Clan',
                                    style: const TextStyle(fontSize: 12)),
                                selected: _enMuro == muro,
                                showCheckmark: false,
                                onSelected: _publicando ? null : (_) => setState(() => _enMuro = muro),
                                selectedColor: TempleColors.violeta.withValues(alpha: 0.28),
                                backgroundColor: TempleColors.superficie,
                                side: BorderSide(color: _enMuro == muro ? TempleColors.violeta : TempleColors.borde),
                                labelStyle: TextStyle(
                                    color: _enMuro == muro ? TempleColors.blancoLuna : TempleColors.textoSuave),
                              ),
                          ],
                        ),
                      ],
                      if (_archivos.isNotEmpty) ...<Widget>[
                        const SizedBox(height: 14),
                        SizedBox(
                          height: 128,
                          child: ListView.separated(
                            scrollDirection: Axis.horizontal,
                            itemCount: _archivos.length,
                            separatorBuilder: (_, __) => const SizedBox(width: 10),
                            itemBuilder: (BuildContext c, int i) => _VistaPrevia(
                              archivo: _archivos[i],
                              onQuitar: _publicando
                                  ? null
                                  : () => setState(() => _archivos.removeAt(i)),
                            ),
                          ),
                        ),
                      ],
                      const SizedBox(height: 14),
                      Row(
                        children: <Widget>[
                          const Expanded(
                            child: Text(
                              'Usa # para etiquetar: #pierna #récord #volví',
                              style: TextStyle(fontSize: 12, color: TempleColors.textoTenue),
                            ),
                          ),
                          Text('$largo/$_maxTexto',
                              style: TextStyle(
                                  fontSize: 11.5,
                                  color: largo > _maxTexto - 100
                                      ? TempleColors.alertaSuave
                                      : TempleColors.textoTenue)),
                        ],
                      ),
                      BloqueError(mensaje: _error),
                      const SizedBox(height: 18),
                      Container(
                        padding: const EdgeInsets.all(12),
                        decoration: BoxDecoration(
                          color: TempleColors.superficie.withValues(alpha: 0.6),
                          borderRadius: BorderRadius.circular(TempleRadius.campo),
                          border: Border.all(color: TempleColors.borde),
                        ),
                        child: const Row(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: <Widget>[
                            Icon(Icons.shield_outlined, size: 17, color: TempleColors.violetaClaro),
                            SizedBox(width: 10),
                            Expanded(
                              child: Text(
                                'Antes de publicar: nada de desnudez, nada de datos personales '
                                '(tuyos o de otros) y respeto por el cuerpo de todos. Lo que '
                                'incumpla el reglamento se elimina.',
                                style: TextStyle(fontSize: 12, height: 1.45, color: TempleColors.textoSuave),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
                Container(
                  padding: EdgeInsets.fromLTRB(10, 8, 10, 8 + abajo),
                  decoration: const BoxDecoration(
                    color: TempleColors.grafito,
                    border: Border(top: BorderSide(color: TempleColors.borde)),
                  ),
                  child: Row(
                    children: <Widget>[
                      _BotonMedio(
                        icono: Icons.photo_library_outlined,
                        texto: 'Fotos',
                        onTap: _publicando ? null : _fotosGaleria,
                      ),
                      _BotonMedio(
                        icono: Icons.photo_camera_outlined,
                        texto: 'Cámara',
                        onTap: _publicando ? null : _fotoCamara,
                      ),
                      _BotonMedio(
                        icono: Icons.videocam_outlined,
                        texto: 'Video',
                        candado: !LimitesPase.pase,
                        onTap: _publicando ? null : _elegirVideo,
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class _BotonMedio extends StatelessWidget {
  const _BotonMedio({required this.icono, required this.texto, required this.onTap, this.candado = false});
  final IconData icono;
  final String texto;
  final VoidCallback? onTap;

  /// Ventaja del Pase: se ve el candado dorado y al tocar se abre el Pase.
  final bool candado;

  @override
  Widget build(BuildContext context) {
    return Expanded(
      child: InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(TempleRadius.chip),
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 10),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: <Widget>[
              Icon(icono,
                  size: 22,
                  color: onTap == null ? TempleColors.textoTenue : TempleColors.violetaClaro),
              const SizedBox(height: 4),
              Row(
                mainAxisSize: MainAxisSize.min,
                children: <Widget>[
                  Text(texto, style: const TextStyle(fontSize: 11.5, color: TempleColors.textoSuave)),
                  if (candado) ...<Widget>[
                    const SizedBox(width: 4),
                    const Icon(Icons.lock_outline_rounded, size: 11, color: Color(0xFFE8B65A)),
                  ],
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _VistaPrevia extends StatelessWidget {
  const _VistaPrevia({required this.archivo, required this.onQuitar});
  final _ArchivoElegido archivo;
  final VoidCallback? onQuitar;

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(TempleRadius.chip),
      child: SizedBox(
        width: archivo.video ? 180 : 104,
        child: Stack(
          fit: StackFit.expand,
          children: <Widget>[
            if (archivo.bytes != null)
              Image.memory(archivo.bytes!, fit: BoxFit.cover)
            else
              Container(
                decoration: const BoxDecoration(
                  gradient: LinearGradient(
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                    colors: <Color>[TempleColors.moradoProfundo, TempleColors.superficie],
                  ),
                ),
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: <Widget>[
                    const Icon(Icons.play_circle_outline_rounded,
                        size: 36, color: TempleColors.blancoLuna),
                    const SizedBox(height: 6),
                    Padding(
                      padding: const EdgeInsets.symmetric(horizontal: 8),
                      child: Text(archivo.archivo.name,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(fontSize: 11, color: TempleColors.textoSuave)),
                    ),
                  ],
                ),
              ),
            if (onQuitar != null)
              Positioned(
                top: 4,
                right: 4,
                child: GestureDetector(
                  onTap: onQuitar,
                  child: Container(
                    width: 26,
                    height: 26,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: TempleColors.negro.withValues(alpha: 0.7),
                    ),
                    child: const Icon(Icons.close_rounded, size: 16, color: TempleColors.blancoLuna),
                  ),
                ),
              ),
          ],
        ),
      ),
    );
  }
}

