class DetallePublicacionScreen extends StatefulWidget {
  const DetallePublicacionScreen({super.key, required this.publicacion});
  final ClanPublicacion publicacion;

  @override
  State<DetallePublicacionScreen> createState() => _DetallePublicacionScreenState();
}

class _DetallePublicacionScreenState extends State<DetallePublicacionScreen> {
  final TextEditingController _texto = TextEditingController();
  List<ClanComentario>? _comentarios;
  String? _error;
  bool _enviando = false;

  ClanPublicacion get _p => widget.publicacion;

  @override
  void initState() {
    super.initState();
    _texto.addListener(() => setState(() {}));
    _cargar();
  }

  @override
  void dispose() {
    _texto.dispose();
    super.dispose();
  }

  Future<void> _cargar() async {
    try {
      final List<ClanComentario> c = await ClanRepo.instancia.comentarios(_p.id);
      if (mounted) {
        setState(() {
          _comentarios = c;
          _error = null;
        });
      }
    } catch (e) {
      if (mounted) setState(() => _error = SesionTemplo.mensajeDe(e));
    }
  }

  Future<void> _enviar() async {
    final String t = _texto.text.trim();
    if (t.isEmpty || _enviando) return;
    setState(() => _enviando = true);
    try {
      await ClanRepo.instancia.comentar(_p.id, t);
      _texto.clear();
      _p.nComentarios++;
      await _cargar();
    } catch (e) {
      if (mounted) avisoClan(context, SesionTemplo.mensajeDe(e), error: true);
    } finally {
      if (mounted) setState(() => _enviando = false);
    }
  }

  void _opcionesComentario(ClanComentario c) {
    final bool mio = c.autor.id == SesionTemplo.instancia.uid;
    mostrarOpcionesClan(context, <OpcionHoja>[
      if (mio || _p.esMia)
        OpcionHoja(Icons.delete_outline_rounded, 'Eliminar comentario', () async {
          try {
            await ClanRepo.instancia.borrarComentario(c.id);
            _p.nComentarios = math.max(0, _p.nComentarios - 1);
            await _cargar();
          } catch (e) {
            if (mounted) avisoClan(context, SesionTemplo.mensajeDe(e), error: true);
          }
        }, peligro: true),
      if (!mio) ...<OpcionHoja>[
        OpcionHoja(Icons.flag_outlined, 'Reportar comentario', () async {
          final bool hecho = await mostrarReporte(
              context, tipo: 'comentario', objetivo: c.id, persona: c.autor);
          if (hecho) _cargar();
        }, peligro: true),
        OpcionHoja(Icons.block_rounded, 'Bloquear a @${c.autor.usuario}', () async {
          if (await bloquearConConfirmacion(context, c.autor)) _cargar();
        }, peligro: true),
      ],
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final double abajo = MediaQuery.paddingOf(context).bottom;
    final List<ClanComentario>? lista = _comentarios;

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: Column(
          children: <Widget>[
            const BarraClan(titulo: 'Publicación'),
            Expanded(
              child: ListView(
                padding: const EdgeInsets.fromLTRB(TempleSpace.borde, 4, TempleSpace.borde, 20),
                children: <Widget>[
                  TarjetaPublicacion(
                    publicacion: _p,
                    enDetalle: true,
                    onEliminada: () => Navigator.of(context).pop(true),
                  ),
                  const SizedBox(height: 18),
                  EtiquetaSeccion(
                      lista == null ? 'Comentarios' : 'Comentarios · ${lista.length}'),
                  if (_error != null)
                    VacioClan(
                      glifo: TempleGlyph.montana,
                      titulo: 'No cargaron los comentarios',
                      texto: _error!,
                      accion: 'Reintentar',
                      onAccion: _cargar,
                    )
                  else if (lista == null)
                    const Padding(
                      padding: EdgeInsets.all(24),
                      child: Center(
                        child: SizedBox(
                          width: 20,
                          height: 20,
                          child: CircularProgressIndicator(strokeWidth: 1.6, color: TempleColors.violeta),
                        ),
                      ),
                    )
                  else if (lista.isEmpty)
                    const Padding(
                      padding: EdgeInsets.symmetric(vertical: 24),
                      child: Text('Nadie ha comentado todavía. Sé el primero en dar ánimo.',
                          textAlign: TextAlign.center,
                          style: TextStyle(fontSize: 13, color: TempleColors.textoTenue)),
                    )
                  else
                    for (final ClanComentario c in lista)
                      _FilaComentario(
                        comentario: c,
                        onOpciones: () => _opcionesComentario(c),
                      ),
                ],
              ),
            ),
            Container(
              padding: EdgeInsets.fromLTRB(14, 8, 8, 8 + abajo),
              decoration: const BoxDecoration(
                color: TempleColors.grafito,
                border: Border(top: BorderSide(color: TempleColors.borde)),
              ),
              child: Row(
                children: <Widget>[
                  Expanded(
                    child: TextField(
                      controller: _texto,
                      maxLength: 500,
                      minLines: 1,
                      maxLines: 4,
                      textCapitalization: TextCapitalization.sentences,
                      style: const TextStyle(fontSize: 14, color: TempleColors.blancoLuna),
                      cursorColor: TempleColors.violetaClaro,
                      decoration: InputDecoration(
                        hintText: 'Escribe algo que sume',
                        hintStyle: const TextStyle(color: TempleColors.textoTenue),
                        counterText: '',
                        filled: true,
                        fillColor: TempleColors.superficie,
                        isDense: true,
                        contentPadding: const EdgeInsets.symmetric(horizontal: 14, vertical: 11),
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(TempleRadius.campo),
                          borderSide: const BorderSide(color: TempleColors.borde),
                        ),
                        enabledBorder: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(TempleRadius.campo),
                          borderSide: const BorderSide(color: TempleColors.borde),
                        ),
                        focusedBorder: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(TempleRadius.campo),
                          borderSide: const BorderSide(color: TempleColors.violeta),
                        ),
                      ),
                    ),
                  ),
                  const SizedBox(width: 6),
                  IconButton(
                    tooltip: 'Enviar comentario',
                    onPressed: _texto.text.trim().isEmpty || _enviando ? null : _enviar,
                    icon: _enviando
                        ? const SizedBox(
                            width: 18,
                            height: 18,
                            child: CircularProgressIndicator(strokeWidth: 1.6, color: TempleColors.violeta))
                        : Icon(Icons.send_rounded,
                            color: _texto.text.trim().isEmpty
                                ? TempleColors.textoTenue
                                : TempleColors.violetaClaro),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

