// ---------------------------------------------------------------------------
// 35.9 PERFIL PÚBLICO
// ---------------------------------------------------------------------------

class PerfilClanScreen extends StatefulWidget {
  const PerfilClanScreen({super.key, required this.id, this.vistaPrevia = false});
  final String id;

  /// Si es true y el perfil es el tuyo, se muestra tal como lo ven los demás.
  final bool vistaPrevia;

  @override
  State<PerfilClanScreen> createState() => _PerfilClanScreenState();
}

class _PerfilClanScreenState extends State<PerfilClanScreen> {
  ClanPerfilPublico? _perfil;
  bool _cargando = true;
  bool _ocupado = false;
  String? _error;
  int _version = 0; // fuerza recargar la cuadrícula

  @override
  void initState() {
    super.initState();
    _cargar();
  }

  bool get _previa => widget.vistaPrevia && (_perfil?.esYo ?? false);

  Future<void> _cargar() async {
    setState(() => _cargando = true);
    try {
      final ClanPerfilPublico? p = await ClanRepo.instancia.perfil(widget.id);
      if (!mounted) return;
      setState(() {
        _perfil = p;
        _error = null;
        _cargando = false;
        _version++;
      });
    } catch (e) {
      if (mounted) {
        setState(() {
          _error = SesionTemplo.mensajeDe(e);
          _cargando = false;
        });
      }
    }
  }

  void _soloVista() => avisoClan(context, 'Es la vista previa: así verán este botón los demás.');

  Future<void> _seguir() async {
    final ClanPerfilPublico? p = _perfil;
    if (p == null || _ocupado) return;
    setState(() => _ocupado = true);
    try {
      await ClanRepo.instancia.seguir(p.persona.id, !p.yoSigo);
      HapticFeedback.selectionClick();
      await _cargar();
    } catch (e) {
      if (mounted) avisoClan(context, SesionTemplo.mensajeDe(e), error: true);
    } finally {
      if (mounted) setState(() => _ocupado = false);
    }
  }

  Future<void> _mensaje() async {
    final ClanPerfilPublico? p = _perfil;
    if (p == null) return;
    final bool sigue = await mostrarAvisoSeguridad(context, nuevaConversacion: !p.mutuo);
    if (!sigue || !mounted) return;
    setState(() => _ocupado = true);
    try {
      final String cid = await ClanRepo.instancia.abrirConversacion(p.persona.id);
      if (!mounted) return;
      await Navigator.of(context).push(MaterialPageRoute<void>(
        builder: (_) => ChatClanScreen(conversacionId: cid, otro: p.persona),
      ));
    } catch (e) {
      if (mounted) avisoClan(context, SesionTemplo.mensajeDe(e), error: true);
    } finally {
      if (mounted) setState(() => _ocupado = false);
    }
  }

  Future<void> _editar() async {
    if (SesionTemplo.instancia.actual == null) {
      await SesionTemplo.instancia.cargarMiPerfil();
    }
    if (!mounted || SesionTemplo.instancia.actual == null) return;
    await Navigator.of(context).push(MaterialPageRoute<void>(
      builder: (_) => PerfilScreen(perfil: SesionTemplo.instancia.perfilApp()),
    ));
    await SesionTemplo.instancia.sincronizarIdentidad(SesionTemplo.instancia.actual!.usuario);
    _cargar();
  }

  Future<void> _foto() async {
    if (await elegirFotoPerfil(context)) _cargar();
  }

  void _verPrevia() {
    final ClanPerfilPublico? p = _perfil;
    if (p == null) return;
    Navigator.of(context).push(MaterialPageRoute<void>(
      builder: (_) => PerfilClanScreen(id: p.persona.id, vistaPrevia: true),
    ));
  }

  void _opciones() {
    final ClanPerfilPublico? p = _perfil;
    if (p == null) return;
    if (p.esYo) {
      final bool conFoto = AlmacenIdentidad.instancia.de(p.persona.usuario).foto != null;
      mostrarOpcionesClan(context, <OpcionHoja>[
        OpcionHoja(Icons.edit_outlined, 'Editar perfil', _editar),
        OpcionHoja(Icons.photo_library_outlined,
            conFoto ? 'Cambiar foto de perfil' : 'Poner foto de perfil', _foto),
        if (conFoto)
          OpcionHoja(Icons.hide_image_outlined, 'Quitar foto y usar el sello', () async {
            await SesionTemplo.instancia.quitarFotoPerfil(p.persona.usuario);
            _cargar();
          }),
        OpcionHoja(Icons.brush_outlined, 'Editar mi viñeta en el Taller', () async {
          await Navigator.of(context).push(MaterialPageRoute<void>(
            builder: (_) => TallerVinetaScreen(usuario: p.persona.usuario),
          ));
          await SesionTemplo.instancia.sincronizarIdentidad(p.persona.usuario);
          _cargar();
        }),
        OpcionHoja(Icons.visibility_outlined, 'Vista previa: cómo me ven', _verPrevia),
        OpcionHoja(Icons.manage_accounts_outlined, 'Cuenta y privacidad', () {
          Navigator.of(context).push(MaterialPageRoute<void>(
            builder: (_) => const AjustesCuentaScreen(),
          ));
        }),
      ]);
      return;
    }
    mostrarOpcionesClan(context, <OpcionHoja>[
      OpcionHoja(Icons.flag_outlined, 'Reportar perfil', () async {
        await mostrarReporte(context, tipo: 'perfil', objetivo: p.persona.id, persona: p.persona);
      }, peligro: true),
      if (p.bloqueadoPorMi)
        OpcionHoja(Icons.lock_open_rounded, 'Desbloquear', _desbloquear)
      else
        OpcionHoja(Icons.block_rounded, 'Bloquear a @${p.persona.usuario}', () async {
          if (await bloquearConConfirmacion(context, p.persona)) _cargar();
        }, peligro: true),
    ]);
  }

  Future<void> _desbloquear() async {
    final ClanPerfilPublico? p = _perfil;
    if (p == null) return;
    try {
      await ClanRepo.instancia.desbloquear(p.persona.id);
      if (mounted) avisoClan(context, 'Desbloqueaste a @${p.persona.usuario}');
      await _cargar();
    } catch (e) {
      if (mounted) avisoClan(context, SesionTemplo.mensajeDe(e), error: true);
    }
  }

  void _lista({required bool siguiendo}) {
    final ClanPerfilPublico? p = _perfil;
    if (p == null) return;
    Navigator.of(context).push(MaterialPageRoute<void>(
      builder: (_) => ListaPersonasScreen(
        titulo: siguiendo ? 'Siguiendo' : 'Seguidores',
        subtitulo: '@${p.persona.usuario}',
        cargar: () => ClanRepo.instancia.listaSeguidores(p.persona.id, siguiendo: siguiendo),
      ),
    ));
  }

  @override
  Widget build(BuildContext context) {
    final ClanPerfilPublico? real = _perfil;
    final ClanPerfilPublico? p = real == null ? null : (_previa ? real.comoLoVenOtros() : real);
    final bool previa = _previa;

    Widget cuerpo;
    if (_cargando && p == null) {
      cuerpo = const Center(
        child: SizedBox(
          width: 24,
          height: 24,
          child: CircularProgressIndicator(strokeWidth: 1.8, color: TempleColors.violeta),
        ),
      );
    } else if (_error != null && p == null) {
      cuerpo = Center(
        child: VacioClan(
          glifo: TempleGlyph.montana,
          titulo: 'No pudimos abrir el perfil',
          texto: _error!,
          accion: 'Reintentar',
          onAccion: _cargar,
        ),
      );
    } else if (p == null) {
      cuerpo = const Center(
        child: VacioClan(
          glifo: TempleGlyph.kitsune,
          titulo: 'Este perfil no está disponible',
          texto: 'Puede que la cuenta ya no exista o que no tengas acceso a ella.',
        ),
      );
    } else {
      cuerpo = FeedClan(
        key: ValueKey<String>('perfil-${p.persona.id}-$_version'),
        deAutor: p.bloqueadoPorMi ? '00000000-0000-0000-0000-000000000000' : p.persona.id,
        relleno: const EdgeInsets.fromLTRB(TempleSpace.borde, 0, TempleSpace.borde, 0),
        cabecera: _CabeceraPerfil(
          perfil: p,
          ocupado: _ocupado,
          onSeguir: previa ? _soloVista : _seguir,
          onMensaje: previa ? _soloVista : _mensaje,
          onOpciones: previa ? _soloVista : _opciones,
          onDesbloquear: _desbloquear,
          onSeguidores: () => _lista(siguiendo: false),
          onSiguiendo: () => _lista(siguiendo: true),
          onEditar: _editar,
          onFoto: _foto,
          onVistaPrevia: _verPrevia,
        ),
        vacio: p.bloqueadoPorMi
            ? const SizedBox.shrink()
            : VacioClan(
                glifo: TempleGlyph.lista,
                titulo: p.esYo ? 'Aún no publicas nada' : 'Sin publicaciones todavía',
                texto: p.esYo
                    ? 'Tu primer avance puede ser el que anime a alguien a empezar.'
                    : 'Cuando @${p.persona.usuario} comparta algo, aparecerá aquí.',
              ),
      );
    }

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: Column(
          children: <Widget>[
            BarraClan(
              titulo: previa ? 'Vista previa' : (p == null ? 'Perfil' : p.persona.nombre),
              subtitulo: previa
                  ? 'Así ven tu perfil los demás'
                  : (p == null ? null : '@${p.persona.usuario}'),
              acciones: <Widget>[
                if (p != null && !previa)
                  IconButton(
                    tooltip: p.esYo ? 'Opciones de mi perfil' : 'Opciones del perfil',
                    onPressed: _opciones,
                    icon: const Icon(Icons.more_vert_rounded, color: TempleColors.textoSuave),
                  ),
              ],
            ),
            if (previa)
              Container(
                margin: const EdgeInsets.fromLTRB(TempleSpace.borde, 0, TempleSpace.borde, 10),
                padding: const EdgeInsets.fromLTRB(12, 10, 6, 10),
                decoration: BoxDecoration(
                  color: TempleColors.violeta.withValues(alpha: 0.1),
                  borderRadius: BorderRadius.circular(TempleRadius.chip),
                  border: Border.all(color: TempleColors.violeta.withValues(alpha: 0.35)),
                ),
                child: Row(
                  children: <Widget>[
                    const Icon(Icons.visibility_outlined, size: 17, color: TempleColors.violetaClaro),
                    const SizedBox(width: 9),
                    const Expanded(
                      child: Text(
                        'Tu fecha de nacimiento nunca se muestra: solo la edad.',
                        style: TextStyle(fontSize: 12, height: 1.4, color: TempleColors.texto),
                      ),
                    ),
                    TextButton(
                      onPressed: () => Navigator.of(context).maybePop(),
                      child: const Text('Salir', style: TextStyle(color: TempleColors.violetaClaro)),
                    ),
                  ],
                ),
              ),
            Expanded(child: cuerpo),
          ],
        ),
      ),
    );
  }
}

class _CabeceraPerfil extends StatelessWidget {
  const _CabeceraPerfil({
    required this.perfil,
    required this.ocupado,
    required this.onSeguir,
    required this.onMensaje,
    required this.onOpciones,
    required this.onDesbloquear,
    required this.onSeguidores,
    required this.onSiguiendo,
    required this.onEditar,
    required this.onFoto,
    required this.onVistaPrevia,
  });

  final ClanPerfilPublico perfil;
  final bool ocupado;
  final VoidCallback onSeguir;
  final VoidCallback onMensaje;
  final VoidCallback onOpciones;
  final VoidCallback onDesbloquear;
  final VoidCallback onSeguidores;
  final VoidCallback onSiguiendo;
  final VoidCallback onEditar;
  final VoidCallback onFoto;
  final VoidCallback onVistaPrevia;

  @override
  Widget build(BuildContext context) {
    final ClanPerfilPublico p = perfil;
    final Llama llama = Llama(valor: p.llama, diasSeguidos: p.racha, diasSinEntrenar: 0);

    return Padding(
      padding: const EdgeInsets.only(bottom: 18),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: <Widget>[
          // Estandarte: la viñeta que la persona armó en el Taller.
          SizedBox(
            height: 214,
            child: Stack(
              clipBehavior: Clip.none,
              children: <Widget>[
                Positioned(
                  left: 0,
                  right: 0,
