class _BotonPerfil extends StatelessWidget {
  const _BotonPerfil({
    required this.texto,
    required this.principal,
    required this.onTap,
    this.icono,
    this.cargando = false,
  });

  final String texto;
  final bool principal;
  final VoidCallback? onTap;
  final IconData? icono;
  final bool cargando;

