  Widget build(BuildContext context) {
    final Widget contenido = cargando
        ? const SizedBox(
            width: 16,
            height: 16,
            child: CircularProgressIndicator(strokeWidth: 1.6, color: Colors.white))
        : Row(
            mainAxisSize: MainAxisSize.min,
            children: <Widget>[
