/// Aviso que aparece cada vez que alguien inicia o abre una conversación.
/// Devuelve true si la persona decide continuar.
Future<bool> mostrarAvisoSeguridad(BuildContext context, {bool nuevaConversacion = false}) async {
  final bool menor = SesionTemplo.instancia.actual?.esMenor ?? false;
  final bool? r = await showDialog<bool>(
    context: context,
    barrierColor: Colors.black.withValues(alpha: 0.7),
    builder: (BuildContext ctx) => Dialog(
      backgroundColor: TempleColors.superficieAlta,
      insetPadding: const EdgeInsets.symmetric(horizontal: 22, vertical: 24),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
        side: BorderSide(color: TempleColors.violeta.withValues(alpha: 0.35)),
      ),
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 420),
        child: SingleChildScrollView(
          padding: const EdgeInsets.fromLTRB(22, 22, 22, 14),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              Row(
                children: <Widget>[
                  Container(
                    width: 40,
                    height: 40,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
