              const _PuntoAviso('No compartas tu dirección, teléfono, colegio, trabajo ni dónde '
                  'entrenas a qué hora.'),
              const _PuntoAviso('Nunca envíes tu contraseña ni tu código de recuperación. Nadie del '
                  'templo te los va a pedir.'),
              const _PuntoAviso('No envíes ni pidas fotos íntimas. Está prohibido y se reporta.'),
              const _PuntoAviso('Desconfía si te ofrecen dinero, suplementos, sustancias o te piden '
                  'verse en persona.'),
              const _PuntoAviso('Si algo te incomoda, no tienes que responder: bloquea y reporta. '
                  'La otra persona no se entera.'),
              if (menor)
                const _PuntoAviso(
                  'Si eres menor de edad y alguien te hace sentir incómodo, cuéntaselo a un adulto '
                  'de confianza.',
                  destacado: true,
                ),
              if (nuevaConversacion) ...<Widget>[
                const SizedBox(height: 6),
                Container(
                  padding: const EdgeInsets.all(12),
                  decoration: BoxDecoration(
                    color: TempleColors.violeta.withValues(alpha: 0.08),
                    borderRadius: BorderRadius.circular(TempleRadius.chip),
                    border: Border.all(color: TempleColors.violeta.withValues(alpha: 0.25)),
                  ),
                  child: const Text(
                    'Como no se siguen mutuamente, si es la primera vez que le escribes tu mensaje '
                    'llegará como solicitud. Podrás enviar hasta 3 mensajes hasta que la acepte.',
                    style: TextStyle(fontSize: 12.5, height: 1.45, color: TempleColors.texto),
                  ),
                ),
              ],
              const SizedBox(height: 16),
              Row(
                children: <Widget>[
                  Expanded(
                    child: TextButton(
                      onPressed: () => Navigator.of(ctx).pop(false),
                      child: const Text('Cancelar', style: TextStyle(color: TempleColors.textoSuave)),
                    ),
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: FilledButton(
                      onPressed: () => Navigator.of(ctx).pop(true),
                      style: FilledButton.styleFrom(
                        backgroundColor: TempleColors.violeta,
                        foregroundColor: Colors.white,
                        padding: const EdgeInsets.symmetric(vertical: 12),
