}

/// Muestra el aviso y, si la persona acepta, abre el chat.
Future<void> abrirChatClan(
  BuildContext context, {
  required String conversacionId,
  required ClanPersona otro,
}) async {
  final bool sigue = await mostrarAvisoSeguridad(context);
  if (!sigue || !context.mounted) return;
  await Navigator.of(context).push(MaterialPageRoute<void>(
    builder: (_) => ChatClanScreen(conversacionId: conversacionId, otro: otro),
  ));
}

// -- Bandeja -----------------------------------------------------------------

class BandejaScreen extends StatefulWidget {
  const BandejaScreen({super.key});

  @override
  State<BandejaScreen> createState() => _BandejaScreenState();
}

class _BandejaScreenState extends State<BandejaScreen> {
  int _pestana = 0; // 0 = Chats, 1 = Solicitudes
  List<ClanConversacion>? _lista;
  String? _error;
  RealtimeChannel? _canal;
  Timer? _espera;

  @override
  void initState() {
    super.initState();
    _cargar();
    _canal = supa
        .channel('clan-bandeja-lista')
        .onPostgresChanges(
          event: PostgresChangeEvent.insert,
          schema: 'public',
          table: 'mensajes',
          callback: (PostgresChangePayload _) {
            // Varios mensajes seguidos → una sola recarga.
            _espera?.cancel();
            _espera = Timer(const Duration(milliseconds: 400), _cargar);
          },
        )
        .subscribe();
  }

  @override
  void dispose() {
    _espera?.cancel();
    final RealtimeChannel? c = _canal;
    if (c != null) supa.removeChannel(c);
    super.dispose();
  }

  Future<void> _cargar() async {
    try {
      final List<ClanConversacion> l = await ClanRepo.instancia.bandeja();
      if (mounted) {
        setState(() {
          _lista = l;
          _error = null;
        });
      }
    } catch (e) {
      if (mounted) setState(() => _error = SesionTemplo.mensajeDe(e));
    }
  }

  Future<void> _abrir(ClanConversacion c) async {
    await abrirChatClan(context, conversacionId: c.id, otro: c.otro);
    _cargar();
  }

  @override
  Widget build(BuildContext context) {
    final List<ClanConversacion> todas = _lista ?? <ClanConversacion>[];
    // Una solicitud que rechacé ya no aparece en mi bandeja.
    final List<ClanConversacion> chats = todas
        .where((ClanConversacion c) =>
            !c.esSolicitudRecibida && !(c.estado == 'rechazada' && !c.creadaPorMi))
        .toList();
    final List<ClanConversacion> solicitudes =
        todas.where((ClanConversacion c) => c.esSolicitudRecibida).toList();
    final List<ClanConversacion> visibles = _pestana == 0 ? chats : solicitudes;

    Widget cuerpo;
    if (_error != null && _lista == null) {
      cuerpo = Center(
        child: VacioClan(
          glifo: TempleGlyph.montana,
          titulo: 'No cargaron tus mensajes',
          texto: _error!,
          accion: 'Reintentar',
          onAccion: _cargar,
        ),
      );
    } else if (_lista == null) {
      cuerpo = const Center(
        child: SizedBox(
          width: 22,
          height: 22,
          child: CircularProgressIndicator(strokeWidth: 1.8, color: TempleColors.violeta),
        ),
      );
    } else {
      cuerpo = RefreshIndicator(
        color: TempleColors.violeta,
        backgroundColor: TempleColors.superficieAlta,
        onRefresh: _cargar,
        child: ListView(
          physics: const AlwaysScrollableScrollPhysics(),
          padding: EdgeInsets.fromLTRB(12, 4, 12, 24 + MediaQuery.paddingOf(context).bottom),
          children: <Widget>[
            if (_pestana == 1)
              Container(
                margin: const EdgeInsets.fromLTRB(4, 4, 4, 12),
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: TempleColors.superficie.withValues(alpha: 0.85),
                  borderRadius: BorderRadius.circular(TempleRadius.chip),
                  border: Border.all(color: TempleColors.borde),
                ),
                child: const Text(
                  'Son mensajes de personas que no se siguen mutuamente contigo. Ábrelos para '
                  'aceptar, rechazar o bloquear. Quien escribe no sabe si los leíste.',
                  style: TextStyle(fontSize: 12.5, height: 1.45, color: TempleColors.textoSuave),
                ),
              ),
            if (visibles.isEmpty)
              VacioClan(
                glifo: _pestana == 0 ? TempleGlyph.clan : TempleGlyph.campana,
                titulo: _pestana == 0 ? 'Aún no tienes conversaciones' : 'Sin solicitudes',
                texto: _pestana == 0
                    ? 'Entra al perfil de alguien de tu clan y pulsa «Mensaje». Si se siguen '
                        'mutuamente, el chat se abre al instante.'
                    : 'Cuando alguien que no sigues te escriba, su mensaje esperará aquí.',
              )
            else
              for (final ClanConversacion c in visibles)
                _FilaConversacion(conversacion: c, onTap: () => _abrir(c)),
          ],
        ),
      );
    }

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: Column(
          children: <Widget>[
            const BarraClan(titulo: 'Mensajes', subtitulo: 'Privados, solo entre ustedes dos', pase: false),
            Padding(
              padding: const EdgeInsets.fromLTRB(TempleSpace.borde, 4, TempleSpace.borde, 8),
              child: _PestanasClan(
                indice: _pestana,
                opciones: <String>[
                  'Chats',
                  solicitudes.isEmpty ? 'Solicitudes' : 'Solicitudes · ${solicitudes.length}',
                ],
                onCambio: (int i) {
                  HapticFeedback.selectionClick();
                  setState(() => _pestana = i);
                },
              ),
            ),
            Expanded(child: cuerpo),
          ],
        ),
      ),
    );
  }
}

class _FilaConversacion extends StatelessWidget {
  const _FilaConversacion({required this.conversacion, required this.onTap});
  final ClanConversacion conversacion;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final ClanConversacion c = conversacion;
    final bool sinLeer = c.sinLeer > 0;

    String vista = (c.ultimoTexto ?? '').replaceAll('\n', ' ').trim();
    if (vista.isEmpty) vista = 'Sin mensajes todavía';
    if (c.ultimoEsMio && (c.ultimoTexto ?? '').isNotEmpty) vista = 'Tú: $vista';

    String? estado;
    if (c.estado == 'solicitud' && c.creadaPorMi) estado = 'Solicitud enviada';
    if (c.estado == 'rechazada') estado = 'Conversación cerrada';

    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(TempleRadius.campo),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 10),
        child: Row(
          children: <Widget>[
            ClanAvatar(persona: c.otro, size: 48),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Row(
                    children: <Widget>[
                      Expanded(
                        child: Text(c.otro.nombre,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                                fontSize: 14.5,
                                fontWeight: sinLeer ? FontWeight.w700 : FontWeight.w600,
                                color: TempleColors.blancoLuna)),
                      ),
                      const SizedBox(width: 8),
                      Text(tiempoClan(c.ultimoEn),
                          style: TextStyle(
                              fontSize: 11,
                              color: sinLeer ? TempleColors.violetaClaro : TempleColors.textoTenue)),
                    ],
                  ),
                  const SizedBox(height: 3),
                  Row(
                    children: <Widget>[
                      Expanded(
                        child: Text(vista,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                                fontSize: 12.5,
                                color: sinLeer ? TempleColors.texto : TempleColors.textoSuave)),
                      ),
                      if (sinLeer) ...<Widget>[
                        const SizedBox(width: 8),
                        Container(
                          constraints: const BoxConstraints(minWidth: 20),
                          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                          decoration: BoxDecoration(
                            color: TempleColors.violeta,
                            borderRadius: BorderRadius.circular(TempleRadius.pastilla),
                          ),
                          alignment: Alignment.center,
                          child: Text(c.sinLeer > 99 ? '99+' : '${c.sinLeer}',
                              style: const TextStyle(
                                  fontSize: 10.5, fontWeight: FontWeight.w700, color: Colors.white)),
                        ),
                      ],
                    ],
                  ),
                  if (estado != null) ...<Widget>[
                    const SizedBox(height: 5),
                    Text(estado,
                        style: const TextStyle(
                            fontSize: 10.5,
                            letterSpacing: 0.4,
                            fontWeight: FontWeight.w600,
                            color: TempleColors.textoTenue)),
                  ],
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// -- Chat --------------------------------------------------------------------

class ChatClanScreen extends StatefulWidget {
  const ChatClanScreen({super.key, required this.conversacionId, required this.otro});
  final String conversacionId;
  final ClanPersona otro;

  @override
  State<ChatClanScreen> createState() => _ChatClanScreenState();
}

class _ChatClanScreenState extends State<ChatClanScreen> {
  static const int _maxSolicitud = 3;

  final TextEditingController _texto = TextEditingController();
  late final Stream<List<ClanMensaje>> _flujo;

  String _estado = 'activa';
  bool _creadaPorMi = true;
  bool _cargandoEstado = true;
  bool _enviando = false;
  bool _respondiendo = false;
  bool _avisoAbierto = true;
  int _ultimoVisto = -1;

  @override
  void initState() {
    super.initState();
    _flujo = ClanRepo.instancia.mensajes(widget.conversacionId);
    _texto.addListener(() => setState(() {}));
    _cargarEstado();
  }

  @override
  void dispose() {
    _texto.dispose();
    ClanRepo.instancia.marcarLeido(widget.conversacionId);
    super.dispose();
  }

  Future<void> _cargarEstado() async {
    try {
      final Map<String, dynamic>? c = await ClanRepo.instancia.conversacion(widget.conversacionId);
      if (!mounted) return;
      setState(() {
        if (c != null) {
          _estado = (c['estado'] as String?) ?? 'activa';
          _creadaPorMi = c['creada_por'] == SesionTemplo.instancia.uid;
        }
        _cargandoEstado = false;
      });
    } catch (_) {
      if (mounted) setState(() => _cargandoEstado = false);
    }
  }

  /// Cada vez que llega algo nuevo se marca como leído. Si la otra persona
  /// respondió a mi solicitud, es que la aceptó: se vuelve a leer el estado.
  void _alLlegar(List<ClanMensaje> lista) {
    if (lista.isEmpty) return;
    final ClanMensaje ultimo = lista.last;
    if (ultimo.id == _ultimoVisto) return;
    _ultimoVisto = ultimo.id;
    ClanRepo.instancia.marcarLeido(widget.conversacionId);
    if (_estado == 'solicitud' && _creadaPorMi && !ultimo.esMio) {
      WidgetsBinding.instance.addPostFrameCallback((_) => _cargarEstado());
    }
  }

  Future<void> _enviar() async {
    final String t = _texto.text.trim();
    if (t.isEmpty || _enviando) return;
    setState(() => _enviando = true);
    try {
      await ClanRepo.instancia.enviar(widget.conversacionId, t);
      _texto.clear();
      HapticFeedback.selectionClick();
    } catch (e) {
      if (mounted) avisoClan(context, SesionTemplo.mensajeDe(e), error: true);
      _cargarEstado();
    } finally {
      if (mounted) setState(() => _enviando = false);
    }
  }

  Future<void> _responder(bool aceptar) async {
    setState(() => _respondiendo = true);
    try {
      await ClanRepo.instancia.responderSolicitud(widget.conversacionId, aceptar);
      if (!mounted) return;
      if (aceptar) {
        setState(() => _estado = 'activa');
        avisoClan(context, 'Solicitud aceptada. Ya pueden hablar.');
      } else {
        avisoClan(context, 'Solicitud rechazada. No se le avisa a @${widget.otro.usuario}.');
        Navigator.of(context).pop();
      }
    } catch (e) {
      if (mounted) avisoClan(context, SesionTemplo.mensajeDe(e), error: true);
    } finally {
      if (mounted) setState(() => _respondiendo = false);
    }
  }

  Future<void> _bloquear() async {
    final bool hecho = await bloquearConConfirmacion(context, widget.otro);
    if (hecho && mounted) Navigator.of(context).pop();
  }

  void _opciones() {
    mostrarOpcionesClan(context, <OpcionHoja>[
      OpcionHoja(Icons.person_outline_rounded, 'Ver perfil', () {
        Navigator.of(context).push(MaterialPageRoute<void>(
          builder: (_) => PerfilClanScreen(id: widget.otro.id),
        ));
      }),
      OpcionHoja(Icons.shield_outlined, 'Consejos de seguridad', () => mostrarAvisoSeguridad(context)),
      OpcionHoja(Icons.flag_outlined, 'Reportar a @${widget.otro.usuario}', () {
        mostrarReporte(context, tipo: 'perfil', objetivo: widget.otro.id, persona: widget.otro);
      }, peligro: true),
      OpcionHoja(Icons.block_rounded, 'Bloquear a @${widget.otro.usuario}', _bloquear, peligro: true),
    ]);
  }

  void _opcionesMensaje(ClanMensaje m) {
    if (m.esMio) {
      Clipboard.setData(ClipboardData(text: m.texto));
      avisoClan(context, 'Mensaje copiado');
      return;
    }
    mostrarOpcionesClan(context, <OpcionHoja>[
      OpcionHoja(Icons.copy_rounded, 'Copiar', () {
        Clipboard.setData(ClipboardData(text: m.texto));
        avisoClan(context, 'Mensaje copiado');
      }),
      OpcionHoja(Icons.flag_outlined, 'Reportar este mensaje', () {
        mostrarReporte(context, tipo: 'mensaje', objetivo: '${m.id}', persona: widget.otro);
      }, peligro: true),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final double abajo = MediaQuery.paddingOf(context).bottom;
    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: Column(
          children: <Widget>[
            SafeArea(
              bottom: false,
              child: SizedBox(
                height: 62,
                child: Row(
                  children: <Widget>[
                    const SizedBox(width: 4),
                    IconButton(
                      tooltip: 'Volver',
                      onPressed: () => Navigator.of(context).maybePop(),
                      icon: const Icon(Icons.arrow_back_rounded, color: TempleColors.textoSuave),
                    ),
                    Expanded(
                      child: GestureDetector(
                        behavior: HitTestBehavior.opaque,
                        onTap: () => Navigator.of(context).push(MaterialPageRoute<void>(
                          builder: (_) => PerfilClanScreen(id: widget.otro.id),
                        )),
                        child: Row(
                          children: <Widget>[
                            ClanAvatar(persona: widget.otro, size: 36),
                            const SizedBox(width: 10),
                            Expanded(
                              child: Column(
                                mainAxisAlignment: MainAxisAlignment.center,
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: <Widget>[
                                  Text(widget.otro.nombre,
                                      maxLines: 1,
                                      overflow: TextOverflow.ellipsis,
                                      style: const TextStyle(
                                          fontSize: 15.5,
                                          fontWeight: FontWeight.w600,
                                          color: TempleColors.blancoLuna)),
                                  Text('@${widget.otro.usuario}',
                                      maxLines: 1,
                                      overflow: TextOverflow.ellipsis,
                                      style: const TextStyle(fontSize: 11.5, color: TempleColors.textoTenue)),
                                ],
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                    IconButton(
                      tooltip: 'Opciones',
                      onPressed: _opciones,
                      icon: const Icon(Icons.more_vert_rounded, color: TempleColors.textoSuave),
                    ),
                    const SizedBox(width: 4),
                  ],
                ),
              ),
            ),
            _BandaSeguridad(
              abierta: _avisoAbierto,
              onCambio: () => setState(() => _avisoAbierto = !_avisoAbierto),
            ),
            Expanded(
              child: StreamBuilder<List<ClanMensaje>>(
                stream: _flujo,
                builder: (BuildContext context, AsyncSnapshot<List<ClanMensaje>> s) {
                  if (s.hasError) {
                    return Center(
                      child: VacioClan(
                        glifo: TempleGlyph.montana,
                        titulo: 'Se perdió la conexión',
                        texto: 'No pudimos traer los mensajes. Sal y vuelve a entrar.',
                      ),
                    );
                  }
                  if (!s.hasData) {
                    return const Center(
                      child: SizedBox(
                        width: 22,
                        height: 22,
                        child: CircularProgressIndicator(strokeWidth: 1.8, color: TempleColors.violeta),
                      ),
                    );
                  }
                  final List<ClanMensaje> lista = s.data!;
                  _alLlegar(lista);
                  final int mios = lista.where((ClanMensaje m) => m.esMio).length;
                  return Column(
                    children: <Widget>[
                      Expanded(child: _listaMensajes(lista)),
                      if (!_cargandoEstado) _pie(abajo, mios),
                    ],
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _listaMensajes(List<ClanMensaje> lista) {
                  if (lista.isEmpty) {
                    return const Center(
                      child: SingleChildScrollView(
                        child: VacioClan(
                          glifo: TempleGlyph.loto,
                          titulo: 'Empieza con respeto',
                          texto: 'Saluda, cuenta qué entrenas o pregunta por su rutina. '
                              'Lo personal, guárdalo para ti.',
                        ),
                      ),
                    );
                  }
                  return ListView.builder(
                    reverse: true,
                    padding: const EdgeInsets.fromLTRB(12, 10, 12, 10),
                    itemCount: lista.length,
                    itemBuilder: (BuildContext c, int i) {
                      final int idx = lista.length - 1 - i;
                      final ClanMensaje m = lista[idx];
                      final ClanMensaje? anterior = idx > 0 ? lista[idx - 1] : null;
                      final bool nuevoDia = anterior == null ||
                          !_mismoDia(anterior.creadoEn, m.creadoEn);
                      final bool agrupado = !nuevoDia &&
                          anterior != null &&
                          anterior.autor == m.autor &&
                          m.creadoEn.difference(anterior.creadoEn).inMinutes < 5;
                      return Column(
                        children: <Widget>[
                          if (nuevoDia) _SeparadorDia(fecha: m.creadoEn),
                          _BurbujaChat(
                            mensaje: m,
                            agrupado: agrupado,
                            onLongPress: () => _opcionesMensaje(m),
                          ),
                        ],
                      );
                    },
                  );
  }

  Widget _pie(double abajo, int mios) {
    // Solicitud que me llegó: primero decido.
    if (_estado == 'solicitud' && !_creadaPorMi) {
      return Container(
        padding: EdgeInsets.fromLTRB(16, 14, 16, 14 + abajo),
        decoration: const BoxDecoration(
          color: TempleColors.grafito,
          border: Border(top: BorderSide(color: TempleColors.borde)),
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: <Widget>[
            Text('@${widget.otro.usuario} quiere hablar contigo',
                style: const TextStyle(
                    fontSize: 14, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
            const SizedBox(height: 4),
            const Text(
              'No se siguen mutuamente. Si aceptas, podrán chatear con normalidad. Si rechazas, '
              'no podrá volver a escribirte por aquí y no se le avisa.',
              style: TextStyle(fontSize: 12.5, height: 1.45, color: TempleColors.textoSuave),
            ),
            const SizedBox(height: 12),
            Row(
              children: <Widget>[
                Expanded(
                  child: OutlinedButton(
                    onPressed: _respondiendo ? null : _bloquear,
                    style: OutlinedButton.styleFrom(
                      foregroundColor: TempleColors.error,
                      side: BorderSide(color: TempleColors.error.withValues(alpha: 0.45)),
                      padding: const EdgeInsets.symmetric(vertical: 12),
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(TempleRadius.campo)),
                    ),
                    child: const Text('Bloquear'),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: OutlinedButton(
                    onPressed: _respondiendo ? null : () => _responder(false),
                    style: OutlinedButton.styleFrom(
                      foregroundColor: TempleColors.textoSuave,
                      side: const BorderSide(color: TempleColors.bordeVivo),
                      padding: const EdgeInsets.symmetric(vertical: 12),
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(TempleRadius.campo)),
                    ),
                    child: const Text('Rechazar'),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: FilledButton(
                    onPressed: _respondiendo ? null : () => _responder(true),
                    style: FilledButton.styleFrom(
                      backgroundColor: TempleColors.violeta,
                      foregroundColor: Colors.white,
                      padding: const EdgeInsets.symmetric(vertical: 12),
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(TempleRadius.campo)),
                    ),
                    child: const Text('Aceptar', style: TextStyle(fontWeight: FontWeight.w600)),
                  ),
                ),
              ],
            ),
          ],
        ),
      );
    }

    if (_estado == 'rechazada') {
      return _PieCerrado(
        abajo: abajo,
        texto: 'Esta conversación está cerrada. Ya no se pueden enviar mensajes.',
      );
    }

    final bool esSolicitud = _estado == 'solicitud' && _creadaPorMi;
    final int restantes = _maxSolicitud - mios;
    if (esSolicitud && restantes <= 0) {
      return _PieCerrado(
        abajo: abajo,
        texto: 'Enviaste $_maxSolicitud mensajes. Podrás escribir más cuando @${widget.otro.usuario} '
            'acepte tu solicitud.',
      );
    }

    return Container(
      padding: EdgeInsets.fromLTRB(12, 8, 6, 8 + abajo),
      decoration: const BoxDecoration(
        color: TempleColors.grafito,
        border: Border(top: BorderSide(color: TempleColors.borde)),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: <Widget>[
          if (esSolicitud)
            Padding(
              padding: const EdgeInsets.fromLTRB(4, 2, 4, 8),
              child: Text(
                'Solicitud enviada · te quedan $restantes '
                '${restantes == 1 ? 'mensaje' : 'mensajes'} hasta que la acepte',
                style: const TextStyle(fontSize: 11.5, color: TempleColors.textoTenue),
              ),
            ),
          Row(
            crossAxisAlignment: CrossAxisAlignment.end,
            children: <Widget>[
              Expanded(
                child: TextField(
                  controller: _texto,
                  maxLength: 2000,
                  minLines: 1,
                  maxLines: 5,
                  textCapitalization: TextCapitalization.sentences,
                  style: const TextStyle(fontSize: 14.5, color: TempleColors.blancoLuna),
                  cursorColor: TempleColors.violetaClaro,
                  decoration: InputDecoration(
                    hintText: 'Escribe un mensaje',
                    hintStyle: const TextStyle(color: TempleColors.textoTenue),
                    counterText: '',
                    filled: true,
                    fillColor: TempleColors.superficie,
                    isDense: true,
                    contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(22),
                      borderSide: const BorderSide(color: TempleColors.borde),
                    ),
                    enabledBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(22),
                      borderSide: const BorderSide(color: TempleColors.borde),
                    ),
                    focusedBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(22),
                      borderSide: const BorderSide(color: TempleColors.violeta),
                    ),
                  ),
                ),
              ),
              const SizedBox(width: 4),
              IconButton(
                tooltip: 'Enviar',
                onPressed: _texto.text.trim().isEmpty || _enviando ? null : _enviar,
                icon: _enviando
                    ? const SizedBox(
                        width: 18,
                        height: 18,
                        child: CircularProgressIndicator(strokeWidth: 1.6, color: TempleColors.violeta))
                    : Icon(Icons.send_rounded,
                        color: _texto.text.trim().isEmpty
                            ? TempleColors.textoTenue
                            : TempleColors.violetaClaro),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

bool _mismoDia(DateTime a, DateTime b) =>
    a.year == b.year && a.month == b.month && a.day == b.day;

