class _SeparadorDia extends StatelessWidget {
  const _SeparadorDia({required this.fecha});
  final DateTime fecha;

  @override
  Widget build(BuildContext context) {
    final DateTime hoy = DateTime.now();
    final String texto;
    if (_mismoDia(fecha, hoy)) {
      texto = 'Hoy';
    } else if (_mismoDia(fecha, hoy.subtract(const Duration(days: 1)))) {
      texto = 'Ayer';
    } else {
      final String mes = kMesesTemplo[fecha.month - 1];
      texto = fecha.year == hoy.year ? '${fecha.day} de $mes' : '${fecha.day} de $mes de ${fecha.year}';
    }
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 12),
      child: Center(
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
          decoration: BoxDecoration(
            color: TempleColors.superficie,
            borderRadius: BorderRadius.circular(TempleRadius.pastilla),
            border: Border.all(color: TempleColors.borde),
          ),
          child: Text(texto,
              style: const TextStyle(fontSize: 11, letterSpacing: 0.4, color: TempleColors.textoSuave)),
        ),
      ),
    );
  }
}

class _BurbujaChat extends StatelessWidget {
  const _BurbujaChat({required this.mensaje, required this.agrupado, required this.onLongPress});
  final ClanMensaje mensaje;
  final bool agrupado;
  final VoidCallback onLongPress;

  @override
  Widget build(BuildContext context) {
    final bool mio = mensaje.esMio;
    const Radius r = Radius.circular(18);
    const Radius chico = Radius.circular(5);
    return Padding(
      padding: EdgeInsets.only(top: agrupado ? 2 : 8),
      child: Row(
        mainAxisAlignment: mio ? MainAxisAlignment.end : MainAxisAlignment.start,
        children: <Widget>[
          Flexible(
            child: ConstrainedBox(
              constraints: BoxConstraints(maxWidth: MediaQuery.sizeOf(context).width * 0.78),
              child: GestureDetector(
                onLongPress: onLongPress,
                child: Container(
                  padding: const EdgeInsets.fromLTRB(13, 9, 13, 7),
                  decoration: BoxDecoration(
                    gradient: mio
                        ? const LinearGradient(
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                            colors: <Color>[Color(0xFF7A4FE8), TempleColors.moradoProfundo],
                          )
                        : null,
                    color: mio ? null : TempleColors.superficieAlta,
                    border: mio ? null : Border.all(color: TempleColors.borde),
                    borderRadius: BorderRadius.only(
                      topLeft: !mio && agrupado ? chico : r,
                      topRight: mio && agrupado ? chico : r,
                      bottomLeft: mio ? r : chico,
                      bottomRight: mio ? chico : r,
                    ),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.end,
                    mainAxisSize: MainAxisSize.min,
                    children: <Widget>[
                      Align(
                        alignment: Alignment.centerLeft,
                        widthFactor: 1,
                        child: Text(
                          mensaje.texto,
                          style: TextStyle(
                              fontSize: 14,
                              height: 1.4,
                              color: mio ? Colors.white : TempleColors.texto),
                        ),
                      ),
                      const SizedBox(height: 3),
                      Text(horaClan(mensaje.creadoEn),
                          style: TextStyle(
                              fontSize: 10,
                              color: mio
                                  ? Colors.white.withValues(alpha: 0.6)
                                  : TempleColors.textoTenue)),
                    ],
                  ),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

