/// Hoja de reporte. Devuelve true si se envió (el contenido deja de verse
/// para quien reporta).
Future<bool> mostrarReporte(
  BuildContext context, {
  required String tipo,
  required String objetivo,
  required ClanPersona persona,
}) async {
  final bool? r = await showModalBottomSheet<bool>(
    context: context,
    isScrollControlled: true,
    backgroundColor: TempleColors.grafito,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
    ),
    builder: (BuildContext ctx) => _HojaReporte(tipo: tipo, objetivo: objetivo, persona: persona),
  );
  if (r == true && context.mounted) {
    avisoClan(context, 'Gracias. Lo revisaremos en menos de 24 horas.');
  }
  return r == true;
}

class _HojaReporte extends StatefulWidget {
  const _HojaReporte({required this.tipo, required this.objetivo, required this.persona});
  final String tipo;
  final String objetivo;
  final ClanPersona persona;

  @override
  State<_HojaReporte> createState() => _HojaReporteState();
}

class _HojaReporteState extends State<_HojaReporte> {
  final TextEditingController _detalle = TextEditingController();
  String? _motivo;
  bool _bloquear = false;
  bool _enviando = false;
  String? _error;

  @override
  void dispose() {
    _detalle.dispose();
    super.dispose();
  }

  String get _queSeReporta {
    switch (widget.tipo) {
      case 'publicacion':
        return 'esta publicación';
      case 'comentario':
        return 'este comentario';
      case 'mensaje':
        return 'este mensaje';
      case 'clan':
        return 'este clan';
      default:
        return 'a @${widget.persona.usuario}';
    }
  }

  Future<void> _enviar() async {
    final String? motivo = _motivo;
    if (motivo == null || _enviando) return;
    setState(() {
      _enviando = true;
      _error = null;
    });
    try {
      await ClanRepo.instancia.reportar(
        tipo: widget.tipo,
        objetivo: widget.objetivo,
        motivo: motivo,
        detalle: _detalle.text,
      );
      if (_bloquear) await ClanRepo.instancia.bloquear(widget.persona.id);
      if (mounted) Navigator.of(context).pop(true);
    } catch (e) {
      if (mounted) {
        setState(() {
          _error = SesionTemplo.mensajeDe(e);
          _enviando = false;
        });
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final bool urgente = _motivo == 'menor_en_riesgo' || _motivo == 'autolesion';
    final bool esYo = widget.persona.id == SesionTemplo.instancia.uid;
    return Padding(
      padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(context).bottom),
      child: SafeArea(
        top: false,
        child: ConstrainedBox(
          constraints: BoxConstraints(maxHeight: MediaQuery.sizeOf(context).height * 0.88),
          child: SingleChildScrollView(
            padding: const EdgeInsets.fromLTRB(20, 12, 20, 16),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: <Widget>[
                Center(
                  child: Container(
                    width: 40,
                    height: 4,
                    margin: const EdgeInsets.only(bottom: 14),
                    decoration: BoxDecoration(
                      color: TempleColors.bordeVivo,
                      borderRadius: BorderRadius.circular(2),
                    ),
                  ),
                ),
                Text('Reportar $_queSeReporta',
                    style: const TextStyle(
                        fontSize: 18, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                const SizedBox(height: 6),
                const Text(
                  'Tu reporte es anónimo. Lo dejarás de ver de inmediato y el equipo lo revisa en '
                  'menos de 24 horas.',
                  style: TextStyle(fontSize: 12.5, height: 1.45, color: TempleColors.textoSuave),
                ),
                const SizedBox(height: 14),
                for (final MapEntry<String, String> m in kMotivosReporte)
                  _OpcionMotivo(
                    texto: m.value,
                    elegido: _motivo == m.key,
                    onTap: () => setState(() => _motivo = m.key),
                  ),
                if (urgente) ...<Widget>[
                  const SizedBox(height: 6),
                  Container(
                    padding: const EdgeInsets.all(12),
                    decoration: BoxDecoration(
                      color: TempleColors.alertaSuave.withValues(alpha: 0.1),
                      borderRadius: BorderRadius.circular(TempleRadius.chip),
                      border: Border.all(color: TempleColors.alertaSuave.withValues(alpha: 0.4)),
                    ),
                    child: const Text(
                      'Este contenido se oculta para todos en cuanto lo reportas. Si alguien está en '
                      'peligro ahora mismo, llama a la línea de emergencias 123 (Colombia) o a la de '
                      'tu país.',
                      style: TextStyle(fontSize: 12.5, height: 1.45, color: TempleColors.blancoLuna),
                    ),
                  ),
                ],
                const SizedBox(height: 12),
                TextField(
                  controller: _detalle,
                  maxLength: 500,
                  minLines: 2,
                  maxLines: 4,
                  textCapitalization: TextCapitalization.sentences,
                  style: const TextStyle(fontSize: 13.5, color: TempleColors.blancoLuna),
                  cursorColor: TempleColors.violetaClaro,
                  decoration: InputDecoration(
                    hintText: 'Cuéntanos más (opcional)',
                    hintStyle: const TextStyle(color: TempleColors.textoTenue),
                    counterStyle: const TextStyle(color: TempleColors.textoTenue, fontSize: 11),
                    filled: true,
                    fillColor: TempleColors.superficie,
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(TempleRadius.campo),
                      borderSide: const BorderSide(color: TempleColors.borde),
                    ),
                    enabledBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(TempleRadius.campo),
                      borderSide: const BorderSide(color: TempleColors.borde),
                    ),
                    focusedBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(TempleRadius.campo),
                      borderSide: const BorderSide(color: TempleColors.violeta),
                    ),
                  ),
                ),
                if (!esYo)
                  CheckboxListTile(
                    value: _bloquear,
                    onChanged: (bool? v) => setState(() => _bloquear = v ?? false),
                    contentPadding: EdgeInsets.zero,
                    controlAffinity: ListTileControlAffinity.leading,
                    activeColor: TempleColors.violeta,
                    side: const BorderSide(color: TempleColors.bordeVivo, width: 1.4),
                    title: Text('Bloquear también a @${widget.persona.usuario}',
                        style: const TextStyle(fontSize: 13.5, color: TempleColors.texto)),
                  ),
                if (_error != null)
                  Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: Text(_error!,
                        style: const TextStyle(fontSize: 12.5, color: TempleColors.error)),
                  ),
                const SizedBox(height: 6),
                SizedBox(
                  height: 50,
                  child: FilledButton(
                    onPressed: _motivo == null || _enviando ? null : _enviar,
                    style: FilledButton.styleFrom(
                      backgroundColor: TempleColors.error,
                      foregroundColor: Colors.white,
                      disabledBackgroundColor: TempleColors.superficieAlta,
                      disabledForegroundColor: TempleColors.textoTenue,
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(TempleRadius.campo)),
                    ),
                    child: _enviando
                        ? const SizedBox(
                            width: 18,
                            height: 18,
                            child: CircularProgressIndicator(strokeWidth: 1.8, color: Colors.white))
                        : const Text('Enviar reporte', style: TextStyle(fontWeight: FontWeight.w600)),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class _OpcionMotivo extends StatelessWidget {
  const _OpcionMotivo({required this.texto, required this.elegido, required this.onTap});
  final String texto;
