/// Botón «⋮» con el mismo aspecto en todos los módulos.
class BotonMenuTemplo extends StatelessWidget {
  const BotonMenuTemplo({super.key, required this.onTap, this.sobreImagen = false});
  final VoidCallback onTap;

  /// Sobre una escena (la Casa) lleva fondo para leerse bien.
  final bool sobreImagen;

  @override
  Widget build(BuildContext context) {
    final Widget icono = Icon(Icons.more_vert_rounded,
        color: sobreImagen ? TempleColors.blancoLuna : TempleColors.textoSuave);
    // El Pase va siempre al lado de los ajustes, en todos los módulos.
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        const BotonPase(),
        _menu(icono),
      ],
    );
  }

  Widget _menu(Widget icono) {
    return IconButton(
      tooltip: 'Opciones',
      onPressed: () {
        HapticFeedback.selectionClick();
        onTap();
      },
      style: sobreImagen
          ? IconButton.styleFrom(
              backgroundColor: TempleColors.negro.withValues(alpha: 0.45),
              side: BorderSide(color: TempleColors.blancoLuna.withValues(alpha: 0.18)),
            )
          : null,
      icon: icono,
    );
  }
}

Future<void> mostrarMenuTemplo(
  BuildContext context, {
  required String titulo,
  required String subtitulo,
  required List<OpcionHoja> opciones,
  String? guia,
}) {
  final String? yo = SesionTemplo.instancia.uid;
  final String? usuario = SesionTemplo.instancia.actual?.usuario;
  opciones = <OpcionHoja>[
    ...opciones,
    if (guia != null)
      OpcionHoja(Icons.help_outline_rounded, 'Cómo funciona este módulo',
          () => mostrarGuiaModulo(context, guia, usuario: usuario)),
  ];
  final List<OpcionHoja> cuenta = <OpcionHoja>[
    OpcionHoja(Icons.workspace_premium_outlined,
        PaseTemplo.instancia.activo ? 'Mi Pase del Templo' : 'El Pase del Templo', () => abrirPase(context)),
    OpcionHoja(Icons.cloud_outlined, 'Mi progreso en la nube', () => mostrarEstadoNube(context)),
    OpcionHoja(Icons.notifications_none_rounded, 'Recordatorios', () => abrirRecordatorios(context)),
    OpcionHoja(Icons.music_note_outlined, 'Sonidos del templo', () => abrirAjustesSonido(context)),
    OpcionHoja(Icons.palette_outlined, 'Apariencia', () => abrirApariencia(context)),
    if (Moderacion.instancia.soyModerador)
      OpcionHoja(Icons.shield_outlined, 'Moderación', () {
        Navigator.of(context).push(MaterialPageRoute<void>(builder: (_) => const ModeracionScreen()));
      }),
    if (usuario != null)
      OpcionHoja(Icons.map_outlined, 'Repetir el recorrido del templo', () {
        Navigator.of(context).push(MaterialPageRoute<void>(
          fullscreenDialog: true,
          builder: (_) => RecorridoScreen(usuario: usuario),
        ));
      }),
    if (yo != null)
      OpcionHoja(Icons.account_circle_outlined, 'Mi perfil público', () {
        Navigator.of(context).push(MaterialPageRoute<void>(
          builder: (_) => PerfilClanScreen(id: yo),
        ));
      }),
    if (yo != null)
      OpcionHoja(Icons.visibility_outlined, 'Vista previa: cómo me ven', () {
        Navigator.of(context).push(MaterialPageRoute<void>(
          builder: (_) => PerfilClanScreen(id: yo, vistaPrevia: true),
        ));
      }),
    OpcionHoja(Icons.manage_accounts_outlined, 'Cuenta y privacidad', () {
      Navigator.of(context).push(MaterialPageRoute<void>(
        builder: (_) => const AjustesCuentaScreen(),
      ));
    }),
  ];

  Widget fila(BuildContext ctx, OpcionHoja o) => ListTile(
        dense: true,
        leading: Icon(o.icono, size: 21, color: o.peligro ? TempleColors.error : TempleColors.textoSuave),
        title: Text(o.texto,
            style: TextStyle(
                fontSize: 14, color: o.peligro ? TempleColors.error : TempleColors.blancoLuna)),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(TempleRadius.chip)),
        onTap: () {
          Navigator.of(ctx).pop();
          o.onTap();
        },
      );

  return showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    backgroundColor: TempleColors.grafito,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
    ),
    builder: (BuildContext ctx) => SafeArea(
      top: false,
      child: ConstrainedBox(
        constraints: BoxConstraints(maxHeight: MediaQuery.sizeOf(ctx).height * 0.85),
        child: SingleChildScrollView(
          padding: const EdgeInsets.fromLTRB(12, 12, 12, 12),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: <Widget>[
              Center(
                child: Container(
                  width: 40,
                  height: 4,
                  margin: const EdgeInsets.only(bottom: 14),
                  decoration: BoxDecoration(
                    color: TempleColors.bordeVivo,
                    borderRadius: BorderRadius.circular(2),
                  ),
                ),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(12, 0, 12, 8),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    Text(titulo,
                        style: const TextStyle(
                            fontSize: 17, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                    const SizedBox(height: 2),
                    Text(subtitulo,
                        style: const TextStyle(fontSize: 12, color: TempleColors.textoTenue)),
                  ],
                ),
              ),
              for (final OpcionHoja o in opciones) fila(ctx, o),
              const Padding(
                padding: EdgeInsets.fromLTRB(12, 14, 12, 4),
                child: EtiquetaSeccion('Tu cuenta'),
              ),
              for (final OpcionHoja o in cuenta) fila(ctx, o),
            ],
          ),
        ),
      ),
    ),
  );
}

void _abrirPantalla(BuildContext context, Widget pantalla) {
  Navigator.of(context).push(MaterialPageRoute<void>(builder: (_) => pantalla));
}

