class AjustesCuentaScreen extends StatefulWidget {
  const AjustesCuentaScreen({super.key});

  @override
  State<AjustesCuentaScreen> createState() => _AjustesCuentaScreenState();
}

class _AjustesCuentaScreenState extends State<AjustesCuentaScreen> {
  @override
  void initState() {
    super.initState();
    if (SesionTemplo.instancia.actual == null) {
      SesionTemplo.instancia.cargarMiPerfil().then((_) {
        if (mounted) setState(() {});
      }).catchError((Object _) {});
    }
  }

  @override
  Widget build(BuildContext context) {
    final PerfilServidor? yo = SesionTemplo.instancia.actual;
    final String? id = SesionTemplo.instancia.uid;
    final IdentidadUsuario? ident = yo == null ? null : AlmacenIdentidad.instancia.de(yo.usuario);
    final bool conFoto = ident?.foto != null;

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: Column(
          children: <Widget>[
            const BarraClan(titulo: 'Cuenta y privacidad', subtitulo: 'Tu perfil, tu seguridad, tu sesión'),
            Expanded(
              child: ListView(
                padding: EdgeInsets.fromLTRB(
                    TempleSpace.borde, 6, TempleSpace.borde, 28 + MediaQuery.paddingOf(context).bottom),
                children: <Widget>[
                  if (yo != null && ident != null)
                    TempleCard(
                      child: Row(
                        children: <Widget>[
                          GestureDetector(
                            onTap: () async {
                              if (await elegirFotoPerfil(context) && mounted) setState(() {});
                            },
                            child: SelloUsuario(
                              identidad: ident,
                              kanji: kanjiDeEspiritu(yo.espiritu ?? ''),
                              nivel: 1,
                              size: 62,
                              mostrarNivel: false,
                            ),
                          ),
                          const SizedBox(width: 14),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: <Widget>[
                                Text(ident.nombreMostrado(yo.usuario),
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: const TextStyle(
                                        fontSize: 17,
                                        fontWeight: FontWeight.w600,
                                        color: TempleColors.blancoLuna)),
                                const SizedBox(height: 3),
                                Text('@${yo.usuario}',
                                    style: const TextStyle(fontSize: 12, color: TempleColors.textoTenue)),
                                const SizedBox(height: 8),
                                BurbujaEdadGenero(edad: yo.edad, genero: yo.genero),
                              ],
                            ),
                          ),
                        ],
                      ),
                    ),
                  const SizedBox(height: 22),
                  const EtiquetaSeccion('Perfil'),
                  if (id != null) ...<Widget>[
                    _FilaAjuste(
                      icono: Icons.account_circle_outlined,
                      titulo: 'Ver mi perfil público',
                      detalle: 'Tu viñeta, tu racha y tus publicaciones',
                      onTap: () => _abrirPantalla(context, PerfilClanScreen(id: id)),
                    ),
                    _FilaAjuste(
                      icono: Icons.visibility_outlined,
                      titulo: 'Vista previa',
                      detalle: 'Mira tu perfil tal como lo ven los demás',
                      onTap: () => _abrirPantalla(context, PerfilClanScreen(id: id, vistaPrevia: true)),
                    ),
                  ],
                  _FilaAjuste(
                    icono: Icons.photo_library_outlined,
                    titulo: conFoto ? 'Cambiar foto de perfil' : 'Poner foto de perfil',
                    detalle: 'Elige una foto de tu galería',
                    onTap: () async {
                      if (await elegirFotoPerfil(context) && mounted) setState(() {});
                    },
                  ),
                  if (conFoto && yo != null)
                    _FilaAjuste(
                      icono: Icons.hide_image_outlined,
                      titulo: 'Quitar foto',
                      detalle: 'Vuelve a mostrar tu sello',
                      onTap: () async {
                        await SesionTemplo.instancia.quitarFotoPerfil(yo.usuario);
                        if (mounted) setState(() {});
                      },
                    ),
                  if (yo != null) ...<Widget>[
                    _FilaAjuste(
                      icono: Icons.edit_outlined,
                      titulo: 'Nombre, biografía y sello',
