class RankedScreen extends StatefulWidget {
  const RankedScreen({super.key, this.usuario});

  /// Si viene, la pantalla se abre fuera del shell (desde el resumen).
  final String? usuario;

  @override
  State<RankedScreen> createState() => _RankedScreenState();
}

class _RankedScreenState extends State<RankedScreen> {
  bool _espalda = false;
  final Set<GrupoMuscular> _seleccion = <GrupoMuscular>{};
  bool _ceremoniaVista = false;

  String _usuario(BuildContext context) =>
      widget.usuario ?? TempleShellScope.of(context).perfil.nombre;

  bool get _suelta => widget.usuario != null;

  void _alternar(GrupoMuscular g) {
    setState(() {
      if (!_seleccion.remove(g)) _seleccion.add(g);
    });
  }

  Future<void> _ceremonia(String usuario) async {
    await mostrarCeremoniaRanked(context, usuario);
    await SesionTemplo.instancia.sincronizarIdentidad(usuario);
    if (mounted) setState(() {});
  }

  Future<void> _forjar(String usuario) async {
    if (_seleccion.isEmpty) return;
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final Sesion? enCurso = a.de(usuario).enCurso;
    if (enCurso != null) {
      final bool seguir = await confirmarClan(
        context,
        titulo: 'Tienes una sesión a medias',
        texto: 'Termínala primero. Puedes retomarla ahora mismo.',
        accion: 'Retomar',
      );
      if (!seguir || !mounted) return;
      await Navigator.of(context).push(MaterialPageRoute<void>(
        builder: (_) => SesionScreen(usuario: usuario, sesion: enCurso),
      ));
      if (mounted) setState(() {});
      return;
    }
    final List<GrupoMuscular> grupos = GrupoMuscular.values.where(_seleccion.contains).toList();
    final PlanSesion plan = planParaMusculos(usuario, grupos);
    if (plan.ejercicios.isEmpty) {
      avisoClan(context, 'No hay ejercicios para esos músculos con tu material.', error: true);
      return;
    }
    final Sesion s = a.abrirSesion(usuario, plan, a.disposicion(usuario, grupos).valor);
    await Navigator.of(context).push(MaterialPageRoute<void>(
      builder: (_) => SesionScreen(usuario: usuario, sesion: s),
    ));
    if (mounted) {
      setState(() => _seleccion.clear());
    }
  }

  @override
  Widget build(BuildContext context) {
    final String usuario = _usuario(context);
    final Widget cuerpo = MotorRanked.desbloqueado(usuario)
        ? _abierto(context, usuario)
        : _RankedBloqueado(usuario: usuario, suelta: _suelta);

    if (!_suelta) return cuerpo;
    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(child: cuerpo),
    );
  }

  Widget _abierto(BuildContext context, String usuario) {
    final EstadoRanked e = MotorRanked.de(usuario);
    final List<AscensoRanked> pendientes = AlmacenRanked.instancia.pendientes(usuario);
    if (pendientes.isNotEmpty && !_ceremoniaVista) {
      _ceremoniaVista = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _ceremonia(usuario);
      });
    }
    final int cuerpo = e.rangoCuerpo;
    final double abajo = _suelta ? 28 : kAlturaNavBar + 28;

    return ListView(
      physics: const BouncingScrollPhysics(),
      padding: EdgeInsets.fromLTRB(
          TempleSpace.borde, MediaQuery.paddingOf(context).top + 8, TempleSpace.borde, abajo),
      children: <Widget>[
        Row(
          children: <Widget>[
            if (_suelta)
              IconButton(
                onPressed: () => Navigator.of(context).maybePop(),
                icon: const Icon(Icons.arrow_back_rounded, color: TempleColors.textoSuave),
              ),
            const Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Text('Ranked',
                      style: TextStyle(
                          fontSize: 26,
                          fontWeight: FontWeight.w600,
                          letterSpacing: 0.4,
                          color: TempleColors.blancoLuna)),
                  SizedBox(height: 2),
                  Text('Nueve músculos, nueve caminos',
                      style: TextStyle(fontSize: 12.5, color: TempleColors.textoSuave)),
                ],
              ),
            ),
            if (!_suelta) BotonMenuTemplo(onTap: () => menuRanked(context, usuario: usuario)),
          ],
        ),
        const SizedBox(height: 16),

        // -- Rango del cuerpo ---------------------------------------------
        TempleCard(
          destacada: true,
          child: Row(
            children: <Widget>[
              EmblemaRanked(rango: cuerpo, size: 74, animado: true),
              const SizedBox(width: 16),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    const Text('RANGO DEL CUERPO',
                        style: TextStyle(
                            fontSize: 10.5,
                            letterSpacing: 1.8,
                            fontWeight: FontWeight.w600,
                            color: TempleColors.textoSuave)),
                    const SizedBox(height: 4),
                    Text(RangosRanked.nombre(cuerpo),
                        style: TextStyle(
                            fontSize: 21,
                            fontWeight: FontWeight.w700,
                            color: RangosRanked.color(cuerpo))),
                    const SizedBox(height: 4),
                    Text('${e.total.round()} de honor · ${e.honorSemana.round()} esta semana',
                        style: const TextStyle(fontSize: 12, color: TempleColors.textoSuave)),
                    const SizedBox(height: 10),
                    Row(
                      children: <Widget>[
                        const Text('Equilibrio',
                            style: TextStyle(fontSize: 11, color: TempleColors.textoTenue)),
                        const SizedBox(width: 8),
                        Expanded(
                          child: _BarraRanked(
                            valor: e.equilibrio,
                            color: TempleColors.violetaClaro,
                          ),
                        ),
                        const SizedBox(width: 8),
                        Text('${(e.equilibrio * 100).round()}%',
                            style: const TextStyle(fontSize: 11, color: TempleColors.violetaClaro)),
                      ],
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 12),

        if (pendientes.isNotEmpty) ...<Widget>[
          _BannerAscensos(n: pendientes.length, onTap: () => _ceremonia(usuario)),
          const SizedBox(height: 12),
        ],

        _BendicionCard(grupo: e.bendicion, musculo: e.de(e.bendicion)),
        const SizedBox(height: 18),

        // -- La silueta ---------------------------------------------------
        EtiquetaSeccion(
          'Elige qué forjar hoy',
          accion: _Conmutador(
            espalda: _espalda,
            onCambio: (bool v) => setState(() => _espalda = v),
          ),
        ),
        TempleCard(
          padding: const EdgeInsets.fromLTRB(10, 14, 10, 14),
          child: Column(
            children: <Widget>[
              AnimatedSwitcher(
                duration: const Duration(milliseconds: 560),
                switchInCurve: Curves.easeOutCubic,
                switchOutCurve: Curves.easeInCubic,
                // Al darle la vuelta, el guerrero gira sobre sí mismo.
                transitionBuilder: (Widget hijo, Animation<double> a) => AnimatedBuilder(
                  animation: a,
                  child: hijo,
                  builder: (BuildContext context, Widget? w) {
                    if (a.value < 0.5) return Opacity(opacity: 0, child: w);
                    final bool entra = hijo.key == ValueKey<bool>(_espalda);
                    final double angulo = (1 - a.value) * math.pi * (entra ? 1 : -1);
                    return Transform(
                      alignment: Alignment.center,
                      transform: Matrix4.identity()
                        ..setEntry(3, 2, 0.0016)
                        ..rotateY(angulo),
                      child: w,
                    );
                  },
                ),
                layoutBuilder: (Widget? actual, List<Widget> previos) => Stack(
                  alignment: Alignment.center,
                  children: <Widget>[...previos, if (actual != null) actual],
                ),
                child: SiluetaRanked(
                  key: ValueKey<bool>(_espalda),
                  espalda: _espalda,
                  altura: 380,
                  rangos: <GrupoMuscular, int>{
                    for (final MusculoRanked m in e.musculos.values) m.grupo: m.rango,
                  },
                  dormidos: <GrupoMuscular>{
                    for (final MusculoRanked m in e.musculos.values)
                      if (m.dormido) m.grupo,
                  },
                  aPunto: <GrupoMuscular>{
                    for (final MusculoRanked m in e.musculos.values)
                      if (m.aPunto) m.grupo,
                  },
                  seleccion: _seleccion,
                  bendicion: e.bendicion,
                  onToque: _alternar,
                ),
              ),
              const SizedBox(height: 6),
              Text(
                _seleccion.isEmpty
                    ? 'Toca los músculos que quieres entrenar · ${_espalda ? 'espalda' : 'frente'}'
                    : _seleccion.map((GrupoMuscular g) => g.etiqueta).join(' · '),
                textAlign: TextAlign.center,
                style: TextStyle(
                    fontSize: 12.5,
                    color: _seleccion.isEmpty ? TempleColors.textoTenue : TempleColors.blancoLuna),
              ),
              const SizedBox(height: 12),
              AnimatedOpacity(
                duration: TempleMotion.rapido,
                opacity: _seleccion.isEmpty ? 0.45 : 1,
                child: DojoPrimaryButton(
                  texto: _seleccion.isEmpty
                      ? 'Forjar sesión'
                      : 'Forjar sesión · ${_seleccion.length} '
                          '${_seleccion.length == 1 ? 'músculo' : 'músculos'}',
                  onPressed: () => _forjar(usuario),
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 18),

        Row(
          children: <Widget>[
            Expanded(
              child: _AccesoRanked(
                icono: Icons.leaderboard_outlined,
                titulo: 'Tabla del clan',
                texto: 'Tú contra quienes sigues',
                onTap: () => Navigator.of(context).push(MaterialPageRoute<void>(
                  builder: (_) => const TablaClanRankedScreen(),
                )),
              ),
            ),
            const SizedBox(width: 10),
            Expanded(
              child: _AccesoRanked(
                icono: Icons.stairs_outlined,
                titulo: 'Escalera',
                texto: 'Los 22 rangos y sus premios',
                onTap: () => Navigator.of(context).push(MaterialPageRoute<void>(
                  builder: (_) => const EscaleraRankedScreen(),
                )),
              ),
            ),
          ],
        ),
        const SizedBox(height: 22),

        // -- El guerrero que evoluciona ------------------------------------
        const EtiquetaSeccion('Tu guerrero'),
        TempleCard(
          padding: const EdgeInsets.fromLTRB(14, 12, 14, 14),
          child: Row(
            children: <Widget>[
              SizedBox(
                width: 132,
                child: GuerreroRanked(
                  altura: 168,
                  rangoCuerpo: e.rangoCuerpo,
                  rangos: <GrupoMuscular, int>{
                    for (final MusculoRanked m in e.musculos.values) m.grupo: m.rango,
                  },
                ),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    Text(
                      e.rangoCuerpo < 0 ? 'Aún sin rango' : 'Cuerpo ${RangosRanked.nombre(e.rangoCuerpo)}',
                      style: const TextStyle(
                          fontSize: 16, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna),
                    ),
                    const SizedBox(height: 6),
                    const Text(
                      'Crece con tus rangos: cada músculo se ensancha al subir y el aura toma el '
                      'color del rango de tu cuerpo. Si entrenas parejo, tu guerrero se ve equilibrado.',
                      style: TextStyle(fontSize: 12.5, height: 1.45, color: TempleColors.textoSuave),
                    ),
                    const SizedBox(height: 8),
                    Text(
                      'Equilibrio ${(e.equilibrio * 100).round()} %',
                      style: const TextStyle(fontSize: 12, color: TempleColors.violetaClaro),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 22),

        const EtiquetaSeccion('Tus nueve guerreros'),
        for (final MusculoRanked m in e.ordenados)
          _FilaMusculo(
            musculo: m,
            bendecido: m.grupo == e.bendicion,
            onTap: () async {
              await Navigator.of(context).push(MaterialPageRoute<void>(
                builder: (_) => FichaMusculoScreen(usuario: usuario, grupo: m.grupo),
              ));
              if (mounted) setState(() {});
            },
          ),
      ],
    );
  }
}

