class _BarraRanked extends StatelessWidget {
  const _BarraRanked({required this.valor, required this.color, this.alto = 6});
  final double valor;
  final Color color;
  final double alto;

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(999),
      child: Stack(
        children: <Widget>[
          Container(height: alto, color: TempleColors.borde),
          TweenAnimationBuilder<double>(
            tween: Tween<double>(begin: 0, end: valor.clamp(0.0, 1.0)),
            duration: const Duration(milliseconds: 900),
            curve: TempleMotion.entrada,
            builder: (BuildContext context, double v, _) => FractionallySizedBox(
              widthFactor: v,
              child: Container(
                height: alto,
                decoration: BoxDecoration(
                  gradient: LinearGradient(colors: <Color>[
                    Color.lerp(color, Colors.white, 0.2)!,
                    color,
                  ]),
                  boxShadow: <BoxShadow>[
                    BoxShadow(color: color.withValues(alpha: 0.5), blurRadius: 6),
                  ],
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _Conmutador extends StatelessWidget {
  const _Conmutador({required this.espalda, required this.onCambio});
  final bool espalda;
  final ValueChanged<bool> onCambio;

  @override
  Widget build(BuildContext context) {
    Widget op(String t, bool activo, bool valor) => GestureDetector(
          onTap: () {
            HapticFeedback.selectionClick();
            onCambio(valor);
          },
          child: AnimatedContainer(
