class _FilaMusculo extends StatelessWidget {
  const _FilaMusculo({required this.musculo, required this.bendecido, required this.onTap});
  final MusculoRanked musculo;
  final bool bendecido;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final MusculoRanked m = musculo;
    String? estado;
    Color colorEstado = TempleColors.textoTenue;
    if (m.pruebaPendiente != null) {
      estado = 'Prueba de ${m.pruebaPendiente!.nombre}';
      colorEstado = TempleColors.alertaSuave;
    } else if (m.aPunto) {
      estado = '¡A punto!';
      colorEstado = TempleColors.exito;
    } else if (m.dormido) {
      estado = 'Dormido · ${m.dias} d';
    } else if (bendecido) {
      estado = 'Bendecido';
      colorEstado = TempleColors.dorado;
    }
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: TempleCard(
        onTap: onTap,
        padding: const EdgeInsets.fromLTRB(12, 12, 14, 12),
        child: Row(
          children: <Widget>[
            EmblemaRanked(rango: m.rango, size: 50),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Row(
                    children: <Widget>[
                      Text(m.grupo.etiqueta,
                          style: const TextStyle(
                              fontSize: 14.5, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                      const SizedBox(width: 8),
                      Flexible(
                        child: Text(m.nombreRango,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: m.color)),
                      ),
                    ],
                  ),
                  const SizedBox(height: 7),
                  _BarraRanked(valor: m.progreso, color: m.rango < 0 ? TempleColors.violeta : m.color, alto: 5),
                  const SizedBox(height: 6),
                  Row(
                    children: <Widget>[
                      Text(
                        m.maximo
                            ? 'Cima alcanzada'
                            : m.rango < 0
                                ? 'Aún sin entrenar'
                                : 'Faltan ${m.faltan} de honor',
                        style: const TextStyle(fontSize: 11, color: TempleColors.textoSuave),
                      ),
                      const Spacer(),
                      if (estado != null)
                        Text(estado,
                            style: TextStyle(fontSize: 11, fontWeight: FontWeight.w600, color: colorEstado)),
                    ],
