  final GrupoMuscular grupo;

  @override
  Widget build(BuildContext context) {
    final EstadoRanked e = MotorRanked.de(usuario);
    final MusculoRanked m = e.de(grupo);
    final DefTierRanked t = RangosRanked.tierDe(m.rango < 0 ? 0 : m.rango);
    final int siguiente = math.min(m.rango + 1, RangosRanked.maximo);

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: Column(
          children: <Widget>[
            BarraClan(titulo: grupo.etiqueta, subtitulo: m.nombreRango),
            Expanded(
              child: ListView(
                physics: const BouncingScrollPhysics(),
                padding: EdgeInsets.fromLTRB(
                    TempleSpace.borde, 4, TempleSpace.borde, 28 + MediaQuery.paddingOf(context).bottom),
                children: <Widget>[
                  Center(child: EmblemaRanked(rango: m.rango, size: 132, animado: true)),
                  const SizedBox(height: 14),
                  Text(m.nombreRango,
                      textAlign: TextAlign.center,
                      style: TextStyle(fontSize: 26, fontWeight: FontWeight.w700, color: m.color)),
                  const SizedBox(height: 4),
                  Text(m.rango < 0 ? 'Este guerrero aún no ha pisado el dojo.' : t.lema,
                      textAlign: TextAlign.center,
                      style: const TextStyle(fontSize: 13, height: 1.45, color: TempleColors.textoSuave)),
                  const SizedBox(height: 18),
                  TempleCard(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: <Widget>[
                        Row(
                          children: <Widget>[
                            Text('${m.xp.round()} de honor',
                                style: const TextStyle(
                                    fontSize: 15, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                            const Spacer(),
                            if (!m.maximo)
                              Text('Meta ${m.xpSiguiente}',
                                  style: const TextStyle(fontSize: 12, color: TempleColors.textoSuave)),
                          ],
                        ),
                        const SizedBox(height: 10),
                        _BarraRanked(valor: m.progreso, color: m.rango < 0 ? TempleColors.violeta : m.color, alto: 8),
                        const SizedBox(height: 10),
                        if (!m.maximo)
                          Row(
                            children: <Widget>[
                              const Text('Siguiente: ',
                                  style: TextStyle(fontSize: 12, color: TempleColors.textoTenue)),
                              EmblemaRanked(rango: siguiente, size: 22),
                              const SizedBox(width: 6),
                              Text(RangosRanked.nombre(siguiente),
                                  style: TextStyle(
                                      fontSize: 12.5,
                                      fontWeight: FontWeight.w600,
                                      color: RangosRanked.color(siguiente))),
                              const Spacer(),
                              const IconoMon(size: 14),
                              const SizedBox(width: 4),
                              Text('+${RangosRanked.monDe(siguiente)}',
                                  style: const TextStyle(fontSize: 12, color: TempleColors.dorado)),
                            ],
                          ),
                      ],
                    ),
                  ),
                  if (m.pruebaPendiente != null) ...<Widget>[
                    const SizedBox(height: 12),
                    _TarjetaPrueba(musculo: m),
                  ],
                  const SizedBox(height: 22),
                  const EtiquetaSeccion('Estadísticas'),
                  GridView.count(
                    crossAxisCount: 2,
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    mainAxisSpacing: 10,
                    crossAxisSpacing: 10,
                    childAspectRatio: 2.1,
                    children: <Widget>[
                      _Estadistica(titulo: 'Volumen (7 días)', valor: '${m.volumenSemana.round()} kg'),
                      _Estadistica(
                          titulo: 'Peso máximo',
                          valor: m.pesoMaximo <= 0 ? '—' : '${m.pesoMaximo.toStringAsFixed(1)} kg'),
                      _Estadistica(
                          titulo: 'Frecuencia', valor: '${m.frecuencia.toStringAsFixed(1)} / semana'),
                      _Estadistica(
                          titulo: 'Técnica', valor: m.tecnica <= 0 ? '—' : '${(m.tecnica * 100).round()}% series'),
                      _Estadistica(
                          titulo: 'Simetría',
                          valor: m.simetria == null ? 'Sin unilaterales' : '${(m.simetria! * 100).round()}%'),
                      _Estadistica(
                          titulo: 'Racha', valor: '${m.rachaSemanas} ${m.rachaSemanas == 1 ? 'semana' : 'semanas'}'),
                    ],
                  ),
                  const SizedBox(height: 22),
                  const EtiquetaSeccion('Honor de las últimas 8 semanas'),
                  TempleCard(
                    child: SizedBox(
                      height: 130,
                      child: _HistorialHonor(valores: m.semanal, color: m.rango < 0 ? TempleColors.violeta : m.color),
                    ),
                  ),
                  const SizedBox(height: 12),
                  PronosticoRanked(musculo: m),
                  const SizedBox(height: 22),
                  EtiquetaSeccion('Toda su historia', accion: LimitesPase.pase ? null : const ChipPase()),
                  HistoriaMusculo(usuario: usuario, musculo: m),
                  const SizedBox(height: 22),
                  const EtiquetaSeccion('Su camino'),
                  _MiniEscalera(rango: m.rango),
                  const SizedBox(height: 24),
                  DojoPrimaryButton(
                    texto: 'Forjar ${grupo.etiqueta.toLowerCase()} ahora',
                    onPressed: () async {
                      final AlmacenTemplo a = AlmacenTemplo.instancia;
                      if (a.de(usuario).enCurso != null) {
                        avisoClan(context, 'Termina primero la sesión que tienes a medias.', error: true);
                        return;
                      }
                      final PlanSesion plan = planParaMusculos(usuario, <GrupoMuscular>[grupo]);
                      if (plan.ejercicios.isEmpty) {
                        avisoClan(context, 'No hay ejercicios para este músculo con tu material.', error: true);
                        return;
                      }
                      final Sesion s = a.abrirSesion(
                          usuario, plan, a.disposicion(usuario, <GrupoMuscular>[grupo]).valor);
                      await Navigator.of(context).pushReplacement(MaterialPageRoute<void>(
                        builder: (_) => SesionScreen(usuario: usuario, sesion: s),
                      ));
                    },
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

