class _HistorialHonor extends StatelessWidget {
  const _HistorialHonor({required this.valores, required this.color});
  final List<double> valores;
  final Color color;

  @override
  Widget build(BuildContext context) {
    final double maximo = valores.fold<double>(1, (double a, double b) => math.max(a, b));
    return Row(
      crossAxisAlignment: CrossAxisAlignment.end,
      children: <Widget>[
        for (int i = 0; i < valores.length; i++)
          Expanded(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 4),
              child: Column(
                mainAxisAlignment: MainAxisAlignment.end,
                children: <Widget>[
                  Text(valores[i] <= 0 ? '' : '${valores[i].round()}',
                      style: const TextStyle(fontSize: 9.5, color: TempleColors.textoSuave)),
                  const SizedBox(height: 4),
                  TweenAnimationBuilder<double>(
                    tween: Tween<double>(begin: 0, end: valores[i] / maximo),
                    duration: Duration(milliseconds: 500 + i * 70),
                    curve: TempleMotion.entrada,
                    builder: (BuildContext context, double v, _) => Container(
                      height: math.max(3, 84 * v),
                      decoration: BoxDecoration(
                        borderRadius: BorderRadius.circular(5),
                        gradient: LinearGradient(
                          begin: Alignment.topCenter,
                          end: Alignment.bottomCenter,
                          colors: <Color>[
                            color.withValues(alpha: i == valores.length - 1 ? 1 : 0.75),
                            color.withValues(alpha: 0.25),
                          ],
                        ),
                      ),
                    ),
                  ),
                  const SizedBox(height: 6),
                  Text(i == valores.length - 1 ? 'Hoy' : '-${valores.length - 1 - i}',
                      style: const TextStyle(fontSize: 9.5, color: TempleColors.textoTenue)),
                ],
              ),
            ),
          ),
      ],
    );
  }
}

class _MiniEscalera extends StatelessWidget {
