// 37.8 CEREMONIA DE ASCENSO
// ---------------------------------------------------------------------------

Future<void> mostrarCeremoniaRanked(BuildContext context, String usuario) async {
  final List<AscensoRanked> pend = AlmacenRanked.instancia.pendientes(usuario);
  if (pend.isEmpty) return;
  // Un momento por músculo: de dónde venía y hasta dónde llegó.
  final List<GrupoMuscular> orden = <GrupoMuscular>[];
  for (final AscensoRanked a in pend) {
    if (!orden.contains(a.grupo)) orden.add(a.grupo);
  }
  for (final GrupoMuscular g in orden) {
    if (!context.mounted) return;
    final List<AscensoRanked> deG = pend.where((AscensoRanked a) => a.grupo == g).toList();
    final int desde = deG.first.rango - 1;
    final int hasta = deG.last.rango;
    final RecompensaRanked r = AlmacenRanked.instancia.cobrar(usuario, g);
    HapticFeedback.heavyImpact();
    sonar(SonidoTemplo.nivel);
    await showGeneralDialog<void>(
      context: context,
      barrierDismissible: false,
      barrierColor: Colors.black.withValues(alpha: 0.88),
      transitionDuration: const Duration(milliseconds: 420),
      pageBuilder: (BuildContext ctx, _, __) => _CeremoniaRanked(
        grupo: g,
        desde: desde,
        hasta: hasta,
        recompensa: r,
        quedan: orden.length - 1 - orden.indexOf(g),
      ),
      transitionBuilder: (BuildContext ctx, Animation<double> a, _, Widget hijo) => FadeTransition(
        opacity: a,
        child: ScaleTransition(
          scale: Tween<double>(begin: 1.08, end: 1).animate(CurvedAnimation(parent: a, curve: TempleMotion.entrada)),
          child: hijo,
        ),
      ),
    );
  }
}

class _CeremoniaRanked extends StatefulWidget {
  const _CeremoniaRanked({
    required this.grupo,
    required this.desde,
    required this.hasta,
    required this.recompensa,
    required this.quedan,
  });

  final GrupoMuscular grupo;
  final int desde;
  final int hasta;
  final RecompensaRanked recompensa;
  final int quedan;

  @override
  State<_CeremoniaRanked> createState() => _CeremoniaRankedState();
}

class _CeremoniaRankedState extends State<_CeremoniaRanked> with SingleTickerProviderStateMixin {
  late final AnimationController _c =
      AnimationController(vsync: this, duration: const Duration(milliseconds: 1800))..forward();

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final DefTierRanked t = RangosRanked.tierDe(widget.hasta);
    final bool nuevoTier = RangosRanked.esEntrada(widget.hasta) ||
        RangosRanked.tierDe(math.max(widget.desde, 0)).tier != t.tier;
    final RecompensaRanked r = widget.recompensa;

    return Material(
      type: MaterialType.transparency,
      child: SafeArea(
        child: AnimatedBuilder(
          animation: _c,
          builder: (BuildContext context, _) {
            final double v = Curves.easeOutBack.transform(_c.value.clamp(0.0, 1.0));
            return Stack(
              alignment: Alignment.center,
              children: <Widget>[
                // Destello y partículas.
                Positioned.fill(
                  child: CustomPaint(
                    painter: _DestelloPainter(t: _c.value, color: t.color),
                  ),
                ),
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 28),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: <Widget>[
                      Text(nuevoTier ? 'NUEVO TIER' : 'ASCENSO',
                          style: TextStyle(
                              fontSize: 12,
                              letterSpacing: 5,
                              fontWeight: FontWeight.w700,
                              color: t.color.withValues(alpha: _c.value))),
                      const SizedBox(height: 18),
                      Transform.scale(
                        scale: 0.4 + 0.6 * v,
                        child: EmblemaRanked(rango: widget.hasta, size: 170, animado: true),
                      ),
                      const SizedBox(height: 22),
                      Opacity(
                        opacity: (_c.value * 1.6 - 0.5).clamp(0.0, 1.0),
                        child: Column(
                          children: <Widget>[
                            Text(widget.grupo.etiqueta.toUpperCase(),
                                style: const TextStyle(
                                    fontSize: 13,
                                    letterSpacing: 3,
                                    color: TempleColors.textoSuave)),
                            const SizedBox(height: 6),
                            Text(RangosRanked.nombre(widget.hasta),
                                textAlign: TextAlign.center,
                                style: TextStyle(
                                    fontSize: 32, fontWeight: FontWeight.w700, color: t.color)),
                            const SizedBox(height: 6),
                            Text(
                              widget.desde < 0
