class _DestelloPainter extends CustomPainter {
  const _DestelloPainter({required this.t, required this.color});
  final double t;
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    final Offset c = Offset(size.width / 2, size.height * 0.36);
    canvas.drawCircle(
      c,
      size.width * (0.2 + 0.5 * t),
      Paint()
        ..color = color.withValues(alpha: 0.22 * (1 - t * 0.6))
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 40),
    );
    final math.Random r = math.Random(7);
    for (int i = 0; i < 46; i++) {
      final double a = r.nextDouble() * 2 * math.pi;
      final double d = (0.15 + r.nextDouble() * 0.6) * size.width * Curves.easeOut.transform(t);
      final Offset p = c + Offset(math.cos(a) * d, math.sin(a) * d - 30 * t);
      canvas.drawCircle(
        p,
        1 + r.nextDouble() * 2.4,
        Paint()..color = (i.isEven ? color : Colors.white).withValues(alpha: (1 - t) * 0.9),
      );
    }
  }

  @override
  bool shouldRepaint(_DestelloPainter old) => old.t != t;
}

