class _FilaTablaRanked {
  const _FilaTablaRanked({required this.persona, required this.xp, required this.esYo});
  final ClanPersona persona;
  final double xp;
  final bool esYo;
}

class TablaClanRankedScreen extends StatefulWidget {
  const TablaClanRankedScreen({super.key});

  @override
  State<TablaClanRankedScreen> createState() => _TablaClanRankedScreenState();
}

class _TablaClanRankedScreenState extends State<TablaClanRankedScreen> {
  String _musculo = 'total';
  List<_FilaTablaRanked>? _filas;
  String? _error;

  @override
  void initState() {
    super.initState();
    _cargar();
  }

  Future<void> _cargar() async {
    setState(() {
      _filas = null;
      _error = null;
    });
    try {
      // Antes de leer la tabla, sube tu propio ranked para que salga al día.
      final String? u = SesionTemplo.instancia.actual?.usuario;
      if (u != null) await SesionTemplo.instancia.sincronizarIdentidad(u);
      final Object? r = await supa.rpc('ranking_clan', params: <String, dynamic>{'musculo': _musculo});
      final List<_FilaTablaRanked> l = <_FilaTablaRanked>[];
      if (r is List) {
        for (final Object? x in r) {
          if (x is! Map) continue;
          final Map<String, dynamic> m = Map<String, dynamic>.from(x);
          l.add(_FilaTablaRanked(
            persona: ClanPersona.desdeMapa(m),
            xp: (m['xp'] as num?)?.toDouble() ?? 0,
            esYo: m['es_yo'] == true,
          ));
        }
      }
      if (mounted) setState(() => _filas = l);
    } catch (e) {
      if (mounted) {
        setState(() => _error = 'La tabla del clan todavía no está activa en el servidor. '
            'Ejecuta el archivo SQL de Ranked en Supabase.');
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final List<_FilaTablaRanked>? f = _filas;
    String? rival;
    if (f != null) {
      final int yo = f.indexWhere((_FilaTablaRanked x) => x.esYo);
      if (yo > 0) {
        final _FilaTablaRanked arriba = f[yo - 1];
        rival = 'Te faltan ${(arriba.xp - f[yo].xp).ceil() + 1} de honor para superar a '
            '@${arriba.persona.usuario}.';
      } else if (yo == 0 && f.length > 1) {
        rival = 'Vas primero. @${f[1].persona.usuario} viene a '
            '${(f[0].xp - f[1].xp).round()} de honor.';
      }
    }

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: Column(
          children: <Widget>[
            const BarraClan(titulo: 'Tabla del clan', subtitulo: 'Tú y las personas que sigues'),
            SizedBox(
              height: 44,
              child: ListView(
                scrollDirection: Axis.horizontal,
                padding: const EdgeInsets.symmetric(horizontal: TempleSpace.borde),
                children: <Widget>[
                  for (final MapEntry<String, String> op in <MapEntry<String, String>>[
                    const MapEntry<String, String>('total', 'Total'),
                    for (final GrupoMuscular g in GrupoMuscular.values)
                      MapEntry<String, String>(g.name, g.etiqueta),
                  ])
                    Padding(
                      padding: const EdgeInsets.only(right: 8),
                      child: ChoiceChip(
                        label: Text(op.value),
                        selected: _musculo == op.key,
                        onSelected: (_) {
                          setState(() => _musculo = op.key);
                          _cargar();
                        },
                        selectedColor: TempleColors.violeta.withValues(alpha: 0.3),
                        backgroundColor: TempleColors.superficie,
                        side: const BorderSide(color: TempleColors.borde),
                        labelStyle: TextStyle(
                          fontSize: 12.5,
                          color: _musculo == op.key ? TempleColors.blancoLuna : TempleColors.textoSuave,
                        ),
                        showCheckmark: false,
                        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(TempleRadius.pastilla)),
                      ),
                    ),
                ],
              ),
            ),
            const SizedBox(height: 8),
            Expanded(
              child: _error != null
                  ? Center(
                      child: VacioClan(
                        glifo: TempleGlyph.espadas,
                        titulo: 'Tabla no disponible',
                        texto: _error!,
                        accion: 'Reintentar',
                        onAccion: _cargar,
                      ),
                    )
                  : f == null
                      ? const Center(
                          child: SizedBox(
                            width: 22,
                            height: 22,
                            child: CircularProgressIndicator(strokeWidth: 1.8, color: TempleColors.violeta),
                          ),
                        )
                      : RefreshIndicator(
                          color: TempleColors.violeta,
                          onRefresh: _cargar,
                          child: ListView(
                            physics: const AlwaysScrollableScrollPhysics(),
                            padding: EdgeInsets.fromLTRB(TempleSpace.borde, 4, TempleSpace.borde,
                                28 + MediaQuery.paddingOf(context).bottom),
                            children: <Widget>[
                              if (rival != null)
                                Container(
                                  margin: const EdgeInsets.only(bottom: 12),
                                  padding: const EdgeInsets.all(12),
                                  decoration: BoxDecoration(
                                    color: TempleColors.violeta.withValues(alpha: 0.1),
                                    borderRadius: BorderRadius.circular(TempleRadius.chip),
                                    border: Border.all(color: TempleColors.violeta.withValues(alpha: 0.3)),
                                  ),
                                  child: Text(rival,
                                      style: const TextStyle(fontSize: 13, color: TempleColors.blancoLuna)),
                                ),
                              if (f.length <= 1)
                                const VacioClan(
                                  glifo: TempleGlyph.clan,
                                  titulo: 'Aún compites solo',
                                  texto: 'Sigue a otras personas en el Clan y aparecerán aquí para medir '
                                      'quién forja más.',
                                ),
                              for (int i = 0; i < f.length; i++)
                                _FilaTabla(
                                  posicion: i + 1,
                                  fila: f[i],
                                  total: _musculo == 'total',
                                ),
                            ],
                          ),
                        ),
            ),
          ],
        ),
      ),
    );
  }
}

class _FilaTabla extends StatelessWidget {
  const _FilaTabla({required this.posicion, required this.fila, required this.total});
  final int posicion;
  final _FilaTablaRanked fila;
  final bool total;

  @override
  Widget build(BuildContext context) {
    final int rango = total
        ? RangosRanked.rangoPorHonor(fila.xp / GrupoMuscular.values.length)
        : RangosRanked.rangoPorHonor(fila.xp);
    final Color medalla = posicion == 1
        ? TempleColors.dorado
        : posicion == 2
            ? const Color(0xFFC9CED8)
            : posicion == 3
                ? const Color(0xFFBF8A5E)
                : TempleColors.textoTenue;
    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Material(
        color: fila.esYo
            ? TempleColors.violeta.withValues(alpha: 0.12)
            : TempleColors.superficie.withValues(alpha: 0.9),
        borderRadius: BorderRadius.circular(TempleRadius.campo),
        child: InkWell(
          borderRadius: BorderRadius.circular(TempleRadius.campo),
          onTap: () => Navigator.of(context).push(MaterialPageRoute<void>(
            builder: (_) => PerfilClanScreen(id: fila.persona.id),
          )),
          child: Padding(
            padding: const EdgeInsets.fromLTRB(12, 10, 14, 10),
            child: Row(
              children: <Widget>[
                SizedBox(
                  width: 28,
                  child: Text('$posicion',
                      style: TextStyle(fontSize: 16, fontWeight: FontWeight.w700, color: medalla)),
                ),
                ClanAvatar(persona: fila.persona, size: 38),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: <Widget>[
                      Text(fila.esYo ? '${fila.persona.nombre} (tú)' : fila.persona.nombre,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                              fontSize: 13.5, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                      Text('${fila.xp.round()} de honor',
                          style: const TextStyle(fontSize: 11.5, color: TempleColors.textoSuave)),
                    ],
                  ),
                ),
                EmblemaRanked(rango: rango, size: 34),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

