/// Bloque de Ranked para el perfil (propio o público).
class TarjetaRankedPerfil extends StatefulWidget {
  const TarjetaRankedPerfil({
    super.key,
    required this.rangos,
    required this.total,
    required this.general,
    this.onTap,
