  @override
  State<TarjetaRankedPerfil> createState() => _TarjetaRankedPerfilState();
}

class _TarjetaRankedPerfilState extends State<TarjetaRankedPerfil> {
  bool _espalda = false;

  @override
  Widget build(BuildContext context) {
    final List<MapEntry<GrupoMuscular, int>> top = widget.rangos.entries
        .where((MapEntry<GrupoMuscular, int> e) => e.value >= 0)
        .toList()
      ..sort((MapEntry<GrupoMuscular, int> a, MapEntry<GrupoMuscular, int> b) => b.value.compareTo(a.value));

    return TempleCard(
      onTap: widget.onTap,
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          SizedBox(
            width: 104,
            child: Column(
              children: <Widget>[
                SiluetaRanked(
                  altura: 190,
                  espalda: _espalda,
                  rangos: widget.rangos,
                  animada: false,
                ),
                GestureDetector(
                  onTap: () => setState(() => _espalda = !_espalda),
                  child: Padding(
                    padding: const EdgeInsets.only(top: 4),
                    child: Text(_espalda ? 'Ver frente' : 'Ver espalda',
                        style: const TextStyle(fontSize: 10.5, color: TempleColors.violetaClaro)),
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: <Widget>[
                Row(
                  children: <Widget>[
                    EmblemaRanked(rango: widget.general, size: 40),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: <Widget>[
                          const Text('RANKED',
                              style: TextStyle(
                                  fontSize: 10, letterSpacing: 1.8, color: TempleColors.textoTenue)),
                          Text(RangosRanked.nombre(widget.general),
                              style: TextStyle(
                                  fontSize: 15,
                                  fontWeight: FontWeight.w700,
                                  color: RangosRanked.color(widget.general))),
                        ],
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 6),
                Text('${widget.total} de honor',
                    style: const TextStyle(fontSize: 11.5, color: TempleColors.textoSuave)),
                const SizedBox(height: 10),
                if (top.isEmpty)
                  const Text('Aún sin rangos.',
                      style: TextStyle(fontSize: 12, color: TempleColors.textoTenue))
                else
                  for (final MapEntry<GrupoMuscular, int> e in top.take(4))
                    Padding(
                      padding: const EdgeInsets.only(bottom: 6),
                      child: Row(
                        children: <Widget>[
                          EmblemaRanked(rango: e.value, size: 22),
                          const SizedBox(width: 8),
                          Expanded(
                            child: Text(e.key.etiqueta,
                                style: const TextStyle(fontSize: 12.5, color: TempleColors.texto)),
                          ),
                          Text(RangosRanked.nombre(e.value),
                              style: TextStyle(
                                  fontSize: 11.5,
                                  fontWeight: FontWeight.w600,
                                  color: RangosRanked.color(e.value))),
                        ],
                      ),
                    ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

/// La misma tarjeta con tus datos locales.
class TarjetaRankedPropia extends StatelessWidget {
  const TarjetaRankedPropia({super.key, required this.usuario});
  final String usuario;

  @override
  Widget build(BuildContext context) {
    final bool abierto = MotorRanked.desbloqueado(usuario);
    final EstadoRanked e = MotorRanked.de(usuario);
    void abrir() => Navigator.of(context).push(MaterialPageRoute<void>(
          builder: (_) => RankedScreen(usuario: usuario),
        ));
    if (!abierto) {
      return TempleCard(
        onTap: abrir,
        child: Row(
          children: <Widget>[
            const Icon(Icons.lock_outline_rounded, color: TempleColors.violetaClaro),
            const SizedBox(width: 12),
            Expanded(
              child: Text(
                'Ranked se abre en el nivel ${MotorRanked.nivelDesbloqueo}. Ya llevas '
                '${e.total.round()} de honor guardado.',
                style: const TextStyle(fontSize: 13, height: 1.4, color: TempleColors.texto),
              ),
            ),
          ],
        ),
      );
    }
    return TarjetaRankedPerfil(
      rangos: <GrupoMuscular, int>{
        for (final MusculoRanked m in e.musculos.values) m.grupo: m.rango,
      },
      total: e.total.round(),
      general: e.rangoCuerpo,
      onTap: abrir,
    );
  }
}

/// Honor que dio la sesión recién terminada.
class TarjetaHonorSesion extends StatelessWidget {
  const TarjetaHonorSesion({super.key, required this.usuario, required this.sesion});
  final String usuario;
  final Sesion sesion;

  @override
  Widget build(BuildContext context) {
    final Map<GrupoMuscular, double> h = MotorRanked.honorDe(usuario, sesion);
    if (h.isEmpty) return const SizedBox.shrink();
    final bool abierto = MotorRanked.desbloqueado(usuario);
    final EstadoRanked e = MotorRanked.de(usuario);
    final int pendientes = AlmacenRanked.instancia.pendientes(usuario).length;
    final List<MapEntry<GrupoMuscular, double>> l = h.entries.toList()
      ..sort((MapEntry<GrupoMuscular, double> a, MapEntry<GrupoMuscular, double> b) =>
          b.value.compareTo(a.value));

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: <Widget>[
        const EtiquetaSeccion('Honor de Ranked'),
        TempleCard(
          onTap: () => Navigator.of(context).push(MaterialPageRoute<void>(
            builder: (_) => RankedScreen(usuario: usuario),
          )),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              if (pendientes > 0)
                Padding(
                  padding: const EdgeInsets.only(bottom: 12),
                  child: Text(
                    pendientes == 1 ? '¡Un ascenso te espera en Ranked!' : '¡$pendientes ascensos te esperan en Ranked!',
                    style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w600, color: TempleColors.dorado),
                  ),
                )
              else if (!abierto)
                Padding(
                  padding: const EdgeInsets.only(bottom: 12),
                  child: Text(
                    'Ranked se abre en el nivel ${MotorRanked.nivelDesbloqueo}. Este honor ya queda guardado.',
                    style: const TextStyle(fontSize: 12.5, color: TempleColors.textoSuave),
                  ),
                ),
              for (final MapEntry<GrupoMuscular, double> x in l)
                Padding(
                  padding: const EdgeInsets.only(bottom: 10),
                  child: Row(
                    children: <Widget>[
                      EmblemaRanked(rango: e.de(x.key).rango, size: 24),
                      const SizedBox(width: 8),
                      SizedBox(
                        width: 86,
                        child: Text(x.key.etiqueta,
                            style: const TextStyle(fontSize: 12.5, color: TempleColors.textoSuave)),
                      ),
                      Expanded(
                        child: _BarraRanked(
                          valor: e.de(x.key).progreso,
                          color: e.de(x.key).rango < 0 ? TempleColors.violeta : e.de(x.key).color,
                          alto: 5,
                        ),
                      ),
                      const SizedBox(width: 10),
                      Text('+${x.value.round()}',
                          style: const TextStyle(fontSize: 12, color: TempleColors.violetaClaro)),
                    ],
                  ),
                ),
            ],
          ),
        ),
        const SizedBox(height: 22),
      ],
    );
  }
}

// ===========================================================================
// 38. LA NUBE DEL TEMPLO — guardado local, copia en la nube y modo sin internet
//
// Todo el progreso de una persona (sesiones, récords, honor, mon, viñeta,
// Tenshi, Casa, medidas…) se convierte en un solo documento JSON que vive en
// dos sitios:
//
//   1. En el dispositivo (SharedPreferences). Se escribe cada pocos segundos y
//      al salir de la app. Así nada se pierde aunque no haya internet.
//   2. En Supabase (tabla `progreso`, solo legible por su dueña). Se sube en
//      cuanto hay conexión.
//
// Si dos dispositivos guardaron a la vez, las sesiones de ambos se juntan
// (ninguna se pierde) y los récords y la XP se recalculan desde cero.
//
//   38.1  Utilidades de lectura
//   38.2  Exportar / importar todo el progreso
//   38.3  Fusión de dos copias
//   38.4  La nube: abrir, autoguardar, subir, resolver conflictos
//   38.5  Indicador del estado de la nube
// ===========================================================================

// ---------------------------------------------------------------------------
// 38.1 UTILIDADES
// ---------------------------------------------------------------------------

DateTime? _nFecha(Object? v) => v is String ? DateTime.tryParse(v) : null;
double _nDouble(Object? v, [double d = 0]) => v is num ? v.toDouble() : d;
int _nInt(Object? v, [int d = 0]) => v is num ? v.toInt() : d;
String? _nTexto(Object? v) => v is String ? v : null;

T? _nEnum<T extends Enum>(List<T> valores, Object? nombre) {
  for (final T v in valores) {
    if (v.name == nombre) return v;
  }
  return null;
}

Map<String, dynamic> _nMapa(Object? v) =>
    v is Map ? Map<String, dynamic>.from(v) : <String, dynamic>{};

List<Map<String, dynamic>> _nLista(Object? v) => v is List
    ? v.whereType<Map>().map((Map m) => Map<String, dynamic>.from(m)).toList()
    : <Map<String, dynamic>>[];

List<String> _nTextos(Object? v) =>
    v is List ? v.map((Object? e) => e.toString()).toList() : <String>[];

/// Convierte en Map<String, dynamic> puro (los fromMap antiguos lo exigen).
Map<String, dynamic> _nPuro(Map<String, dynamic> m) =>
    Map<String, dynamic>.from(convert.jsonDecode(convert.jsonEncode(m)) as Map);

// ---------------------------------------------------------------------------
// 38.2 EXPORTAR / IMPORTAR
// ---------------------------------------------------------------------------

class SerializadorTemplo {
  const SerializadorTemplo._();

  static const int version = 1;

  static Map<String, dynamic> exportar(String usuario) {
    final DatosUsuario d = AlmacenTemplo.instancia.de(usuario);
    final EstadoProgreso p = MotorProgresion.instancia.de(usuario);
    final IdentidadUsuario id = AlmacenIdentidad.instancia.de(usuario);
    final MonedaTemplo mon = MonedaTemplo.instancia;
    final BandejaTemplo bandeja = BandejaTemplo.instancia;
    final PreferenciasAvisos pref = bandeja.prefs(usuario);
    final CicloEntrenamiento? ciclo = AlmacenCiclos.instancia.de(usuario);
    final PerfilNutricion? nut = AlmacenNutricion.instancia.de(usuario);

    return <String, dynamic>{
      'version': version,
      'usuario': usuario,
      'guardado_en': DateTime.now().toUtc().toIso8601String(),
      'templo': <String, dynamic>{
        'ascenso': d.ascenso,
        'sesiones': d.sesiones.map((Sesion s) => s.toMap()).toList(),
        'en_curso': d.enCurso?.toMap(),
        'records': d.records.values.map((RecordPersonal r) => r.toMap()).toList(),
        'xp_grupos': d.xpPorGrupo.map(
            (GrupoMuscular g, double v) => MapEntry<String, double>(g.name, v)),
        'xp_general': d.xpGeneral,
        'diario': d.diario.values.map((RegistroDiario r) => r.toMap()).toList(),
      },
      'mon': <String, dynamic>{
        'saldo': mon.saldo(usuario),
        'historial': (mon._historial[usuario] ?? <MovimientoMon>[])
            .map((MovimientoMon m) => m.toMap())
            .toList(),
        'ultimo_cobro': mon._ultimoCobro[usuario],
      },
      'progreso': p.toMap(),
      'identidad': <String, dynamic>{
        ...id.toMap(),
        'foto': id.foto,
      },
      'bandeja': <String, dynamic>{
        'mensajes': (bandeja._mensajes[usuario] ?? <MensajeTemplo>[])
            .map((MensajeTemplo m) => m.toMap())
            .toList(),
        'prefs': <String, dynamic>{
          'entrenamiento': pref.entrenamiento,
          'habitos': pref.habitos,
          'logros': pref.logros,
          'cuerpo': pref.cuerpo,
          'templo': pref.templo,
          'silencio_desde': pref.silencioDesde,
          'silencio_hasta': pref.silencioHasta,
        },
      },
      'ciclo': ciclo == null ? null : _cicloAMapa(ciclo),
      'nutricion': nut == null
          ? null
          : <String, dynamic>{
              'ritmo': nut.ritmo.name,
              'tiempo': nut.tiempo.name,
              'restricciones': nut.restricciones.map((Restriccion r) => r.name).toList(),
              'dificultad': nut.dificultad.name,
              'peso_corporal': nut.pesoCorporal,
            },
      'recuperacion': (AlmacenRecuperacion.instancia._datos[usuario] ??
              <String, EstadoRecuperacion>{})
          .values
          .map((EstadoRecuperacion e) => <String, dynamic>{
                'fecha': e.fecha.toIso8601String(),
                'dolor': e.dolor,
                'estres': e.estres,
                'energia': e.energia,
              })
          .toList(),
      'casa': <String, dynamic>{
        'ultimo_peso_visto': AlmacenCasa.instancia._ultimoPesoVisto[usuario],
      },
      'habitante': AlmacenHabitante.instancia._elegidos[usuario]?.name,
      'tenshi': <String, dynamic>{
        'turnos': (AlmacenTenshi.instancia._turnos[usuario] ?? <TurnoTenshi>[])
            .map((TurnoTenshi t) => <String, dynamic>{
                  'id': t.id,
                  'autor': t.autor.name,
                  'texto': t.texto,
                  'creado': t.creadoEn.toIso8601String(),
                  'kokoro': t.kokoro,
                  'auxilio': t.auxilio,
                })
            .toList(),
        'recuerdos': (AlmacenTenshi.instancia._recuerdos[usuario] ?? <RecuerdoTenshi>[])
            .map((RecuerdoTenshi r) => <String, dynamic>{
                  'texto': r.texto,
                  'creado': r.creado.toIso8601String(),
                })
            .toList(),
      },
      'ranked': <String, dynamic>{
        'cobrados': (AlmacenRanked.instancia._cobrados[usuario] ?? <String>{}).toList(),
      },
      'guias': GuiaTemplo.instancia._vistas(usuario).toList(),
      'cuerpo': CuerpoTemplo.instancia.exportar(usuario),
      'meta': AlmacenMeta.instancia.exportar(usuario),
      'en_casa': AlmacenCasaEntreno.instancia.exportar(usuario),
      'anuncios': AlmacenAnuncios.instancia.exportar(usuario),
    };
  }

  /// Reemplaza todo lo que hay en memoria de esa persona por la copia.
  static void importar(String usuario, Map<String, dynamic> m) {
    void paso(String nombre, void Function() f) {
      try {
        f();
      } catch (e) {
        debugPrint('Nube: no se pudo leer «$nombre»: $e');
      }
    }

    paso('templo', () {
      final Map<String, dynamic> t = _nMapa(m['templo']);
      final DatosUsuario d = AlmacenTemplo.instancia.de(usuario);
      d.ascenso = _nMapa(t['ascenso']).map(
          (String k, dynamic v) => MapEntry<String, String>(k, v.toString()));
      d.sesiones
        ..clear()
        ..addAll(_nLista(t['sesiones']).map((Map<String, dynamic> s) => Sesion.fromMap(_nPuro(s))));
      final Object? enCurso = t['en_curso'];
      d.enCurso = enCurso is Map ? Sesion.fromMap(_nPuro(_nMapa(enCurso))) : null;
      d.records.clear();
      for (final Map<String, dynamic> r in _nLista(t['records'])) {
        final RecordPersonal rp = RecordPersonal.fromMap(_nPuro(r));
        d.records[rp.ejercicioId] = rp;
      }
      d.xpPorGrupo.clear();
      _nMapa(t['xp_grupos']).forEach((String k, dynamic v) {
        final GrupoMuscular? g = _nEnum(GrupoMuscular.values, k);
        if (g != null) d.xpPorGrupo[g] = _nDouble(v);
      });
      d.xpGeneral = _nDouble(t['xp_general']);
      d.diario.clear();
      for (final Map<String, dynamic> r in _nLista(t['diario'])) {
        final DateTime? f = _nFecha(r['fecha']);
        if (f == null) continue;
        final RegistroDiario reg = RegistroDiario(
          fecha: f,
          horasSueno: r['horas_sueno'] is num ? _nDouble(r['horas_sueno']) : null,
          vasosAgua: _nInt(r['vasos_agua']),
          animo: _nEnum(Sensacion.values, r['animo']),
        );
        d.diario[reg.clave] = reg;
      }
    });

    paso('mon', () {
      final Map<String, dynamic> x = _nMapa(m['mon']);
      final MonedaTemplo mon = MonedaTemplo.instancia;
      mon._saldos[usuario] = _nInt(x['saldo']);
      mon._historial[usuario] = <MovimientoMon>[
        for (final Map<String, dynamic> h in _nLista(x['historial']))
          MovimientoMon(
            fecha: _nFecha(h['fecha']) ?? DateTime.now(),
            cantidad: _nInt(h['cantidad']),
            motivo: _nTexto(h['motivo']) ?? '',
          ),
      ];
      final String? cobro = _nTexto(x['ultimo_cobro']);
      if (cobro == null) {
        mon._ultimoCobro.remove(usuario);
      } else {
        mon._ultimoCobro[usuario] = cobro;
      }
    });

    paso('progreso', () {
      final Map<String, dynamic> x = _nMapa(m['progreso']);
      final EstadoProgreso p = MotorProgresion.instancia.de(usuario);
      p.titulos
        ..clear()
        ..addAll(_nTextos(x['titulos']));
      p.tituloEquipado = _nTexto(x['titulo_equipado']);
      p.piezas
        ..clear()
        ..addAll(PiezasVineta.base)
        ..addAll(_nTextos(x['piezas']));
      final Map<CapaVineta, String> v = PiezasVineta.configInicial();
      _nMapa(x['vineta']).forEach((String k, dynamic pieza) {
        final CapaVineta? c = _nEnum(CapaVineta.values, k);
        if (c != null && pieza is String) v[c] = pieza;
      });
      p.vineta = v;
      p.clase = _nEnum(ClaseTemplo.values, x['clase']);
      p.misiones
        ..clear()
        ..addAll(_nTextos(x['misiones']));
      p.semanas
        ..clear()
        ..addAll(_nLista(x['semanas']).map((Map<String, dynamic> s) => SemanaArchivada(
              lunes: _nFecha(s['lunes']) ?? DateTime.now(),
              sesiones: _nInt(s['sesiones']),
              volumen: _nDouble(s['volumen']),
              minutos: _nInt(s['minutos']),
              grupos: _nTextos(s['grupos'])
                  .map((String n) => _nEnum(GrupoMuscular.values, n))
                  .whereType<GrupoMuscular>()
                  .toList(),
              objetivo: _nInt(s['objetivo'], 3),
              mejorDiaVolumen: _nDouble(s['mejor_dia']),
              records: _nInt(s['records']),
            )));
      p.ultimaSemanaCerrada = _nFecha(x['ultima_semana']);
    });

    paso('identidad', () {
      final Map<String, dynamic> x = _nMapa(m['identidad']);
      if (x.isEmpty) return;
      final IdentidadUsuario id = AlmacenIdentidad.instancia.de(usuario);
      id.nombreVisible = _nTexto(x['nombre_visible']);
      id.biografia = _nTexto(x['biografia']) ?? '';
      id.etiquetas
        ..clear()
        ..addAll(_nTextos(x['etiquetas']));
      id.paleta = _nInt(x['paleta']);
      id.simbolo = _nEnum(SimboloSello.values, x['simbolo']) ?? SimboloSello.kanji;
      id.marco = _nEnum(MarcoSello.values, x['marco']) ?? MarcoSello.simple;
      final Object? estilo = x['estilo'];
      id.estiloNombre = estilo is String ? estilo : null;
      id.foto = _nTexto(x['foto']);
      id.redes
        ..clear()
        ..addAll(RedesSociales.desde(x['redes']));
    });

    paso('bandeja', () {
      final Map<String, dynamic> x = _nMapa(m['bandeja']);
      final BandejaTemplo b = BandejaTemplo.instancia;
      b._mensajes[usuario] = <MensajeTemplo>[
        for (final Map<String, dynamic> e in _nLista(x['mensajes']))
          if (_nEnum(TipoMensaje.values, e['tipo']) != null)
            MensajeTemplo(
              id: _nTexto(e['id']) ?? '${DateTime.now().microsecondsSinceEpoch}',
              tipo: _nEnum(TipoMensaje.values, e['tipo'])!,
              categoria: _nEnum(CategoriaMensaje.values, e['categoria']) ?? CategoriaMensaje.templo,
              titulo: _nTexto(e['titulo']) ?? '',
              cuerpo: _nTexto(e['cuerpo']) ?? '',
              fecha: _nFecha(e['fecha']) ?? DateTime.now(),
              firma: _nTexto(e['firma']),
              dorado: e['dorado'] == true,
              leido: e['leido'] == true,
            ),
      ];
      final Map<String, dynamic> pr = _nMapa(x['prefs']);
      if (pr.isNotEmpty) {
        final PreferenciasAvisos p = b.prefs(usuario);
        p.entrenamiento = pr['entrenamiento'] != false;
        p.habitos = pr['habitos'] != false;
        p.logros = pr['logros'] != false;
        p.cuerpo = pr['cuerpo'] != false;
        p.templo = pr['templo'] != false;
        p.silencioDesde = _nInt(pr['silencio_desde'], 23);
        p.silencioHasta = _nInt(pr['silencio_hasta'], 7);
      }
    });

    paso('ciclo', () {
      final Object? c = m['ciclo'];
      if (c is Map) {
        AlmacenCiclos.instancia._ciclos[usuario] = _cicloDeMapa(_nMapa(c));
      } else {
        AlmacenCiclos.instancia._ciclos.remove(usuario);
      }
    });

    paso('nutricion', () {
      final Object? n = m['nutricion'];
      if (n is! Map) {
        AlmacenNutricion.instancia._perfiles.remove(usuario);
        return;
      }
      final Map<String, dynamic> x = _nMapa(n);
      AlmacenNutricion.instancia._perfiles[usuario] = PerfilNutricion(
        ritmo: _nEnum(RitmoComidas.values, x['ritmo']) ?? RitmoComidas.tres,
        tiempo: _nEnum(TiempoCocina.values, x['tiempo']) ?? TiempoCocina.normal,
        restricciones: _nTextos(x['restricciones'])
            .map((String r) => _nEnum(Restriccion.values, r))
            .whereType<Restriccion>()
            .toSet(),
        dificultad: _nEnum(Dificultad.values, x['dificultad']) ?? Dificultad.proteina,
        pesoCorporal: x['peso_corporal'] is num ? _nDouble(x['peso_corporal']) : null,
      );
    });

    paso('recuperacion', () {
      final Map<String, EstadoRecuperacion> r = <String, EstadoRecuperacion>{};
      for (final Map<String, dynamic> e in _nLista(m['recuperacion'])) {
        final DateTime? f = _nFecha(e['fecha']);
        if (f == null) continue;
        final EstadoRecuperacion x = EstadoRecuperacion(
          fecha: f,
          dolor: _nInt(e['dolor']),
          estres: _nInt(e['estres']),
          energia: _nInt(e['energia'], 2),
        );
        r[x.clave] = x;
      }
      AlmacenRecuperacion.instancia._datos[usuario] = r;
    });

    paso('casa', () {
      final Object? v = _nMapa(m['casa'])['ultimo_peso_visto'];
      if (v is num) {
        AlmacenCasa.instancia._ultimoPesoVisto[usuario] = v.toDouble();
      }
    });

    paso('habitante', () {
      final Habitante? h = _nEnum(Habitante.values, m['habitante']);
      if (h != null) AlmacenHabitante.instancia._elegidos[usuario] = h;
    });

    paso('tenshi', () {
      final Map<String, dynamic> x = _nMapa(m['tenshi']);
      AlmacenTenshi.instancia._turnos[usuario] = <TurnoTenshi>[
        for (final Map<String, dynamic> t in _nLista(x['turnos']))
          TurnoTenshi(
            id: _nTexto(t['id']) ?? AlmacenTenshi.nuevoId(),
            autor: _nEnum(AutorTurno.values, t['autor']) ?? AutorTurno.tenshi,
            texto: _nTexto(t['texto']) ?? '',
            creadoEn: _nFecha(t['creado']) ?? DateTime.now(),
            kokoro: t['kokoro'] == true,
            auxilio: t['auxilio'] == true,
          ),
      ];
      AlmacenTenshi.instancia._recuerdos[usuario] = <RecuerdoTenshi>[
        for (final Map<String, dynamic> r in _nLista(x['recuerdos']))
          RecuerdoTenshi(
            texto: _nTexto(r['texto']) ?? '',
            creado: _nFecha(r['creado']) ?? DateTime.now(),
          ),
      ];
    });

    paso('ranked', () {
      AlmacenRanked.instancia._cobrados[usuario] =
          _nTextos(_nMapa(m['ranked'])['cobrados']).toSet();
    });

    paso('guias', () {
      GuiaTemplo.instancia._vistas(usuario)
        ..clear()
        ..addAll(_nTextos(m['guias']));
    });

    paso('cuerpo', () => CuerpoTemplo.instancia.importar(usuario, _nMapa(m['cuerpo'])));
    paso('meta', () => AlmacenMeta.instancia.importar(usuario, m['meta']));
    paso('en_casa', () => AlmacenCasaEntreno.instancia.importar(usuario, m['en_casa']));
    paso('anuncios', () => AlmacenAnuncios.instancia.importar(usuario, m['anuncios']));

    if (m['recalcular'] == true) {
      paso('recalcular', () => recalcularDerivados(usuario));
    }
  }

  static Map<String, dynamic> _cicloAMapa(CicloEntrenamiento c) => <String, dynamic>{
        'creado': c.creado.toIso8601String(),
        'respuestas': <String, dynamic>{
          'prioridad': c.respuestas.prioridad?.name,
          'semanas': c.respuestas.semanas,
          'limitacion': c.respuestas.limitacion.name,
          'material': c.respuestas.material,
        },
        'semanas': <Map<String, dynamic>>[
          for (final SemanaCiclo s in c.semanas)
            <String, dynamic>{
              'numero': s.numero,
              'factor': s.factorCarga,
              'titulo': s.titulo,
              'nota': s.nota,
              'descarga': s.esDescarga,
              'dias': <Map<String, dynamic>>[
                for (final DiaCiclo d in s.dias)
                  <String, dynamic>{
                    'nombre': d.nombre,
                    'grupos': d.grupos.map((GrupoMuscular g) => g.name).toList(),
                    'ejercicios': <Map<String, dynamic>>[
                      for (final EjercicioPlan e in d.ejercicios)
                        <String, dynamic>{
                          'id': e.ejercicioId,
                          'series': e.series,
                          'reps': e.repsObjetivo,
                          'peso': e.pesoSugerido,
                        },
                    ],
                  },
              ],
            },
        ],
        'ajustes': <Map<String, dynamic>>[
          for (final AjusteCiclo a in c.ajustes)
            <String, dynamic>{
              'fecha': a.fecha.toIso8601String(),
              'titulo': a.titulo,
              'motivo': a.motivo,
            },
        ],
      };

  static CicloEntrenamiento _cicloDeMapa(Map<String, dynamic> m) {
    final Map<String, dynamic> r = _nMapa(m['respuestas']);
    final CicloEntrenamiento c = CicloEntrenamiento(
      creado: _nFecha(m['creado']) ?? DateTime.now(),
      respuestas: RespuestasCiclo(
        prioridad: _nEnum(GrupoMuscular.values, r['prioridad']),
        semanas: _nInt(r['semanas'], 4),
        limitacion: _nEnum(Limitacion.values, r['limitacion']) ?? Limitacion.ninguna,
        material: _nTexto(r['material']) ?? 'gimnasio',
      ),
      semanas: <SemanaCiclo>[
        for (final Map<String, dynamic> s in _nLista(m['semanas']))
          SemanaCiclo(
            numero: _nInt(s['numero'], 1),
            factorCarga: _nDouble(s['factor'], 1),
            titulo: _nTexto(s['titulo']) ?? '',
            nota: _nTexto(s['nota']) ?? '',
            esDescarga: s['descarga'] == true,
            dias: <DiaCiclo>[
              for (final Map<String, dynamic> d in _nLista(s['dias']))
                DiaCiclo(
                  nombre: _nTexto(d['nombre']) ?? '',
                  grupos: _nTextos(d['grupos'])
                      .map((String n) => _nEnum(GrupoMuscular.values, n))
                      .whereType<GrupoMuscular>()
                      .toList(),
                  ejercicios: <EjercicioPlan>[
                    for (final Map<String, dynamic> e in _nLista(d['ejercicios']))
                      EjercicioPlan(
                        ejercicioId: _nTexto(e['id']) ?? '',
                        series: _nInt(e['series'], 3),
                        repsObjetivo: _nInt(e['reps'], 10),
                        pesoSugerido: e['peso'] is num ? _nDouble(e['peso']) : null,
                      ),
                  ],
                ),
            ],
          ),
      ],
    );
    for (final Map<String, dynamic> a in _nLista(m['ajustes'])) {
      c.ajustes.add(AjusteCiclo(
        fecha: _nFecha(a['fecha']) ?? DateTime.now(),
        titulo: _nTexto(a['titulo']) ?? '',
        motivo: _nTexto(a['motivo']) ?? '',
      ));
    }
    return c;
  }

  /// Récords, XP por grupo y XP general rehechos a partir de las sesiones.
  /// Se usa después de juntar las sesiones de dos dispositivos.
  static void recalcularDerivados(String usuario) {
    final DatosUsuario d = AlmacenTemplo.instancia.de(usuario);
    d.records.clear();
    d.xpPorGrupo.clear();
    d.xpGeneral = 0;
    final List<Sesion> ses = d.completadas
      ..sort((Sesion a, Sesion b) => (a.fin ?? a.inicio).compareTo(b.fin ?? b.inicio));
    for (final Sesion s in ses) {
      final DateTime fecha = s.fin ?? s.inicio;
      final List<RecordRoto> rotos = <RecordRoto>[];
      for (final EjercicioSesion e in s.ejercicios) {
        if (e.seriesEfectivas.isEmpty) continue;
        final RecordPersonal? previo = d.records[e.ejercicioId];
        final double nuevo1RM = e.mejor1RM ?? 0;
        if (previo == null) {
          d.records[e.ejercicioId] = RecordPersonal(
            ejercicioId: e.ejercicioId,
            pesoMaximo: e.pesoMaximo,
            mejor1RM: nuevo1RM,
            mejorVolumenSesion: e.volumen,
            fecha: fecha,
          );
          continue;
        }
        if (e.pesoMaximo > previo.pesoMaximo) {
          rotos.add(RecordRoto(
            ejercicioId: e.ejercicioId,
            tipo: 'peso',
            anterior: previo.pesoMaximo,
            nuevo: e.pesoMaximo,
          ));
        }
        if (e.volumen > previo.mejorVolumenSesion) {
          rotos.add(RecordRoto(
            ejercicioId: e.ejercicioId,
            tipo: 'volumen',
            anterior: previo.mejorVolumenSesion,
            nuevo: e.volumen,
          ));
        }
        d.records[e.ejercicioId] = RecordPersonal(
          ejercicioId: e.ejercicioId,
          pesoMaximo: math.max(e.pesoMaximo, previo.pesoMaximo),
          mejor1RM: math.max(nuevo1RM, previo.mejor1RM),
          mejorVolumenSesion: math.max(e.volumen, previo.mejorVolumenSesion),
          fecha: fecha,
        );
      }
      ReglasXp.deSesion(s, records: rotos).forEach((GrupoMuscular g, double v) {
        d.xpPorGrupo[g] = (d.xpPorGrupo[g] ?? 0) + v;
        d.xpGeneral += v;
      });
    }
  }
}

// ---------------------------------------------------------------------------
// 38.3 FUSIÓN DE DOS COPIAS
//
// La copia guardada más tarde manda, pero lo que nunca se debe perder se
// junta: sesiones, registros diarios, piezas, títulos, misiones, ascensos
// cobrados, medidas y fotos de progreso.
// ---------------------------------------------------------------------------

Map<String, dynamic> fusionarCopias(Map<String, dynamic> a, Map<String, dynamic> b) {
  final String fa = _nTexto(a['guardado_en']) ?? '';
  final String fb = _nTexto(b['guardado_en']) ?? '';
  final bool ganaA = fa.compareTo(fb) >= 0;
  final Map<String, dynamic> base = _nPuro(ganaA ? a : b);
  final Map<String, dynamic> otra = _nPuro(ganaA ? b : a);

  List<Map<String, dynamic>> unirPor(
    Object? x,
    Object? y,
    String Function(Map<String, dynamic>) clave,
  ) {
    final Map<String, Map<String, dynamic>> r = <String, Map<String, dynamic>>{};
    for (final Map<String, dynamic> e in _nLista(y)) {
      r[clave(e)] = e;
    }
    for (final Map<String, dynamic> e in _nLista(x)) {
      r[clave(e)] = e; // la base gana
    }
    return r.values.toList();
  }

  List<String> unirTextos(Object? x, Object? y) =>
      <String>{..._nTextos(x), ..._nTextos(y)}.toList();

  final Map<String, dynamic> tb = _nMapa(base['templo']);
  final Map<String, dynamic> to = _nMapa(otra['templo']);
  // Una sesión completada gana a la misma sesión abandonada o a medias.
  final Map<String, Map<String, dynamic>> ses = <String, Map<String, dynamic>>{};
  for (final Map<String, dynamic> s in <Map<String, dynamic>>[
    ..._nLista(to['sesiones']),
    ..._nLista(tb['sesiones']),
  ]) {
    final String id = _nTexto(s['id']) ?? '';
    final Map<String, dynamic>? ya = ses[id];
    if (ya == null || ya['estado'] != 'completada' || s['estado'] == 'completada') {
      ses[id] = s;
    }
  }
  tb['sesiones'] = ses.values.toList();
  tb['diario'] = unirPor(tb['diario'], to['diario'], (Map<String, dynamic> e) => '${e['fecha']}'.split('T').first);
  base['templo'] = tb;

  final Map<String, dynamic> pb = _nMapa(base['progreso']);
  final Map<String, dynamic> po = _nMapa(otra['progreso']);
  pb['titulos'] = unirTextos(pb['titulos'], po['titulos']);
  pb['piezas'] = unirTextos(pb['piezas'], po['piezas']);
  pb['misiones'] = unirTextos(pb['misiones'], po['misiones']);
  base['progreso'] = pb;

  final Map<String, dynamic> rb = _nMapa(base['ranked']);
  rb['cobrados'] = unirTextos(rb['cobrados'], _nMapa(otra['ranked'])['cobrados']);
  base['ranked'] = rb;

  base['guias'] = unirTextos(base['guias'], otra['guias']);

  final Map<String, dynamic> cb = _nMapa(base['cuerpo']);
  final Map<String, dynamic> co = _nMapa(otra['cuerpo']);
  cb['medidas'] = unirPor(cb['medidas'], co['medidas'], (Map<String, dynamic> e) => '${e['id']}');
  cb['fotos'] = unirPor(cb['fotos'], co['fotos'], (Map<String, dynamic> e) => '${e['id']}');
  base['cuerpo'] = cb;

  // La meta: gana la que se editó más tarde, venga de donde venga.
  final Map<String, dynamic> mb = _nMapa(base['meta']);
  final Map<String, dynamic> mo = _nMapa(otra['meta']);
  if (mo.isNotEmpty && (mb.isEmpty || (_nTexto(mo['editada']) ?? '').compareTo(_nTexto(mb['editada']) ?? '') > 0)) {
    base['meta'] = mo;
  }

  base['recalcular'] = true;
  base['guardado_en'] = DateTime.now().toUtc().toIso8601String();
  return base;
}

// ---------------------------------------------------------------------------
// 38.4 LA NUBE
// ---------------------------------------------------------------------------

enum EstadoNube { apagada, guardandoLocal, subiendo, alDia, sinConexion }

class NubeTemplo extends ChangeNotifier with WidgetsBindingObserver {
  NubeTemplo._();
  static final NubeTemplo instancia = NubeTemplo._();

  static const String _clave = 'tos.progreso.';
  static const String _claveMeta = 'tos.meta.';
  static const String _clavePerfil = 'tos.perfil.';

  String? _uid;
  String? _usuario;
  int _revision = 0; // última revisión del servidor que conocemos
  bool _pendiente = false;
  int? _huella;
  bool _subiendo = false;
  bool _observando = false;
  Timer? _reloj;
  Timer? _espera;

  EstadoNube estado = EstadoNube.apagada;
  DateTime? ultimaSubida;
  DateTime? ultimoGuardadoLocal;

  bool get pendiente => _pendiente;
  String? get usuario => _usuario;

  // -- Perfil en caché (para entrar sin internet) --------------------------

  static Future<void> guardarPerfilCache(String uid, Map<String, dynamic> perfil) async {
    try {
      final SharedPreferences sp = await SharedPreferences.getInstance();
      await sp.setString('$_clavePerfil$uid', convert.jsonEncode(perfil));
    } catch (_) {}
  }

  static Future<Map<String, dynamic>?> perfilCache(String uid) async {
    try {
      final SharedPreferences sp = await SharedPreferences.getInstance();
      final String? t = sp.getString('$_clavePerfil$uid');
      if (t == null) return null;
      return Map<String, dynamic>.from(convert.jsonDecode(t) as Map);
    } catch (_) {
      return null;
    }
  }

  // -- Abrir ---------------------------------------------------------------

  /// Carga el progreso: primero el del dispositivo (instantáneo, sirve sin
  /// internet) y luego el de la nube si es más nuevo.
  Future<void> abrir({required String uid, required String usuario}) async {
    if (_uid == uid && _usuario == usuario) return;
    _uid = uid;
    _usuario = usuario;
    _revision = 0;
    _pendiente = false;
    estado = EstadoNube.guardandoLocal;

    Map<String, dynamic>? local;
    try {
      final SharedPreferences sp = await SharedPreferences.getInstance();
      final String? t = sp.getString('$_clave$uid');
      if (t != null) local = Map<String, dynamic>.from(convert.jsonDecode(t) as Map);
      final String? meta = sp.getString('$_claveMeta$uid');
      if (meta != null) {
        final Map<String, dynamic> mm = Map<String, dynamic>.from(convert.jsonDecode(meta) as Map);
        _revision = _nInt(mm['revision']);
        _pendiente = mm['pendiente'] == true;
        ultimaSubida = _nFecha(mm['subida']);
      }
    } catch (e) {
      debugPrint('Nube: copia local ilegible: $e');
    }
    if (local != null) SerializadorTemplo.importar(usuario, local);

    try {
      final Map<String, dynamic>? fila = await supa
          .from('progreso')
          .select('datos, revision')
          .eq('usuario', uid)
          .maybeSingle()
          .timeout(const Duration(seconds: 8));
      if (fila != null) {
        final int rev = _nInt(fila['revision']);
        final Map<String, dynamic> remota = _nMapa(fila['datos']);
        if (local == null) {
          SerializadorTemplo.importar(usuario, remota);
          _revision = rev;
          _pendiente = false;
        } else if (rev > _revision) {
          if (_pendiente) {
            SerializadorTemplo.importar(usuario, fusionarCopias(remota, local));
          } else {
            SerializadorTemplo.importar(usuario, remota);
            _pendiente = false;
          }
          _revision = rev;
        }
      } else {
        // Nunca subió nada: lo que haya en el dispositivo se sube ahora.
        _revision = 0;
        _pendiente = true;
      }
      estado = _pendiente ? EstadoNube.subiendo : EstadoNube.alDia;
    } catch (e) {
      estado = EstadoNube.sinConexion;
    }

    _huella = _huellaDe(usuario);
    if (!_observando) {
      WidgetsBinding.instance.addObserver(this);
      _observando = true;
    }
    _reloj?.cancel();
    _reloj = Timer.periodic(const Duration(seconds: 15), (_) => revisar());
    notifyListeners();
    await _guardarLocal(uid, usuario);
    if (_pendiente) unawaited(subir());
  }

  // -- Guardar -------------------------------------------------------------

  /// Avisa de un cambio importante: se guarda en dos segundos.
  void marcarCambio() {
    _espera?.cancel();
    _espera = Timer(const Duration(seconds: 2), revisar);
  }

  /// Guarda en el dispositivo si algo cambió y sube a la nube si hace falta.
  Future<void> revisar() async {
    final String? uid = _uid;
    final String? usuario = _usuario;
    if (uid == null || usuario == null) return;
    final int? huella = _huellaDe(usuario);
    if (huella == null) return;
    if (huella != _huella) {
      _huella = huella;
      _pendiente = true;
      await _guardarLocal(uid, usuario);
    }
    if (_pendiente) await subir();
  }

  /// Resumen numérico del progreso: si cambia, hay algo nuevo que guardar.
  int? _huellaDe(String usuario) {
    try {
      final Map<String, dynamic> datos = SerializadorTemplo.exportar(usuario)..remove('guardado_en');
      final String texto = convert.jsonEncode(datos);
      return Object.hash(texto.length, texto.hashCode);
    } catch (e) {
      debugPrint('Nube: no se pudo exportar: $e');
      return null;
    }
  }

  Future<void> _guardarLocal(String uid, String usuario) async {
    try {
      final SharedPreferences sp = await SharedPreferences.getInstance();
      await sp.setString('$_clave$uid', convert.jsonEncode(SerializadorTemplo.exportar(usuario)));
      await _guardarMeta(sp, uid);
      ultimoGuardadoLocal = DateTime.now();
    } catch (e) {
      debugPrint('Nube: no se pudo guardar en el dispositivo: $e');
    }
  }

  Future<void> _guardarMeta(SharedPreferences sp, String uid) => sp.setString(
        '$_claveMeta$uid',
        convert.jsonEncode(<String, dynamic>{
          'revision': _revision,
          'pendiente': _pendiente,
          'subida': ultimaSubida?.toIso8601String(),
        }),
      );

  /// Sube la copia. Si otro dispositivo guardó antes, junta ambas y reintenta.
  Future<bool> subir({bool forzar = false}) async {
    final String? uid = _uid;
    final String? usuario = _usuario;
    if (uid == null || usuario == null || _subiendo) return false;
    if (!_pendiente && !forzar) return true;
    _subiendo = true;
    estado = EstadoNube.subiendo;
    notifyListeners();
    try {
      for (int intento = 0; intento < 3; intento++) {
        final Map<String, dynamic> datos = SerializadorTemplo.exportar(usuario);
        final Map<String, dynamic> fila = <String, dynamic>{
          'datos': datos,
          'dispositivo': _dispositivo(),
        };
        if (_revision == 0) {
          try {
            final Map<String, dynamic> r = await supa
                .from('progreso')
                .insert(<String, dynamic>{'usuario': uid, ...fila})
                .select('revision')
                .single()
                .timeout(const Duration(seconds: 15));
            _revision = _nInt(r['revision'], 1);
            break;
          } on PostgrestException catch (e) {
            if (e.code != '23505') rethrow;
            await _fusionarConServidor(uid, usuario);
            continue;
          }
        }
        final List<Map<String, dynamic>> r = await supa
            .from('progreso')
            .update(fila)
            .eq('usuario', uid)
            .eq('revision', _revision)
            .select('revision')
            .timeout(const Duration(seconds: 15));
        if (r.isNotEmpty) {
          _revision = _nInt(r.first['revision'], _revision + 1);
          break;
        }
        // Alguien guardó antes: juntar y volver a intentar.
        await _fusionarConServidor(uid, usuario);
      }
      _pendiente = false;
      ultimaSubida = DateTime.now();
      estado = EstadoNube.alDia;
      final SharedPreferences sp = await SharedPreferences.getInstance();
      await sp.setString('$_clave$uid', convert.jsonEncode(SerializadorTemplo.exportar(usuario)));
      await _guardarMeta(sp, uid);
      // El perfil público también se pone al día.
      SesionTemplo.instancia.sincronizarIdentidad(usuario);
      return true;
    } catch (e) {
      debugPrint('Nube: sin conexión ($e)');
      estado = EstadoNube.sinConexion;
      return false;
    } finally {
      _subiendo = false;
      notifyListeners();
    }
  }

  Future<void> _fusionarConServidor(String uid, String usuario) async {
    final Map<String, dynamic>? fila = await supa
        .from('progreso')
        .select('datos, revision')
        .eq('usuario', uid)
        .maybeSingle()
        .timeout(const Duration(seconds: 10));
    if (fila == null) {
      _revision = 0;
      return;
    }
    final Map<String, dynamic> mezcla =
        fusionarCopias(_nMapa(fila['datos']), SerializadorTemplo.exportar(usuario));
    SerializadorTemplo.importar(usuario, mezcla);
    _revision = _nInt(fila['revision']);
  }

  static String _dispositivo() {
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return kIsWeb ? 'web (android)' : 'android';
      case TargetPlatform.iOS:
        return kIsWeb ? 'web (iphone)' : 'iphone';
      case TargetPlatform.windows:
        return kIsWeb ? 'web (windows)' : 'windows';
      case TargetPlatform.macOS:
        return kIsWeb ? 'web (mac)' : 'mac';
      default:
        return kIsWeb ? 'web' : 'otro';
    }
  }

  // -- Ciclo de vida -------------------------------------------------------

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.paused ||
        state == AppLifecycleState.inactive ||
        state == AppLifecycleState.detached) {
      revisar();
    }
    if (state == AppLifecycleState.resumed && _pendiente) subir();
  }

  /// Al cerrar sesión: guarda y sube lo último, y deja de vigilar.
  Future<void> cerrar() async {
    await revisar();
    _reloj?.cancel();
    _espera?.cancel();
    _uid = null;
    _usuario = null;
    _huella = null;
    estado = EstadoNube.apagada;
    notifyListeners();
  }

  /// Al eliminar la cuenta: no debe quedar nada en el dispositivo.
  Future<void> borrarTodo(String uid) async {
    _reloj?.cancel();
    _espera?.cancel();
    _uid = null;
    _usuario = null;
    try {
      final SharedPreferences sp = await SharedPreferences.getInstance();
      await sp.remove('$_clave$uid');
      await sp.remove('$_claveMeta$uid');
      await sp.remove('$_clavePerfil$uid');
    } catch (_) {}
    estado = EstadoNube.apagada;
    notifyListeners();
  }
}

// ---------------------------------------------------------------------------
// 38.5 INDICADOR
// ---------------------------------------------------------------------------

String _haceCuanto(DateTime? t) {
  if (t == null) return 'nunca';
  final Duration d = DateTime.now().difference(t);
  if (d.inSeconds < 60) return 'hace un momento';
  if (d.inMinutes < 60) return 'hace ${d.inMinutes} min';
  if (d.inHours < 24) return 'hace ${d.inHours} h';
  return 'hace ${d.inDays} d';
}

/// Nube pequeña: se toca para ver el estado y sincronizar.
class IndicadorNube extends StatelessWidget {
  const IndicadorNube({super.key, this.compacto = false});

  /// Versión diminuta para ir junto a un texto (la cabecera del Dojo).
  final bool compacto;

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: NubeTemplo.instancia,
      builder: (BuildContext context, _) {
        final NubeTemplo n = NubeTemplo.instancia;
        final IconData icono;
        final Color color;
        switch (n.estado) {
          case EstadoNube.alDia:
            icono = Icons.cloud_done_outlined;
            color = TempleColors.textoSuave;
          case EstadoNube.subiendo:
          case EstadoNube.guardandoLocal:
            icono = Icons.cloud_upload_outlined;
            color = TempleColors.violetaClaro;
          case EstadoNube.sinConexion:
            icono = Icons.cloud_off_outlined;
            color = TempleColors.alertaSuave;
          case EstadoNube.apagada:
            icono = Icons.cloud_outlined;
            color = TempleColors.textoTenue;
        }
        if (compacto) {
          return Semantics(
            button: true,
            label: 'Tu progreso en la nube',
            child: InkWell(
              onTap: () => mostrarEstadoNube(context),
              borderRadius: BorderRadius.circular(999),
              child: Padding(
                padding: const EdgeInsets.all(4),
                child: Icon(icono, size: 16, color: color),
              ),
            ),
          );
        }
        return IconButton(
          tooltip: 'Tu progreso en la nube',
          onPressed: () => mostrarEstadoNube(context),
          icon: Icon(icono, size: 21, color: color),
        );
      },
    );
  }
}

Future<void> mostrarEstadoNube(BuildContext context) {
  return showModalBottomSheet<void>(
    context: context,
    backgroundColor: TempleColors.grafito,
    shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
    builder: (BuildContext ctx) => ListenableBuilder(
      listenable: NubeTemplo.instancia,
      builder: (BuildContext ctx, _) {
        final NubeTemplo n = NubeTemplo.instancia;
        final String titulo;
        final String texto;
        switch (n.estado) {
          case EstadoNube.alDia:
            titulo = 'Todo guardado en la nube';
            texto = 'Tu progreso está a salvo. Si cambias de teléfono, entra con tu usuario y '
                'lo encontrarás todo.';
          case EstadoNube.subiendo:
          case EstadoNube.guardandoLocal:
            titulo = 'Guardando…';
            texto = 'Subiendo tus últimos cambios.';
          case EstadoNube.sinConexion:
            titulo = 'Sin conexión';
            texto = 'Puedes seguir entrenando: todo se guarda en este dispositivo y se subirá '
                'solo en cuanto vuelva internet.';
          case EstadoNube.apagada:
            titulo = 'La nube está dormida';
            texto = 'Entra con tu cuenta para guardar tu progreso.';
        }
        return SafeArea(
          top: false,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(22, 20, 22, 20),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: <Widget>[
                Text(titulo,
                    style: const TextStyle(
                        fontSize: 18, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                const SizedBox(height: 8),
                Text(texto, style: const TextStyle(fontSize: 13.5, height: 1.5, color: TempleColors.textoSuave)),
                const SizedBox(height: 14),
                Text('Última subida: ${_haceCuanto(n.ultimaSubida)}',
                    style: const TextStyle(fontSize: 12.5, color: TempleColors.texto)),
                Text('Guardado en el dispositivo: ${_haceCuanto(n.ultimoGuardadoLocal)}',
                    style: const TextStyle(fontSize: 12.5, color: TempleColors.texto)),
                const SizedBox(height: 18),
                SizedBox(
                  width: double.infinity,
                  child: OutlinedButton.icon(
                    onPressed: n.estado == EstadoNube.subiendo
                        ? null
                        : () async {
                            await n.revisar();
                            await n.subir(forzar: true);
                          },
                    icon: const Icon(Icons.sync_rounded, size: 18),
                    label: const Text('Sincronizar ahora'),
                    style: OutlinedButton.styleFrom(
                      foregroundColor: TempleColors.violetaClaro,
                      side: const BorderSide(color: TempleColors.bordeVivo),
                      padding: const EdgeInsets.symmetric(vertical: 13),
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(TempleRadius.campo)),
                    ),
                  ),
                ),
              ],
            ),
          ),
        );
      },
    ),
  );
}

// ===========================================================================
// 39. CUERPO Y PROGRESO — medidas y fotos privadas
//
// Las medidas viajan dentro de la copia de la nube (sección 38), así que se
// pueden registrar sin internet. Las fotos se suben a un almacén PRIVADO
// (bucket `progreso`): nadie más que su dueña puede verlas, ni siquiera desde
// el Clan.
// ===========================================================================

class MedidaCorporal {
  const MedidaCorporal({
    required this.id,
    required this.fecha,
    this.peso,
    this.grasa,
    this.cintura,
    this.pecho,
    this.brazo,
    this.muslo,
    this.cadera,
    this.cuello,
  });

  final String id;
  final DateTime fecha;
  final double? peso; // kg
  final double? grasa; // %
  final double? cintura; // cm
  final double? pecho;
  final double? brazo;
  final double? muslo;
  final double? cadera;
  final double? cuello;

  static const List<String> campos = <String>[
    'peso', 'grasa', 'cintura', 'pecho', 'brazo', 'muslo', 'cadera', 'cuello',
  ];

  static String etiqueta(String c) => const <String, String>{
        'peso': 'Peso',
        'grasa': 'Grasa corporal',
        'cintura': 'Cintura',
        'pecho': 'Pecho',
        'brazo': 'Brazo',
        'muslo': 'Muslo',
        'cadera': 'Cadera',
        'cuello': 'Cuello',
      }[c]!;

  static String unidad(String c) => c == 'peso' ? 'kg' : (c == 'grasa' ? '%' : 'cm');

  double? valor(String c) {
    switch (c) {
      case 'peso':
        return peso;
      case 'grasa':
        return grasa;
      case 'cintura':
        return cintura;
      case 'pecho':
        return pecho;
      case 'brazo':
        return brazo;
      case 'muslo':
        return muslo;
      case 'cadera':
        return cadera;
      case 'cuello':
        return cuello;
    }
    return null;
  }

  Map<String, dynamic> toMap() => <String, dynamic>{
        'id': id,
        'fecha': fecha.toIso8601String(),
        for (final String c in campos)
          if (valor(c) != null) c: valor(c),
      };

  static MedidaCorporal desdeMapa(Map<String, dynamic> m) {
    double? v(String c) => m[c] is num ? (m[c] as num).toDouble() : null;
    return MedidaCorporal(
      id: _nTexto(m['id']) ?? '${DateTime.now().microsecondsSinceEpoch}',
      fecha: _nFecha(m['fecha']) ?? DateTime.now(),
      peso: v('peso'),
      grasa: v('grasa'),
      cintura: v('cintura'),
      pecho: v('pecho'),
      brazo: v('brazo'),
      muslo: v('muslo'),
      cadera: v('cadera'),
      cuello: v('cuello'),
    );
  }
}

class FotoProgreso {
  const FotoProgreso({
    required this.id,
    required this.fecha,
    required this.ruta,
    required this.pose,
    this.peso,
  });

  final String id;
  final DateTime fecha;
  final String ruta; // dentro del bucket privado `progreso`
  final String pose; // frente | lado | espalda
  final double? peso;

  static const Map<String, String> poses = <String, String>{
    'frente': 'Frente',
    'lado': 'Perfil',
    'espalda': 'Espalda',
  };

  Map<String, dynamic> toMap() => <String, dynamic>{
        'id': id,
        'fecha': fecha.toIso8601String(),
        'ruta': ruta,
        'pose': pose,
        'peso': peso,
      };

  static FotoProgreso desdeMapa(Map<String, dynamic> m) => FotoProgreso(
        id: _nTexto(m['id']) ?? '',
        fecha: _nFecha(m['fecha']) ?? DateTime.now(),
        ruta: _nTexto(m['ruta']) ?? '',
        pose: _nTexto(m['pose']) ?? 'frente',
        peso: m['peso'] is num ? (m['peso'] as num).toDouble() : null,
      );
}

class CuerpoTemplo {
  CuerpoTemplo._();
  static final CuerpoTemplo instancia = CuerpoTemplo._();

  static const String bucket = 'progreso';

  final Map<String, List<MedidaCorporal>> _medidas = <String, List<MedidaCorporal>>{};
  final Map<String, List<FotoProgreso>> _fotos = <String, List<FotoProgreso>>{};
  final Map<String, MapEntry<String, DateTime>> _urls = <String, MapEntry<String, DateTime>>{};

  List<MedidaCorporal> medidas(String u) => List<MedidaCorporal>.from(
      _medidas[u] ?? <MedidaCorporal>[])
    ..sort((MedidaCorporal a, MedidaCorporal b) => a.fecha.compareTo(b.fecha));

  List<FotoProgreso> fotos(String u) => List<FotoProgreso>.from(_fotos[u] ?? <FotoProgreso>[])
    ..sort((FotoProgreso a, FotoProgreso b) => b.fecha.compareTo(a.fecha));

  double? ultimoPeso(String u) {
    for (final MedidaCorporal m in medidas(u).reversed) {
      if (m.peso != null) return m.peso;
    }
    return null;
  }

  void agregarMedida(String u, MedidaCorporal m) {
    _medidas.putIfAbsent(u, () => <MedidaCorporal>[]).add(m);
    CargaCorporal.olvidar();
    NubeTemplo.instancia.marcarCambio();
  }

  void borrarMedida(String u, String id) {
    _medidas[u]?.removeWhere((MedidaCorporal m) => m.id == id);
    NubeTemplo.instancia.marcarCambio();
  }

  Future<FotoProgreso> subirFoto(String u, XFile archivo, String pose) async {
    final String? yo = SesionTemplo.instancia.uid;
    if (yo == null) throw const AuthFailure('Tu sesión se cerró. Vuelve a entrar.');
    final Uint8List bytes = await archivo.readAsBytes();
    if (bytes.length > 10 * 1024 * 1024) {
      throw const AuthFailure('La foto pesa más de 10 MB.');
    }
    final String id = uuidClan();
    final String ruta = '$yo/$id.jpg';
    try {
      await supa.storage.from(bucket).uploadBinary(
            ruta,
            bytes,
            fileOptions: const FileOptions(contentType: 'image/jpeg', upsert: false),
          );
    } catch (e) {
      throw const AuthFailure('Para subir fotos necesitas conexión. Tus medidas sí se guardan sin internet.');
    }
    final FotoProgreso f = FotoProgreso(
      id: id,
      fecha: DateTime.now(),
      ruta: ruta,
      pose: pose,
      peso: ultimoPeso(u),
    );
    _fotos.putIfAbsent(u, () => <FotoProgreso>[]).add(f);
    NubeTemplo.instancia.marcarCambio();
    return f;
  }

  Future<void> borrarFoto(String u, FotoProgreso f) async {
    _fotos[u]?.removeWhere((FotoProgreso x) => x.id == f.id);
    NubeTemplo.instancia.marcarCambio();
    try {
      await supa.storage.from(bucket).remove(<String>[f.ruta]);
    } catch (_) {}
  }

  Future<String?> url(String ruta) async {
    final MapEntry<String, DateTime>? e = _urls[ruta];
    if (e != null && DateTime.now().isBefore(e.value)) return e.key;
    try {
      final String u = await supa.storage.from(bucket).createSignedUrl(ruta, 3600);
      _urls[ruta] = MapEntry<String, DateTime>(u, DateTime.now().add(const Duration(minutes: 55)));
      return u;
    } catch (_) {
      return null;
    }
  }

  Map<String, dynamic> exportar(String u) => <String, dynamic>{
        'medidas': (_medidas[u] ?? <MedidaCorporal>[]).map((MedidaCorporal m) => m.toMap()).toList(),
        'fotos': (_fotos[u] ?? <FotoProgreso>[]).map((FotoProgreso f) => f.toMap()).toList(),
      };

  void importar(String u, Map<String, dynamic> m) {
    _medidas[u] = _nLista(m['medidas']).map(MedidaCorporal.desdeMapa).toList();
    _fotos[u] = _nLista(m['fotos'])
        .map(FotoProgreso.desdeMapa)
        .where((FotoProgreso f) => f.ruta.isNotEmpty)
        .toList();
  }
}

/// Imagen del almacén privado de progreso.
class ImagenPrivada extends StatefulWidget {
  const ImagenPrivada({super.key, required this.ruta, this.fit = BoxFit.cover});
  final String ruta;
  final BoxFit fit;

  @override
  State<ImagenPrivada> createState() => _ImagenPrivadaState();
}

class _ImagenPrivadaState extends State<ImagenPrivada> {
  String? _url;
  bool _fallo = false;

  @override
  void initState() {
    super.initState();
    CuerpoTemplo.instancia.url(widget.ruta).then((String? u) {
      if (mounted) {
        setState(() {
          _url = u;
          _fallo = u == null;
        });
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    if (_fallo) {
      return Container(
        color: TempleColors.superficie,
        alignment: Alignment.center,
        child: const Icon(Icons.cloud_off_outlined, color: TempleColors.textoTenue),
      );
    }
    if (_url == null) return const _MedioCargando();
    return Image.network(
      _url!,
      fit: widget.fit,
      gaplessPlayback: true,
      errorBuilder: (BuildContext c, Object e, StackTrace? s) => const _MedioRoto(),
    );
  }
}

