class CuerpoScreen extends StatefulWidget {
  const CuerpoScreen({super.key, required this.usuario, this.pestanaInicial = 0});
  final String usuario;
  final int pestanaInicial;

  @override
  State<CuerpoScreen> createState() => _CuerpoScreenState();
}

class _CuerpoScreenState extends State<CuerpoScreen> {
  late int _pestana = widget.pestanaInicial;
  String _campo = 'peso';
  bool _subiendo = false;

  CuerpoTemplo get _c => CuerpoTemplo.instancia;

  Future<void> _registrar() async {
    final MedidaCorporal? m = await showModalBottomSheet<MedidaCorporal>(
      context: context,
      isScrollControlled: true,
      backgroundColor: TempleColors.grafito,
      shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
      builder: (_) => _HojaMedidas(
          anterior: _c.medidas(widget.usuario).isEmpty ? null : _c.medidas(widget.usuario).last),
    );
    if (m == null) return;
    _c.agregarMedida(widget.usuario, m);
    HapticFeedback.mediumImpact();
    if (mounted) setState(() {});
  }

  Future<void> _foto(ImageSource fuente) async {
    if (!LimitesPase.pase) {
      final DateTime ahora = DateTime.now();
      final int esteMes = _c
          .fotos(widget.usuario)
          .where((FotoProgreso f) => f.fecha.year == ahora.year && f.fecha.month == ahora.month)
          .length;
      final AlmacenAnuncios an = AlmacenAnuncios.instancia;
      if (esteMes >= LimitesPase.fotosMes + an.fotosExtra(widget.usuario)) {
        Future<void> muro() => mostrarMuroPase(
              context,
              titulo: 'Ya tienes tus fotos del mes',
              texto: 'Gratis guardas ${LimitesPase.fotosMes} fotos de progreso cada mes. Con el Pase, las que quieras, '
                  'y puedes verlas en fundido o como línea de tiempo.',
              ventajas: const <String>[
                'Fotos de progreso sin límite',
                'Comparar en fundido, no solo con cortina',
                'Tu cambio como línea de tiempo',
              ],
              icono: Icons.photo_camera_outlined,
            );
        if (!MotorAnuncios.instancia.ofrecible || !an.puedeFotoExtra(widget.usuario)) {
          await muro();
          return;
        }
        final int quedan = AlmacenAnuncios.fotosExtraMes - an.fotosExtra(widget.usuario);
        final bool visto = await ofrecerAnuncioOPase(
          context,
          titulo: 'Ya tienes tus ${LimitesPase.fotosMes} fotos del mes',
          texto: 'Puedes sumar una foto más viendo un anuncio, o guardar las que quieras con el Pase.',
          recompensa: 'Una foto más este mes',
          quedan: 'Te ${quedan == 1 ? 'queda 1 foto extra' : 'quedan $quedan fotos extra'} este mes',
          abrirMuro: muro,
        );
        if (!visto || !mounted) return;
        an.sumarFoto(widget.usuario);
      }
    }
    final String? pose = await showModalBottomSheet<String>(
      context: context,
      backgroundColor: TempleColors.grafito,
      shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
      builder: (BuildContext ctx) => SafeArea(
        top: false,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(16, 18, 16, 12),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: <Widget>[
              const Text('¿Qué pose es?',
                  style: TextStyle(fontSize: 17, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
              const SizedBox(height: 4),
              const Text('Repite siempre la misma pose, luz y distancia: así la comparación es honesta.',
                  style: TextStyle(fontSize: 12.5, height: 1.4, color: TempleColors.textoSuave)),
              const SizedBox(height: 12),
              for (final MapEntry<String, String> p in FotoProgreso.poses.entries)
                ListTile(
                  leading: const Icon(Icons.accessibility_new_rounded, color: TempleColors.violetaClaro),
                  title: Text(p.value, style: const TextStyle(color: TempleColors.blancoLuna)),
                  onTap: () => Navigator.of(ctx).pop(p.key),
                ),
            ],
          ),
        ),
      ),
    );
    if (pose == null || !mounted) return;
    final XFile? f = await ImagePicker().pickImage(
      source: fuente,
      maxWidth: 1400,
      maxHeight: 1400,
      imageQuality: 82,
    );
    if (f == null || !mounted) return;
    setState(() => _subiendo = true);
    try {
      await _c.subirFoto(widget.usuario, f, pose);
      if (mounted) avisoClan(context, 'Foto guardada. Solo tú puedes verla.');
    } catch (e) {
      if (mounted) avisoClan(context, SesionTemplo.mensajeDe(e), error: true);
    } finally {
      if (mounted) setState(() => _subiendo = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: Column(
          children: <Widget>[
            const BarraClan(titulo: 'Cuerpo y progreso', subtitulo: 'Privado: solo tú lo ves'),
            Padding(
              padding: const EdgeInsets.fromLTRB(TempleSpace.borde, 0, TempleSpace.borde, 8),
              child: _PestanasClan(
                indice: _pestana,
                opciones: const <String>['Medidas', 'Fotos'],
                onCambio: (int i) => setState(() => _pestana = i),
              ),
            ),
            if (_subiendo)
              const LinearProgressIndicator(
                minHeight: 2,
                backgroundColor: Colors.transparent,
                valueColor: AlwaysStoppedAnimation<Color>(TempleColors.violeta),
              ),
            Expanded(child: _pestana == 0 ? _medidas() : _fotos()),
          ],
        ),
      ),
    );
  }

