String _num(double v) => v == v.roundToDouble() ? v.round().toString() : v.toStringAsFixed(1);

class _Delta extends StatelessWidget {
  const _Delta({required this.valor, required this.campo});
  final double valor;
  final String campo;

  @override
  Widget build(BuildContext context) {
    final bool sube = valor > 0;
    final Color c = valor == 0 ? TempleColors.textoSuave : TempleColors.violetaClaro;
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
      decoration: BoxDecoration(
        color: c.withValues(alpha: 0.12),
        borderRadius: BorderRadius.circular(TempleRadius.pastilla),
      ),
      child: Text('${sube ? '+' : ''}${_num(valor)} ${MedidaCorporal.unidad(campo)}',
          style: TextStyle(fontSize: 12.5, fontWeight: FontWeight.w600, color: c)),
    );
  }
}

class _LineaPainter extends CustomPainter {
  const _LineaPainter({required this.valores});
  final List<double> valores;

  @override
  void paint(Canvas canvas, Size size) {
    if (valores.isEmpty) return;
    final double mn = valores.reduce(math.min);
    final double mx = valores.reduce(math.max);
    final double rango = (mx - mn).abs() < 0.001 ? 1 : mx - mn;
    final Paint guia = Paint()
      ..color = TempleColors.borde
      ..strokeWidth = 1;
    for (int i = 0; i < 3; i++) {
      final double y = size.height * (0.1 + 0.4 * i);
      canvas.drawLine(Offset(0, y), Offset(size.width, y), guia);
    }
    Offset p(int i) => Offset(
          valores.length == 1 ? size.width / 2 : size.width * i / (valores.length - 1),
          size.height * 0.9 - (valores[i] - mn) / rango * size.height * 0.8,
        );
    final Path linea = Path()..moveTo(p(0).dx, p(0).dy);
    for (int i = 1; i < valores.length; i++) {
      final Offset a = p(i - 1);
      final Offset b = p(i);
      linea.cubicTo((a.dx + b.dx) / 2, a.dy, (a.dx + b.dx) / 2, b.dy, b.dx, b.dy);
    }
    final Path area = Path.from(linea)
      ..lineTo(p(valores.length - 1).dx, size.height)
      ..lineTo(p(0).dx, size.height)
      ..close();
    canvas.drawPath(
      area,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[TempleColors.violeta.withValues(alpha: 0.3), TempleColors.violeta.withValues(alpha: 0)],
        ).createShader(Offset.zero & size),
    );
    canvas.drawPath(
      linea,
      Paint()
        ..color = TempleColors.violetaClaro
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.4
        ..strokeCap = StrokeCap.round,
    );
    for (int i = 0; i < valores.length; i++) {
      canvas.drawCircle(p(i), i == valores.length - 1 ? 4.5 : 2.5, Paint()..color = TempleColors.blancoLuna);
    }
  }

  @override
  bool shouldRepaint(_LineaPainter old) => old.valores != valores;
}

