class _HojaMedidasState extends State<_HojaMedidas> {
  final Map<String, TextEditingController> _c = <String, TextEditingController>{
    for (final String c in MedidaCorporal.campos) c: TextEditingController(),
  };

  @override
  void dispose() {
    for (final TextEditingController t in _c.values) {
      t.dispose();
    }
    super.dispose();
  }

  double? _v(String c) => double.tryParse(_c[c]!.text.replaceAll(',', '.').trim());

  void _guardar() {
    final bool alguno = MedidaCorporal.campos.any((String c) => _v(c) != null);
    if (!alguno) {
      Navigator.of(context).pop();
      return;
    }
    Navigator.of(context).pop(MedidaCorporal(
      id: uuidClan(),
      fecha: DateTime.now(),
      peso: _v('peso'),
      grasa: _v('grasa'),
      cintura: _v('cintura'),
      pecho: _v('pecho'),
      brazo: _v('brazo'),
      muslo: _v('muslo'),
      cadera: _v('cadera'),
      cuello: _v('cuello'),
    ));
