/// Antes y después con una cortina que se arrastra.
class CompararFotosScreen extends StatefulWidget {
  const CompararFotosScreen({super.key, required this.fotos});
  final List<FotoProgreso> fotos; // más reciente primero

  @override
  State<CompararFotosScreen> createState() => _CompararFotosScreenState();
}

class _CompararFotosScreenState extends State<CompararFotosScreen>
    with TickerDecorativo {
  @override
  bool get animarEnWeb => true;
  late FotoProgreso _antes = widget.fotos.last;
  late FotoProgreso _despues = widget.fotos.first;
  double _corte = 0.5;

  /// 0 = cortina (gratis), 1 = fundido, 2 = línea de tiempo (del Pase).
  int _modo = 0;
  late final AnimationController _linea = AnimationController(vsync: this);

  /// Las fotos de la misma pose que «después», de la más vieja a la nueva.
  List<FotoProgreso> get _serie => widget.fotos.where((FotoProgreso f) => f.pose == _despues.pose).toList()
    ..sort((FotoProgreso a, FotoProgreso b) => a.fecha.compareTo(b.fecha));

  @override
  void dispose() {
    _linea.dispose();
    super.dispose();
  }

  void _cambiarModo(int m) {
    if (m != 0 && !LimitesPase.pase) {
      mostrarMuroPase(
        context,
        titulo: m == 1 ? 'Comparar en fundido' : 'Tu cambio en línea de tiempo',
        texto: m == 1
            ? 'Una foto se funde con la otra y ves exactamente qué cambió. Es parte del Pase.'
            : 'Todas tus fotos de la misma pose, una tras otra, como un pequeño video de tu cambio. Es parte del Pase.',
        icono: Icons.compare_rounded,
      );
      return;
    }
    HapticFeedback.selectionClick();
    setState(() => _modo = m);
    if (m == 2) {
      final int n = math.max(1, _serie.length);
      _linea
        ..duration = Duration(milliseconds: 900 * n)
        ..repeat();
    } else {
      _linea.stop();
    }
  }

  Future<void> _elegir(bool antes) async {
    final FotoProgreso? f = await showModalBottomSheet<FotoProgreso>(
      context: context,
      backgroundColor: TempleColors.grafito,
      isScrollControlled: true,
      builder: (BuildContext ctx) => SafeArea(
        child: SizedBox(
          height: MediaQuery.sizeOf(ctx).height * 0.6,
          child: GridView.count(
            crossAxisCount: 3,
            padding: const EdgeInsets.all(14),
            mainAxisSpacing: 8,
            crossAxisSpacing: 8,
            childAspectRatio: 0.72,
            children: <Widget>[
              for (final FotoProgreso x in widget.fotos)
                GestureDetector(
                  onTap: () => Navigator.of(ctx).pop(x),
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(TempleRadius.chip),
                    child: Stack(
                      fit: StackFit.expand,
                      children: <Widget>[
                        ImagenPrivada(ruta: x.ruta),
                        Positioned(
                          left: 6,
                          bottom: 5,
                          child: Text('${x.fecha.day}/${x.fecha.month}/${x.fecha.year % 100}',
                              style: const TextStyle(fontSize: 11, color: Colors.white)),
                        ),
                      ],
                    ),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
    if (f == null) return;
    setState(() {
      if (antes) {
        _antes = f;
      } else {
        _despues = f;
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    final int dias = _despues.fecha.difference(_antes.fecha).inDays.abs();
    return Scaffold(
      backgroundColor: Colors.black,
      body: Column(
        children: <Widget>[
          BarraClan(titulo: 'Antes y después', subtitulo: '$dias días de diferencia'),
          Expanded(
            child: _modo == 2
                ? AnimatedBuilder(
                    animation: _linea,
                    builder: (BuildContext c, _) {
                      final List<FotoProgreso> serie = _serie;
                      if (serie.isEmpty) return const SizedBox.shrink();
                      final int i = math.min(serie.length - 1, math.max(0, (_linea.value * serie.length).floor()));
                      final FotoProgreso f = serie[i];
                      return Stack(
                        fit: StackFit.expand,
                        children: <Widget>[
                          AnimatedSwitcher(
                            duration: const Duration(milliseconds: 380),
                            child: ImagenPrivada(key: ValueKey<String>('l${f.id}'), ruta: f.ruta, fit: BoxFit.contain),
                          ),
                          Positioned(
                            left: 0,
                            right: 0,
                            bottom: 12,
                            child: Center(
                              child: Container(
                                padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                                decoration: BoxDecoration(
                                  color: Colors.black.withValues(alpha: 0.6),
                                  borderRadius: BorderRadius.circular(999),
                                ),
                                child: Text('${f.fecha.day}/${f.fecha.month}/${f.fecha.year} · ${i + 1} de ${serie.length}',
                                    style: const TextStyle(fontSize: 12.5, color: Colors.white)),
                              ),
                            ),
                          ),
                        ],
                      );
                    },
                  )
                : _modo == 1
                    ? LayoutBuilder(
                        builder: (BuildContext c, BoxConstraints bc) => GestureDetector(
                          onHorizontalDragUpdate: (DragUpdateDetails d) =>
                              setState(() => _corte = (d.localPosition.dx / bc.maxWidth).clamp(0.0, 1.0)),
                          child: Stack(
                            fit: StackFit.expand,
                            children: <Widget>[
                              ImagenPrivada(key: ValueKey<String>('a${_antes.id}'), ruta: _antes.ruta, fit: BoxFit.contain),
                              Opacity(
                                opacity: _corte,
                                child: ImagenPrivada(
                                    key: ValueKey<String>('d${_despues.id}'), ruta: _despues.ruta, fit: BoxFit.contain),
                              ),
                              Positioned(
                                left: 24,
                                right: 24,
                                bottom: 14,
                                child: SliderTheme(
                                  data: SliderTheme.of(context).copyWith(
                                    activeTrackColor: const Color(0xFFE8B65A),
                                    thumbColor: const Color(0xFFF2D493),
                                    inactiveTrackColor: Colors.white24,
                                  ),
                                  child: Slider(value: _corte, onChanged: (double v) => setState(() => _corte = v)),
                                ),
                              ),
                            ],
                          ),
                        ),
                      )
                    : LayoutBuilder(
              builder: (BuildContext c, BoxConstraints bc) => GestureDetector(
                onHorizontalDragUpdate: (DragUpdateDetails d) =>
                    setState(() => _corte = (d.localPosition.dx / bc.maxWidth).clamp(0.02, 0.98)),
                onTapDown: (TapDownDetails d) =>
                    setState(() => _corte = (d.localPosition.dx / bc.maxWidth).clamp(0.02, 0.98)),
                child: Stack(
                  fit: StackFit.expand,
                  children: <Widget>[
                    ImagenPrivada(key: ValueKey<String>('d${_despues.id}'), ruta: _despues.ruta, fit: BoxFit.contain),
                    ClipRect(
                      clipper: _CorteIzquierdo(_corte),
                      child: ImagenPrivada(key: ValueKey<String>('a${_antes.id}'), ruta: _antes.ruta, fit: BoxFit.contain),
                    ),
                    Positioned(
                      left: bc.maxWidth * _corte - 1,
                      top: 0,
                      bottom: 0,
                      child: Container(width: 2, color: Colors.white),
                    ),
                    Positioned(
                      left: bc.maxWidth * _corte - 18,
                      top: bc.maxHeight / 2 - 18,
                      child: Container(
                        width: 36,
                        height: 36,
                        decoration: const BoxDecoration(shape: BoxShape.circle, color: Colors.white),
                        child: const Icon(Icons.compare_arrows_rounded, color: Colors.black),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 10, 16, 0),
            child: Wrap(
              runSpacing: 6,
              children: <Widget>[
                for (final (int, String) m in const <(int, String)>[(0, 'Cortina'), (1, 'Fundido'), (2, 'Línea de tiempo')])
                  Padding(
                    padding: const EdgeInsets.only(right: 8),
                    child: ChoiceChip(
                      label: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: <Widget>[
                          Text(m.$2, style: const TextStyle(fontSize: 12)),
                          if (m.$1 != 0 && !LimitesPase.pase) ...<Widget>[
                            const SizedBox(width: 4),
                            const Icon(Icons.lock_outline_rounded, size: 12, color: Color(0xFFE8B65A)),
                          ],
                        ],
                      ),
                      selected: _modo == m.$1,
                      onSelected: (_) => _cambiarModo(m.$1),
                      selectedColor: TempleColors.violeta.withValues(alpha: 0.3),
                      backgroundColor: TempleColors.superficie,
                      labelStyle: TextStyle(color: _modo == m.$1 ? TempleColors.blancoLuna : TempleColors.textoSuave),
                      side: BorderSide(color: _modo == m.$1 ? TempleColors.violeta : TempleColors.borde),
                      showCheckmark: false,
                    ),
                  ),
              ],
            ),
          ),
          SafeArea(
            top: false,
            child: Padding(
              padding: const EdgeInsets.fromLTRB(16, 10, 16, 12),
              child: Row(
                children: <Widget>[
                  Expanded(
                    child: _BotonPerfil(
                      texto: 'Antes · ${_antes.fecha.day}/${_antes.fecha.month}',
                      principal: false,
                      onTap: () => _elegir(true),
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: _BotonPerfil(
                      texto: 'Después · ${_despues.fecha.day}/${_despues.fecha.month}',
                      principal: false,
                      onTap: () => _elegir(false),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _CorteIzquierdo extends CustomClipper<Rect> {
  const _CorteIzquierdo(this.corte);
  final double corte;

  @override
  Rect getClip(Size size) => Rect.fromLTWH(0, 0, size.width * corte, size.height);

  @override
  bool shouldReclip(_CorteIzquierdo old) => old.corte != corte;
}

// ===========================================================================
// 40. EL MAESTRO DE TÉCNICA — avatar animado que demuestra cada ejercicio
//
// Un guerrero vectorial con hachimaki hace el movimiento en bucle: baja
// controlado, sube con fuerza. La zona que trabaja se ilumina al contraer.
// No hay vídeos ni imágenes: todo es cinemática dibujada en CustomPainter,
// así pesa nada y se ve igual en cualquier pantalla.
//
//   40.1  Patrones de movimiento y poses clave
//   40.2  Guía escrita de cada ejercicio
//   40.3  El avatar (pintor y widget)
//   40.4  Ficha de técnica y biblioteca de ejercicios
// ===========================================================================

// ---------------------------------------------------------------------------
// 40.1 PATRONES Y POSES
// ---------------------------------------------------------------------------

enum PatronMovimiento {
  sentadilla,
  goblet,
  pesoMuerto,
  rumano,
  pressBanca,
  pressInclinado,
  pressMilitar,
  remo,
  remoSentado,
  jalon,
  dominada,
  fondos,
  flexion,
  curl,
  extensionPolea,
  extensionSobreCabeza,
  pressFrances,
  curlMuneca,
  prensa,
  zancada,
  curlFemoral,
  talones,
  plancha,
  elevacionPiernas,
  rueda,
  puenteGluteo,
  crunch,
  // En casa (sección 46)
  flexionRodillas,
  flexionInclinada,
  flexionDeclinada,
  pica,
  fondosSilla,
  remoInvertido,
  superman,
  bulgara,
  sentadillaPared,
  subida,
  sentadillaSalto,
  escaladores,
  tijeras,
  marcha,
  saltitos,
  // Vista de frente
  elevacionLateral,
  pajaro,
  aperturas,
  saltosTijera,
}

/// Una pose clave de perfil, en una caja de 200×200 con el suelo en y=190 y
/// el avatar mirando hacia +x.
///
/// - torso: 0 = vertical, + inclina hacia delante, -90 = tumbado boca arriba
///   con la cabeza a la izquierda, +90 = boca abajo con la cabeza a la derecha.
/// - curva: cuánto se dobla la parte alta de la columna (encogimiento, puente).
/// - cuello / cabeza: inclinación de la cabeza respecto al torso, o ángulo
///   absoluto (tumbado, la cabeza descansa plana).
/// - Brazo: hombro+codo (ángulos, para codos que pivotan quietos) o una mano
///   objetivo: en el marco del torso (mano, con colgar 0–1 para pesos que
///   caen a plomo) o fija en el mundo (manoAbs: barras, suelo).
/// - Pierna: tobillo objetivo (pie), dedos apoyados (punta + pieAng), ángulos
///   (muslo + rodilla) o de rodillas (rodillaAbs + pie para la espinilla).
class PoseAvatar {
  const PoseAvatar({
    required this.cadera,
    required this.torso,
    this.curva = 0,
    this.cuello = 0,
    this.cabeza,
    this.hombro,
    this.codo,
    this.mano,
    this.colgar = 0,
    this.manoAbs,
    this.pie,
    this.punta,
    this.pieAng,
    this.pie2,
    this.punta2,
    this.pieAng2,
    this.muslo,
    this.rodilla,
    this.rodillaAbs,
    this.muneca = 0,
  });

  final Offset cadera;
  final double torso;
  final double curva;
  final double cuello;
  final double? cabeza;
  final double? hombro;
  final double? codo;
  final Offset? mano;
  final double colgar;
  final Offset? manoAbs;
  final Offset? pie;
  final Offset? punta;
  final double? pieAng;
  final Offset? pie2;
  final Offset? punta2;
  final double? pieAng2;
  final double? muslo;
  final double? rodilla;
  final Offset? rodillaAbs;
  final double muneca;
}

/// Bancos, poleas y barras que rodean al avatar.
class MuebleAvatar {
  const MuebleAvatar({
    this.esterilla,
    this.torre,
    this.barraFija,
    this.paralelas,
    this.bancos = const <List<double>>[],
    this.patas = const <Offset>[],
    this.escalon,
    this.prensa,
    this.polea,
    this.trineo = false,
    this.rodillo = false,
    this.silla,
    this.pared,
    this.mesa,
  });

  final List<double>? esterilla; // [x1, x2]
  final double? torre; // poste vertical de la polea
  final List<double>? barraFija; // [y, x1, x2]
  final List<double>? paralelas; // [y, x1, x2]
  final List<List<double>> bancos; // cada uno [x1, y1, x2, y2]
  final List<Offset> patas;
  final List<double>? escalon; // [x1, x2, y]
  final List<Offset>? prensa; // raíles de la prensa
  final Offset? polea; // anclaje del cable
  final bool trineo; // plataforma de la prensa en los pies
  final bool rodillo; // almohadilla en el tobillo (curl femoral)

  // Lo que hay en cualquier casa.
  final List<double>? silla; // [x1, x2, y del asiento, lado del respaldo -1|0|1]
  final double? pared; // x de la cara de la pared
  final List<double>? mesa; // [y del tablero, x1, x2]
}

enum TrazoAvatar { ninguno, mano, cadera }

enum AsaAvatar { ninguna, barra, d }

/// Un patrón de movimiento: sus poses clave y lo que hay alrededor.
class EscenaPatron {
  const EscenaPatron({
    this.poses = const <PoseAvatar>[],
    this.mueble = const MuebleAvatar(),
    this.barraEspalda = false,
    this.disco = 16,
    this.trazo = TrazoAvatar.ninguno,
    this.sinAgarre = false,
    this.goblet = false,
    this.asa = AsaAvatar.ninguna,
    this.escala = 1,
    this.detrasCabeza = false,
    this.codoInvertido = false,
    this.codoFijo,
    this.escorzo = 1,
    this.frontal = false,
    this.anguloA = 0,
    this.anguloB = 0,
    this.flexCodo = 14,
    this.inclinado = false,
    this.poleaFrente,
    this.piernasA = 2.5,
    this.piernasB = 2.5,
    this.salto = 0,
  });

  /// De la pose de reposo (0) a la contracción (1). Con tres o más, el
  /// recorrido pasa suave por todas (Catmull-Rom).
  final List<PoseAvatar> poses;
  final MuebleAvatar mueble;

  /// La barra apoyada en la espalda (sentadilla trasera).
  final bool barraEspalda;
  final double disco;

  /// Puntos que marcan el recorrido de la barra (o de la cadera).
  final TrazoAvatar trazo;
  final bool sinAgarre;
  final bool goblet;
  final AsaAvatar asa;

  /// Para que quepan los movimientos por encima de la cabeza.
  final double escala;

  /// El brazo cercano pasa por detrás de la cabeza.
  final bool detrasCabeza;
  final bool codoInvertido;

  /// Agarre en escorzo: el codo cuelga en este ángulo y el antebrazo llega a
  /// la barra acortado por la perspectiva.
  final double? codoFijo;
  final double escorzo;

  // Vista de frente
  final bool frontal;
  final double anguloA;
  final double anguloB;
  final double flexCodo;
  final bool inclinado;
  final Offset? poleaFrente;

  /// Apertura de las piernas (grados) al principio y al final, y cuánto se
  /// despega del suelo a mitad del movimiento (saltos de tijera).
  final double piernasA;
  final double piernasB;
  final double salto;
}

const Map<PatronMovimiento, EscenaPatron> escenasPatron = <PatronMovimiento, EscenaPatron>{
  PatronMovimiento.sentadilla: EscenaPatron(
    poses: <PoseAvatar>[
      PoseAvatar(cadera: Offset(100, 107), torso: 5, mano: Offset(-8, 49), pie: Offset(104, 186)),
      PoseAvatar(cadera: Offset(78, 146), torso: 43, mano: Offset(-8, 49), pie: Offset(104, 186)),
    ],
    barraEspalda: true,
    disco: 12,
    trazo: TrazoAvatar.mano,
    codoFijo: -22,
    escorzo: 0.8,
  ),
  PatronMovimiento.goblet: EscenaPatron(
    poses: <PoseAvatar>[
      PoseAvatar(cadera: Offset(100, 107), torso: 3, mano: Offset(14, 40), pie: Offset(104, 186)),
      PoseAvatar(cadera: Offset(84, 150), torso: 24, mano: Offset(14, 40), pie: Offset(104, 186)),
    ],
    goblet: true,
  ),
