// ---------------------------------------------------------------------------
// 40.3 EL AVATAR
//
// El cuerpo se resuelve con reglas anatómicas fijas: la rodilla siempre se
// dobla hacia atrás y el codo hacia delante, en cualquier postura (el cuerpo
// solo gira, nunca se refleja). Así ninguna articulación se «voltea» a mitad
// del movimiento. Las extremidades se interpolan por ángulos o por objetivos
// según el ejercicio, y cada patrón está comprobado fotograma a fotograma:
// sin miembros que atraviesen el suelo ni manos que no lleguen a la barra.
// ---------------------------------------------------------------------------

enum EquipoMano { nada, barra, mancuerna, kettlebell, rueda, garrafa, banda }

/// Lo que se usa en casa en lugar de pesas: garrafas, botellas o mochilas.
const Map<String, EquipoMano> _manoCasera = <String, EquipoMano>{
  'remo_garrafa': EquipoMano.garrafa,
  'curl_garrafa': EquipoMano.garrafa,
  'elevaciones_botellas': EquipoMano.garrafa,
  'curl_muneca_garrafa': EquipoMano.garrafa,
  'paseo_granjero': EquipoMano.garrafa,
  // El remo con banda ya dibuja su cable de la polea.
  'remo_banda': EquipoMano.nada,
};

EquipoMano _equipoMano(String ejercicioId) {
  if (ejercicioId == 'rueda_abdominal') return EquipoMano.rueda;
  final EquipoMano? casera = _manoCasera[ejercicioId];
  if (casera != null) return casera;
  final Ejercicio? e = ejercicioPorId(ejercicioId);
  switch (e?.equipo) {
    case Equipo.banda:
      return EquipoMano.banda;
    case Equipo.casero:
      return EquipoMano.garrafa;
    case Equipo.barra:
      return EquipoMano.barra;
    case Equipo.mancuerna:
      return EquipoMano.mancuerna;
    case Equipo.kettlebell:
      return EquipoMano.kettlebell;
    default:
      return EquipoMano.nada;
  }
}

/// Bucle del movimiento: pausa abajo, sube con fuerza, pausa, baja lento.
double faseMovimiento(double t) {
  if (t < 0.12) return 0;
  if (t < 0.42) return Curves.easeInOut.transform((t - 0.12) / 0.30);
  if (t < 0.52) return 1;
  return 1 - Curves.easeInOut.transform((t - 0.52) / 0.48);
}

// -- Geometría ---------------------------------------------------------------

const double _avRad = math.pi / 180;
const double _avBrazo = 29, _avAnte = 25, _avMuslo = 41, _avPierna = 39, _avPie = 15;
const double _avColumna = 52;

double _avDot(Offset a, Offset b) => a.dx * b.dx + a.dy * b.dy;
double _avCross(Offset a, Offset b) => a.dx * b.dy - a.dy * b.dx;
Offset _avNorm(Offset a) {
  final double l = a.distance;
  return l == 0 ? Offset.zero : a / l;
}

/// Dirección de un ángulo de torso: 0 = arriba, + hacia delante.
Offset _avDirTorso(double g) => Offset(math.sin(g * _avRad), -math.cos(g * _avRad));

/// Dirección de un ángulo del mundo: 0 = +x, 90 = abajo.
Offset _avDirMundo(double g) => Offset(math.cos(g * _avRad), math.sin(g * _avRad));

/// Normal «hacia delante» de una tangente de la columna.
Offset _avFrente(Offset t) => Offset(-t.dy, t.dx);

/// Ángulo en el marco del cuerpo: 0 = hacia abajo, + hacia delante.
Offset _avEnMarco(Offset abajo, Offset delante, double g) =>
    abajo * math.cos(g * _avRad) + delante * math.sin(g * _avRad);

double _avAnguloEnMarco(Offset v, Offset abajo, Offset delante) =>
    math.atan2(_avDot(v, delante), _avDot(v, abajo)) / _avRad;

/// La columna: dos tramos (lumbar y dorsal) unidos por una cuadrática.
class _AvColumna {
  _AvColumna(Offset cadera, double torso, double curva)
      : p0 = cadera,
        dB = _avDirTorso(torso),
        dA = _avDirTorso(torso + curva),
        p1 = cadera + _avDirTorso(torso) * (_avColumna / 2),
        p2 = cadera + _avDirTorso(torso) * (_avColumna / 2) + _avDirTorso(torso + curva) * (_avColumna / 2);

  final Offset p0, p1, p2, dB, dA;

  Offset tangente(double yt) {
    if (yt <= 0) return dB;
    final double u = math.min(yt / _avColumna, 1);
    return _avNorm((p1 - p0) * (2 * (1 - u)) + (p2 - p1) * (2 * u));
  }

  /// Punto en el marco del torso: xt hacia delante, yt hacia arriba.
  Offset en(double xt, double yt) {
    if (yt <= 0) return p0 + dB * yt + _avFrente(dB) * xt;
    if (yt >= _avColumna) return p2 + dA * (yt - _avColumna) + _avFrente(dA) * xt;
    final double u = yt / _avColumna;
    final Offset b = p0 * ((1 - u) * (1 - u)) + p1 * (2 * u * (1 - u)) + p2 * (u * u);
    return b + _avFrente(tangente(yt)) * xt;
  }
}

/// Dos huesos: devuelve la articulación y el extremo.
(Offset, Offset) _avIk(Offset r, Offset t, double a, double b, double signo, {bool abajo = false}) {
  final Offset d = t - r;
  final double dist = d.distance;
  final double dc = dist.clamp((a - b).abs() + 0.01, a + b - 0.05);
  final double base = math.atan2(d.dy, d.dx);
  final double cosA = ((a * a + dc * dc - b * b) / (2 * a * dc)).clamp(-1.0, 1.0);
  final double ang = math.acos(cosA);
  final Offset e = dist > 0 ? r + d * (dc / dist) : t;
  Offset j = r + Offset(math.cos(base + ang), math.sin(base + ang)) * a;
  final Offset otra = r + Offset(math.cos(base - ang), math.sin(base - ang)) * a;
  if (abajo) {
    if (otra.dy > j.dy) j = otra;
  } else if (_avCross(j - r, e - j) * signo < 0) {
    j = otra;
  }
  return (j, e);
}

double _avCr(double p0, double p1, double p2, double p3, double t) {
  final double t2 = t * t, t3 = t2 * t;
  return 0.5 *
      (2 * p1 + (-p0 + p2) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 + (-p0 + 3 * p1 - 3 * p2 + p3) * t3);
}

Offset _avCrO(Offset a, Offset b, Offset c, Offset d, double t) =>
    Offset(_avCr(a.dx, b.dx, c.dx, d.dx, t), _avCr(a.dy, b.dy, c.dy, d.dy, t));

/// La pose en la fase f (0–1), pasando suave por todas las poses clave.
PoseAvatar _avPoseEn(EscenaPatron e, double f) {
  final List<PoseAvatar> k = e.poses;
  if (k.length == 1) return k.first;
  final int n = k.length - 1;
  final double x = f.clamp(0.0, 1.0) * n;
  final int i = math.min(x.floor(), n - 1);
  final double t = x - i;
  final PoseAvatar a = k[math.max(i - 1, 0)], b = k[i], c = k[i + 1], d = k[math.min(i + 2, n)];
  double nn(double va, double vb, double vc, double vd) => _avCr(va, vb, vc, vd, t);
  double? nq(double? Function(PoseAvatar) g) {
    final double? vb = g(b);
    if (vb == null) return null;
    final double vc = g(c) ?? vb;
    return _avCr(g(a) ?? vb, vb, vc, g(d) ?? vc, t);
  }

  Offset? oq(Offset? Function(PoseAvatar) g) {
    final Offset? vb = g(b);
    if (vb == null) return null;
    final Offset vc = g(c) ?? vb;
    return _avCrO(g(a) ?? vb, vb, vc, g(d) ?? vc, t);
  }

  return PoseAvatar(
    cadera: _avCrO(a.cadera, b.cadera, c.cadera, d.cadera, t),
    torso: nn(a.torso, b.torso, c.torso, d.torso),
    curva: nn(a.curva, b.curva, c.curva, d.curva),
    cuello: nn(a.cuello, b.cuello, c.cuello, d.cuello),
    cabeza: nq((PoseAvatar p) => p.cabeza),
    hombro: nq((PoseAvatar p) => p.hombro),
    codo: nq((PoseAvatar p) => p.codo),
    mano: oq((PoseAvatar p) => p.mano),
    colgar: nn(a.colgar, b.colgar, c.colgar, d.colgar),
    manoAbs: oq((PoseAvatar p) => p.manoAbs),
    pie: oq((PoseAvatar p) => p.pie),
    punta: oq((PoseAvatar p) => p.punta),
    pieAng: nq((PoseAvatar p) => p.pieAng),
    pie2: oq((PoseAvatar p) => p.pie2),
    punta2: oq((PoseAvatar p) => p.punta2),
    pieAng2: nq((PoseAvatar p) => p.pieAng2),
    muslo: nq((PoseAvatar p) => p.muslo),
    rodilla: nq((PoseAvatar p) => p.rodilla),
    rodillaAbs: oq((PoseAvatar p) => p.rodillaAbs),
    muneca: nn(a.muneca, b.muneca, c.muneca, d.muneca),
  );
}

/// El cuerpo resuelto en un instante.
class _AvCuerpo {
  _AvCuerpo({
    required this.col,
    required this.cadera,
    required this.hombro,
    required this.cuello,
    required this.cabeza,
    required this.dirCabeza,
    required this.codo,
    required this.mano,
    required this.rodilla,
    required this.tobillo,
    required this.dedo,
    required this.rodilla2,
    required this.tobillo2,
    required this.dedo2,
  });

  final _AvColumna col;
  final Offset cadera, hombro, cuello, cabeza, dirCabeza, codo, mano;
  final Offset rodilla, tobillo, dedo, rodilla2, tobillo2, dedo2;
}

_AvCuerpo _avResolver(EscenaPatron e, PoseAvatar p) {
  // De rodillas: la cadera queda a un muslo exacto de la rodilla apoyada.
  Offset h = p.cadera;
  final Offset? rk = p.rodillaAbs;
  if (rk != null) h = rk + _avNorm(p.cadera - rk) * _avMuslo;
  final _AvColumna c = _AvColumna(h, p.torso, p.curva);
  final Offset s = c.en(0.5, 47);
  final Offset tS = c.tangente(47);
  final Offset abajoS = -tS, delanteS = _avFrente(tS);
  final Offset n = c.en(-0.5, 51);
  final Offset tN = c.tangente(51);
  final double cu = p.cuello * _avRad;
  final Offset dirCab = p.cabeza != null
      ? _avDirTorso(p.cabeza!)
      : _avNorm(tN * math.cos(cu) + _avFrente(tN) * math.sin(cu));
  final Offset cab = n + dirCab * 11;

  // Brazo
  Offset codo, mano;
  if (p.hombro != null) {
    codo = s + _avEnMarco(abajoS, delanteS, p.hombro!) * _avBrazo;
    mano = codo + _avEnMarco(abajoS, delanteS, p.hombro! + (p.codo ?? 0)) * _avAnte;
  } else {
    Offset t;
    if (p.manoAbs != null) {
      t = p.manoAbs!;
    } else {
      // En el marco del torso; «colgar» la deja caer a plomo (pesos).
      final Offset m = p.mano ?? const Offset(10, 20);
      final Offset enT = c.en(m.dx, m.dy);
      final Offset plomo = s + const Offset(0, _avBrazo + _avAnte - 1.2);
      t = Offset.lerp(enT, plomo, p.colgar)!;
    }
    final double k = e.escorzo;
    if (e.codoFijo != null) {
      codo = s + _avEnMarco(abajoS, delanteS, e.codoFijo!) * (_avBrazo * k);
      mano = t;
    } else {
      final (Offset, Offset) r =
          _avIk(s, t, _avBrazo * k, _avAnte * k, e.codoInvertido ? 1 : -1);
      codo = r.$1;
      mano = r.$2;
    }
  }

  // Piernas
  final Offset abajoH = -c.dB, delanteH = _avFrente(c.dB);
  (Offset, Offset, Offset) pierna(Offset? pie, Offset? punta, double? pieAng, Offset? rodAbs, bool fk) {
    Offset rod, tob;
    if (fk) {
      rod = h + _avEnMarco(abajoH, delanteH, p.muslo!) * _avMuslo;
      tob = rod + _avEnMarco(abajoH, delanteH, p.muslo! - (p.rodilla ?? 0)) * _avPierna;
    } else if (rodAbs != null) {
      rod = rodAbs;
      tob = rod + _avNorm((pie ?? rod + const Offset(-1, 0)) - rod) * _avPierna;
    } else {
      final Offset objetivo =
          punta != null ? punta - _avDirMundo(pieAng ?? 90) * _avPie : (pie ?? h + const Offset(0, 79));
      final (Offset, Offset) r = _avIk(h, objetivo, _avMuslo, _avPierna, 1);
      rod = r.$1;
      tob = r.$2;
    }
    Offset dedo;
    if (punta != null) {
      dedo = punta;
    } else if (pieAng != null) {
      dedo = tob + _avDirMundo(pieAng) * _avPie;
    } else {
      final Offset sh = _avNorm(tob - rod);
      final double g = _avAnguloEnMarco(sh, abajoH, delanteH) + 90;
      Offset dir = _avEnMarco(abajoH, delanteH, g);
      if (tob.dy > 179) dir = Offset(dir.dx >= 0 ? 1 : -1, 0); // apoyado: planta plana
      dedo = tob + dir * _avPie;
    }
    return (rod, tob, dedo);
  }

  final (Offset, Offset, Offset) cerca = pierna(p.pie, p.punta, p.pieAng, p.rodillaAbs, p.muslo != null);
  final (Offset, Offset, Offset) lejos = (p.pie2 != null || p.punta2 != null)
      ? pierna(p.pie2, p.punta2, p.pieAng2 ?? p.pieAng, null, false)
      : cerca;

  return _AvCuerpo(
    col: c,
    cadera: h,
    hombro: s,
    cuello: n,
    cabeza: cab,
    dirCabeza: dirCab,
    codo: codo,
    mano: mano,
    rodilla: cerca.$1,
    tobillo: cerca.$2,
    dedo: cerca.$3,
    rodilla2: lejos.$1,
    tobillo2: lejos.$2,
    dedo2: lejos.$3,
  );
}

// -- Widget ------------------------------------------------------------------

class AvatarEjercicio extends StatefulWidget {
  const AvatarEjercicio({
    super.key,
    required this.ejercicioId,
    this.size = 220,
    this.animado = true,
    this.mostrarSuelo = true,
    this.velocidad = 1,
    this.pausado = false,
    this.espejo = false,
  });

  final String ejercicioId;
  final double size;
  final bool animado;
  final bool mostrarSuelo;

  /// 1 = ritmo normal; 0.5 = cámara lenta (del Pase).
  final double velocidad;

  /// Congela el movimiento donde esté.
  final bool pausado;

  /// Lo muestra del otro lado, como en un espejo.
  final bool espejo;

  @override
  State<AvatarEjercicio> createState() => _AvatarEjercicioState();
}

class _AvatarEjercicioState extends State<AvatarEjercicio>
    with TickerDecorativo {
  @override
  bool get animarEnWeb => true;
  late final AnimationController _c = AnimationController(vsync: this, duration: _duracion);

  Duration get _duracion => Duration(milliseconds: (3200 / widget.velocidad.clamp(0.25, 2.0)).round());

  void _sincronizar() {
    final bool reducir = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    if (_c.duration != _duracion) {
      _c.duration = _duracion;
      if (_c.isAnimating) _c.repeat();
    }
    if (widget.animado && !reducir && !widget.pausado) {
      if (!_c.isAnimating) _c.repeat();
    } else {
      _c.stop();
      if (!widget.pausado) _c.value = 0.45;
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _sincronizar();
  }

  @override
  void didUpdateWidget(AvatarEjercicio old) {
    super.didUpdateWidget(old);
    if (old.velocidad != widget.velocidad || old.pausado != widget.pausado || old.animado != widget.animado) {
      _sincronizar();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final PatronMovimiento? p = patronDeEjercicio[widget.ejercicioId];
    if (p == null) {
      return SizedBox(
        width: widget.size,
        height: widget.size,
        child: Center(
          child: TempleIcon(TempleGlyph.mancuerna, size: widget.size * 0.3, color: TempleColors.textoTenue),
        ),
      );
    }
    final Ejercicio? def = ejercicioPorId(widget.ejercicioId);
    return SizedBox(
      width: widget.size,
      height: widget.size,
      child: RepaintBoundary(
        child: AnimatedBuilder(
          animation: _c,
          builder: (BuildContext context, _) => Transform.flip(
            flipX: widget.espejo,
            child: CustomPaint(
            painter: _AvatarPainter(
              escena: escenasPatron[p]!,
              fase: faseMovimiento(_c.value),
              tiempo: _c.value,
              equipo: _equipoMano(widget.ejercicioId),
              principal: def?.grupoPrincipal,
              suelo: widget.mostrarSuelo,
            ),
          ),
          ),
        ),
      ),
    );
  }
}

