/// Una pieza de una extremidad: cápsula, círculo o elipse.
class _AvPieza {
  const _AvPieza.cap(this.a, this.b, this.ra, this.rb, this.color, this.borde)
      : elipse = false,
        ang = 0;
  const _AvPieza.circ(Offset c, double r, this.color, this.borde)
      : a = c,
        b = c,
        ra = r,
        rb = r,
        elipse = false,
        ang = 0;
  _AvPieza.elip(Offset p, Offset q, double t, double lado, double sep, double rx, double ry, this.color, this.borde)
      : a = p + (q - p) * t + Offset(_avNorm(q - p).dy, -_avNorm(q - p).dx) * (sep * lado),
        b = Offset.zero,
        ra = rx,
        rb = ry,
        elipse = true,
        ang = math.atan2((q - p).dy, (q - p).dx);

  final Offset a, b;
  final double ra, rb;
  final Color color, borde;
  final bool elipse;
  final double ang;

  void pintar(Canvas c, double extra, Color col) {
    if (elipse) {
      c.save();
      c.translate(a.dx, a.dy);
      c.rotate(ang);
      c.drawOval(Rect.fromCenter(center: Offset.zero, width: (ra + extra) * 2, height: (rb + extra) * 2),
          Paint()..color = col);
      c.restore();
    } else {
      _avCapsula(c, a, b, ra + extra, rb + extra, col);
    }
  }
}

/// Dos pasadas: primero todo un poco más grueso en el color del contorno y
/// luego el relleno. Queda un trazo fino solo por fuera, como en el anime.
void _avPiezas(Canvas c, List<_AvPieza> lista) {
  for (final _AvPieza p in lista) {
    p.pintar(c, 0.95, p.borde);
  }
  for (final _AvPieza p in lista) {
    p.pintar(c, 0, p.color);
  }
}

void _avCirculo(Canvas c, Offset p, double r, Color col) => c.drawCircle(p, r, Paint()..color = col);

/// Segmento cónico: dos círculos unidos por sus tangentes exteriores.
void _avCapsula(Canvas c, Offset a, Offset b, double ra, double rb, Color col) {
  final Paint paint = Paint()..color = col;
  c.drawCircle(a, ra, paint);
  c.drawCircle(b, rb, paint);
  final Offset d = b - a;
  final double l = d.distance;
  if (l < 0.01) return;
  final double base = math.atan2(d.dy, d.dx);
  final double phi = math.acos(((ra - rb) / l).clamp(-1.0, 1.0));
  Offset u(double g) => Offset(math.cos(g), math.sin(g));
  final Path p = Path()
    ..moveTo((a + u(base + phi) * ra).dx, (a + u(base + phi) * ra).dy)
    ..lineTo((b + u(base + phi) * rb).dx, (b + u(base + phi) * rb).dy)
    ..lineTo((b + u(base - phi) * rb).dx, (b + u(base - phi) * rb).dy)
    ..lineTo((a + u(base - phi) * ra).dx, (a + u(base - phi) * ra).dy)
    ..close();
  c.drawPath(p, paint);
}

void _avLinea(Canvas c, Offset a, Offset b, double w, Color col) => c.drawLine(
      a,
      b,
      Paint()
        ..color = col
        ..strokeWidth = w
        ..strokeCap = StrokeCap.round,
    );

Paint _avTrazo(Color col, double w) => Paint()
  ..color = col
  ..style = PaintingStyle.stroke
  ..strokeWidth = w
  ..strokeCap = StrokeCap.round
  ..strokeJoin = StrokeJoin.round;

/// Curva cerrada que pasa por todos los puntos (Catmull-Rom en cúbicas).
Path _avCurvaCerrada(List<Offset> pts) {
  final int n = pts.length;
  final Path p = Path()..moveTo(pts[0].dx, pts[0].dy);
  for (int i = 0; i < n; i++) {
    final Offset p0 = pts[(i - 1 + n) % n], p1 = pts[i], p2 = pts[(i + 1) % n], p3 = pts[(i + 2) % n];
    final Offset c1 = p1 + (p2 - p0) / 6;
    final Offset c2 = p2 - (p3 - p1) / 6;
    p.cubicTo(c1.dx, c1.dy, c2.dx, c2.dy, p2.dx, p2.dy);
  }
  return p..close();
}

const List<Offset> _avContorno = <Offset>[
  Offset(6.5, -6), Offset(8.5, 6), Offset(9.5, 18), Offset(11.5, 31), Offset(12, 40), Offset(9.5, 47),
  Offset(4.5, 51.5), Offset(-5, 52.5), Offset(-10, 48), Offset(-11.5, 38), Offset(-9.8, 25), Offset(-8.6, 13),
  Offset(-10.2, 2), Offset(-8, -7), Offset(0, -9),
];

const List<Offset> _avSombraEspalda = <Offset>[
  Offset(-12, 50), Offset(-12.5, 30), Offset(-11, 4), Offset(-6.5, 2), Offset(-7.5, 28), Offset(-7, 48),
];

/// Garrafa de agua (o botella grande) colgando de la mano: el peso de casa.
void _avGarrafa(Canvas c, Offset pos) {
  final Offset g = pos + const Offset(0, 10.5);
  final RRect cuerpo = RRect.fromRectAndRadius(Rect.fromLTWH(g.dx - 6.5, g.dy - 6.5, 13, 15), const Radius.circular(4));
  c.drawRRect(cuerpo, Paint()..color = const Color(0x4D6FA8FF));
  c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(g.dx - 6.5, g.dy - 1, 13, 9.5), const Radius.circular(3.5)),
      Paint()..color = const Color(0x8C6FA8FF));
  c.drawRRect(cuerpo, _avTrazo(const Color(0xFFBFD8FF), 1.2));
  _avLinea(c, g + const Offset(-4, -3.5), g + const Offset(-4, 5), 1, const Color(0x8CFFFFFF));
  // Asa que abraza el puño y tapón.
  c.drawArc(Rect.fromCircle(center: pos + const Offset(0, 1), radius: 3.6), math.pi * 1.05, math.pi * 0.9, false,
      _avTrazo(const Color(0xFFBFD8FF), 1.8));
  c.drawLine(pos + const Offset(-3.4, 1.6), g + const Offset(-4.5, -6.5), _avTrazo(const Color(0xFFBFD8FF), 1.8));
  c.drawLine(pos + const Offset(3.4, 1.6), g + const Offset(2.5, -6.5), _avTrazo(const Color(0xFFBFD8FF), 1.8));
  c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(g.dx + 2, g.dy - 9, 4, 3), const Radius.circular(1)),
      Paint()..color = _AvCol.cinta);
}

/// Banda elástica del pie a la mano: más fina cuanto más se estira.
void _avBanda(Canvas c, Offset a, Offset b) {
  final double largo = (b - a).distance;
  final double ancho = math.max(1.6, 3.4 - largo / 60);
  final Offset m = Offset.lerp(a, b, 0.5)!;
  final Offset n = _avNorm(Offset(-(b.dy - a.dy), b.dx - a.dx));
  final Offset ctrl = m + n * math.max(0.0, 6 - largo / 14);
  final Path p = Path()
    ..moveTo(a.dx, a.dy)
    ..quadraticBezierTo(ctrl.dx, ctrl.dy, b.dx, b.dy);
  c.drawPath(p, _avTrazo(const Color(0xFF2E8C69), ancho + 1.2));
  c.drawPath(p, _avTrazo(const Color(0xFF5BD6A0), ancho));
}

class _AvatarPainter extends CustomPainter {
  const _AvatarPainter({
    required this.escena,
    required this.fase,
    required this.tiempo,
    required this.equipo,
    required this.principal,
    required this.suelo,
  });

  final EscenaPatron escena;
  final double fase; // 0 = reposo, 1 = contracción
  final double tiempo; // 0–1 del bucle (cinta, ondas)
  final EquipoMano equipo;
  final GrupoMuscular? principal;
  final bool suelo;

  double get _fuerzaAura => 0.35 + 0.55 * fase;

  @override
  void paint(Canvas canvas, Size size) {
    final double k = size.shortestSide / 200;
    canvas.save();
    canvas.translate((size.width - 200 * k) / 2, (size.height - 200 * k) / 2);
    canvas.scale(k);
    if (suelo) _avLinea(canvas, const Offset(10, 190), const Offset(190, 190), 1.2, _AvCol.suelo);
    final double e = escena.escala;
    if (e != 1) {
      canvas.translate(100, 190);
      canvas.scale(e);
      canvas.translate(-100, -190);
    }
    if (escena.frontal) {
      canvas.drawOval(
        Rect.fromCenter(center: const Offset(100, 190), width: 68, height: 7),
        Paint()
          ..color = Colors.black.withValues(alpha: 0.4)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 2.5),
      );
      _pintarFrente(canvas);
    } else {
      _pintarLado(canvas);
    }
    canvas.restore();
  }

  // ---- Aura del músculo que trabaja --------------------------------------

  void _aura(Canvas c, void Function(Paint) dibujar) {
    c.saveLayer(null, Paint()..color = Colors.white.withValues(alpha: _fuerzaAura.clamp(0.0, 1.0)));
    dibujar(
      Paint()
        ..color = _AvCol.dorado
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3.5),
    );
    c.restore();
  }

  void _pintarAura(Canvas c, _AvCuerpo j) {
    if (principal == null) return;
    _aura(c, (Paint d) {
      void cap(Offset a, Offset b, double ra, double rb) {
        c.drawCircle(a, ra, d);
        c.drawCircle(b, rb, d);
        final Offset dir = _avNorm(b - a);
        final Offset n = Offset(-dir.dy, dir.dx);
        c.drawPath(
          Path()
            ..moveTo((a + n * ra).dx, (a + n * ra).dy)
            ..lineTo((b + n * rb).dx, (b + n * rb).dy)
            ..lineTo((b - n * rb).dx, (b - n * rb).dy)
            ..lineTo((a - n * ra).dx, (a - n * ra).dy)
            ..close(),
          d,
        );
      }

      switch (principal!) {
        case GrupoMuscular.piernas:
          cap(j.cadera, j.rodilla, 11.5, 9);
          c.drawCircle(j.col.en(-9, 1), 10, d);
        case GrupoMuscular.pantorrillas:
          cap(j.rodilla, j.tobillo, 8.5, 6.5);
        case GrupoMuscular.pecho:
          c.drawCircle(j.col.en(11, 37), 11, d);
        case GrupoMuscular.espalda:
          c.drawCircle(j.col.en(-10, 35), 13, d);
          c.drawCircle(j.col.en(-9, 20), 9, d);
        case GrupoMuscular.abdomen:
          c.drawCircle(j.col.en(9.5, 21), 10, d);
        case GrupoMuscular.hombros:
          c.drawCircle(j.hombro, 10.5, d);
        case GrupoMuscular.biceps:
        case GrupoMuscular.triceps:
          cap(j.hombro, j.codo, 9, 7.5);
        case GrupoMuscular.antebrazos:
          cap(j.codo, j.mano, 7.5, 6.5);
      }
    });
  }

  // ---- Torso -------------------------------------------------------------

  Path _torso(_AvColumna c) => _avCurvaCerrada(<Offset>[for (final Offset o in _avContorno) c.en(o.dx, o.dy)]);

  void _pintarTorso(Canvas cv, _AvCuerpo j) {
    final _AvColumna c = j.col;
    final Path t = _torso(c);
    cv.drawPath(t, _avTrazo(_AvCol.borde, 1.9));
    cv.drawPath(t, Paint()..color = _AvCol.gi);
    cv.save();
    cv.clipPath(t);
    cv.drawPath(_avCurvaCerrada(<Offset>[for (final Offset o in _avSombraEspalda) c.en(o.dx, o.dy)]),
        Paint()..color = _AvCol.giSombra);
    cv.restore();
    // Solapa del gi y el escote
    final Offset s0 = c.en(4.5, 51.5), s1 = c.en(2.5, 42), s2 = c.en(5.5, 28), s3 = c.en(8.8, 13);
    cv.drawPath(Path()
          ..moveTo(s0.dx, s0.dy)
          ..cubicTo(s1.dx, s1.dy, s2.dx, s2.dy, s3.dx, s3.dy),
        _avTrazo(_AvCol.giLinea, 1.3));
    final Offset v0 = c.en(4.5, 51.5), v1 = c.en(2.6, 45), v2 = c.en(7.8, 47.5);
    cv.drawPath(
        Path()
          ..moveTo(v0.dx, v0.dy)
          ..lineTo(v1.dx, v1.dy)
          ..lineTo(v2.dx, v2.dy)
          ..close(),
        Paint()..color = _AvCol.piel);
    // Obi
    final Offset o0 = c.en(9.2, 13.5), o1 = c.en(8.7, 8), o2 = c.en(-9, 8), o3 = c.en(-9.2, 13.5);
    cv.drawPath(
        Path()
          ..moveTo(o0.dx, o0.dy)
          ..lineTo(o1.dx, o1.dy)
          ..lineTo(o2.dx, o2.dy)
          ..lineTo(o3.dx, o3.dy)
          ..close(),
        Paint()..color = _AvCol.obi);
    final Offset nudo = c.en(9.6, 10.8);
    _avCirculo(cv, nudo, 2.4, _AvCol.obi);
    final Offset abajo = -c.tangente(10);
    final Offset lado = Offset(-abajo.dy, abajo.dx);
    for (final double s in <double>[-1, 1]) {
      _avLinea(cv, nudo, nudo + abajo * 9 + lado * (s * 1.6 + 1), 2.2, _AvCol.obi);
    }
  }

  // ---- Extremidades ------------------------------------------------------

  void _pintarPierna(Canvas c, _AvCuerpo j, bool lejos) {
    final Offset h = j.cadera;
    final Offset r = lejos ? j.rodilla2 : j.rodilla;
    final Offset t = lejos ? j.tobillo2 : j.tobillo;
    final Offset d = lejos ? j.dedo2 : j.dedo;
    final Color gi = lejos ? _AvCol.giLejos : _AvCol.gi;
    final Color piel = lejos ? _AvCol.pielLejos : _AvCol.piel;
    final Color bo = lejos ? _AvCol.bordeLejos : _AvCol.borde;
    final Color bp = lejos ? _AvCol.bordeLejos : _AvCol.bordePiel;
    final Offset dir = _avNorm(d - t);
    final Offset talon = t - dir * 3.2;
    _avPiezas(c, <_AvPieza>[
      _AvPieza.cap(talon, d, 3.6, 2.4, piel, bp),
      _AvPieza.cap(t, t + dir * 6, 3.8, 3.3, piel, bp),
    ]);
    _avPiezas(c, <_AvPieza>[
      _AvPieza.cap(h, r, 8.6, 6.2, gi, bo),
      _AvPieza.elip(h, r, 0.42, 1, 2.6, 13, 6.4, gi, bo), // cuádriceps
      _AvPieza.cap(r, t, 6.2, 4.3, gi, bo),
      _AvPieza.elip(r, t, 0.32, -1, 2.0, 9, 4.6, gi, bo), // gemelo
      _AvPieza.cap(Offset.lerp(r, t, 0.82)!, t, 5.0, 4.9, gi, bo), // bajo del pantalón
    ]);
  }

  Offset _pintarBrazo(Canvas c, _AvCuerpo j, bool lejos, double muneca) {
    final Offset s = j.hombro, e = j.codo, m = j.mano;
    final Color gi = lejos ? _AvCol.giLejos : _AvCol.gi;
    final Color piel = lejos ? _AvCol.pielLejos : _AvCol.piel;
    final Color bo = lejos ? _AvCol.bordeLejos : _AvCol.borde;
    final Color bp = lejos ? _AvCol.bordeLejos : _AvCol.bordePiel;
    final Offset d = _avNorm(m - e);
    final double g = muneca * _avRad;
    final Offset dm = Offset(d.dx * math.cos(g) - d.dy * math.sin(g), d.dx * math.sin(g) + d.dy * math.cos(g));
    final Offset puno = m + dm * 4.2;
    _avPiezas(c, <_AvPieza>[
      _AvPieza.cap(e, m, 4.4, 3.4, piel, bp),
      _AvPieza.elip(e, m, 0.30, 1, 0.8, 7, 3.6, piel, bp), // antebrazo
      _AvPieza.cap(m + dm * 0.5, puno, 3.6, 4.1, piel, bp), // puño
    ]);
    _avPiezas(c, <_AvPieza>[
      _AvPieza.cap(s, e, 6.3, 4.9, gi, bo),
      _AvPieza.elip(s, e, 0.5, 1, 1.4, 9, 4.6, gi, bo), // bíceps
      _AvPieza.cap(e, Offset.lerp(e, m, 0.38)!, 5.3, 4.8, gi, bo), // manga
    ]);
    return puno;
  }

  // ---- Cabeza ------------------------------------------------------------

  void _pintarCabeza(Canvas c, _AvCuerpo j) {
    final Offset cab = j.cabeza, up = j.dirCabeza, fw = Offset(-up.dy, up.dx);
    Offset pt(double a, double r) =>
        cab + fw * (math.cos(a * _avRad) * r) + up * (math.sin(a * _avRad) * r);
    Path poligono(List<Offset> ps) {
      final Path p = Path()..moveTo(ps.first.dx, ps.first.dy);
      for (final Offset q in ps.skip(1)) {
        p.lineTo(q.dx, q.dy);
      }
      return p..close();
    }

    // Cuello
    _avCapsula(c, j.cuello, j.cuello + up * 5, 3.8, 3.6, _AvCol.pielSombra);
    // Cara y mentón
    _avCirculo(c, cab, 10, _AvCol.piel);
    final Offset m1 = pt(-5, 9.6), m2 = pt(-62, 9.8), ctrl = pt(-35, 12.4);
    c.drawPath(
        Path()
          ..moveTo(m1.dx, m1.dy)
          ..quadraticBezierTo(ctrl.dx, ctrl.dy, m2.dx, m2.dy)
          ..lineTo(cab.dx, cab.dy)
          ..close(),
        Paint()..color = _AvCol.piel);
    // Oreja
    _avCirculo(c, pt(188, 3.6), 1.9, _AvCol.pielSombra);
    // Pelo: casquete, mechones hacia atrás y flequillo
    final Paint pelo = Paint()..color = _AvCol.pelo;
    c.drawPath(
      poligono(<Offset>[
        for (double a = 52; a <= 222; a += 6) pt(a, 11),
        pt(212, 7.5),
        pt(185, 5.2),
        pt(150, 5.6),
        pt(110, 7.2),
        pt(72, 8.6),
      ]),
      pelo,
    );
    for (final double a in <double>[92, 116, 140, 164, 188]) {
      c.drawPath(poligono(<Offset>[pt(a - 10, 10), pt(a + 22, 16 + (a == 140 ? 1.5 : 0)), pt(a + 10, 10)]), pelo);
    }
    c.drawPath(poligono(<Offset>[pt(44, 10.4), pt(30, 7.4), pt(64, 10.6)]), pelo);
    c.drawPath(poligono(<Offset>[pt(58, 10.4), pt(48, 6.8), pt(80, 10.6)]), pelo);
    final Path brillo = Path()..moveTo(pt(100, 8.6).dx, pt(100, 8.6).dy);
    for (double a = 105; a <= 150; a += 5) {
      brillo.lineTo(pt(a, 8.6).dx, pt(a, 8.6).dy);
    }
    c.drawPath(brillo, _avTrazo(_AvCol.peloBrillo, 1.2));
    // Hachimaki: banda de la frente a la nuca
    final Offset f1 = pt(38, 10.4), f2 = pt(188, 10.6), fc = pt(110, 8.2);
    c.drawPath(
        Path()
          ..moveTo(f1.dx, f1.dy)
          ..quadraticBezierTo(fc.dx, fc.dy, f2.dx, f2.dy),
        _avTrazo(_AvCol.cinta, 3.4));
    final Offset nudo = pt(188, 10.8);
    _avCirculo(c, nudo, 2.3, _AvCol.cintaOscura);
    // Las colas caen hacia atrás y un poco con la gravedad; nunca bajo el suelo.
    final Offset atras = _avNorm(fw * -0.7 + const Offset(-0.4, 0.5));
    final Offset perp = Offset(-atras.dy, atras.dx);
    for (final (double, double) cola in const <(double, double)>[(1.0, 15.0), (-1.0, 12.0)]) {
      final double s = cola.$1, largo = cola.$2;
      final double ola = math.sin(tiempo * math.pi * 4 + s) * 2.4;
      Offset p1 = nudo + atras * (largo * 0.55) + perp * (s * 1.6 + ola);
      Offset p2 = nudo + atras * largo + perp * (s * 3 - ola * 0.6);
      p1 = Offset(p1.dx, math.min(p1.dy, 188.5));
      p2 = Offset(p2.dx, math.min(p2.dy, 188.5));
      c.drawPath(
          Path()
            ..moveTo(nudo.dx, nudo.dy)
            ..quadraticBezierTo(p1.dx, p1.dy, p2.dx, p2.dy),
          _avTrazo(s > 0 ? _AvCol.cinta : _AvCol.cintaOscura, 2.6));
    }
    // Ojo (se entrecierra con el esfuerzo) y ceja
    final Offset ojo = pt(16, 5.4);
    c.save();
    c.translate(ojo.dx, ojo.dy);
    c.rotate(math.atan2(fw.dy, fw.dx));
    c.drawOval(Rect.fromCenter(center: Offset.zero, width: 2.2, height: (1.75 - 0.75 * fase) * 2),
        Paint()..color = _AvCol.ojo);
    c.restore();
    _avLinea(c, pt(34, 7.6), pt(14, 8.8 - 0.6 * fase), 1.1, _AvCol.pelo);
  }

  // ---- Equipo ------------------------------------------------------------

  void _disco(Canvas c, Offset p, double r) {
    _avCirculo(c, p, r, _AvCol.metal);
    c.drawCircle(p, r - 0.9, _avTrazo(_AvCol.dorado, 1.8));
    c.drawCircle(p, r * 0.6, _avTrazo(_AvCol.metalBorde, 1.1));
    _avCirculo(c, p, 3, _AvCol.eje);
  }

  void _pintarEquipo(Canvas c, _AvCuerpo j, Offset puno) {
    if (escena.sinAgarre) return;
    final Offset pos = escena.barraEspalda ? j.mano : puno;
    switch (equipo) {
      case EquipoMano.barra:
        _disco(c, pos, escena.disco);
      case EquipoMano.mancuerna:
        if (escena.goblet) {
          _avCapsula(c, pos + const Offset(0, -7), pos + const Offset(0, 7), 2, 2, _AvCol.metalBorde);
          for (final double s in <double>[-7, 7]) {
            final Rect r = Rect.fromCenter(center: pos + Offset(0, s), width: 12, height: 6);
            c.drawOval(r, Paint()..color = _AvCol.metal);
            c.drawOval(r, _avTrazo(_AvCol.mancuernaAro, 1.1));
          }
        } else {
          _avCirculo(c, pos, 6.4, _AvCol.metal);
          c.drawCircle(pos, 5.6, _avTrazo(_AvCol.mancuernaAro, 1.4));
          _avCirculo(c, pos, 1.8, _AvCol.eje);
        }
      case EquipoMano.kettlebell:
        _avCirculo(c, pos + const Offset(0, 8), 7.4, _AvCol.metal);
        c.drawArc(Rect.fromCircle(center: pos + const Offset(0, 1.5), radius: 4.6), math.pi, math.pi, false,
            _avTrazo(_AvCol.metal, 2.6));
      case EquipoMano.rueda:
        const double r = 8.6;
        _avCirculo(c, pos, r, _AvCol.metal);
        c.drawCircle(pos, r - 0.8, _avTrazo(_AvCol.dorado, 1.6));
        final double giro = pos.dx / r;
        for (int i = 0; i < 3; i++) {
          final double a = giro + i * math.pi * 2 / 3;
          _avLinea(c, pos, pos + Offset(math.cos(a), math.sin(a)) * (r - 1.5), 1.3, _AvCol.metalBorde);
        }
        _avCirculo(c, pos, 2.2, _AvCol.eje);
      case EquipoMano.garrafa:
        _avGarrafa(c, pos);
      case EquipoMano.banda:
        _avBanda(c, Offset.lerp(j.tobillo, j.dedo, 0.45)!, pos);
      case EquipoMano.nada:
        break;
    }
  }

  void _pintarAsa(Canvas c, Offset puno, AsaAvatar asa) {
    switch (asa) {
      case AsaAvatar.barra:
        _avCirculo(c, puno, 3.4, _AvCol.cable);
        _avCirculo(c, puno, 1.4, _AvCol.metal);
      case AsaAvatar.d:
        c.drawPath(
            Path()
              ..moveTo(puno.dx - 3, puno.dy - 4)
              ..lineTo(puno.dx + 4, puno.dy)
              ..lineTo(puno.dx - 3, puno.dy + 4)
              ..close(),
            _avTrazo(_AvCol.cable, 1.8));
      case AsaAvatar.ninguna:
        break;
    }
  }

  // ---- Mobiliario --------------------------------------------------------

  void _pintarMueble(Canvas c, _AvCuerpo j, bool delante) {
    final MuebleAvatar m = escena.mueble;
    if (!delante) {
      final List<double>? est = m.esterilla;
      if (est != null) {
        c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(est[0], 186.5, est[1] - est[0], 4), const Radius.circular(2)),
            Paint()..color = _AvCol.esterilla);
      }
      final double? torre = m.torre;
      if (torre != null) _avLinea(c, Offset(torre, 4), Offset(torre, 190), 4, _AvCol.mueble);
      final List<double>? bf = m.barraFija;
      if (bf != null) {
        _avLinea(c, Offset(bf[1], bf[0] - 6), Offset(bf[1], 190), 4, _AvCol.mueble);
        _avLinea(c, Offset(bf[2], bf[0] - 6), Offset(bf[2], 190), 4, _AvCol.mueble);
        _avLinea(c, Offset(bf[1] - 4, bf[0]), Offset(bf[2] + 4, bf[0]), 3.2, _AvCol.cable);
      }
      final List<double>? par = m.paralelas;
      if (par != null) {
        _avLinea(c, Offset(par[1] + 8, par[0]), Offset(par[1] + 8, 190), 4, _AvCol.mueble);
        _avLinea(c, Offset(par[2] - 8, par[0]), Offset(par[2] - 8, 190), 4, _AvCol.mueble);
      }
      for (final List<double> b in m.bancos) {
        _avLinea(c, Offset(b[0], b[1]), Offset(b[2], b[3]), 7, _AvCol.muebleClaro);
        _avLinea(c, Offset(b[0], b[1] + 3), Offset(b[2], b[3] + 3), 2, _AvCol.muebleBorde);
      }
      for (final Offset p in m.patas) {
        _avLinea(c, p, Offset(p.dx, 190), 3.5, _AvCol.mueble);
      }
      final List<double>? esc = m.escalon;
      if (esc != null) {
        c.drawRRect(
            RRect.fromRectAndRadius(Rect.fromLTRB(esc[0], esc[2], esc[1], 190), const Radius.circular(2)),
            Paint()..color = _AvCol.muebleClaro);
      }
      final List<Offset>? pr = m.prensa;
      if (pr != null) {
        _avLinea(c, pr[0], pr[1], 3, _AvCol.mueble);
        _avLinea(c, pr[0] + const Offset(6, 6), pr[1] + const Offset(6, 6), 3, _AvCol.mueble);
      }
      final double? pared = m.pared;
      if (pared != null) {
        final double x0 = pared < 100 ? pared - 14 : pared;
        c.drawRect(Rect.fromLTWH(x0, 0, 14, 190), Paint()..color = _AvCol.mueble);
        _avLinea(c, Offset(pared, 0), Offset(pared, 190), 1.4, _AvCol.muebleBorde);
        for (final double y in const <double>[40, 95, 150]) {
          _avLinea(c, Offset(x0 + 2, y), Offset(x0 + 12, y), 0.8, _AvCol.muebleClaro);
        }
      }
      final List<double>? mesa = m.mesa;
      if (mesa != null) {
        final double y = mesa[0], x1 = mesa[1], x2 = mesa[2];
        _avLinea(c, Offset(x1 + 4, y), Offset(x1 + 4, 190), 3.5, _AvCol.mueble);
        _avLinea(c, Offset(x2 - 4, y), Offset(x2 - 4, 190), 3.5, _AvCol.mueble);
        c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(x1, y - 3, x2 - x1, 6), const Radius.circular(2)),
            Paint()..color = _AvCol.muebleClaro);
        _avLinea(c, Offset(x1 + 1, y + 3), Offset(x2 - 1, y + 3), 1.4, _AvCol.muebleBorde);
      }
      final List<double>? silla = m.silla;
      if (silla != null) {
        final double x1 = silla[0], x2 = silla[1], y = silla[2], lado = silla[3];
        _avLinea(c, Offset(x1 + 3, y), Offset(x1 + 3, 190), 3.2, _AvCol.mueble);
        _avLinea(c, Offset(x2 - 3, y), Offset(x2 - 3, 190), 3.2, _AvCol.mueble);
        _avLinea(c, Offset(x1 + 3, y + 22), Offset(x2 - 3, y + 22), 2, _AvCol.mueble);
        if (lado != 0) {
          final double x = lado < 0 ? x1 + 2 : x2 - 2;
          _avLinea(c, Offset(x, y), Offset(x, y - 40), 3.4, _AvCol.mueble);
          _avLinea(c, Offset(x, y - 38), Offset(x - lado, y - 22), 2.2, _AvCol.muebleClaro);
        }
        c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(x1, y - 2.5, x2 - x1, 5), const Radius.circular(2)),
            Paint()..color = _AvCol.muebleClaro);
      }
      return;
    }
    final List<double>? par = m.paralelas;
    if (par != null) _avLinea(c, Offset(par[1], par[0]), Offset(par[2], par[0]), 3.4, _AvCol.cable);
    final Offset? polea = m.polea;
    if (polea != null) {
      _avCirculo(c, polea, 4.5, _AvCol.mueble);
      _avCirculo(c, polea, 1.8, _AvCol.cable);
      _avLinea(c, polea, j.mano, 1.1, _AvCol.cable);
    }
    if (m.trineo) {
      final Offset pie = Offset.lerp(j.tobillo, j.dedo, 0.5)!;
      c.save();
      c.translate(pie.dx + 4, pie.dy + 2);
      c.rotate(-math.pi / 4);
      c.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(-3, -14, 6, 28), const Radius.circular(2)),
          Paint()..color = _AvCol.muebleClaro);
      c.restore();
      _disco(c, pie + const Offset(15, -7), 10);
    }
    if (m.rodillo) {
      final Offset n = _avNorm(j.tobillo - j.rodilla);
      final Offset p = j.tobillo + Offset(-n.dy, n.dx) * -6;
      _avCirculo(c, p, 5, _AvCol.muebleClaro);
      _avCirculo(c, p, 2, _AvCol.muebleBorde);
    }
  }

  // ---- Vista de perfil ---------------------------------------------------

  void _pintarLado(Canvas c) {
    final PoseAvatar p = _avPoseEn(escena, fase);
    final _AvCuerpo j = _avResolver(escena, p);

    // Recorrido de la barra (o de la cadera), en puntos.
    if (escena.trazo != TrazoAvatar.ninguno) {
      final Paint pt = Paint()..color = _AvCol.trazo;
      for (int i = 0; i <= 12; i++) {
        final _AvCuerpo q = _avResolver(escena, _avPoseEn(escena, i / 12));
        c.drawCircle(escena.trazo == TrazoAvatar.cadera ? q.cadera : q.mano, 1.1, pt);
      }
    }
    // Sombra
    final double cx = (j.cadera.dx + j.hombro.dx + j.tobillo.dx) / 3;
    c.drawOval(
      Rect.fromCenter(center: Offset(cx, 190), width: 80, height: 7),
      Paint()
        ..color = Colors.black.withValues(alpha: 0.38)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 2.5),
    );

    _pintarMueble(c, j, false);
    _pintarAura(c, j);
    // Lado lejano: un poco desplazado y más oscuro.
    c.save();
    c.translate(-2.2, -1.6);
    _pintarPierna(c, j, true);
    _pintarBrazo(c, j, true, p.muneca);
    c.restore();
    // La chaqueta del gi tapa el arranque del muslo cercano.
    _pintarPierna(c, j, false);
    _pintarTorso(c, j);
    if (escena.detrasCabeza) {
      final Offset puno = _pintarBrazo(c, j, false, p.muneca);
      _pintarEquipo(c, j, puno);
      _pintarCabeza(c, j);
      _pintarMueble(c, j, true);
      return;
    }
    _pintarCabeza(c, j);
    final Offset puno = _pintarBrazo(c, j, false, p.muneca);
    _pintarMueble(c, j, true);
    _pintarAsa(c, puno, escena.asa);
    // El disco va por fuera del cuerpo: siempre encima.
    _pintarEquipo(c, j, puno);
  }

  // ---- Vista de frente ---------------------------------------------------

  void _pintarFrente(Canvas c) {
    final double salto = escena.salto * math.sin(math.pi * fase);
    c.save();
    c.translate(0, -salto);
    _pintarFrenteCuerpo(c);
    c.restore();
  }

  void _pintarFrenteCuerpo(Canvas c) {
    final EscenaPatron e = escena;
    final double a = e.anguloA + (e.anguloB - e.anguloA) * fase;
    final bool inc = e.inclinado;
    final double hombroY = inc ? 96 : 66, cinturaY = inc ? 110 : 104, caderaY = 116;
    final Offset cab = inc ? const Offset(100, 88) : const Offset(100, 46);
    final List<(double, Offset, Offset, Offset)> brazos = <(double, Offset, Offset, Offset)>[];
    for (final double s in <double>[-1, 1]) {
      final Offset hom = Offset(100 + 22 * s, hombroY + 3);
      final double g = a * _avRad;
      final Offset codo = hom + Offset(math.sin(g) * s, math.cos(g)) * 28;
      final double g2 = g + e.flexCodo * _avRad;
      final Offset mano = codo + Offset(math.sin(g2) * s, math.cos(g2)) * 24;
      brazos.add((s, hom, codo, mano));
    }
    // Aura detrás
    if (principal == GrupoMuscular.hombros || principal == GrupoMuscular.pecho) {
      _aura(c, (Paint d) {
        if (principal == GrupoMuscular.hombros) {
          for (final (double, Offset, Offset, Offset) b in brazos) {
            c.drawCircle(b.$2, 10.5, d);
          }
        } else {
          for (final double s in <double>[-1, 1]) {
            c.drawCircle(Offset(100 + 12 * s, hombroY + 12), 11, d);
          }
        }
      });
    }
    // Piernas
    final double abre = (e.piernasA + (e.piernasB - e.piernasA) * fase) * _avRad;
    for (final double s in <double>[-1, 1]) {
      final Offset cad = Offset(100 + 9 * s, caderaY);
      final Offset rod = cad + Offset(math.sin(abre) * s * 35, math.cos(abre) * 35);
      final Offset tob = cad + Offset(math.sin(abre) * s * 69, math.cos(abre) * 69);
      _avPiezas(c, <_AvPieza>[
        _AvPieza.cap(tob + const Offset(0, 1), tob + Offset(4 * s, 3), 4.2, 3.6, _AvCol.piel, _AvCol.bordePiel),
      ]);
      _avPiezas(c, <_AvPieza>[
        _AvPieza.cap(cad, rod, 8.6, 6.4, _AvCol.gi, _AvCol.borde),
        _AvPieza.cap(rod, tob, 6.4, 4.8, _AvCol.gi, _AvCol.borde),
      ]);
    }
    // Poleas
    final Offset? pf = e.poleaFrente;
    if (pf != null) {
      for (final double s in <double>[-1, 1]) {
        final double x = s < 0 ? pf.dx : 200 - pf.dx;
        _avLinea(c, Offset(x, 4), Offset(x, 190), 4, _AvCol.mueble);
        _avCirculo(c, Offset(x, pf.dy), 4.5, _AvCol.mueble);
        _avCirculo(c, Offset(x, pf.dy), 1.8, _AvCol.cable);
      }
      for (final (double, Offset, Offset, Offset) b in brazos) {
        _avLinea(c, Offset(b.$1 < 0 ? pf.dx : 200 - pf.dx, pf.dy), b.$4, 1.1, _AvCol.cable);
      }
    }
    // Torso
    final double medio = (hombroY + cinturaY) / 2;
    final Path torso = Path()
      ..moveTo(77, hombroY)
      ..quadraticBezierTo(100, hombroY - 5, 123, hombroY)
      ..quadraticBezierTo(121, medio, 117, cinturaY)
      ..lineTo(118.5, caderaY + 5)
      ..lineTo(81.5, caderaY + 5)
      ..lineTo(83, cinturaY)
      ..quadraticBezierTo(79, medio, 77, hombroY)
      ..close();
    c.drawPath(torso, _avTrazo(_AvCol.borde, 1.9));
    c.drawPath(torso, Paint()..color = _AvCol.gi);
    if (inc) {
      _avLinea(c, Offset(100, hombroY), Offset(100, cinturaY - 3), 1.2, _AvCol.giLinea);
    } else {
      c.drawPath(
          Path()
            ..moveTo(93.5, hombroY - 3)
            ..lineTo(100, hombroY + 13)
            ..lineTo(106.5, hombroY - 3)
            ..close(),
          Paint()..color = _AvCol.piel);
      c.drawPath(
          Path()
            ..moveTo(92.5, hombroY - 3)
            ..quadraticBezierTo(98, hombroY + 20, 108, cinturaY - 2),
          _avTrazo(_AvCol.giLinea, 1.3));
      _avLinea(c, Offset(107.5, hombroY - 3), Offset(100.5, hombroY + 13), 1.3, _AvCol.giLinea);
    }
    // Obi
    c.drawRect(Rect.fromLTWH(82.4, cinturaY - 3, 35.2, 5.6), Paint()..color = _AvCol.obi);
    if (!inc) {
      _avCirculo(c, Offset(100, cinturaY), 2.7, _AvCol.obi);
      final double ola = math.sin(tiempo * math.pi * 2) * 0.8;
      _avLinea(c, Offset(100, cinturaY), Offset(96 - ola, cinturaY + 11), 2.3, _AvCol.obi);
      _avLinea(c, Offset(100, cinturaY), Offset(104 + ola, cinturaY + 12), 2.3, _AvCol.obi);
    }
    // Cabeza
    final Paint pelo = Paint()..color = _AvCol.pelo;
    if (inc) {
      // Inclinado: se ve sobre todo la coronilla.
      _avCapsula(c, Offset(100, hombroY - 1), Offset(100, cab.dy + 2), 4, 4, _AvCol.pielSombra);
      _avCirculo(c, cab, 10.4, _AvCol.piel);
      c.drawArc(Rect.fromCircle(center: cab + const Offset(0, -1.5), radius: 11), math.pi * 0.95, math.pi * 1.1, false,
          pelo);
      _avCirculo(c, cab + const Offset(0, -3), 9.5, _AvCol.pelo);
      _avLinea(c, cab + const Offset(-10.4, 2.5), cab + const Offset(10.4, 2.5), 3, _AvCol.cinta);
      for (final double s in <double>[-1, 1]) {
        c.drawOval(
            Rect.fromCenter(center: cab + Offset(4 * s, 6), width: 2.2, height: (1.2 - 0.5 * fase) * 2),
            Paint()..color = _AvCol.ojo);
      }
    } else {
      _avCapsula(c, Offset(100, hombroY - 2), Offset(100, cab.dy + 6), 4, 4, _AvCol.pielSombra);
      for (final double s in <double>[-1, 1]) {
        _avCirculo(c, cab + Offset(10.2 * s, 1.5), 2.4, _AvCol.pielSombra);
      }
      _avCirculo(c, cab, 10.4, _AvCol.piel);
      c.drawArc(Rect.fromCircle(center: cab + const Offset(0, -0.5), radius: 11.3), math.pi * 1.04, math.pi * 0.92,
          false, pelo);
      Path tri(Offset p1, Offset p2, Offset p3) => Path()
        ..moveTo(p1.dx, p1.dy)
        ..lineTo(p2.dx, p2.dy)
        ..lineTo(p3.dx, p3.dy)
        ..close();
      // Flequillo en punta
      for (final (double, double, double) f in const <(double, double, double)>[
        (-7.0, 6.0, 4.5),
        (-1.5, 7.0, 6.0),
        (5.0, 6.0, 4.0),
      ]) {
        c.drawPath(
            tri(cab + Offset(f.$1 - f.$2 / 2, -7), cab + Offset(f.$1 + 1.2, -7 + f.$3), cab + Offset(f.$1 + f.$2 / 2, -7)),
            pelo);
      }
      // Mechones laterales y corona en punta
      for (final double s in <double>[-1, 1]) {
        c.drawPath(tri(cab + Offset(8 * s, -9), cab + Offset(13.5 * s, -2), cab + Offset(10.5 * s, -1)), pelo);
      }
      for (final double g in <double>[-150, -122, -95, -68, -40]) {
        final double r = g * _avRad;
        Offset q(double ang, double rad) => cab + Offset(math.cos(ang) * rad, -0.5 + math.sin(ang) * rad);
        c.drawPath(tri(q(r - 0.2, 10.6), q(r + 0.12, 14.2), q(r + 0.2, 10.6)), pelo);
      }
      _avLinea(c, cab + const Offset(-10.8, -4.5), cab + const Offset(10.8, -4.5), 3.2, _AvCol.cinta);
      final double ola = math.sin(tiempo * math.pi * 4) * 2;
      c.drawPath(
          Path()
            ..moveTo(cab.dx + 10, cab.dy - 4.5)
            ..quadraticBezierTo(cab.dx + 16, cab.dy - 3 + ola, cab.dx + 20, cab.dy + 4 - ola),
          _avTrazo(_AvCol.cinta, 2.4));
      c.drawPath(
          Path()
            ..moveTo(cab.dx + 10, cab.dy - 4)
            ..quadraticBezierTo(cab.dx + 14, cab.dy + 1 - ola, cab.dx + 16, cab.dy + 7),
          _avTrazo(_AvCol.cintaOscura, 2.4));
      for (final double s in <double>[-1, 1]) {
        c.drawOval(
            Rect.fromCenter(center: cab + Offset(4.2 * s, 1.2), width: 2.5, height: (2.0 - 0.9 * fase) * 2),
            Paint()..color = _AvCol.ojo);
        _avLinea(c, cab + Offset(2.2 * s, -2.4 + 0.5 * fase), cab + Offset(6.4 * s, -2.8), 1, _AvCol.pelo);
      }
      _avLinea(c, cab + const Offset(-1.6, 6.4), cab + const Offset(1.6, 6.4), 1, _AvCol.pielSombra);
    }
    // Brazos
    for (final (double, Offset, Offset, Offset) b in brazos) {
      final Offset hom = b.$2, codo = b.$3, mano = b.$4;
      _avPiezas(c, <_AvPieza>[
        _AvPieza.cap(codo, mano, 4.3, 3.3, _AvCol.piel, _AvCol.bordePiel),
        _AvPieza.circ(mano, 4.2, _AvCol.piel, _AvCol.bordePiel),
      ]);
      _avPiezas(c, <_AvPieza>[
        _AvPieza.cap(hom, codo, 6.6, 5, _AvCol.gi, _AvCol.borde),
        _AvPieza.cap(codo, Offset.lerp(codo, mano, 0.38)!, 5.3, 4.8, _AvCol.gi, _AvCol.borde),
        _AvPieza.circ(hom, 7.2, _AvCol.gi, _AvCol.borde),
      ]);
      if (equipo == EquipoMano.garrafa) _avGarrafa(c, mano);
      if (equipo == EquipoMano.mancuerna) {
        _avCirculo(c, mano, 6, _AvCol.metal);
        c.drawCircle(mano, 5.2, _avTrazo(_AvCol.mancuernaAro, 1.3));
        _avCirculo(c, mano, 1.6, _AvCol.eje);
      }
      if (pf != null) _pintarAsa(c, mano, AsaAvatar.d);
    }
  }

  @override
  bool shouldRepaint(_AvatarPainter old) =>
      old.fase != fase || old.tiempo != tiempo || old.escena != escena || old.equipo != equipo;
}

