Future<void> mostrarTecnica(BuildContext context, String ejercicioId, {String? usuario}) {
  return Navigator.of(context).push(MaterialPageRoute<void>(
    builder: (_) => TecnicaEjercicioScreen(ejercicioId: ejercicioId, usuario: usuario),
  ));
}

class TecnicaEjercicioScreen extends StatelessWidget {
  const TecnicaEjercicioScreen({super.key, required this.ejercicioId, this.usuario});
