                    children: <Widget>[
                      for (final MapEntry<GrupoMuscular, double> r in reparto)
                        Container(
                          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 7),
                          decoration: BoxDecoration(
                            color: (r == reparto.first ? TempleColors.dorado : TempleColors.violeta)
