// ===========================================================================
// 41. EL RECORRIDO — tutorial del primer inicio y guía de cada módulo
//
// La primera vez que alguien entra al templo ve un recorrido corto por los
// cinco módulos. Después, la primera vez que abre cada módulo, aparece una
// guía breve de esa pantalla. Lo visto se guarda en la nube, así que no se
// repite al cambiar de teléfono. Todo se puede volver a ver desde los menús.
// ===========================================================================

class GuiaTemplo {
  GuiaTemplo._();
  static final GuiaTemplo instancia = GuiaTemplo._();

  final Map<String, Set<String>> _v = <String, Set<String>>{};

  Set<String> _vistas(String u) => _v.putIfAbsent(u, () => <String>{});

  bool vista(String u, String clave) => _vistas(u).contains(clave);

  void marcar(String u, String clave) {
    if (_vistas(u).add(clave)) NubeTemplo.instancia.marcarCambio();
  }

  void reiniciar(String u) {
    _vistas(u).clear();
    NubeTemplo.instancia.marcarCambio();
  }
}

/// Claves de los módulos en el orden de la barra inferior.
const List<String> clavesModulos = <String>['dojo', 'casa', 'tenshi', 'clan', 'ranked'];

class _Consejo {
  const _Consejo(this.icono, this.titulo, this.texto);
  final IconData icono;
  final String titulo;
  final String texto;
}

class _GuiaModulo {
  const _GuiaModulo({required this.titulo, required this.kanji, required this.lema, required this.consejos});
  final String titulo;
  final String kanji;
  final String lema;
  final List<_Consejo> consejos;
}

const Map<String, _GuiaModulo> _guias = <String, _GuiaModulo>{
  'dojo': _GuiaModulo(
    titulo: 'El Dojo',
    kanji: '道',
    lema: 'Tu día de entrenamiento empieza aquí.',
    consejos: <_Consejo>[
      _Consejo(Icons.bolt_rounded, 'Tu disposición',
          'Según tu sueño, ánimo y descanso, el templo ajusta la sesión de hoy: más corta si llegas con poca energía, más exigente si estás en tu punto.'),
      _Consejo(Icons.play_arrow_rounded, 'El camino de hoy',
          'Pulsa «Comenzar» y registra cada serie con un toque. Todo viene prellenado con lo que hiciste la última vez.'),
      _Consejo(Icons.local_fire_department_outlined, 'Llama, semana y peso del templo',
          'La llama mide tu constancia y se enfría poco a poco, nunca de golpe. El peso del templo suma todos los kilos que has movido.'),
      _Consejo(Icons.more_vert_rounded, 'El menú ⋮',
          'Arriba a la derecha: tu camino, nutrición, recuperación, medidas y fotos, la biblioteca de técnica y tu cuenta.'),
    ],
  ),
  'casa': _GuiaModulo(
