/// Guía de un módulo en una hoja. `forzar` la muestra aunque ya se haya visto.
Future<void> mostrarGuiaModulo(BuildContext context, String clave, {String? usuario}) async {
  final _GuiaModulo? g = _guias[clave];
  if (g == null) return;
  if (usuario != null) GuiaTemplo.instancia.marcar(usuario, clave);
  await showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    backgroundColor: TempleColors.grafito,
    shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
    builder: (BuildContext ctx) => SafeArea(
      top: false,
      child: ConstrainedBox(
