// ===========================================================================
// 42. LA SESIÓN, MÁS AFILADA — sugerencia de carga, calentamiento y discos
//
// Lo que más se valora de las mejores apps de registro: saber qué hiciste la
// última vez, que te propongan el peso de hoy, que el calentamiento se arme
// solo y no tener que hacer cuentas con los discos.
// ===========================================================================

/// La última vez que se hizo ese ejercicio con alguna serie efectiva.
EjercicioSesion? ultimaVezEjercicio(String usuario, String ejercicioId, {String? excluirSesion}) {
  final List<Sesion> ses = AlmacenTemplo.instancia.de(usuario).completadas
    ..sort((Sesion a, Sesion b) => (b.fin ?? b.inicio).compareTo(a.fin ?? a.inicio));
  for (final Sesion s in ses) {
    if (s.id == excluirSesion) continue;
    for (final EjercicioSesion e in s.ejercicios) {
      if (e.ejercicioId == ejercicioId && e.seriesEfectivas.isNotEmpty) return e;
    }
  }
  return null;
}

String textoUltimaVez(EjercicioSesion e) => e.seriesEfectivas
    .map((SerieRegistrada s) => s.peso > 0 ? '${_num(s.peso)}×${s.repeticiones}' : '${s.repeticiones} reps')
    .join(' · ');

class SugerenciaCarga {
  const SugerenciaCarga({required this.peso, required this.reps, required this.texto});
  final double peso;
  final int reps;
  final String texto;
}

double _incrementoDe(Equipo? e) {
  switch (e) {
    case Equipo.barra:
    case Equipo.maquina:
    case Equipo.polea:
      return 2.5;
    case Equipo.mancuerna:
      return 2;
    case Equipo.kettlebell:
      return 4;
    case Equipo.casero:
      return 1;
    default:
      return 0;
  }
}

/// Doble progresión: primero más repeticiones; al llegar a 12 en todas las
/// series, más peso y se vuelve a 8. Si hoy la disposición es baja, sostener.
SugerenciaCarga? sugerirCarga(String usuario, String ejercicioId, {String? sesionActual}) {
  final EjercicioSesion? ultima = ultimaVezEjercicio(usuario, ejercicioId, excluirSesion: sesionActual);
  if (ultima == null) return null;
  final List<SerieRegistrada> ef = ultima.seriesEfectivas;
  final double top = ef.map((SerieRegistrada s) => s.peso).reduce(math.max);
  final List<SerieRegistrada> enTop = ef.where((SerieRegistrada s) => s.peso == top).toList();
  final int repsMin = enTop.map((SerieRegistrada s) => s.repeticiones).reduce(math.min);
  final int repsMax = enTop.map((SerieRegistrada s) => s.repeticiones).reduce(math.max);
  final List<double> rpes = ef.map((SerieRegistrada s) => s.rpe).whereType<double>().toList();
  final double rpeMedio = rpes.isEmpty ? 0 : rpes.reduce((double a, double b) => a + b) / rpes.length;
  final Ejercicio? def = ejercicioPorId(ejercicioId);
  final double inc = _incrementoDe(def?.equipo);
  final int disp = AlmacenTemplo.instancia
      .disposicion(usuario, def == null ? <GrupoMuscular>[] : <GrupoMuscular>[def.grupoPrincipal])
      .valor;

  if (disp < 45) {
    return SugerenciaCarga(
      peso: top,
      reps: repsMin,
      texto: 'Hoy toca sostener: ${top > 0 ? '${_num(top)} kg × ' : ''}$repsMin. Sostener también es entrenar.',
    );
  }
  if (def != null && def.porTiempo) {
    final int seg = math.min(180, repsMax + 5);
    return SugerenciaCarga(peso: top, reps: seg, texto: 'Aguanta $seg s: cinco más que la última vez.');
  }
  if (top <= 0 || inc == 0) {
    // Sin pesas, la progresión es la variante: cuando sobran repeticiones,
    // toca una versión más difícil del mismo movimiento.
    final String? siguiente = varianteMasDificil[ejercicioId];
    if (repsMax >= 20 && siguiente != null) {
      final String nombre = ejercicioPorId(siguiente)?.nombre ?? siguiente;
      return SugerenciaCarga(
        peso: top,
        reps: repsMax,
        texto: 'Ya haces $repsMax: cuando quieras, pasa a «$nombre».',
      );
    }
    return SugerenciaCarga(
      peso: top,
      reps: repsMax + 1,
      texto: 'Una repetición más que la última vez: ${repsMax + 1}.',
    );
  }
  if (rpeMedio >= 9.5) {
    return SugerenciaCarga(
      peso: top,
      reps: repsMin,
      texto: 'La última vez fue al límite. Repite ${_num(top)} kg × $repsMin y hazlo más limpio.',
    );
  }
  if (repsMin >= 12) {
    final double nuevo = top + inc;
    return SugerenciaCarga(
      peso: nuevo,
      reps: 8,
      texto: 'Hiciste 12 en todas: sube a ${_num(nuevo)} kg × 8.',
    );
  }
  final int objetivo = math.min(12, repsMin + 1);
  return SugerenciaCarga(
    peso: top,
    reps: objetivo,
    texto: 'Mismo peso, una más: ${_num(top)} kg × $objetivo.',
  );
}

double _redondear(double v, double paso) => (v / paso).round() * paso;

/// Series de calentamiento hasta el peso de trabajo.
List<SerieRegistrada> seriesCalentamiento(double trabajo, Equipo? equipo) {
  if (trabajo <= 0) return <SerieRegistrada>[];
  final bool barra = equipo == Equipo.barra;
  final double paso = barra ? 2.5 : (equipo == Equipo.mancuerna ? 2 : 2.5);
  final List<List<double>> esquema = <List<double>>[];
  if (barra) {
    if (trabajo >= 40) esquema.add(<double>[20, 10]);
    esquema.add(<double>[0.5, 8]);
    esquema.add(<double>[0.7, 5]);
    if (trabajo >= 60) esquema.add(<double>[0.85, 3]);
  } else {
    esquema.add(<double>[0.5, 10]);
    esquema.add(<double>[0.75, 5]);
  }
  final List<SerieRegistrada> r = <SerieRegistrada>[];
  double ultimo = -1;
  for (final List<double> e in esquema) {
    final double p = e[0] > 1 ? e[0] : _redondear(trabajo * e[0], paso);
    if (p <= 0 || p >= trabajo || p <= ultimo) continue;
    ultimo = p;
    r.add(SerieRegistrada(numero: 0, peso: p, repeticiones: e[1].round(), tipo: TipoSerie.calentamiento));
  }
  return r;
}

// -- Calculadora de discos ----------------------------------------------------

class _Disco {
  const _Disco(this.kg, this.color, this.alto);
  final double kg;
  final Color color;
  final double alto;
}

const List<_Disco> _discos = <_Disco>[
  _Disco(25, Color(0xFFD94A4A), 1.0),
  _Disco(20, Color(0xFF3F74D9), 1.0),
  _Disco(15, Color(0xFFE2C24A), 0.92),
  _Disco(10, Color(0xFF4FB06A), 0.84),
  _Disco(5, Color(0xFFE8E6EE), 0.66),
  _Disco(2.5, Color(0xFF30303A), 0.54),
