class _HojaDiscos extends StatefulWidget {
  const _HojaDiscos({required this.inicial});
  final double inicial;

  @override
  State<_HojaDiscos> createState() => _HojaDiscosState();
}

class _HojaDiscosState extends State<_HojaDiscos> {
  late double _peso = widget.inicial <= 0 ? 60 : widget.inicial;
  double _barra = 20;

  List<_Disco> get _porLado {
    double resto = (_peso - _barra) / 2;
    final List<_Disco> r = <_Disco>[];
    for (final _Disco d in _discos) {
      while (resto + 1e-6 >= d.kg) {
        r.add(d);
        resto -= d.kg;
      }
    }
    return r;
  }

  double get _sobra {
    final double puesto = _porLado.fold<double>(0, (double a, _Disco d) => a + d.kg) * 2 + _barra;
    return _peso - puesto;
  }

  @override
  Widget build(BuildContext context) {
    final List<_Disco> lado = _porLado;
    return SafeArea(
      top: false,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(20, 18, 20, 18),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: <Widget>[
            const Text('Calculadora de discos',
                style: TextStyle(fontSize: 18, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
            const SizedBox(height: 14),
            Row(
              children: <Widget>[
                IconButton(
                  onPressed: () => setState(() => _peso = math.max(_barra, _peso - 2.5)),
                  icon: const Icon(Icons.remove_circle_outline_rounded, color: TempleColors.violetaClaro),
                ),
                Expanded(
                  child: Text('${_num(_peso)} kg',
                      textAlign: TextAlign.center,
                      style: const TextStyle(fontSize: 30, fontWeight: FontWeight.w700, color: TempleColors.blancoLuna)),
                ),
                IconButton(
                  onPressed: () => setState(() => _peso += 2.5),
                  icon: const Icon(Icons.add_circle_outline_rounded, color: TempleColors.violetaClaro),
                ),
              ],
            ),
            const SizedBox(height: 6),
            Wrap(
              spacing: 8,
              alignment: WrapAlignment.center,
              children: <Widget>[
                for (final double b in <double>[20, 15, 10])
                  ChoiceChip(
                    label: Text('Barra ${_num(b)} kg'),
                    selected: _barra == b,
                    onSelected: (_) => setState(() => _barra = b),
                    showCheckmark: false,
                    selectedColor: TempleColors.violeta.withValues(alpha: 0.3),
                    backgroundColor: TempleColors.superficie,
                    side: const BorderSide(color: TempleColors.borde),
                    labelStyle: TextStyle(
                        fontSize: 12, color: _barra == b ? TempleColors.blancoLuna : TempleColors.textoSuave),
                  ),
              ],
            ),
            const SizedBox(height: 18),
            SizedBox(height: 120, child: CustomPaint(painter: _BarraPainter(lado))),
            const SizedBox(height: 14),
            Text(
              lado.isEmpty
                  ? 'Solo la barra.'
                  : 'Por lado: ${lado.map((_Disco d) => _num(d.kg)).join(' + ')} kg',
              textAlign: TextAlign.center,
              style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w600, color: TempleColors.texto),
            ),
            if (_sobra.abs() > 0.01)
              Padding(
                padding: const EdgeInsets.only(top: 6),
                child: Text('No sale exacto con discos estándar: quedan ${_num(_sobra)} kg.',
                    textAlign: TextAlign.center,
                    style: const TextStyle(fontSize: 12.5, color: TempleColors.alertaSuave)),
              ),
          ],
        ),
      ),
    );
  }
}

class _BarraPainter extends CustomPainter {
  const _BarraPainter(this.lado);
  final List<_Disco> lado;

  @override
  void paint(Canvas canvas, Size size) {
    final double cy = size.height / 2;
    final Paint metal = Paint()..color = const Color(0xFF9A93B0);
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(0, cy - 3, size.width, 6), const Radius.circular(3)),
      metal,
    );
    canvas.drawRect(Rect.fromLTWH(size.width / 2 - 40, cy - 4, 80, 8), Paint()..color = const Color(0xFF6E6880));
    for (final int s in <int>[-1, 1]) {
      double x = size.width / 2 + s * 54;
      for (final _Disco d in lado) {
        final double ancho = d.kg >= 10 ? 13 : 9;
        final double alto = size.height * 0.9 * d.alto;
        final Rect r = Rect.fromCenter(center: Offset(x + s * ancho / 2, cy), width: ancho, height: alto);
        canvas.drawRRect(RRect.fromRectAndRadius(r, const Radius.circular(3)), Paint()..color = d.color);
        canvas.drawRRect(
          RRect.fromRectAndRadius(r, const Radius.circular(3)),
          Paint()
            ..color = Colors.black.withValues(alpha: 0.35)
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1,
        );
        x += s * (ancho + 2);
      }
      canvas.drawRect(Rect.fromCenter(center: Offset(x + s * 4, cy), width: 6, height: 18), metal);
    }
  }

  @override
  bool shouldRepaint(_BarraPainter old) => true;
}

// ===========================================================================
// 43. IDEAS DEL TEMPLO — el pergamino del mes y el guerrero que evoluciona
// ===========================================================================

// ---------------------------------------------------------------------------
// 43.1 EL PERGAMINO DEL MES
//
// Un resumen mensual con estética de pergamino: sesiones, kilos, días,
// récords, ascensos y el músculo estrella. Se puede publicar en el Clan con
// un toque (se convierte en imagen dentro de la app).
// ---------------------------------------------------------------------------

const List<String> _kanjiMes = <String>[
  '一月', '二月', '三月', '四月', '五月', '六月', '七月', '八月', '九月', '十月', '十一月', '十二月',
];

class ResumenMes {
  const ResumenMes({
    required this.anio,
    required this.mes,
    required this.sesiones,
    required this.dias,
    required this.kilos,
    required this.minutos,
    required this.series,
    required this.records,
    required this.ascensos,
    required this.mon,
    required this.estrella,
    required this.honorEstrella,
    required this.mejorDia,
  });

  final int anio;
  final int mes;
  final int sesiones;
  final int dias;
  final double kilos;
  final int minutos;
  final int series;
  final int records;
  final int ascensos;
  final int mon;
  final GrupoMuscular? estrella;
  final double honorEstrella;
  final double mejorDia;

  bool get vacio => sesiones == 0;

  static ResumenMes de(String usuario, int anio, int mes) {
    bool enMes(DateTime f) => f.year == anio && f.month == mes;
    final DatosUsuario d = AlmacenTemplo.instancia.de(usuario);
    final List<Sesion> ses = d.completadas.where((Sesion s) => enMes(s.fin ?? s.inicio)).toList();
    final Set<String> dias = <String>{};
    double kilos = 0;
    int minutos = 0;
    int series = 0;
    double mejorDia = 0;
    final Map<GrupoMuscular, double> honor = <GrupoMuscular, double>{};
    for (final Sesion s in ses) {
      final DateTime f = s.fin ?? s.inicio;
      dias.add('${f.year}-${f.month}-${f.day}');
      kilos += s.volumenTotal;
      minutos += s.minutos;
      series += s.seriesEfectivas;
      mejorDia = math.max(mejorDia, s.volumenTotal);
      MotorRanked.honorDe(usuario, s).forEach((GrupoMuscular g, double v) {
        honor[g] = (honor[g] ?? 0) + v;
      });
    }
    GrupoMuscular? estrella;
    double hEstrella = 0;
    honor.forEach((GrupoMuscular g, double v) {
      if (v > hEstrella) {
        hEstrella = v;
        estrella = g;
      }
    });
    final int records = d.records.values.where((RecordPersonal r) => enMes(r.fecha)).length;
    final int ascensos = MotorRanked.de(usuario).ascensos.where((AscensoRanked a) => enMes(a.fecha)).length;
    final int mon = (MonedaTemplo.instancia._historial[usuario] ?? <MovimientoMon>[])
        .where((MovimientoMon m) => m.cantidad > 0 && enMes(m.fecha))
        .fold<int>(0, (int a, MovimientoMon m) => a + m.cantidad);
    return ResumenMes(
      anio: anio,
      mes: mes,
      sesiones: ses.length,
      dias: dias.length,
      kilos: kilos,
      minutos: minutos,
      series: series,
      records: records,
      ascensos: ascensos,
      mon: mon,
      estrella: estrella,
      honorEstrella: hEstrella,
      mejorDia: mejorDia,
    );
  }
}

class PergaminoMesScreen extends StatefulWidget {
  const PergaminoMesScreen({super.key, required this.usuario});
  final String usuario;

  @override
  State<PergaminoMesScreen> createState() => _PergaminoMesScreenState();
}

class _PergaminoMesScreenState extends State<PergaminoMesScreen> {
  late DateTime _mes = DateTime(DateTime.now().year, DateTime.now().month);
  final GlobalKey _captura = GlobalKey();
  bool _publicando = false;

  void _mover(int delta) {
    final DateTime n = DateTime(_mes.year, _mes.month + delta);
    final DateTime hoy = DateTime.now();
    if (n.isAfter(DateTime(hoy.year, hoy.month))) return;
    setState(() => _mes = n);
  }

  Future<void> _publicar(ResumenMes r) async {
    final RenderObject? ro = _captura.currentContext?.findRenderObject();
    if (ro is! RenderRepaintBoundary) return;
    setState(() => _publicando = true);
    try {
      final ui.Image img = await ro.toImage(pixelRatio: 3);
      final ByteData? bytes = await img.toByteData(format: ui.ImageByteFormat.png);
      if (bytes == null) throw const AuthFailure('No se pudo crear la imagen.');
      final String id = uuidClan();
      final ClanMedio medio = await MediosClan.instancia.subir(
        archivo: XFile.fromData(bytes.buffer.asUint8List(), name: 'pergamino.png', mimeType: 'image/png'),
        publicacionId: id,
        indice: 0,
        video: false,
      );
      final String mes = kMesesTemplo[r.mes - 1];
      await ClanRepo.instancia.publicar(
        id: id,
        texto: 'Mi pergamino de $mes: ${r.sesiones} sesiones y ${_num(r.kilos)} kg movidos. '
            '#PergaminoDelMes #TempleOfStrength',
        medios: <ClanMedio>[medio],
      );
      if (mounted) avisoClan(context, 'Publicado en el Clan');
    } catch (e) {
      if (mounted) avisoClan(context, SesionTemplo.mensajeDe(e), error: true);
    } finally {
      if (mounted) setState(() => _publicando = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final ResumenMes r = ResumenMes.de(widget.usuario, _mes.year, _mes.month);
    final DateTime hoy = DateTime.now();
    final bool esActual = _mes.year == hoy.year && _mes.month == hoy.month;
    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: Column(
          children: <Widget>[
            const BarraClan(titulo: 'Pergamino del mes', subtitulo: 'Tu mes, escrito en tinta'),
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: <Widget>[
                IconButton(
                  onPressed: () => _mover(-1),
                  icon: const Icon(Icons.chevron_left_rounded, color: TempleColors.textoSuave),
                ),
                Text('${kMesesTemplo[_mes.month - 1]} ${_mes.year}',
                    style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                IconButton(
                  onPressed: esActual ? null : () => _mover(1),
                  icon: Icon(Icons.chevron_right_rounded,
                      color: esActual ? TempleColors.borde : TempleColors.textoSuave),
                ),
              ],
            ),
            Expanded(
              child: ListView(
                padding: EdgeInsets.fromLTRB(
                    TempleSpace.borde, 4, TempleSpace.borde, 28 + MediaQuery.paddingOf(context).bottom),
                children: <Widget>[
                  RepaintBoundary(
                    key: _captura,
                    child: _Pergamino(resumen: r, usuario: widget.usuario),
                  ),
                  const SizedBox(height: 18),
                  if (!r.vacio)
                    DojoPrimaryButton(
                      texto: 'Publicar en el Clan',
                      cargando: _publicando,
                      onPressed: () => _publicar(r),
                    ),
                  if (esActual) ...<Widget>[
                    const SizedBox(height: 10),
                    const Text('El mes aún no termina: tu pergamino se sigue escribiendo.',
                        textAlign: TextAlign.center,
                        style: TextStyle(fontSize: 12, color: TempleColors.textoTenue)),
                  ],
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

