String _frasePergamino(ResumenMes r) {
  if (r.vacio) return 'El camino espera.';
  if (r.dias >= 16) return 'La constancia ya es tu forma de vivir.';
  if (r.dias >= 10) return 'Un mes de verdadero trabajo.';
  if (r.dias >= 5) return 'Cada semana sumaste.';
  return 'Toda montaña empieza con una piedra.';
}

// ---------------------------------------------------------------------------
// 43.2 EL GUERRERO QUE EVOLUCIONA
//
// Tu avatar de frente, con el mismo trazo anime que el maestro de técnica.
// Cada músculo engrosa según su rango de Ranked: quien entrena solo pecho verá
// un guerrero con pecho de Shōgun y piernas de Ashigaru. El aura (llamas,
// chispas y el círculo del suelo) toma el color del rango del cuerpo. Respira,
// parpadea y la cinta ondea. Con el Pase se viste de samurái o de kimono.
// ---------------------------------------------------------------------------

class GuerreroRanked extends StatefulWidget {
  const GuerreroRanked({
    super.key,
    required this.rangos,
    required this.rangoCuerpo,
    this.altura = 220,
    this.aspecto,
  });
  final Map<GrupoMuscular, int> rangos;
  final int rangoCuerpo;
  final double altura;

  /// Null = el que eligió la persona (si su Pase lo permite).
  final AspectoGuerrero? aspecto;

  @override
  State<GuerreroRanked> createState() => _GuerreroRankedState();
}

class _GuerreroRankedState extends State<GuerreroRanked>
    with TickerDecorativo {
  late final AnimationController _c =
      AnimationController(vsync: this, duration: const Duration(milliseconds: 4000));

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final bool reducir = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    if (reducir) {
      _c.stop();
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      height: widget.altura,
      child: ListenableBuilder(
        listenable: Listenable.merge(<Listenable>[PreferenciasPase.instancia.aspecto, PaseTemplo.instancia]),
        builder: (BuildContext context, _) {
          final AspectoGuerrero aspecto = widget.aspecto ?? PreferenciasPase.instancia.vigente;
          return RepaintBoundary(
            child: AnimatedBuilder(
              animation: _c,
              builder: (BuildContext context, _) => CustomPaint(
                size: Size.infinite,
                painter: _GuerreroPainter(rangos: widget.rangos, cuerpo: widget.rangoCuerpo, t: _c.value, aspecto: aspecto),
              ),
            ),
          );
        },
      ),
    );
  }
}

/// Colores de cada aspecto del guerrero.
class _RopaGuerrero {
  const _RopaGuerrero(this.top, this.topSombra, this.borde, this.baja, this.bajaBorde);
  final Color top;
  final Color topSombra;
  final Color borde;
  final Color baja;
  final Color bajaBorde;

  static _RopaGuerrero de(AspectoGuerrero a) => switch (a) {
        AspectoGuerrero.gi => const _RopaGuerrero(
            Color(0xFFEEE8F8), Color(0xFFCEC4E6), Color(0xFF9F92C8), Color(0xFF2A2240), Color(0xFF4E4378)),
        AspectoGuerrero.samurai => const _RopaGuerrero(
            Color(0xFF6A1A26), Color(0xFF4A101A), Color(0xFF2A0A10), Color(0xFF22182E), Color(0xFF3A2A4E)),
        AspectoGuerrero.kimono => const _RopaGuerrero(
            Color(0xFF1A1424), Color(0xFF120E1A), Color(0xFF3A2E52), Color(0xFF3A3550), Color(0xFF26223A)),
      };
}

class _GuerreroPainter extends CustomPainter {
  const _GuerreroPainter({required this.rangos, required this.cuerpo, required this.t, required this.aspecto});
  final Map<GrupoMuscular, int> rangos;
  final int cuerpo;
  final double t;
  final AspectoGuerrero aspecto;

  static const double _tau = math.pi * 2;

  /// 0 (sin rango) → 1 (Kami).
  double _f(GrupoMuscular g) => ((rangos[g] ?? -1) + 1) / (RangosRanked.maximo + 1);

  static double _hash(double a, double b) {
    final double x = math.sin(a * 127.1 + b * 311.7) * 43758.5453;
    return x - x.floorToDouble();
  }

  static Color _al(Color c, double a) => c.withValues(alpha: a.clamp(0.0, 1.0));

  void _glow(Canvas c, Offset p, double r, Color col, double a) {
    if (r <= 0 || a <= 0) return;
    c.drawCircle(
        p,
        r,
        Paint()
          ..shader = RadialGradient(colors: <Color>[_al(col, a), _al(col, 0)])
              .createShader(Rect.fromCircle(center: p, radius: r)));
  }

  @override
  void paint(Canvas canvas, Size size) {
    final double k = math.min(size.width / 200, size.height / 220);
    canvas.save();
    canvas.translate((size.width - 200 * k) / 2, (size.height - 220 * k) / 2);
    canvas.scale(k);
    _pintar(canvas);
    canvas.restore();
  }

  void _pintar(Canvas c) {
    final _RopaGuerrero ropa = _RopaGuerrero.de(aspecto);
    final Color aura = cuerpo < 0 ? ColoresTradicion.violeta : RangosRanked.color(cuerpo);
    final double resp = math.sin(t * _tau);
    final double peso = math.sin(t * _tau + 1.2) * 0.6;
    final double fuerza = 0.35 + 0.65 * math.max(0, cuerpo + 1) / (RangosRanked.maximo + 1);

    // -- Aura: lenguas de fuego que suben detrás del cuerpo ----------------
    _glow(c, const Offset(100, 120), 92, aura, 0.10 + 0.14 * fuerza + 0.03 * resp);
    for (int i = 0; i < 9; i++) {
      final double u = (i - 4) / 4;
      final double x0 = 100 + u * 46;
      final double alto = (70 + 50 * fuerza) * (1 - u.abs() * 0.35) * (0.8 + 0.2 * math.sin(t * _tau * 2 + i * 1.7));
      final double ola = math.sin(t * _tau * 3 + i * 2.1) * 6;
      c.drawPath(
        Path()
          ..moveTo(x0 - 11, 206)
          ..quadraticBezierTo(x0 - 14 + ola * 0.3, 206 - alto * 0.55, x0 + ola, 206 - alto)
          ..quadraticBezierTo(x0 + 12 + ola * 0.3, 206 - alto * 0.5, x0 + 11, 206)
          ..close(),
        Paint()
          ..shader = ui.Gradient.linear(
              const Offset(0, 206), Offset(0, 206 - alto), <Color>[_al(aura, 0.30 * fuerza + 0.08), _al(aura, 0)]),
      );
    }
    // -- Círculo del rango en el suelo --------------------------------------
    c.save();
    c.translate(100, 207);
    c.scale(1, 0.24);
    c.drawCircle(Offset.zero, 58, _avTrazo(_al(aura, 0.55), 2.4));
    for (int i = 0; i < 18; i++) {
      final double a = t * _tau * 0.5 + i * _tau / 18;
      c.drawArc(Rect.fromCircle(center: Offset.zero, radius: 66), a, 0.12, false,
          _avTrazo(_al(aura, i % 3 == 0 ? 0.7 : 0.35), 3)..strokeCap = StrokeCap.butt);
    }
    c.restore();
    c.save();
    c.translate(100, 207);
    c.scale(1, 0.18);
    _glow(c, Offset.zero, 52, Colors.black, 0.55);
    c.restore();

    // -- Medidas que crecen con los rangos ----------------------------------
    final double hom = 25 + 8 * _f(GrupoMuscular.hombros);
    final double pecho = 19 + 7 * math.max(_f(GrupoMuscular.pecho), _f(GrupoMuscular.espalda));
    final double cint = 14 + 1.5 * _f(GrupoMuscular.abdomen);
    final double rBrazo = 5.4 + 2.8 * math.max(_f(GrupoMuscular.biceps), _f(GrupoMuscular.triceps));
    final double rAnte = 4.5 + 1.8 * _f(GrupoMuscular.antebrazos);
    final double rMuslo = 8.2 + 3.4 * _f(GrupoMuscular.piernas);
    final double rPierna = 6 + 2.4 * _f(GrupoMuscular.pantorrillas);
    final double yHom = 68 - resp * 0.7, yPecho = 90 - resp * 0.9;
    const double yCint = 113, yCad = 124;

    // -- Piernas ---------------------------------------------------------------
    for (final double s in <double>[-1, 1]) {
      final Offset cad = Offset(100 + 10 * s + peso * 0.5, yCad);
      final Offset rod = Offset(100 + 13 * s + peso, 163);
      final Offset tob = Offset(100 + 14 * s + peso * 0.4, 199);
      final List<(Offset, Offset, double, double)> tramos = aspecto == AspectoGuerrero.gi
          ? <(Offset, Offset, double, double)>[(cad, rod, rMuslo, rMuslo * 0.78), (rod, tob, rMuslo * 0.78, rPierna * 0.7)]
          : <(Offset, Offset, double, double)>[
              (cad, rod, rMuslo + 1.5, rMuslo + 2.5),
              (rod, tob.translate(0, -2), rMuslo + 2.5, rMuslo + 3),
            ];
      // Dos pasadas: bordes y luego rellenos (sin aros en la rodilla).
      for (final (Offset, Offset, double, double) p in tramos) {
        _avCapsula(c, p.$1, p.$2, p.$3 + 1.5, p.$4 + 1.5, ropa.bajaBorde);
      }
      for (final (Offset, Offset, double, double) p in tramos) {
        _avCapsula(c, p.$1, p.$2, p.$3, p.$4, ropa.baja);
      }
      if (aspecto == AspectoGuerrero.kimono) {
        for (int k = -1; k <= 1; k++) {
          _avLinea(c, cad.translate(k * 4.0, 6), tob.translate(k * 5.0, -4), 1, const Color(0xE64A4466));
        }
      }
      _avCapsula(c, Offset(tob.dx - s, 201), Offset(tob.dx + s * 6, 203), 3.6, 3.2, const Color(0xFF1E1630));
    }

    // -- Brazos (se calculan aquí; se pintan delante del torso) -------------
    final List<(double, Offset, Offset, Offset)> brazos = <(double, Offset, Offset, Offset)>[
      for (final double s in <double>[-1, 1])
        (
          s,
          Offset(100 + hom * s, yHom + 3),
          Offset(100 + (hom + 5 + rBrazo * 0.3) * s, 100 - resp * 0.5),
          Offset(100 + (hom + 3) * s + math.sin(t * _tau + s) * 0.6, 129 - resp * 0.3),
        ),
    ];

    // -- Torso -------------------------------------------------------------------
    final Path torso = Path()
      ..moveTo(100 - hom + 4, yHom)
      ..quadraticBezierTo(100, yHom - 6, 100 + hom - 4, yHom)
      ..quadraticBezierTo(100 + pecho + 3, yPecho - 6, 100 + pecho, yPecho)
      ..quadraticBezierTo(100 + cint + 2, yCint - 8, 100 + cint, yCint)
      ..lineTo(100 + cint + 2, yCad + 4)
      ..lineTo(100 - cint - 2, yCad + 4)
      ..lineTo(100 - cint, yCint)
      ..quadraticBezierTo(100 - cint - 2, yCint - 8, 100 - pecho, yPecho)
      ..quadraticBezierTo(100 - pecho - 3, yPecho - 6, 100 - hom + 4, yHom)
      ..close();
    c.drawPath(torso, _avTrazo(ropa.borde, 3));
    c.drawPath(torso, Paint()..color = ropa.top);
    // Sombra lateral del torso.
    c.save();
    c.clipPath(torso);
    c.drawRect(
      const Rect.fromLTWH(60, 50, 80, 90),
      Paint()
        ..shader = ui.Gradient.linear(Offset(100 - pecho, 0), Offset(100 + pecho, 0),
            <Color>[_al(ropa.topSombra, 0.9), _al(ropa.topSombra, 0), _al(ropa.topSombra, 0.25)], <double>[0, 0.35, 1]),
    );
    c.restore();

    switch (aspecto) {
      case AspectoGuerrero.gi:
        // Cuello en V y solapas cruzadas.
        final double fp = _f(GrupoMuscular.pecho);
        c.drawPath(
          Path()
            ..moveTo(93, yHom - 3)
            ..lineTo(100, yHom + 15 + fp * 3)
            ..lineTo(107, yHom - 3)
            ..close(),
          Paint()..color = _AvCol.piel,
        );
        c.drawPath(
          Path()
            ..moveTo(92, yHom - 3)
            ..quadraticBezierTo(98, yHom + 22, 108, yCint - 2),
          _avTrazo(ropa.borde, 1.3),
        );
        _avLinea(c, Offset(107.5, yHom - 3), Offset(100.5, yHom + 15), 1.3, ropa.borde);
        // El pecho se marca al subir de rango.
        if (fp > 0.1) {
          c.drawPath(
            Path()
              ..moveTo(100 - pecho * 0.75, yPecho - 3)
              ..quadraticBezierTo(100 - pecho * 0.35, yPecho + 2, 97, yPecho - 2),
            _avTrazo(_al(_AvCol.giLinea, 0.4 + fp * 0.5), 1),
          );
        }
      case AspectoGuerrero.samurai:
        // Dō lacado con cordones dorados en filas.
        for (int k = 0; k < 5; k++) {
          final double y = yPecho - 8 + k * 6.5;
          final double an = (k < 2 ? pecho : cint + (pecho - cint) * (1 - (k - 2) / 3)) - 2;
          _avLinea(c, Offset(100 - an, y), Offset(100 + an, y), 1.4, _al(const Color(0xFFE8B65A), 0.85));
          for (int m = -2; m <= 2; m++) {
            _avCirculo(c, Offset(100 + m * an * 0.42, y), 0.9, const Color(0xFFFFE7A8));
          }
        }
        // Kusazuri: placas que cuelgan de la cintura.
        for (int k = -2; k <= 2; k++) {
          final double x = 100 + k * 7.2;
          final Rect placa = Rect.fromLTWH(x - 3.4, yCad + 2, 6.8, 15 - k.abs() * 1.5);
          c.drawRect(placa, Paint()..color = const Color(0xFF4A101A));
          c.drawRect(placa, _avTrazo(const Color(0xFF2A0A10), 1.2));
          _avLinea(c, Offset(x - 3, yCad + 8), Offset(x + 3, yCad + 8), 1, _al(const Color(0xFFE8B65A), 0.8));
        }
      case AspectoGuerrero.kimono:
        // Cuello blanco cruzado, haori con borde violeta y el mon dorado.
        c.drawPath(
          Path()
            ..moveTo(93, yHom - 3)
            ..lineTo(100, yHom + 17)
            ..lineTo(107, yHom - 3)
            ..close(),
          Paint()..color = ColoresTradicion.blancoLuna,
        );
        c.drawPath(
          Path()
            ..moveTo(91, yHom - 3)
            ..quadraticBezierTo(95, yHom + 25, 96, yCad + 2),
          _avTrazo(ColoresTradicion.violeta, 2.2),
        );
        c.drawPath(
          Path()
            ..moveTo(109, yHom - 3)
            ..quadraticBezierTo(105, yHom + 25, 104, yCad + 2),
          _avTrazo(ColoresTradicion.violeta, 2.2),
        );
        for (final double s in <double>[-1, 1]) {
          final Offset m = Offset(100 + s * pecho * 0.55, yPecho - 6);
          _avCirculo(c, m, 3.6, const Color(0xFFE8B65A));
          _avCirculo(c, m.translate(0.9, -0.6), 2.8, ropa.top);
        }
    }
    // Obi / cinturón con nudo y cintas que ondean.
    final Color obi = switch (aspecto) {
      AspectoGuerrero.samurai => const Color(0xFFE8B65A),
      AspectoGuerrero.kimono => const Color(0xFF3A2E52),
      AspectoGuerrero.gi => _AvCol.obi,
    };
    c.drawRect(Rect.fromLTWH(100 - cint - 1.5, yCint - 3, (cint + 1.5) * 2, 6), Paint()..color = obi);
    if (aspecto != AspectoGuerrero.samurai) {
      final double ola = math.sin(t * _tau * 2) * 1.2;
      _avCirculo(c, const Offset(100, yCint), 2.8, obi);
      _avLinea(c, const Offset(100, yCint), Offset(96 - ola, yCint + 12), 2.4, obi);
      _avLinea(c, const Offset(100, yCint), Offset(104 + ola, yCint + 13), 2.4, obi);
    }

    // -- Cabeza --------------------------------------------------------------------
    final Offset cab = Offset(100, 45 - resp * 0.6);
    _avCapsula(c, Offset(100, yHom - 1), cab.translate(0, 7), 4.2, 4, _AvCol.pielSombra);
    _avCirculo(c, cab, 11.2, _AvCol.piel);
    final Paint pelo = Paint()..color = _AvCol.pelo;
    Path tri(Offset a, Offset b, Offset d) => Path()
      ..moveTo(a.dx, a.dy)
      ..lineTo(b.dx, b.dy)
      ..lineTo(d.dx, d.dy)
      ..close();
    if (aspecto == AspectoGuerrero.samurai) {
      // Kabuto con la luna creciente dorada (el maedate).
      final Paint casco = Paint()..color = const Color(0xFF241828);
      c.drawArc(Rect.fromCircle(center: cab.translate(0, -1), radius: 13), math.pi * 1.02, math.pi * 0.96, true, casco);
      c.drawRect(Rect.fromLTWH(cab.dx - 14.5, cab.dy - 3, 29, 3.2), casco);
      final Paint ala = Paint()..color = const Color(0xFF3A2A3E);
      c.drawPath(tri(cab.translate(-14, 0), cab.translate(-18, 8), cab.translate(-11, 4)), ala);
      c.drawPath(tri(cab.translate(14, 0), cab.translate(18, 8), cab.translate(11, 4)), ala);
      c.drawPath(
        Path.combine(
          PathOperation.difference,
          Path()..addOval(Rect.fromCircle(center: cab.translate(0, -13), radius: 7)),
          Path()..addOval(Rect.fromCircle(center: cab.translate(0, -16.5), radius: 6.6)),
        ),
        Paint()..color = const Color(0xFFF2D493),
      );
      _glow(c, cab.translate(0, -9), 9, const Color(0xFFF2D493), 0.3 + 0.2 * math.sin(t * _tau * 2));
    } else {
      c.drawArc(Rect.fromCircle(center: cab.translate(0, -0.5), radius: 12.2), math.pi * 1.04, math.pi * 0.92, false, pelo);
      for (final (double, double, double) m in const <(double, double, double)>[(-7, 6, 4.5), (-1.5, 7, 6), (5, 6, 4)]) {
        c.drawPath(
            tri(cab.translate(m.$1 - m.$2 / 2, -7), cab.translate(m.$1 + 1.2, -7 + m.$3), cab.translate(m.$1 + m.$2 / 2, -7)),
            pelo);
      }
      for (final double s in <double>[-1, 1]) {
        c.drawPath(tri(cab.translate(8 * s, -9), cab.translate(13.5 * s, -2), cab.translate(10.5 * s, -1)), pelo);
      }
      for (final double g in <double>[-150, -122, -95, -68, -40]) {
        final double r = g * math.pi / 180;
        Offset q(double a, double rad) => cab + Offset(math.cos(a) * rad, -0.5 + math.sin(a) * rad);
        c.drawPath(tri(q(r - 0.2, 11.4), q(r + 0.12, 15.6), q(r + 0.2, 11.4)), pelo);
      }
      if (aspecto == AspectoGuerrero.gi) {
        _avLinea(c, cab.translate(-11.6, -4.5), cab.translate(11.6, -4.5), 3.4, _AvCol.cinta);
        final double ola = math.sin(t * _tau * 3) * 2.4;
        c.drawPath(
          Path()
            ..moveTo(cab.dx + 11, cab.dy - 4.5)
            ..quadraticBezierTo(cab.dx + 18, cab.dy - 3 + ola, cab.dx + 24, cab.dy + 5 - ola),
          _avTrazo(_AvCol.cinta, 2.6),
        );
        c.drawPath(
          Path()
            ..moveTo(cab.dx + 11, cab.dy - 4)
            ..quadraticBezierTo(cab.dx + 16, cab.dy + 1 - ola, cab.dx + 18, cab.dy + 9),
          _avTrazo(_AvCol.cintaOscura, 2.6),
        );
      } else {
        // Moño alto del kimono.
        _avCirculo(c, cab.translate(0, -14), 4.6, _AvCol.pelo);
        _avLinea(c, cab.translate(-5, -14), cab.translate(5, -14), 1.6, ColoresTradicion.violeta);
      }
    }
    // Ojos con parpadeo y cejas decididas.
    final double parp = ((t * 3) % 1.0) < 0.05 ? 0.15 : 1.0;
    for (final double s in <double>[-1, 1]) {
      c.drawOval(Rect.fromCenter(center: cab.translate(4.3 * s, 1.5), width: 2.8, height: 4.2 * parp),
          Paint()..color = _AvCol.ojo);
      if (parp > 0.5) _avCirculo(c, cab.translate(4.3 * s - 0.4, 0.8), 0.5, Colors.white);
      _avLinea(c, cab.translate(2.2 * s, -2.6), cab.translate(6.6 * s, -3.4), 1.1, _AvCol.pelo);
    }
    _avLinea(c, cab.translate(-1.6, 6.6), cab.translate(1.6, 6.6), 1, _AvCol.pielSombra);

    // -- Brazos delante --------------------------------------------------------
    final double manga = aspecto == AspectoGuerrero.kimono ? 1.35 : 1;
    for (final (double, Offset, Offset, Offset) b in brazos) {
      final double s = b.$1;
      final Offset h = b.$2, codo = b.$3, mano = b.$4;
      _avCapsula(c, codo, mano, rAnte + 1.5, rAnte * 0.8 + 1.5, _AvCol.bordePiel);
      _avCapsula(c, codo, mano, rAnte, rAnte * 0.8, _AvCol.piel);
      _avCirculo(c, mano.translate(0, 1), rAnte * 0.95 + 1.4, _AvCol.bordePiel);
      _avCirculo(c, mano.translate(0, 1), rAnte * 0.95, _AvCol.piel);
      // Dos pasadas: bordes y luego rellenos, para que el hombro no deje un aro.
      _avCapsula(c, h, codo, (rBrazo + 0.8) * manga + 1.5, rBrazo * 0.85 * manga + 1.5, ropa.borde);
      if (aspecto != AspectoGuerrero.samurai) _avCirculo(c, h, rBrazo + 2.4, ropa.borde);
      _avCapsula(c, h, codo, (rBrazo + 0.8) * manga, rBrazo * 0.85 * manga, ropa.top);
      if (aspecto == AspectoGuerrero.samurai) {
        // Sode: hombreras en láminas.
        for (int k = 0; k < 3; k++) {
          final Rect lamina = Rect.fromLTWH(h.dx - 8 + s * 3, h.dy - 2 + k * 5, 16, 5);
          c.drawRect(lamina, Paint()..color = const Color(0xFF4A101A));
          c.drawRect(lamina, _avTrazo(const Color(0xFF2A0A10), 1.2));
          _avLinea(c, Offset(lamina.left + 1, lamina.center.dy), Offset(lamina.right - 1, lamina.center.dy), 0.9,
              _al(const Color(0xFFE8B65A), 0.8));
        }
      } else {
        _avCirculo(c, h, rBrazo + 0.9, ropa.top);
        if (aspecto == AspectoGuerrero.kimono) {
          _avLinea(c, codo.translate(-s, 6), codo.translate(s * 7, 4), 1.6, ColoresTradicion.violeta);
        }
      }
    }

    // -- Chispas del aura ------------------------------------------------------
    final int n = 4 + (10 * fuerza).round();
    final Color chispa = cuerpo >= 18 ? const Color(0xFFFFF4CC) : aura;
    for (int i = 0; i < n; i++) {
      final double fase = (t * (1 + _hash(i.toDouble(), 5)) + _hash(5, i.toDouble())) % 1.0;
      final Offset p = Offset(100 + (_hash(i.toDouble(), 7) - 0.5) * 110 + math.sin(fase * _tau + i) * 5, 200 - fase * 160);
      _avCirculo(c, p, 0.8 + 1.2 * _hash(i.toDouble(), 9), _al(chispa, 0.8 * math.sin(fase * math.pi)));
    }
  }

  @override
  bool shouldRepaint(_GuerreroPainter old) =>
      old.t != t || old.rangos != rangos || old.aspecto != aspecto || old.cuerpo != cuerpo;
}

// ===========================================================================
// 44. RECOMPENSAS ANIMADAS — celebración, miniaturas del taller
//
// Conseguir algo tiene que sentirse: rayos que giran, chispas que estallan y
// la pieza nueva entrando con un rebote. Se usa al comprar en el taller, al
// estrenar un marco y al terminar una sesión que desbloquea algo.
// ===========================================================================

