  'cielo_sangre', 'cielo_cosmos', 'cielo_oro', 'cielo_fugaces', 'cielo_linternas', 'cielo_kintsugi',
  'luna_llena', 'luna_creciente', 'luna_roja', 'luna_eclipse', 'luna_velada', 'luna_gemela',
  'luna_dorada', 'luna_kanji', 'luna_halo', 'luna_conejo',
  'mont_colinas', 'mont_volcan', 'mont_islas', 'mont_cristal', 'mont_acantilado', 'mont_agujas',
  'agua_lago', 'agua_cascada', 'agua_helada', 'agua_laca', 'agua_espejo', 'agua_oro', 'agua_toro', 'agua_olas',
  'est_santuario', 'est_pagoda', 'est_puente', 'est_dojo', 'est_castillo',
  'est_linterna', 'est_campana', 'est_faroles', 'est_puerta_luna', 'est_torii_dorado',
  'veg_sakura', 'veg_sakura_nocturno', 'veg_arce', 'veg_bambu', 'veg_pino', 'veg_glicina', 'veg_loto',
  'veg_sauce', 'veg_susuki',
  'cri_zorro', 'cri_tigre', 'cri_grulla', 'cri_cuervos', 'cri_carpa', 'cri_dragon', 'cri_luciernagas',
  'cri_espiritus', 'cri_mariposas', 'cri_grullas_papel', 'cri_fenix', 'cri_kitsune', 'cri_koi_dorado',
