/// Reloj quieto para las miniaturas: se dibujan una sola vez.
final ValueNotifier<double> _relojQuieto = ValueNotifier<double>(0.25);

/// Viñeta en pequeño. Quieta en las listas, viva en la celebración.
class MiniVineta extends StatelessWidget {
  const MiniVineta({super.key, required this.config, this.ancho = 64, this.alto = 40, this.animada = false});

  final Map<CapaVineta, String> config;
  final double ancho;
  final double alto;
  final bool animada;

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(8),
      child: SizedBox(
        width: ancho,
        height: alto,
        child: animada
            ? VinetaPerfil(config: config, altura: alto)
            : RepaintBoundary(
                child: CustomPaint(
                  size: Size(ancho, alto),
                  painter: _LienzoPainter(reloj: _relojQuieto, config: config),
                ),
              ),
      ),
    );
  }
}

/// La pieza puesta sobre lo que ya tienes, para enseñarla.
Map<CapaVineta, String> configConPieza(String usuario, String piezaId) {
  final Map<CapaVineta, String> c = Map<CapaVineta, String>.from(MotorProgresion.instancia.de(usuario).vineta);
  final PiezaTienda? t = TiendaVineta.porId(piezaId);
  final PiezaVineta? l = PiezasVineta.porId(piezaId);
  final CapaVineta? capa = t?.capa ?? l?.capa;
  if (capa != null) c[capa] = piezaId;
  return c;
}

/// Celebración a pantalla completa. Devuelve true si se pulsó la acción
/// principal (por ejemplo «Ponérmela»).
Future<bool> mostrarCelebracion(
  BuildContext context, {
  required String titulo,
  required String nombre,
  String? detalle,
  required Color color,
  required Widget vista,
  String boton = 'Genial',
  String? botonSecundario,
  SonidoTemplo? sonido = SonidoTemplo.desbloqueo,
}) async {
  HapticFeedback.heavyImpact();
  if (sonido != null) sonar(sonido);
  final bool? r = await showGeneralDialog<bool>(
    context: context,
    barrierDismissible: true,
    barrierLabel: titulo,
    barrierColor: Colors.black.withValues(alpha: 0.72),
    transitionDuration: const Duration(milliseconds: 320),
    pageBuilder: (BuildContext ctx, _, __) => _Celebracion(
      titulo: titulo,
      nombre: nombre,
      detalle: detalle,
      color: color,
      vista: vista,
      boton: boton,
      botonSecundario: botonSecundario,
    ),
    transitionBuilder: (BuildContext ctx, Animation<double> a, _, Widget hijo) => FadeTransition(
      opacity: CurvedAnimation(parent: a, curve: Curves.easeOut),
      child: hijo,
    ),
  );
  return r ?? false;
}

class _Celebracion extends StatefulWidget {
  const _Celebracion({
    required this.titulo,
    required this.nombre,
    required this.detalle,
    required this.color,
    required this.vista,
    required this.boton,
    required this.botonSecundario,
  });

  final String titulo;
  final String nombre;
  final String? detalle;
  final Color color;
  final Widget vista;
  final String boton;
  final String? botonSecundario;

  @override
  State<_Celebracion> createState() => _CelebracionState();
}

class _CelebracionState extends State<_Celebracion>
    with TickerDecorativo {
  @override
  bool get animarEnWeb => true;
  late final AnimationController _entrada =
      AnimationController(vsync: this, duration: const Duration(milliseconds: 1600));
  late final AnimationController _giro = AnimationController(vsync: this, duration: const Duration(seconds: 9));

  @override
  void initState() {
    super.initState();
    _entrada.forward();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final bool reducir = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    if (reducir) {
      _entrada.value = 1;
      _giro.stop();
    } else if (!_giro.isAnimating) {
      _giro.repeat();
    }
  }

  @override
  void dispose() {
    _entrada.dispose();
    _giro.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Material(
        type: MaterialType.transparency,
        child: SizedBox(
          width: 320,
          child: AnimatedBuilder(
            animation: Listenable.merge(<Listenable>[_entrada, _giro]),
            builder: (BuildContext context, _) {
              final double e = _entrada.value;
              final double rebote = Curves.elasticOut.transform((e / 0.7).clamp(0.0, 1.0));
              final double texto = Curves.easeOut.transform(((e - 0.35) / 0.5).clamp(0.0, 1.0));
              return Column(
                mainAxisSize: MainAxisSize.min,
                children: <Widget>[
                  SizedBox(
                    width: 320,
                    height: 260,
                    child: Stack(
                      alignment: Alignment.center,
                      children: <Widget>[
                        Positioned.fill(
                          child: CustomPaint(
                            painter: _RayosPainter(color: widget.color, giro: _giro.value, entrada: e),
                          ),
                        ),
                        Transform.scale(scale: 0.4 + 0.6 * rebote, child: widget.vista),
                      ],
                    ),
                  ),
                  Opacity(
                    opacity: texto,
                    child: Transform.translate(
                      offset: Offset(0, 12 * (1 - texto)),
                      child: Column(
                        children: <Widget>[
                          Text(widget.titulo.toUpperCase(),
                              style: TextStyle(
                                  fontSize: 12, letterSpacing: 3, fontWeight: FontWeight.w600, color: widget.color)),
                          const SizedBox(height: 6),
                          Text(widget.nombre,
                              textAlign: TextAlign.center,
                              style: const TextStyle(
                                  fontSize: 24, fontWeight: FontWeight.w700, color: TempleColors.blancoLuna)),
                          if (widget.detalle != null) ...<Widget>[
                            const SizedBox(height: 6),
                            Padding(
                              padding: const EdgeInsets.symmetric(horizontal: 20),
                              child: Text(widget.detalle!,
                                  textAlign: TextAlign.center,
                                  style: const TextStyle(fontSize: 13, height: 1.45, color: TempleColors.textoSuave)),
                            ),
                          ],
                          const SizedBox(height: 22),
                          Padding(
                            padding: const EdgeInsets.symmetric(horizontal: 24),
                            child: DojoPrimaryButton(
                              texto: widget.boton,
                              onPressed: () => Navigator.of(context).pop(true),
                            ),
                          ),
                          if (widget.botonSecundario != null)
                            TextButton(
                              onPressed: () => Navigator.of(context).pop(false),
                              child: Text(widget.botonSecundario!,
                                  style: const TextStyle(color: TempleColors.textoSuave)),
                            ),
                        ],
                      ),
                    ),
                  ),
                ],
              );
            },
          ),
        ),
      ),
    );
  }
}

/// Rayos de luz que giran y chispas que estallan al aparecer.
class _RayosPainter extends CustomPainter {
  const _RayosPainter({required this.color, required this.giro, required this.entrada});
  final Color color;
  final double giro;
  final double entrada;

  @override
  void paint(Canvas canvas, Size size) {
    final Offset c = size.center(Offset.zero);
    final double r = size.shortestSide * 0.62;
    final double aparecer = Curves.easeOut.transform((entrada / 0.5).clamp(0.0, 1.0));
    // Halo
    canvas.drawCircle(
      c,
      r * 0.75,
      Paint()
        ..shader = RadialGradient(colors: <Color>[color.withValues(alpha: 0.35 * aparecer), color.withValues(alpha: 0)])
            .createShader(Rect.fromCircle(center: c, radius: r * 0.75)),
    );
    // Rayos
    const int n = 12;
    for (int i = 0; i < n; i++) {
      final double a = giro * math.pi * 2 + i * math.pi * 2 / n;
      const double ancho = math.pi / n * 0.5;
      canvas.drawPath(
        Path()
          ..moveTo(c.dx, c.dy)
          ..lineTo(c.dx + math.cos(a - ancho) * r, c.dy + math.sin(a - ancho) * r)
          ..lineTo(c.dx + math.cos(a + ancho) * r, c.dy + math.sin(a + ancho) * r)
          ..close(),
        Paint()
          ..shader = RadialGradient(colors: <Color>[color.withValues(alpha: 0.22 * aparecer), color.withValues(alpha: 0)])
              .createShader(Rect.fromCircle(center: c, radius: r)),
      );
    }
    // Chispas: salen disparadas, frenan y caen.
    final math.Random rnd = math.Random(7);
    final double p = entrada.clamp(0.0, 1.0);
    for (int i = 0; i < 34; i++) {
      final double a = rnd.nextDouble() * math.pi * 2;
      final double v = 0.45 + rnd.nextDouble() * 0.55;
      final double dist = r * 0.8 * v * Curves.easeOutCubic.transform(p);
      final Offset pos = c + Offset(math.cos(a), math.sin(a)) * dist + Offset(0, 60 * p * p);
      final double vida = (1 - p).clamp(0.0, 1.0);
      if (vida <= 0) continue;
      final bool petalo = i.isEven;
      final Paint pintura = Paint()
        ..color = (petalo ? const Color(0xFFF6B8D8) : Color.lerp(color, Colors.white, 0.4)!).withValues(alpha: vida);
      if (petalo) {
        canvas.save();
        canvas.translate(pos.dx, pos.dy);
        canvas.rotate(a + p * 6);
        canvas.drawOval(const Rect.fromLTWH(-3.5, -2, 7, 4), pintura);
        canvas.restore();
      } else {
        canvas.drawCircle(pos, 1.6 + rnd.nextDouble() * 1.6, pintura);
      }
    }
  }

  @override
  bool shouldRepaint(_RayosPainter old) => old.giro != giro || old.entrada != entrada || old.color != color;
}

/// Al terminar una sesión: celebra lo que se acaba de desbloquear (hasta dos
/// cosas, para no convertirlo en una cola de ventanas).
Future<void> celebrarDesbloqueos(
  BuildContext context,
  String usuario, {
  required List<PiezaVineta> piezas,
  required List<MarcoSello> marcos,
}) async {
  int mostradas = 0;
  for (final PiezaVineta p in piezas) {
    if (mostradas >= 2 || !context.mounted) return;
    mostradas++;
    final bool poner = await mostrarCelebracion(
      context,
      titulo: 'Pieza ganada',
      nombre: p.nombre,
      detalle: p.comoSeGana,
      color: p.rara ? TempleColors.dorado : TempleColors.violetaClaro,
      vista: MiniVineta(config: configConPieza(usuario, p.id), ancho: 240, alto: 130, animada: true),
      boton: 'Ponérmela',
      botonSecundario: 'Ahora no',
    );
    if (poner) MotorProgresion.instancia.colocarPieza(usuario, p.capa, p.id);
  }
  final IdentidadUsuario id = AlmacenIdentidad.instancia.de(usuario);
  for (final MarcoSello m in marcos) {
    if (mostradas >= 2 || !context.mounted) return;
    mostradas++;
    final IdentidadUsuario prueba = IdentidadUsuario(usuario: usuario)
      ..paleta = id.paleta
      ..simbolo = id.simbolo
      ..foto = id.foto
      ..marco = m;
    final bool poner = await mostrarCelebracion(
      context,
      titulo: 'Marco ganado',
      nombre: m.etiqueta,
      detalle: m.pista,
      color: m.rareza?.color ?? TempleColors.violetaClaro,
      vista: SelloUsuario(
        identidad: prueba,
        kanji: kanjiDeEspiritu(SesionTemplo.instancia.actual?.espiritu ?? ''),
        nivel: NivelTemplo.desdeXp(AlmacenTemplo.instancia.de(usuario).xpGeneral).nivel,
        size: 120,
        animar: true,
      ),
      boton: 'Ponérmelo',
      botonSecundario: 'Ahora no',
    );
    if (poner) {
      id.marco = m;
      NubeTemplo.instancia.marcarCambio();
    }
  }
}

// ===========================================================================
// 45. EL PASE DEL TEMPLO — la suscripción
//
//   45.1  Estado del Pase: manda el servidor, el teléfono lo recuerda
//   45.2  Límites de la versión gratis y contador de uso
//   45.3  El emblema y el botón que brilla
//   45.4  Muro suave, alerta tras el recorrido, insignia y estilos de nombre
//   45.5  La pantalla del Pase
//   45.6  Temporada del Pase y ofrenda mensual
//   45.7  Tu progreso: gráficas por ejercicio, mapa de calor y comparar
//   45.8  Informe semanal de Tenshi
//   45.9  Exportar entrenamientos
//
// Regla de oro: la versión gratis está completa. Registrar, la nube, el XP,
// el honor del Ranked, el clima y los banners animados son de todos. El Pase
// vende profundidad, comodidad y estilo; nunca honor ni XP.
//
// Quién tiene Pase lo decide el servidor (tabla `pases`). El teléfono guarda
// una copia para funcionar sin internet, pero lo que cuesta dinero (Tenshi)
// lo vuelve a comprobar la función del servidor en cada mensaje.
// ===========================================================================

// ---------------------------------------------------------------------------
// 45.1 ESTADO DEL PASE
// ---------------------------------------------------------------------------

enum PlanPase { ninguno, prueba, mensual, anual, regalo }

extension DatosPlanPase on PlanPase {
  String get etiqueta => switch (this) {
        PlanPase.ninguno => 'Sin Pase',
        PlanPase.prueba => 'Semana de prueba',
        PlanPase.mensual => 'Pase mensual',
        PlanPase.anual => 'Pase anual',
        PlanPase.regalo => 'Pase de regalo',
      };

  static PlanPase desde(Object? v) {
    for (final PlanPase p in PlanPase.values) {
      if (p.name == v) return p;
    }
    return PlanPase.ninguno;
  }
}

/// Precios de referencia. Cuando la app esté en las tiendas, los reales
/// llegan de Google Play / App Store (ya convertidos a la moneda local).
class PreciosPase {
  const PreciosPase._();
  static const String mensual = '4,99 US\$';
  static const String anual = '34,99 US\$';
  static const String mensualCop = '14.900 COP';
  static const String anualCop = '99.900 COP';
  static const String anualPorMes = '2,92 US\$';
  static const int ahorroAnual = 42; // % frente a 12 meses sueltos
}

class EstadoPase {
  const EstadoPase({this.plan = PlanPase.ninguno, this.vence, this.pruebaUsada = false});

  final PlanPase plan;

  /// Null con un plan puesto = sin fecha de fin (regalo del templo).
  final DateTime? vence;
  final bool pruebaUsada;

  bool get activo => plan != PlanPase.ninguno && (vence == null || vence!.isAfter(DateTime.now()));

  int get diasRestantes {
    final DateTime? v = vence;
    if (v == null) return 9999;
    final int h = v.difference(DateTime.now()).inHours;
    return h <= 0 ? 0 : (h / 24).ceil();
  }

  Map<String, dynamic> toMap() => <String, dynamic>{
        'plan': plan.name,
        'vence': vence?.toUtc().toIso8601String(),
        'prueba_usada': pruebaUsada,
      };

  factory EstadoPase.desdeMapa(Map<String, dynamic> m) {
    final Object? v = m['vence'];
    return EstadoPase(
      plan: DatosPlanPase.desde(m['plan']),
      vence: v is String ? DateTime.tryParse(v)?.toLocal() : null,
      pruebaUsada: m['prueba_usada'] == true,
    );
  }
}

class PaseTemplo extends ChangeNotifier {
  PaseTemplo._();
  static final PaseTemplo instancia = PaseTemplo._();

  EstadoPase _e = const EstadoPase();
  EstadoPase get estado => _e;
  bool get activo => _e.activo;

  static const String _clave = 'pase_templo_v1_';

  /// Lee la copia del teléfono y luego pregunta al servidor.
  Future<void> cargar() async {
    final String? uid = SesionTemplo.instancia.uid;
    if (uid == null) return;
    try {
      final SharedPreferences sp = await SharedPreferences.getInstance();
      final String? s = sp.getString('$_clave$uid');
      if (s != null) {
        final Object? m = convert.jsonDecode(s);
        if (m is Map) {
          _e = EstadoPase.desdeMapa(Map<String, dynamic>.from(m));
          notifyListeners();
        }
      }
    } catch (e) {
      debugPrint('Pase: no se pudo leer la copia local: $e');
    }
    await UsoPase.instancia.cargar(uid);
    await refrescar();
  }

  Future<void> refrescar() async {
    if (SesionTemplo.instancia.uid == null) return;
    try {
      final Object? r = await supa.rpc('mi_pase');
      if (r is Map) _poner(EstadoPase.desdeMapa(Map<String, dynamic>.from(r)));
    } catch (e) {
      // Sin internet o el servidor aún sin la tabla: se queda la copia local.
      debugPrint('Pase: no se pudo consultar: $e');
    }
  }

  Future<void> _poner(EstadoPase e) async {
    final bool cambio = e.plan != _e.plan || e.vence != _e.vence || e.pruebaUsada != _e.pruebaUsada;
    _e = e;
    if (!e.activo) _retirarExclusivos();
    if (cambio) notifyListeners();
    final String? uid = SesionTemplo.instancia.uid;
    if (uid == null) return;
    try {
      final SharedPreferences sp = await SharedPreferences.getInstance();
      await sp.setString('$_clave$uid', convert.jsonEncode(e.toMap()));
    } catch (_) {}
  }

  /// Siete días gratis, una vez por cuenta. Devuelve un mensaje si falla.
  Future<String?> iniciarPrueba() async {
    try {
      final Object? r = await supa.rpc('iniciar_prueba_pase');
      if (r is Map) await _poner(EstadoPase.desdeMapa(Map<String, dynamic>.from(r)));
      return activo ? null : 'No se pudo activar la prueba. Inténtalo de nuevo.';
    } on PostgrestException catch (e) {
      return e.message;
    } catch (e) {
      return SesionTemplo.mensajeDe(e);
    }
  }

  /// La compra real se conecta aquí (RevenueCat o in_app_purchase). Hasta
  /// que la app esté en las tiendas, solo explica qué pasa.
  Future<String?> comprar(PlanPase plan) async {
    return 'Las compras dentro de la app se activan cuando Temple of Strength '
        'esté publicada en Google Play y en la App Store. Cuando llegue ese '
        'día, podrás unirte desde aquí mismo.';
  }

  Future<String?> restaurar() async {
    await refrescar();
    return activo ? null : 'No encontramos un Pase activo en esta cuenta.';
  }

  /// Al terminar el Pase, lo exclusivo vuelve a lo de siempre. Nada de lo
  /// ganado entrenando se toca.
  void _retirarExclusivos() {
    final String? u = SesionTemplo.instancia.actual?.usuario;
    if (u == null) return;
    bool cambio = false;
    final EstadoProgreso prog = MotorProgresion.instancia.de(u);
    for (final CapaVineta c in CapaVineta.values) {
      final String? id = prog.vineta[c];
      if (id != null && PiezasPase.es(id)) {
        final String? base = PiezasVineta.configInicial()[c];
        if (base != null) {
          prog.vineta[c] = base;
        } else {
          prog.vineta.remove(c);
        }
        cambio = true;
      }
    }
    final IdentidadUsuario id = AlmacenIdentidad.instancia.de(u);
    if (id.marco.dePase) {
      id.marco = MarcoSello.simple;
      cambio = true;
    }
    if (id.estiloNombre != null) {
      id.estiloNombre = null;
      cambio = true;
    }
    // Las redes de más dejan de verse (se conservan las dos primeras).
    final Map<String, String> dos = RedesSociales.visibles(id.redes, limite: 2);
    if (dos.length < id.redes.length) {
      id.redes
        ..clear()
        ..addAll(dos);
      cambio = true;
    }
    if (cambio) NubeTemplo.instancia.marcarCambio();
  }
}

// ---------------------------------------------------------------------------
// 45.2 LÍMITES Y USO
// ---------------------------------------------------------------------------

class LimitesPase {
  const LimitesPase._();

  static const int tenshiDia = 10;
  static const int recuerdosGratis = 8;
  static const int recuerdosPase = 40;
  static const int fotosMes = 4;
  static const int diasHistorial = 90;
  /// Subir videos al Clan es solo con el Pase (1.4.1): ocupan mucho espacio.
  static const int videoPase = 60;
  static const int monOfrenda = 300;
  static const int diasEntreCiclos = 30;

  static bool get pase => PaseTemplo.instancia.activo;
}

/// Cuánto se usó hoy lo que tiene límite. Se guarda por cuenta y por día.
class UsoPase extends ChangeNotifier {
  UsoPase._();
  static final UsoPase instancia = UsoPase._();

  static const String _clave = 'pase_uso_v1_';
  String? _uid;
  String _dia = '';
  int _tenshi = 0;

  /// Mensajes ganados hoy con anuncios y anuncios vistos (sección 48.9).
  int _extra = 0;
  int _anuncios = 0;

  static String _hoy() {
    final DateTime d = DateTime.now();
    return '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
  }

  void _alDia() {
    final String h = _hoy();
    if (_dia != h) {
      _dia = h;
      _tenshi = 0;
      _extra = 0;
      _anuncios = 0;
    }
  }

  Future<void> cargar(String uid) async {
    _uid = uid;
    try {
      final SharedPreferences sp = await SharedPreferences.getInstance();
      final String? s = sp.getString('$_clave$uid');
      if (s != null) {
        final Object? m = convert.jsonDecode(s);
        if (m is Map) {
          _dia = (m['dia'] as String?) ?? '';
          _tenshi = (m['tenshi'] as num?)?.toInt() ?? 0;
          _extra = (m['extra'] as num?)?.toInt() ?? 0;
          _anuncios = (m['anuncios'] as num?)?.toInt() ?? 0;
        }
      }
    } catch (_) {}
    _alDia();
    // El servidor lleva la cuenta de verdad; se toma la mayor.
    try {
      final Object? r = await supa.rpc('mi_cupo_tenshi');
      if (r is Map) {
        aplicarCupo(r, avisar: false);
      }
    } catch (_) {
      try {
        final Object? r = await supa.rpc('mi_uso_tenshi');
        if (r is num && r.toInt() > _tenshi) _tenshi = r.toInt();
      } catch (_) {}
    }
    notifyListeners();
  }

  /// Lo que dice el servidor de hoy: usados, extra y anuncios.
  void aplicarCupo(Map<dynamic, dynamic> r, {bool avisar = true}) {
    _alDia();
    final int usados = (r['usados'] as num?)?.toInt() ?? 0;
    final int extra = (r['extra'] as num?)?.toInt() ?? 0;
    final int anuncios = (r['anuncios'] as num?)?.toInt() ?? 0;
    if (usados > _tenshi) _tenshi = usados;
    _extra = math.max(_extra, extra);
    _anuncios = math.max(_anuncios, anuncios);
    _guardar();
    if (avisar) notifyListeners();
  }

  int get anunciosTenshiHoy {
    _alDia();
    return _anuncios;
  }

  /// Cuántos mensajes con la mente completa hay hoy en total sin Pase.
  int get tenshiLimiteHoy {
    _alDia();
    return LimitesPase.tenshiDia + _extra;
  }

  Future<void> _guardar() async {
    final String? uid = _uid;
    if (uid == null) return;
    try {
      final SharedPreferences sp = await SharedPreferences.getInstance();
      await sp.setString('$_clave$uid',
          convert.jsonEncode(<String, Object>{'dia': _dia, 'tenshi': _tenshi, 'extra': _extra, 'anuncios': _anuncios}));
    } catch (_) {}
  }

  int get tenshiHoy {
    _alDia();
    return _tenshi;
  }

  int get tenshiRestantes => math.max(0, tenshiLimiteHoy - tenshiHoy);

  /// La mente completa (la que cuesta) está disponible ahora.
  bool get tenshiDisponible => LimitesPase.pase || tenshiHoy < tenshiLimiteHoy;

  void sumarTenshi() {
    _alDia();
    _tenshi++;
    _guardar();
    notifyListeners();
  }

  /// El servidor dijo que hoy ya no: el contador se pone al tope.
  void agotarTenshi() {
    _alDia();
    _tenshi = math.max(_tenshi, tenshiLimiteHoy);
    _guardar();
    notifyListeners();
  }
}

// ---------------------------------------------------------------------------
// 45.3 EL EMBLEMA Y EL BOTÓN QUE BRILLA
//
// Una luna creciente dorada con el torii dentro, sobre un disco violeta. Late
// siempre un poco: sin Pase, más fuerte, para que se vea desde cualquier
// pantalla; con Pase, una luz tranquila de «ya es tuyo».
// ---------------------------------------------------------------------------

class EmblemaPase extends StatefulWidget {
  const EmblemaPase({super.key, this.size = 30, this.rayos = false, this.animado = true});
  final double size;

  /// Rayos que giran detrás (en la pantalla del Pase y en las alertas).
  final bool rayos;
  final bool animado;

  @override
  State<EmblemaPase> createState() => _EmblemaPaseState();
}

class _EmblemaPaseState extends State<EmblemaPase>
    with TickerDecorativo {
  late final AnimationController _c = AnimationController(vsync: this, duration: const Duration(milliseconds: 3200));

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final bool reducir = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    if (!widget.animado || reducir) {
      _c.stop();
      _c.value = 0.3;
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: PaseTemplo.instancia,
      builder: (BuildContext context, _) => RepaintBoundary(
        child: AnimatedBuilder(
          animation: _c,
          builder: (BuildContext context, _) => CustomPaint(
            size: Size.square(widget.size),
            painter: _EmblemaPasePainter(t: _c.value, activo: PaseTemplo.instancia.activo, rayos: widget.rayos),
          ),
        ),
      ),
    );
  }
}

class _EmblemaPasePainter extends CustomPainter {
  const _EmblemaPasePainter({required this.t, required this.activo, required this.rayos});
  final double t;
  final bool activo;
  final bool rayos;

  static const Color _oro = Color(0xFFF2D493);
  static const Color _oroHondo = Color(0xFFB8862A);

  @override
  void paint(Canvas canvas, Size size) {
    const double tau = math.pi * 2;
    final Offset c = size.center(Offset.zero);
    final double r = size.shortestSide / 2;
    final double latido = 0.5 + 0.5 * math.sin(t * tau);

    // Luz que se escapa del botón: llama la atención sin gritar.
    final double fuerza = activo ? 0.30 + 0.10 * latido : 0.42 + 0.30 * latido;
    canvas.drawCircle(
      c,
      r * 1.45,
      Paint()
        ..shader = RadialGradient(colors: <Color>[
          _oro.withValues(alpha: fuerza),
          ColoresTradicion.violeta.withValues(alpha: fuerza * 0.35),
          Colors.transparent,
        ], stops: const <double>[0, 0.55, 1])
            .createShader(Rect.fromCircle(center: c, radius: r * 1.45)),
    );

    if (rayos) {
      for (int i = 0; i < 12; i++) {
        final double a = t * tau * 0.25 + i * tau / 12;
        final double largo = r * (1.55 + 0.25 * math.sin(t * tau * 2 + i));
        canvas.drawPath(
          Path()
            ..moveTo(c.dx + math.cos(a - 0.07) * r * 0.9, c.dy + math.sin(a - 0.07) * r * 0.9)
            ..lineTo(c.dx + math.cos(a) * largo, c.dy + math.sin(a) * largo)
            ..lineTo(c.dx + math.cos(a + 0.07) * r * 0.9, c.dy + math.sin(a + 0.07) * r * 0.9)
            ..close(),
          Paint()..color = _oro.withValues(alpha: 0.16),
        );
      }
    }

    // Disco.
    canvas.drawCircle(
      c,
      r * 0.92,
      Paint()
        ..shader = const RadialGradient(
          colors: <Color>[Color(0xFF3A2470), Color(0xFF140B28)],
          center: Alignment(-0.3, -0.4),
        ).createShader(Rect.fromCircle(center: c, radius: r * 0.92)),
    );
    // Aro dorado con un brillo que gira.
    canvas.drawCircle(
      c,
      r * 0.86,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = r * 0.10
        ..shader = SweepGradient(
          colors: const <Color>[_oroHondo, Color(0xFFFFF4CC), _oro, _oroHondo, Color(0xFFE8B65A), _oroHondo],
          stops: const <double>[0, 0.12, 0.25, 0.55, 0.75, 1],
          transform: GradientRotation(t * tau),
        ).createShader(Rect.fromCircle(center: c, radius: r)),
    );

    // Luna creciente dorada.
    final Path luna = Path.combine(
      PathOperation.difference,
      Path()..addOval(Rect.fromCircle(center: c.translate(-r * 0.05, r * 0.02), radius: r * 0.52)),
      Path()..addOval(Rect.fromCircle(center: c.translate(r * 0.2, -r * 0.12), radius: r * 0.45)),
    );
    canvas.drawPath(
      luna,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: const <Color>[Color(0xFFFFF4CC), _oro, Color(0xFFD49A36)],
        ).createShader(Rect.fromCircle(center: c, radius: r * 0.55)),
    );

    // El torii dentro del hueco de la luna.
    final double a = r * 0.40;
    final Offset b = c.translate(r * 0.14, r * 0.26);
    final Paint trazo = Paint()
      ..color = const Color(0xFFFFF4CC)
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeWidth = a * 0.10;
    canvas.drawPath(
      Path()
        ..moveTo(b.dx - a * 0.5, b.dy - a * 0.92)
        ..quadraticBezierTo(b.dx, b.dy - a * 0.8, b.dx + a * 0.5, b.dy - a * 0.92),
      trazo,
    );
    canvas.drawLine(Offset(b.dx - a * 0.36, b.dy - a * 0.62), Offset(b.dx + a * 0.36, b.dy - a * 0.62),
        trazo..strokeWidth = a * 0.08);
    canvas.drawLine(Offset(b.dx - a * 0.26, b.dy - a * 0.84), Offset(b.dx - a * 0.3, b.dy), trazo..strokeWidth = a * 0.09);
    canvas.drawLine(Offset(b.dx + a * 0.26, b.dy - a * 0.84), Offset(b.dx + a * 0.3, b.dy), trazo);

    // Destello que recorre el aro y una estrella que titila.
    final Offset chispa = c + Offset(math.cos(t * tau - math.pi / 2), math.sin(t * tau - math.pi / 2)) * (r * 0.86);
    _estrella(canvas, chispa, r * 0.22 * (0.6 + 0.4 * latido), Colors.white.withValues(alpha: 0.95));
    final double tit = math.max(0.0, math.sin(t * tau * 2 + 1));
    _estrella(canvas, c.translate(r * 0.42, -r * 0.4), r * 0.16 * tit, const Color(0xFFFFF4CC).withValues(alpha: tit));
  }

  void _estrella(Canvas c, Offset p, double s, Color col) {
    if (s <= 0.2) return;
    c.drawPath(
      Path()
        ..moveTo(p.dx, p.dy - s)
        ..quadraticBezierTo(p.dx, p.dy, p.dx + s, p.dy)
        ..quadraticBezierTo(p.dx, p.dy, p.dx, p.dy + s)
        ..quadraticBezierTo(p.dx, p.dy, p.dx - s, p.dy)
        ..quadraticBezierTo(p.dx, p.dy, p.dx, p.dy - s)
        ..close(),
      Paint()..color = col,
    );
  }

  @override
  bool shouldRepaint(_EmblemaPasePainter old) => old.t != t || old.activo != activo || old.rayos != rayos;
}

/// El botón del Pase. Va al lado del menú ⋮ en todos los módulos y en la
/// cabecera de cada sección.
class BotonPase extends StatelessWidget {
  const BotonPase({super.key, this.size = 40});
  final double size;

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: PaseTemplo.instancia,
      builder: (BuildContext context, _) {
        final bool activo = PaseTemplo.instancia.activo;
        return Tooltip(
          message: activo ? 'Tu Pase del Templo' : 'El Pase del Templo',
          child: Semantics(
            button: true,
            label: activo ? 'Tu Pase del Templo' : 'Conocer el Pase del Templo',
            child: InkResponse(
              radius: size * 0.6,
              onTap: () {
                HapticFeedback.selectionClick();
                abrirPase(context);
              },
              child: SizedBox(
                width: size,
                height: size,
                child: Center(child: EmblemaPase(size: size * 0.72)),
              ),
            ),
          ),
        );
      },
    );
  }
}

Future<void> abrirPase(BuildContext context, {String? desde}) {
  return Navigator.of(context).push(PageRouteBuilder<void>(
    transitionDuration: const Duration(milliseconds: 420),
    reverseTransitionDuration: const Duration(milliseconds: 260),
    pageBuilder: (_, __, ___) => PaseTemploScreen(desde: desde),
    transitionsBuilder: (BuildContext c, Animation<double> a, _, Widget hijo) => FadeTransition(
      opacity: CurvedAnimation(parent: a, curve: Curves.easeOut),
      child: ScaleTransition(
        scale: Tween<double>(begin: 0.96, end: 1).animate(CurvedAnimation(parent: a, curve: TempleMotion.entrada)),
        child: hijo,
      ),
    ),
  ));
}

/// Botón dorado del Pase, con un brillo que lo cruza.
class BotonOro extends StatefulWidget {
  const BotonOro({super.key, required this.texto, required this.onPressed, this.cargando = false, this.icono});
  final String texto;
  final VoidCallback? onPressed;
  final bool cargando;
  final IconData? icono;

  @override
  State<BotonOro> createState() => _BotonOroState();
}

class _BotonOroState extends State<BotonOro>
    with TickerDecorativo {
  late final AnimationController _c = AnimationController(vsync: this, duration: const Duration(milliseconds: 2600));

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final bool reducir = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    if (reducir) {
      _c.stop();
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      height: 56,
      child: DecoratedBox(
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(TempleRadius.campo),
          boxShadow: <BoxShadow>[
            BoxShadow(color: const Color(0xFFE8B65A).withValues(alpha: 0.35), blurRadius: 26, spreadRadius: -6, offset: const Offset(0, 8)),
          ],
        ),
        child: ClipRRect(
          borderRadius: BorderRadius.circular(TempleRadius.campo),
          child: Material(
            color: Colors.transparent,
            child: Ink(
              decoration: const BoxDecoration(
                gradient: LinearGradient(colors: <Color>[Color(0xFFB8862A), Color(0xFFF2D493), Color(0xFFD49A36)]),
              ),
              child: InkWell(
                onTap: widget.cargando ? null : widget.onPressed,
                child: Stack(
                  fit: StackFit.expand,
                  children: <Widget>[
                    AnimatedBuilder(
                      animation: _c,
                      builder: (BuildContext context, _) => CustomPaint(painter: _BrilloBotonPainter(_c.value)),
                    ),
                    Center(
                      child: widget.cargando
                          ? const SizedBox(
                              width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2.2, color: Color(0xFF2A1A08)))
                          : Row(
                              mainAxisSize: MainAxisSize.min,
                              children: <Widget>[
                                if (widget.icono != null) ...<Widget>[
                                  Icon(widget.icono, size: 19, color: const Color(0xFF2A1A08)),
                                  const SizedBox(width: 8),
                                ],
                                Flexible(
                                  child: Text(
                                    widget.texto,
                                    overflow: TextOverflow.ellipsis,
                                    style: const TextStyle(
                                        fontSize: 15, fontWeight: FontWeight.w700, letterSpacing: 0.8, color: Color(0xFF2A1A08)),
                                  ),
                                ),
                              ],
                            ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class _BrilloBotonPainter extends CustomPainter {
  const _BrilloBotonPainter(this.t);
  final double t;

  @override
  void paint(Canvas canvas, Size size) {
    // Una franja de luz cruza el botón y luego descansa.
    final double f = (t * 1.6) % 1.6;
    if (f > 1) return;
    final double x = -size.width * 0.3 + f * size.width * 1.6;
    final Rect r = Rect.fromLTWH(x, 0, size.width * 0.25, size.height);
    canvas.save();
    canvas.translate(x + r.width / 2, size.height / 2);
    canvas.skew(-0.4, 0);
    canvas.translate(-(x + r.width / 2), -size.height / 2);
    canvas.drawRect(
      r,
      Paint()
        ..shader = LinearGradient(colors: <Color>[
          Colors.white.withValues(alpha: 0),
          Colors.white.withValues(alpha: 0.45),
          Colors.white.withValues(alpha: 0),
        ]).createShader(r),
    );
    canvas.restore();
  }

  @override
  bool shouldRepaint(_BrilloBotonPainter old) => old.t != t;
}

