/// Si una persona del Clan tiene el Pase (el servidor lo sella en su perfil).
bool tienePaseSello(Map<String, dynamic> sello) {
  final Object? v = sello['pase_hasta'];
  if (v is! String) return false;
  final DateTime? d = DateTime.tryParse(v);
  return d != null && d.isAfter(DateTime.now());
}

/// Estilos de nombre del Pase (se ven en el Clan).
enum EstiloNombre { oro, aurora, sakura, luna }

extension DatosEstiloNombre on EstiloNombre {
  String get etiqueta => switch (this) {
        EstiloNombre.oro => 'Oro imperial',
        EstiloNombre.aurora => 'Aurora',
        EstiloNombre.sakura => 'Sakura',
        EstiloNombre.luna => 'Luz de luna',
      };

  List<Color> get colores => switch (this) {
        EstiloNombre.oro => const <Color>[Color(0xFFFFF4CC), Color(0xFFE8B65A), Color(0xFFB8862A)],
        EstiloNombre.aurora => const <Color>[Color(0xFF5BE3A8), Color(0xFF6FD3FF), Color(0xFFB79CFF)],
        EstiloNombre.sakura => const <Color>[Color(0xFFFFE2F2), Color(0xFFF6A8D6), Color(0xFFE07AB8)],
        EstiloNombre.luna => const <Color>[Color(0xFFFFFFFF), Color(0xFFD9CCFF), Color(0xFF9A7BFF)],
      };

  static EstiloNombre? desde(Object? v) {
    for (final EstiloNombre e in EstiloNombre.values) {
      if (e.name == v) return e;
    }
    return null;
  }
}

/// Nombre con el estilo del Pase (degradado) o normal si no lo tiene.
class NombreConEstilo extends StatelessWidget {
  const NombreConEstilo(this.texto, {super.key, required this.estilo, required this.style, this.insignia = false});
  final String texto;
  final EstiloNombre? estilo;
  final TextStyle style;
  final bool insignia;

  @override
  Widget build(BuildContext context) {
    final EstiloNombre? e = estilo;
    final Widget nombre = Text(texto,
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        style: e == null ? style : style.copyWith(color: Colors.white));
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Flexible(
          child: e == null
              ? nombre
              : ShaderMask(
                  blendMode: BlendMode.srcIn,
                  shaderCallback: (Rect r) => LinearGradient(colors: e.colores).createShader(r),
                  child: nombre,
                ),
        ),
        if (insignia) ...<Widget>[
          const SizedBox(width: 5),
          InsigniaPase(size: (style.fontSize ?? 14) * 0.95),
        ],
      ],
    );
  }
}

