/// La alerta que aparece al terminar el recorrido del templo. Una sola vez.
Future<void> mostrarAlertaPase(BuildContext context) {
  HapticFeedback.mediumImpact();
  return showGeneralDialog<void>(
    context: context,
    barrierDismissible: true,
    barrierLabel: 'El Pase del Templo',
    barrierColor: Colors.black.withValues(alpha: 0.75),
    transitionDuration: const Duration(milliseconds: 480),
    pageBuilder: (BuildContext ctx, _, __) => const _AlertaPase(),
    transitionBuilder: (BuildContext ctx, Animation<double> a, _, Widget hijo) {
      final Animation<double> curva = CurvedAnimation(parent: a, curve: Curves.easeOutBack);
      return FadeTransition(
        opacity: a,
        child: ScaleTransition(scale: Tween<double>(begin: 0.86, end: 1).animate(curva), child: hijo),
      );
    },
  );
}

