class PaseTemploScreen extends StatefulWidget {
  const PaseTemploScreen({super.key, this.desde});

  /// Desde dónde se abrió (para el texto de bienvenida).
  final String? desde;

  @override
  State<PaseTemploScreen> createState() => _PaseTemploScreenState();
}

class _PaseTemploScreenState extends State<PaseTemploScreen>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;

  late final AnimationController _cielo = AnimationController(vsync: this, duration: const Duration(seconds: 24));
  final PageController _vitrina = PageController(viewportFraction: 0.84);
  PlanPase _plan = PlanPase.anual;
  bool _cargando = false;
  int _pagina = 0;

  String? get _usuario => SesionTemplo.instancia.actual?.usuario;

  @override
  void initState() {
    super.initState();
    PaseTemplo.instancia.refrescar();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final bool reducir = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    if (reducir) {
      _cielo.stop();
    } else if (!_cielo.isAnimating) {
      _cielo.repeat();
    }
  }

  @override
  void dispose() {
    _cielo.dispose();
    _vitrina.dispose();
    super.dispose();
  }

  Future<void> _unirme() async {
    final PaseTemplo p = PaseTemplo.instancia;
    setState(() => _cargando = true);
    final String? error = p.estado.pruebaUsada ? await p.comprar(_plan) : await p.iniciarPrueba();
    if (!mounted) return;
    setState(() => _cargando = false);
    if (error != null) {
      await _aviso(error);
      return;
    }
    final String? u = _usuario;
    if (u != null) SesionTemplo.instancia.sincronizarIdentidad(u);
    await mostrarCelebracion(
      context,
      titulo: 'Bienvenido al Pase',
      sonido: SonidoTemplo.pase,
      nombre: p.estado.plan.etiqueta,
      detalle: p.estado.vence == null
          ? 'Todo el templo es tuyo.'
          : 'Tienes ${p.estado.diasRestantes} días de todo el templo. Tenshi ya no tiene límite.',
      color: const Color(0xFFE8B65A),
      vista: const EmblemaPase(size: 110, rayos: true),
      boton: 'Explorar',
    );
    if (mounted) setState(() {});
  }

  Future<void> _restaurar() async {
    setState(() => _cargando = true);
    final String? error = await PaseTemplo.instancia.restaurar();
    if (!mounted) return;
    setState(() => _cargando = false);
    avisoClan(context, error ?? 'Tu Pase está activo en esta cuenta.', error: error != null);
  }

  Future<void> _aviso(String texto) => showModalBottomSheet<void>(
        context: context,
        backgroundColor: TempleColors.grafito,
        shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
        builder: (BuildContext ctx) => SafeArea(
          top: false,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(22, 22, 22, 14),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: <Widget>[
                const EmblemaPase(size: 56),
                const SizedBox(height: 14),
                Text(texto,
                    textAlign: TextAlign.center,
                    style: const TextStyle(fontSize: 14, height: 1.5, color: TempleColors.texto)),
                const SizedBox(height: 14),
                DojoPrimaryButton(texto: 'Entendido', onPressed: () => Navigator.of(ctx).pop()),
              ],
            ),
          ),
        ),
      );

  Future<void> _ofrenda(String u) async {
    if (!OfrendaPase.cobrar(u)) return;
    await mostrarCelebracion(
      context,
      titulo: 'Ofrenda del mes',
      sonido: SonidoTemplo.mon,
      nombre: '+${LimitesPase.monOfrenda} mon',
      detalle: 'Gracias por sostener el templo. Están en tu bolsa para el Taller.',
      color: const Color(0xFFE8B65A),
      vista: const IconoMon(size: 72),
      boton: 'Listo',
    );
    if (mounted) setState(() {});
  }

  String _fecha(DateTime d) {
    const List<String> meses = <String>['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
    return '${d.day} ${meses[d.month - 1]} ${d.year}';
  }

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: PaseTemplo.instancia,
      builder: (BuildContext context, _) {
        final EstadoPase e = PaseTemplo.instancia.estado;
        return Scaffold(
          backgroundColor: TempleColors.negro,
          body: Stack(
            children: <Widget>[
              Positioned.fill(
                child: DecoratedBox(
                  decoration: BoxDecoration(
                    gradient: LinearGradient(
                      begin: Alignment.topCenter,
                      end: Alignment.bottomCenter,
                      colors: TemaTemplo.esTradicional
                          ? const <Color>[Color(0xFF1C1036), Color(0xFF0C0718), TempleColors.negro]
                          : const <Color>[TempleColors.superficieAlta, TempleColors.grafito, TempleColors.negro],
                      stops: const <double>[0, 0.45, 1],
                    ),
                  ),
                ),
              ),
              Positioned.fill(
                child: IgnorePointer(
                  child: RepaintBoundary(
                    child: AnimatedBuilder(
                      animation: _cielo,
                      builder: (BuildContext context, _) => CustomPaint(painter: _CieloPasePainter(_cielo.value)),
                    ),
                  ),
                ),
              ),
              SafeArea(
                child: Column(
                  children: <Widget>[
                    Padding(
                      padding: const EdgeInsets.fromLTRB(4, 4, 12, 0),
                      child: Row(
                        children: <Widget>[
                          IconButton(
                            onPressed: () => Navigator.of(context).maybePop(),
                            icon: const Icon(Icons.close_rounded, color: TempleColors.textoSuave),
                            tooltip: 'Cerrar',
                          ),
                          const Spacer(),
                          if (e.activo) const ChipPase(texto: 'ACTIVO'),
                        ],
                      ),
                    ),
                    Expanded(
                      child: ListView(
                        physics: const BouncingScrollPhysics(),
                        padding: const EdgeInsets.fromLTRB(18, 0, 18, 28),
                        children: <Widget>[
                          _heroe(e),
                          const SizedBox(height: 20),
                          if (e.activo) ..._activo(e) else ..._planes(e),
                          const SizedBox(height: 24),
                          const EtiquetaSeccion('Lo que incluye'),
                          _vitrinaPase(),
                          const SizedBox(height: 24),
                          const EtiquetaSeccion('Gratis y Pase, módulo por módulo'),
                          for (final _ModuloComparado m in comparacionPase) _BloquePase(modulo: m),
                          const SizedBox(height: 8),
                          _siempreGratis(),
                          const SizedBox(height: 18),
                          _preguntas(),
                        ],
                      ),
                    ),
                    if (!e.activo) _barraCompra(e),
                  ],
                ),
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _heroe(EstadoPase e) {
    return Column(
      children: <Widget>[
        const SizedBox(height: 6),
        const EmblemaPase(size: 124, rayos: true),
        const SizedBox(height: 18),
        ShaderMask(
          blendMode: BlendMode.srcIn,
          shaderCallback: (Rect r) =>
              const LinearGradient(colors: <Color>[Color(0xFFFFF4CC), Color(0xFFE8B65A), Color(0xFFFFF4CC)]).createShader(r),
          child: const Text('El Pase del Templo',
              textAlign: TextAlign.center,
              style: TextStyle(fontSize: 28, fontWeight: FontWeight.w700, letterSpacing: 0.6, color: Colors.white)),
        ),
        const SizedBox(height: 8),
        Text(
          e.activo
              ? 'Gracias por sostener el templo. Todo lo de abajo ya es tuyo.'
              : widget.desde == 'recorrido'
                  ? 'Ya conoces el templo. Esto es lo que se abre con el Pase.'
                  : 'Profundidad, comodidad y estilo. Nunca honor ni XP: eso se gana entrenando.',
          textAlign: TextAlign.center,
          style: const TextStyle(fontSize: 13.5, height: 1.5, color: TempleColors.textoSuave),
        ),
      ],
    );
  }

  List<Widget> _activo(EstadoPase e) {
    final String? u = _usuario;
    return <Widget>[
      Container(
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
          color: (TemaTemplo.esTradicional ? const Color(0xFF1C1430) : TempleColors.superficieAlta)
              .withValues(alpha: 0.92),
          border: Border.all(color: const Color(0xFFE8B65A).withValues(alpha: 0.5)),
        ),
        child: Row(
          children: <Widget>[
            const EmblemaPase(size: 46),
            const SizedBox(width: 14),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Text(e.plan.etiqueta,
                      style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w700, color: Color(0xFFF2D493))),
                  const SizedBox(height: 3),
                  Text(
                    e.vence == null
                        ? 'Sin fecha de fin'
                        : 'Activo hasta el ${_fecha(e.vence!)} · ${e.diasRestantes} ${e.diasRestantes == 1 ? 'día' : 'días'}',
                    style: const TextStyle(fontSize: 12.5, color: TempleColors.textoSuave),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
      if (u != null) ...<Widget>[
        const SizedBox(height: 12),
        TempleCard(
          onTap: OfrendaPase.disponible(u) ? () => _ofrenda(u) : null,
          destacada: OfrendaPase.disponible(u),
          child: Row(
            children: <Widget>[
              const IconoMon(size: 30),
              const SizedBox(width: 14),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    const Text('Ofrenda del mes',
                        style: TextStyle(fontSize: 14.5, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                    const SizedBox(height: 2),
                    Text(
                      OfrendaPase.disponible(u)
                          ? 'Toca para recibir ${LimitesPase.monOfrenda} mon para el Taller.'
                          : 'Ya la recibiste este mes. La próxima llega el día 1.',
                      style: const TextStyle(fontSize: 12, color: TempleColors.textoSuave),
                    ),
                  ],
                ),
              ),
              if (OfrendaPase.disponible(u)) const Icon(Icons.redeem_rounded, color: Color(0xFFF2D493)),
            ],
          ),
        ),
        const SizedBox(height: 12),
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: <Widget>[
            _Atajo(Icons.show_chart_rounded, 'Mi progreso',
                () => Navigator.of(context).push(MaterialPageRoute<void>(builder: (_) => ProgresoEjercicioScreen(usuario: u)))),
            _Atajo(Icons.auto_stories_outlined, 'Informe semanal',
                () => Navigator.of(context).push(MaterialPageRoute<void>(builder: (_) => InformeSemanalScreen(usuario: u)))),
            _Atajo(Icons.brush_outlined, 'Temporada en el Taller',
                () => Navigator.of(context).push(MaterialPageRoute<void>(builder: (_) => TallerVinetaScreen(usuario: u)))),
            _Atajo(Icons.file_download_outlined, 'Exportar', () => exportarEntrenamientos(context, u)),
          ],
        ),
      ],
    ];
  }

  List<Widget> _planes(EstadoPase e) {
    return <Widget>[
      _TarjetaPlanPase(
        titulo: 'Anual',
        precio: PreciosPase.anual,
        detalle: '${PreciosPase.anualPorMes} al mes · ${PreciosPase.anualCop}',
        etiqueta: 'Ahorra ${PreciosPase.ahorroAnual} %',
        elegido: _plan == PlanPase.anual,
        onTap: () => setState(() => _plan = PlanPase.anual),
      ),
      const SizedBox(height: 10),
      _TarjetaPlanPase(
        titulo: 'Mensual',
        precio: PreciosPase.mensual,
        detalle: 'Cada mes · ${PreciosPase.mensualCop}',
        elegido: _plan == PlanPase.mensual,
        onTap: () => setState(() => _plan = PlanPase.mensual),
      ),
      const SizedBox(height: 10),
      Text(
        e.pruebaUsada
            ? 'Precios de referencia. En la tienda verás el de tu país.'
            : 'Empieza con 7 días gratis, sin tarjeta. Si no te convence, no pasa nada: tu progreso se queda.',
        textAlign: TextAlign.center,
        style: const TextStyle(fontSize: 12, height: 1.45, color: TempleColors.textoTenue),
      ),
    ];
  }

  Widget _vitrinaPase() {
    final List<(String, String, Widget)> tarjetas = <(String, String, Widget)>[
      ('Tenshi sin límite', 'Conversa todo lo que quieras, con memoria larga y un informe de tu semana.',
          const _MiniAnimada(tipo: 0)),
      ('Toda tu historia', 'Cada ejercicio, desde el primer día. Compara épocas y mira tu mapa de calor.',
          const _MiniAnimada(tipo: 1)),
      ('Técnica a fondo', 'Cámara lenta, pausa y espejo para ver cada repetición con calma.',
          const AvatarEjercicio(ejercicioId: 'sentadilla', size: 130, velocidad: 0.5)),
      (
        'Estilo en el Clan',
        'Marcos exclusivos, el sello 金 y tu nombre con color.',
        Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: <Widget>[
            MarcoVivo(paleta: PaletasSello.todas[0], marco: MarcoSello.kintsugi, size: 82),
            const SizedBox(height: 8),
            const NombreConEstilo('Tu nombre',
                estilo: EstiloNombre.oro,
                insignia: true,
                style: TextStyle(fontSize: 16, fontWeight: FontWeight.w700, color: TempleColors.blancoLuna)),
          ],
        )
      ),
      (
        'Temporada del Pase',
        'Cuatro piezas animadas para tu viñeta que solo existen con el Pase.',
        MiniVineta(config: PiezasPase.muestra, ancho: 230, alto: 120, animada: true)
      ),
      (
        'Tu guerrero, con armadura',
        'Aspectos de samurái y kimono de gala para el guerrero del Ranked.',
        const GuerreroRanked(rangos: <GrupoMuscular, int>{}, rangoCuerpo: 9, altura: 130, aspecto: AspectoGuerrero.samurai)
      ),
    ];
    return Column(
      children: <Widget>[
        SizedBox(
          height: 246,
          child: PageView.builder(
            controller: _vitrina,
            itemCount: tarjetas.length,
            onPageChanged: (int i) => setState(() => _pagina = i),
            itemBuilder: (BuildContext context, int i) {
              final (String titulo, String texto, Widget vista) = tarjetas[i];
              return AnimatedScale(
                duration: TempleMotion.medio,
                curve: TempleMotion.suave,
                scale: i == _pagina ? 1 : 0.94,
                child: Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 6),
                  child: Container(
                    decoration: BoxDecoration(
                      borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
                      gradient: LinearGradient(
                        begin: Alignment.topCenter,
                        end: Alignment.bottomCenter,
                        colors: TemaTemplo.esTradicional
                            ? const <Color>[Color(0xFF241A3D), Color(0xFF130E22)]
                            : const <Color>[TempleColors.superficieAlta, TempleColors.superficie],
                      ),
                      border: Border.all(
                          color: i == _pagina ? const Color(0xFFE8B65A).withValues(alpha: 0.45) : TempleColors.borde),
                    ),
                    padding: const EdgeInsets.fromLTRB(16, 12, 16, 14),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: <Widget>[
                        SizedBox(height: 140, width: double.infinity, child: Center(child: vista)),
                        const SizedBox(height: 10),
                        Text(titulo,
                            style: const TextStyle(fontSize: 15.5, fontWeight: FontWeight.w700, color: Color(0xFFF2D493))),
                        const SizedBox(height: 4),
                        Text(texto,
                            maxLines: 3,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(fontSize: 12.5, height: 1.4, color: TempleColors.textoSuave)),
                      ],
                    ),
                  ),
                ),
              );
            },
          ),
        ),
        const SizedBox(height: 10),
        Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: <Widget>[
            for (int i = 0; i < tarjetas.length; i++)
              AnimatedContainer(
                duration: TempleMotion.medio,
                margin: const EdgeInsets.symmetric(horizontal: 3),
                width: i == _pagina ? 18 : 6,
                height: 6,
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(3),
                  color: i == _pagina ? const Color(0xFFE8B65A) : TempleColors.bordeVivo,
                ),
              ),
          ],
        ),
      ],
    );
  }

