  Widget _preguntas() {
    const List<(String, String)> faq = <(String, String)>[
      ('¿Pierdo algo si dejo de pagar?',
          'No. Tus entrenamientos, tu nube, tu XP, tu honor y todo lo que ganaste se quedan. Solo se guardan las piezas de temporada y los marcos exclusivos hasta que vuelvas.'),
      ('¿Cómo cancelo?',
          'Desde Google Play o la App Store, en Suscripciones. El Pase sigue activo hasta el final del periodo que pagaste.'),
      ('¿El Pase da ventaja en el Ranked?',
          'No. El honor y el XP son iguales para todos. Las tablas del Clan miden entrenamiento, no dinero.'),
    ];
    return Theme(
      data: Theme.of(context).copyWith(dividerColor: Colors.transparent),
      child: Column(
        children: <Widget>[
          for (final (String, String) f in faq)
            ExpansionTile(
              tilePadding: const EdgeInsets.symmetric(horizontal: 4),
              iconColor: TempleColors.violetaClaro,
              collapsedIconColor: TempleColors.textoTenue,
              title: Text(f.$1, style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w600, color: TempleColors.texto)),
              childrenPadding: const EdgeInsets.fromLTRB(4, 0, 4, 12),
              children: <Widget>[
                Text(f.$2, style: const TextStyle(fontSize: 13, height: 1.5, color: TempleColors.textoSuave)),
              ],
            ),
        ],
      ),
