/// Polvo de oro que sube y halos violetas: el fondo de la pantalla del Pase.
class _CieloPasePainter extends CustomPainter {
  const _CieloPasePainter(this.t);
  final double t;

  static double _h(double a, double b) {
    final double x = math.sin(a * 127.1 + b * 311.7) * 43758.5453;
    return x - x.floorToDouble();
  }

  @override
  void paint(Canvas canvas, Size size) {
    const double tau = math.pi * 2;
    final double w = size.width, h = size.height;
    for (int i = 0; i < 3; i++) {
      final Offset p = Offset(w * (0.2 + 0.3 * i) + math.sin(t * tau + i) * w * 0.05, h * (0.12 + 0.1 * i));
      canvas.drawCircle(
        p,
        w * 0.5,
        Paint()
          ..shader = RadialGradient(colors: <Color>[
            (i == 1 ? const Color(0xFFE8B65A) : ColoresTradicion.violeta).withValues(alpha: 0.10),
            Colors.transparent,
          ]).createShader(Rect.fromCircle(center: p, radius: w * 0.5)),
      );
    }
    for (int i = 0; i < 34; i++) {
      final double s = _h(i.toDouble(), 3);
      final double f = (t * (0.6 + s) + _h(3, i.toDouble())) % 1.0;
      final Offset p = Offset(w * _h(i.toDouble(), 7) + math.sin(f * tau * 2 + i) * 12, h * (1.05 - f * 1.1));
      final double a = math.sin(f * math.pi);
      canvas.drawCircle(p, 0.8 + 1.4 * s, Paint()..color = const Color(0xFFF2D493).withValues(alpha: 0.5 * a));
    }
  }

  @override
  bool shouldRepaint(_CieloPasePainter old) => old.t != t;
}

/// Animaciones pequeñas de la vitrina: 0 = Tenshi conversando, 1 = una
/// gráfica que se dibuja sola.
class _MiniAnimada extends StatefulWidget {
  const _MiniAnimada({required this.tipo});
  final int tipo;

  @override
  State<_MiniAnimada> createState() => _MiniAnimadaState();
}

class _MiniAnimadaState extends State<_MiniAnimada>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;
  late final AnimationController _c = AnimationController(vsync: this, duration: const Duration(seconds: 5))..repeat();

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => RepaintBoundary(
        child: AnimatedBuilder(
          animation: _c,
          builder: (BuildContext context, _) => CustomPaint(
            size: const Size(220, 130),
            painter: _MiniPasePainter(tipo: widget.tipo, t: _c.value),
          ),
        ),
      );
}

class _MiniPasePainter extends CustomPainter {
  const _MiniPasePainter({required this.tipo, required this.t});
  final int tipo;
  final double t;

  @override
  void paint(Canvas canvas, Size size) {
    if (tipo == 0) {
      _conversacion(canvas, size);
    } else {
      _grafica(canvas, size);
    }
  }

  void _conversacion(Canvas c, Size s) {
    // Burbujas que entran una tras otra y el ∞ al final.
    const List<(bool, double)> burbujas = <(bool, double)>[(false, 0.62), (true, 0.44), (false, 0.7), (true, 0.36)];
    for (int i = 0; i < burbujas.length; i++) {
      final double v = ((t * 5 - i * 0.9) / 0.6).clamp(0.0, 1.0);
      if (v <= 0) continue;
      final (bool propia, double ancho) = burbujas[i];
      final double w = s.width * ancho * Curves.easeOutBack.transform(v);
      final double y = 8 + i * 28.0;
      final Rect r = propia ? Rect.fromLTWH(s.width - w - 6, y, w, 22) : Rect.fromLTWH(6, y, w, 22);
      c.drawRRect(
        RRect.fromRectAndRadius(r, const Radius.circular(11)),
        Paint()
          ..color = (propia ? ColoresTradicion.violeta : const Color(0xFF2E2448)).withValues(alpha: 0.9 * v),
      );
      for (int k = 0; k < 3; k++) {
        final double lx = r.left + 10 + k * (r.width - 20) / 3;
        c.drawLine(Offset(lx, r.center.dy), Offset(lx + (r.width - 26) / 3.4, r.center.dy),
            Paint()
              ..color = Colors.white.withValues(alpha: 0.5 * v)
              ..strokeWidth = 2.2
              ..strokeCap = StrokeCap.round);
      }
    }
    final double brillo = 0.5 + 0.5 * math.sin(t * math.pi * 4);
    final TextPainter tp = TextPainter(
      text: TextSpan(
        text: '∞',
        style: TextStyle(fontSize: 26, fontWeight: FontWeight.w700, color: const Color(0xFFF2D493).withValues(alpha: 0.6 + 0.4 * brillo)),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(c, Offset(s.width / 2 - tp.width / 2, s.height - tp.height));
  }

  void _grafica(Canvas c, Size s) {
    final List<double> ys = <double>[0.2, 0.25, 0.22, 0.35, 0.4, 0.38, 0.5, 0.56, 0.6, 0.58, 0.7, 0.78, 0.82, 0.9];
    final double avance = (t * 1.3).clamp(0.0, 1.0);
    final Path linea = Path();
    final Path area = Path()..moveTo(0, s.height);
    Offset? ultimo;
    for (int i = 0; i < ys.length; i++) {
      final double u = i / (ys.length - 1);
      if (u > avance) break;
      final Offset p = Offset(u * s.width, s.height - 10 - ys[i] * (s.height - 24));
      if (i == 0) {
        linea.moveTo(p.dx, p.dy);
      } else {
        linea.lineTo(p.dx, p.dy);
      }
      area.lineTo(p.dx, p.dy);
      ultimo = p;
    }
    for (int k = 1; k < 4; k++) {
      final double y = s.height * k / 4;
      c.drawLine(Offset(0, y), Offset(s.width, y), Paint()..color = ColoresTradicion.borde.withValues(alpha: 0.6));
    }
    if (ultimo == null) return;
    area
      ..lineTo(ultimo.dx, s.height)
      ..close();
    c.drawPath(
      area,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[const Color(0xFFE8B65A).withValues(alpha: 0.35), const Color(0xFFE8B65A).withValues(alpha: 0)],
        ).createShader(Offset.zero & s),
    );
    c.drawPath(
      linea,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.4
        ..strokeJoin = StrokeJoin.round
        ..color = const Color(0xFFF2D493),
    );
    c.drawCircle(ultimo, 8, Paint()..color = const Color(0xFFF2D493).withValues(alpha: 0.25));
    c.drawCircle(ultimo, 3.6, Paint()..color = Colors.white);
  }

  @override
  bool shouldRepaint(_MiniPasePainter old) => old.t != t || old.tipo != tipo;
}

// ---------------------------------------------------------------------------
// 45.6 TEMPORADA DEL PASE Y OFRENDA MENSUAL
//
// Cuatro piezas animadas que existen mientras el Pase está activo. No se
// compran con mon ni se ganan: son el «gracias» del templo. Si el Pase
// termina, la viñeta vuelve a lo que tenías y la pieza espera a que vuelvas.
// ---------------------------------------------------------------------------

class PiezaPase {
  const PiezaPase({required this.id, required this.capa, required this.nombre, required this.descripcion});
  final String id;
  final CapaVineta capa;
  final String nombre;
  final String descripcion;
}

class PiezasPase {
  const PiezasPase._();

  static const String temporada = 'Otoño del Pase';

  static const List<PiezaPase> todas = <PiezaPase>[
    PiezaPase(
      id: 'cielo_kintsugi',
      capa: CapaVineta.cielo,
      nombre: 'Cielo kintsugi',
      descripcion: 'El cielo roto y reparado con oro. La luz recorre cada grieta.',
    ),
    PiezaPase(
      id: 'est_torii_dorado',
      capa: CapaVineta.estructura,
      nombre: 'Torii del Pase',
      descripcion: 'Torii de oro con su shimenawa y papeles sagrados que se mecen.',
    ),
    PiezaPase(
      id: 'cri_kitsunebi',
      capa: CapaVineta.criatura,
      nombre: 'Kitsunebi',
      descripcion: 'Fuegos de zorro que cruzan el templo en procesión.',
    ),
    PiezaPase(
      id: 'veg_susuki',
      capa: CapaVineta.vegetacion,
      nombre: 'Campo de susuki',
      descripcion: 'Hierba plateada de otoño que ondea con el viento.',
    ),
  ];

  static bool es(String id) => todas.any((PiezaPase p) => p.id == id);

  static List<PiezaPase> deCapa(CapaVineta c) => todas.where((PiezaPase p) => p.capa == c).toList();

  /// Las cuatro juntas, para la vitrina.
  static final Map<CapaVineta, String> muestra = <CapaVineta, String>{
    CapaVineta.cielo: 'cielo_kintsugi',
    CapaVineta.estructura: 'est_torii_dorado',
    CapaVineta.criatura: 'cri_kitsunebi',
    CapaVineta.vegetacion: 'veg_susuki',
  };
}

class OfrendaPase {
  const OfrendaPase._();

  static String motivo(DateTime d) => 'Ofrenda del Pase · ${d.year}-${d.month.toString().padLeft(2, '0')}';

  static bool disponible(String u) =>
      PaseTemplo.instancia.activo &&
      !MonedaTemplo.instancia.historial(u).any((MovimientoMon m) => m.motivo == motivo(DateTime.now()));

  static bool cobrar(String u) {
    if (!disponible(u)) return false;
    MonedaTemplo.instancia.ganar(u, LimitesPase.monOfrenda, motivo(DateTime.now()));
    NubeTemplo.instancia.marcarCambio();
    HapticFeedback.heavyImpact();
    return true;
  }
}

/// Preferencias del Pase que viven en el teléfono (el aspecto del guerrero).
class PreferenciasPase {
  PreferenciasPase._();
  static final PreferenciasPase instancia = PreferenciasPase._();

  final ValueNotifier<AspectoGuerrero> aspecto = ValueNotifier<AspectoGuerrero>(AspectoGuerrero.gi);

  static const String _clave = 'pase_aspecto_v1_';

  Future<void> cargar() async {
    final String? uid = SesionTemplo.instancia.uid;
    if (uid == null) return;
    try {
      final SharedPreferences sp = await SharedPreferences.getInstance();
      final String? s = sp.getString('$_clave$uid');
      for (final AspectoGuerrero a in AspectoGuerrero.values) {
        if (a.name == s) aspecto.value = a;
      }
    } catch (_) {}
  }

  Future<void> elegir(AspectoGuerrero a) async {
    aspecto.value = a;
    final String? uid = SesionTemplo.instancia.uid;
    if (uid == null) return;
    try {
      final SharedPreferences sp = await SharedPreferences.getInstance();
      await sp.setString('$_clave$uid', a.name);
    } catch (_) {}
  }

  /// El que se ve: sin Pase, siempre el gi.
  AspectoGuerrero get vigente => LimitesPase.pase ? aspecto.value : AspectoGuerrero.gi;
}

// ---------------------------------------------------------------------------
// 45.7 TU PROGRESO — gráficas por ejercicio, mapa de calor y comparar
// ---------------------------------------------------------------------------

class PuntoEjercicio {
  const PuntoEjercicio({required this.fecha, required this.rm, required this.peso, required this.volumen});
  final DateTime fecha;
  final double rm;
  final double peso;
  final double volumen;
}

DateTime _fechaSesion(Sesion s) => s.fin ?? s.inicio;

/// La historia de cada ejercicio, de la sesión más vieja a la más nueva.
Map<String, List<PuntoEjercicio>> historialEjercicios(String usuario) {
  final List<Sesion> ses = AlmacenTemplo.instancia.de(usuario).completadas
    ..sort((Sesion a, Sesion b) => _fechaSesion(a).compareTo(_fechaSesion(b)));
  final Map<String, List<PuntoEjercicio>> m = <String, List<PuntoEjercicio>>{};
  for (final Sesion s in ses) {
    for (final EjercicioSesion e in s.ejercicios) {
      if (e.seriesEfectivas.isEmpty) continue;
      m.putIfAbsent(e.ejercicioId, () => <PuntoEjercicio>[]).add(PuntoEjercicio(
            fecha: _fechaSesion(s),
            rm: e.mejor1RM ?? e.pesoMaximo,
            peso: e.pesoMaximo,
            volumen: e.volumen,
          ));
    }
  }
  return m;
}

enum MetricaProgreso { rm, peso, volumen }

extension DatosMetrica on MetricaProgreso {
  String get etiqueta => switch (this) {
        MetricaProgreso.rm => '1RM estimado',
        MetricaProgreso.peso => 'Peso máximo',
        MetricaProgreso.volumen => 'Volumen',
      };
  double de(PuntoEjercicio p) => switch (this) {
        MetricaProgreso.rm => p.rm,
        MetricaProgreso.peso => p.peso,
        MetricaProgreso.volumen => p.volumen,
      };
}

class ProgresoEjercicioScreen extends StatefulWidget {
  const ProgresoEjercicioScreen({super.key, required this.usuario, this.ejercicioInicial});
  final String usuario;
  final String? ejercicioInicial;

  @override
  State<ProgresoEjercicioScreen> createState() => _ProgresoEjercicioScreenState();
}

class _ProgresoEjercicioScreenState extends State<ProgresoEjercicioScreen> {
  late final Map<String, List<PuntoEjercicio>> _historia = historialEjercicios(widget.usuario);
  late final List<String> _ids = _historia.keys.toList()
    ..sort((String a, String b) => _historia[b]!.length.compareTo(_historia[a]!.length));
  late String? _id = widget.ejercicioInicial != null && _historia.containsKey(widget.ejercicioInicial)
      ? widget.ejercicioInicial
      : (_ids.isEmpty ? null : _ids.first);
  int _pestana = 0;
  int _dias = LimitesPase.diasHistorial; // 0 = toda la historia
  MetricaProgreso _metrica = MetricaProgreso.rm;
  int _comparar = 0;

  void _rango(int dias) {
    if (dias != LimitesPase.diasHistorial && !LimitesPase.pase) {
      mostrarMuroPase(
        context,
        titulo: 'Toda tu historia, con el Pase',
        texto: 'Gratis ves los últimos 3 meses de cada ejercicio. Con el Pase ves desde tu primera sesión.',
        ventajas: const <String>[
          '6 meses, un año o toda tu historia',
          'Compara épocas: este mes contra el anterior',
          'Mapa de calor de tu volumen por día',
        ],
        icono: Icons.show_chart_rounded,
      );
      return;
    }
    HapticFeedback.selectionClick();
    setState(() => _dias = dias);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: Column(
          children: <Widget>[
            const BarraClan(titulo: 'Tu progreso', subtitulo: 'Cada ejercicio, cada semana'),
            Padding(
              padding: const EdgeInsets.fromLTRB(TempleSpace.borde, 0, TempleSpace.borde, 8),
              child: SegmentedButton<int>(
                segments: const <ButtonSegment<int>>[
                  ButtonSegment<int>(value: 0, label: Text('Ejercicios'), icon: Icon(Icons.show_chart_rounded, size: 16)),
                  ButtonSegment<int>(value: 1, label: Text('Músculos'), icon: Icon(Icons.grid_on_rounded, size: 16)),
                  ButtonSegment<int>(value: 2, label: Text('Comparar'), icon: Icon(Icons.compare_arrows_rounded, size: 16)),
                ],
                selected: <int>{_pestana},
                showSelectedIcon: false,
                onSelectionChanged: (Set<int> s) => setState(() => _pestana = s.first),
                style: ButtonStyle(
                  foregroundColor: WidgetStateProperty.resolveWith((Set<WidgetState> e) =>
                      e.contains(WidgetState.selected) ? TempleColors.blancoLuna : TempleColors.textoSuave),
                  backgroundColor: WidgetStateProperty.resolveWith((Set<WidgetState> e) =>
                      e.contains(WidgetState.selected) ? TempleColors.violeta.withValues(alpha: 0.28) : Colors.transparent),
                  side: const WidgetStatePropertyAll<BorderSide>(BorderSide(color: TempleColors.borde)),
                  textStyle: const WidgetStatePropertyAll<TextStyle>(TextStyle(fontSize: 12.5)),
                ),
              ),
            ),
            Expanded(
              child: AnimatedSwitcher(
                duration: TempleMotion.medio,
                child: KeyedSubtree(
                  key: ValueKey<int>(_pestana),
                  child: switch (_pestana) {
                    0 => _ejercicios(),
                    1 => _bloqueado(_musculos(), 'Tu mapa de calor',
                        'Cada día que entrenaste, con su intensidad, y el volumen de cada músculo.'),
                    _ => _bloqueado(_comparacion(), 'Comparar épocas',
                        'Este mes contra el anterior, o tus últimos 90 días contra los 90 de antes.'),
                  },
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  /// Lo del Pase se enseña difuminado, con su candado: se ve qué hay detrás.
  Widget _bloqueado(Widget contenido, String titulo, String texto) {
    if (LimitesPase.pase) return contenido;
    return Stack(
      children: <Widget>[
        IgnorePointer(
          child: ImageFiltered(imageFilter: ImageFilter.blur(sigmaX: 6, sigmaY: 6), child: Opacity(opacity: 0.55, child: contenido)),
        ),
        Center(
          child: Padding(
            padding: const EdgeInsets.all(28),
            child: Container(
              padding: const EdgeInsets.fromLTRB(20, 20, 20, 12),
              decoration: BoxDecoration(
                color: TempleColors.grafito.withValues(alpha: 0.94),
                borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
                border: Border.all(color: const Color(0xFFE8B65A).withValues(alpha: 0.4)),
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: <Widget>[
                  const EmblemaPase(size: 54),
                  const SizedBox(height: 12),
                  Text(titulo,
                      textAlign: TextAlign.center,
                      style: const TextStyle(fontSize: 17, fontWeight: FontWeight.w700, color: TempleColors.blancoLuna)),
                  const SizedBox(height: 6),
                  Text(texto,
                      textAlign: TextAlign.center,
                      style: const TextStyle(fontSize: 13, height: 1.45, color: TempleColors.textoSuave)),
                  const SizedBox(height: 14),
                  BotonOro(texto: 'Desbloquear con el Pase', onPressed: () => abrirPase(context)),
                ],
              ),
            ),
          ),
        ),
      ],
    );
  }

  Widget _ejercicios() {
    final String? id = _id;
    if (id == null) {
      return const Center(
        child: Padding(
          padding: EdgeInsets.all(32),
          child: Text('Completa tu primera sesión y aquí verás cómo sube cada ejercicio.',
              textAlign: TextAlign.center, style: TextStyle(fontSize: 14, height: 1.5, color: TempleColors.textoSuave)),
        ),
      );
    }
    final List<PuntoEjercicio> todos = _historia[id]!;
    final DateTime? desde = _dias == 0 ? null : DateTime.now().subtract(Duration(days: _dias));
    final List<PuntoEjercicio> puntos =
        desde == null ? todos : todos.where((PuntoEjercicio p) => p.fecha.isAfter(desde)).toList();
    final int ocultos = todos.length - puntos.length;
    final double mejor = puntos.fold<double>(0, (double a, PuntoEjercicio p) => math.max(a, _metrica.de(p)));
    final double cambio = puntos.length < 2 || _metrica.de(puntos.first) <= 0
        ? 0
        : (_metrica.de(puntos.last) - _metrica.de(puntos.first)) / _metrica.de(puntos.first);

    return ListView(
      physics: const BouncingScrollPhysics(),
      padding: EdgeInsets.fromLTRB(TempleSpace.borde, 4, TempleSpace.borde, 28 + MediaQuery.paddingOf(context).bottom),
      children: <Widget>[
        SizedBox(
          height: 38,
          child: ListView(
            scrollDirection: Axis.horizontal,
            children: <Widget>[
              for (final String e in _ids)
                Padding(
                  padding: const EdgeInsets.only(right: 8),
                  child: ChoiceChip(
                    label: Text(ejercicioPorId(e)?.nombre ?? e, style: const TextStyle(fontSize: 12.5)),
                    selected: e == id,
                    onSelected: (_) => setState(() => _id = e),
                    selectedColor: TempleColors.violeta.withValues(alpha: 0.3),
                    backgroundColor: TempleColors.superficie,
                    side: BorderSide(color: e == id ? TempleColors.violeta : TempleColors.borde),
                    labelStyle: TextStyle(color: e == id ? TempleColors.blancoLuna : TempleColors.textoSuave),
                    showCheckmark: false,
                  ),
                ),
            ],
          ),
        ),
        const SizedBox(height: 12),
        TempleCard(
          destacada: true,
          padding: const EdgeInsets.fromLTRB(14, 14, 14, 10),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              Row(
                children: <Widget>[
                  Expanded(
                    child: Text(ejercicioPorId(id)?.nombre ?? id,
                        style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w700, color: TempleColors.blancoLuna)),
                  ),
                  PopupMenuButton<MetricaProgreso>(
                    initialValue: _metrica,
                    color: TempleColors.superficieAlta,
                    onSelected: (MetricaProgreso m) => setState(() => _metrica = m),
                    itemBuilder: (_) => <PopupMenuEntry<MetricaProgreso>>[
                      for (final MetricaProgreso m in MetricaProgreso.values)
                        PopupMenuItem<MetricaProgreso>(
                            value: m, child: Text(m.etiqueta, style: const TextStyle(color: TempleColors.texto))),
                    ],
                    child: Row(
                      children: <Widget>[
                        Text(_metrica.etiqueta, style: const TextStyle(fontSize: 12.5, color: TempleColors.violetaClaro)),
                        const Icon(Icons.expand_more_rounded, size: 18, color: TempleColors.violetaClaro),
                      ],
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 10),
              SizedBox(
                height: 190,
                child: TweenAnimationBuilder<double>(
                  key: ValueKey<String>('$id|$_dias|${_metrica.name}'),
                  tween: Tween<double>(begin: 0, end: 1),
                  duration: const Duration(milliseconds: 900),
                  curve: TempleMotion.entrada,
                  builder: (BuildContext c, double v, _) => CustomPaint(
                    size: Size.infinite,
                    painter: _GraficaProgresoPainter(puntos: puntos, metrica: _metrica, avance: v),
                  ),
                ),
              ),
              const SizedBox(height: 10),
              Wrap(
                spacing: 8,
                children: <Widget>[
                  for (final (int, String) r in const <(int, String)>[(90, '3 meses'), (180, '6 meses'), (365, '1 año'), (0, 'Todo')])
                    ChoiceChip(
                      label: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: <Widget>[
                          Text(r.$2, style: const TextStyle(fontSize: 12)),
                          if (r.$1 != LimitesPase.diasHistorial && !LimitesPase.pase) ...<Widget>[
                            const SizedBox(width: 4),
