  Widget _musculos() {
    final List<Sesion> ses = AlmacenTemplo.instancia.de(widget.usuario).completadas;
    final DateTime hoy = DateTime.now();
    final DateTime inicio = lunesDe(hoy).subtract(const Duration(days: 7 * 15));
    final Map<int, double> porDia = <int, double>{};
    final Map<GrupoMuscular, double> porGrupo = <GrupoMuscular, double>{};
    final DateTime hace28 = hoy.subtract(const Duration(days: 28));
    for (final Sesion s in ses) {
      final DateTime f = _fechaSesion(s);
      if (!f.isBefore(inicio)) {
        final int d = DateTime(f.year, f.month, f.day).difference(DateTime(inicio.year, inicio.month, inicio.day)).inDays;
        porDia[d] = (porDia[d] ?? 0) + s.volumenTotal;
      }
      if (f.isAfter(hace28)) {
        s.volumenPorGrupo.forEach((GrupoMuscular g, double v) => porGrupo[g] = (porGrupo[g] ?? 0) + v);
      }
    }
    final double maxGrupo = porGrupo.values.fold<double>(1, math.max);
    return ListView(
      physics: const BouncingScrollPhysics(),
      padding: EdgeInsets.fromLTRB(TempleSpace.borde, 4, TempleSpace.borde, 28 + MediaQuery.paddingOf(context).bottom),
      children: <Widget>[
        const EtiquetaSeccion('16 semanas de entrenamiento'),
        TempleCard(
          child: SizedBox(
            height: 132,
            child: TweenAnimationBuilder<double>(
              tween: Tween<double>(begin: 0, end: 1),
              duration: const Duration(milliseconds: 1100),
              curve: TempleMotion.entrada,
              builder: (BuildContext c, double v, _) =>
                  CustomPaint(size: Size.infinite, painter: _MapaCalorPainter(porDia: porDia, avance: v)),
            ),
          ),
        ),
        const SizedBox(height: 20),
        const EtiquetaSeccion('Volumen por músculo · 4 semanas'),
        for (final GrupoMuscular g in GrupoMuscular.values)
          Padding(
            padding: const EdgeInsets.only(bottom: 9),
            child: Row(
              children: <Widget>[
                SizedBox(
                    width: 92,
                    child: Text(g.etiqueta, style: const TextStyle(fontSize: 12.5, color: TempleColors.textoSuave))),
                Expanded(
                  child: TweenAnimationBuilder<double>(
                    tween: Tween<double>(begin: 0, end: (porGrupo[g] ?? 0) / maxGrupo),
                    duration: const Duration(milliseconds: 800),
                    curve: TempleMotion.entrada,
                    builder: (BuildContext c, double v, _) => ClipRRect(
                      borderRadius: BorderRadius.circular(5),
                      child: LinearProgressIndicator(
                        value: v,
                        minHeight: 9,
                        backgroundColor: TempleColors.superficieAlta,
                        valueColor: const AlwaysStoppedAnimation<Color>(TempleColors.violeta),
                      ),
                    ),
                  ),
                ),
                SizedBox(
                  width: 70,
                  child: Text('${((porGrupo[g] ?? 0) / 1000).toStringAsFixed(1)} t',
                      textAlign: TextAlign.right, style: const TextStyle(fontSize: 12, color: TempleColors.texto)),
                ),
              ],
            ),
          ),
      ],
    );
  }

  Widget _comparacion() {
    final List<Sesion> ses = AlmacenTemplo.instancia.de(widget.usuario).completadas;
    final DateTime hoy = DateTime.now();
    late final DateTime aIni, aFin, bIni, bFin;
    late final String etiquetaA, etiquetaB;
    switch (_comparar) {
      case 1:
        aIni = DateTime(hoy.year, hoy.month);
        aFin = hoy;
        bIni = DateTime(hoy.year, hoy.month - 1);
        bFin = aIni;
        etiquetaA = 'Este mes';
        etiquetaB = 'Mes pasado';
      case 2:
        aIni = hoy.subtract(const Duration(days: 90));
        aFin = hoy;
        bIni = hoy.subtract(const Duration(days: 180));
        bFin = aIni;
        etiquetaA = 'Últimos 90 días';
        etiquetaB = '90 días antes';
      default:
        aIni = hoy.subtract(const Duration(days: 28));
        aFin = hoy;
        bIni = hoy.subtract(const Duration(days: 56));
        bFin = aIni;
        etiquetaA = 'Últimas 4 semanas';
        etiquetaB = '4 semanas antes';
    }
    List<Sesion> entre(DateTime i, DateTime f) =>
        ses.where((Sesion s) => !_fechaSesion(s).isBefore(i) && _fechaSesion(s).isBefore(f.add(const Duration(seconds: 1)))).toList();
    final List<Sesion> a = entre(aIni, aFin), b = entre(bIni, bFin);
    double suma(List<Sesion> l, double Function(Sesion) f) => l.fold<double>(0, (double x, Sesion s) => x + f(s));
    final List<(String, double, double, String)> filas = <(String, double, double, String)>[
      ('Sesiones', a.length.toDouble(), b.length.toDouble(), ''),
      ('Volumen', suma(a, (Sesion s) => s.volumenTotal) / 1000, suma(b, (Sesion s) => s.volumenTotal) / 1000, ' t'),
      ('Series efectivas', suma(a, (Sesion s) => s.seriesEfectivas.toDouble()), suma(b, (Sesion s) => s.seriesEfectivas.toDouble()), ''),
      ('Minutos', suma(a, (Sesion s) => s.minutos.toDouble()), suma(b, (Sesion s) => s.minutos.toDouble()), ''),
    ];
    // Mejores subidas de 1RM entre las dos épocas.
    Map<String, double> mejores(List<Sesion> l) {
      final Map<String, double> m = <String, double>{};
      for (final Sesion s in l) {
        for (final EjercicioSesion e in s.ejercicios) {
          final double v = e.mejor1RM ?? 0;
          if (v > (m[e.ejercicioId] ?? 0)) m[e.ejercicioId] = v;
        }
      }
      return m;
    }

    final Map<String, double> ma = mejores(a), mb = mejores(b);
    final List<MapEntry<String, double>> subidas = <MapEntry<String, double>>[
      for (final String k in ma.keys)
        if ((mb[k] ?? 0) > 0) MapEntry<String, double>(k, (ma[k]! - mb[k]!) / mb[k]!),
    ]..sort((MapEntry<String, double> x, MapEntry<String, double> y) => y.value.compareTo(x.value));

    return ListView(
      physics: const BouncingScrollPhysics(),
      padding: EdgeInsets.fromLTRB(TempleSpace.borde, 4, TempleSpace.borde, 28 + MediaQuery.paddingOf(context).bottom),
      children: <Widget>[
        Wrap(
          spacing: 8,
          children: <Widget>[
            for (final (int, String) o in const <(int, String)>[(0, '4 semanas'), (1, 'Mes'), (2, '90 días')])
              ChoiceChip(
                label: Text(o.$2, style: const TextStyle(fontSize: 12)),
                selected: _comparar == o.$1,
                onSelected: (_) => setState(() => _comparar = o.$1),
                selectedColor: TempleColors.violeta.withValues(alpha: 0.3),
                backgroundColor: TempleColors.superficie,
                side: BorderSide(color: _comparar == o.$1 ? TempleColors.violeta : TempleColors.borde),
                labelStyle: TextStyle(color: _comparar == o.$1 ? TempleColors.blancoLuna : TempleColors.textoSuave),
                showCheckmark: false,
              ),
          ],
        ),
        const SizedBox(height: 12),
        TempleCard(
          child: Column(
            children: <Widget>[
              Row(
                children: <Widget>[
                  const Expanded(child: SizedBox()),
                  Expanded(
                      child: Text(etiquetaA,
                          textAlign: TextAlign.right,
                          style: const TextStyle(fontSize: 11.5, fontWeight: FontWeight.w700, color: TempleColors.violetaClaro))),
                  Expanded(
                      child: Text(etiquetaB,
                          textAlign: TextAlign.right, style: const TextStyle(fontSize: 11.5, color: TempleColors.textoTenue))),
                ],
              ),
              const SizedBox(height: 8),
              for (final (String, double, double, String) f in filas)
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 7),
                  child: Row(
                    children: <Widget>[
                      Expanded(child: Text(f.$1, style: const TextStyle(fontSize: 13, color: TempleColors.texto))),
                      Expanded(
                        child: Text('${_num(f.$2)}${f.$4}',
                            textAlign: TextAlign.right,
                            style: TextStyle(
                                fontSize: 14,
                                fontWeight: FontWeight.w700,
                                color: f.$2 >= f.$3 ? TempleColors.exito : TempleColors.alertaSuave)),
                      ),
                      Expanded(
                        child: Text('${_num(f.$3)}${f.$4}',
                            textAlign: TextAlign.right, style: const TextStyle(fontSize: 13, color: TempleColors.textoSuave)),
                      ),
                    ],
                  ),
                ),
            ],
          ),
        ),
        const SizedBox(height: 18),
        const EtiquetaSeccion('Lo que más subió'),
        if (subidas.isEmpty)
          const Text('Haz los mismos ejercicios en las dos épocas para comparar sus marcas.',
              style: TextStyle(fontSize: 13, color: TempleColors.textoSuave))
        else
          for (final MapEntry<String, double> s in subidas.take(5))
            Padding(
              padding: const EdgeInsets.only(bottom: 8),
              child: Row(
                children: <Widget>[
                  Expanded(
                    child: Text(ejercicioPorId(s.key)?.nombre ?? s.key,
                        style: const TextStyle(fontSize: 13.5, color: TempleColors.texto)),
                  ),
                  Text('${s.value >= 0 ? '+' : ''}${(s.value * 100).round()} %',
                      style: TextStyle(
                          fontSize: 13.5,
                          fontWeight: FontWeight.w700,
                          color: s.value >= 0 ? TempleColors.exito : TempleColors.alertaSuave)),
                ],
              ),
            ),
      ],
    );
  }
}

