class _GraficaProgresoPainter extends CustomPainter {
  const _GraficaProgresoPainter({required this.puntos, required this.metrica, required this.avance});
  final List<PuntoEjercicio> puntos;
  final MetricaProgreso metrica;
  final double avance;

  @override
  void paint(Canvas canvas, Size size) {
    const double izq = 34, abajo = 18;
    final double w = size.width - izq, h = size.height - abajo;
    final Paint rejilla = Paint()..color = TempleColors.borde.withValues(alpha: 0.7);
    if (puntos.isEmpty) {
      final TextPainter tp = TextPainter(
        text: const TextSpan(text: 'Sin sesiones en este rango', style: TextStyle(fontSize: 12.5, color: TempleColors.textoTenue)),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(size.width / 2 - tp.width / 2, size.height / 2 - tp.height / 2));
      return;
    }
    final List<double> vs = puntos.map(metrica.de).toList();
    double minV = vs.reduce(math.min), maxV = vs.reduce(math.max);
    if (maxV - minV < 1) {
      maxV += 1;
      minV = math.max(0, minV - 1);
    }
    final double margen = (maxV - minV) * 0.12;
    minV = math.max(0, minV - margen);
    maxV += margen;
    final int t0 = puntos.first.fecha.millisecondsSinceEpoch;
    final int t1 = math.max(t0 + 1, puntos.last.fecha.millisecondsSinceEpoch);

    for (int k = 0; k <= 3; k++) {
      final double y = h * k / 3;
      canvas.drawLine(Offset(izq, y), Offset(size.width, y), rejilla);
      final double v = maxV - (maxV - minV) * k / 3;
      final TextPainter tp = TextPainter(
        text: TextSpan(text: _num(v.roundToDouble()), style: const TextStyle(fontSize: 9.5, color: TempleColors.textoTenue)),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(0, y - tp.height / 2));
    }
    Offset en(int i) {
      final double u = puntos.length == 1 ? 0.5 : (puntos[i].fecha.millisecondsSinceEpoch - t0) / (t1 - t0);
      return Offset(izq + u * w, h - (vs[i] - minV) / (maxV - minV) * h);
    }

    canvas.save();
    canvas.clipRect(Rect.fromLTWH(0, 0, izq + w * avance + 6, size.height));
    final Path linea = Path();
    final Path area = Path();
    for (int i = 0; i < puntos.length; i++) {
      final Offset p = en(i);
      if (i == 0) {
        linea.moveTo(p.dx, p.dy);
        area
          ..moveTo(p.dx, h)
          ..lineTo(p.dx, p.dy);
      } else {
        final Offset a = en(i - 1);
        final double cx = (a.dx + p.dx) / 2;
        linea.cubicTo(cx, a.dy, cx, p.dy, p.dx, p.dy);
        area.cubicTo(cx, a.dy, cx, p.dy, p.dx, p.dy);
      }
    }
    area
      ..lineTo(en(puntos.length - 1).dx, h)
      ..close();
    canvas.drawPath(
      area,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[TempleColors.violeta.withValues(alpha: 0.38), TempleColors.violeta.withValues(alpha: 0)],
        ).createShader(Rect.fromLTWH(0, 0, size.width, h)),
    );
    canvas.drawPath(
      linea,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.4
        ..strokeJoin = StrokeJoin.round
        ..strokeCap = StrokeCap.round
        ..color = TempleColors.violetaClaro,
    );
    for (int i = 0; i < puntos.length; i++) {
      canvas.drawCircle(en(i), 2.6, Paint()..color = TempleColors.blancoLuna);
    }
    canvas.restore();
    if (avance >= 1) {
      final int im = vs.indexOf(vs.reduce(math.max));
      final Offset p = en(im);
      canvas.drawCircle(p, 9, Paint()..color = const Color(0xFFE8B65A).withValues(alpha: 0.25));
      canvas.drawCircle(p, 4, Paint()..color = const Color(0xFFF2D493));
    }
    // Fechas extremas.
    String f(DateTime d) => '${d.day}/${d.month}';
    final TextPainter a = TextPainter(
      text: TextSpan(text: f(puntos.first.fecha), style: const TextStyle(fontSize: 9.5, color: TempleColors.textoTenue)),
      textDirection: TextDirection.ltr,
    )..layout();
    a.paint(canvas, Offset(izq, h + 4));
    final TextPainter b = TextPainter(
      text: TextSpan(text: f(puntos.last.fecha), style: const TextStyle(fontSize: 9.5, color: TempleColors.textoTenue)),
      textDirection: TextDirection.ltr,
    )..layout();
    b.paint(canvas, Offset(size.width - b.width, h + 4));
  }

  @override
  bool shouldRepaint(_GraficaProgresoPainter old) => old.avance != avance || old.puntos != puntos || old.metrica != metrica;
}

class _MapaCalorPainter extends CustomPainter {
  const _MapaCalorPainter({required this.porDia, required this.avance});
  final Map<int, double> porDia;
  final double avance;

  @override
  void paint(Canvas canvas, Size size) {
    const int semanas = 16;
    final double celda = math.min((size.width - 8) / semanas, (size.height - 4) / 7);
    final double hueco = celda * 0.16;
    final double maxV = porDia.values.fold<double>(1, math.max);
    final int hoy = DateTime.now().difference(lunesDe(DateTime.now()).subtract(const Duration(days: 7 * 15))).inDays;
    for (int s = 0; s < semanas; s++) {
      for (int d = 0; d < 7; d++) {
        final int i = s * 7 + d;
        if (i > hoy) continue;
        final double aparece = ((avance * (semanas + 4) - s) / 4).clamp(0.0, 1.0);
        final double v = (porDia[i] ?? 0) / maxV;
        final Rect r = Rect.fromLTWH(s * celda + hueco / 2, d * celda + hueco / 2, celda - hueco, celda - hueco);
        canvas.drawRRect(
          RRect.fromRectAndRadius(r.deflate((1 - aparece) * celda * 0.3), Radius.circular(celda * 0.22)),
          Paint()
            ..color = v <= 0
                ? TempleColors.superficieAlta.withValues(alpha: aparece)
                : Color.lerp(const Color(0xFF3A2470), const Color(0xFFE8B65A), v)!.withValues(alpha: (0.45 + 0.55 * v) * aparece),
        );
      }
    }
  }

  @override
  bool shouldRepaint(_MapaCalorPainter old) => old.avance != avance || old.porDia != porDia;
}

// ---------------------------------------------------------------------------
// 45.8 INFORME SEMANAL DE TENSHI
//
// Se calcula en el teléfono con tus datos: no gasta mensajes de Tenshi y
// funciona sin internet.
// ---------------------------------------------------------------------------

class InformeSemanal {
  const InformeSemanal({
    required this.sesiones,
    required this.sesionesAntes,
    required this.volumen,
    required this.volumenAntes,
    required this.minutos,
    required this.records,
    required this.grupos,
    required this.olvidados,
    required this.estancados,
    required this.subiendo,
  });

  final int sesiones;
  final int sesionesAntes;
  final double volumen;
  final double volumenAntes;
  final int minutos;
  final int records;
  final Set<GrupoMuscular> grupos;
  final List<GrupoMuscular> olvidados;
  final List<String> estancados;
  final List<String> subiendo;

  static InformeSemanal de(String usuario) {
    final DatosUsuario d = AlmacenTemplo.instancia.de(usuario);
    final List<Sesion> ses = d.completadas;
    final DateTime hoy = DateTime.now();
    final DateTime lunes = lunesDe(hoy);
    final DateTime lunesAntes = lunes.subtract(const Duration(days: 7));
    final List<Sesion> esta = ses.where((Sesion s) => !_fechaSesion(s).isBefore(lunes)).toList();
    final List<Sesion> antes =
        ses.where((Sesion s) => !_fechaSesion(s).isBefore(lunesAntes) && _fechaSesion(s).isBefore(lunes)).toList();
    final Set<GrupoMuscular> grupos = <GrupoMuscular>{for (final Sesion s in esta) ...s.gruposTrabajados};

    // Músculos sin tocar en 10 días o más.
    final Map<GrupoMuscular, DateTime> ultima = <GrupoMuscular, DateTime>{};
    for (final Sesion s in ses) {
      for (final GrupoMuscular g in s.gruposTrabajados) {
        final DateTime f = _fechaSesion(s);
        if (ultima[g] == null || f.isAfter(ultima[g]!)) ultima[g] = f;
      }
    }
    final List<GrupoMuscular> olvidados = <GrupoMuscular>[
      for (final GrupoMuscular g in GrupoMuscular.values)
        if (ultima[g] != null && hoy.difference(ultima[g]!).inDays >= 10) g,
    ];

    // Estancados: hechos 3+ veces en 4 semanas sin superar la marca de las
    // dos semanas anteriores.
    final Map<String, List<PuntoEjercicio>> h = historialEjercicios(usuario);
    final DateTime hace14 = hoy.subtract(const Duration(days: 14)), hace28 = hoy.subtract(const Duration(days: 28));
    final List<String> estancados = <String>[];
    final List<String> subiendo = <String>[];
    h.forEach((String id, List<PuntoEjercicio> ps) {
      final List<PuntoEjercicio> recientes = ps.where((PuntoEjercicio p) => p.fecha.isAfter(hace14)).toList();
      final List<PuntoEjercicio> previos =
          ps.where((PuntoEjercicio p) => p.fecha.isAfter(hace28) && !p.fecha.isAfter(hace14)).toList();
      if (recientes.isEmpty || previos.isEmpty || recientes.length + previos.length < 3) return;
      final double r = recientes.map((PuntoEjercicio p) => p.rm).reduce(math.max);
      final double q = previos.map((PuntoEjercicio p) => p.rm).reduce(math.max);
      if (r <= q * 1.005) {
        estancados.add(id);
      } else if (r >= q * 1.03) {
        subiendo.add(id);
      }
    });
    return InformeSemanal(
      sesiones: esta.length,
      sesionesAntes: antes.length,
      volumen: esta.fold<double>(0, (double a, Sesion s) => a + s.volumenTotal),
      volumenAntes: antes.fold<double>(0, (double a, Sesion s) => a + s.volumenTotal),
      minutos: esta.fold<int>(0, (int a, Sesion s) => a + s.minutos),
      records: d.records.values.where((RecordPersonal r) => !r.fecha.isBefore(lunes)).length,
      grupos: grupos,
      olvidados: olvidados,
      estancados: estancados,
      subiendo: subiendo,
    );
  }

  /// La lectura de Tenshi, con su voz.
  String consejo(TonoTenshi tono) {
    final String? est = estancados.isEmpty ? null : (ejercicioPorId(estancados.first)?.nombre ?? estancados.first);
    final String? olv = olvidados.isEmpty ? null : olvidados.first.etiqueta.toLowerCase();
    if (sesiones == 0) {
      return switch (tono) {
        TonoTenshi.exigente => 'Cero sesiones esta semana. No te pido una gran sesión: te pido una. Hoy.',
        TonoTenshi.alegre => '¡Semana en blanco! Pasa, que el templo te echa de menos. Una corta y listo.',
        TonoTenshi.serena => 'Esta semana el templo estuvo en silencio. Cuando puedas, una sesión corta basta para volver.',
      };
    }
    final List<String> partes = <String>[];
    if (est != null) {
      partes.add(switch (tono) {
        TonoTenshi.exigente => '$est lleva dos semanas sin subir. Cambia el rango de repeticiones o baja un 10 % y vuelve a subir.',
        TonoTenshi.alegre => '$est se ha quedado quieto, ¿eh? Prueba otro rango de repeticiones y verás cómo se despierta.',
        TonoTenshi.serena => '$est no ha subido en dos semanas. Es normal; prueba otro rango o una semana más ligera.',
      });
    }
    if (olv != null) {
      partes.add(switch (tono) {
        TonoTenshi.exigente => 'Y $olv lleva más de diez días esperando.',
        TonoTenshi.alegre => 'Por cierto, $olv te extraña.',
        TonoTenshi.serena => 'También $olv lleva días sin verte.',
      });
    }
    if (partes.isEmpty) {
      partes.add(switch (tono) {
        TonoTenshi.exigente => 'Semana sólida. Mantén el ritmo y no te saltes la recuperación.',
        TonoTenshi.alegre => '¡Semanaza! Todo sube y nada se queda atrás. Así da gusto.',
        TonoTenshi.serena => 'Una semana equilibrada. Sigue así, sin prisa.',
      });
    }
    return partes.join(' ');
  }
}

