// ---------------------------------------------------------------------------
// 45.9 EXPORTAR ENTRENAMIENTOS
//
// Sin paquetes extra: el CSV se copia al portapapeles y se pega en Excel o
// en Google Sheets. Gratis, los últimos 3 meses; con el Pase, todo y un
// resumen por ejercicio.
// ---------------------------------------------------------------------------

String csvEntrenamientos(String usuario, {required bool todo}) {
  final List<Sesion> ses = List<Sesion>.of(AlmacenTemplo.instancia.de(usuario).completadas)
    ..sort((Sesion a, Sesion b) => _fechaSesion(a).compareTo(_fechaSesion(b)));
  final DateTime desde = DateTime.now().subtract(const Duration(days: LimitesPase.diasHistorial));
  String c(String s) => s.contains(',') || s.contains('"') ? '"${s.replaceAll('"', '""')}"' : s;
  final StringBuffer b = StringBuffer('fecha,sesion,ejercicio,serie,tipo,peso_kg,repeticiones,rpe\n');
  for (final Sesion s in ses) {
    final DateTime f = _fechaSesion(s);
    if (!todo && f.isBefore(desde)) continue;
    final String fecha = f.toIso8601String().substring(0, 10);
    for (final EjercicioSesion e in s.ejercicios) {
      for (final SerieRegistrada r in e.series) {
        if (!r.completada || (!r.cuenta && r.tipo != TipoSerie.calentamiento)) continue;
        b.writeln('$fecha,${c(s.nombre ?? 'Sesión')},${c(e.nombre)},${r.numero},${r.tipo.name},'
            '${_num(r.peso)},${r.repeticiones},${r.rpe == null ? '' : _num(r.rpe!)}');
      }
    }
  }
  if (todo) {
    b.writeln();
    b.writeln('ejercicio,sesiones,mejor_peso_kg,mejor_1rm_kg,volumen_total_kg');
    historialEjercicios(usuario).forEach((String id, List<PuntoEjercicio> ps) {
      b.writeln('${c(ejercicioPorId(id)?.nombre ?? id)},${ps.length},'
          '${_num(ps.map((PuntoEjercicio p) => p.peso).reduce(math.max))},'
          '${_num(ps.map((PuntoEjercicio p) => p.rm).reduce(math.max))},'
          '${_num(ps.fold<double>(0, (double a, PuntoEjercicio p) => a + p.volumen))}');
    });
  }
  return b.toString();
}

Future<void> exportarEntrenamientos(BuildContext context, String usuario) {
  Future<void> copiar(bool todo) async {
    await Clipboard.setData(ClipboardData(text: csvEntrenamientos(usuario, todo: todo)));
    HapticFeedback.mediumImpact();
    if (context.mounted) avisoClan(context, 'Copiado. Pégalo en Excel o en Google Sheets.');
  }

  return showModalBottomSheet<void>(
    context: context,
    backgroundColor: TempleColors.grafito,
    shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
    builder: (BuildContext ctx) => SafeArea(
      top: false,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(16, 18, 16, 12),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: <Widget>[
            const Text('Exportar entrenamientos',
                style: TextStyle(fontSize: 17, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
            const SizedBox(height: 4),
            const Text('Se copia como tabla (CSV). Pégala en una hoja de cálculo.',
                style: TextStyle(fontSize: 12.5, color: TempleColors.textoSuave)),
            const SizedBox(height: 10),
            ListTile(
              leading: const Icon(Icons.table_rows_outlined, color: TempleColors.violetaClaro),
              title: const Text('Últimos 3 meses', style: TextStyle(color: TempleColors.blancoLuna)),
              subtitle: const Text('Cada serie con su peso y repeticiones', style: TextStyle(color: TempleColors.textoTenue)),
              onTap: () {
                Navigator.of(ctx).pop();
                copiar(false);
              },
            ),
            ListTile(
              leading: const Icon(Icons.auto_awesome_rounded, color: Color(0xFFF2D493)),
              title: const Text('Toda tu historia y resumen', style: TextStyle(color: TempleColors.blancoLuna)),
              subtitle: const Text('Desde tu primera sesión, con mejores marcas por ejercicio',
                  style: TextStyle(color: TempleColors.textoTenue)),
              trailing: LimitesPase.pase ? null : const ChipPase(),
              onTap: () {
                Navigator.of(ctx).pop();
                if (LimitesPase.pase) {
                  copiar(true);
                } else {
                  mostrarMuroPase(
                    context,
                    titulo: 'Exporta toda tu historia',
                    texto: 'Gratis exportas los últimos 3 meses. Con el Pase, todo desde el primer día, con un resumen por ejercicio.',
                    icono: Icons.file_download_outlined,
                  );
                }
              },
            ),
          ],
        ),
      ),
    ),
  );
}

// ---------------------------------------------------------------------------
// 45.10 LÍMITES EN SU SITIO — ciclo, Tenshi y aspecto del guerrero
// ---------------------------------------------------------------------------

/// Gratis, el ciclo se rehace una vez al mes; con el Pase, cuando quieras.
/// El primer ciclo siempre es libre.
bool puedeRehacerCiclo(BuildContext context, String usuario) {
  if (LimitesPase.pase) return true;
  final CicloEntrenamiento? c = AlmacenCiclos.instancia.de(usuario);
  if (c == null) return true;
  final int dias = DateTime.now().difference(c.creado).inDays;
  if (dias >= LimitesPase.diasEntreCiclos) return true;
  final int faltan = LimitesPase.diasEntreCiclos - dias;
  mostrarMuroPase(
    context,
    titulo: 'Tu ciclo sigue en marcha',
    texto: 'Gratis puedes rehacer tu ciclo una vez al mes: el próximo, en $faltan ${faltan == 1 ? 'día' : 'días'}. '
        'Con el Pase lo rehaces cuando cambien tus planes.',
    ventajas: const <String>[
      'Rehacer el ciclo cuando quieras',
      'Ver si cada cambio funcionó en tus gráficas',
      'El informe semanal de Tenshi',
    ],
    icono: Icons.route_outlined,
  );
  return false;
}

Future<void> rehacerCiclo(BuildContext context, String usuario) async {
  if (!puedeRehacerCiclo(context, usuario)) return;
  final RespuestasCiclo? r = await Navigator.of(context).push<RespuestasCiclo>(
    MaterialPageRoute<RespuestasCiclo>(builder: (_) => PreguntasCicloScreen(usuario: usuario)),
  );
  if (r == null) return;
  AlmacenCiclos.instancia.guardar(usuario, GeneradorCiclo.generar(usuario: usuario, r: r));
  NubeTemplo.instancia.marcarCambio();
  if (context.mounted) avisoClan(context, 'Tu ciclo nuevo está listo en «Mi camino».');
}

/// Encima del campo de Tenshi: cuánto queda hoy y, al llegar a cero, qué
/// pasa ahora (Tenshi ligero sigue, mañana se renueva).
class _TshCupo extends StatelessWidget {
  const _TshCupo({required this.tono});
  final TonoTenshi tono;

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: Listenable.merge(<Listenable>[UsoPase.instancia, PaseTemplo.instancia]),
      builder: (BuildContext context, _) {
        if (LimitesPase.pase) return const SizedBox.shrink();
        final int quedan = UsoPase.instancia.tenshiRestantes;
        if (quedan > 3) return const SizedBox.shrink();
        final int anunciosQuedan =
            math.max(0, AlmacenAnuncios.tenshiAnunciosDia - UsoPase.instancia.anunciosTenshiHoy);
        if (quedan == 0 && MotorAnuncios.instancia.ofrecible && anunciosQuedan > 0) {
          return Padding(
            padding: const EdgeInsets.fromLTRB(16, 0, 16, 8),
            child: Container(
              padding: const EdgeInsets.fromLTRB(12, 10, 10, 10),
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(TempleRadius.campo),
                color: TempleColors.superficie.withValues(alpha: 0.94),
                border: Border.all(color: tono.acento.withValues(alpha: 0.45)),
              ),
              child: Row(
                children: <Widget>[
                  Expanded(
                    child: Text(
                      'Se acabaron tus mensajes con la mente completa de hoy. Mira un anuncio y suma '
                      '${AlmacenAnuncios.tenshiPorAnuncio} más ($anunciosQuedan de ${AlmacenAnuncios.tenshiAnunciosDia} hoy), '
                      'o sigue con Tenshi ligero.',
