/// Elegir cómo se viste tu guerrero del Ranked. El gi es de todos; la
/// armadura y el kimono, del Pase.
Future<void> elegirAspectoGuerrero(BuildContext context) {
  return showModalBottomSheet<void>(
    context: context,
    backgroundColor: TempleColors.grafito,
    isScrollControlled: true,
    shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
    builder: (BuildContext ctx) {
      final String? u = SesionTemplo.instancia.actual?.usuario;
      final EstadoRanked? e = u == null ? null : MotorRanked.de(u);
      final Map<GrupoMuscular, int> rangos = <GrupoMuscular, int>{
        if (e != null)
          for (final MusculoRanked m in e.musculos.values) m.grupo: m.rango,
      };
      return SafeArea(
        top: false,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(16, 18, 16, 16),
          child: ValueListenableBuilder<AspectoGuerrero>(
            valueListenable: PreferenciasPase.instancia.aspecto,
            builder: (BuildContext c, AspectoGuerrero actual, _) => Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: <Widget>[
                const Text('Aspecto de tu guerrero',
                    style: TextStyle(fontSize: 17, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                const SizedBox(height: 4),
                const Text('Solo cambia cómo se ve. Su tamaño y su aura siguen saliendo de tus rangos.',
                    style: TextStyle(fontSize: 12.5, color: TempleColors.textoSuave)),
                const SizedBox(height: 14),
                Row(
                  children: <Widget>[
                    for (final AspectoGuerrero a in AspectoGuerrero.values)
                      Expanded(
                        child: GestureDetector(
                          onTap: () {
                            if (a != AspectoGuerrero.gi && !LimitesPase.pase) {
                              Navigator.of(ctx).pop();
                              mostrarMuroPase(
                                context,
                                titulo: 'Viste a tu guerrero',
                                texto: 'La armadura samurái y el kimono de gala son del Pase. Tu guerrero sigue creciendo igual con tus rangos.',
                                icono: Icons.checkroom_outlined,
                              );
                              return;
                            }
                            HapticFeedback.selectionClick();
                            PreferenciasPase.instancia.elegir(a);
                          },
                          child: AnimatedContainer(
                            duration: TempleMotion.medio,
                            margin: const EdgeInsets.symmetric(horizontal: 4),
                            padding: const EdgeInsets.fromLTRB(4, 8, 4, 10),
                            decoration: BoxDecoration(
                              borderRadius: BorderRadius.circular(TempleRadius.campo),
                              color: actual == a ? TempleColors.violeta.withValues(alpha: 0.16) : TempleColors.superficie,
                              border: Border.all(color: actual == a ? TempleColors.violeta : TempleColors.borde),
                            ),
                            child: Column(
                              children: <Widget>[
                                GuerreroRanked(
                                  rangos: rangos,
                                  rangoCuerpo: e?.rangoCuerpo ?? -1,
                                  altura: 120,
                                  aspecto: a,
                                ),
                                const SizedBox(height: 6),
                                Row(
                                  mainAxisAlignment: MainAxisAlignment.center,
                                  children: <Widget>[
                                    Flexible(
                                      child: Text(a.etiqueta,
                                          overflow: TextOverflow.ellipsis,
                                          style: const TextStyle(fontSize: 12, color: TempleColors.texto)),
                                    ),
                                    if (a != AspectoGuerrero.gi && !LimitesPase.pase) ...<Widget>[
                                      const SizedBox(width: 4),
                                      const Icon(Icons.lock_outline_rounded, size: 12, color: Color(0xFFE8B65A)),
                                    ],
                                  ],
                                ),
                              ],
                            ),
                          ),
                        ),
                      ),
                  ],
                ),
              ],
            ),
          ),
        ),
      );
    },
  );
}

/// El avatar de técnica con sus controles: cámara lenta, pausa y espejo
/// (del Pase). Gratis se ve completo, a su ritmo.
class VisorTecnica extends StatefulWidget {
  const VisorTecnica({super.key, required this.ejercicioId});
  final String ejercicioId;

  @override
  State<VisorTecnica> createState() => _VisorTecnicaState();
}

class _VisorTecnicaState extends State<VisorTecnica> {
  bool _lenta = false;
  bool _pausa = false;
  bool _espejo = false;

  void _pase(VoidCallback cambio) {
    if (!LimitesPase.pase) {
      mostrarMuroPase(
        context,
        titulo: 'Técnica a fondo',
        texto: 'Con el Pase pones el avatar en cámara lenta, lo pausas en el punto exacto o lo ves en espejo, '
            'como si entrenaras frente a él.',
        ventajas: const <String>['Cámara lenta para cada fase', 'Pausa en cualquier punto', 'Vista en espejo'],
        icono: Icons.slow_motion_video_rounded,
      );
      return;
    }
    HapticFeedback.selectionClick();
    setState(cambio);
  }

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: PaseTemplo.instancia,
      builder: (BuildContext context, _) => Column(
        children: <Widget>[
          Center(
            child: AvatarEjercicio(
              ejercicioId: widget.ejercicioId,
              size: 260,
              velocidad: _lenta ? 0.45 : 1,
              pausado: _pausa,
              espejo: _espejo,
            ),
          ),
          Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: <Widget>[
              _BotonVisor(
                icono: _pausa ? Icons.play_arrow_rounded : Icons.pause_rounded,
                texto: _pausa ? 'Seguir' : 'Pausa',
                activo: _pausa,
                onTap: () => _pase(() => _pausa = !_pausa),
              ),
              _BotonVisor(
                icono: Icons.slow_motion_video_rounded,
                texto: 'Lenta',
                activo: _lenta,
                onTap: () => _pase(() => _lenta = !_lenta),
              ),
              _BotonVisor(
                icono: Icons.flip_rounded,
                texto: 'Espejo',
                activo: _espejo,
                onTap: () => _pase(() => _espejo = !_espejo),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

