/// Cuánto dura un video elegido. Null si no se puede saber (se deja pasar).
Future<Duration?> duracionVideo(XFile f) async {
  VideoPlayerController? c;
  try {
    final Uri uri = kIsWeb || f.path.startsWith('blob:') || f.path.startsWith('http') ? Uri.parse(f.path) : Uri.file(f.path);
    c = VideoPlayerController.networkUrl(uri);
    await c.initialize().timeout(const Duration(seconds: 6));
    return c.value.duration;
  } catch (_) {
    return null;
  } finally {
    await c?.dispose();
  }
}

