// 45.11 RANKED — pronóstico de ascenso e historia completa (del Pase)
//
// Solo informa: el honor se gana igual con o sin Pase.
// ---------------------------------------------------------------------------

class PronosticoRanked extends StatelessWidget {
  const PronosticoRanked({super.key, required this.musculo});
  final MusculoRanked musculo;

  @override
  Widget build(BuildContext context) {
    final MusculoRanked m = musculo;
    final List<double> ultimas = m.semanal.sublist(m.semanal.length - 4);
    final double media = ultimas.fold<double>(0, (double a, double b) => a + b) / 4;
    final int siguiente = math.min(m.rango + 1, RangosRanked.maximo);
    String texto;
    if (m.maximo) {
      texto = 'Ya está en lo más alto. Ahora se trata de no dejarlo dormir.';
    } else if (media <= 0) {
      texto = 'Entrena ${m.grupo.etiqueta.toLowerCase()} unas semanas y Tenshi calculará cuándo asciende.';
    } else {
      final int semanas = math.max(1, (m.faltan / media).ceil());
      final DateTime cuando = DateTime.now().add(Duration(days: semanas * 7));
      texto = 'A tu ritmo (${media.round()} de honor por semana), llegarás a ${RangosRanked.nombre(siguiente)} '
          'en unas $semanas ${semanas == 1 ? 'semana' : 'semanas'}, hacia el ${cuando.day}/${cuando.month}.'
          '${m.pruebaPendiente != null ? ' Antes tendrás que pasar su prueba de constancia.' : ''}';
    }
    final Widget tarjeta = Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
        color: (TemaTemplo.esTradicional ? const Color(0xFF1C1430) : TempleColors.superficieAlta)
            .withValues(alpha: 0.9),
        border: Border.all(color: const Color(0xFFE8B65A).withValues(alpha: 0.35)),
      ),
      child: Row(
        children: <Widget>[
          EmblemaRanked(rango: siguiente, size: 40, animado: LimitesPase.pase),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: <Widget>[
                const Text('Pronóstico de ascenso',
                    style: TextStyle(fontSize: 12, letterSpacing: 0.6, color: Color(0xFFF2D493))),
                const SizedBox(height: 4),
                Text(texto, style: const TextStyle(fontSize: 13, height: 1.45, color: TempleColors.texto)),
              ],
            ),
          ),
        ],
      ),
    );
    if (LimitesPase.pase) return tarjeta;
    return GestureDetector(
      onTap: () => mostrarMuroPase(
        context,
        titulo: 'Pronóstico de ascenso',
        texto: 'Con el Pase, cada músculo te dice cuándo subirá de rango a tu ritmo actual, y ves toda su historia.',
        icono: Icons.military_tech_outlined,
      ),
      child: Stack(
        alignment: Alignment.center,
        children: <Widget>[
          ImageFiltered(imageFilter: ImageFilter.blur(sigmaX: 4, sigmaY: 4), child: tarjeta),
          const ChipPase(texto: 'VER CON EL PASE'),
        ],
      ),
    );
  }
}

class HistoriaMusculo extends StatelessWidget {
  const HistoriaMusculo({super.key, required this.usuario, required this.musculo});
  final String usuario;
  final MusculoRanked musculo;

  @override
  Widget build(BuildContext context) {
    final MusculoRanked m = musculo;
    if (m.porSemana.isEmpty) {
      return const Text('Todavía no hay semanas que mostrar.', style: TextStyle(fontSize: 13, color: TempleColors.textoSuave));
    }
    final int primera = m.porSemana.keys.reduce(math.min);
    final int hoy = MotorRanked.semana(DateTime.now());
    final List<double> valores = <double>[for (int w = primera; w <= hoy; w++) m.porSemana[w] ?? 0];
    final Set<int> ascensos = <int>{
      for (final AscensoRanked a in MotorRanked.de(usuario).ascensos)
        if (a.grupo == m.grupo) MotorRanked.semana(a.fecha) - primera,
    };
    final Widget grafica = TempleCard(
      padding: const EdgeInsets.fromLTRB(10, 12, 10, 10),
      child: SizedBox(
        height: 120,
        child: TweenAnimationBuilder<double>(
          tween: Tween<double>(begin: 0, end: 1),
          duration: const Duration(milliseconds: 900),
          curve: TempleMotion.entrada,
          builder: (BuildContext c, double v, _) => CustomPaint(
            size: Size.infinite,
            painter: _HistoriaHonorPainter(valores: valores, ascensos: ascensos, color: m.rango < 0 ? TempleColors.violeta : m.color, avance: v),
          ),
        ),
      ),
    );
    if (LimitesPase.pase) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          grafica,
          const SizedBox(height: 6),
          Text('${valores.length} ${valores.length == 1 ? 'semana' : 'semanas'} · ${ascensos.length} '
              '${ascensos.length == 1 ? 'ascenso' : 'ascensos'} (puntos dorados)',
              style: const TextStyle(fontSize: 11.5, color: TempleColors.textoTenue)),
        ],
      );
    }
    return GestureDetector(
      onTap: () => abrirPase(context),
      child: Stack(
        alignment: Alignment.center,
        children: <Widget>[
          ImageFiltered(imageFilter: ImageFilter.blur(sigmaX: 5, sigmaY: 5), child: Opacity(opacity: 0.6, child: grafica)),
          const ChipPase(texto: 'TODA SU HISTORIA CON EL PASE'),
        ],
      ),
    );
  }
}

class _HistoriaHonorPainter extends CustomPainter {
  const _HistoriaHonorPainter({required this.valores, required this.ascensos, required this.color, required this.avance});
  final List<double> valores;
  final Set<int> ascensos;
  final Color color;
  final double avance;

  @override
  void paint(Canvas canvas, Size size) {
    final double maxV = valores.fold<double>(1, math.max);
    final int n = valores.length;
    final double paso = size.width / math.max(1, n);
    final double ancho = math.max(1.5, paso * 0.7);
    for (int i = 0; i < n; i++) {
      final double aparece = ((avance * (n + 6) - i) / 6).clamp(0.0, 1.0);
      final double alto = (size.height - 14) * valores[i] / maxV * aparece;
      final double x = i * paso + (paso - ancho) / 2;
      canvas.drawRRect(
        RRect.fromRectAndRadius(Rect.fromLTWH(x, size.height - 10 - alto, ancho, math.max(1, alto)), Radius.circular(ancho / 2)),
        Paint()
          ..shader = LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: <Color>[color, color.withValues(alpha: 0.25)],
          ).createShader(Rect.fromLTWH(x, 0, ancho, size.height)),
      );
      if (ascensos.contains(i) && aparece > 0.9) {
        final Offset p = Offset(x + ancho / 2, size.height - 14 - alto - 6);
        canvas.drawCircle(p, 5, Paint()..color = const Color(0xFFE8B65A).withValues(alpha: 0.3));
        canvas.drawCircle(p, 2.6, Paint()..color = const Color(0xFFF2D493));
      }
    }
  }

  @override
  bool shouldRepaint(_HistoriaHonorPainter old) => old.avance != avance || old.valores != valores;
}

// ===========================================================================
// 46. EL DOJO EN CASA — entrenar sin gimnasio, y la meta con tus palabras
//
// Mucha gente no pisa un gimnasio: entrena en el salón, con una silla, una
// mesa, una garrafa de agua o nada. Esta sección le da su propio dojo:
// rutinas que se adaptan al material que tiene y a su nivel, la biblioteca
// de ejercicios en casa con su avatar animado, consejos y los pasos hacia su
// meta. Todo cuenta para Ranked: cada flexión mueve parte del peso corporal
// (sección 21, CargaCorporal).
//
// La meta: al crear la cuenta se pregunta qué quiere lograr cada persona y se
// le pide que lo escriba con sus palabras (y, si quiere, una foto de cómo
// está). Esas palabras vuelven de vez en cuando —en el Dojo, en una carta y
// en lo que Tenshi sabe— para recordarle por qué empezó.
//
//   46.1  Material y nivel
//   46.2  Rutinas en casa
//   46.3  Variantes y pasos hacia la meta
//   46.4  Pantalla del dojo en casa
//   46.5  La meta personal
//   46.6  Las páginas de la meta en El Ascenso
//   46.7  El recordatorio: tarjeta del Dojo y carta
//   46.8  Pantalla «Mi meta»
// ===========================================================================

// ---------------------------------------------------------------------------
// 46.1 MATERIAL Y NIVEL
// ---------------------------------------------------------------------------

/// Lo que puede haber en una casa. El suelo y la pared se dan por hechos.
enum MaterialCasa { silla, mesa, escalon, garrafa, banda, mancuernas }

extension DatosMaterialCasa on MaterialCasa {
  String get etiqueta => switch (this) {
        MaterialCasa.silla => 'Una silla firme',
        MaterialCasa.mesa => 'Una mesa robusta',
        MaterialCasa.escalon => 'Un escalón',
        MaterialCasa.garrafa => 'Garrafas o mochila',
        MaterialCasa.banda => 'Banda elástica',
        MaterialCasa.mancuernas => 'Mancuernas',
      };

  IconData get icono => switch (this) {
        MaterialCasa.silla => Icons.chair_alt_outlined,
        MaterialCasa.mesa => Icons.table_restaurant_outlined,
        MaterialCasa.escalon => Icons.stairs_outlined,
        MaterialCasa.garrafa => Icons.water_drop_outlined,
        MaterialCasa.banda => Icons.gesture_rounded,
        MaterialCasa.mancuernas => Icons.fitness_center_rounded,
      };
}

/// Qué hace falta para cada ejercicio de casa. Los que no están, solo piden
/// suelo (y, como mucho, una pared).
