enum NivelCasa { principiante, intermedio, avanzado }

extension DatosNivelCasa on NivelCasa {
  String get etiqueta => switch (this) {
        NivelCasa.principiante => 'Empiezo',
        NivelCasa.intermedio => 'Intermedio',
        NivelCasa.avanzado => 'Avanzado',
      };

  int get series => this == NivelCasa.avanzado ? 4 : 3;

  double get factorReps => switch (this) {
        NivelCasa.principiante => 0.8,
        NivelCasa.intermedio => 1.0,
        NivelCasa.avanzado => 1.25,
      };

  double get factorSegundos => switch (this) {
        NivelCasa.principiante => 0.8,
        NivelCasa.intermedio => 1.0,
        NivelCasa.avanzado => 1.4,
      };
}

/// Segundos de aguante para los ejercicios por tiempo según la experiencia.
int segundosAguante(String? experiencia) => switch (experiencia) {
      'novato' => 25,
      'inicial' => 30,
      'avanzado' => 50,
      _ => 40,
    };

class PreferenciasCasa {
  PreferenciasCasa({required this.nivel, Set<MaterialCasa>? material})
      : material = material ?? <MaterialCasa>{MaterialCasa.silla};

  NivelCasa nivel;
  final Set<MaterialCasa> material;

  Map<String, dynamic> toMap() => <String, dynamic>{
        'nivel': nivel.name,
        'material': material.map((MaterialCasa m) => m.name).toList(),
      };

  static PreferenciasCasa desdeMapa(Map<String, dynamic> m) => PreferenciasCasa(
        nivel: _nEnum(NivelCasa.values, m['nivel']) ?? NivelCasa.principiante,
        material: <MaterialCasa>{
          for (final String x in _nTextos(m['material']))
            if (_nEnum(MaterialCasa.values, x) != null) _nEnum(MaterialCasa.values, x)!,
        },
      );
}

class AlmacenCasaEntreno {
  AlmacenCasaEntreno._();
  static final AlmacenCasaEntreno instancia = AlmacenCasaEntreno._();

  final Map<String, PreferenciasCasa> _prefs = <String, PreferenciasCasa>{};

  PreferenciasCasa de(String usuario) => _prefs.putIfAbsent(usuario, () {
        final String? exp = AlmacenTemplo.instancia.de(usuario).ascenso['experiencia'];
        return PreferenciasCasa(
          nivel: switch (exp) {
            'medio' => NivelCasa.intermedio,
            'avanzado' => NivelCasa.avanzado,
            _ => NivelCasa.principiante,
          },
        );
      });

  void cambiar(String usuario) => NubeTemplo.instancia.marcarCambio();

  Map<String, dynamic>? exportar(String usuario) => _prefs[usuario]?.toMap();

  void importar(String usuario, Object? m) {
    if (m is Map) _prefs[usuario] = PreferenciasCasa.desdeMapa(_nMapa(m));
  }
}

bool _hayMaterial(String id, Set<MaterialCasa> material) =>
    (materialEjercicio[id] ?? const <MaterialCasa>{}).every(material.contains);

