/// La rutina ya resuelta para esta persona: su nivel, su material y su meta.
class RutinaResuelta {
  const RutinaResuelta({required this.rutina, required this.ejercicios, required this.minutos, required this.faltan});
  final RutinaCasa rutina;
  final List<EjercicioPlan> ejercicios;
  final int minutos;

  /// Huecos que se quedaron sin ejercicio por falta de material.
  final int faltan;

  PlanSesion plan() => PlanSesion(
        nombre: 'En casa · ${rutina.nombre}',
        grupos: rutina.grupos.take(3).toList(),
        ejercicios: ejercicios,
        minutos: minutos,
        razon: rutina.descripcion,
      );
}

RutinaResuelta resolverRutina(String usuario, RutinaCasa r) {
  final PreferenciasCasa pref = AlmacenCasaEntreno.instancia.de(usuario);
  final Map<String, String> asc = AlmacenTemplo.instancia.de(usuario).ascenso;
  final String objetivo = asc['objetivo'] ?? 'salud';
  final double porMeta = switch (objetivo) {
    'grasa' => 1.2,
    'fuerza' => 0.8,
    'salud' => 0.9,
    _ => 1.0,
  };
  final int n = pref.nivel.index;
  final List<EjercicioPlan> lista = <EjercicioPlan>[];
  final Set<String> usados = <String>{};
  int faltan = 0;
  for (final BloqueCasa b in r.bloques) {
    // Su nivel primero; si no hay material, el vecino más cercano.
    final List<int> orden = <int>[n, n - 1, n + 1, n - 2, n + 2]
        .where((int i) => i >= 0 && i < b.niveles.length)
        .toList();
    if (b.niveles[n].isEmpty) continue; // hueco que solo existe en otros niveles
    String? elegido;
    for (final int i in orden) {
      for (final String id in b.niveles[i]) {
        if (!usados.contains(id) && _hayMaterial(id, pref.material) && ejercicioPorId(id) != null) {
          elegido = id;
          break;
        }
      }
      if (elegido != null) break;
    }
    if (elegido == null) {
      faltan++;
      continue;
    }
    usados.add(elegido);
    final Ejercicio e = ejercicioPorId(elegido)!;
    final int cant = e.porTiempo
        ? (((b.segundos * pref.nivel.factorSegundos) / 5).round() * 5).clamp(15, 120)
        : (b.reps * pref.nivel.factorReps * porMeta).round().clamp(5, 60);
    lista.add(EjercicioPlan(
      ejercicioId: elegido,
      series: pref.nivel.series,
      repsObjetivo: cant,
      pesoSugerido: AlmacenTemplo.instancia.ultimaSerieDe(usuario, elegido)?.peso,
    ));
  }
  final int series = lista.fold<int>(0, (int a, EjercicioPlan e) => a + e.series);
  final int minutos = (series * (r.circuito ? 1.1 : 1.8)).round() + 4;
  return RutinaResuelta(rutina: r, ejercicios: lista, minutos: math.max(10, minutos), faltan: faltan);
}

/// La rutina que toca hoy: la que trabaja lo que más tiempo lleva sin tocar.
RutinaCasa rutinaRecomendada(String usuario) {
  final AlmacenTemplo a = AlmacenTemplo.instancia;
  if (a.de(usuario).completadas.isEmpty) return rutinasCasa.first;
  final Map<GrupoMuscular, int> deuda = a.deuda(usuario);
  RutinaCasa mejor = rutinasCasa.first;
  double max = -1;
  for (final RutinaCasa r in rutinasCasa) {
    if (r.circuito) continue;
    final RutinaResuelta rr = resolverRutina(usuario, r);
    if (rr.ejercicios.length < 3) continue;
    final double d = r.grupos.map((GrupoMuscular g) => math.min(deuda[g] ?? 30, 30)).fold<int>(0, (int x, int y) => x + y) /
        r.grupos.length;
    if (d > max) {
      max = d;
      mejor = r;
    }
  }
  return mejor;
}

/// Empieza una sesión con este plan, o retoma la que esté a medias.
Future<void> entrenarPlanCasa(BuildContext context, String usuario, PlanSesion plan) async {
  final AlmacenTemplo a = AlmacenTemplo.instancia;
  final Sesion? enCurso = a.de(usuario).enCurso;
  if (enCurso != null) {
    final bool? retomar = await showDialog<bool>(
      context: context,
      builder: (BuildContext ctx) => AlertDialog(
        backgroundColor: TempleColors.superficieAlta,
        title: const Text('Tienes una sesión a medias', style: TextStyle(color: TempleColors.blancoLuna)),
        content: Text('«${enCurso.nombre ?? 'Sesión'}» sigue abierta. Termínala o descártala antes de empezar otra.',
            style: const TextStyle(color: TempleColors.textoSuave, height: 1.4)),
        actions: <Widget>[
          TextButton(onPressed: () => Navigator.of(ctx).pop(false), child: const Text('Ahora no')),
          TextButton(onPressed: () => Navigator.of(ctx).pop(true), child: const Text('Retomarla')),
        ],
      ),
    );
    if (retomar != true || !context.mounted) return;
    await Navigator.of(context).push(MaterialPageRoute<void>(
      builder: (_) => SesionScreen(usuario: usuario, sesion: enCurso),
    ));
    return;
  }
  final int disp = a.disposicion(usuario, plan.grupos).valor;
  final Sesion s = a.abrirSesion(usuario, plan, disp);
  HapticFeedback.mediumImpact();
  await Navigator.of(context).push(MaterialPageRoute<void>(
    builder: (_) => SesionScreen(usuario: usuario, sesion: s),
  ));
}

