class PasoMeta {
  const PasoMeta({required this.titulo, required this.texto, required this.hecho, this.accion, this.textoAccion});
  final String titulo;
  final String texto;
  final bool hecho;
  final Future<void> Function()? accion;
  final String? textoAccion;
}

List<PasoMeta> pasosHaciaLaMeta(BuildContext context, String usuario) {
  final AlmacenTemplo a = AlmacenTemplo.instancia;
  final MetaPersonal? meta = AlmacenMeta.instancia.de(usuario);
  final bool menor = SesionTemplo.instancia.actual?.esMenor ?? false;
  final Racha racha = MotorProgresion.instancia.racha(usuario);
  final List<Sesion> ses = a.de(usuario).completadas;
  final String objetivo = a.de(usuario).ascenso['objetivo'] ?? 'salud';
  final List<FotoProgreso> fotos = CuerpoTemplo.instancia.fotos(usuario);
  Future<void> abrirMeta() =>
      Navigator.of(context).push(MaterialPageRoute<void>(builder: (_) => MetaScreen(usuario: usuario)));
  Future<void> abrirCuerpo() =>
      Navigator.of(context).push(MaterialPageRoute<void>(builder: (_) => CuerpoScreen(usuario: usuario)));

  bool hizoAlguno(Set<String> ids, {int reps = 0}) => ses.any((Sesion s) => s.ejercicios.any((EjercicioSesion e) =>
      ids.contains(e.ejercicioId) && e.seriesEfectivas.any((SerieRegistrada x) => x.repeticiones >= reps)));

  final PasoMeta intermedio = switch (objetivo) {
    'grasa' => PasoMeta(
        titulo: 'Doce sesiones en casa',
        texto: 'Dos rutinas de fuerza y una quema rápida por semana. Lo que comes hace el resto: mira Nutrición.',
        hecho: ses.length >= 12,
      ),
    'musculo' => PasoMeta(
        titulo: 'Sube de variante',
        texto: 'El músculo crece cuando la serie cuesta. Cuando pases de 20 repeticiones, cambia a la versión difícil.',
        hecho: hizoAlguno(<String>{'flexiones_declinadas', 'flexiones_diamante', 'sentadilla_bulgara', 'puente_una_pierna'}) ||
            hizoAlguno(<String>{'flexiones'}, reps: 20),
      ),
    'fuerza' => PasoMeta(
        titulo: 'Tu primer récord en casa',
        texto: 'Más repeticiones limpias o una variante más dura cuentan como récord. El templo los anota solo.',
        hecho: a.de(usuario).records.keys.any(ejerciciosEnCasa.contains),
      ),
    _ => PasoMeta(
        titulo: 'Tres días de movimiento',
        texto: 'No hace falta matarse: tres ratos por semana sostenidos valen más que un lunes heroico.',
        hecho: racha.semanas >= 2,
      ),
  };

  return <PasoMeta>[
    PasoMeta(
      titulo: 'Escribe lo que quieres lograr',
      texto: 'Con tus palabras. El templo te lo recordará cuando más falta haga.',
      hecho: (meta?.texto ?? '').trim().isNotEmpty,
      accion: abrirMeta,
      textoAccion: 'Escribir',
    ),
    if (!menor)
      PasoMeta(
        titulo: 'Guarda tu foto de partida',
        texto: 'Privada: solo tú la ves. Dentro de unas semanas será la mejor prueba de tu cambio.',
        hecho: meta?.fotoId != null || fotos.isNotEmpty,
        accion: abrirMeta,
        textoAccion: 'Añadir',
      )
    else
      PasoMeta(
        titulo: 'Anota tus medidas',
        texto: 'Cintura, brazo y lo que quieras seguir. Así verás el avance con números.',
        hecho: CuerpoTemplo.instancia.medidas(usuario).isNotEmpty,
        accion: abrirCuerpo,
        textoAccion: 'Anotar',
      ),
    PasoMeta(
      titulo: 'Tu primera semana completa',
      texto: 'Cumple los días que elegiste. La primera semana es la que más cuesta.',
      hecho: racha.semanas >= 1 || racha.semanaCumplida,
    ),
    intermedio,
    PasoMeta(
      titulo: 'Cuatro semanas seguidas',
      texto: 'A las cuatro semanas el hábito ya es tuyo. Es cuando empieza a notarse.',
      hecho: racha.semanas >= 4,
    ),
    if (!menor)
      PasoMeta(
        titulo: 'Compárate con tu foto de partida',
        texto: 'Misma luz, misma pose, misma distancia. Mira lo que cambió.',
        hecho: fotos.length >= 2 && fotos.first.fecha.difference(fotos.last.fecha).inDays >= 28,
        accion: abrirCuerpo,
        textoAccion: 'Abrir',
      ),
  ];
}

