Future<void> abrirDojoCasa(BuildContext context, String usuario) =>
    Navigator.of(context).push(MaterialPageRoute<void>(builder: (_) => DojoCasaScreen(usuario: usuario)));

class DojoCasaScreen extends StatefulWidget {
  const DojoCasaScreen({super.key, required this.usuario});
  final String usuario;

  @override
  State<DojoCasaScreen> createState() => _DojoCasaScreenState();
}

class _DojoCasaScreenState extends State<DojoCasaScreen> {
  PreferenciasCasa get _pref => AlmacenCasaEntreno.instancia.de(widget.usuario);

  void _cambio() {
    AlmacenCasaEntreno.instancia.cambiar(widget.usuario);
    HapticFeedback.selectionClick();
    setState(() {});
  }

  Future<void> _empezar(RutinaResuelta r) async {
    if (r.ejercicios.isEmpty) {
      avisoClan(context, r.rutina.pide ?? 'Marca qué material tienes para armar esta rutina.', error: true);
      return;
    }
    await entrenarPlanCasa(context, widget.usuario, r.plan());
    if (mounted) setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final String u = widget.usuario;
    final PreferenciasCasa pref = _pref;
    final RutinaCasa recomendada = rutinaRecomendada(u);
    final List<PasoMeta> pasos = pasosHaciaLaMeta(context, u);
    final int hechos = pasos.where((PasoMeta p) => p.hecho).length;
    final MetaPersonal? meta = AlmacenMeta.instancia.de(u);

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: SafeArea(
          child: ListView(
            padding: const EdgeInsets.fromLTRB(TempleSpace.borde, 4, TempleSpace.borde, 40),
            children: <Widget>[
              Row(
                children: <Widget>[
                  IconButton(
                    onPressed: () => Navigator.of(context).maybePop(),
                    icon: const Icon(Icons.arrow_back_rounded, color: TempleColors.textoSuave),
                  ),
                  const Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: <Widget>[
                        Text('El dojo en casa',
                            style: TextStyle(fontSize: 19, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                        Text('Tu cuerpo, una silla y lo que tengas a mano',
                            style: TextStyle(fontSize: 12, color: TempleColors.textoSuave)),
                      ],
                    ),
                  ),
                  const BotonPase(),
                ],
              ),
              const SizedBox(height: 14),
              _HeroCasa(meta: meta),
              const SizedBox(height: TempleSpace.l),

              const EtiquetaSeccion('Tu nivel'),
              SegmentedButton<NivelCasa>(
                segments: <ButtonSegment<NivelCasa>>[
                  for (final NivelCasa n in NivelCasa.values)
                    ButtonSegment<NivelCasa>(value: n, label: Text(n.etiqueta, style: const TextStyle(fontSize: 12.5))),
                ],
                selected: <NivelCasa>{pref.nivel},
                showSelectedIcon: false,
                onSelectionChanged: (Set<NivelCasa> s) {
                  pref.nivel = s.first;
                  _cambio();
                },
                style: ButtonStyle(
                  foregroundColor: WidgetStateProperty.resolveWith((Set<WidgetState> st) =>
                      st.contains(WidgetState.selected) ? TempleColors.blancoLuna : TempleColors.textoSuave),
                  backgroundColor: WidgetStateProperty.resolveWith((Set<WidgetState> st) =>
                      st.contains(WidgetState.selected) ? TempleColors.violeta.withValues(alpha: 0.32) : Colors.transparent),
                  side: const WidgetStatePropertyAll<BorderSide>(BorderSide(color: TempleColors.borde)),
                ),
              ),
              const SizedBox(height: TempleSpace.l),

              const EtiquetaSeccion('Lo que tienes en casa'),
              Wrap(
                spacing: 8,
                runSpacing: 8,
                children: <Widget>[
                  for (final MaterialCasa m in MaterialCasa.values)
                    FilterChip(
                      avatar: Icon(m.icono,
                          size: 16, color: pref.material.contains(m) ? TempleColors.blancoLuna : TempleColors.textoSuave),
                      label: Text(m.etiqueta),
                      selected: pref.material.contains(m),
                      showCheckmark: false,
                      onSelected: (bool v) {
                        if (v) {
                          pref.material.add(m);
                        } else {
                          pref.material.remove(m);
                        }
                        _cambio();
                      },
                      labelStyle: TextStyle(
                          fontSize: 12.5,
                          color: pref.material.contains(m) ? TempleColors.blancoLuna : TempleColors.textoSuave),
                      backgroundColor: TempleColors.superficie,
                      selectedColor: TempleColors.violeta.withValues(alpha: 0.30),
                      side: BorderSide(color: pref.material.contains(m) ? TempleColors.violeta : TempleColors.borde),
                    ),
                ],
              ),
              const SizedBox(height: 6),
              const Text('El suelo y una pared siempre cuentan. Sin nada más, también hay rutina.',
                  style: TextStyle(fontSize: 11.5, color: TempleColors.textoTenue)),
              const SizedBox(height: TempleSpace.l),

              const EtiquetaSeccion('Rutinas en casa'),
              for (final RutinaCasa r in rutinasCasa) ...<Widget>[
                _TarjetaRutinaCasa(
                  resuelta: resolverRutina(u, r),
                  recomendada: r.id == recomendada.id,
                  onEmpezar: _empezar,
                  onTecnica: (String id) => mostrarTecnica(context, id, usuario: u),
                ),
                const SizedBox(height: 12),
              ],
              const SizedBox(height: TempleSpace.l - 12),

              EtiquetaSeccion('Ejercicios en casa',
                  accion: Text('${ejerciciosEnCasa.length}',
                      style: const TextStyle(fontSize: 12, color: TempleColors.textoTenue))),
              for (final GrupoMuscular g in GrupoMuscular.values) _FilaEjerciciosCasa(usuario: u, grupo: g, material: pref.material),
              const SizedBox(height: TempleSpace.l),

              EtiquetaSeccion('Tu camino hacia la meta',
                  accion: Text('$hechos de ${pasos.length}',
                      style: const TextStyle(fontSize: 12, color: TempleColors.violetaClaro))),
              _CaminoMeta(pasos: pasos, onVolver: () => setState(() {})),
              const SizedBox(height: TempleSpace.l),

              const EtiquetaSeccion('Consejos para entrenar en casa'),
              for (final (IconData, String, String) c in consejosCasa) _ConsejoCasa(icono: c.$1, titulo: c.$2, texto: c.$3),
            ],
          ),
        ),
      ),
    );
  }
}

/// Cabecera: el guerrero va cambiando de ejercicio cada pocos segundos.
class _HeroCasa extends StatefulWidget {
  const _HeroCasa({required this.meta});
  final MetaPersonal? meta;

  @override
  State<_HeroCasa> createState() => _HeroCasaState();
}

class _HeroCasaState extends State<_HeroCasa> {
  static const List<String> _desfile = <String>[
    'flexiones_inclinadas', 'sentadilla_salto', 'remo_mesa', 'escaladores', 'fondos_silla',
    'saltos_tijera', 'sentadilla_bulgara', 'superman', 'flexiones_pica', 'paseo_granjero',
  ];
  int _i = 0;
  Timer? _t;

  @override
  void initState() {
    super.initState();
    _t = Timer.periodic(const Duration(milliseconds: 4200), (_) {
      if (mounted) setState(() => _i = (_i + 1) % _desfile.length);
    });
  }

  @override
  void dispose() {
    _t?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final String id = _desfile[_i];
    final String? texto = widget.meta?.texto.trim();
    return TempleCard(
      destacada: true,
      padding: const EdgeInsets.fromLTRB(10, 10, 16, 10),
      child: Row(
        children: <Widget>[
          SizedBox(
            width: 128,
            height: 128,
            child: AnimatedSwitcher(
              duration: const Duration(milliseconds: 500),
              transitionBuilder: (Widget c, Animation<double> a) => FadeTransition(
                opacity: a,
                child: ScaleTransition(scale: Tween<double>(begin: 0.92, end: 1).animate(a), child: c),
              ),
              child: AvatarEjercicio(key: ValueKey<String>(id), ejercicioId: id, size: 128),
            ),
          ),
          const SizedBox(width: 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: <Widget>[
                AnimatedSwitcher(
                  duration: const Duration(milliseconds: 400),
                  child: Text(ejercicioPorId(id)?.nombre ?? '',
                      key: ValueKey<String>('n$id'),
                      style: const TextStyle(fontSize: 12, color: TempleColors.violetaClaro)),
                ),
                const SizedBox(height: 6),
                Text(
                  texto == null || texto.isEmpty
                      ? 'Sin gimnasio no hay excusa ni castigo: hay un dojo en tu salón.'
                      : '«${texto.length > 110 ? '${texto.substring(0, 110).trimRight()}…' : texto}»',
                  maxLines: 5,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(fontSize: 13.5, height: 1.45, color: TempleColors.blancoLuna),
                ),
                if (texto != null && texto.isNotEmpty) ...<Widget>[
                  const SizedBox(height: 4),
                  const Text('Lo escribiste tú', style: TextStyle(fontSize: 11, color: TempleColors.textoTenue)),
                ],
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _TarjetaRutinaCasa extends StatelessWidget {
  const _TarjetaRutinaCasa({
    required this.resuelta,
    required this.recomendada,
    required this.onEmpezar,
    required this.onTecnica,
  });

  final RutinaResuelta resuelta;
  final bool recomendada;
  final ValueChanged<RutinaResuelta> onEmpezar;
  final ValueChanged<String> onTecnica;

  @override
  Widget build(BuildContext context) {
    final RutinaCasa r = resuelta.rutina;
    final bool vacia = resuelta.ejercicios.isEmpty;
    return TempleCard(
      destacada: recomendada,
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Row(
            children: <Widget>[
              Container(
                width: 46,
                height: 46,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(TempleRadius.chip),
                  color: TempleColors.violeta.withValues(alpha: recomendada ? 0.24 : 0.10),
                ),
                child: Text(r.kanji,
                    style: TextStyle(
                        fontSize: r.kanji.length > 1 ? 17 : 22,
                        color: recomendada ? TempleColors.blancoLuna : TempleColors.violetaClaro)),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    Row(
                      children: <Widget>[
                        Flexible(
                          child: Text(r.nombre,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                  fontSize: 15.5, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                        ),
                        if (recomendada) ...<Widget>[
                          const SizedBox(width: 8),
                          Container(
                            padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 2),
                            decoration: BoxDecoration(
                              borderRadius: BorderRadius.circular(999),
                              color: TempleColors.violeta.withValues(alpha: 0.25),
                            ),
                            child: const Text('Hoy',
                                style: TextStyle(fontSize: 10, color: TempleColors.violetaClaro)),
                          ),
                        ],
                      ],
                    ),
                    const SizedBox(height: 2),
                    Text(
                      vacia
                          ? 'Falta material'
                          : '${resuelta.minutos} min · ${resuelta.ejercicios.length} ejercicios'
                              '${r.circuito ? ' · circuito' : ''}',
                      style: const TextStyle(fontSize: 12, color: TempleColors.textoSuave),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          Text(r.descripcion, style: const TextStyle(fontSize: 12.5, height: 1.45, color: TempleColors.textoSuave)),
          const SizedBox(height: 10),
          if (!vacia)
            SizedBox(
              height: 112,
              child: ListView.separated(
                scrollDirection: Axis.horizontal,
                itemCount: resuelta.ejercicios.length,
                separatorBuilder: (_, __) => const SizedBox(width: 8),
                itemBuilder: (BuildContext c, int i) {
                  final EjercicioPlan e = resuelta.ejercicios[i];
                  final bool tiempo = ejercicioPorId(e.ejercicioId)?.porTiempo ?? false;
                  return GestureDetector(
                    onTap: () => onTecnica(e.ejercicioId),
                    child: Container(
                      width: 92,
                      decoration: BoxDecoration(
                        color: TempleColors.superficie,
                        borderRadius: BorderRadius.circular(TempleRadius.chip),
                        border: Border.all(color: TempleColors.borde),
                      ),
                      child: Column(
                        children: <Widget>[
                          AvatarEjercicio(ejercicioId: e.ejercicioId, size: 70, animado: recomendada),
                          Padding(
                            padding: const EdgeInsets.symmetric(horizontal: 5),
                            child: Text(e.nombre,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(fontSize: 10.5, color: TempleColors.texto)),
                          ),
                          Text('${e.series} × ${e.repsObjetivo}${tiempo ? ' s' : ''}',
                              style: const TextStyle(fontSize: 10.5, color: TempleColors.violetaClaro)),
                        ],
                      ),
                    ),
                  );
                },
              ),
            ),
          if (resuelta.faltan > 0 && r.pide != null) ...<Widget>[
            const SizedBox(height: 8),
            Text(r.pide!, style: const TextStyle(fontSize: 11.5, height: 1.4, color: TempleColors.alertaSuave)),
          ],
          Align(
            alignment: Alignment.centerRight,
            child: TextButton.icon(
              onPressed: () => onEmpezar(resuelta),
              icon: const Icon(Icons.play_arrow_rounded, size: 18),
              label: const Text('Empezar'),
              style: TextButton.styleFrom(foregroundColor: TempleColors.violetaClaro),
            ),
          ),
        ],
      ),
    );
  }
}

class _FilaEjerciciosCasa extends StatelessWidget {
  const _FilaEjerciciosCasa({required this.usuario, required this.grupo, required this.material});
  final String usuario;
  final GrupoMuscular grupo;
  final Set<MaterialCasa> material;

  @override
  Widget build(BuildContext context) {
    final List<Ejercicio> l = <Ejercicio>[
      for (final String id in ejerciciosEnCasa)
        if (ejercicioPorId(id)?.grupoPrincipal == grupo) ejercicioPorId(id)!,
    ];
    if (l.isEmpty) return const SizedBox.shrink();
    return Padding(
      padding: const EdgeInsets.only(bottom: 14),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Text(grupo.etiqueta,
              style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: TempleColors.texto)),
          const SizedBox(height: 8),
          SizedBox(
            height: 150,
            child: ListView.separated(
              scrollDirection: Axis.horizontal,
              itemCount: l.length,
              separatorBuilder: (_, __) => const SizedBox(width: 10),
              itemBuilder: (BuildContext c, int i) {
                final Ejercicio e = l[i];
                final bool hay = _hayMaterial(e.id, material);
                final Set<MaterialCasa> pide = materialEjercicio[e.id] ?? const <MaterialCasa>{};
                return GestureDetector(
                  onTap: () => mostrarTecnica(context, e.id, usuario: usuario),
                  child: Opacity(
                    opacity: hay ? 1 : 0.55,
                    child: Container(
                      width: 118,
                      padding: const EdgeInsets.only(bottom: 6),
                      decoration: BoxDecoration(
                        color: TempleColors.superficie,
                        borderRadius: BorderRadius.circular(TempleRadius.chip),
                        border: Border.all(color: TempleColors.borde),
                      ),
                      child: Column(
                        children: <Widget>[
                          AvatarEjercicio(ejercicioId: e.id, size: 100),
                          Padding(
                            padding: const EdgeInsets.symmetric(horizontal: 6),
                            child: Text(e.nombre,
                                maxLines: 2,
                                textAlign: TextAlign.center,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(fontSize: 11, height: 1.2, color: TempleColors.texto)),
                          ),
                          const Spacer(),
                          if (pide.isNotEmpty)
                            Row(
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: <Widget>[
                                for (final MaterialCasa m in pide)
                                  Icon(m.icono, size: 12, color: hay ? TempleColors.textoTenue : TempleColors.alertaSuave),
                              ],
                            ),
                        ],
                      ),
                    ),
                  ),
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

class _CaminoMeta extends StatelessWidget {
  const _CaminoMeta({required this.pasos, required this.onVolver});
  final List<PasoMeta> pasos;
  final VoidCallback onVolver;

  @override
  Widget build(BuildContext context) {
    final int hechos = pasos.where((PasoMeta p) => p.hecho).length;
    return TempleCard(
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 6),
      child: Column(
        children: <Widget>[
          ClipRRect(
            borderRadius: BorderRadius.circular(999),
            child: TweenAnimationBuilder<double>(
              tween: Tween<double>(begin: 0, end: pasos.isEmpty ? 0 : hechos / pasos.length),
              duration: const Duration(milliseconds: 900),
              curve: TempleMotion.suave,
              builder: (BuildContext c, double v, _) => LinearProgressIndicator(
                value: v,
                minHeight: 5,
                backgroundColor: TempleColors.borde,
                valueColor: const AlwaysStoppedAnimation<Color>(TempleColors.violeta),
              ),
            ),
          ),
          const SizedBox(height: 10),
          for (int i = 0; i < pasos.length; i++)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 6),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  AnimatedContainer(
                    duration: TempleMotion.medio,
                    width: 26,
                    height: 26,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: pasos[i].hecho ? TempleColors.exito.withValues(alpha: 0.18) : TempleColors.superficieAlta,
                      border: Border.all(color: pasos[i].hecho ? TempleColors.exito : TempleColors.borde),
                    ),
                    child: pasos[i].hecho
                        ? const Icon(Icons.check_rounded, size: 15, color: TempleColors.exito)
                        : Text('${i + 1}', style: const TextStyle(fontSize: 11.5, color: TempleColors.textoSuave)),
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: <Widget>[
                        Text(pasos[i].titulo,
                            style: TextStyle(
                                fontSize: 13.5,
                                fontWeight: FontWeight.w600,
                                color: pasos[i].hecho ? TempleColors.textoSuave : TempleColors.blancoLuna,
                                decoration: pasos[i].hecho ? TextDecoration.lineThrough : null,
                                decorationColor: TempleColors.textoTenue)),
                        const SizedBox(height: 2),
                        Text(pasos[i].texto,
                            style: const TextStyle(fontSize: 12, height: 1.4, color: TempleColors.textoTenue)),
                      ],
                    ),
                  ),
                  if (!pasos[i].hecho && pasos[i].accion != null)
                    TextButton(
                      onPressed: () async {
                        await pasos[i].accion!();
                        onVolver();
                      },
                      style: TextButton.styleFrom(
                        foregroundColor: TempleColors.violetaClaro,
                        minimumSize: Size.zero,
                        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                      ),
                      child: Text(pasos[i].textoAccion ?? 'Ir', style: const TextStyle(fontSize: 12)),
                    ),
                ],
              ),
            ),
        ],
      ),
    );
  }
}

