/// Metas concretas según lo que eligió en El Ascenso.
const Map<String, List<(String, String)>> metasConcretas = <String, List<(String, String)>>{
  'grasa': <(String, String)>[
    ('talla', 'Bajar de talla'),
    ('abdomen', 'Marcar el abdomen'),
    ('ligero', 'Sentirme más ligero'),
    ('peso', 'Llegar a un peso concreto'),
    ('energia', 'Tener más energía'),
  ],
  'musculo': <(String, String)>[
    ('brazos', 'Brazos más grandes'),
    ('espalda', 'Espalda en V'),
    ('piernas', 'Piernas fuertes'),
    ('ganar', 'Ganar peso sano'),
    ('atletico', 'Verme atlético'),
  ],
  'fuerza': <(String, String)>[
    ('dominada', 'Mi primera dominada'),
    ('flexiones', '20 flexiones seguidas'),
    ('levantar', 'Levantar mi propio peso'),
    ('diario', 'Fuerza para el día a día'),
    ('competir', 'Prepararme para competir'),
  ],
  'salud': <(String, String)>[
    ('dormir', 'Dormir mejor'),
    ('energia', 'Tener más energía'),
    ('constancia', 'Entrenar sin faltar'),
    ('espalda', 'Cuidar mi espalda'),
    ('moverme', 'Moverme más cada día'),
  ],
};

const List<(String, String)> plazosMeta = <(String, String)>[
  ('1m', 'Un mes'),
  ('3m', 'Tres meses'),
  ('6m', 'Seis meses'),
  ('1a', 'Un año'),
  ('sin', 'Sin prisa'),
];

String? etiquetaMeta(String? objetivo, String? tipo) {
  if (tipo == null) return null;
  for (final (String, String) m in metasConcretas[objetivo] ?? const <(String, String)>[]) {
    if (m.$1 == tipo) return m.$2;
  }
  for (final List<(String, String)> l in metasConcretas.values) {
    for (final (String, String) m in l) {
      if (m.$1 == tipo) return m.$2;
    }
  }
  return null;
}

String? etiquetaPlazo(String? plazo) {
  for (final (String, String) p in plazosMeta) {
    if (p.$1 == plazo) return p.$2;
  }
  return null;
}

class MetaPersonal {
  MetaPersonal({
    this.tipo,
    this.plazo,
    this.texto = '',
    DateTime? creada,
    DateTime? editada,
    this.fotoId,
    this.fotoPendiente,
    this.frecuencia = 'aveces',
    this.ultimoRecuerdo,
    this.cerradoEl,
    this.ultimaCarta,
  })  : creada = creada ?? DateTime.now(),
        editada = editada ?? DateTime.now();

  String? tipo;
  String? plazo;
  String texto;
  DateTime creada;
  DateTime editada;

  /// La foto de partida, dentro de las fotos privadas de Cuerpo.
  String? fotoId;

  /// Ruta local si no se pudo subir (sin conexión). Se reintenta al abrir.
  String? fotoPendiente;

  /// 'menudo' (cada dos días), 'aveces' (cada cuatro) o 'nunca'.
  String frecuencia;
  DateTime? ultimoRecuerdo;
  DateTime? cerradoEl;
  DateTime? ultimaCarta;

  int get dias => DateTime.now().difference(creada).inDays;

  Map<String, dynamic> toMap() => <String, dynamic>{
        'tipo': tipo,
        'plazo': plazo,
        'texto': texto,
        'creada': creada.toIso8601String(),
        'editada': editada.toUtc().toIso8601String(),
        'foto': fotoId,
        'frecuencia': frecuencia,
        'ultimo_recuerdo': ultimoRecuerdo?.toIso8601String(),
        'cerrado_el': cerradoEl?.toIso8601String(),
        'ultima_carta': ultimaCarta?.toIso8601String(),
      };

  static MetaPersonal desdeMapa(Map<String, dynamic> m) => MetaPersonal(
        tipo: _nTexto(m['tipo']),
        plazo: _nTexto(m['plazo']),
        texto: (_nTexto(m['texto']) ?? '').trim(),
        creada: _nFecha(m['creada']),
        editada: _nFecha(m['editada']),
        fotoId: _nTexto(m['foto']),
        frecuencia: _nTexto(m['frecuencia']) ?? 'aveces',
        ultimoRecuerdo: _nFecha(m['ultimo_recuerdo']),
        cerradoEl: _nFecha(m['cerrado_el']),
        ultimaCarta: _nFecha(m['ultima_carta']),
      );
}

class AlmacenMeta {
  AlmacenMeta._();
  static final AlmacenMeta instancia = AlmacenMeta._();

  final Map<String, MetaPersonal> _metas = <String, MetaPersonal>{};

  /// Si la persona dijo «ahora no» a escribirla, cuándo.
  final Map<String, DateTime> _invitacionCerrada = <String, DateTime>{};

  MetaPersonal? de(String usuario) => _metas[usuario];

  void guardar(String usuario, MetaPersonal m) {
    m.editada = DateTime.now();
    _metas[usuario] = m;
    NubeTemplo.instancia.marcarCambio();
  }

  void tocar(String usuario) => NubeTemplo.instancia.marcarCambio();

  Map<String, dynamic>? exportar(String usuario) => _metas[usuario]?.toMap();

  void importar(String usuario, Object? m) {
    if (m is Map) {
      final MetaPersonal nueva = MetaPersonal.desdeMapa(_nMapa(m));
      final String? pendiente = _metas[usuario]?.fotoPendiente;
      nueva.fotoPendiente ??= pendiente;
      _metas[usuario] = nueva;
    }
  }

  /// La foto de partida, si sigue entre las fotos de Cuerpo.
  FotoProgreso? foto(String usuario) {
    final String? id = _metas[usuario]?.fotoId;
    if (id == null) return null;
    for (final FotoProgreso f in CuerpoTemplo.instancia.fotos(usuario)) {
      if (f.id == id) return f;
    }
    return null;
  }

  /// Sube la foto de partida. Si no hay conexión, la deja pendiente.
  Future<bool> subirFoto(String usuario, XFile archivo) async {
    final MetaPersonal m = _metas[usuario] ?? MetaPersonal();
    _metas[usuario] = m;
    try {
      final FotoProgreso f = await CuerpoTemplo.instancia.subirFoto(usuario, archivo, 'frente');
      m.fotoId = f.id;
      m.fotoPendiente = null;
      NubeTemplo.instancia.marcarCambio();
      return true;
    } catch (_) {
      m.fotoPendiente = archivo.path;
      return false;
    }
  }

  bool _reintentando = false;
  DateTime _ultimoIntento = DateTime.fromMillisecondsSinceEpoch(0);

  /// Se llama al abrir el Dojo: si quedó una foto sin subir, otro intento
  /// (como mucho cada cinco minutos).
  Future<void> reintentarFoto(String usuario) async {
    final String? ruta = _metas[usuario]?.fotoPendiente;
    if (ruta == null || _reintentando || SesionTemplo.instancia.uid == null) return;
    if (DateTime.now().difference(_ultimoIntento).inMinutes < 5) return;
    _reintentando = true;
    _ultimoIntento = DateTime.now();
    try {
      final XFile f = XFile(ruta);
      try {
        await f.length();
      } catch (_) {
        // El archivo temporal ya no existe: se olvida sin molestar.
        _metas[usuario]?.fotoPendiente = null;
        return;
      }
      await subirFoto(usuario, f);
    } finally {
      _reintentando = false;
    }
  }

  /// Lo que Tenshi debe saber, recortado para no llenar su contexto.
  String? paraTenshi(String usuario) {
    final MetaPersonal? m = _metas[usuario];
    if (m == null) return null;
    final String obj = AlmacenTemplo.instancia.de(usuario).ascenso['objetivo'] ?? 'salud';
    final String? concreta = etiquetaMeta(obj, m.tipo);
    final String? plazo = etiquetaPlazo(m.plazo);
    final String t = m.texto.trim();
    if (t.isEmpty && concreta == null) return null;
    final String recorte = t.length > 420 ? '${t.substring(0, 420)}…' : t;
    return <String>[
      if (concreta != null) 'Su meta concreta: ${concreta.toLowerCase()}${plazo == null ? '' : ' (plazo: ${plazo.toLowerCase()})'}.',
      if (recorte.isNotEmpty)
        'Lo que escribió hace ${m.dias} ${m.dias == 1 ? 'día' : 'días'}, con sus palabras: «$recorte». '
            'Recuérdaselo solo cuando de verdad ayude (cuando duda, vuelve tras una pausa o lo pide), nunca en cada mensaje.',
    ].join(' ');
  }
}

