  @override
  Widget build(BuildContext context) {
    final List<(String, String)> opciones = metasConcretas[objetivo] ?? metasConcretas['salud']!;
    Widget chip(String id, String texto, bool sel, ValueChanged<String> f) => ChoiceChip(
          label: Text(texto),
          selected: sel,
          showCheckmark: false,
          onSelected: (_) {
            HapticFeedback.selectionClick();
