      padding: const EdgeInsets.fromLTRB(26, 26, 26, 30),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: <Widget>[
          const Text('¿Qué quieres lograr, exactamente?',
              style: TextStyle(fontSize: 25, height: 1.25, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
          const SizedBox(height: 10),
          const Text('Elige lo que más se parezca. En la siguiente pantalla lo cuentas con tus palabras.',
              style: TextStyle(fontSize: 13.5, height: 1.5, color: TempleColors.textoSuave)),
          const SizedBox(height: 26),
          Wrap(
            spacing: 8,
            runSpacing: 10,
            children: <Widget>[for (final (String, String) o in opciones) chip(o.$1, o.$2, tipo == o.$1, onTipo)],
          ),
          const SizedBox(height: 30),
          const Text('¿Para cuándo?',
              style: TextStyle(fontSize: 16, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
          const SizedBox(height: 4),
          const Text('Un plazo realista ayuda. «Sin prisa» también es una respuesta.',
              style: TextStyle(fontSize: 12.5, color: TempleColors.textoTenue)),
          const SizedBox(height: 14),
          Wrap(
            spacing: 8,
            runSpacing: 10,
            children: <Widget>[for (final (String, String) p in plazosMeta) chip(p.$1, p.$2, plazo == p.$1, onPlazo)],
          ),
          const SizedBox(height: 36),
          AnimatedOpacity(
            duration: TempleMotion.medio,
            opacity: tipo == null ? 0.45 : 1,
            child: DojoPrimaryButton(texto: 'Seguir', onPressed: tipo == null ? () {} : onSeguir),
          ),
        ],
      ),
