class _PaginaMetaTextoState extends State<_PaginaMetaTexto> {
  late final TextEditingController _c = TextEditingController(text: widget.inicial);

  static const List<String> _ayudas = <String>[
    'Quiero…',
    'Porque…',
    'Cuando lo logre, voy a…',
    'Lo que más me cuesta es…',
  ];

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  void _anadir(String a) {
    final String t = _c.text.trimRight();
    _c.text = t.isEmpty ? '$a ' : '$t\n$a ';
    _c.selection = TextSelection.collapsed(offset: _c.text.length);
    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final int largo = _c.text.trim().length;
    return SingleChildScrollView(
      padding: const EdgeInsets.fromLTRB(26, 26, 26, 30),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: <Widget>[
          const Text('Escríbelo con tus palabras',
              style: TextStyle(fontSize: 25, height: 1.25, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
          const SizedBox(height: 10),
          const Text(
            'Qué quieres cumplir, cómo te quieres ver y sentir, y por qué ahora. '
            'Con detalle: el templo te lo devolverá de vez en cuando, cuando más falta haga.',
            style: TextStyle(fontSize: 13.5, height: 1.5, color: TempleColors.textoSuave),
          ),
          const SizedBox(height: 18),
          Wrap(
            spacing: 6,
            runSpacing: 6,
            children: <Widget>[
              for (final String a in _ayudas)
                ActionChip(
                  label: Text(a, style: const TextStyle(fontSize: 12, color: TempleColors.violetaClaro)),
                  onPressed: () => _anadir(a),
                  backgroundColor: TempleColors.superficie,
                  side: const BorderSide(color: TempleColors.borde),
                ),
            ],
          ),
          const SizedBox(height: 12),
          TextField(
            controller: _c,
            minLines: 6,
            maxLines: 10,
            maxLength: 800,
            textCapitalization: TextCapitalization.sentences,
            onChanged: (_) => setState(() {}),
            style: const TextStyle(fontSize: 14.5, height: 1.5, color: TempleColors.blancoLuna),
            decoration: InputDecoration(
              hintText: 'Ej.: Quiero poder jugar con mis hijos sin cansarme y volver a ponerme ese pantalón. '
                  'Porque llevo dos años diciéndolo y este es el año.',
              hintMaxLines: 4,
              hintStyle: const TextStyle(fontSize: 13.5, height: 1.45, color: TempleColors.textoTenue),
              filled: true,
              fillColor: TempleColors.superficie,
              counterStyle: const TextStyle(color: TempleColors.textoTenue),
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(TempleRadius.campo),
                borderSide: const BorderSide(color: TempleColors.borde),
              ),
              enabledBorder: OutlineInputBorder(
                borderRadius: BorderRadius.circular(TempleRadius.campo),
                borderSide: const BorderSide(color: TempleColors.borde),
              ),
              focusedBorder: OutlineInputBorder(
                borderRadius: BorderRadius.circular(TempleRadius.campo),
                borderSide: const BorderSide(color: TempleColors.violeta),
              ),
            ),
          ),
          const SizedBox(height: 4),
          const Row(
            children: <Widget>[
              Icon(Icons.lock_outline_rounded, size: 14, color: TempleColors.textoTenue),
              SizedBox(width: 6),
              Expanded(
                child: Text('Es privado: no aparece en tu perfil ni en el Clan.',
                    style: TextStyle(fontSize: 11.5, color: TempleColors.textoTenue)),
              ),
            ],
          ),
          const SizedBox(height: 26),
          AnimatedOpacity(
            duration: TempleMotion.medio,
            opacity: largo < 12 ? 0.45 : 1,
            child: DojoPrimaryButton(
              texto: 'Guardar mis palabras',
              onPressed: () {
