class _PaginaMetaFotoState extends State<_PaginaMetaFoto> {
  XFile? _foto;
  Uint8List? _vista;

  Future<void> _elegir(ImageSource fuente) async {
    try {
      final XFile? f = await ImagePicker().pickImage(source: fuente, maxWidth: 1400, maxHeight: 1400, imageQuality: 82);
      if (f == null) return;
      final Uint8List b = await f.readAsBytes();
      if (!mounted) return;
      setState(() {
        _foto = f;
        _vista = b;
      });
    } catch (_) {
      if (mounted) avisoClan(context, 'No se pudo abrir la cámara o la galería.', error: true);
    }
  }

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      padding: const EdgeInsets.fromLTRB(26, 26, 26, 30),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: <Widget>[
          const Text('¿Cómo estás hoy?',
              style: TextStyle(fontSize: 25, height: 1.25, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
          const SizedBox(height: 10),
          const Text(
            'Si quieres, guarda una foto de tu punto de partida. Dentro de unas semanas la pondrás al lado '
            'de una nueva y verás lo que el espejo no te cuenta.',
            style: TextStyle(fontSize: 13.5, height: 1.5, color: TempleColors.textoSuave),
          ),
          const SizedBox(height: 22),
          AspectRatio(
            aspectRatio: 3 / 4,
            child: Container(
              decoration: BoxDecoration(
                color: TempleColors.superficie,
                borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
                border: Border.all(color: _vista == null ? TempleColors.borde : TempleColors.violeta),
              ),
              clipBehavior: Clip.antiAlias,
              child: _vista == null
                  ? const Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: <Widget>[
                        Icon(Icons.accessibility_new_rounded, size: 64, color: TempleColors.textoTenue),
                        SizedBox(height: 10),
                        Padding(
                          padding: EdgeInsets.symmetric(horizontal: 26),
                          child: Text('De frente, con buena luz y ropa ajustada. Repite siempre la misma pose.',
                              textAlign: TextAlign.center,
                              style: TextStyle(fontSize: 12.5, height: 1.4, color: TempleColors.textoTenue)),
                        ),
                      ],
                    )
                  : Image.memory(_vista!, fit: BoxFit.cover),
            ),
          ),
          const SizedBox(height: 14),
          Row(
            children: <Widget>[
              Expanded(
                child: OutlinedButton.icon(
                  onPressed: () => _elegir(ImageSource.camera),
                  icon: const Icon(Icons.photo_camera_outlined, size: 18),
                  label: const Text('Hacer foto'),
                  style: OutlinedButton.styleFrom(
                    foregroundColor: TempleColors.violetaClaro,
                    side: const BorderSide(color: TempleColors.borde),
                    padding: const EdgeInsets.symmetric(vertical: 13),
                  ),
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: OutlinedButton.icon(
                  onPressed: () => _elegir(ImageSource.gallery),
                  icon: const Icon(Icons.photo_library_outlined, size: 18),
                  label: const Text('Galería'),
