// ---------------------------------------------------------------------------
// 46.7 EL RECORDATORIO: TARJETA DEL DOJO Y CARTA
// ---------------------------------------------------------------------------

class RecordatorioMeta {
  const RecordatorioMeta._();

  static bool _mismoDia(DateTime a, DateTime b) => a.year == b.year && a.month == b.month && a.day == b.day;

  static int _diasSinEntrenar(String usuario) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    if (a.de(usuario).completadas.isEmpty) return 0;
    for (int i = 0; i < 60; i++) {
      if (a.entrenoEse(usuario, DateTime.now().subtract(Duration(days: i)))) return i;
    }
    return 60;
  }

  /// ¿Toca enseñar hoy la tarjeta «Tus palabras» (o invitar a escribirlas)?
  static bool tocaHoy(String usuario) {
    final MetaPersonal? m = AlmacenMeta.instancia.de(usuario);
    final DateTime ahora = DateTime.now();
    if (m == null || m.texto.trim().isEmpty) {
      final DateTime? cerrada = AlmacenMeta.instancia._invitacionCerrada[usuario] ?? m?.cerradoEl;
      return cerrada == null || ahora.difference(cerrada).inDays >= 7;
    }
    if (m.frecuencia == 'nunca') return false;
    if (m.cerradoEl != null && _mismoDia(m.cerradoEl!, ahora)) return false;
    if (m.ultimoRecuerdo != null && _mismoDia(m.ultimoRecuerdo!, ahora)) return true;
    if (_mismoDia(m.creada, ahora)) return false;
    final int cada = m.frecuencia == 'menudo' ? 2 : 4;
    final DateTime? ult = m.ultimoRecuerdo;
    if (ult == null) return ahora.difference(m.creada).inDays >= 1;
    if (_diasSinEntrenar(usuario) >= 3) return true;
    return ahora.difference(ult).inDays >= cada;
  }

  static void mostrada(String usuario) {
    final MetaPersonal? m = AlmacenMeta.instancia.de(usuario);
    if (m == null || m.texto.trim().isEmpty) return;
    final DateTime ahora = DateTime.now();
    if (m.ultimoRecuerdo == null || !_mismoDia(m.ultimoRecuerdo!, ahora)) {
      m.ultimoRecuerdo = ahora;
      AlmacenMeta.instancia.tocar(usuario);
    }
  }

  static void cerrar(String usuario) {
    final MetaPersonal? m = AlmacenMeta.instancia.de(usuario);
    if (m == null || m.texto.trim().isEmpty) {
      AlmacenMeta.instancia._invitacionCerrada[usuario] = DateTime.now();
      if (m != null) m.cerradoEl = DateTime.now();
      return;
    }
    m.cerradoEl = DateTime.now();
    AlmacenMeta.instancia.tocar(usuario);
  }

  /// Una palabra de Tenshi según su voz y su momento.
  static String animo(String usuario) {
    final AlmacenTemplo a = AlmacenTemplo.instancia;
    final String voz = a.de(usuario).ascenso['voz'] ?? 'serena';
    final int sin = _diasSinEntrenar(usuario);
    final int ses = a.de(usuario).completadas.length;
    if (sin >= 3) {
      return switch (voz) {
        'exigente' => 'Esto lo escribiste tú, no yo. Llevas $sin días parado. Hoy, aunque sean veinte minutos.',
        'alegre' => '¡Mira lo que escribiste! Esa persona sigue ahí. ¿Le regalamos un rato hoy?',
        _ => 'Lo escribiste tú, con calma y con ganas. No hace falta recuperar nada: basta con volver hoy.',
      };
    }
    if (ses == 0) {
      return switch (voz) {
        'exigente' => 'Las palabras ya están. Falta la primera sesión. Hoy.',
        'alegre' => '¡Qué buen comienzo! Ahora toca estrenar el templo.',
        _ => 'Ya sabes adónde vas. El primer paso puede ser pequeño.',
      };
    }
    final double kilos = a.pesoDelTemplo(usuario);
    final String hecho = '$ses ${ses == 1 ? 'sesión' : 'sesiones'}'
        '${kilos >= 100 ? ' y ${_num((kilos / 1000 * 10).roundToDouble() / 10)} t movidas' : ''}';
    return switch (voz) {
      'exigente' => 'Desde que lo escribiste: $hecho. No es suficiente hasta que lo sea. Sigue.',
      'alegre' => 'Desde que lo escribiste llevas $hecho. ¡Vas en serio!',
      _ => 'Desde que lo escribiste: $hecho. Vas por buen camino.',
    };
  }

  /// Se llama al abrir el Dojo: cada diez días, una carta con sus palabras.
  static void alAbrir(String usuario, String espiritu) {
    unawaited(AlmacenMeta.instancia.reintentarFoto(usuario));
    final MetaPersonal? m = AlmacenMeta.instancia.de(usuario);
    if (m == null || m.texto.trim().isEmpty || m.frecuencia == 'nunca') return;
    final DateTime ahora = DateTime.now();
    final DateTime? ult = m.ultimaCarta;
    final bool toca = ult == null ? ahora.difference(m.creada).inDays >= 7 : ahora.difference(ult).inDays >= 10;
    if (!toca || BandejaTemplo.instancia.yaHoy(usuario, TipoMensaje.meta)) return;
    final String t = m.texto.trim();
    final String recorte = t.length > 600 ? '${t.substring(0, 600).trimRight()}…' : t;
    BandejaTemplo.instancia.entregar(
      usuario,
      MensajeTemplo(
        id: 'msg_meta_${ahora.microsecondsSinceEpoch}',
        tipo: TipoMensaje.meta,
        categoria: CategoriaMensaje.templo,
        titulo: 'Recuerda por qué empezaste',
        cuerpo: 'Hace ${m.dias} días escribiste esto:\n\n«$recorte»\n\n${animo(usuario)}',
        fecha: ahora,
        firma: espiritu.isEmpty ? null : espiritu,
      ),
      forzar: true,
    );
    m.ultimaCarta = ahora;
    AlmacenMeta.instancia.tocar(usuario);
  }
}

