// ---------------------------------------------------------------------------
// 46.8 PANTALLA «MI META»
// ---------------------------------------------------------------------------

class MetaScreen extends StatefulWidget {
  const MetaScreen({super.key, required this.usuario});
  final String usuario;

  @override
  State<MetaScreen> createState() => _MetaScreenState();
}

class _MetaScreenState extends State<MetaScreen> {
  late final MetaPersonal _m = AlmacenMeta.instancia.de(widget.usuario) ?? MetaPersonal();
  late final TextEditingController _texto = TextEditingController(text: _m.texto);
  late String? _tipo = _m.tipo;
  late String? _plazo = _m.plazo;
  late String _frecuencia = _m.frecuencia;
  bool _subiendo = false;

  bool get _menor => SesionTemplo.instancia.actual?.esMenor ?? false;

  @override
  void dispose() {
    _texto.dispose();
    super.dispose();
  }

  void _guardar() {
    final bool nueva = AlmacenMeta.instancia.de(widget.usuario) == null;
    _m
      ..texto = _texto.text.trim()
      ..tipo = _tipo
      ..plazo = _plazo
      ..frecuencia = _frecuencia;
    if (nueva) _m.creada = DateTime.now();
    AlmacenMeta.instancia.guardar(widget.usuario, _m);
    HapticFeedback.mediumImpact();
    avisoClan(context, 'Guardado. El templo te lo recordará.');
    Navigator.of(context).maybePop();
  }

  Future<void> _foto(ImageSource fuente) async {
    final XFile? f = await ImagePicker().pickImage(source: fuente, maxWidth: 1400, maxHeight: 1400, imageQuality: 82);
    if (f == null || !mounted) return;
    setState(() => _subiendo = true);
    if (AlmacenMeta.instancia.de(widget.usuario) == null) AlmacenMeta.instancia.guardar(widget.usuario, _m);
    final bool ok = await AlmacenMeta.instancia.subirFoto(widget.usuario, f);
    if (!mounted) return;
    setState(() => _subiendo = false);
    avisoClan(context, ok ? 'Tu foto de partida está guardada. Solo tú puedes verla.' : 'Sin conexión: la subiremos en cuanto vuelva.');
  }

  @override
  Widget build(BuildContext context) {
    final String obj = AlmacenTemplo.instancia.de(widget.usuario).ascenso['objetivo'] ?? 'salud';
    final FotoProgreso? foto = AlmacenMeta.instancia.foto(widget.usuario);
    Widget chip(String id, String t, bool sel, VoidCallback f) => ChoiceChip(
          label: Text(t),
          selected: sel,
          showCheckmark: false,
          onSelected: (_) => setState(f),
          labelStyle: TextStyle(fontSize: 12.5, color: sel ? TempleColors.blancoLuna : TempleColors.textoSuave),
          backgroundColor: TempleColors.superficie,
          selectedColor: TempleColors.violeta.withValues(alpha: 0.30),
          side: BorderSide(color: sel ? TempleColors.violeta : TempleColors.borde),
        );

    return Scaffold(
      backgroundColor: TempleColors.negro,
      body: FondoTemplo(
        child: SafeArea(
          child: ListView(
            padding: const EdgeInsets.fromLTRB(TempleSpace.borde, 4, TempleSpace.borde, 40),
            children: <Widget>[
              Row(
                children: <Widget>[
                  IconButton(
                    onPressed: () => Navigator.of(context).maybePop(),
                    icon: const Icon(Icons.arrow_back_rounded, color: TempleColors.textoSuave),
                  ),
                  const Expanded(
                    child: Text('Mi meta',
                        style: TextStyle(fontSize: 19, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                  ),
                  TextButton(onPressed: _guardar, child: const Text('Guardar')),
                ],
              ),
              const SizedBox(height: 10),
              const EtiquetaSeccion('Qué quieres lograr'),
              Wrap(
                spacing: 8,
                runSpacing: 8,
                children: <Widget>[
                  for (final (String, String) o in metasConcretas[obj] ?? metasConcretas['salud']!)
                    chip(o.$1, o.$2, _tipo == o.$1, () => _tipo = _tipo == o.$1 ? null : o.$1),
                ],
              ),
              const SizedBox(height: 14),
              Wrap(
                spacing: 8,
                runSpacing: 8,
                children: <Widget>[
                  for (final (String, String) p in plazosMeta)
                    chip(p.$1, p.$2, _plazo == p.$1, () => _plazo = _plazo == p.$1 ? null : p.$1),
                ],
              ),
              const SizedBox(height: TempleSpace.l),
              const EtiquetaSeccion('Con tus palabras'),
              TextField(
                controller: _texto,
                minLines: 5,
                maxLines: 12,
                maxLength: 800,
                textCapitalization: TextCapitalization.sentences,
                style: const TextStyle(fontSize: 14.5, height: 1.5, color: TempleColors.blancoLuna),
                decoration: InputDecoration(
                  hintText: 'Qué quieres cumplir, cómo te quieres ver y sentir, y por qué ahora.',
                  hintStyle: const TextStyle(color: TempleColors.textoTenue),
                  filled: true,
                  fillColor: TempleColors.superficie,
                  counterStyle: const TextStyle(color: TempleColors.textoTenue),
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(TempleRadius.campo),
                    borderSide: const BorderSide(color: TempleColors.borde),
                  ),
                  enabledBorder: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(TempleRadius.campo),
                    borderSide: const BorderSide(color: TempleColors.borde),
                  ),
                  focusedBorder: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(TempleRadius.campo),
                    borderSide: const BorderSide(color: TempleColors.violeta),
                  ),
                ),
              ),
              if (AlmacenMeta.instancia.de(widget.usuario) != null)
                Text('Lo escribiste hace ${_m.dias} ${_m.dias == 1 ? 'día' : 'días'}.',
                    style: const TextStyle(fontSize: 11.5, color: TempleColors.textoTenue)),
              const SizedBox(height: TempleSpace.l),
              if (!_menor) ...<Widget>[
                const EtiquetaSeccion('Tu foto de partida'),
                TempleCard(
                  child: Row(
                    children: <Widget>[
                      ClipRRect(
                        borderRadius: BorderRadius.circular(12),
                        child: SizedBox(
                          width: 72,
                          height: 96,
                          child: foto != null
                              ? ImagenPrivada(ruta: foto.ruta)
                              : const ColoredBox(
                                  color: TempleColors.superficieAlta,
                                  child: Icon(Icons.accessibility_new_rounded, color: TempleColors.textoTenue),
                                ),
                        ),
                      ),
                      const SizedBox(width: 14),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: <Widget>[
                            Text(
                              foto != null
                                  ? 'Guardada el ${foto.fecha.day}/${foto.fecha.month}/${foto.fecha.year}. Privada.'
                                  : _m.fotoPendiente != null
                                      ? 'Pendiente de subir: se guardará cuando haya conexión.'
                                      : 'Opcional y privada. Te servirá para comparar.',
                              style: const TextStyle(fontSize: 12.5, height: 1.4, color: TempleColors.textoSuave),
                            ),
                            const SizedBox(height: 8),
                            if (_subiendo)
                              const SizedBox(
                                  width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2))
                            else
                              Wrap(
                                spacing: 4,
                                children: <Widget>[
                                  TextButton.icon(
                                    onPressed: () => _foto(ImageSource.camera),
                                    icon: const Icon(Icons.photo_camera_outlined, size: 16),
                                    label: const Text('Cámara'),
                                  ),
                                  TextButton.icon(
                                    onPressed: () => _foto(ImageSource.gallery),
                                    icon: const Icon(Icons.photo_library_outlined, size: 16),
                                    label: const Text('Galería'),
                                  ),
                                ],
                              ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: TempleSpace.l),
              ],
              const EtiquetaSeccion('Que el templo te lo recuerde'),
              Wrap(
                spacing: 8,
                runSpacing: 8,
                children: <Widget>[
                  chip('menudo', 'A menudo', _frecuencia == 'menudo', () => _frecuencia = 'menudo'),
                  chip('aveces', 'De vez en cuando', _frecuencia == 'aveces', () => _frecuencia = 'aveces'),
                  chip('nunca', 'No me lo recuerdes', _frecuencia == 'nunca', () => _frecuencia = 'nunca'),
                ],
              ),
              const SizedBox(height: 8),
              const Text(
                'Aparece en el Dojo, te llega como carta de vez en cuando y Tenshi lo tiene presente '
                'cuando hablas con él.',
                style: TextStyle(fontSize: 11.5, height: 1.4, color: TempleColors.textoTenue),
              ),
              const SizedBox(height: 26),
              DojoPrimaryButton(texto: 'Guardar mi meta', onPressed: _guardar),
            ],
          ),
        ),
      ),
    );
  }
}


