// ---------------------------------------------------------------------------
// 47.1 ENLACES A REDES SOCIALES
// ---------------------------------------------------------------------------

/// Los cinco huecos, en el orden en que se muestran (y se recortan).
const List<String> huecosRedes = <String>['instagram', 'facebook', 'tiktok', 'extra1', 'extra2'];

class RedesSociales {
  const RedesSociales._();

  /// Dominios aceptados para los tres huecos fijos.
  static const Map<String, List<String>> dominiosFijos = <String, List<String>>{
    'instagram': <String>['instagram.com', 'www.instagram.com'],
    'facebook': <String>['facebook.com', 'www.facebook.com', 'm.facebook.com', 'fb.com', 'www.fb.com'],
    'tiktok': <String>['tiktok.com', 'www.tiktok.com', 'vm.tiktok.com'],
  };

  /// Redes aceptadas en los dos huecos libres. Solo redes conocidas: así
  /// nadie usa el perfil para mandar a páginas de estafa.
  static const Map<String, String> otrasRedes = <String, String>{
    'youtube.com': 'YouTube',
    'www.youtube.com': 'YouTube',
    'm.youtube.com': 'YouTube',
    'youtu.be': 'YouTube',
    'x.com': 'X',
    'www.x.com': 'X',
    'twitter.com': 'X',
    'www.twitter.com': 'X',
    'twitch.tv': 'Twitch',
    'www.twitch.tv': 'Twitch',
    'kick.com': 'Kick',
    'www.kick.com': 'Kick',
    'threads.net': 'Threads',
    'www.threads.net': 'Threads',
    'threads.com': 'Threads',
    'www.threads.com': 'Threads',
    'linkedin.com': 'LinkedIn',
    'www.linkedin.com': 'LinkedIn',
    'strava.com': 'Strava',
    'www.strava.com': 'Strava',
    'snapchat.com': 'Snapchat',
    'www.snapchat.com': 'Snapchat',
    'pinterest.com': 'Pinterest',
    'www.pinterest.com': 'Pinterest',
    'open.spotify.com': 'Spotify',
    // También se puede repetir una de las fijas (una segunda cuenta).
    'instagram.com': 'Instagram',
    'www.instagram.com': 'Instagram',
    'facebook.com': 'Facebook',
    'www.facebook.com': 'Facebook',
    'tiktok.com': 'TikTok',
    'www.tiktok.com': 'TikTok',
  };

  static String titulo(String hueco) => switch (hueco) {
        'instagram' => 'Instagram',
        'facebook' => 'Facebook',
        'tiktok' => 'TikTok',
        'extra1' => 'Otra red',
        _ => 'Otra red más',
      };

  static String pista(String hueco) => switch (hueco) {
        'instagram' => 'tu_usuario o el enlace',
        'facebook' => 'tu_usuario o el enlace',
        'tiktok' => '@tu_usuario o el enlace',
        _ => 'Enlace de YouTube, X, Twitch, Strava…',
      };

  static IconData iconoDe(String url) {
    final String n = redDe(url);
    return switch (n) {
      'Instagram' => Icons.photo_camera_outlined,
      'Facebook' => Icons.people_alt_outlined,
      'TikTok' => Icons.music_note_rounded,
      'YouTube' => Icons.smart_display_outlined,
      'X' => Icons.alternate_email_rounded,
      'Twitch' || 'Kick' => Icons.videogame_asset_outlined,
      'Threads' => Icons.forum_outlined,
      'LinkedIn' => Icons.work_outline_rounded,
      'Strava' => Icons.directions_run_rounded,
      'Spotify' => Icons.headphones_rounded,
      _ => Icons.link_rounded,
    };
  }

  static String? _host(String url) {
    final Uri? u = Uri.tryParse(url);
    if (u == null || u.scheme != 'https' || u.host.isEmpty) return null;
    return u.host.toLowerCase();
  }

  /// Nombre de la red de un enlace ya guardado.
  static String redDe(String url) {
    final String? h = _host(url);
    if (h == null) return 'Enlace';
    for (final MapEntry<String, List<String>> e in dominiosFijos.entries) {
      if (e.value.contains(h)) return titulo(e.key);
    }
    return otrasRedes[h] ?? 'Enlace';
  }

  /// Lo que se muestra en el perfil: @usuario cuando se puede leer.
  static String etiqueta(String url) {
    final Uri? u = Uri.tryParse(url);
    final List<String> partes = u?.pathSegments.where((String s) => s.isNotEmpty).toList() ?? <String>[];
    final String red = redDe(url);
    if (partes.isEmpty || partes.first == 'profile.php') return red;
    final String primero = partes.first == 'c' || partes.first == 'channel' || partes.first == 'in' || partes.first == 'user'
        ? (partes.length > 1 ? partes[1] : partes.first)
        : partes.first;
    final String h = primero.startsWith('@') ? primero : '@$primero';
    return h.length > 26 ? '${h.substring(0, 25)}…' : h;
  }

  /// Convierte lo que escribe la persona en un enlace seguro, o null si no
  /// vale. Cadena vacía = quitar el enlace.
  static String? normalizar(String hueco, String entrada) {
    String t = entrada.trim();
    if (t.isEmpty) return '';
    if (t.length > 200 || t.contains(' ')) return null;
    final bool fijo = dominiosFijos.containsKey(hueco);
    // Solo el usuario: «@ana.fit» o «ana.fit».
    if (fijo && !t.contains('/') && !t.toLowerCase().contains('.com')) {
      final String h = t.startsWith('@') ? t.substring(1) : t;
      if (!RegExp(r'^[A-Za-z0-9._]{1,30}$').hasMatch(h)) return null;
      return switch (hueco) {
        'instagram' => 'https://www.instagram.com/$h',
        'facebook' => 'https://www.facebook.com/$h',
        _ => 'https://www.tiktok.com/@$h',
      };
    }
    if (t.toLowerCase().startsWith('http://')) t = 'https://${t.substring(7)}';
    if (!t.toLowerCase().startsWith('https://')) t = 'https://$t';
    final String? h = _host(t);
    if (h == null) return null;
    final bool vale = fijo ? dominiosFijos[hueco]!.contains(h) : otrasRedes.containsKey(h);
    if (!vale) return null;
    final Uri u = Uri.parse(t);
    if (u.userInfo.isNotEmpty || u.hasPort) return null;
    return Uri(scheme: 'https', host: h, path: u.path, query: u.query.isEmpty ? null : u.query).toString();
  }

  /// Cuántos enlaces se pueden mostrar con el plan actual.
  static int get limite => LimitesPase.pase ? 5 : 2;

  /// Los enlaces en orden, recortados al límite (como hace el servidor).
  static Map<String, String> visibles(Map<String, String> redes, {int? limite}) {
    final int max = limite ?? RedesSociales.limite;
    final Map<String, String> r = <String, String>{};
    for (final String k in huecosRedes) {
      final String? v = redes[k];
      if (v == null || v.isEmpty) continue;
      if (r.length >= max) break;
      r[k] = v;
    }
    return r;
  }

  static Map<String, String> desde(Object? m) {
    final Map<String, String> r = <String, String>{};
    if (m is Map) {
      for (final String k in huecosRedes) {
        final Object? v = m[k];
        if (v is String && v.startsWith('https://')) r[k] = v;
      }
    }
    return r;
  }
}

/// Abre un enlace de otra persona con aviso: sale de la app.
Future<void> abrirRedSocial(BuildContext context, String url, {String? de}) async {
  final String host = Uri.tryParse(url)?.host ?? url;
  final String? accion = await showModalBottomSheet<String>(
    context: context,
    backgroundColor: TempleColors.grafito,
    shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
    builder: (BuildContext ctx) => SafeArea(
      top: false,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(20, 18, 20, 12),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: <Widget>[
            Row(
              children: <Widget>[
                Icon(RedesSociales.iconoDe(url), color: TempleColors.violetaClaro),
                const SizedBox(width: 10),
                const Expanded(
                  child: Text('Vas a salir del templo',
                      style: TextStyle(fontSize: 17, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                ),
              ],
            ),
            const SizedBox(height: 8),
            Text(
              'Este enlace abre $host fuera de Temple of Strength'
              '${de == null ? '' : '. Lo puso $de'}: el templo no controla lo que hay allí.',
              style: const TextStyle(fontSize: 13, height: 1.45, color: TempleColors.textoSuave),
            ),
            const SizedBox(height: 6),
            Text(url, style: const TextStyle(fontSize: 11.5, color: TempleColors.textoTenue)),
            const SizedBox(height: 16),
            DojoPrimaryButton(texto: 'Abrir ${RedesSociales.redDe(url)}', onPressed: () => Navigator.of(ctx).pop('abrir')),
            TextButton(
              onPressed: () => Navigator.of(ctx).pop('copiar'),
              child: const Text('Copiar el enlace', style: TextStyle(color: TempleColors.textoSuave)),
            ),
          ],
        ),
      ),
    ),
  );
  if (accion == 'copiar') {
    await Clipboard.setData(ClipboardData(text: url));
    if (context.mounted) avisoClan(context, 'Enlace copiado.');
    return;
  }
  if (accion != 'abrir') return;
  bool ok = false;
  try {
    ok = await launchUrl(Uri.parse(url), mode: LaunchMode.externalApplication);
  } catch (_) {
    ok = false;
  }
  if (!ok) {
    await Clipboard.setData(ClipboardData(text: url));
    if (context.mounted) avisoClan(context, 'No se pudo abrir. Copiamos el enlace para que lo pegues en tu navegador.');
  }
}

