class _HojaRedes extends StatefulWidget {
  const _HojaRedes({required this.usuario});
  final String usuario;

  @override
  State<_HojaRedes> createState() => _HojaRedesState();
}

class _HojaRedesState extends State<_HojaRedes> {
  late final IdentidadUsuario _id = AlmacenIdentidad.instancia.de(widget.usuario);
  late final Map<String, TextEditingController> _c = <String, TextEditingController>{
    for (final String k in huecosRedes) k: TextEditingController(text: _id.redes[k] ?? ''),
  };
  final Map<String, String> _error = <String, String>{};
  bool _guardando = false;

  bool get _menor => SesionTemplo.instancia.actual?.esMenor ?? false;

  @override
  void dispose() {
    for (final TextEditingController c in _c.values) {
      c.dispose();
    }
    super.dispose();
  }

  int get _llenos => huecosRedes.where((String k) => _c[k]!.text.trim().isNotEmpty).length;

  /// Un hueco vacío se bloquea cuando ya se usaron los del plan gratis.
  bool _bloqueado(String k) => !LimitesPase.pase && _c[k]!.text.trim().isEmpty && _llenos >= RedesSociales.limite;

  Future<void> _muro() => mostrarMuroPase(
        context,
        titulo: 'Tus 5 redes, con el Pase',
        texto: 'Gratis muestras 2 enlaces en tu perfil. Con el Pase del Templo, los 5: Instagram, Facebook, '
            'TikTok y dos redes más.',
        ventajas: const <String>[
          'Los 5 enlaces visibles en tu perfil',
          'Nombre con estilo y marcos exclusivos',
          'Tenshi con la mente completa sin límite diario',
        ],
        icono: Icons.link_rounded,
      );

  Future<void> _guardar() async {
    _error.clear();
    final Map<String, String> nuevas = <String, String>{};
    for (final String k in huecosRedes) {
      final String? n = RedesSociales.normalizar(k, _c[k]!.text);
      if (n == null) {
        _error[k] = dominiosFijosTexto(k);
      } else if (n.isNotEmpty) {
        nuevas[k] = n;
      }
    }
    if (_error.isNotEmpty) {
      setState(() {});
      return;
    }
    if (nuevas.length > RedesSociales.limite) {
      await _muro();
      return;
    }
    setState(() => _guardando = true);
    _id.redes
      ..clear()
      ..addAll(nuevas);
    NubeTemplo.instancia.marcarCambio();
    final bool ok = await SesionTemplo.instancia.sincronizarIdentidad(widget.usuario);
    if (!mounted) return;
    setState(() => _guardando = false);
    avisoClan(context, ok ? 'Tus redes ya están en tu perfil.' : 'Guardado. Se publicará cuando vuelva la conexión.');
    Navigator.of(context).pop();
  }

  static String dominiosFijosTexto(String k) => switch (k) {
        'instagram' => 'Pon tu usuario o un enlace de instagram.com.',
        'facebook' => 'Pon tu usuario o un enlace de facebook.com.',
        'tiktok' => 'Pon tu usuario o un enlace de tiktok.com.',
        _ => 'Solo enlaces de redes conocidas: YouTube, X, Twitch, Kick, Threads, LinkedIn, Strava, '
            'Snapchat, Pinterest, Spotify o una segunda cuenta de Instagram, Facebook o TikTok.',
      };

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(context).bottom),
      child: SizedBox(
        height: MediaQuery.sizeOf(context).height * 0.86,
        child: ListView(
          padding: const EdgeInsets.fromLTRB(22, 14, 22, 26),
          children: <Widget>[
            Center(
              child: Container(
                width: 40,
                height: 4,
                decoration: BoxDecoration(color: TempleColors.borde, borderRadius: BorderRadius.circular(9)),
              ),
            ),
            const SizedBox(height: 16),
            Row(
              children: <Widget>[
                const Expanded(
                  child: Text('Tus redes',
                      style: TextStyle(fontSize: 21, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                ),
                if (!_menor)
                  Text(
                    LimitesPase.pase ? '$_llenos / 5' : '$_llenos / ${RedesSociales.limite} gratis',
                    style: const TextStyle(fontSize: 12, color: TempleColors.textoSuave),
                  ),
              ],
            ),
            const SizedBox(height: 6),
            if (_menor)
              const Padding(
                padding: EdgeInsets.only(top: 10),
                child: Text(
                  'Por tu seguridad, los perfiles de menores de edad no muestran enlaces a otras redes. '
                  'Cuando cumplas 18 podrás añadirlos aquí.',
                  style: TextStyle(fontSize: 13.5, height: 1.5, color: TempleColors.textoSuave),
                ),
              )
            else ...<Widget>[
              const Text(
                'Quien visite tu perfil verá estos enlaces y podrá ir a tus redes. Pon solo cuentas tuyas.',
                style: TextStyle(fontSize: 12.5, height: 1.45, color: TempleColors.textoSuave),
              ),
              const SizedBox(height: 18),
              for (final String k in huecosRedes) ...<Widget>[
                _campo(k),
                const SizedBox(height: 12),
              ],
              if (!LimitesPase.pase) ...<Widget>[
                Row(
                  children: <Widget>[
                    const Expanded(
                      child: Text('Gratis: 2 enlaces visibles. Con el Pase: los 5.',
                          style: TextStyle(fontSize: 12, color: TempleColors.textoTenue)),
                    ),
                    GestureDetector(onTap: _muro, child: const ChipPase()),
                  ],
                ),
                const SizedBox(height: 14),
              ],
              DojoPrimaryButton(texto: 'Guardar mis redes', cargando: _guardando, onPressed: _guardar),
            ],
          ],
        ),
      ),
    );
  }

  Widget _campo(String k) {
    final bool bloqueado = _bloqueado(k);
    final String? err = _error[k];
    return GestureDetector(
      onTap: bloqueado ? _muro : null,
      child: AbsorbPointer(
        absorbing: bloqueado,
        child: Opacity(
          opacity: bloqueado ? 0.5 : 1,
          child: TextField(
            controller: _c[k],
            keyboardType: TextInputType.url,
            autocorrect: false,
            maxLength: 200,
            onChanged: (_) => setState(() => _error.remove(k)),
            style: const TextStyle(fontSize: 14, color: TempleColors.blancoLuna),
            decoration: InputDecoration(
              counterText: '',
              labelText: RedesSociales.titulo(k),
              labelStyle: const TextStyle(color: TempleColors.textoSuave),
              hintText: RedesSociales.pista(k),
              hintStyle: const TextStyle(color: TempleColors.textoTenue, fontSize: 13),
              errorText: err,
              errorMaxLines: 3,
              prefixIcon: Icon(
                  k == 'instagram'
                      ? Icons.photo_camera_outlined
                      : k == 'facebook'
                          ? Icons.people_alt_outlined
                          : k == 'tiktok'
                              ? Icons.music_note_rounded
                              : Icons.link_rounded,
                  size: 19,
                  color: TempleColors.violetaClaro),
              suffixIcon: bloqueado
                  ? const Icon(Icons.lock_outline_rounded, size: 18, color: Color(0xFFE8B65A))
                  : (_c[k]!.text.isEmpty
                      ? null
                      : IconButton(
                          tooltip: 'Quitar',
                          icon: const Icon(Icons.close_rounded, size: 18, color: TempleColors.textoTenue),
                          onPressed: () => setState(() => _c[k]!.clear()),
                        )),
              filled: true,
              fillColor: TempleColors.superficie,
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(TempleRadius.campo),
                borderSide: BorderSide.none,
              ),
            ),
          ),
        ),
      ),
    );
  }
}

