// 47.3 ACEPTAR DE NUEVO LOS TÉRMINOS
// ---------------------------------------------------------------------------

/// Si la cuenta aceptó una versión anterior, se le piden los nuevos antes de
/// seguir. Devuelve false si la persona prefirió salir.
Future<bool> pedirTerminosSiCambiaron(BuildContext context) async {
  final String? v = SesionTemplo.instancia.actual?.terminosVersion;
  if (v == null || v == ConfigSupabase.versionTerminos || SesionTemplo.instancia.terminosAceptadosAhora) {
    return true;
  }
  final bool? ok = await Navigator.of(context).push<bool>(MaterialPageRoute<bool>(
    fullscreenDialog: true,
    builder: (_) => TerminosScreen(
      paraAceptar: true,
      obligatorio: true,
      menor: SesionTemplo.instancia.actual?.esMenor ?? false,
    ),
  ));
  if (ok == true) {
    SesionTemplo.instancia.terminosAceptadosAhora = true;
    final bool guardado = await SesionTemplo.instancia.aceptarTerminos();
    if (!guardado && context.mounted) {
      avisoClan(context, 'Sin conexión: te los volveremos a mostrar para registrar tu aceptación.');
    }
    return true;
  }
  if (!context.mounted) return false;
  try {
    await SesionTemplo.instancia.cerrarSesion();
  } catch (_) {}
  if (context.mounted) _alInicio(context);
  return false;
}

