// 47.4 PÉTALOS DE CEREZO PARA TENSHI
// ---------------------------------------------------------------------------

/// Pétalos de sakura que caen despacio, giran y dan la vuelta. Van detrás de
/// la conversación y no se pueden tocar.
class PetalosSakura extends StatefulWidget {
  const PetalosSakura({super.key, this.cantidad = 22});
  final int cantidad;

  @override
  State<PetalosSakura> createState() => _PetalosSakuraState();
}

class _PetalosSakuraState extends State<PetalosSakura>
    with TickerDecorativo {
  @override
  int get cuadrosWeb => Rendimiento.cuadrosLentos;
  late final AnimationController _c = AnimationController(vsync: this, duration: const Duration(seconds: 60))
    ..addListener(_avanzar);

  /// Tiempo continuo en segundos: nunca vuelve a cero, así no saltan.
  final ValueNotifier<double> _t = ValueNotifier<double>(3);
  int _vueltas = 0;
  double _ultimo = 0;

  void _avanzar() {
    if (_c.value < _ultimo) _vueltas++;
    _ultimo = _c.value;
    _t.value = 3 + (_vueltas + _c.value) * 60;
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (MediaQuery.maybeDisableAnimationsOf(context) ?? false) {
      _c.stop();
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    _t.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Rendimiento.ligero
      // En la web no hay pétalos: la experiencia completa vive en la app (59).
      ? const SizedBox.shrink()
      : IgnorePointer(
        child: RepaintBoundary(
          child: CustomPaint(
            painter: _SakuraPainter(_t, widget.cantidad),
            size: Size.infinite,
          ),
        ),
      );
}

class _SakuraPainter extends CustomPainter {
  _SakuraPainter(this.reloj, this.n) : super(repaint: reloj);
  final ValueNotifier<double> reloj;
  final int n;

  static double _h(double a, double b) {
    final double x = math.sin(a * 127.1 + b * 311.7) * 43758.5453;
    return x - x.floorToDouble();
  }

  static Path _petalo(double s) => Path()
    ..moveTo(0, s * 0.72)
    ..cubicTo(-s * 0.44, s * 0.36, -s * 0.46, -s * 0.36, -s * 0.17, -s * 0.62)
    ..quadraticBezierTo(-s * 0.06, -s * 0.68, 0, -s * 0.5)
    ..quadraticBezierTo(s * 0.06, -s * 0.68, s * 0.17, -s * 0.62)
    ..cubicTo(s * 0.46, -s * 0.36, s * 0.44, s * 0.36, 0, s * 0.72)
    ..close();

  @override
  void paint(Canvas canvas, Size size) {
    final double w = size.width, h = size.height;
    if (w <= 0 || h <= 0) return;
    final double t = reloj.value;
    for (int k = 0; k < n; k++) {
      final double i = k.toDouble();
      final double prof = _h(i, 3); // 0 lejos, 1 cerca
      final double s = 8 + 13 * prof;
      final double vel = 0.035 + 0.05 * _h(i, 7);
      final double f = (t * vel + _h(7, i)) % 1.0;
      final double y = -30 + f * (h + 60);
      final double vaiven = math.sin(t * (0.5 + _h(i, 13) * 0.6) + i) * (16 + 22 * _h(13, i));
      final double x = ((_h(i, 11) * w + vaiven + f * 40 * (_h(i, 17) - 0.3)) % (w + 40) + w + 40) % (w + 40) - 20;
      final double giro = t * (0.4 + _h(i, 19) * 0.9) * (_h(19, i) > 0.5 ? 1 : -1) + i;
      final double vuelta = math.cos(t * (0.8 + _h(i, 23) * 1.2) + i * 2);
      final double alfa = ((0.34 + 0.44 * prof) * math.min(1.0, math.min(f * 8, (1 - f) * 6))).clamp(0.0, 1.0);
      if (alfa <= 0.01) continue;
      canvas.save();
      canvas.translate(x, y);
      canvas.rotate(giro);
      canvas.scale(1, 0.35 + 0.65 * vuelta.abs());
      if (prof > 0.55) {
        canvas.drawCircle(
          Offset.zero,
          s * 0.8,
          Paint()
            ..color = const Color(0xFFFF8FC0).withValues(alpha: alfa * 0.35)
            ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6),
        );
      }
      final bool dorso = vuelta < 0;
      final Path p = _petalo(s);
      final Paint relleno = Paint()
        ..shader = ui.Gradient.linear(
          Offset(0, s * 0.6),
          Offset(0, -s * 0.6),
          <Color>[
            (dorso ? const Color(0xFFE58AB0) : const Color(0xFFFFE4EF)).withValues(alpha: alfa),
            (dorso ? const Color(0xFFF3A6C6) : const Color(0xFFFFC2DA)).withValues(alpha: alfa),
            (dorso ? const Color(0xFFD9799F) : const Color(0xFFF79BC0)).withValues(alpha: alfa),
          ],
          const <double>[0, 0.55, 1],
        );
      if (prof < 0.3) relleno.maskFilter = const MaskFilter.blur(BlurStyle.normal, 1.2);
      canvas.drawPath(p, relleno);
      canvas.drawPath(
        p,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 0.6
          ..color = const Color(0xFFFFF3F8).withValues(alpha: alfa * 0.6),
      );
      canvas.drawLine(
        Offset(0, s * 0.5),
        Offset(0, -s * 0.3),
        Paint()
          ..strokeWidth = 0.5
          ..color = const Color(0xFFE07AA6).withValues(alpha: alfa * 0.35),
      );
      canvas.restore();
    }
  }

  @override
  bool shouldRepaint(_SakuraPainter old) => old.n != n;
}

// ===========================================================================
// 48. ANUNCIOS CON RECOMPENSA
//
// Ningún anuncio salta solo: la persona elige verlo y recibe algo a cambio.
// Nunca durante el entrenamiento, en la conversación con Tenshi ni en las
// líneas de ayuda. Nunca a menores de edad. Nunca dan honor ni experiencia:
// el Ranked queda limpio.
//
//   48.1  Configuración (códigos de AdMob)
//   48.2  Motor: permiso de privacidad, carga y reproducción
//   48.3  Cupos y recompensas de cada persona
//   48.4  Ver un anuncio desde cualquier pantalla
//   48.5  Taller: ofrenda del espectador (10 mon, 10 al día)
//   48.6  Dojo: ofrenda doble tras la sesión
//   48.7  Casa: omikuji del templo
//   48.8  Taller: lucir una pieza 24 horas
//   48.9  Tenshi: +3 mensajes por anuncio (5 al día, lo cuenta el servidor)
//   48.10 Ofrecer anuncio o Pase (informe semanal, foto extra)
// ===========================================================================

// ---------------------------------------------------------------------------
// 48.1 CONFIGURACIÓN
//
// Estos son los códigos de PRUEBA oficiales de Google: muestran anuncios de
// ejemplo y no pagan. Cuando AdMob apruebe la app, cámbialos por los tuyos
// (AdMob → Apps → Bloques de anuncios). No toques tus anuncios reales.
// ---------------------------------------------------------------------------

class ConfigAnuncios {
  const ConfigAnuncios._();

  static const String recompensaAndroid = 'ca-app-pub-3940256099942544/5224354917';
  static const String recompensaIos = 'ca-app-pub-3940256099942544/1712485313';

  static String get recompensa =>
      defaultTargetPlatform == TargetPlatform.iOS ? recompensaIos : recompensaAndroid;
}

// ---------------------------------------------------------------------------
// 48.2 MOTOR
// ---------------------------------------------------------------------------

enum ResultadoAnuncio { visto, cerrado, sinAnuncio }

class MotorAnuncios {
  MotorAnuncios._();
  static final MotorAnuncios instancia = MotorAnuncios._();

  bool _iniciado = false;
  Future<void>? _iniciando;
  Future<RewardedAd?>? _proximo;

  bool get soportado =>
      !kIsWeb && (defaultTargetPlatform == TargetPlatform.android || defaultTargetPlatform == TargetPlatform.iOS);

  /// En Chrome o Windows no hay anuncios de Google. Mientras desarrollas
  /// (modo debug) se simula uno, para poder probar las pantallas. En la app
  /// publicada esto nunca ocurre.
  bool get simulado => !soportado && kDebugMode;

  /// Todas las cuentas con sesión. A las de menores (o si aún no se sabe la
  /// edad) se les piden anuncios no personalizados y aptos para adolescentes.
  bool get permitido => (soportado || simulado) && SesionTemplo.instancia.actual != null;

  /// Si se muestran las recompensas por anuncio. En la web se ven igual y, al
  /// tocarlas, se recomienda descargar la app (58.2).
  bool get ofrecible => permitido || (kIsWeb && SesionTemplo.instancia.actual != null);

  bool get _menor => SesionTemplo.instancia.actual?.esMenor ?? true;

  /// Con qué edad se configuró Google por última vez (cambia si se entra con
  /// otra cuenta).
  bool? _configuradoComoMenor;

  Future<void> _configurar() async {
    final bool menor = _menor;
    await MobileAds.instance.updateRequestConfiguration(RequestConfiguration(
      maxAdContentRating: MaxAdContentRating.t,
      tagForChildDirectedTreatment: TagForChildDirectedTreatment.no,
      tagForUnderAgeOfConsent: menor ? TagForUnderAgeOfConsent.yes : TagForUnderAgeOfConsent.no,
    ));
    _configuradoComoMenor = menor;
  }

  Future<void> iniciar() {
    if (!permitido || simulado) return Future<void>.value();
    return _iniciando ??= _iniciar();
  }

  Future<void> _iniciar() async {
    try {
      // Permiso de privacidad de Google: solo aparece donde la ley lo pide.
      final Completer<void> permiso = Completer<void>();
      ConsentInformation.instance.requestConsentInfoUpdate(
        ConsentRequestParameters(tagForUnderAgeOfConsent: _menor),
        () {
          ConsentForm.loadAndShowConsentFormIfRequired((FormError? e) {
            if (!permiso.isCompleted) permiso.complete();
          });
        },
        (FormError e) {
          if (!permiso.isCompleted) permiso.complete();
        },
      );
      await permiso.future.timeout(const Duration(seconds: 15), onTimeout: () {});
      await MobileAds.instance.initialize();
      await _configurar();
      _iniciado = true;
      _precargar();
    } catch (e) {
      debugPrint('Anuncios: no se pudieron iniciar: $e');
      _iniciando = null;
    }
  }

  Future<RewardedAd?> _cargar() {
    final Completer<RewardedAd?> c = Completer<RewardedAd?>();
    try {
      RewardedAd.load(
        adUnitId: ConfigAnuncios.recompensa,
        request: AdRequest(nonPersonalizedAds: _menor),
        rewardedAdLoadCallback: RewardedAdLoadCallback(
          onAdLoaded: (RewardedAd ad) {
            if (c.isCompleted) {
              ad.dispose();
            } else {
              c.complete(ad);
            }
          },
          onAdFailedToLoad: (LoadAdError e) {
            debugPrint('Anuncios: no cargó: ${e.message}');
            if (!c.isCompleted) c.complete(null);
          },
        ),
      );
    } catch (e) {
      debugPrint('Anuncios: $e');
      if (!c.isCompleted) c.complete(null);
    }
    return c.future.timeout(const Duration(seconds: 15), onTimeout: () => null);
  }

  void _precargar() {
    if (_iniciado) _proximo ??= _cargar();
  }

  /// Muestra un anuncio con recompensa. [alListo] se llama justo antes de que
  /// aparezca (para cerrar el «buscando…»).
  Future<ResultadoAnuncio> mostrar({VoidCallback? alListo}) async {
    if (!permitido) return ResultadoAnuncio.sinAnuncio;
    await iniciar();
    if (!_iniciado) return ResultadoAnuncio.sinAnuncio;
    if (_configuradoComoMenor != _menor) {
      // Se entró con otra cuenta: el anuncio precargado era para la otra edad.
      try {
        await _configurar();
      } catch (_) {}
      final Future<RewardedAd?>? viejo = _proximo;
      _proximo = null;
      if (viejo != null) unawaited(viejo.then((RewardedAd? a) => a?.dispose()));
    }
    final RewardedAd? ad = await (_proximo ?? _cargar());
    _proximo = null;
    if (ad == null) {
      _precargar();
      return ResultadoAnuncio.sinAnuncio;
    }
    final Completer<ResultadoAnuncio> fin = Completer<ResultadoAnuncio>();
    bool premio = false;
    ad.fullScreenContentCallback = FullScreenContentCallback<RewardedAd>(
      onAdDismissedFullScreenContent: (RewardedAd a) {
        a.dispose();
        if (!fin.isCompleted) fin.complete(premio ? ResultadoAnuncio.visto : ResultadoAnuncio.cerrado);
      },
      onAdFailedToShowFullScreenContent: (RewardedAd a, AdError e) {
        a.dispose();
        if (!fin.isCompleted) fin.complete(ResultadoAnuncio.sinAnuncio);
      },
    );
    alListo?.call();
    try {
      await ad.show(onUserEarnedReward: (AdWithoutView a, RewardItem r) => premio = true);
    } catch (_) {
      if (!fin.isCompleted) fin.complete(ResultadoAnuncio.sinAnuncio);
    }
    final ResultadoAnuncio r = await fin.future;
    _precargar();
    return r;
  }
}

