class FortunaOmikuji {
  const FortunaOmikuji(this.kanji, this.nombre, this.frases, this.peso);
  final String kanji;
  final String nombre;
  final List<String> frases;
  final int peso;
}

const List<FortunaOmikuji> fortunasOmikuji = <FortunaOmikuji>[
  FortunaOmikuji('大吉', 'Gran fortuna', <String>[
    'Hoy tu cuerpo responde. Si el plan dice una serie más, hazla con la técnica limpia.',
    'Un récord ronda tu barra. Calienta bien y ve por él sin prisa.',
    'El templo brilla contigo. Lo que hoy entrenes, mañana se notará.',
  ], 2),
  FortunaOmikuji('中吉', 'Buena fortuna', <String>[
    'Constancia antes que intensidad: cumplir hoy vale más que destrozarte.',
    'Tu espalda y tus piernas agradecen el trabajo que nadie ve.',
    'Bebe agua, duerme temprano: así se gana el próximo rango.',
  ], 3),
  FortunaOmikuji('小吉', 'Pequeña fortuna', <String>[
    'Un paso corto también es avanzar. Diez minutos cuentan.',
    'Revisa tu técnica en el visor antes de subir el peso.',
    'Estira al terminar: la flexibilidad de hoy es la fuerza de mañana.',
  ], 3),
  FortunaOmikuji('吉', 'Fortuna', <String>[
    'El camino es largo y lo estás recorriendo. Eso ya es fortuna.',
    'Escucha a tu cuerpo: si pide descanso, el descanso también entrena.',
    'Escribe a Tenshi cómo te sientes; a veces un ajuste lo cambia todo.',
  ], 3),
  FortunaOmikuji('末吉', 'Fortuna por venir', <String>[
    'Lo mejor llega después. Siembra hoy, aunque aún no veas el brote.',
    'Una semana constante y el templo se verá distinto.',
  ], 2),
  FortunaOmikuji('凶', 'Camino cuesta arriba', <String>[
    'Ata este papel al pino del templo y entrena igual: la mala fortuna se suda.',
    'Día difícil. Haz lo mínimo bien hecho y vuelve mañana más fuerte.',
  ], 1),
];

class AlmacenAnuncios extends ChangeNotifier {
  AlmacenAnuncios._();
  static final AlmacenAnuncios instancia = AlmacenAnuncios._();

  static const int tallerDia = 10;
  static const int monPorAnuncio = 10;
  static const int omikujiMon = 5;
  static const int pruebasDia = 2;
  static const int fotosExtraMes = 2;
  static const int tenshiAnunciosDia = 5;
  static const int tenshiPorAnuncio = 3;
  static const Duration duracionPrueba = Duration(hours: 24);

  final Map<String, Map<String, dynamic>> _datos = <String, Map<String, dynamic>>{};

  Map<String, dynamic> _de(String u) => _datos.putIfAbsent(u, () => <String, dynamic>{});

  static String _f(DateTime d) =>
      '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
  static String get _hoy => _f(DateTime.now());
  static String get _semana {
    final DateTime d = DateTime.now();
    return 'S${_f(DateTime(d.year, d.month, d.day - (d.weekday - 1)))}';
  }

  static String get _mes {
    final DateTime d = DateTime.now();
    return 'M${d.year}-${d.month.toString().padLeft(2, '0')}';
  }

  Map<String, int> _cuentas(String u) {
    final Object? c = _de(u)['cuentas'];
    final Map<String, int> r = <String, int>{};
    if (c is Map) {
      c.forEach((Object? k, Object? v) {
        if (k is String && v is num) r[k] = v.toInt();
      });
    }
    return r;
  }

  int _cuenta(String u, String tipo, String periodo) => _cuentas(u)['$tipo@$periodo'] ?? 0;

  void _sumar(String u, String tipo, String periodo) {
    final Map<String, int> c = _cuentas(u);
    final Set<String> vigentes = <String>{_hoy, _semana, _mes};
    c.removeWhere((String k, int _) => !vigentes.contains(k.split('@').last));
    c['$tipo@$periodo'] = (c['$tipo@$periodo'] ?? 0) + 1;
    _de(u)['cuentas'] = c;
  }

  void _guardado() {
    NubeTemplo.instancia.marcarCambio();
    notifyListeners();
  }

  // -- Taller --------------------------------------------------------------
  int tallerRestantes(String u) => math.max(0, tallerDia - _cuenta(u, 'taller', _hoy));

  bool cobrarTaller(String u) {
    if (tallerRestantes(u) <= 0) return false;
    _sumar(u, 'taller', _hoy);
    MonedaTemplo.instancia.ganar(u, monPorAnuncio, 'Ofrenda del espectador');
    _guardado();
    return true;
  }

  // -- Ofrenda doble -------------------------------------------------------
  void registrarSesion(String u, int mon) {
    if (mon <= 0) return;
    _de(u)['ofrenda'] = <String, dynamic>{'dia': _hoy, 'base': mon};
    _guardado();
  }

  int _baseOfrenda(String u) {
    final Object? o = _de(u)['ofrenda'];
    if (o is Map && o['dia'] == _hoy && o['base'] is num) return (o['base'] as num).toInt();
    return 0;
  }

  int extraOfrenda(String u) => (_baseOfrenda(u) / 2).ceil();
  int baseOfrenda(String u) => _baseOfrenda(u);
  bool ofrendaDisponible(String u) => _baseOfrenda(u) > 0 && _cuenta(u, 'ofrenda', _hoy) == 0;

  int cobrarOfrenda(String u) {
    if (!ofrendaDisponible(u)) return 0;
    final int extra = extraOfrenda(u);
    _sumar(u, 'ofrenda', _hoy);
    MonedaTemplo.instancia.ganar(u, extra, 'Ofrenda doble');
    _guardado();
    return extra;
  }

  // -- Omikuji -------------------------------------------------------------
  int omikujiHoy(String u) => _cuenta(u, 'omikuji', _hoy);

  /// La fortuna que salió hoy (la última), o null.
  ({FortunaOmikuji fortuna, String frase})? fortunaDeHoy(String u) {
    final Object? o = _de(u)['omikuji'];
    if (o is! Map || o['dia'] != _hoy) return null;
    final int i = (o['i'] as num?)?.toInt() ?? 0;
    final int j = (o['j'] as num?)?.toInt() ?? 0;
    final FortunaOmikuji f = fortunasOmikuji[i.clamp(0, fortunasOmikuji.length - 1)];
    return (fortuna: f, frase: f.frases[j.clamp(0, f.frases.length - 1)]);
  }

  ({FortunaOmikuji fortuna, String frase}) tirarOmikuji(String u) {
    final int n = omikujiHoy(u);
    final math.Random r = math.Random('$u|$_hoy|$n'.hashCode);
    final int total = fortunasOmikuji.fold<int>(0, (int s, FortunaOmikuji f) => s + f.peso);
    int x = r.nextInt(total);
    int i = 0;
    while (x >= fortunasOmikuji[i].peso) {
      x -= fortunasOmikuji[i].peso;
      i++;
    }
    final int j = r.nextInt(fortunasOmikuji[i].frases.length);
    _sumar(u, 'omikuji', _hoy);
    _de(u)['omikuji'] = <String, dynamic>{'dia': _hoy, 'i': i, 'j': j};
    MonedaTemplo.instancia.ganar(u, omikujiMon, 'Omikuji del templo');
    _guardado();
    return (fortuna: fortunasOmikuji[i], frase: fortunasOmikuji[i].frases[j]);
  }

  // -- Lucir una pieza 24 horas --------------------------------------------
  int pruebasRestantes(String u) => math.max(0, pruebasDia - _cuenta(u, 'prueba', _hoy));

  ({CapaVineta capa, String id, DateTime vence})? pruebaActiva(String u) {
    final Object? p = _de(u)['prueba'];
    if (p is! Map) return null;
    CapaVineta? capa;
    for (final CapaVineta c in CapaVineta.values) {
      if (c.name == p['capa']) capa = c;
    }
    final DateTime? vence = DateTime.tryParse('${p['vence']}');
    final Object? id = p['id'];
    if (capa == null || vence == null || id is! String) return null;
    return (capa: capa, id: id, vence: vence);
  }

  void iniciarPrueba(String u, CapaVineta capa, String id) {
    revisarPrueba(u, forzar: true);
    final Map<CapaVineta, String> v = MotorProgresion.instancia.de(u).vineta;
    _de(u)['prueba'] = <String, dynamic>{
      'capa': capa.name,
      'id': id,
      'anterior': v[capa],
      'vence': DateTime.now().add(duracionPrueba).toIso8601String(),
    };
    _sumar(u, 'prueba', _hoy);
    v[capa] = id;
    _guardado();
    SesionTemplo.instancia.sincronizarIdentidad(u);
  }

  /// Cierra la prueba si venció (o si [forzar]). Si la pieza no se compró y
  /// sigue puesta, vuelve la que había. Devuelve true si cambió algo.
  bool revisarPrueba(String u, {bool forzar = false}) {
    final ({CapaVineta capa, String id, DateTime vence})? p = pruebaActiva(u);
    if (p == null) {
      if (_de(u).containsKey('prueba')) {
        _de(u).remove('prueba');
        return true;
      }
      return false;
    }
    final bool comprada = MotorProgresion.instancia.tienePieza(u, p.id);
    if (!forzar && !comprada && DateTime.now().isBefore(p.vence)) return false;
    final Map<CapaVineta, String> v = MotorProgresion.instancia.de(u).vineta;
    final Object? anterior = (_de(u)['prueba'] as Map)['anterior'];
    _de(u).remove('prueba');
    if (!comprada && v[p.capa] == p.id) {
      if (anterior is String && anterior.isNotEmpty) {
        v[p.capa] = anterior;
      } else {
        final String? inicial = PiezasVineta.configInicial()[p.capa];
        if (inicial != null) v[p.capa] = inicial;
      }
      SesionTemplo.instancia.sincronizarIdentidad(u);
    }
    _guardado();
    return true;
  }

  // -- Informe semanal y fotos ---------------------------------------------
  bool informeAbierto(String u) => _cuenta(u, 'informe', _semana) > 0;

  void abrirInforme(String u) {
    if (informeAbierto(u)) return;
    _sumar(u, 'informe', _semana);
    _guardado();
  }

  int fotosExtra(String u) => _cuenta(u, 'foto', _mes);
  bool puedeFotoExtra(String u) => fotosExtra(u) < fotosExtraMes;

  void sumarFoto(String u) {
    if (!puedeFotoExtra(u)) return;
    _sumar(u, 'foto', _mes);
    _guardado();
  }

  // -- Copia en la nube ----------------------------------------------------
  Map<String, dynamic> exportar(String u) => Map<String, dynamic>.from(_de(u));

  void importar(String u, Object? m) {
    _datos[u] = m is Map ? Map<String, dynamic>.from(m) : <String, dynamic>{};
    notifyListeners();
  }
}

// ---------------------------------------------------------------------------
// 48.4 VER UN ANUNCIO DESDE CUALQUIER PANTALLA
// ---------------------------------------------------------------------------

/// Busca un anuncio, lo muestra y devuelve true si se vio entero.
Future<bool> verAnuncio(BuildContext context) async {
  if (EnWeb.activo) {
    await recomendarApp(context, SoloEnApp.anuncios);
    return false;
  }
  if (!MotorAnuncios.instancia.permitido) {
    avisoClan(context, 'Los anuncios no están disponibles en esta cuenta.');
    return false;
  }
  if (MotorAnuncios.instancia.simulado) {
    final bool? visto = await showDialog<bool>(
      context: context,
      useRootNavigator: true,
      barrierDismissible: false,
      barrierColor: Colors.black.withValues(alpha: 0.85),
      builder: (_) => const _AnuncioSimulado(),
    );
    if (visto == true) {
      HapticFeedback.mediumImpact();
      return true;
    }
    if (context.mounted) {
      avisoClan(context, 'El anuncio se cerró antes de terminar: esta vez no hubo recompensa.');
    }
    return false;
  }
  final NavigatorState nav = Navigator.of(context, rootNavigator: true);
  bool abierto = true;
  unawaited(showDialog<void>(
    context: context,
    useRootNavigator: true,
    barrierDismissible: false,
    barrierColor: Colors.black.withValues(alpha: 0.6),
    builder: (_) => const _BuscandoAnuncio(),
  ).then((_) => abierto = false));
  void cerrar() {
    if (abierto) {
      abierto = false;
      nav.pop();
    }
  }

  ResultadoAnuncio r = ResultadoAnuncio.sinAnuncio;
  try {
    r = await MotorAnuncios.instancia.mostrar(alListo: cerrar);
  } finally {
    cerrar();
  }
  if (!context.mounted) return r == ResultadoAnuncio.visto;
  if (r == ResultadoAnuncio.visto) {
    HapticFeedback.mediumImpact();
    return true;
  }
  avisoClan(
      context,
      r == ResultadoAnuncio.cerrado
          ? 'El anuncio se cerró antes de terminar: esta vez no hubo recompensa.'
          : 'Ahora no hay anuncios disponibles. Prueba en un rato.');
  return false;
}

/// Solo en modo debug fuera del teléfono: un «anuncio» de 5 segundos para
/// probar el recorrido completo (recompensa incluida).
class _AnuncioSimulado extends StatefulWidget {
  const _AnuncioSimulado();

  @override
  State<_AnuncioSimulado> createState() => _AnuncioSimuladoState();
}

class _AnuncioSimuladoState extends State<_AnuncioSimulado> {
  int _quedan = 5;
  Timer? _t;

  @override
  void initState() {
    super.initState();
    _t = Timer.periodic(const Duration(seconds: 1), (Timer t) {
      if (!mounted) return t.cancel();
      setState(() => _quedan--);
      if (_quedan <= 0) t.cancel();
    });
  }

  @override
  void dispose() {
    _t?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final bool listo = _quedan <= 0;
    return PopScope(
      canPop: false,
      child: Center(
        child: Container(
          width: 300,
          padding: const EdgeInsets.fromLTRB(20, 18, 20, 14),
          decoration: BoxDecoration(
            color: TempleColors.grafito,
            borderRadius: BorderRadius.circular(TempleRadius.tarjeta),
            border: Border.all(color: TempleColors.violeta.withValues(alpha: 0.6)),
          ),
          child: Material(
            color: Colors.transparent,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: <Widget>[
                const Text('ANUNCIO DE PRUEBA',
                    textAlign: TextAlign.center,
                    style: TextStyle(fontSize: 11, letterSpacing: 3, color: TempleColors.textoTenue)),
                const SizedBox(height: 14),
                Container(
                  height: 150,
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(12),
                    gradient: const LinearGradient(
                      begin: Alignment.topLeft,
                      end: Alignment.bottomRight,
                      colors: <Color>[Color(0xFF2A1B4A), Color(0xFF0E0B16)],
                    ),
                  ),
                  alignment: Alignment.center,
                  child: Text(listo ? '✓' : '$_quedan',
                      style: const TextStyle(fontSize: 46, fontWeight: FontWeight.w300, color: TempleColors.blancoLuna)),
                ),
                const SizedBox(height: 12),
                const Text(
                  'Simulado porque estás en Chrome o Windows en modo de prueba. En el teléfono aquí sale el '
                  'video de Google.',
                  textAlign: TextAlign.center,
                  style: TextStyle(fontSize: 11.5, height: 1.4, color: TempleColors.textoSuave),
                ),
                const SizedBox(height: 12),
                Row(
                  children: <Widget>[
                    TextButton(
                      onPressed: () => Navigator.of(context).pop(false),
                      child: const Text('Cerrar ya', style: TextStyle(color: TempleColors.textoTenue)),
                    ),
                    const Spacer(),
                    FilledButton(
                      onPressed: listo ? () => Navigator.of(context).pop(true) : null,
                      style: FilledButton.styleFrom(backgroundColor: TempleColors.violeta),
                      child: Text(listo ? 'Recibir recompensa' : 'Espera…'),
                    ),
                  ],
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

