// ---------------------------------------------------------------------------
// 48.5 TALLER: OFRENDA DEL ESPECTADOR
// ---------------------------------------------------------------------------

class TarjetaAnunciosTaller extends StatelessWidget {
  const TarjetaAnunciosTaller({super.key, required this.usuario, required this.onMon});
  final String usuario;
  final VoidCallback onMon;

  @override
  Widget build(BuildContext context) {
    if (!MotorAnuncios.instancia.ofrecible) return const SizedBox.shrink();
    return ListenableBuilder(
      listenable: AlmacenAnuncios.instancia,
      builder: (BuildContext context, _) {
        final AlmacenAnuncios a = AlmacenAnuncios.instancia;
        final int quedan = a.tallerRestantes(usuario);
        return Padding(
          padding: const EdgeInsets.only(bottom: 14),
          child: TempleCard(
            onTap: quedan == 0
                ? null
                : () async {
                    if (!await verAnuncio(context)) return;
                    if (!a.cobrarTaller(usuario)) return;
                    sonar(SonidoTemplo.mon);
                    onMon();
                    if (context.mounted) {
                      avisoClan(context, '+${AlmacenAnuncios.monPorAnuncio} mon. Gracias por sostener el templo.');
                    }
                  },
            child: Row(
              children: <Widget>[
                const IconoMon(size: 30),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: <Widget>[
                      const Text('Ofrenda del espectador',
                          style: TextStyle(fontSize: 14, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                      const SizedBox(height: 3),
                      Text(
                        quedan == 0
                            ? 'Ya recibiste tus ${AlmacenAnuncios.tallerDia * AlmacenAnuncios.monPorAnuncio} mon de hoy. Mañana hay más.'
                            : 'Mira un video corto y recibe ${AlmacenAnuncios.monPorAnuncio} mon. '
                                'Te ${quedan == 1 ? 'queda 1' : 'quedan $quedan'} hoy.',
                        style: const TextStyle(fontSize: 11.5, height: 1.35, color: TempleColors.textoTenue),
                      ),
                      const SizedBox(height: 7),
                      _PuntosCupo(total: AlmacenAnuncios.tallerDia, usados: AlmacenAnuncios.tallerDia - quedan),
                    ],
                  ),
                ),
                const SizedBox(width: 10),
                _PastillaAnuncio(texto: '+${AlmacenAnuncios.monPorAnuncio}', activa: quedan > 0),
              ],
            ),
          ),
        );
      },
    );
  }
}

