class TarjetaOfrendaDoble extends StatefulWidget {
  const TarjetaOfrendaDoble({super.key, required this.usuario});
  final String usuario;

  @override
  State<TarjetaOfrendaDoble> createState() => _TarjetaOfrendaDobleState();
}

class _TarjetaOfrendaDobleState extends State<TarjetaOfrendaDoble> {
  int _cobrado = 0;

  @override
  Widget build(BuildContext context) {
    final AlmacenAnuncios a = AlmacenAnuncios.instancia;
    final String u = widget.usuario;
    if (!MotorAnuncios.instancia.ofrecible) return const SizedBox.shrink();
    if (_cobrado == 0 && !a.ofrendaDisponible(u)) return const SizedBox.shrink();
    return Padding(
      padding: const EdgeInsets.only(bottom: 22),
      child: TempleCard(
        destacada: _cobrado == 0,
        onTap: _cobrado > 0
            ? null
            : () async {
                if (!await verAnuncio(context)) return;
                final int extra = a.cobrarOfrenda(u);
                if (extra > 0) sonar(SonidoTemplo.mon);
                if (extra > 0 && mounted) setState(() => _cobrado = extra);
              },
        child: Row(
          children: <Widget>[
            const IconoMon(size: 30),
            const SizedBox(width: 12),
            Expanded(
              child: AnimatedSwitcher(
                duration: TempleMotion.medio,
                child: _cobrado > 0
                    ? Text('Ofrenda doble: +$_cobrado mon más en tu bolsa.',
                        key: const ValueKey<int>(1),
                        style: const TextStyle(fontSize: 13.5, color: TempleColors.dorado))
                    : Column(
                        key: const ValueKey<int>(0),
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: <Widget>[
                          Text('Hoy ganaste ${a.baseOfrenda(u)} mon',
                              style: const TextStyle(
                                  fontSize: 14, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                          const SizedBox(height: 3),
                          Text('Mira un anuncio y recibe +${a.extraOfrenda(u)} más. Una vez al día.',
                              style: const TextStyle(fontSize: 11.5, color: TempleColors.textoTenue)),
                        ],
                      ),
              ),
            ),
            if (_cobrado == 0) ...<Widget>[
              const SizedBox(width: 10),
              _PastillaAnuncio(texto: '+${a.extraOfrenda(u)}'),
            ],
          ],
        ),
      ),
    );
  }
}

// ---------------------------------------------------------------------------
// 48.7 CASA: OMIKUJI DEL TEMPLO
//
// El papelito de la fortuna de los santuarios. Uno gratis al día y otro con
// un anuncio; los dos dan lo mismo (5 mon): la suerte está en la frase, no
// en el premio.
// ---------------------------------------------------------------------------

class TarjetaOmikuji extends StatelessWidget {
  const TarjetaOmikuji({super.key, required this.usuario});
  final String usuario;

  Future<void> _tirar(BuildContext context, {required bool conAnuncio}) async {
    if (conAnuncio && !await verAnuncio(context)) return;
    final ({FortunaOmikuji fortuna, String frase}) f = AlmacenAnuncios.instancia.tirarOmikuji(usuario);
    if (!context.mounted) return;
    HapticFeedback.mediumImpact();
    await mostrarCelebracion(
      context,
      titulo: 'Omikuji · ${f.fortuna.nombre}',
      sonido: SonidoTemplo.omikuji,
      nombre: f.fortuna.kanji,
      detalle: '${f.frase}\n\n+${AlmacenAnuncios.omikujiMon} mon',
      color: f.fortuna.peso == 1 ? TempleColors.textoSuave : TempleColors.dorado,
      vista: _PapelOmikuji(kanji: f.fortuna.kanji, alto: 120),
      boton: 'Guardar mi fortuna',
    );
  }

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: AlmacenAnuncios.instancia,
      builder: (BuildContext context, _) {
        final AlmacenAnuncios a = AlmacenAnuncios.instancia;
        final int n = a.omikujiHoy(usuario);
        final ({FortunaOmikuji fortuna, String frase})? hoy = a.fortunaDeHoy(usuario);
        final bool anuncio = MotorAnuncios.instancia.ofrecible && n == 1;
        return TempleCard(
          onTap: n == 0
              ? () => _tirar(context, conAnuncio: false)
              : anuncio
                  ? () => _tirar(context, conAnuncio: true)
                  : null,
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              _PapelOmikuji(kanji: hoy?.fortuna.kanji ?? 'おみくじ', alto: 74, cerrado: hoy == null),
              const SizedBox(width: 14),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    Text(hoy == null ? 'Omikuji del templo' : 'Tu fortuna: ${hoy.fortuna.nombre}',
                        style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                    const SizedBox(height: 4),
                    Text(
                      hoy == null
                          ? 'Saca el papel de la fortuna de hoy. Trae un consejo y ${AlmacenAnuncios.omikujiMon} mon.'
                          : hoy.frase,
                      style: const TextStyle(fontSize: 12, height: 1.4, color: TempleColors.textoSuave),
                    ),
                    const SizedBox(height: 10),
                    if (n == 0)
                      const _PastillaFortuna(texto: 'Sacar mi fortuna')
                    else if (anuncio)
                      _PastillaAnuncio(texto: 'Otra fortuna · +${AlmacenAnuncios.omikujiMon}')
                    else
                      const Text('Mañana te espera otro papel.',
                          style: TextStyle(fontSize: 11.5, color: TempleColors.textoTenue)),
                  ],
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

