// ---------------------------------------------------------------------------
// 48.8 TALLER: LUCIR UNA PIEZA 24 HORAS
// ---------------------------------------------------------------------------

String _nombrePiezaVineta(CapaVineta capa, String id) {
  for (final PiezaUnificada p in PiezaUnificada.deCapa(capa)) {
    if (p.id == id) return p.nombre;
  }
  return 'la pieza';
}

/// Debajo de la vista previa del Taller: prueba en curso o botón para lucir
/// 24 horas la pieza que se está probando.
class BarraPruebaPieza extends StatelessWidget {
  const BarraPruebaPieza({super.key, required this.usuario, this.probando, this.onCambio});
  final String usuario;

  /// Pieza de la tienda que se está viendo sin tenerla (capa, id).
  final ({CapaVineta capa, String id})? probando;
  final VoidCallback? onCambio;

  @override
  Widget build(BuildContext context) {
    if (!MotorAnuncios.instancia.ofrecible) return const SizedBox.shrink();
    return ListenableBuilder(
      listenable: AlmacenAnuncios.instancia,
      builder: (BuildContext context, _) {
        final AlmacenAnuncios a = AlmacenAnuncios.instancia;
        final ({CapaVineta capa, String id, DateTime vence})? activa = a.pruebaActiva(usuario);
        final ({CapaVineta capa, String id})? p = probando;
        if (p != null && activa?.id != p.id) {
          final int quedan = a.pruebasRestantes(usuario);
          return Padding(
            padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
            child: GestureDetector(
              onTap: quedan == 0
                  ? () => avisoClan(context, 'Hoy ya luciste ${AlmacenAnuncios.pruebasDia} piezas de prueba. Mañana, más.')
                  : () async {
                      if (!await verAnuncio(context)) return;
                      a.iniciarPrueba(usuario, p.capa, p.id);
                      onCambio?.call();
                      if (context.mounted) {
                        avisoClan(context,
                            'Luces ${_nombrePiezaVineta(p.capa, p.id)} durante 24 horas. Si te gusta, cómprala para quedártela.');
                      }
                    },
              child: Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: <Widget>[
                  _PastillaAnuncio(texto: 'Lucirla 24 h en tu perfil', activa: quedan > 0),
                  const SizedBox(width: 8),
                  Text('$quedan de ${AlmacenAnuncios.pruebasDia} hoy',
                      style: const TextStyle(fontSize: 11, color: TempleColors.textoTenue)),
                ],
              ),
            ),
          );
        }
        if (activa == null) return const SizedBox.shrink();
        final Duration falta = activa.vence.difference(DateTime.now());
        final int horas = math.max(1, (falta.inMinutes / 60).ceil());
        return Padding(
          padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
          child: Text(
            'Luces ${_nombrePiezaVineta(activa.capa, activa.id)} de prueba · ${horas == 1 ? 'queda 1 hora' : 'quedan $horas horas'}. '
            'Cómprala para quedártela.',
            textAlign: TextAlign.center,
            style: const TextStyle(fontSize: 11.5, color: TempleColors.alertaSuave),
          ),
        );
      },
    );
  }
}

// ---------------------------------------------------------------------------
// 48.9 TENSHI: MENSAJES EXTRA
// ---------------------------------------------------------------------------

/// Ve un anuncio y pide al servidor los 3 mensajes extra.
Future<void> anuncioParaTenshi(BuildContext context) async {
  if (UsoPase.instancia.anunciosTenshiHoy >= AlmacenAnuncios.tenshiAnunciosDia) {
    avisoClan(context, 'Hoy ya sumaste todos los mensajes extra. Mañana se renueva.');
    return;
  }
  if (!await verAnuncio(context)) return;
  Object? r;
  for (int intento = 0; intento < 2 && r == null; intento++) {
    try {
      r = await supa.rpc('tenshi_anuncio').timeout(const Duration(seconds: 10));
    } catch (_) {
      await Future<void>.delayed(const Duration(seconds: 1));
    }
  }
  if (!context.mounted) return;
  if (r is Map) {
    UsoPase.instancia.aplicarCupo(r);
    if (r['ok'] == true) sonar(SonidoTemplo.tenshi);
    avisoClan(
        context,
        r['ok'] == true
            ? '+${AlmacenAnuncios.tenshiPorAnuncio} mensajes con la mente completa de Tenshi.'
            : 'Hoy ya sumaste todos los mensajes extra. Mañana se renueva.');
  } else {
    avisoClan(context, 'No pudimos sumar los mensajes: revisa tu conexión e inténtalo de nuevo.');
  }
}

// ---------------------------------------------------------------------------
// 48.10 OFRECER ANUNCIO O PASE
// ---------------------------------------------------------------------------

/// Hoja con dos caminos: ver un anuncio para desbloquear algo una vez, o el
/// Pase. Devuelve true si se vio el anuncio entero; false si no.
Future<bool> ofrecerAnuncioOPase(
  BuildContext context, {
  required String titulo,
  required String texto,
  required String recompensa,
  required String quedan,
  required Future<void> Function() abrirMuro,
}) async {
  final bool? anuncio = await showModalBottomSheet<bool>(
    context: context,
    backgroundColor: TempleColors.grafito,
    shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
    builder: (BuildContext ctx) => SafeArea(
      top: false,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(20, 20, 20, 14),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: <Widget>[
            Text(titulo,
                style: const TextStyle(fontSize: 17, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
            const SizedBox(height: 6),
            Text(texto, style: const TextStyle(fontSize: 13, height: 1.45, color: TempleColors.textoSuave)),
            const SizedBox(height: 16),
            TempleCard(
              onTap: () => Navigator.of(ctx).pop(true),
              child: Row(
                children: <Widget>[
                  const Icon(Icons.play_circle_outline_rounded, color: TempleColors.violetaClaro, size: 28),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: <Widget>[
                        Text(recompensa,
                            style: const TextStyle(
                                fontSize: 13.5, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                        const SizedBox(height: 2),
                        Text(quedan, style: const TextStyle(fontSize: 11.5, color: TempleColors.textoTenue)),
                      ],
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 10),
            TempleCard(
              onTap: () => Navigator.of(ctx).pop(false),
              child: const Row(
                children: <Widget>[
                  EmblemaPase(size: 28),
                  SizedBox(width: 12),
                  Expanded(
                    child: Text('Sin límites con el Pase del Templo',
                        style: TextStyle(fontSize: 13.5, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    ),
  );
  if (anuncio == null || !context.mounted) return false;
  if (!anuncio) {
    await abrirMuro();
    return false;
  }
  return verAnuncio(context);
}

// ===========================================================================
// 49. SONIDOS DEL TEMPLO
//
// Trece sonidos propios, hechos para la app: madera de templo, campana rin,
// koto en escala hirajoshi, taiko, monedas y un furin (campanilla de viento).
// Suaves y cortos. Se mezclan con la música de la persona (no la cortan) y
// en iPhone respetan el modo silencio. Se apagan o se bajan desde el menú
// «⋮» de cualquier módulo → «Sonidos del templo».
//
// Los archivos van en assets/sonidos/ y se declaran en pubspec.yaml.
// ===========================================================================

enum SonidoTemplo {
  toque,
  serie,
  descanso,
  sesion,
  record,
  nivel,
  mon,
  compra,
  desbloqueo,
  tenshi,
  respeto,
  omikuji,
  pase,
}

class SonidosTemplo extends ChangeNotifier {
  SonidosTemplo._();
  static final SonidosTemplo instancia = SonidosTemplo._();

  static const String _clave = 'sonidos_v1';

  /// Cuánto suena cada uno frente a los demás (antes del volumen general).
  static const Map<SonidoTemplo, double> _mezcla = <SonidoTemplo, double>{
    SonidoTemplo.toque: 0.3,
    SonidoTemplo.serie: 0.6,
    SonidoTemplo.descanso: 0.85,
    SonidoTemplo.sesion: 0.9,
    SonidoTemplo.record: 0.85,
    SonidoTemplo.nivel: 0.9,
    SonidoTemplo.mon: 0.6,
    SonidoTemplo.compra: 0.75,
    SonidoTemplo.desbloqueo: 0.7,
    SonidoTemplo.tenshi: 0.45,
    SonidoTemplo.respeto: 0.55,
    SonidoTemplo.omikuji: 0.7,
    SonidoTemplo.pase: 0.7,
  };

  bool _activos = true;
  double _volumen = 0.7;
  bool _contextoListo = false;
  final Map<SonidoTemplo, List<AudioPlayer>> _jugadores = <SonidoTemplo, List<AudioPlayer>>{};
  final Map<SonidoTemplo, int> _turno = <SonidoTemplo, int>{};
  final Map<SonidoTemplo, DateTime> _ultimo = <SonidoTemplo, DateTime>{};

  bool get activos => _activos;
  double get volumen => _volumen;

  Future<void> cargar() async {
    try {
      final SharedPreferences sp = await SharedPreferences.getInstance();
      final String? s = sp.getString(_clave);
      if (s != null) {
        final Object? m = convert.jsonDecode(s);
        if (m is Map) {
          _activos = m['activos'] != false;
          _volumen = ((m['volumen'] as num?)?.toDouble() ?? 0.7).clamp(0.0, 1.0);
        }
      }
    } catch (_) {}
    notifyListeners();
  }

  Future<void> cambiar({bool? activos, double? volumen}) async {
    if (activos != null) _activos = activos;
    if (volumen != null) _volumen = volumen.clamp(0.0, 1.0);
    notifyListeners();
    try {
      final SharedPreferences sp = await SharedPreferences.getInstance();
      await sp.setString(_clave, convert.jsonEncode(<String, Object>{'activos': _activos, 'volumen': _volumen}));
    } catch (_) {}
  }

  Future<void> _prepararContexto() async {
    if (_contextoListo) return;
    _contextoListo = true;
    try {
      // Sin pedir el «foco» del audio: la música de la persona sigue sonando.
      await AudioPlayer.global.setAudioContext(AudioContext(
        android: AudioContextAndroid(
          isSpeakerphoneOn: false,
          stayAwake: false,
          contentType: AndroidContentType.sonification,
          usageType: AndroidUsageType.game,
          audioFocus: AndroidAudioFocus.none,
        ),
        iOS: AudioContextIOS(
          category: AVAudioSessionCategory.ambient,
          options: const <AVAudioSessionOptions>{},
        ),
      ));
    } catch (e) {
      debugPrint('Sonidos: contexto no aplicado: $e');
    }
  }

  AudioPlayer _jugador(SonidoTemplo s) {
    final List<AudioPlayer> lista = _jugadores.putIfAbsent(s, () {
      final int n = s == SonidoTemplo.serie || s == SonidoTemplo.toque || s == SonidoTemplo.mon ? 3 : 2;
      return <AudioPlayer>[
        for (int i = 0; i < n; i++)
          AudioPlayer()
            ..setReleaseMode(ReleaseMode.stop)
            ..setPlayerMode(PlayerMode.lowLatency),
      ];
    });
    final int i = (_turno[s] ?? 0) % lista.length;
    _turno[s] = i + 1;
    return lista[i];
  }

  /// Toca un sonido. Devuelve false si los sonidos están apagados.
  bool tocar(SonidoTemplo s, {Duration retraso = Duration.zero}) {
    if (!_activos || _volumen <= 0) return false;
    final DateTime ahora = DateTime.now();
    final DateTime? antes = _ultimo[s];
    if (antes != null && ahora.difference(antes).inMilliseconds < 90) return true;
    _ultimo[s] = ahora;
    Future<void> reproducir() async {
      try {
        await _prepararContexto();
        final AudioPlayer p = _jugador(s);
        await p.stop();
        await p.play(
          AssetSource('sonidos/${s.name}.mp3'),
          volume: (_volumen * (_mezcla[s] ?? 0.7)).clamp(0.0, 1.0),
          mode: PlayerMode.lowLatency,
        );
      } catch (e) {
        debugPrint('Sonidos: no sonó ${s.name}: $e');
      }
    }

    if (retraso == Duration.zero) {
      unawaited(reproducir());
    } else {
      unawaited(Future<void>.delayed(retraso, reproducir));
    }
    return true;
  }
}

/// Atajo: `sonar(SonidoTemplo.serie)`.
bool sonar(SonidoTemplo s, {Duration retraso = Duration.zero}) =>
    SonidosTemplo.instancia.tocar(s, retraso: retraso);

/// Hoja de ajustes: encender, volumen y escuchar.
Future<void> abrirAjustesSonido(BuildContext context) {
  return showModalBottomSheet<void>(
    context: context,
    backgroundColor: TempleColors.grafito,
    shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
    builder: (BuildContext ctx) => SafeArea(
      top: false,
      child: ListenableBuilder(
        listenable: SonidosTemplo.instancia,
        builder: (BuildContext c, _) {
          final SonidosTemplo s = SonidosTemplo.instancia;
          return Padding(
            padding: const EdgeInsets.fromLTRB(22, 20, 22, 18),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: <Widget>[
                const Text('Sonidos del templo',
                    style: TextStyle(fontSize: 17, fontWeight: FontWeight.w600, color: TempleColors.blancoLuna)),
                const SizedBox(height: 4),
                const Text(
                  'Madera al completar una serie, campana al terminar el descanso, taiko al cerrar la sesión, koto en '
                  'tus récords. No cortan tu música.',
                  style: TextStyle(fontSize: 12.5, height: 1.45, color: TempleColors.textoSuave),
                ),
                const SizedBox(height: 14),
                Row(
                  children: <Widget>[
                    const Expanded(
                      child: Text('Sonidos', style: TextStyle(fontSize: 14, color: TempleColors.texto)),
                    ),
                    Switch(
                      value: s.activos,
                      onChanged: (bool v) {
                        s.cambiar(activos: v);
                        if (v) sonar(SonidoTemplo.desbloqueo);
                      },
                      activeTrackColor: TempleColors.violeta,
                      inactiveTrackColor: TempleColors.borde,
                    ),
                  ],
                ),
                AnimatedOpacity(
                  duration: TempleMotion.rapido,
                  opacity: s.activos ? 1 : 0.35,
                  child: Row(
                    children: <Widget>[
                      const Icon(Icons.volume_down_rounded, size: 20, color: TempleColors.textoTenue),
                      Expanded(
                        child: Slider(
                          value: s.volumen,
                          onChanged: s.activos ? (double v) => s.cambiar(volumen: v) : null,
                          onChangeEnd: s.activos ? (double v) => sonar(SonidoTemplo.serie) : null,
                          activeColor: TempleColors.violetaClaro,
                          inactiveColor: TempleColors.borde,
                        ),
                      ),
                      const Icon(Icons.volume_up_rounded, size: 20, color: TempleColors.textoTenue),
                    ],
                  ),
                ),
                const SizedBox(height: 6),
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: <Widget>[
                    for (final (SonidoTemplo, String) m in const <(SonidoTemplo, String)>[
                      (SonidoTemplo.serie, 'Serie'),
                      (SonidoTemplo.descanso, 'Descanso'),
                      (SonidoTemplo.record, 'Récord'),
                      (SonidoTemplo.nivel, 'Nivel'),
                      (SonidoTemplo.sesion, 'Sesión'),
                      (SonidoTemplo.mon, 'Mon'),
                    ])
                      ActionChip(
                        label: Text(m.$2, style: const TextStyle(fontSize: 12, color: TempleColors.texto)),
                        avatar: const Icon(Icons.play_arrow_rounded, size: 16, color: TempleColors.violetaClaro),
                        backgroundColor: TempleColors.superficie,
                        side: const BorderSide(color: TempleColors.borde),
                        onPressed: s.activos ? () => sonar(m.$1) : null,
                      ),
                  ],
                ),
              ],
            ),
          );
        },
      ),
    ),
  );
}

