class MiClanInfo {
  const MiClanInfo({
    required this.id,
    required this.nombre,
    required this.kanji,
    required this.color,
    required this.rol,
    required this.estado,
  });

  final String id;
  final String nombre;
  final String kanji;
  final int color;
  final String rol;
  final String estado;

  bool get activo => estado == 'activo';
  bool get manda => activo && (rol == 'lider' || rol == 'oficial');

  factory MiClanInfo.desde(Map<String, dynamic> m) => MiClanInfo(
        id: m['id'].toString(),
        nombre: (m['nombre'] ?? '').toString(),
        kanji: (m['kanji'] ?? '武').toString(),
        color: _entClan(m['color']),
        rol: (m['rol'] ?? 'miembro').toString(),
        estado: (m['estado'] ?? 'activo').toString(),
      );
}

