// ===========================================================================
// 59. RENDIMIENTO EN LA WEB
//
// En el navegador, Flutter vuelve a dibujar la pantalla entera en cada
// cuadro. Las animaciones decorativas que se repiten sin parar (el cielo,
// los pétalos, las escenas de la Casa y el Dojo, el guerrero de Ranked, el
// brillo del botón del Pase…) obligaban a dibujar 60 veces por segundo
// aunque no pasara nada importante.
//
// Desde la 1.5.2 la web es más sobria: la decoración queda quieta (el mismo
// cuadro que con «reducir movimiento») y no hay pétalos, para que vaya
// fluida en cualquier navegador y la experiencia completa quede en la app.
// Solo se animan las que cumplen una función (demostración de ejercicios,
// línea de tiempo de fotos, celebración), al ritmo de un reloj de 24
// cuadros por segundo. Lo que responde al dedo (botones, desplazamiento,
// transiciones, el teclado) sigue a 60. En la app instalada no cambia nada.
// ===========================================================================

class Rendimiento {
  const Rendimiento._();

  /// Modo ligero: en la web.
  static bool get ligero => kIsWeb;

  /// Latidos por segundo del reloj de la decoración en la web.
  static const int cuadrosDecoracion = 24;

  /// Ritmo de la decoración ambiental: cielos, escenas, pétalos, avatares
  /// en reposo. Como el anime «a dos cuadros». Lo rápido (celebraciones,
  /// brillo del Pase, guerrero de Ranked, ejercicio) va a 24.
  static const int cuadrosLentos = 12;
}

/// Reloj único de la decoración en la web: junta todas las animaciones
/// lentas para que se dibujen en el mismo cuadro, nunca más de
/// [Rendimiento.cuadrosDecoracion] veces por segundo.
class _RelojDecorativo {
  _RelojDecorativo._();
  static final _RelojDecorativo instancia = _RelojDecorativo._();

  static const int _periodoUs = 1000000 ~/ Rendimiento.cuadrosDecoracion;
  final Set<_TickerLento> _esperando = <_TickerLento>{};
  final Stopwatch _reloj = Stopwatch()..start();
  Timer? _timer;

  int get ahora => _reloj.elapsedMicroseconds;

  void esperar(_TickerLento t) {
    _esperando.add(t);
    _timer ??= Timer(Duration(microseconds: _periodoUs - (ahora % _periodoUs)), _latido);
  }

  void soltar(_TickerLento t) {
    _esperando.remove(t);
    if (_esperando.isEmpty) {
      _timer?.cancel();
      _timer = null;
    }
  }

  void _latido() {
    _timer = null;
    final int t = ahora;
    final List<_TickerLento> listos = _esperando.where((_TickerLento x) => x._listoEn <= t).toList();
    _esperando.removeAll(listos);
    for (final _TickerLento x in listos) {
      x._programarYa();
    }
    if (_esperando.isNotEmpty) {
      _timer = Timer(Duration(microseconds: _periodoUs - (ahora % _periodoUs)), _latido);
    }
  }
}

/// Ticker que, en vez de pedir un cuadro cada vez que la pantalla refresca,
/// espera el latido del reloj decorativo. El tiempo de la animación sigue
/// siendo el real: solo se dibujan menos cuadros.
class _TickerLento extends Ticker {
  _TickerLento(super.onTick, {required this.intervaloUs, super.debugLabel});

  final int intervaloUs;
  int _listoEn = 0;

  @override
  void scheduleTick({bool rescheduling = false}) {
    if (!rescheduling) {
      // El primer cuadro (al empezar o al volver a la pantalla) va ya.
      _RelojDecorativo.instancia.soltar(this);
      super.scheduleTick();
      return;
    }
    // Margen de 3 ms para no perder un latido por redondeo.
    _listoEn = _RelojDecorativo.instancia.ahora + intervaloUs - 3000;
    _RelojDecorativo.instancia.esperar(this);
  }

  void _programarYa() {
    if (shouldScheduleTick) super.scheduleTick(rescheduling: true);
  }

  @override
  void unscheduleTick() {
    _RelojDecorativo.instancia.soltar(this);
    if (scheduled) super.unscheduleTick();
  }

  @override
  void dispose() {
    _RelojDecorativo.instancia.soltar(this);
    super.dispose();
  }
}

/// Ticker que nunca pide cuadros: la animación queda en su primer cuadro,
/// igual que con «reducir movimiento». Para la decoración en la web.
class _TickerQuieto extends Ticker {
  _TickerQuieto(super.onTick, {super.debugLabel});

  @override
  void scheduleTick({bool rescheduling = false}) {}
}

/// Para las animaciones decorativas: hace lo mismo que
/// SingleTickerProviderStateMixin (y admite varios controladores), y en la
/// web las pone al ritmo del reloj decorativo. Se pausan solas cuando su
/// pantalla queda tapada, igual que antes.
mixin TickerDecorativo<T extends StatefulWidget> on State<T> implements TickerProvider {
  Set<Ticker>? _tickersDecorativos;
  ValueListenable<TickerModeData>? _modoTicker;

  /// Cuadros por segundo de esta animación en la web, si se anima.
  int get cuadrosWeb => Rendimiento.cuadrosDecoracion;

  /// En la web la decoración queda quieta: el mismo cuadro que se ve con
  /// «reducir movimiento». Solo se animan las que cumplen una función
  /// (demostración de ejercicios, línea de tiempo de fotos, celebración).
  bool get animarEnWeb => false;

  @override
  Ticker createTicker(TickerCallback onTick) {
    _escucharModoTicker();
    final String etiqueta = 'decorativo ${widget.runtimeType}';
    final int cuadros = cuadrosWeb.clamp(1, Rendimiento.cuadrosDecoracion);
    final Ticker t = !Rendimiento.ligero
        ? Ticker(onTick, debugLabel: etiqueta)
        : animarEnWeb
            ? _TickerLento(onTick, intervaloUs: 1000000 ~/ cuadros, debugLabel: etiqueta)
            : _TickerQuieto(onTick, debugLabel: etiqueta);
    t.muted = !(_modoTicker?.value.enabled ?? true);
    (_tickersDecorativos ??= <Ticker>{}).add(t);
    return t;
  }

  void _escucharModoTicker() {
    final ValueListenable<TickerModeData> nuevo = TickerMode.getValuesNotifier(context);
    if (identical(nuevo, _modoTicker)) return;
    _modoTicker?.removeListener(_aplicarModoTicker);
    nuevo.addListener(_aplicarModoTicker);
    _modoTicker = nuevo;
  }

  void _aplicarModoTicker() {
    final bool activo = _modoTicker?.value.enabled ?? true;
    for (final Ticker t in _tickersDecorativos ?? const <Ticker>{}) {
      t.muted = !activo;
    }
  }

  @override
  void activate() {
    super.activate();
    _escucharModoTicker();
    _aplicarModoTicker();
  }

  @override
  void dispose() {
    _modoTicker?.removeListener(_aplicarModoTicker);
    _modoTicker = null;
    super.dispose();
  }
}

// ===========================================================================
// 60. TEMAS DE COLOR
//
// Cada persona escoge la tonalidad del templo: Tradicional (la noche morada
// de siempre), Oscuro (grafito neutro), Claro (papel y tinta), Sakura, Jade,
// Océano y Carmesí, o Automático (claro u oscuro según el teléfono).
//
// Cómo funciona: los colores de TempleColors son ColorTema, constantes para
// el compilador pero que leen sus canales de la paleta vigente al pintar.
// Así los ~2.700 usos del código cambian de tema sin tocarlos. Al cambiar de
// tema la app se vuelve a montar entera (vuelve al mismo módulo y reabre
// Apariencia), porque Flutter guarda en caché el texto ya dibujado.
//
// Las escenas e ilustraciones (jardín, taller, casa, guerrero, emblemas,
// Tenshi, sellos…) usan ColoresTradicion y no cambian. El paisaje de fondo sí
// se adapta: de día en Claro y con el tono de cada paleta en las demás.
// ===========================================================================

// ---------------------------------------------------------------------------
// 60.1 COLOR VIVO
// ---------------------------------------------------------------------------

/// Color del tema activo. Para el compilador es constante, pero sus canales
/// se leen de la paleta vigente en el momento de pintar.
class ColorTema extends Color {
  const ColorTema(this.indice, [this.alfa]) : super(0xFF000000);

  /// Posición en [PaletaTemplo.colores] (ver TempleColors).
  final int indice;

  /// Opacidad fija (0–255) para variantes translúcidas, o null para la de la paleta.
  final int? alfa;

  Color get _c => TemaTemplo.paleta.colores[indice];

  @override
  double get a => alfa == null ? _c.a : alfa! / 255.0;

  @override
  double get r => _c.r;

  @override
  double get g => _c.g;

  @override
  double get b => _c.b;

  @override
  ui.ColorSpace get colorSpace => _c.colorSpace;
}

/// La paleta original, fija. La usan las ilustraciones y escenas, que se ven
/// igual en todos los temas.
class ColoresTradicion {
  const ColoresTradicion._();

  static const Color negro = Color(0xFF06050A);
  static const Color grafito = Color(0xFF100E18);
  static const Color superficie = Color(0xFF15121F);
  static const Color superficieAlta = Color(0xFF1D1829);
  static const Color borde = Color(0xFF29223A);
  static const Color bordeVivo = Color(0xFF3D3157);
  static const Color moradoProfundo = Color(0xFF2B1B52);
  static const Color violeta = Color(0xFF8B5CF6);
  static const Color violetaClaro = Color(0xFFB79CFF);
  static const Color dorado = Color(0xFFD9A441);
  static const Color blancoLuna = Color(0xFFF4F1FA);
  static const Color texto = Color(0xFFE7E3F2);
  static const Color textoSuave = Color(0xFF9A93B0);
  static const Color textoTenue = Color(0xFF645D7A);
  static const Color exito = Color(0xFF5BD6A0);
  static const Color alertaSuave = Color(0xFFE2A03F);
  static const Color error = Color(0xFFE05C6E);
  static const LinearGradient fondo = LinearGradient(
    begin: Alignment.topCenter,
    end: Alignment.bottomCenter,
    colors: <Color>[Color(0xFF120D22), Color(0xFF09070F), Color(0xFF06050A)],
    stops: <double>[0, 0.55, 1],
  );
}

// ---------------------------------------------------------------------------
// 60.2 PALETAS
// ---------------------------------------------------------------------------

/// Colores del paisaje de fondo (cielo nocturno, Fuji, bambú, casa, agua y
/// torii), para que el fondo acompañe al tema.
class PaisajePaleta {
  const PaisajePaleta({
    required this.cielo,
    required this.luna,
    required this.fuji,
    required this.nieve,
    required this.colinas,
    required this.bambu,
    required this.aguaArriba,
    required this.aguaAbajo,
    required this.tinta,
    required this.frente,
    required this.estrellas,
  });

  /// Cuatro tonos de arriba abajo.
  final List<Color> cielo;
  final Color luna;
  final Color fuji;
  final Color nieve;
  final Color colinas;
  final Color bambu;
  final Color aguaArriba;
  final Color aguaAbajo;

  /// Casa tradicional.
  final Color tinta;

  /// Torii y siluetas del frente.
  final Color frente;

  /// Si se dibujan estrellas (de día no).
  final bool estrellas;
}

class PaletaTemplo {
  PaletaTemplo({
    required this.id,
    required this.nombre,
    required this.descripcion,
    required this.claro,
    required Color negro,
    required Color grafito,
    required Color superficie,
    required Color superficieAlta,
    required Color borde,
    required Color bordeVivo,
    required Color moradoProfundo,
    required Color violeta,
    required Color violetaClaro,
    required Color dorado,
    required Color blancoLuna,
    required Color texto,
    required Color textoSuave,
    required Color textoTenue,
    required Color exito,
    required Color alertaSuave,
    required Color error,
    required List<Color> fondo,
    required this.paisaje,
  }) : colores = <Color>[
          negro, grafito, superficie, superficieAlta, borde, bordeVivo, moradoProfundo, violeta, violetaClaro,
          dorado, blancoLuna, texto, textoSuave, textoTenue, exito, alertaSuave, error,
          fondo[0], fondo[1], fondo[2],
        ];

  final String id;
  final String nombre;
  final String descripcion;

  /// Tema de fondo claro: texto oscuro y barra de estado con iconos oscuros.
  final bool claro;

  /// Por índice, en el orden de TempleColors.
  final List<Color> colores;
  final PaisajePaleta paisaje;

  Color get fondoApp => colores[0];
  Color get tarjeta => colores[2];
  Color get bordeTarjeta => colores[4];
  Color get acento => colores[7];
  Color get acentoClaro => colores[8];
  Color get titulo => colores[10];
  Color get textoSecundario => colores[12];
  List<Color> get degradado => <Color>[colores[17], colores[18], colores[19]];
}

